class BuilderContext(BaseModel): """Context information for AI-powered suggestions.""" industry: str = Field(..., description="Industry category") business_type: str = Field(..., description="Type of business") page_type: str = Field(default="landing_page", description="Type of page being built") goals: List[str] = Field(default=[], description="Business goals") target_audience: str = Field(default="general", description="Target audience") brand_guidelines: Optional[Dict[str, Any]] = Field(default=None, description="Brand guidelines") existing_components: List[Dict[str, Any]] = Field(default=[], description="Current components")
class ComponentSuggestionRequest(BaseModel): """Request for component suggestions.""" context: BuilderContext current_components: List[Dict[str, Any]] = Field(default=[], description="Currently added components") max_suggestions: int = Field(default=5, ge=1, le=10, description="Maximum number of suggestions") preferences: Optional[Dict[str, Any]] = Field(default=None, description="User preferences")
