class TemplateGenerationRequest(BaseModel): """Request for AI-powered template generation.""" description: str = Field(..., min_length=10, description="Natural language description of desired template") business_context: BuilderContext requirements: Optional[Dict[str, Any]] = Field(default=None, description="Specific requirements") style_preferences: Optional[Dict[str, Any]] = Field(default=None, description="Style preferences")
