class WorkflowCreationRequest(BaseModel): """Request for natural language workflow creation.""" user_input: str = Field(..., min_length=5, description="Natural language workflow description") context: Dict[str, Any] = Field(default={}, description="Additional context") existing_workflows: List[Dict[str, Any]] = Field(default=[], description="Existing workflows for reference")
