class PerformancePrediction(BaseModel): """Template performance prediction response.""" conversion_predictions: Dict[str, Any] engagement_predictions: Dict[str, Any] performance_analysis: Dict[str, Any] improvement_recommendations: List[Dict[str, Any]] industry_comparison: Dict[str, Any] confidence_assessment: Dict[str, Any]
