@router.post("/ai/component-suggestions", response_model=ComponentSuggestionsResponse) async def get_component_suggestions( request: ComponentSuggestionRequest, background_tasks: BackgroundTasks, current_user: User = Depends(get_current_user), db: AsyncSession = Depends(get_db) ): """ Story 4.1: Get intelligent component suggestions based on context.
