filters = {"owner_id": current_user.id} if status: filters["status"] = status if source: filters["source"] = source
if search: contacts = await contact_service.search_contacts(current_user.id, search, skip, limit) else: contacts = await contact_service.get_multi(skip, limit, filters)
total = await contact_service.count(filters)
return { "contacts": contacts, "total": total, "page": skip // limit + 1, "size": limit, "pages": (total + limit - 1) // limit }
