"""API endpoints for site publishing and deployment."""

from typing import Dict, Any, Optional, List
from fastapi import APIRouter, Depends, HTTPException, BackgroundTasks, Query
from pydantic import BaseModel, Field
from sqlalchemy.ext.asyncio import AsyncSession

from ..core.database import get_async_session
from ..services.publishing_service import PublishingService
from ..services.domain_manager import DomainManager
from ..services.tasks import (
    publish_site_task, 
    verify_domain_task, 
    check_ssl_status_task,
    optimize_site_performance,
    generate_analytics_report
)

router = APIRouter(prefix="/api/v1", tags=["publishing"])

# Pydantic models for request/response
class PublishSiteRequest(BaseModel):
    """Request model for publishing a site."""
    custom_domain: Optional[str] = Field(None, description="Custom domain to use")
    seo_settings: Optional[Dict[str, Any]] = Field(default_factory=dict, description="SEO configuration")
    performance_optimization: bool = Field(True, description="Enable performance optimization")

class PublishSiteResponse(BaseModel):
    """Response model for site publishing."""
    success: bool
    task_id: Optional[str] = None
    published_site_id: Optional[str] = None
    preview_url: Optional[str] = None
    status: str
    message: str

class DomainVerificationRequest(BaseModel):
    """Request model for domain verification."""
    domain: str = Field(..., description="Domain to verify")

class DomainSetupResponse(BaseModel):
    """Response model for domain setup."""
    success: bool
    status: str
    verification_token: Optional[str] = None
    dns_instructions: Optional[Dict[str, Any]] = None
    message: str

class PublishingStatusResponse(BaseModel):
    """Response model for publishing status."""
    success: bool
    status: str
    site_status: str
    published_site: Optional[Dict[str, Any]] = None
    ssl_status_info: Optional[Dict[str, Any]] = None

class DeploymentHistoryResponse(BaseModel):
    """Response model for deployment history."""
    success: bool
    deployments: List[Dict[str, Any]]
    total_deployments: int


@router.post("/sites/{site_id}/publish", response_model=PublishSiteResponse)
async def publish_site(
    site_id: str,
    request: PublishSiteRequest,
    background_tasks: BackgroundTasks,
    session: AsyncSession = Depends(get_async_session)
):
    """
    Publish a site with complete deployment pipeline.

    This endpoint triggers a background task that:
    1. Generates static site from components
    2. Optimizes assets (CSS, JS, images)
    3. Uploads to CDN
    4. Sets up custom domain (if provided)
    5. Configures SSL certificate
    6. Validates deployment
    """
    try:
        # Validate site exists and user has access
        # TODO: Add proper authentication and authorization

        # Start background publishing task
        task = publish_site_task.delay(site_id, request.custom_domain)

        # Optionally trigger performance optimization
        if request.performance_optimization:
            background_tasks.add_task(
                lambda: optimize_site_performance.delay(site_id)
            )

        return PublishSiteResponse(
            success=True,
            task_id=task.id,
            status="started",
            message="Site publishing started. Check status using the task ID."
        )

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/sites/{site_id}/publish/status", response_model=PublishingStatusResponse)
async def get_publishing_status(
    site_id: str,
    session: AsyncSession = Depends(get_async_session)
):
    """Get current publishing status for a site."""
    try:
        publishing_service = PublishingService()
        result = await publishing_service.get_publishing_status(site_id)

        if not result["success"]:
            raise HTTPException(status_code=404, detail=result["error"])

        return PublishingStatusResponse(**result)

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/tasks/{task_id}/status")
async def get_task_status(task_id: str):
    """Get status of a background task."""
    try:
        from ..services.tasks import celery_app

        task = celery_app.AsyncResult(task_id)

        response = {
            "task_id": task_id,
            "status": task.status,
            "result": task.result if task.ready() else None
        }

        if task.status == "PROGRESS":
            response["progress"] = task.info.get("progress", 0)
            response["current_status"] = task.info.get("status", "Processing...")

        return response

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/sites/{site_id}/unpublish")
async def unpublish_site(
    site_id: str,
    session: AsyncSession = Depends(get_async_session)
):
    """Unpublish a site and clean up resources."""
    try:
        publishing_service = PublishingService()
        result = await publishing_service.unpublish_site(site_id)

        if not result["success"]:
            raise HTTPException(status_code=400, detail=result["error"])

        return result

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/domains/verify", response_model=DomainSetupResponse)
async def verify_domain(
    request: DomainVerificationRequest,
    site_id: str = Query(..., description="Site ID for domain verification")
):
    """Verify domain ownership and setup DNS."""
    try:
        # Start background domain verification task
        task = verify_domain_task.delay(request.domain, site_id)

        return DomainSetupResponse(
            success=True,
            status="verification_started",
            verification_token=f"aiwebbuilder-verify={site_id}",
            dns_instructions={
                "record_type": "TXT",
                "name": request.domain,
                "value": f"aiwebbuilder-verify={site_id}",
                "ttl": 300
            },
            message="Add the TXT record to your domain DNS and verification will complete automatically."
        )

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/domains/{domain}/setup")
async def setup_custom_domain(
    domain: str,
    site_id: str = Query(..., description="Site ID")
):
    """Setup custom domain configuration."""
    try:
        domain_manager = DomainManager()

        # Setup DNS records
        dns_result = await domain_manager.setup_dns_records(
            domain, f"{site_id}.aiwebbuilder.com"
        )

        # Request SSL certificate
        ssl_result = await domain_manager.request_ssl_certificate(domain)

        return {
            "success": True,
            "domain": domain,
            "dns_setup": dns_result,
            "ssl_setup": ssl_result
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/sites/{site_id}/deployments", response_model=DeploymentHistoryResponse)
async def get_deployment_history(
    site_id: str,
    limit: int = Query(10, ge=1, le=100, description="Number of deployments to return"),
    session: AsyncSession = Depends(get_async_session)
):
    """Get deployment history for a site."""
    try:
        publishing_service = PublishingService()
        result = await publishing_service.get_deployment_history(site_id)

        if not result["success"]:
            raise HTTPException(status_code=404, detail=result["error"])

        # Limit results
        result["deployments"] = result["deployments"][:limit]

        return DeploymentHistoryResponse(**result)

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/sites/{site_id}/rollback")
async def rollback_deployment(
    site_id: str,
    target_version: str = Query(..., description="Version to rollback to"),
    session: AsyncSession = Depends(get_async_session)
):
    """Rollback site to a previous deployment version."""
    try:
        publishing_service = PublishingService()
        result = await publishing_service.rollback_deployment(site_id, target_version)

        if not result["success"]:
            raise HTTPException(status_code=400, detail=result["error"])

        return result

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/sites/{site_id}/ssl/status")
async def check_ssl_status(
    site_id: str,
    background_tasks: BackgroundTasks,
    session: AsyncSession = Depends(get_async_session)
):
    """Check SSL certificate status for a site."""
    try:
        # Get published site ID
        publishing_service = PublishingService()
        status_result = await publishing_service.get_publishing_status(site_id)

        if not status_result["success"] or status_result["status"] != "published":
            raise HTTPException(status_code=404, detail="Site not published")

        published_site_id = status_result["published_site"]["id"]

        # Start background SSL check task
        task = check_ssl_status_task.delay(published_site_id)

        return {
            "success": True,
            "task_id": task.id,
            "message": "SSL status check started"
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/sites/{site_id}/optimize")
async def optimize_site(
    site_id: str,
    background_tasks: BackgroundTasks
):
    """Trigger site performance optimization."""
    try:
        # Start background optimization task
        task = optimize_site_performance.delay(site_id)

        return {
            "success": True,
            "task_id": task.id,
            "message": "Site optimization started"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/sites/{site_id}/analytics")
async def get_site_analytics(
    site_id: str,
    period: str = Query("30d", regex="^(7d|30d|90d)$", description="Analytics period"),
    background_tasks: BackgroundTasks
):
    """Get site analytics report."""
    try:
        # Start background analytics generation task
        task = generate_analytics_report.delay(site_id, period)

        return {
            "success": True,
            "task_id": task.id,
            "message": "Analytics report generation started"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/sites/{site_id}/performance")
async def get_site_performance(
    site_id: str,
    session: AsyncSession = Depends(get_async_session)
):
    """Get site performance metrics."""
    try:
        publishing_service = PublishingService()
        status_result = await publishing_service.get_publishing_status(site_id)

        if not status_result["success"] or status_result["status"] != "published":
            raise HTTPException(status_code=404, detail="Site not published")

        published_site = status_result["published_site"]
        domain = published_site["custom_domain"] or published_site["domain"]

        domain_manager = DomainManager()
        validation_result = await domain_manager.validate_domain_configuration(domain)

        return {
            "success": True,
            "site_id": site_id,
            "domain": domain,
            "performance_metrics": validation_result
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/publishing/stats")
async def get_publishing_stats(
    session: AsyncSession = Depends(get_async_session)
):
    """Get overall publishing statistics."""
    try:
        from ..models.sites import PublishedSite, DeploymentHistory, BuildStatus
        from sqlalchemy import select, func

        # Get publishing statistics
        total_sites = await session.scalar(
            select(func.count(PublishedSite.id))
        )

        successful_builds = await session.scalar(
            select(func.count(PublishedSite.id)).where(
                PublishedSite.build_status == BuildStatus.SUCCESS
            )
        )

        failed_builds = await session.scalar(
            select(func.count(PublishedSite.id)).where(
                PublishedSite.build_status == BuildStatus.FAILED
            )
        )

        total_deployments = await session.scalar(
            select(func.count(DeploymentHistory.id))
        )

        avg_build_time = await session.scalar(
            select(func.avg(DeploymentHistory.build_duration)).where(
                DeploymentHistory.build_status == BuildStatus.SUCCESS
            )
        )

        return {
            "success": True,
            "stats": {
                "total_published_sites": total_sites or 0,
                "successful_builds": successful_builds or 0,
                "failed_builds": failed_builds or 0,
                "success_rate": (successful_builds / max(total_sites, 1)) * 100 if total_sites else 0,
                "total_deployments": total_deployments or 0,
                "average_build_time": round(avg_build_time or 0, 2)
            }
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

""" SLA Optimization API endpoints for Story 3.5 Threshold optimization, A/B testing, and management endpoints. """
from typing import List, Optional, Dict, Any from fastapi import APIRouter, Depends, HTTPException, BackgroundTasks from sqlalchemy.ext.asyncio import AsyncSession from datetime import datetime, timedelta import logging
from app.core.database import get_db from app.services.sla_performance_analysis_service import SLAPerformanceAnalysisService from app.services.sla_threshold_optimizer import ( SLAThresholdOptimizer, OptimizationObjective, ThresholdOptimizationRecommendation ) from app.services.sla_ab_testing_service import ( SLAABTestingService, ExperimentConfig, ExperimentResult, StoppingReason ) from app.services.threshold_management_service import ( ThresholdManagementService, ThresholdChangeRequest, ThresholdChangeRecord, ChangeType, RollbackTrigger )
logger = logging.getLogger(__name__) router = APIRouter()
# Performance Analysis Endpoints
@router.get("/analysis/{service_type}") async def get_performance_analysis( service_type: str, analysis_period_days: int = 30, confidence_level: float = 0.95, include_seasonal: bool = True, db: AsyncSession = Depends(get_db) ): """Get comprehensive performance analysis for service type.""" try: analysis_service = SLAPerformanceAnalysisService(db)
analysis = await analysis_service.analyze_service_performance( service_type=service_type, analysis_period_days=analysis_period_days, confidence_level=confidence_level, include_seasonal_patterns=include_seasonal )
return { "service_type": analysis.service_type, "analysis_period_days": analysis.analysis_period_days, "sample_size": analysis.sample_size, "current_thresholds": analysis.current_thresholds, "statistics": { "mean_performance": analysis.performance_statistics.mean_performance, "median_performance": analysis.performance_statistics.median_performance, "percentile_95": analysis.performance_statistics.percentile_95, "percentile_99": analysis.performance_statistics.percentile_99, "standard_deviation": analysis.performance_statistics.standard_deviation, "coefficient_of_variation": analysis.performance_statistics.coefficient_of_variation, "distribution_type": analysis.performance_statistics.distribution_type }, "patterns": { "trend_direction": analysis.patterns.trend_direction.value, "trend_confidence": analysis.patterns.trend_confidence, "seasonal_factors": [ { "period": sf.period, "pattern_strength": sf.pattern_strength, "peak_periods": sf.peak_periods, "low_periods": sf.low_periods } for sf in analysis.patterns.seasonal_factors ], "load_correlations": [ { "metric_name": lc.metric_name, "correlation_coefficient": lc.correlation_coefficient, "significance_level": lc.significance_level } for lc in analysis.patterns.load_correlations ] }, "confidence_level": analysis.confidence_level, "data_quality_score": analysis.data_quality_score, "analysis_timestamp": analysis.analysis_timestamp.isoformat() }
except Exception as e: logger.error(f"Failed to get performance analysis: {e}") raise HTTPException(status_code=500, detail="Failed to analyze performance")
@router.get("/analysis/report") async def get_performance_report( service_types: Optional[List[str]] = None, analysis_period_days: int = 30, db: AsyncSession = Depends(get_db) ): """Generate comprehensive performance report for multiple service types.""" try: analysis_service = SLAPerformanceAnalysisService(db)
# If no service types specified, get all monitored services if not service_types: service_types = await analysis_service.get_monitored_service_types()
report = {} for service_type in service_types: try: analysis = await analysis_service.analyze_service_performance( service_type=service_type, analysis_period_days=analysis_period_days ) report[service_type] = analysis except Exception as e: logger.error(f"Failed to analyze {service_type}: {e}") continue
return { "report_generated_at": datetime.utcnow().isoformat(), "analysis_period_days": analysis_period_days, "services_analyzed": len(report), "analyses": { service_type: { "sample_size": analysis.sample_size, "data_quality_score": analysis.data_quality_score, "violation_rate": analysis.current_thresholds.get('violation_rate', 0.0), "trend_direction": analysis.patterns.trend_direction.value, "optimization_potential": ( 1.0 - analysis.data_quality_score if analysis.patterns.trend_direction.value == "degrading" else analysis.data_quality_score ) } for service_type, analysis in report.items() } }
except Exception as e: logger.error(f"Failed to generate performance report: {e}") raise HTTPException(status_code=500, detail="Failed to generate report")
# Threshold Optimization Endpoints
@router.post("/optimize/{service_type}") async def optimize_threshold( service_type: str, objective: OptimizationObjective = OptimizationObjective.BALANCE_BOTH, analysis_period_days: int = 30, db: AsyncSession = Depends(get_db) ): """Generate threshold optimization recommendations for service type.""" try: optimizer = SLAThresholdOptimizer(db)
optimization_result = await optimizer.optimize_threshold( service_type=service_type, objective=objective, analysis_period_days=analysis_period_days )
if not optimization_result.optimization_successful: raise HTTPException( status_code=400, detail="Optimization failed - insufficient data or poor model performance" )
return { "service_type": optimization_result.service_type, "optimization_successful": optimization_result.optimization_successful, "optimization_score": optimization_result.optimization_score, "processing_time_seconds": optimization_result.processing_time_seconds, "model_performance_metrics": optimization_result.model_performance_metrics, "recommendations": [ { "service_type": rec.service_type, "current_threshold": rec.current_threshold, "recommended_threshold": rec.recommended_threshold, "optimization_rationale": { "statistical_basis": rec.optimization_rationale.statistical_basis, "reliability_impact": rec.optimization_rationale.reliability_impact, "achievability_improvement": rec.optimization_rationale.achievability_improvement, "business_justification": rec.optimization_rationale.business_justification }, "predicted_outcomes": { "expected_violation_rate": rec.predicted_outcomes.expected_violation_rate, "reliability_score_change": rec.predicted_outcomes.reliability_score_change, "team_stress_reduction": rec.predicted_outcomes.team_stress_reduction, "cost_impact": rec.predicted_outcomes.cost_impact, "customer_satisfaction_change": rec.predicted_outcomes.customer_satisfaction_change }, "confidence_score": rec.confidence_score, "implementation_risk": rec.implementation_risk.value, "rollback_criteria": rec.rollback_criteria, "optimization_timestamp": rec.optimization_timestamp.isoformat(), "model_version": rec.model_version } for rec in optimization_result.recommendations ] }
except Exception as e: logger.error(f"Failed to optimize threshold: {e}") raise HTTPException(status_code=500, detail="Failed to optimize threshold")
@router.get("/recommendations") async def get_all_recommendations( db: AsyncSession = Depends(get_db) ): """Get optimization recommendations for all services.""" try: optimizer = SLAThresholdOptimizer(db) analysis_service = SLAPerformanceAnalysisService(db)
# Get all monitored service types service_types = await analysis_service.get_monitored_service_types()
recommendations = [] for service_type in service_types: try: optimization_result = await optimizer.optimize_threshold(service_type) if optimization_result.optimization_successful: recommendations.extend(optimization_result.recommendations) except Exception as e: logger.error(f"Failed to get recommendations for {service_type}: {e}") continue
return recommendations
except Exception as e: logger.error(f"Failed to get all recommendations: {e}") raise HTTPException(status_code=500, detail="Failed to get recommendations")
