# Threshold Management Endpoints
@router.post("/thresholds/change") async def request_threshold_change( service_type: str, current_threshold: float, proposed_threshold: float, change_type: str = "optimization", justification: str = "", requested_by: str = "system", rollback_criteria: Optional[List[str]] = None, monitoring_duration_hours: int = 48, auto_rollback_enabled: bool = True, db: AsyncSession = Depends(get_db) ): """Request a threshold change with impact assessment.""" try: management_service = ThresholdManagementService(db)
# Map string to enum change_type_enum = ChangeType.OPTIMIZATION if change_type == "manual": change_type_enum = ChangeType.MANUAL elif change_type == "ab_test": change_type_enum = ChangeType.A_B_TEST elif change_type == "emergency": change_type_enum = ChangeType.EMERGENCY
request = ThresholdChangeRequest( service_type=service_type, current_threshold=current_threshold, proposed_threshold=proposed_threshold, change_type=change_type_enum, justification=justification, requested_by=requested_by, rollback_criteria=rollback_criteria or [], monitoring_duration_hours=monitoring_duration_hours, auto_rollback_enabled=auto_rollback_enabled )
change_id, impact_assessment = await management_service.request_threshold_change(request)
return { "change_id": change_id, "status": "pending", "impact_assessment": { "expected_violation_rate_change": impact_assessment.expected_violation_rate_change, "performance_impact_estimate": impact_assessment.performance_impact_estimate, "affected_services": impact_assessment.affected_services, "risk_level": impact_assessment.risk_level, "confidence_score": impact_assessment.confidence_score, "business_impact_score": impact_assessment.business_impact_score, "rollback_feasibility": impact_assessment.rollback_feasibility }, "message": "Threshold change requested successfully. Review impact assessment before applying." }
except Exception as e: logger.error(f"Failed to request threshold change: {e}") raise HTTPException(status_code=500, detail="Failed to request threshold change")
@router.post("/thresholds/change/{change_id}/apply") async def apply_threshold_change( change_id: str, background_tasks: BackgroundTasks, db: AsyncSession = Depends(get_db) ): """Apply approved threshold change.""" try: management_service = ThresholdManagementService(db)
success = await management_service.apply_threshold_change(change_id)
if not success: raise HTTPException(status_code=400, detail="Failed to apply threshold change")
return { "change_id": change_id, "status": "applied", "message": "Threshold change applied successfully. Monitoring has started." }
except Exception as e: logger.error(f"Failed to apply threshold change: {e}") raise HTTPException(status_code=500, detail="Failed to apply threshold change")
@router.post("/thresholds/change/{change_id}/rollback") async def rollback_threshold_change( change_id: str, trigger: str = "manual", trigger_metrics: Optional[Dict[str, float]] = None, db: AsyncSession = Depends(get_db) ): """Rollback a threshold change to previous value.""" try: management_service = ThresholdManagementService(db)
# Map string to enum trigger_enum = RollbackTrigger.MANUAL if trigger == "automatic": trigger_enum = RollbackTrigger.AUTOMATIC elif trigger == "violation_rate": trigger_enum = RollbackTrigger.VIOLATION_RATE elif trigger == "performance_degradation": trigger_enum = RollbackTrigger.PERFORMANCE_DEGRADATION
success = await management_service.rollback_threshold_change( change_id, trigger_enum, trigger_metrics )
if not success: raise HTTPException(status_code=400, detail="Failed to rollback threshold change")
return { "change_id": change_id, "status": "rolled_back", "trigger": trigger, "message": "Threshold change rolled back successfully." }
except Exception as e: logger.error(f"Failed to rollback threshold change: {e}") raise HTTPException(status_code=500, detail="Failed to rollback threshold change")
@router.get("/thresholds/history") async def get_threshold_change_history( service_type: Optional[str] = None, hours: int = 168, db: AsyncSession = Depends(get_db) ): """Get threshold change history for analysis.""" try: management_service = ThresholdManagementService(db)
history = await management_service.get_change_history(service_type, hours)
return { "total_changes": len(history), "period_hours": hours, "service_type_filter": service_type, "changes": [ { "change_id": change.change_id, "service_type": change.service_type, "previous_threshold": change.previous_threshold, "new_threshold": change.new_threshold, "change_type": change.change_type.value, "status": change.status.value, "requested_by": change.requested_by, "requested_at": change.requested_at.isoformat(), "applied_at": change.applied_at.isoformat() if change.applied_at else None, "rollback_at": change.rollback_at.isoformat() if change.rollback_at else None, "impact_assessment": { "risk_level": change.impact_assessment.risk_level, "confidence_score": change.impact_assessment.confidence_score, "business_impact_score": change.impact_assessment.business_impact_score }, "actual_impact": change.actual_impact, "justification": change.justification } for change in history ] }
except Exception as e: logger.error(f"Failed to get threshold change history: {e}") raise HTTPException(status_code=500, detail="Failed to get change history")
