""" Template management endpoints. """
from typing import Any, List, Optional from fastapi import APIRouter, Depends, HTTPException, status, Query, BackgroundTasks from sqlalchemy.ext.asyncio import AsyncSession
from app.api.deps import get_db, get_current_active_user, require_admin from app.models.user import User from app.models.template import TemplateCategory, TemplateStatus from app.schemas.template import ( Template, TemplateCreate, TemplateUpdate, TemplateList, TemplateComponent, TemplateComponentCreate, TemplateComponentUpdate ) from app.schemas.ai_template import ( AITemplateGenerateRequest, AITemplateGenerateResponse, AITemplateOptimizeRequest, AITemplateOptimizeResponse, AITemplateVariantsRequest, AITemplateVariantsResponse, AITemplatePersonalizeRequest, AITemplatePersonalizeResponse, AITemplateAnalysisRequest, AITemplateAnalysisResponse ) from app.services.template_service import TemplateService, TemplateComponentService from app.services.ai_template_service import AITemplateService
router = APIRouter()
@router.get("/", response_model=TemplateList) async def get_templates( skip: int = Query(0, ge=0), limit: int = Query(100, ge=1, le=100), category: Optional[TemplateCategory] = None, featured: Optional[bool] = None, premium: Optional[bool] = None, search: Optional[str] = None, db: AsyncSession = Depends(get_db) ) -> Any: """Get templates with filtering and pagination.""" template_service = TemplateService(db)
# Handle different filtering scenarios if search: templates = await template_service.search_templates(search, category, skip, limit) elif featured: templates = await template_service.get_featured(limit) elif premium: templates = await template_service.get_premium(skip, limit) elif category: templates = await template_service.get_by_category(category, skip, limit) else: filters = {"status": TemplateStatus.PUBLISHED} templates = await template_service.get_multi(skip, limit, filters)
# Get total count for pagination filters = {"status": TemplateStatus.PUBLISHED} if category: filters["category"] = category
total = await template_service.count(filters)
return { "templates": templates, "total": total, "page": skip // limit + 1, "size": limit, "pages": (total + limit - 1) // limit }
@router.get("/popular", response_model=List[Template]) async def get_popular_templates( limit: int = Query(10, ge=1, le=50), db: AsyncSession = Depends(get_db) ) -> Any: """Get most popular templates.""" template_service = TemplateService(db) return await template_service.get_popular_templates(limit)
