# Verify template exists and user has access template_service = TemplateService(db) template = await template_service.get_by_id(request.template_id) if not template: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Template not found" )
# Prepare template data for analysis template_data = { "name": template.name, "description": template.description, "category": template.category, "components": template.components, "styles": template.styles, "config": template.config }
# Perform analysis based on type ai_service = AIService()
if request.analysis_type == "seo": analysis_prompt = f""" Analyze this website template for SEO optimization:
Template: {template_data['name']} Description: {template_data['description']} Components: {len(template_data['components'])} elements
Provide JSON response with: - score: SEO score (0-100) - findings: list of SEO issues and strengths - recommendations: specific SEO improvements - priority_level: overall priority (high/medium/low) """
result = await ai_service.generate_json_response(analysis_prompt)
elif request.analysis_type == "conversion": analysis_prompt = f""" Analyze this website template for conversion rate optimization:
Template: {template_data['name']} Category: {template_data['category']} Components: {len(template_data['components'])} elements
Provide JSON response with: - score: conversion potential score (0-100) - findings: conversion strengths and weaknesses - recommendations: CRO improvements - priority_level: overall priority (high/medium/low) """
result = await ai_service.generate_json_response(analysis_prompt)
elif request.analysis_type == "accessibility": analysis_prompt = f""" Analyze this website template for accessibility compliance:
Template: {template_data['name']} Components: {len(template_data['components'])} elements
Provide JSON response with: - score: accessibility score (0-100) - findings: accessibility issues and strengths - recommendations: accessibility improvements - priority_level: overall priority (high/medium/low) """
result = await ai_service.generate_json_response(analysis_prompt)
else: analysis_prompt = f""" Analyze this website template for overall performance:
Template: {template_data['name']} Description: {template_data['description']} Category: {template_data['category']}
Provide JSON response with: - score: overall performance score (0-100) - findings: key performance insights - recommendations: improvement suggestions - priority_level: overall priority (high/medium/low) """
result = await ai_service.generate_json_response(analysis_prompt)
return AITemplateAnalysisResponse( success=True, template_id=request.template_id, analysis_type=request.analysis_type, score=result.get("score", 0.0), findings=result.get("findings", []), recommendations=result.get("recommendations", []), priority_level=result.get("priority_level", "medium"), error=None )
except Exception as e: logger = logging.getLogger(__name__) logger.error(f"Error analyzing template: {str(e)}") raise HTTPException( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=f"Template analysis failed: {str(e)}" )

""" REST API endpoints for workflow debugging functionality. Story 3.1: Visual Workflow Debugging UI Backend Support """
import json from typing import Any, List, Optional, Dict from fastapi import APIRouter, Depends, HTTPException, status, Query, Response from fastapi.responses import StreamingResponse from sqlalchemy.ext.asyncio import AsyncSession from datetime import datetime, timedelta import io import csv
from app.api.deps import get_db, get_current_active_user from app.models.user import User from app.models.workflow import WorkflowStatus from app.schemas.workflow_debug import ( DebugSessionCreate, DebugSessionResponse, ExecutionTimelineResponse, NodeExecutionLogsResponse, WorkflowPerformanceMetricsResponse, ExecutionExportResponse, DebugSessionConfig ) from app.services.workflow_debug_service import WorkflowDebugService, WorkflowExecutionDebugService from app.services.workflow_service import WorkflowService
router = APIRouter()
@router.post("/{workflow_id}/debug/start", response_model=DebugSessionResponse) async def start_debug_session( workflow_id: int, config: DebugSessionConfig, db: AsyncSession = Depends(get_db), current_user: User = Depends(get_current_active_user) ) -> Any: """Start a new debugging session for a workflow."""
# Verify workflow access workflow_service = WorkflowService(db) workflow = await workflow_service.get_by_id(workflow_id)
if not workflow: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Workflow not found" )
if workflow.owner_id != current_user.id: raise HTTPException( status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to debug this workflow" )
debug_service = WorkflowDebugService(db) session = await debug_service.start_debug_session( workflow_id=workflow_id, user_id=current_user.id, session_name=config.session_name, debug_config={ 'debug_level': config.debug_level, 'capture_logs': config.capture_logs, 'capture_metrics': config.capture_metrics, 'capture_data_flow': config.capture_data_flow } )
return DebugSessionResponse( session_id=session.id, workflow_id=workflow_id, session_name=session.session_name, debug_level=session.debug_level, capture_logs=session.capture_logs, capture_metrics=session.capture_metrics, capture_data_flow=session.capture_data_flow, is_active=session.is_active, started_at=session.started_at, executions_monitored=session.executions_monitored, errors_detected=session.errors_detected )
@router.post("/{workflow_id}/debug/stop") async def stop_debug_session( workflow_id: int, db: AsyncSession = Depends(get_db), current_user: User = Depends(get_current_active_user) ) -> Any: """Stop the active debugging session for a workflow."""
# Verify workflow access workflow_service = WorkflowService(db) workflow = await workflow_service.get_by_id(workflow_id)
if not workflow: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Workflow not found" )
if workflow.owner_id != current_user.id: raise HTTPException( status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to debug this workflow" )
debug_service = WorkflowDebugService(db) success = await debug_service.end_debug_session(workflow_id, current_user.id)
if not success: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="No active debug session found" )
return {"message": "Debug session stopped successfully"}
