return WorkflowPerformanceMetricsResponse(**metrics)
@router.get("/{workflow_id}/export/logs") async def export_execution_logs( workflow_id: int, format_type: str = Query("json", regex="^(json|csv)$"), execution_ids: Optional[str] = Query(None, description="Comma-separated execution IDs"), timeframe_hours: int = Query(24, ge=1, le=168), db: AsyncSession = Depends(get_db), current_user: User = Depends(get_current_active_user) ) -> Any: """Export execution logs and performance data."""
# Verify workflow access workflow_service = WorkflowService(db) workflow = await workflow_service.get_by_id(workflow_id)
if not workflow: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Workflow not found" )
if workflow.owner_id != current_user.id: raise HTTPException( status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to access this workflow" )
# Parse execution IDs if provided execution_id_list = None if execution_ids: try: execution_id_list = [int(x.strip()) for x in execution_ids.split(',')] except ValueError: raise HTTPException( status_code=status.HTTP_400_BAD_REQUEST, detail="Invalid execution IDs format" )
debug_service = WorkflowDebugService(db) export_data = await debug_service.export_execution_logs( workflow_id, format_type, execution_id_list )
# Generate filename timestamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S") filename = f"workflow_{workflow_id}_logs_{timestamp}.{format_type}"
if format_type == "json": content = json.dumps(export_data, indent=2) media_type = "application/json" else: # CSV format content = _convert_to_csv(export_data) media_type = "text/csv"
return StreamingResponse( io.StringIO(content), media_type=media_type, headers={"Content-Disposition": f"attachment; filename={filename}"} )
@router.post("/{workflow_id}/executions/{execution_id}/retry") async def retry_failed_execution( workflow_id: int, execution_id: int, db: AsyncSession = Depends(get_db), current_user: User = Depends(get_current_active_user) ) -> Any: """Retry a failed workflow execution with debugging enabled."""
# Verify workflow access workflow_service = WorkflowService(db) workflow = await workflow_service.get_by_id(workflow_id)
if not workflow: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Workflow not found" )
if workflow.owner_id != current_user.id: raise HTTPException( status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to execute this workflow" )
# Get original execution debug_service = WorkflowExecutionDebugService(db) original_execution = await debug_service.get_execution_with_steps(execution_id)
if not original_execution: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Original execution not found" )
# Create new execution with debug enabled new_execution = await debug_service.create_execution_with_debug( workflow_id, original_execution.trigger_data, debug_enabled=True )
# TODO: Trigger actual workflow execution here # For now, return the new execution details
return { "message": "Execution retry initiated with debugging enabled", "original_execution_id": execution_id, "new_execution_id": new_execution.id, "retry_timestamp": new_execution.started_at.isoformat() }
def _convert_to_csv(export_data: Dict[str, Any]) -> str: """Convert export data to CSV format."""
output = io.StringIO() writer = csv.writer(output)
# Write header writer.writerow([ 'Execution ID', 'Status', 'Started At', 'Finished At', 'Duration (ms)', 'Node ID', 'Node Name', 'Node Type', 'Node Status', 'Node Duration (ms)', 'Error Message', 'Memory Usage (MB)', 'CPU Usage (%)' ])
# Write data rows for execution in export_data['executions']: base_row = [ execution['execution_id'], execution['status'], execution['started_at'], execution['finished_at'], execution['execution_time'] ]
if execution['steps']: for step in execution['steps']: row = base_row + [ step['node_id'], step['node_name'], step['node_type'], step['status'], step['execution_time_ms'], step['error_message'] or '', step['performance_metrics']['memory_usage_mb'] or '', step['performance_metrics']['cpu_usage_percent'] or '' ] writer.writerow(row) else: # Write execution without steps row = base_row + ['', '', '', '', '', '', '', ''] writer.writerow(row)
return output.getvalue()
@router.get("/{workflow_id}/debug/health") async def get_debug_health_status( workflow_id: int, db: AsyncSession = Depends(get_db), current_user: User = Depends(get_current_active_user) ) -> Any: """Get debugging health status for a workflow."""
# Verify workflow access workflow_service = WorkflowService(db) workflow = await workflow_service.get_by_id(workflow_id)
if not workflow: raise HTTPException( status_code=status.HTTP_404_NOT_FOUND, detail="Workflow not found" )
if workflow.owner_id != current_user.id: raise HTTPException( status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to access this workflow" )
# Check WebSocket connections from app.api.v1.endpoints.workflow_websocket import connection_manager active_connections = len(connection_manager.active_connections.get(workflow_id, set()))
# Get recent execution statistics debug_service = WorkflowDebugService(db) metrics = await debug_service.get_workflow_performance_metrics(workflow_id, 1) # Last hour
return { "workflow_id": workflow_id, "workflow_name": workflow.name, "debugging_enabled": True, "active_websocket_connections": active_connections, "recent_executions": metrics['overall_metrics']['total_executions'], "avg_execution_time_ms": metrics['overall_metrics']['avg_execution_time_ms'], "health_status": "healthy", "last_checked": datetime.utcnow().isoformat() }

