""" Main FastAPI application for AI Marketing Web Builder Platform. """
import logging from contextlib import asynccontextmanager from fastapi import FastAPI, Request, status from fastapi.middleware.cors import CORSMiddleware from fastapi.middleware.trustedhost import TrustedHostMiddleware from fastapi.responses import JSONResponse from fastapi.exceptions import RequestValidationError from starlette.exceptions import HTTPException as StarletteHTTPException
from app.core.config import settings from app.db.session import init_db, close_db from app.api.v1.api import api_router
# Configure logging logging.basicConfig( level=logging.INFO if settings.DEBUG else logging.WARNING, format="%(asctime)s - %(name)s - %(levelname)s - %(message)s" ) logger = logging.getLogger(__name__)
@asynccontextmanager async def lifespan(app: FastAPI): """Application lifespan manager.""" # Startup logger.info("Starting up AI Marketing Web Builder API...")
try: # Initialize database await init_db() logger.info("Database initialized successfully")
yield
finally: # Shutdown logger.info("Shutting down AI Marketing Web Builder API...") await close_db() logger.info("Database connections closed")
# Create FastAPI application app = FastAPI( title=settings.APP_NAME, version=settings.VERSION, description=settings.DESCRIPTION, openapi_url="/api/v1/openapi.json" if settings.DEBUG else None, docs_url="/docs" if settings.DEBUG else None, redoc_url="/redoc" if settings.DEBUG else None, lifespan=lifespan )
# Add security middleware if not settings.DEBUG: app.add_middleware( TrustedHostMiddleware, allowed_hosts=["localhost", "127.0.0.1", "*.yourdomain.com"] )
# Add CORS middleware app.add_middleware( CORSMiddleware, allow_origins=settings.ALLOWED_ORIGINS, allow_credentials=True, allow_methods=["GET", "POST", "PUT", "DELETE", "OPTIONS"], allow_headers=["*"], )
# Exception handlers @app.exception_handler(StarletteHTTPException) async def http_exception_handler(request: Request, exc: StarletteHTTPException): """Handle HTTP exceptions with consistent JSON response.""" return JSONResponse( status_code=exc.status_code, content={ "error": True, "message": exc.detail, "status_code": exc.status_code } )
@app.exception_handler(RequestValidationError) async def validation_exception_handler(request: Request, exc: RequestValidationError): """Handle request validation errors.""" return JSONResponse( status_code=status.HTTP_422_UNPROCESSABLE_ENTITY, content={ "error": True, "message": "Validation error", "details": exc.errors(), "status_code": status.HTTP_422_UNPROCESSABLE_ENTITY } )
@app.exception_handler(Exception) async def general_exception_handler(request: Request, exc: Exception): """Handle general exceptions.""" logger.exception("Unhandled exception occurred")
if settings.DEBUG: import traceback return JSONResponse( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, content={ "error": True, "message": str(exc), "traceback": traceback.format_exc(), "status_code": status.HTTP_500_INTERNAL_SERVER_ERROR } )
return JSONResponse( status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, content={ "error": True, "message": "Internal server error", "status_code": status.HTTP_500_INTERNAL_SERVER_ERROR } )
# Health check endpoint @app.get("/health", tags=["Health"]) async def health_check(): """Health check endpoint.""" return { "status": "healthy", "version": settings.VERSION, "environment": settings.ENVIRONMENT }
# Root endpoint @app.get("/", tags=["Root"]) async def root(): """Root endpoint with API information.""" return { "message": f"Welcome to {settings.APP_NAME} API", "version": settings.VERSION, "docs_url": "/docs" if settings.DEBUG else None, "health_url": "/health" }
# Include API routers app.include_router(api_router, prefix="/api/v1")
# Request logging middleware @app.middleware("http") async def log_requests(request: Request, call_next): """Log all requests in development mode.""" if settings.DEBUG: logger.info(f"{request.method} {request.url}")
response = await call_next(request)
if settings.DEBUG: logger.info(f"Response: {response.status_code}")
return response
if __name__ == "__main__": import uvicorn
uvicorn.run( "app.main:app", host="0.0.0.0", port=8000, reload=settings.DEBUG, log_level="info" if settings.DEBUG else "warning" )

"""
Minimal HTTP server for AI Marketing Web Builder Platform
This runs without external dependencies while we get FastAPI working
"""

import http.server
import socketserver
import json
import urllib.parse
from datetime import datetime

PORT = 8000

class AIMarketingHandler(http.server.BaseHTTPRequestHandler):
    """Custom handler for AI Marketing API endpoints."""

    def do_GET(self):
        """Handle GET requests."""
        parsed_path = urllib.parse.urlparse(self.path)
        path = parsed_path.path

        # Route the requests
        if path == '/':
            self.send_json_response({
                "message": "AI Marketing Web Builder Platform",
                "version": "0.1.0",
                "status": "running",
                "timestamp": datetime.now().isoformat()
            })
        elif path == '/health':
            self.send_json_response({
                "status": "healthy",
                "timestamp": datetime.now().isoformat()
            })
        elif path == '/api/status':
            self.send_json_response({
                "api": {
                    "name": "AI Marketing Web Builder Platform",
                    "version": "0.1.0",
                    "environment": "development"
                },
                "services": {
                    "server": "running",
                    "database": "pending",
                    "redis": "pending"
                },
                "features": {
                    "workflow_automation": "ready",
                    "crm_integration": "ready",
                    "campaign_management": "ready"
                }
            })
        elif path == '/api/workflows':
            self.send_json_response({
                "workflows": [],
                "total": 0,
                "message": "Workflow system ready for implementation"
            })
        elif path == '/api/campaigns':
            self.send_json_response({
                "campaigns": [],
                "total": 0,
                "message": "Campaign system ready for implementation"
            })
        else:
            self.send_json_response({
                "error": "Endpoint not found",
                "path": path
            }, status_code=404)

    def do_POST(self):
        """Handle POST requests."""
        self.send_json_response({
            "message": "POST endpoint ready",
            "path": self.path
        })

    def send_json_response(self, data, status_code=200):
        """Send JSON response."""
        self.send_response(status_code)
        self.send_header('Content-type', 'application/json')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        self.end_headers()

        response_json = json.dumps(data, indent=2)
        self.wfile.write(response_json.encode('utf-8'))

    def log_message(self, format, *args):
        """Override to customize logging."""
        print(f"[{datetime.now().isoformat()}] {format % args}")

if __name__ == "__main__":
    print(f"""
🚀 AI Marketing Web Builder Platform - Backend Server
=====================================
Server starting on http://localhost:{PORT}

Available endpoints:
- GET  /              - Root API info
- GET  /health        - Health check
- GET  /api/status    - Detailed status
- GET  /api/workflows - Workflows (placeholder)
- GET  /api/campaigns - Campaigns (placeholder)

Press Ctrl+C to stop the server
=====================================
    """)

    with socketserver.TCPServer(("", PORT), AIMarketingHandler) as httpd:
        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            print(f"\n🛑 Server stopped")
            httpd.shutdown()

"""Base models and mixins for SQLAlchemy."""

import uuid
from datetime import datetime
from typing import Any

from sqlalchemy import Column, DateTime, String
from sqlalchemy.dialects.sqlite import TEXT
from sqlalchemy.ext.declarative import as_declarative, declared_attr
from sqlalchemy.types import TypeDecorator


# Custom UUID type for SQLite compatibility
class UUIDType(TypeDecorator):
    """SQLite-compatible UUID type."""
    impl = String(36)
    cache_ok = True

    def process_bind_param(self, value, dialect):
        if value is None:
            return None
        if isinstance(value, uuid.UUID):
            return str(value)
        return str(uuid.UUID(value))

    def process_result_value(self, value, dialect):
        if value is None:
            return None
        return uuid.UUID(value)


from sqlalchemy.orm import declarative_base

Base = declarative_base()

class BaseModel(Base):
    """Base class for all database models."""
    __abstract__ = True

    id: Any


class TimestampMixin:
    """Mixin for adding created_at and updated_at timestamps."""

    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)
    updated_at = Column(
        DateTime, 
        default=datetime.utcnow, 
        onupdate=datetime.utcnow, 
        nullable=False
    )


class UUIDMixin:
    """Mixin for adding UUID primary key."""

    id = Column(
        UUIDType, 
        primary_key=True, 
        default=uuid.uuid4, 
        nullable=False
    )

""" User schemas for API request/response validation. """
from typing import Optional from pydantic import BaseModel, EmailStr, Field, ConfigDict from datetime import datetime
class UserBase(BaseModel): """Base user schema.""" email: EmailStr first_name: Optional[str] = None last_name: Optional[str] = None company: Optional[str] = None phone: Optional[str] = None bio: Optional[str] = None avatar_url: Optional[str] = None
class UserCreate(UserBase): """User creation schema.""" password: str = Field(..., min_length=8, description="Password must be at least 8 characters")
class UserUpdate(BaseModel): """User update schema.""" first_name: Optional[str] = None last_name: Optional[str] = None company: Optional[str] = None phone: Optional[str] = None bio: Optional[str] = None avatar_url: Optional[str] = None
class UserPasswordUpdate(BaseModel): """User password update schema.""" current_password: str new_password: str = Field(..., min_length=8)
class UserInDB(UserBase): """User schema for database operations.""" model_config = ConfigDict(from_attributes=True)
id: int is_active: bool is_superuser: bool is_verified: bool created_at: datetime updated_at: Optional[datetime] = None
class User(UserInDB): """User schema for API responses.""" full_name: str
@property def full_name(self) -> str: if self.first_name and self.last_name: return f"{self.first_name} {self.last_name}" return self.email
class UserLogin(BaseModel): """User login schema.""" email: EmailStr password: str
class Token(BaseModel): """Authentication token schema.""" access_token: str token_type: str = "bearer" expires_in: int user: User

""" Advanced A/B testing service for template optimization with statistical analysis. """
import json import logging import uuid from typing import Dict, List, Optional, Any, Tuple from datetime import datetime, timedelta from sqlalchemy.ext.asyncio import AsyncSession from sqlalchemy import select, func, and_ import numpy as np from scipy import stats
from app.models.template import Template from app.models.ab_test import ABTest, ABTestVariant, ABTestStatus, ABTestResult from app.services.ai_service import AIService from app.services.template_service import TemplateService from app.core.celery import celery_app
logger = logging.getLogger(__name__)
class StatisticalAnalyzer: """Statistical analysis utilities for A/B testing."""
@staticmethod def calculate_sample_size( baseline_rate: float, minimum_effect: float = 0.05, power: float = 0.8, alpha: float = 0.05 ) -> int: """Calculate required sample size for A/B test.""" if baseline_rate <= 0 or baseline_rate >= 1: return 1000
# Cohen's h effect size p1 = baseline_rate p2 = baseline_rate + minimum_effect
# Standard normal quantiles z_alpha = stats.norm.ppf(1 - alpha/2) z_beta = stats.norm.ppf(power)
# Pooled proportion p_pool = (p1 + p2) / 2
# Sample size calculation numerator = (z_alpha * np.sqrt(2 * p_pool * (1 - p_pool)) + z_beta * np.sqrt(p1 * (1 - p1) + p2 * (1 - p2)))**2 denominator = (p2 - p1)**2
sample_size = int(np.ceil(numerator / denominator)) return max(sample_size, 100) # Minimum 100 samples
@staticmethod def calculate_confidence_interval( successes: int, trials: int, confidence: float = 0.95 ) -> Tuple[float, float]: """Calculate Wilson confidence interval for conversion rate.""" if trials == 0: return (0.0, 0.0)
p = successes / trials z = stats.norm.ppf(1 - (1 - confidence) / 2)
denominator = 1 + z**2 / trials centre = (p + z**2 / (2 * trials)) / denominator half_width = z * np.sqrt(p * (1 - p) / trials + z**2 / (4 * trials**2)) / denominator
return (max(0, centre - half_width), min(1, centre + half_width))
@staticmethod def perform_chi_square_test( variant_a_successes: int, variant_a_trials: int, variant_b_successes: int, variant_b_trials: int ) -> Dict[str, Any]: """Perform chi-square test for conversion rate difference.""" if variant_a_trials == 0 or variant_b_trials == 0: return {"significant": False, "p_value": 1.0}
# Contingency table table = [ [variant_a_successes, variant_a_trials - variant_a_successes], [variant_b_successes, variant_b_trials - variant_b_successes] ]
chi2, p_value = stats.chi2_contingency(table)[:2]
return { "significant": p_value < 0.05, "p_value": float(p_value), "chi_square": float(chi2), "effect_size": abs( variant_b_successes / variant_b_trials - variant_a_successes / variant_a_trials ) }
class ABTestService: """A/B testing service for template optimization."""
def __init__(self, db: AsyncSession): self.db = db self.ai_service = AIService() self.template_service = TemplateService(db) self.statistical_analyzer = StatisticalAnalyzer()
async def create_ab_test( self, base_template_id: int, test_name: str, hypothesis: str, primary_metric: str, variants_config: List[Dict[str, Any]] ) -> Dict[str, Any]: """Create a new A/B test with AI-generated variants.""" try: base_template = await self.template_service.get_by_id(base_template_id) if not base_template: return {"success": False, "error": "Base template not found"}
# Generate AI variants ai_variants = await self._generate_ai_variants( base_template, variants_config )
# Calculate required sample size baseline_conversion = await self._get_baseline_conversion(base_template_id) required_sample_size = self.statistical_analyzer.calculate_sample_size( baseline_conversion )
# Create A/B test ab_test = ABTest( name=test_name, description=hypothesis, base_template_id=base_template_id, primary_metric=primary_metric, status=ABTestStatus.DRAFT, required_sample_size=required_sample_size, estimated_duration_days=14, configuration={ "baseline_conversion": baseline_conversion, "confidence_level": 0.95, "power": 0.8, "minimum_detectable_effect": 0.05 } )
self.db.add(ab_test) await self.db.flush()
# Create variants variants = [] for i, variant_config in enumerate(ai_variants): variant = ABTestVariant( ab_test_id=ab_test.id, name=variant_config["name"], description=variant_config["description"], template_data=variant_config["template_data"], weight=1.0 / (len(ai_variants) + 1), # Equal distribution configuration=variant_config.get("configuration", {}) ) variants.append(variant) self.db.add(variant)
# Add control variant (original) control_variant = ABTestVariant( ab_test_id=ab_test.id, name="Control (Original)", description="Original template as control", template_data=base_template.components, weight=1.0 / (len(ai_variants) + 1), is_control=True, configuration={} ) variants.append(control_variant) self.db.add(control_variant)
await self.db.commit()
return { "success": True, "test_id": ab_test.id, "test_name": test_name, "required_sample_size": required_sample_size, "estimated_duration_days": 14, "variants": [ { "id": v.id, "name": v.name, "description": v.description } for v in variants ] }
except Exception as e: logger.error(f"Error creating A/B test: {str(e)}") return {"success": False, "error": str(e)}
async def start_ab_test(self, test_id: int) -> Dict[str, Any]: """Start an A/B test.""" try: test = await self.db.get(ABTest, test_id) if not test: return {"success": False, "error": "Test not found"}
if test.status != ABTestStatus.DRAFT: return {"success": False, "error": "Test is not in draft status"}
test.status = ABTestStatus.RUNNING test.started_at = datetime.utcnow() test.expected_completion_date = datetime.utcnow() + timedelta(days=test.estimated_duration_days)
await self.db.commit()
# Queue monitoring task celery_app.send_task( "monitor_ab_test", args=[test_id], countdown=3600 # Check in 1 hour )
return { "success": True, "test_id": test_id, "status": "running", "expected_completion": test.expected_completion_date.isoformat() }
except Exception as e: logger.error(f"Error starting A/B test: {str(e)}") return {"success": False, "error": str(e)}
async def record_test_event( self, test_id: int, variant_id: int, event_type: str, user_id: Optional[str] = None, metadata: Optional[Dict] = None ) -> Dict[str, Any]: """Record an event for A/B test analysis.""" try: test = await self.db.get(ABTest, test_id) if not test: return {"success": False, "error": "Test not found"}
variant = await self.db.get(ABTestVariant, variant_id) if not variant or variant.ab_test_id != test_id: return {"success": False, "error": "Variant not found"}
# Record event based on type if event_type == "view": variant.views += 1 elif event_type == "conversion": variant.conversions += 1 elif event_type == "bounce": variant.bounces += 1
# Add metadata if provided if metadata: variant.event_metadata.append({ "type": event_type, "timestamp": datetime.utcnow().isoformat(), "metadata": metadata, "user_id": user_id })
await self.db.commit()
# Check if test should be analyzed if test.status == ABTestStatus.RUNNING: await self._check_test_completion(test)
return {"success": True}
except Exception as e: logger.error(f"Error recording test event: {str(e)}") return {"success": False, "error": str(e)}
async def get_test_results(self, test_id: int) -> Dict[str, Any]: """Get comprehensive A/B test results.""" try: test = await self.db.get(ABTest, test_id) if not test: return {"success": False, "error": "Test not found"}
# Get all variants variants = await self.db.execute( select(ABTestVariant).where(ABTestVariant.ab_test_id == test_id) ) variants = variants.scalars().all()
# Calculate statistics for each variant results = [] control_variant = None
for variant in variants: if variant.is_control: control_variant = variant
conversion_rate = variant.conversions / variant.views if variant.views > 0 else 0 confidence_interval = self.statistical_analyzer.calculate_confidence_interval( variant.conversions, variant.views )
results.append({ "variant_id": variant.id, "name": variant.name, "views": variant.views, "conversions": variant.conversions, "conversion_rate": conversion_rate, "confidence_interval": { "lower": confidence_interval[0], "upper": confidence_interval[1] }, "is_control": variant.is_control, "is_winner": False # Will be determined later })
# Perform statistical tests if control_variant and len(variants) > 1: for result in results: if not result["is_control"]: test_result = self.statistical_analyzer.perform_chi_square_test( control_variant.conversions, control_variant.views, result["conversions"], result["views"] ) result["statistical_test"] = test_result
# Determine winner if (test_result["significant"] and result["conversion_rate"] > (control_variant.conversions / control_variant.views)): result["is_winner"] = True
# Find overall winner winner = max(results, key=lambda x: x["conversion_rate"]) if results else None if winner: for result in results: result["is_winner"] = (result["variant_id"] == winner["variant_id"] and not result["is_control"])
return { "success": True, "test_id": test_id, "test_name": test.name, "status": test.status.value, "results": results, "summary": { "total_views": sum(r["views"] for r in results), "total_conversions": sum(r["conversions"] for r in results), "significant_winner": any(r.get("statistical_test", {}).get("significant", False) for r in results), "winner_id": winner["variant_id"] if winner and winner.get("is_winner") else None } }
except Exception as e: logger.error(f"Error getting test results: {str(e)}") return {"success": False, "error": str(e)}
async def stop_ab_test(self, test_id: int, reason: str = "manual") -> Dict[str, Any]: """Stop an A/B test and declare final results.""" try: test = await self.db.get(ABTest, test_id) if not test: return {"success": False, "error": "Test not found"}
if test.status not in [ABTestStatus.RUNNING, ABTestStatus.COMPLETED]: return {"success": False, "error": "Test is not running"}
test.status = ABTestStatus.COMPLETED test.completed_at = datetime.utcnow() test.stop_reason = reason
# Final analysis results = await self.get_test_results(test_id)
# Store final results test.final_results = results
await self.db.commit()
return { "success": True, "test_id": test_id, "final_results": results }
except Exception as e: logger.error(f"Error stopping A/B test: {str(e)}") return {"success": False, "error": str(e)}
async def _generate_ai_variants( self, base_template: Template, variants_config: List[Dict[str, Any]] ) -> List[Dict[str, Any]]: """Generate AI-powered test variants.""" prompt = f""" Create A/B test variants for this {base_template.category} template:
TEMPLATE: {base_template.name} DESCRIPTION: {base_template.description} COMPONENTS: {len(base_template.components)} elements
Generate {len(variants_config)} variants focusing on: {json.dumps(variants_config, indent=2)}
Each variant should include: 1. Specific changes from original 2. Hypothesis for improvement 3. Expected impact on conversion 4. Implementation details
Return JSON with structured variant data. """
ai_response = await self.ai_service.generate_json_response( prompt, expected_schema={ "variants": List[Dict] } )
return ai_response.get("variants", [])
async def _get_baseline_conversion(self, template_id: int) -> float: """Get baseline conversion rate for template.""" # Mock implementation - would query analytics return 0.15
async def _check_test_completion(self, test: ABTest): """Check if A/B test should be completed.""" try: variants = await self.db.execute( select(ABTestVariant).where(ABTestVariant.ab_test_id == test.id) ) variants = variants.scalars().all()
total_views = sum(v.views for v in variants)
if total_views >= test.required_sample_size: # Auto-complete test await self.stop_ab_test(test.id, "sample_size_reached")
except Exception as e: logger.error(f"Error checking test completion: {str(e)}")
@celery_app.task def monitor_ab_test(test_id: int): """Monitor A/B test progress and auto-complete if needed.""" logger.info(f"Monitoring A/B test {test_id}") # Implementation would check test status and completion criteria
@celery_app.task def generate_ab_test_report(test_id: int): """Generate comprehensive A/B test report.""" logger.info(f"Generating report for A/B test {test_id}") # Implementation would create detailed analysis and recommendations

""" AI service for integrating with Google Gemini API. Provides AI-powered content generation and analysis capabilities. Enhanced for Epic 4: Advanced AI Features with multi-model support. """
import logging import json import asyncio from typing import Dict, Any, Optional, List from datetime import datetime, timedelta import aiohttp import os from functools import wraps from asyncio import Semaphore import hashlib
logger = logging.getLogger(__name__)
class RateLimiter: """Rate limiter for API calls."""
def __init__(self, max_calls: int = 60, time_window: int = 60): self.max_calls = max_calls self.time_window = time_window self.calls = [] self.semaphore = Semaphore(max_calls)
async def acquire(self): """Acquire permission to make an API call.""" await self.semaphore.acquire()
now = datetime.utcnow() # Remove old calls outside the time window self.calls = [call for call in self.calls if now - call < timedelta(seconds=self.time_window)]
if len(self.calls) >= self.max_calls: sleep_time = self.time_window - (now - self.calls[0]).total_seconds() if sleep_time > 0: await asyncio.sleep(sleep_time)
self.calls.append(now) self.semaphore.release()
def rate_limit(max_calls: int = 60, time_window: int = 60): """Decorator for rate limiting.""" limiter = RateLimiter(max_calls, time_window)
def decorator(func): @wraps(func) async def wrapper(*args, **kwargs): await limiter.acquire() return await func(*args, **kwargs) return wrapper return decorator
class IntelligentModelRouter: """Route AI requests to optimal models based on task complexity and requirements."""
MODEL_ROUTING = { 'component_suggestions': { 'simple': 'gemini-1.5-flash', 'complex': 'gpt-4-turbo' }, 'template_generation': { 'default': 'claude-3.5-sonnet', 'creative': 'gpt-4-turbo' }, 'workflow_creation': { 'default': 'claude-3.5-sonnet' }, 'performance_analysis': { 'default': 'gpt-4-turbo' } }
async def select_model(self, task_type: str, context: Any = None) -> str: """Select optimal model for task based on context complexity."""
if task_type not in self.MODEL_ROUTING: return 'gemini-1.5-flash' # Default fallback
task_config = self.MODEL_ROUTING[task_type]
# Simple routing logic - can be enhanced with ML-based routing if task_type == 'component_suggestions': # Use complex model if context has many existing components if isinstance(context, dict) and len(context.get('existing_components', [])) > 10: return task_config.get('complex', task_config['simple']) return task_config['simple']
return task_config.get('default', 'gemini-1.5-flash')
class AIService: """Enhanced AI service for Epic 4 advanced AI features with multi-model support."""
def __init__(self): self.api_key = os.getenv("GOOGLE_API_KEY") self.openai_api_key = os.getenv("OPENAI_API_KEY") self.anthropic_api_key = os.getenv("ANTHROPIC_API_KEY")
# Model configurations self.models = { 'gemini-1.5-flash': { 'base_url': 'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent', 'api_key': self.api_key, 'type': 'gemini' }, 'gpt-4-turbo': { 'base_url': 'https://api.openai.com/v1/chat/completions', 'api_key': self.openai_api_key, 'type': 'openai' }, 'claude-3.5-sonnet': { 'base_url': 'https://api.anthropic.com/v1/messages', 'api_key': self.anthropic_api_key, 'type': 'anthropic' } }
# Epic 4: Intelligent model routing self.model_router = IntelligentModelRouter() self.session = None
# Performance tracking self.request_count = 0 self.total_latency = 0
# Epic 4: AI feature caches self.component_suggestion_cache = {} self.template_generation_cache = {} self.workflow_creation_cache = {}
async def __aenter__(self): """Async context manager entry.""" self.session = aiohttp.ClientSession() return self
async def __aexit__(self, exc_type, exc_val, exc_tb): """Async context manager exit.""" if self.session: await self.session.close()
@rate_limit(max_calls=60, time_window=60) async def generate_response(self, prompt: str, max_tokens: int = 2000) -> str: """Generate text response using Gemini API.""" if not self.api_key: logger.error("Google API key not found") raise ValueError("Google API key not configured")
if not self.session: self.session = aiohttp.ClientSession()
headers = { "Content-Type": "application/json", }
payload = { "contents": [{ "parts": [{"text": prompt}] }], "generationConfig": { "temperature": 0.7, "topK": 40, "topP": 0.95, "maxOutputTokens": max_tokens, } }
url = f"{self.base_url}?key={self.api_key}"
try: async with self.session.post(url, json=payload, headers=headers) as response: if response.status == 200: data = await response.json() if "candidates" in data and data["candidates"]: content = data["candidates"][0]["content"]["parts"][0]["text"] return content.strip() else: logger.error(f"No candidates in response: {data}") raise ValueError("No response generated") else: error_text = await response.text() logger.error(f"API error {response.status}: {error_text}") raise ValueError(f"API request failed: {response.status}")
except aiohttp.ClientError as e: logger.error(f"Network error calling Gemini API: {str(e)}") raise ValueError(f"Network error: {str(e)}") except Exception as e: logger.error(f"Unexpected error in AI service: {str(e)}") raise
@rate_limit(max_calls=30, time_window=60) async def generate_json_response( self, prompt: str, expected_schema: Optional[Dict[str, Any]] = None ) -> Dict[str, Any]: """Generate JSON response using Gemini API.""" json_prompt = f""" {prompt}
Please respond with valid JSON only. Ensure the response is properly formatted and parseable. """
try: response = await self.generate_response(json_prompt, max_tokens=4000)
# Clean response to extract JSON response = response.strip() if response.startswith("```json"): response = response[7:] if response.startswith("```"): response = response[3:] if response.endswith("```"): response = response[:-3]
response = response.strip()
# Parse JSON data = json.loads(response)
# Validate against expected schema if provided if expected_schema: self._validate_schema(data, expected_schema)
return data
except json.JSONDecodeError as e: logger.error(f"Invalid JSON response: {str(e)}") logger.error(f"Response: {response}") raise ValueError(f"Invalid JSON response: {str(e)}") except Exception as e: logger.error(f"Error processing JSON response: {str(e)}") raise
def _validate_schema(self, data: Dict[str, Any], expected_schema: Dict[str, Any]) -> bool: """Validate response against expected schema.""" try: self._check_schema_compatibility(data, expected_schema) return True except Exception as e: logger.warning(f"Schema validation warning: {str(e)}") return False
def _check_schema_compatibility(self, data: Any, schema: Any, path: str = "") -> None: """Recursively check schema compatibility.""" if isinstance(schema, dict): if not isinstance(data, dict): raise ValueError(f"Expected dict at {path}, got {type(data)}")
for key, expected_type in schema.items(): if key not in data: raise ValueError(f"Missing key '{key}' at {path}")
new_path = f"{path}.{key}" if path else key self._check_schema_compatibility(data[key], expected_type, new_path)
elif isinstance(schema, list): if not isinstance(data, list): raise ValueError(f"Expected list at {path}, got {type(data)}")
if schema and data: for i, item in enumerate(data): self._check_schema_compatibility(item, schema[0], f"{path}[{i}]")
elif schema == str: if not isinstance(data, str): raise ValueError(f"Expected string at {path}, got {type(data)}")
elif schema == int: if not isinstance(data, int): raise ValueError(f"Expected int at {path}, got {type(data)}")
elif schema == float: if not isinstance(data, (int, float)): raise ValueError(f"Expected float at {path}, got {type(data)}")
elif schema == bool: if not isinstance(data, bool): raise ValueError(f"Expected bool at {path}, got {type(data)}")
async def analyze_content(self, content: str, analysis_type: str = "general") -> Dict[str, Any]: """Analyze content for various metrics.""" prompt = f""" Analyze the following content for {analysis_type}:
CONTENT: {content}
Provide analysis in JSON format with: - sentiment: overall sentiment (positive/negative/neutral) - keywords: top 10 relevant keywords - readability_score: readability score (0-100) - engagement_potential: engagement prediction (0-100) - seo_score: SEO optimization score (0-100) - suggestions: list of improvement suggestions """
return await self.generate_json_response(prompt)
async def generate_marketing_copy( self, context: str, target_audience: str, tone: str = "professional" ) -> Dict[str, Any]: """Generate marketing copy variations.""" prompt = f""" Generate marketing copy for:
CONTEXT: {context} TARGET AUDIENCE: {target_audience} TONE: {tone}
