async def generate_component_suggestions( self, context: Dict[str, Any], current_components: List[Dict[str, Any]] = None, user_preferences: Dict[str, Any] = None ) -> List[Dict[str, Any]]: """Generate intelligent component suggestions based on context."""
cache_key = self._generate_cache_key('component_suggestions', context) if cache_key in self.component_suggestion_cache: return self.component_suggestion_cache[cache_key]
prompt = f""" Analyze the current website building context and suggest 5 highly relevant components:
