# Epic 4: Enhanced utility methods
async def generate_json_response_with_model( self, prompt: str, model: str, max_tokens: int = 2000 ) -> Dict[str, Any]: """Generate JSON response using specific AI model."""
model_config = self.models.get(model) if not model_config: # Fallback to default Gemini model return await self.generate_json_response(prompt)
if model_config['type'] == 'gemini': return await self.generate_json_response(prompt) elif model_config['type'] == 'openai': return await self._generate_openai_json_response(prompt, model_config, max_tokens) elif model_config['type'] == 'anthropic': return await self._generate_anthropic_json_response(prompt, model_config, max_tokens) else: return await self.generate_json_response(prompt)
async def _generate_openai_json_response( self, prompt: str, model_config: Dict[str, Any], max_tokens: int ) -> Dict[str, Any]: """Generate JSON response using OpenAI API."""
if not model_config['api_key']: logger.warning("OpenAI API key not found, falling back to Gemini") return await self.generate_json_response(prompt)
if not self.session: self.session = aiohttp.ClientSession()
headers = { "Authorization": f"Bearer {model_config['api_key']}", "Content-Type": "application/json" }
payload = { "model": "gpt-4-turbo-preview", "messages": [ {"role": "system", "content": "You are an expert AI assistant. Always respond with valid JSON only."}, {"role": "user", "content": prompt} ], "max_tokens": max_tokens, "temperature": 0.7, "response_format": {"type": "json_object"} }
try: async with self.session.post(model_config['base_url'], json=payload, headers=headers) as response: if response.status == 200: data = await response.json() if "choices" in data and data["choices"]: content = data["choices"][0]["message"]["content"] return json.loads(content.strip()) else: logger.error(f"No choices in OpenAI response: {data}") raise ValueError("No response generated") else: error_text = await response.text() logger.error(f"OpenAI API error {response.status}: {error_text}") # Fallback to Gemini return await self.generate_json_response(prompt) except Exception as e: logger.error(f"OpenAI API call failed: {str(e)}, falling back to Gemini") return await self.generate_json_response(prompt)
async def _generate_anthropic_json_response( self, prompt: str, model_config: Dict[str, Any], max_tokens: int ) -> Dict[str, Any]: """Generate JSON response using Anthropic Claude API."""
if not model_config['api_key']: logger.warning("Anthropic API key not found, falling back to Gemini") return await self.generate_json_response(prompt)
if not self.session: self.session = aiohttp.ClientSession()
headers = { "x-api-key": model_config['api_key'], "Content-Type": "application/json", "anthropic-version": "2023-06-01" }
json_instruction = "\n\nPlease respond with valid JSON only. Do not include any other text or formatting."
payload = { "model": "claude-3-5-sonnet-20241022", "max_tokens": max_tokens, "temperature": 0.7, "messages": [ {"role": "user", "content": prompt + json_instruction} ] }
try: async with self.session.post(model_config['base_url'], json=payload, headers=headers) as response: if response.status == 200: data = await response.json() if "content" in data and data["content"]: content = data["content"][0]["text"]
# Clean response to extract JSON content = content.strip() if content.startswith("```json"): content = content[7:] if content.startswith("```"): content = content[3:] if content.endswith("```"): content = content[:-3]
return json.loads(content.strip()) else: logger.error(f"No content in Claude response: {data}") raise ValueError("No response generated") else: error_text = await response.text() logger.error(f"Claude API error {response.status}: {error_text}") # Fallback to Gemini return await self.generate_json_response(prompt) except Exception as e: logger.error(f"Claude API call failed: {str(e)}, falling back to Gemini") return await self.generate_json_response(prompt)
def _generate_cache_key(self, feature: str, data: Dict[str, Any]) -> str: """Generate cache key for AI responses.""" data_str = json.dumps(data, sort_keys=True) hash_key = hashlib.md5(f"{feature}:{data_str}".encode()).hexdigest() return f"{feature}:{hash_key}"
async def _expire_cache_key(self, cache_type: str, cache_key: str, delay: int): """Expire cache key after delay.""" await asyncio.sleep(delay)
cache_map = { 'component_suggestions': self.component_suggestion_cache, 'template_generation': self.template_generation_cache, 'workflow_creation': self.workflow_creation_cache }
cache = cache_map.get(cache_type) if cache and cache_key in cache: del cache[cache_key]
# Performance tracking methods
def get_performance_metrics(self) -> Dict[str, Any]: """Get AI service performance metrics.""" avg_latency = self.total_latency / max(self.request_count, 1)
return { "total_requests": self.request_count, "average_latency_ms": avg_latency, "cache_stats": { "component_suggestions_cached": len(self.component_suggestion_cache), "template_generation_cached": len(self.template_generation_cache), "workflow_creation_cached": len(self.workflow_creation_cache) }, "model_availability": { "gemini": bool(self.api_key), "openai": bool(self.openai_api_key), "anthropic": bool(self.anthropic_api_key) } }
async def clear_caches(self): """Clear all AI response caches.""" self.component_suggestion_cache.clear() self.template_generation_cache.clear() self.workflow_creation_cache.clear()
logger.info("All AI service caches cleared")
