""" AI-powered template generation service. Provides intelligent template creation, optimization, and customization. """
import json import logging from typing import Dict, List, Optional, Any, Tuple from datetime import datetime from sqlalchemy.ext.asyncio import AsyncSession from sqlalchemy import select, func
from app.models.template import Template, TemplateComponent, TemplateCategory, TemplateStatus from app.models.user import User from app.services.template_service import TemplateService from app.services.ai_service import AIService from app.schemas.template import TemplateCreate, TemplateComponentCreate from app.core.celery import celery_app
logger = logging.getLogger(__name__)
class AITemplateService: """AI-powered template generation and optimization service."""
def __init__(self, db: AsyncSession, ai_service: AIService = None): self.db = db self.template_service = TemplateService(db) self.ai_service = ai_service or AIService()
async def generate_template_from_description( self, description: str, category: TemplateCategory, user_id: Optional[int] = None, style_preferences: Optional[Dict[str, Any]] = None ) -> Dict[str, Any]: """ Generate a complete template from natural language description.
Args: description: Natural language description of desired template category: Template category (landing, ecommerce, etc.) user_id: Optional user ID for personalization style_preferences: Style and layout preferences
Returns: Generated template data with components """ try: # Generate template structure using AI prompt = self._build_template_generation_prompt( description, category, style_preferences )
ai_response = await self.ai_service.generate_json_response( prompt, expected_schema={ "template": { "name": str, "description": str, "category": str, "components": List[Dict], "layout": Dict, "styles": Dict } } )
template_data = ai_response.get("template", {})
# Create template object template_create = TemplateCreate( name=template_data.get("name", f"AI Generated {category.value.title()}"), description=template_data.get("description", description), category=category, thumbnail="/api/placeholder/400/300", # Placeholder components=template_data.get("components", []), is_featured=False, is_premium=False, created_by=user_id, ai_generated=True, generation_metadata={ "original_description": description, "style_preferences": style_preferences or {}, "generation_time": datetime.utcnow().isoformat(), "ai_model": "gemini-1.5-flash" } )
# Save template to database template = await self.template_service.create(template_create)
# Queue optimization task if template: await self._queue_template_optimization(template.id)
return { "success": True, "template": template, "components_count": len(template_data.get("components", [])), "optimization_queued": template is not None }
except Exception as e: logger.error(f"Error generating template: {str(e)}") return { "success": False, "error": str(e), "template": None }
async def optimize_template_for_conversion( self, template_id: int, target_metrics: Dict[str, Any] ) -> Dict[str, Any]: """ Optimize existing template for better conversion rates.
Args: template_id: ID of template to optimize target_metrics: Target conversion metrics (CTR, bounce rate, etc.)
Returns: Optimization results with suggestions """ try: template = await self.template_service.get_by_id(template_id) if not template: return {"success": False, "error": "Template not found"}
# Analyze template for optimization opportunities prompt = self._build_optimization_prompt(template, target_metrics)
ai_response = await self.ai_service.generate_json_response( prompt, expected_schema={ "optimization": { "suggestions": List[Dict], "a_b_test_variants": List[Dict], "performance_predictions": Dict, "priority_changes": List[Dict] } } )
optimization_data = ai_response.get("optimization", {})
# Save optimization metadata template.optimization_metadata = { **(template.optimization_metadata or {}), "last_optimization": { "timestamp": datetime.utcnow().isoformat(), "target_metrics": target_metrics, "suggestions": optimization_data.get("suggestions", []), "a_b_test_variants": optimization_data.get("a_b_test_variants", []) } }
await self.db.commit()
return { "success": True, "template_id": template_id, "suggestions": optimization_data.get("suggestions", []), "a_b_test_variants": optimization_data.get("a_b_test_variants", []), "performance_predictions": optimization_data.get("performance_predictions", {}) }
except Exception as e: logger.error(f"Error optimizing template: {str(e)}") return {"success": False, "error": str(e)}
async def generate_template_variants( self, base_template_id: int, variant_count: int = 3, variation_type: str = "aesthetic" ) -> List[Dict[str, Any]]: """ Generate multiple variants of a template for A/B testing.
Args: base_template_id: ID of base template variant_count: Number of variants to generate variation_type: Type of variation (aesthetic, layout, content)
Returns: List of template variants """ try: base_template = await self.template_service.get_by_id(base_template_id) if not base_template: return []
prompt = self._build_variant_generation_prompt( base_template, variant_count, variation_type )
ai_response = await self.ai_service.generate_json_response( prompt, expected_schema={ "variants": List[Dict] } )
variants = [] for i, variant_data in enumerate(ai_response.get("variants", [])): variant_create = TemplateCreate( name=f"{base_template.name} - Variant {i+1}", description=f"{base_template.description} (Variant {i+1})", category=base_template.category, thumbnail=f"/api/placeholder/400/300?text=Variant+{i+1}", components=variant_data.get("components", []), is_featured=False, is_premium=False, parent_template_id=base_template_id, variant_type=variation_type, generation_metadata={ "base_template_id": base_template_id, "variant_number": i+1, "variation_type": variation_type, "generation_time": datetime.utcnow().isoformat() } )
variant = await self.template_service.create(variant_create) if variant: variants.append(variant)
return variants
except Exception as e: logger.error(f"Error generating variants: {str(e)}") return []
async def personalize_template( self, template_id: int, user_data: Dict[str, Any], industry: str, brand_preferences: Dict[str, Any] ) -> Dict[str, Any]: """ Personalize template based on user data and brand preferences.
Args: template_id: ID of template to personalize user_data: User demographic and behavioral data industry: Target industry/business type brand_preferences: Brand colors, fonts, tone, etc.
Returns: Personalized template data """ try: template = await self.template_service.get_by_id(template_id) if not template: return {"success": False, "error": "Template not found"}
prompt = self._build_personalization_prompt( template, user_data, industry, brand_preferences )
ai_response = await self.ai_service.generate_json_response( prompt, expected_schema={ "personalization": { "customized_components": List[Dict], "style_adjustments": Dict, "content_recommendations": List[Dict], "seo_optimizations": Dict } } )
personalization_data = ai_response.get("personalization", {})
# Create personalized template personalized_create = TemplateCreate( name=f"{template.name} - Personalized", description=f"Personalized version of {template.description}", category=template.category, thumbnail=template.thumbnail, components=personalization_data.get("customized_components", template.components), is_featured=False, is_premium=True, # Personalized templates are premium personalization_metadata={ "base_template_id": template_id, "user_data_hash": hash(str(user_data)), # Hash for privacy "industry": industry, "brand_preferences": brand_preferences, "personalization_time": datetime.utcnow().isoformat() } )
personalized_template = await self.template_service.create(personalized_create)
return { "success": True, "personalized_template": personalized_template, "style_adjustments": personalization_data.get("style_adjustments", {}), "content_recommendations": personalization_data.get("content_recommendations", []), "seo_optimizations": personalization_data.get("seo_optimizations", {}) }
except Exception as e: logger.error(f"Error personalizing template: {str(e)}") return {"success": False, "error": str(e)}
def _build_template_generation_prompt( self, description: str, category: TemplateCategory, style_preferences: Optional[Dict[str, Any]] ) -> str: """Build AI prompt for template generation.""" style_prefs = json.dumps(style_preferences or {}, indent=2)
return f""" Generate a high-converting {category.value} website template based on the following requirements:
DESCRIPTION: {description} CATEGORY: {category.value} STYLE PREFERENCES: {style_prefs}
Requirements: 1. Create a complete template with 5-10 strategically arranged components 2. Optimize for conversion rates and user experience 3. Include modern design patterns and best practices 4. Ensure mobile responsiveness 5. Add appropriate CTAs and conversion elements 6. Use semantic HTML and accessibility best practices
Return a JSON object with: - template: object with name, description, category, components, layout, and styles - Each component should have: type, name, props, styles, and positioning info - Focus on {category.value} industry best practices - Include performance optimization recommendations """
def _build_optimization_prompt( self, template: Template, target_metrics: Dict[str, Any] ) -> str: """Build AI prompt for template optimization.""" return f""" Analyze and optimize the following website template for better conversion rates:
TEMPLATE: {template.name} DESCRIPTION: {template.description} CATEGORY: {template.category} TARGET METRICS: {json.dumps(target_metrics, indent=2)}
Components: {len(template.components)} elements
Provide optimization suggestions focusing on: 1. Conversion rate optimization (CRO) 2. User experience improvements 3. A/B test variants 4. Performance predictions 5. Priority changes based on impact
Return JSON with optimization recommendations. """
def _build_variant_generation_prompt( self, template: Template, variant_count: int, variation_type: str ) -> str: """Build AI prompt for variant generation.""" return f""" Create {variant_count} {variation_type} variants of this website template for A/B testing:
BASE TEMPLATE: {template.name} DESCRIPTION: {template.description} CATEGORY: {template.category} VARIATION TYPE: {variation_type}
Original components: {len(template.components)} elements
Generate variants that test different: - Layout arrangements - Color schemes and styling - Component configurations - Content variations - CTA placements and designs
Ensure each variant is significantly different for meaningful A/B testing. """
def _build_personalization_prompt( self, template: Template, user_data: Dict[str, Any], industry: str, brand_preferences: Dict[str, Any] ) -> str: """Build AI prompt for personalization.""" return f""" Personalize this website template for a {industry} business:
TEMPLATE: {template.name} DESCRIPTION: {template.description} USER DATA: {json.dumps(user_data, indent=2)} BRAND PREFERENCES: {json.dumps(brand_preferences, indent=2)}
Customize: 1. Content and messaging for {industry} 2. Visual styling based on brand preferences 3. Component selection and arrangement 4. Color schemes and typography 5. Industry-specific features and CTAs 6. SEO optimizations for {industry}
Ensure the personalized template maintains conversion optimization while matching brand identity. """
async def _queue_template_optimization(self, template_id: int): """Queue template optimization task for async processing.""" try: celery_app.send_task( "optimize_template_async", args=[template_id], countdown=300 # 5 minutes delay ) except Exception as e: logger.error(f"Error queuing optimization: {str(e)}")
@celery_app.task def optimize_template_async(template_id: int): """Async task for template optimization.""" # This would run optimization algorithms, generate performance reports, # and update template metadata with optimization suggestions logger.info(f"Queued optimization for template {template_id}")

""" Context Analysis Service for intelligent template recommendations. Analyzes user context including industry, company size, goals, and business requirements. """
import logging from typing import Dict, List, Optional, Any, Tuple from datetime import datetime import json import asyncio from dataclasses import dataclass, asdict
from sqlalchemy.ext.asyncio import AsyncSession from sqlalchemy import select, func, and_, or_
from app.services.base_service import BaseService from app.services.ai_service import AIService from app.models.template import Template, TemplateCategory from app.models.user import User from app.models.analytics import ComponentAnalytics, SiteAnalytics
logger = logging.getLogger(__name__)
@dataclass class UserContext: """User context data structure.""" industry: Optional[str] = None company_size: Optional[str] = None business_stage: Optional[str] = None target_audience: Optional[str] = None geographic_region: Optional[str] = None technical_expertise: Optional[str] = None budget_range: Optional[str] = None timeline: Optional[str] = None marketing_goals: List[str] = None existing_brand_assets: bool = False competitor_analysis: Dict[str, Any] = None
def __post_init__(self): if self.marketing_goals is None: self.marketing_goals = [] if self.competitor_analysis is None: self.competitor_analysis = {}
@dataclass class BusinessRequirements: """Business requirements analysis.""" primary_goal: str secondary_goals: List[str] required_features: List[str] preferred_style: str content_complexity: str integration_needs: List[str] compliance_requirements: List[str] performance_priorities: List[str] success_metrics: List[str]
@dataclass class ContextAnalysisResult: """Result of context analysis.""" context_score: float confidence_level: str industry_match: bool size_match: bool goals_alignment: float technical_fit: float budget_compatibility: float recommended_categories: List[str] suggested_features: List[str] potential_challenges: List[str] success_probability: float analysis_metadata: Dict[str, Any]
class ContextAnalysisService(BaseService): """Service for analyzing user context and business requirements."""
def __init__(self, db_session: AsyncSession): super().__init__(db_session) self.ai_service = AIService()
# Industry categorization mapping self.industry_categories = { "technology": ["saas", "software", "tech_startup", "ai_ml"], "ecommerce": ["retail", "online_store", "marketplace", "dropshipping"], "professional_services": ["consulting", "legal", "accounting", "healthcare"], "creative": ["design", "photography", "marketing_agency", "media"], "education": ["online_courses", "schools", "training", "coaching"], "finance": ["fintech", "banking", "insurance", "investment"], "real_estate": ["property_management", "real_estate_agency", "construction"], "food_beverage": ["restaurant", "catering", "food_delivery", "brewery"], "fitness_wellness": ["gym", "spa", "wellness", "personal_training"], "nonprofit": ["charity", "foundation", "social_cause", "community"] }
# Company size impact factors self.size_factors = { "startup": {"complexity": 0.3, "features": 0.4, "budget": 0.2}, "small_business": {"complexity": 0.5, "features": 0.6, "budget": 0.5}, "medium_business": {"complexity": 0.7, "features": 0.8, "budget": 0.8}, "enterprise": {"complexity": 0.9, "features": 1.0, "budget": 1.0} }
async def analyze_user_context( self, user_id: str, context_data: Dict[str, Any], include_historical: bool = True ) -> ContextAnalysisResult: """ Analyze comprehensive user context for template recommendations.
Args: user_id: User identifier context_data: Raw context information include_historical: Whether to include historical usage data
Returns: ContextAnalysisResult with detailed analysis """ try: # Parse context data user_context = UserContext(**context_data)
# Get historical data if requested historical_data = {} if include_historical: historical_data = await self._get_historical_context(user_id)
# Perform multi-dimensional analysis industry_analysis = await self._analyze_industry_context(user_context) size_analysis = await self._analyze_company_size_context(user_context) goals_analysis = await self._analyze_goals_alignment(user_context) technical_analysis = await self._analyze_technical_requirements(user_context) budget_analysis = await self._analyze_budget_constraints(user_context)
# Calculate composite scores context_score = await self._calculate_context_score( industry_analysis, size_analysis, goals_analysis, technical_analysis, budget_analysis )
# Determine confidence level confidence_level = self._determine_confidence_level(context_score, user_context)
# Generate recommendations recommended_categories = await self._recommend_template_categories(user_context) suggested_features = await self._suggest_required_features(user_context) potential_challenges = await self._identify_potential_challenges(user_context)
# Calculate success probability success_probability = await self._calculate_success_probability( user_context, historical_data )
# Compile metadata analysis_metadata = { "analysis_timestamp": datetime.utcnow().isoformat(), "industry_category": self._categorize_industry(user_context.industry), "size_category": user_context.company_size, "primary_goals": user_context.marketing_goals[:3], "context_completeness": self._calculate_context_completeness(user_context), "historical_data_available": bool(historical_data) }
return ContextAnalysisResult( context_score=context_score, confidence_level=confidence_level, industry_match=industry_analysis["match_found"], size_match=size_analysis["appropriate_complexity"], goals_alignment=goals_analysis["alignment_score"], technical_fit=technical_analysis["compatibility_score"], budget_compatibility=budget_analysis["compatibility_score"], recommended_categories=recommended_categories, suggested_features=suggested_features, potential_challenges=potential_challenges, success_probability=success_probability, analysis_metadata=analysis_metadata )
except Exception as e: logger.error(f"Error analyzing user context: {str(e)}") raise
async def analyze_business_requirements( self, context_data: Dict[str, Any], project_description: str ) -> BusinessRequirements: """ Analyze business requirements from context and project description.
Args: context_data: User context information project_description: Natural language description of the project
Returns: BusinessRequirements analysis """ try: # Use AI to extract structured requirements analysis_prompt = f""" Analyze the following business context and project description to extract structured requirements:
Context: - Industry: {context_data.get('industry', 'Not specified')} - Company Size: {context_data.get('company_size', 'Not specified')} - Goals: {', '.join(context_data.get('marketing_goals', []))} - Target Audience: {context_data.get('target_audience', 'Not specified')} - Budget: {context_data.get('budget_range', 'Not specified')}
Project Description: {project_description}
Extract and return JSON with: {{ "primary_goal": "main business objective", "secondary_goals": ["additional objectives"], "required_features": ["essential features needed"], "preferred_style": "design style preference", "content_complexity": "simple/moderate/complex", "integration_needs": ["third-party integrations"], "compliance_requirements": ["regulatory needs"], "performance_priorities": ["performance requirements"], "success_metrics": ["how to measure success"] }} """
ai_result = await self.ai_service.generate_json_response(analysis_prompt)
return BusinessRequirements( primary_goal=ai_result.get("primary_goal", ""), secondary_goals=ai_result.get("secondary_goals", []), required_features=ai_result.get("required_features", []), preferred_style=ai_result.get("preferred_style", ""), content_complexity=ai_result.get("content_complexity", "moderate"), integration_needs=ai_result.get("integration_needs", []), compliance_requirements=ai_result.get("compliance_requirements", []), performance_priorities=ai_result.get("performance_priorities", []), success_metrics=ai_result.get("success_metrics", []) )
except Exception as e: logger.error(f"Error analyzing business requirements: {str(e)}") raise
async def score_template_suitability( self, template_id: int, user_context: UserContext, business_requirements: BusinessRequirements ) -> Dict[str, Any]: """ Score how suitable a template is for the given context and requirements.
Args: template_id: Template to evaluate user_context: User context information business_requirements: Business requirements analysis
Returns: Detailed suitability scoring """ try: # Get template information template = await self._get_template_details(template_id) if not template: raise ValueError(f"Template {template_id} not found")
# Analyze template characteristics template_analysis = await self._analyze_template_characteristics(template)
# Calculate dimension scores scores = {}
# Industry alignment score scores["industry_alignment"] = await self._score_industry_alignment( template, user_context.industry )
# Complexity match score scores["complexity_match"] = await self._score_complexity_match( template, user_context.company_size, business_requirements.content_complexity )
# Goals alignment score scores["goals_alignment"] = await self._score_goals_alignment( template, user_context.marketing_goals, business_requirements.primary_goal )
# Feature coverage score scores["feature_coverage"] = await self._score_feature_coverage( template, business_requirements.required_features )
# Style compatibility score scores["style_compatibility"] = await self._score_style_compatibility( template, business_requirements.preferred_style )
# Technical fit score scores["technical_fit"] = await self._score_technical_fit( template, user_context.technical_expertise, business_requirements.integration_needs )
# Calculate weighted overall score weights = { "industry_alignment": 0.25, "complexity_match": 0.20, "goals_alignment": 0.20, "feature_coverage": 0.15, "style_compatibility": 0.10, "technical_fit": 0.10 }
overall_score = sum( scores[dimension] * weights[dimension] for dimension in weights )
# Generate explanation explanation = await self._generate_suitability_explanation( template, scores, overall_score )
# Identify potential issues potential_issues = await self._identify_template_issues( template, user_context, business_requirements, scores )
return { "template_id": template_id, "overall_score": round(overall_score, 2), "dimension_scores": {k: round(v, 2) for k, v in scores.items()}, "explanation": explanation, "potential_issues": potential_issues, "recommendation": self._get_recommendation_level(overall_score), "analysis_timestamp": datetime.utcnow().isoformat(), "template_characteristics": template_analysis }
except Exception as e: logger.error(f"Error scoring template suitability: {str(e)}") raise
async def batch_analyze_templates( self, template_ids: List[int], user_context: UserContext, business_requirements: BusinessRequirements ) -> List[Dict[str, Any]]: """ Analyze multiple templates in batch for efficiency.
Args: template_ids: List of template IDs to analyze user_context: User context information business_requirements: Business requirements analysis
Returns: List of template suitability analyses """ try: # Process templates in parallel tasks = [ self.score_template_suitability(template_id, user_context, business_requirements) for template_id in template_ids ]
results = await asyncio.gather(*tasks, return_exceptions=True)
# Filter out failed analyses successful_results = [] for i, result in enumerate(results): if isinstance(result, Exception): logger.error(f"Failed to analyze template {template_ids[i]}: {str(result)}") else: successful_results.append(result)
# Sort by overall score successful_results.sort(key=lambda x: x["overall_score"], reverse=True)
return successful_results
except Exception as e: logger.error(f"Error in batch template analysis: {str(e)}") raise
# Private helper methods
async def _get_historical_context(self, user_id: str) -> Dict[str, Any]: """Get historical usage patterns for the user.""" try: # Query user's past template usage query = select(SiteAnalytics).where(SiteAnalytics.user_id == user_id) result = await self.db_session.execute(query) analytics = result.scalars().all()
if not analytics: return {}
# Analyze patterns historical_data = { "total_sites": len(analytics), "average_conversion_rate": sum(a.conversion_rate or 0 for a in analytics) / len(analytics), "most_used_categories": [], "performance_trends": [], "common_components": [] }
return historical_data
except Exception as e: logger.error(f"Error getting historical context: {str(e)}") return {}
async def _analyze_industry_context(self, context: UserContext) -> Dict[str, Any]: """Analyze industry-specific context.""" if not context.industry: return {"match_found": False, "category": None, "confidence": 0.0}
category = self._categorize_industry(context.industry)
return { "match_found": category is not None, "category": category, "confidence": 0.9 if category else 0.1, "industry_factors": self._get_industry_factors(context.industry) }
async def _analyze_company_size_context(self, context: UserContext) -> Dict[str, Any]: """Analyze company size implications.""" if not context.company_size: return {"appropriate_complexity": False, "size_factors": {}}
size_factors = self.size_factors.get(context.company_size, {})
return { "appropriate_complexity": bool(size_factors), "size_factors": size_factors, "recommended_complexity": self._get_recommended_complexity(context.company_size) }
async def _analyze_goals_alignment(self, context: UserContext) -> Dict[str, Any]: """Analyze marketing goals alignment.""" if not context.marketing_goals: return {"alignment_score": 0.0, "goal_categories": []}
# Categorize goals goal_categories = [] for goal in context.marketing_goals: category = self._categorize_goal(goal) if category: goal_categories.append(category)
alignment_score = len(goal_categories) / max(len(context.marketing_goals), 1)
return { "alignment_score": alignment_score, "goal_categories": goal_categories, "primary_focus": goal_categories[0] if goal_categories else None }
async def _analyze_technical_requirements(self, context: UserContext) -> Dict[str, Any]: """Analyze technical compatibility.""" expertise_levels = ["beginner", "intermediate", "advanced", "expert"] expertise_score = 0.25 # Default for not specified
if context.technical_expertise in expertise_levels: expertise_score = (expertise_levels.index(context.technical_expertise) + 1) / len(expertise_levels)
return { "compatibility_score": expertise_score, "expertise_level": context.technical_expertise or "beginner", "recommended_complexity": self._get_technical_complexity_recommendation(expertise_score) }
async def _analyze_budget_constraints(self, context: UserContext) -> Dict[str, Any]: """Analyze budget compatibility.""" budget_ranges = ["minimal", "low", "medium", "high", "unlimited"] budget_score = 0.5 # Default for not specified
if context.budget_range in budget_ranges: budget_score = (budget_ranges.index(context.budget_range) + 1) / len(budget_ranges)
return { "compatibility_score": budget_score, "budget_level": context.budget_range or "medium", "feature_recommendations": self._get_budget_appropriate_features(budget_score) }
def _categorize_industry(self, industry: str) -> Optional[str]: """Categorize industry into template categories.""" if not industry: return None
industry_lower = industry.lower() for category, keywords in self.industry_categories.items(): if any(keyword in industry_lower for keyword in keywords): return category
return "business" # Default category
def _categorize_goal(self, goal: str) -> Optional[str]: """Categorize marketing goal.""" goal_lower = goal.lower()
if any(word in goal_lower for word in ["lead", "conversion", "sales"]): return "lead_generation" elif any(word in goal_lower for word in ["brand", "awareness", "recognition"]): return "brand_awareness" elif any(word in goal_lower for word in ["engage", "community", "social"]): return "engagement" elif any(word in goal_lower for word in ["educate", "inform", "content"]): return "education" elif any(word in goal_lower for word in ["ecommerce", "sell", "product"]): return "ecommerce"
return "general"
async def _calculate_context_score(self, *analyses) -> float: """Calculate composite context score.""" scores = [] for analysis in analyses: if isinstance(analysis, dict): if "compatibility_score" in analysis: scores.append(analysis["compatibility_score"]) elif "alignment_score" in analysis: scores.append(analysis["alignment_score"]) elif "confidence" in analysis: scores.append(analysis["confidence"])
return sum(scores) / max(len(scores), 1)
def _determine_confidence_level(self, score: float, context: UserContext) -> str: """Determine confidence level of analysis.""" completeness = self._calculate_context_completeness(context)
if score >= 0.8 and completeness >= 0.7: return "high" elif score >= 0.6 and completeness >= 0.5: return "medium" else: return "low"
def _calculate_context_completeness(self, context: UserContext) -> float: """Calculate how complete the context information is.""" fields = asdict(context) completed_fields = sum(1 for value in fields.values() if value is not None and value != [] and value != {}) return completed_fields / len(fields)
async def _recommend_template_categories(self, context: UserContext) -> List[str]: """Recommend template categories based on context.""" categories = []
# Industry-based recommendations if context.industry: industry_category = self._categorize_industry(context.industry) if industry_category: categories.append(industry_category)
# Goal-based recommendations for goal in context.marketing_goals: goal_category = self._categorize_goal(goal) if goal_category and goal_category not in categories: categories.append(goal_category)
# Size-based recommendations if context.company_size in ["startup", "small_business"]: categories.extend(["landing_page", "portfolio"]) elif context.company_size in ["medium_business", "enterprise"]: categories.extend(["corporate", "enterprise"])
return categories[:5] # Limit to top 5 recommendations
async def _suggest_required_features(self, context: UserContext) -> List[str]: """Suggest required features based on context.""" features = []
# Industry-specific features if context.industry: industry_features = self._get_industry_features(context.industry) features.extend(industry_features)
# Goal-specific features for goal in context.marketing_goals: goal_features = self._get_goal_features(goal) features.extend(goal_features)
# Size-specific features if context.company_size: size_features = self._get_size_features(context.company_size) features.extend(size_features)
return list(set(features)) # Remove duplicates
async def _identify_potential_challenges(self, context: UserContext) -> List[str]: """Identify potential challenges based on context.""" challenges = []
if context.technical_expertise == "beginner": challenges.append("May need technical support for advanced customizations")
if context.budget_range in ["minimal", "low"]: challenges.append("Limited budget may restrict premium features")
if not context.existing_brand_assets: challenges.append("Will need to develop brand assets and guidelines")
if context.timeline and "urgent" in context.timeline.lower(): challenges.append("Tight timeline may limit customization options")
return challenges
async def _calculate_success_probability( self, context: UserContext, historical_data: Dict[str, Any] ) -> float: """Calculate probability of project success.""" base_probability = 0.7 # Base 70% success rate
# Adjust based on context completeness completeness = self._calculate_context_completeness(context) completeness_factor = completeness * 0.2
# Adjust based on technical expertise expertise_factor = 0.0 if context.technical_expertise: expertise_levels = ["beginner", "intermediate", "advanced", "expert"] if context.technical_expertise in expertise_levels: expertise_factor = (expertise_levels.index(context.technical_expertise) + 1) / len(expertise_levels) * 0.1
# Adjust based on historical performance historical_factor = 0.0 if historical_data and "average_conversion_rate" in historical_data: historical_factor = min(historical_data["average_conversion_rate"] / 100, 0.1)
return min(base_probability + completeness_factor + expertise_factor + historical_factor, 1.0)
# Additional helper methods for template scoring
async def _get_template_details(self, template_id: int) -> Optional[Template]: """Get detailed template information.""" query = select(Template).where(Template.id == template_id) result = await self.db_session.execute(query) return result.scalar_one_or_none()
async def _analyze_template_characteristics(self, template: Template) -> Dict[str, Any]: """Analyze template characteristics for scoring.""" return { "category": template.category, "complexity": self._assess_template_complexity(template), "features": self._extract_template_features(template), "style": self._analyze_template_style(template), "industry_focus": self._determine_template_industry_focus(template) }
def _assess_template_complexity(self, template: Template) -> str: """Assess template complexity level.""" component_count = len(template.components) if template.components else 0
if component_count <= 5: return "simple" elif component_count <= 15: return "moderate" else: return "complex"
def _extract_template_features(self, template: Template) -> List[str]: """Extract features from template.""" features = []
# Analyze components to identify features if template.components: for component in template.components: if component.get("type") == "contact_form": features.append("contact_form") elif component.get("type") == "gallery": features.append("image_gallery") elif component.get("type") == "testimonials": features.append("testimonials") elif component.get("type") == "blog": features.append("blog") elif component.get("type") == "ecommerce": features.append("ecommerce")
return features
def _get_industry_factors(self, industry: str) -> Dict[str, float]: """Get industry-specific factors.""" return { "visual_importance": 0.8 if "creative" in industry.lower() else 0.6, "trust_importance": 0.9 if any(word in industry.lower() for word in ["finance", "legal", "healthcare"]) else 0.7, "conversion_focus": 0.9 if "ecommerce" in industry.lower() else 0.6 }
def _get_industry_features(self, industry: str) -> List[str]: """Get features recommended for specific industries.""" industry_lower = industry.lower()
if "ecommerce" in industry_lower or "retail" in industry_lower: return ["product_catalog", "shopping_cart", "payment_integration", "reviews"] elif "restaurant" in industry_lower or "food" in industry_lower: return ["menu", "reservations", "location_map", "contact_form"] elif "professional" in industry_lower or "consulting" in industry_lower: return ["services", "testimonials", "contact_form", "about_team"] elif "creative" in industry_lower or "portfolio" in industry_lower: return ["portfolio", "image_gallery", "about", "contact_form"]
return ["contact_form", "about", "services"]
def _get_goal_features(self, goal: str) -> List[str]: """Get features for specific goals.""" goal_lower = goal.lower()
if any(word in goal_lower for word in ["lead", "conversion"]): return ["contact_form", "cta_buttons", "testimonials"] elif any(word in goal_lower for word in ["brand", "awareness"]): return ["about", "story", "team", "values"] elif "sales" in goal_lower: return ["product_showcase", "pricing", "testimonials", "guarantees"]
return []
def _get_size_features(self, company_size: str) -> List[str]: """Get features based on company size.""" if company_size in ["startup", "small_business"]: return ["contact_form", "about", "services"] elif company_size in ["medium_business", "enterprise"]: return ["team", "case_studies", "resources", "support"]
return []
async def _score_industry_alignment(self, template: Template, industry: str) -> float: """Score industry alignment.""" if not industry: return 0.5
template_industry = self._determine_template_industry_focus(template) user_industry_category = self._categorize_industry(industry)
if template_industry == user_industry_category: return 1.0 elif template_industry == "business": # Generic business template return 0.7 else: return 0.3
async def _score_complexity_match(self, template: Template, company_size: str, content_complexity: str) -> float: """Score complexity match.""" template_complexity = self._assess_template_complexity(template)
# Define ideal complexity mapping ideal_complexity = { "startup": "simple", "small_business": "moderate", "medium_business": "moderate", "enterprise": "complex" }
target_complexity = ideal_complexity.get(company_size, "moderate")
if template_complexity == target_complexity: return 1.0 elif abs(["simple", "moderate", "complex"].index(template_complexity) - ["simple", "moderate", "complex"].index(target_complexity)) == 1: return 0.7 else: return 0.3
async def _score_goals_alignment(self, template: Template, marketing_goals: List[str], primary_goal: str) -> float: """Score goals alignment.""" if not marketing_goals: return 0.5
template_features = self._extract_template_features(template)
# Score based on feature-goal alignment alignment_scores = [] for goal in marketing_goals: goal_features = self._get_goal_features(goal) common_features = set(template_features) & set(goal_features) alignment = len(common_features) / max(len(goal_features), 1) if goal_features else 0.5 alignment_scores.append(alignment)
return sum(alignment_scores) / len(alignment_scores)
async def _score_feature_coverage(self, template: Template, required_features: List[str]) -> float: """Score feature coverage.""" if not required_features: return 1.0
template_features = self._extract_template_features(template) covered_features = set(template_features) & set(required_features)
return len(covered_features) / len(required_features)
async def _score_style_compatibility(self, template: Template, preferred_style: str) -> float: """Score style compatibility.""" if not preferred_style: return 0.8 # Neutral score if no preference
template_style = self._analyze_template_style(template)
# Simple style matching - in production this would be more sophisticated if preferred_style.lower() in template_style.lower(): return 1.0 else: return 0.6
async def _score_technical_fit(self, template: Template, technical_expertise: str, integration_needs: List[str]) -> float: """Score technical fit.""" complexity = self._assess_template_complexity(template)
# Map expertise to complexity compatibility expertise_compatibility = { "beginner": {"simple": 1.0, "moderate": 0.6, "complex": 0.2}, "intermediate": {"simple": 0.8, "moderate": 1.0, "complex": 0.7}, "advanced": {"simple": 0.6, "moderate": 0.9, "complex": 1.0}, "expert": {"simple": 0.5, "moderate": 0.8, "complex": 1.0} }
expertise = technical_expertise or "beginner" return expertise_compatibility.get(expertise, {}).get(complexity, 0.5)
def _analyze_template_style(self, template: Template) -> str: """Analyze template style characteristics.""" # Placeholder implementation - would analyze actual template styles if template.category == "creative": return "modern creative" elif template.category == "corporate": return "professional corporate" elif template.category == "ecommerce": return "clean commercial" else: return "versatile business"
def _determine_template_industry_focus(self, template: Template) -> str: """Determine template's industry focus.""" category_mapping = { "portfolio": "creative", "ecommerce": "ecommerce", "corporate": "professional_services", "restaurant": "food_beverage", "fitness": "fitness_wellness", "education": "education" }
return category_mapping.get(template.category, "business")
async def _generate_suitability_explanation( self, template: Template, scores: Dict[str, float], overall_score: float ) -> str: """Generate human-readable explanation of suitability.""" explanations = []
if scores["industry_alignment"] >= 0.8: explanations.append("Excellent industry fit") elif scores["industry_alignment"] >= 0.6: explanations.append("Good industry compatibility")
if scores["feature_coverage"] >= 0.8: explanations.append("Covers most required features") elif scores["feature_coverage"] < 0.5: explanations.append("Missing some key features")
if scores["complexity_match"] >= 0.8: explanations.append("Appropriate complexity level")
if overall_score >= 0.8: recommendation = "Highly recommended" elif overall_score >= 0.6: recommendation = "Good fit with minor considerations" else: recommendation = "May require significant customization"
return f"{recommendation}. {'. '.join(explanations)}."
async def _identify_template_issues( self, template: Template, context: UserContext, requirements: BusinessRequirements, scores: Dict[str, float] ) -> List[str]: """Identify potential issues with template selection.""" issues = []
if scores["feature_coverage"] < 0.5: missing_features = set(requirements.required_features) - set(self._extract_template_features(template)) issues.append(f"Missing features: {', '.join(list(missing_features)[:3])}")
if scores["complexity_match"] < 0.5: issues.append("Template complexity may not match your needs")
if scores["technical_fit"] < 0.5: issues.append("May require technical expertise beyond your current level")
if context.budget_range in ["minimal", "low"] and template.premium: issues.append("Premium template may exceed budget constraints")
return issues
def _get_recommendation_level(self, score: float) -> str: """Get recommendation level based on score.""" if score >= 0.8: return "highly_recommended" elif score >= 0.6: return "recommended" elif score >= 0.4: return "consider_with_modifications" else: return "not_recommended"
def _get_recommended_complexity(self, company_size: str) -> str: """Get recommended complexity for company size.""" mapping = { "startup": "simple", "small_business": "moderate", "medium_business": "moderate", "enterprise": "complex" } return mapping.get(company_size, "moderate")
def _get_technical_complexity_recommendation(self, expertise_score: float) -> str: """Get technical complexity recommendation.""" if expertise_score >= 0.8: return "complex" elif expertise_score >= 0.5: return "moderate" else: return "simple"
def _get_budget_appropriate_features(self, budget_score: float) -> List[str]: """Get features appropriate for budget level.""" if budget_score >= 0.8: return ["premium_components", "advanced_integrations", "custom_animations"] elif budget_score >= 0.5: return ["standard_components", "basic_integrations", "responsive_design"] else: return ["essential_components", "basic_layout", "mobile_friendly"]

"""Domain management service for custom domain setup and SSL certificates."""

import asyncio
import dns.resolver
import ssl
import socket
from typing import Dict, Any, Optional, List
from datetime import datetime, timedelta
import requests
from cryptography import x509
from cryptography.x509.oid import NameOID
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa
import boto3
from botocore.exceptions import ClientError

from ..core.config import settings
from ..models.sites import PublishedSite, DomainStatus, SSLStatus


class DomainManager:
    """Handles custom domain configuration and SSL certificate management."""

    def __init__(self):
        # Cloudflare API client
        self.cloudflare_headers = {
            'Authorization': f'Bearer {settings.cloudflare_api_token}',
            'Content-Type': 'application/json'
        }

        # AWS Certificate Manager client
        self.acm_client = None
        if settings.aws_access_key_id and settings.aws_secret_access_key:
            self.acm_client = boto3.client(
                'acm',
                aws_access_key_id=settings.aws_access_key_id,
                aws_secret_access_key=settings.aws_secret_access_key,
                region_name=settings.aws_region
            )

    async def verify_domain_ownership(self, domain: str, site_id: str) -> Dict[str, Any]:
        """
        Verify domain ownership using DNS TXT record.

        Args:
            domain: Domain to verify
            site_id: Site ID for verification token

        Returns:
            Verification result
        """
        verification_token = f"aiwebbuilder-verify={site_id}"

        try:
            # Query DNS TXT records
            answers = dns.resolver.resolve(domain, 'TXT')

            for answer in answers:
                txt_record = str(answer).strip('"')
                if txt_record == verification_token:
                    return {
                        "status": DomainStatus.VERIFIED,
                        "verified_at": datetime.utcnow(),
                        "verification_method": "dns_txt"
                    }

            return {
                "status": DomainStatus.FAILED,
                "error": "Verification TXT record not found",
                "expected_record": verification_token
            }

        except Exception as e:
            return {
                "status": DomainStatus.DNS_ERROR,
                "error": str(e)
            }

    async def setup_dns_records(self, domain: str, target_url: str) -> Dict[str, Any]:
        """
        Setup DNS records for custom domain.

        Args:
            domain: Custom domain
            target_url: Target URL (CDN or load balancer)

        Returns:
            DNS setup result
        """
        if not settings.cloudflare_api_token:
            return {
                "status": "manual",
                "instructions": {
                    "record_type": "CNAME",
                    "name": domain,
                    "value": target_url,
                    "ttl": 300
                }
            }

        try:
            # Get zone ID for domain
            zone_id = await self._get_cloudflare_zone_id(domain)
            if not zone_id:
                return {
                    "status": "error",
                    "error": "Domain zone not found in Cloudflare"
                }

            # Create CNAME record
            response = requests.post(
                f'https://api.cloudflare.com/client/v4/zones/{zone_id}/dns_records',
                headers=self.cloudflare_headers,
                json={
                    'type': 'CNAME',
                    'name': domain,
                    'content': target_url,
                    'ttl': 300,
                    'proxied': True  # Enable Cloudflare proxy for security
                }
            )

            if response.status_code == 200:
                return {
                    "status": "success",
                    "record_id": response.json()['result']['id']
                }
            else:
                return {
                    "status": "error",
                    "error": response.json().get('errors', [])
                }

        except Exception as e:
            return {
                "status": "error",
                "error": str(e)
            }

    async def _get_cloudflare_zone_id(self, domain: str) -> Optional[str]:
        """Get Cloudflare zone ID for domain."""
        # Extract root domain
        domain_parts = domain.split('.')
        if len(domain_parts) >= 2:
            root_domain = '.'.join(domain_parts[-2:])
        else:
            root_domain = domain

        try:
            response = requests.get(
                f'https://api.cloudflare.com/client/v4/zones?name={root_domain}',
                headers=self.cloudflare_headers
            )

            if response.status_code == 200:
                zones = response.json()['result']
                if zones:
                    return zones[0]['id']

            return None

        except Exception:
            return None

    async def request_ssl_certificate(self, domain: str) -> Dict[str, Any]:
        """
        Request SSL certificate for domain.

        Args:
            domain: Domain for SSL certificate

        Returns:
            Certificate request result
        """
        if self.acm_client:
            return await self._request_acm_certificate(domain)
        else:
            return await self._request_letsencrypt_certificate(domain)

    async def _request_acm_certificate(self, domain: str) -> Dict[str, Any]:
        """Request certificate from AWS Certificate Manager."""
        try:
            response = self.acm_client.request_certificate(
                DomainName=domain,
                SubjectAlternativeNames=[f'www.{domain}'],
                ValidationMethod='DNS',
                Tags=[
                    {
                        'Key': 'Service',
                        'Value': 'AIWebBuilder'
                    }
                ]
            )

            certificate_arn = response['CertificateArn']

            # Get DNS validation records
            cert_details = self.acm_client.describe_certificate(
                CertificateArn=certificate_arn
            )

            validation_records = []
            for validation in cert_details['Certificate'].get('DomainValidationOptions', []):
                if 'ResourceRecord' in validation:
                    validation_records.append({
                        'name': validation['ResourceRecord']['Name'],
                        'type': validation['ResourceRecord']['Type'],
                        'value': validation['ResourceRecord']['Value']
                    })

            return {
                "status": SSLStatus.PENDING,
                "certificate_arn": certificate_arn,
                "validation_records": validation_records,
                "provider": "aws_acm"
            }

        except Exception as e:
            return {
                "status": SSLStatus.FAILED,
                "error": str(e)
            }

    async def _request_letsencrypt_certificate(self, domain: str) -> Dict[str, Any]:
        """Request certificate from Let's Encrypt."""
        # This would integrate with ACME client (like certbot)
        # For now, return a placeholder implementation

        return {
            "status": SSLStatus.PENDING,
            "provider": "letsencrypt",
            "challenge_type": "dns-01",
            "instructions": f"Create DNS TXT record _acme-challenge.{domain} with provided value"
        }

    async def check_ssl_status(self, published_site: PublishedSite) -> Dict[str, Any]:
        """
        Check SSL certificate status for published site.

        Args:
            published_site: PublishedSite instance

        Returns:
            SSL status information
        """
        domain = published_site.custom_domain or published_site.domain

        try:
            # Check SSL certificate via direct connection
            context = ssl.create_default_context()

            with socket.create_connection((domain, 443), timeout=10) as sock:
                with context.wrap_socket(sock, server_hostname=domain) as ssock:
                    cert_der = ssock.getpeercert_chain()[0]
                    cert = x509.load_der_x509_certificate(cert_der)

                    # Extract certificate information
                    subject = cert.subject
                    issuer = cert.issuer
                    not_after = cert.not_valid_after

                    # Get subject common name
                    common_name = None
                    for attribute in subject:
                        if attribute.oid == NameOID.COMMON_NAME:
                            common_name = attribute.value
                            break

                    # Get issuer organization
                    issuer_org = None
                    for attribute in issuer:
                        if attribute.oid == NameOID.ORGANIZATION_NAME:
                            issuer_org = attribute.value
                            break

                    # Check if certificate is valid and not expiring soon
                    now = datetime.utcnow()
                    days_until_expiry = (not_after - now).days

                    if days_until_expiry > 30:
                        status = SSLStatus.ACTIVE
                    elif days_until_expiry > 0:
                        status = SSLStatus.ACTIVE  # But needs renewal soon
                    else:
                        status = SSLStatus.EXPIRED

                    return {
                        "status": status,
                        "common_name": common_name,
                        "issuer": issuer_org,
                        "expires_at": not_after,
                        "days_until_expiry": days_until_expiry
                    }

        except Exception as e:
            return {
                "status": SSLStatus.FAILED,
                "error": str(e)
            }

    async def setup_domain_security(self, domain: str) -> Dict[str, Any]:
        """
        Setup domain security headers and policies.

        Args:
            domain: Domain to secure

        Returns:
            Security setup result
        """
        security_config = {
            "security_headers": {
                "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
                "X-Content-Type-Options": "nosniff",
                "X-Frame-Options": "DENY",
                "X-XSS-Protection": "1; mode=block",
                "Referrer-Policy": "strict-origin-when-cross-origin",
                "Content-Security-Policy": "default-src 'self'; script-src 'self' 'unsafe-inline' https://www.googletagmanager.com; style-src 'self' 'unsafe-inline'"
            },
            "ssl_redirect": True,
            "hsts_enabled": True
        }

        # Apply security configuration (would integrate with CDN/proxy)
        return {
            "status": "success",
            "security_config": security_config
        }

    async def validate_domain_configuration(self, domain: str) -> Dict[str, Any]:
        """
        Validate complete domain configuration.

        Args:
            domain: Domain to validate

        Returns:
            Validation results
        """
        results = {
            "domain": domain,
            "dns_resolution": False,
            "ssl_certificate": False,
            "security_headers": False,
            "performance_score": 0,
            "issues": []
        }

        try:
            # Test DNS resolution
            dns_result = await self._test_dns_resolution(domain)
            results["dns_resolution"] = dns_result["success"]
            if not dns_result["success"]:
                results["issues"].append(f"DNS resolution failed: {dns_result['error']}")

            # Test SSL certificate
            ssl_result = await self._test_ssl_certificate(domain)
            results["ssl_certificate"] = ssl_result["success"]
            if not ssl_result["success"]:
                results["issues"].append(f"SSL certificate issue: {ssl_result['error']}")

            # Test security headers
            security_result = await self._test_security_headers(domain)
            results["security_headers"] = security_result["success"]
            if not security_result["success"]:
                results["issues"].append(f"Security headers missing: {security_result['missing']}")

            # Calculate performance score
            results["performance_score"] = await self._calculate_performance_score(domain)

        except Exception as e:
            results["issues"].append(f"Validation error: {str(e)}")

        return results

    async def _test_dns_resolution(self, domain: str) -> Dict[str, Any]:
        """Test DNS resolution for domain."""
        try:
            answers = dns.resolver.resolve(domain, 'A')
            return {
                "success": True,
                "ip_addresses": [str(answer) for answer in answers]
            }
        except Exception as e:
            return {
                "success": False,
                "error": str(e)
            }

    async def _test_ssl_certificate(self, domain: str) -> Dict[str, Any]:
        """Test SSL certificate validity."""
        try:
            context = ssl.create_default_context()

            with socket.create_connection((domain, 443), timeout=10) as sock:
                with context.wrap_socket(sock, server_hostname=domain) as ssock:
                    return {"success": True}

        except Exception as e:
            return {
                "success": False,
                "error": str(e)
            }

    async def _test_security_headers(self, domain: str) -> Dict[str, Any]:
        """Test security headers presence."""
        required_headers = [
            'strict-transport-security',
            'x-content-type-options',
            'x-frame-options'
        ]

        try:
            response = requests.head(f'https://{domain}', timeout=10)
            present_headers = [h.lower() for h in response.headers.keys()]
            missing_headers = [h for h in required_headers if h not in present_headers]

            return {
                "success": len(missing_headers) == 0,
                "missing": missing_headers
            }

        except Exception as e:
            return {
                "success": False,
                "error": str(e)
            }

    async def _calculate_performance_score(self, domain: str) -> int:
        """Calculate basic performance score (0-100)."""
        try:
            # Simple performance test - measure response time
            start_time = datetime.utcnow()
            response = requests.get(f'https://{domain}', timeout=30)
            end_time = datetime.utcnow()

            response_time = (end_time - start_time).total_seconds()

            # Score based on response time
            if response_time < 1.0:
                return 100
            elif response_time < 2.0:
                return 90
            elif response_time < 3.0:
                return 80
            elif response_time < 5.0:
                return 70
            else:
                return 60

        except Exception:
            return 0

"""
Content Migration Pipeline
Handles HTML/CSS/JS extraction, optimization, and transformation
"""

import re
import json
import logging
from typing import Dict, List, Optional, Any, Tuple
from pathlib import Path
from bs4 import BeautifulSoup, Comment
import cssutils
from cssutils.css import CSSRule
import hashlib
from urllib.parse import urljoin, urlparse
from datetime import datetime

logger = logging.getLogger(__name__)

class ContentOptimizer:
    """Optimizes scraped content for template migration"""

    @staticmethod
    def optimize_html(content: str, base_url: str) -> Dict[str, Any]:
        """Optimize HTML content for template use"""

        soup = BeautifulSoup(content, 'html.parser')

        # Remove unnecessary elements
        ContentOptimizer._clean_html(soup)

        # Extract semantic structure
        structure = ContentOptimizer._extract_structure(soup)

        # Generate component mappings
        components = ContentOptimizer._identify_components(soup)

        # Optimize images
        ContentOptimizer._optimize_images(soup, base_url)

        # Extract inline styles for migration
        inline_styles = ContentOptimizer._extract_inline_styles(soup)

        return {
            'optimized_html': str(soup),
            'structure': structure,
            'components': components,
            'inline_styles': inline_styles,
            'metadata': {
                'word_count': len(soup.get_text(strip=True).split()),
                'image_count': len(soup.find_all('img')),
                'link_count': len(soup.find_all('a')),
                'heading_count': len(soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6']))
            }
        }

    @staticmethod
    def _clean_html(soup: BeautifulSoup):
        """Remove unnecessary elements from HTML"""

        # Remove comments
        comments = soup.find_all(string=lambda text: isinstance(text, Comment))
        for comment in comments:
            comment.extract()

        # Remove script tags (keep content for analysis)
        for script in soup.find_all('script'):
            script.decompose()

        # Remove style tags
        for style in soup.find_all('style'):
            style.decompose()

        # Remove empty elements
        for element in soup.find_all():
            if not element.get_text(strip=True) and not element.find_all():
                if element.name not in ['br', 'hr', 'img']:
                    element.decompose()

    @staticmethod
    def _extract_structure(soup: BeautifulSoup) -> Dict[str, Any]:
        """Extract semantic structure"""

        structure = {
            'header': None,
            'navigation': [],
            'main_content': None,
            'sidebar': [],
            'footer': None,
            'sections': []
        }

        # Find header
        header = soup.find('header') or soup.find(class_=re.compile('header', re.I))
        if header:
            structure['header'] = {
                'content': str(header),
                'text': header.get_text(strip=True),
                'logo': bool(header.find('img')) or bool(header.find(class_=re.compile('logo', re.I)))
            }

        # Find navigation
        nav_elements = soup.find_all('nav') + soup.find_all(class_=re.compile('nav|menu', re.I))
        for nav in nav_elements:
            structure['navigation'].append({
                'content': str(nav),
                'links': len(nav.find_all('a')),
                'type': 'horizontal' if len(nav.find_all('li')) > 1 else 'vertical'
            })

        # Find main content
        main = soup.find('main') or soup.find(id=re.compile('main|content', re.I)) or soup.find(class_=re.compile('main|content', re.I))
        if main:
            structure['main_content'] = {
                'content': str(main),
                'text': main.get_text(strip=True),
                'sections': len(main.find_all(['section', 'article']))
            }

        # Find footer
        footer = soup.find('footer') or soup.find(class_=re.compile('footer', re.I))
        if footer:
            structure['footer'] = {
                'content': str(footer),
                'text': footer.get_text(strip=True),
                'links': len(footer.find_all('a'))
            }

        return structure

    @staticmethod
    def _identify_components(soup: BeautifulSoup) -> List[Dict[str, Any]]:
        """Identify reusable components"""

        components = []

        # Identify common patterns
        patterns = [
            {'name': 'hero_section', 'selectors': ['.hero', '.banner', '.jumbotron']},
            {'name': 'card', 'selectors': ['.card', '.post', '.item', '.product']},
            {'name': 'button', 'selectors': ['.btn', '.button', 'button']},
            {'name': 'form', 'selectors': ['form', '.form', '.contact-form']},
            {'name': 'feature', 'selectors': ['.feature', '.service', '.benefit']},
            {'name': 'testimonial', 'selectors': ['.testimonial', '.review', '.quote']},
            {'name': 'team_member', 'selectors': ['.team', '.member', '.profile']},
            {'name': 'pricing_table', 'selectors': ['.pricing', '.price', '.plan']}
        ]

        for pattern in patterns:
            for selector in pattern['selectors']:
                elements = soup.select(selector)
                if elements:
                    for element in elements:
                        components.append({
                            'type': pattern['name'],
                            'selector': selector,
                            'content': str(element),
                            'text': element.get_text(strip=True),
                            'classes': element.get('class', [])
                        })

        return components

    @staticmethod
    def _optimize_images(soup: BeautifulSoup, base_url: str):
        """Optimize images for web use"""

        for img in soup.find_all('img'):
            src = img.get('src', '')
            if src and not src.startswith(('http://', 'https://', 'data:')):
                # Convert relative URLs to absolute
                img['src'] = urljoin(base_url, src)

            # Add loading attribute for performance
            if not img.get('loading'):
                img['loading'] = 'lazy'

            # Ensure alt text
            if not img.get('alt'):
                img['alt'] = 'Image'

    @staticmethod
    def _extract_inline_styles(soup: BeautifulSoup) -> List[Dict[str, str]]:
        """Extract inline styles for migration"""

        inline_styles = []

        for element in soup.find_all(style=True):
            inline_styles.append({
                'selector': element.name,
                'classes': element.get('class', []),
                'id': element.get('id', ''),
                'styles': element.get('style', '')
            })

        return inline_styles

class CSSProcessor:
    """Process and optimize CSS for template migration"""

    @staticmethod
    def process_css(css_content: str, base_url: str) -> Dict[str, Any]:
        """Process CSS content for template use"""

        try:
            sheet = cssutils.parseString(css_content)

            # Extract theme variables
            theme_data = CSSProcessor._extract_theme_variables(sheet)

            # Extract responsive breakpoints
            breakpoints = CSSProcessor._extract_breakpoints(sheet)

            # Extract component styles
            components = CSSProcessor._extract_component_styles(sheet)

            # Optimize CSS
            optimized_css = CSSProcessor._optimize_css(sheet, base_url)

            return {
                'theme': theme_data,
                'breakpoints': breakpoints,
                'components': components,
                'optimized_css': optimized_css,
                'metadata': {
                    'rules_count': len(sheet.cssRules),
                    'selectors_count': sum(1 for rule in sheet.cssRules if rule.type == CSSRule.STYLE_RULE),
                    'media_queries': len([r for r in sheet.cssRules if r.type == CSSRule.MEDIA_RULE])
                }
            }

        except Exception as e:
            logger.error(f"Error processing CSS: {e}")
            return {
                'theme': {},
                'breakpoints': {},
                'components': {},
                'optimized_css': css_content,
                'error': str(e)
            }

    @staticmethod
    def _extract_theme_variables(sheet) -> Dict[str, Any]:
        """Extract theme variables from CSS"""

        theme = {
            'colors': {},
            'fonts': {},
            'spacing': {},
            'border_radius': {},
            'shadows': {}
        }

        for rule in sheet.cssRules:
            if rule.type == CSSRule.STYLE_RULE:
                for prop in rule.style:
                    # Extract colors
                    if 'color' in prop.name or 'background' in prop.name:
                        value = prop.value.strip()
                        if value and value not in theme['colors']:
                            theme['colors'][value] = {
                                'usage': [prop.name],
                                'selectors': [rule.selectorText]
                            }

                    # Extract fonts
                    elif 'font-family' in prop.name:
                        fonts = prop.value.split(',')
                        for font in fonts:
                            font = font.strip().strip('"\'')
                            if font and font not in theme['fonts']:
                                theme['fonts'][font] = {
                                    'usage': [prop.name],
                                    'selectors': [rule.selectorText]
                                }

                    # Extract spacing
                    elif any(spacing in prop.name for spacing in ['margin', 'padding']):
                        value = prop.value.strip()
                        if value not in theme['spacing']:
                            theme['spacing'][value] = {
                                'property': prop.name,
                                'selectors': [rule.selectorText]
                            }

        return theme

    @staticmethod
    def _extract_breakpoints(sheet) -> Dict[str, str]:
        """Extract responsive breakpoints"""

        breakpoints = {}

        for rule in sheet.cssRules:
            if rule.type == CSSRule.MEDIA_RULE:
                media_query = rule.media.mediaText
                # Extract common breakpoint patterns
                if 'max-width' in media_query or 'min-width' in media_query:
                    breakpoints[media_query] = {
                        'rules': len(rule.cssRules),
                        'selectors': [r.selectorText for r in rule.cssRules if hasattr(r, 'selectorText')]
                    }

        return breakpoints

    @staticmethod
    def _extract_component_styles(sheet) -> Dict[str, Any]:
        """Extract component-specific styles"""

        components = {}

        # Define component patterns
        component_patterns = {
            'button': [r'\.btn', r'button', r'\.button'],
            'card': [r'\.card', r'\.post', r'\.item'],
            'navigation': [r'\.nav', r'\.navbar', r'\.menu'],
            'form': [r'\.form', r'input', r'\.input'],
            'hero': [r'\.hero', r'\.banner', r'\.jumbotron'],
            'footer': [r'\.footer', r'footer'],
            'header': [r'\.header', r'\.navbar', r'header']
        }

        for rule in sheet.cssRules:
            if rule.type == CSSRule.STYLE_RULE:
                selector = rule.selectorText

                for component, patterns in component_patterns.items():
                    for pattern in patterns:
                        if re.search(pattern, selector, re.IGNORECASE):
                            if component not in components:
                                components[component] = []

                            styles = {}
                            for prop in rule.style:
                                styles[prop.name] = prop.value

                            components[component].append({
                                'selector': selector,
                                'styles': styles
                            })

        return components

    @staticmethod
    def _optimize_css(sheet, base_url: str) -> str:
        """Optimize CSS for template use"""

        optimized_rules = []

        for rule in sheet.cssRules:
            if rule.type == CSSRule.STYLE_RULE:
                # Remove vendor prefixes that are no longer needed
                styles = {}
                for prop in rule.style:
                    if not prop.name.startswith('-webkit-') and not prop.name.startswith('-moz-'):
                        styles[prop.name] = prop.value

                # Update URLs in CSS
                updated_styles = CSSProcessor._update_css_urls(styles, base_url)

                # Rebuild rule
                rule.style.cssText = '; '.join(f"{k}: {v}" for k, v in updated_styles.items())
                optimized_rules.append(rule.cssText)
            else:
                optimized_rules.append(rule.cssText)

        return '\n'.join(optimized_rules)

    @staticmethod
    def _update_css_urls(styles: Dict[str, str], base_url: str) -> Dict[str, str]:
        """Update relative URLs in CSS to absolute"""

        updated_styles = {}

        for prop, value in styles.items():
            if 'url(' in value:
                # Extract and update URLs
                urls = re.findall(r'url\(["\']?([^"\')]+)["\']?\)', value)
                for url in urls:
                    if not url.startswith(('http://', 'https://', 'data:')):
                        new_url = urljoin(base_url, url)
                        value = value.replace(url, new_url)

            updated_styles[prop] = value

        return updated_styles

class MigrationPipeline:
    """Main pipeline for content migration"""

    def __init__(self):
        self.optimizer = ContentOptimizer()
        self.css_processor = CSSProcessor()
        self.migration_steps = []

    async def process_website(self, scraped_data: Dict[str, Any]) -> Dict[str, Any]:
        """Process entire website for migration"""

        migration_data = {
            'original_data': scraped_data,
            'processed_pages': {},
            'processed_styles': {},
            'processed_scripts': {},
            'migration_plan': {},
            'recommendations': [],
            'warnings': []
        }

        # Process each page
        for url, page_data in scraped_data.get('pages', {}).items():
            try:
                processed_page = await self._process_page(page_data, scraped_data.get('base_url', ''))
                migration_data['processed_pages'][url] = processed_page
            except Exception as e:
                migration_data['warnings'].append(f"Failed to process page {url}: {str(e)}")

        # Process CSS
        for css_url, css_data in scraped_data.get('styles', {}).items():
            try:
                processed_css = self.css_processor.process_css(
                    css_data.get('content', ''),
                    scraped_data.get('base_url', '')
                )
                migration_data['processed_styles'][css_url] = processed_css
            except Exception as e:
                migration_data['warnings'].append(f"Failed to process CSS {css_url}: {str(e)}")

        # Generate migration plan
        migration_data['migration_plan'] = await self._generate_migration_plan(migration_data)

        # Generate recommendations
        migration_data['recommendations'] = await self._generate_recommendations(migration_data)

        return migration_data

    async def _process_page(self, page_data: Dict[str, Any], base_url: str) -> Dict[str, Any]:
        """Process individual page"""

        html_content = page_data.get('content', {}).get('html', '')

        if html_content:
            optimized = self.optimizer.optimize_html(html_content, base_url)
            return {
                'original': page_data,
                'optimized': optimized,
                'migration_priority': self._calculate_priority(page_data),
                'estimated_effort': self._estimate_effort(optimized)
            }

        return {'error': 'No HTML content found'}

    def _calculate_priority(self, page_data: Dict[str, Any]) -> str:
        """Calculate migration priority for page"""

        url = page_data.get('url', '')
        title = page_data.get('title', '').lower()

        # High priority pages
        if any(keyword in url.lower() or keyword in title for keyword in ['index', 'home', 'landing', 'main']):
            return 'high'

        # Medium priority pages
        if any(keyword in url.lower() or keyword in title for keyword in ['about', 'contact', 'services', 'products']):
            return 'medium'

        # Low priority pages
        return 'low'

    def _estimate_effort(self, optimized_data: Dict[str, Any]) -> str:
        """Estimate migration effort for page"""

        metadata = optimized_data.get('metadata', {})

        word_count = metadata.get('word_count', 0)
        image_count = metadata.get('image_count', 0)
        component_count = len(optimized_data.get('components', []))

        if word_count > 1000 or image_count > 10 or component_count > 10:
            return 'high'
        elif word_count > 500 or image_count > 5 or component_count > 5:
            return 'medium'
        else:
            return 'low'

    async def _generate_migration_plan(self, migration_data: Dict[str, Any]) -> Dict[str, Any]:
        """Generate detailed migration plan"""

        plan = {
            'phases': [
                {
                    'name': 'Setup and Planning',
                    'duration': '30 minutes',
                    'tasks': [
                        'Create new template structure',
                        'Set up development environment',
                        'Review scraped content'
                    ]
                },
                {
                    'name': 'Content Migration',
                    'duration': '2-4 hours',
                    'tasks': [
                        'Migrate high priority pages',
                        'Extract and migrate components',
                        'Optimize images and assets'
                    ]
                },
                {
                    'name': 'Styling and Layout',
                    'duration': '1-2 hours',
                    'tasks': [
                        'Migrate CSS styles',
                        'Implement responsive design',
                        'Apply theme variables'
                    ]
                },
                {
                    'name': 'Testing and Deployment',
                    'duration': '1 hour',
                    'tasks': [
                        'Test across devices',
                        'SEO optimization',
                        'Deploy to production'
                    ]
                }
            ],
            'total_estimated_time': '4.5-8.5 hours',
            'risk_level': 'medium'
        }

        return plan

    async def _generate_recommendations(self, migration_data: Dict[str, Any]) -> List[str]:
        """Generate migration recommendations"""

        recommendations = []

        # Analyze theme
        themes = []
        for css_data in migration_data.get('processed_styles', {}).values():
            theme = css_data.get('theme', {})
            if theme.get('colors'):
                themes.append(theme)

        if themes:
            recommendations.append("Extract common color scheme for consistent branding")

        # Analyze components
        components = []
        for page_data in migration_data.get('processed_pages', {}).values():
            page_components = page_data.get('optimized', {}).get('components', [])
            components.extend(page_components)

        if components:
            recommendations.append("Create reusable component library based on extracted patterns")

        # Analyze images
        image_count = 0
        for page_data in migration_data.get('processed_pages', {}).values():
            metadata = page_data.get('optimized', {}).get('metadata', {})
            image_count += metadata.get('image_count', 0)

        if image_count > 20:
            recommendations.append("Consider implementing image optimization and lazy loading")

        # General recommendations
        recommendations.extend([
            "Test migrated site on multiple devices and browsers",
            "Set up proper redirects to maintain SEO rankings",
            "Monitor site performance after migration",
            "Create backup plan for rollback if issues occur"
        ])

        return recommendations

"""
Rollback System for Template Migration
Provides comprehensive rollback capabilities and error recovery
"""

import json
import shutil
import logging
from typing import Dict, List, Optional, Any
from pathlib import Path
from datetime import datetime
import os
import tempfile

logger = logging.getLogger(__name__)

class RollbackPoint:
    """Represents a rollback point in the migration process"""

    def __init__(self, migration_id: str, step: str, data: Dict[str, Any]):
        self.migration_id = migration_id
        self.step = step
        self.timestamp = datetime.utcnow().isoformat()
        self.data = data
        self.checksum = self._calculate_checksum(data)

    def _calculate_checksum(self, data: Dict[str, Any]) -> str:
        """Calculate checksum for data integrity"""
        import hashlib
        data_str = json.dumps(data, sort_keys=True)
        return hashlib.md5(data_str.encode()).hexdigest()

class RollbackManager:
    """Manages rollback operations for template migration"""

    def __init__(self, storage_path: str = "/tmp/migration_rollback"):
        self.storage_path = Path(storage_path)
        self.storage_path.mkdir(parents=True, exist_ok=True)
        self.rollback_points = []
        self.current_migration = None

    def create_rollback_point(self, migration_id: str, step: str, 
                            data: Dict[str, Any]) -> str:
        """Create a new rollback point"""

        rollback_point = RollbackPoint(migration_id, step, data)

        # Create rollback directory for this migration
        migration_dir = self.storage_path / migration_id
        migration_dir.mkdir(exist_ok=True)

        # Save rollback point
        rollback_file = migration_dir / f"{step}_{rollback_point.timestamp}.json"
        with open(rollback_file, 'w') as f:
            json.dump({
                'migration_id': rollback_point.migration_id,
                'step': rollback_point.step,
                'timestamp': rollback_point.timestamp,
                'data': rollback_point.data,
                'checksum': rollback_point.checksum
            }, f, indent=2)

        # Create backup of critical files
        self._create_file_backup(migration_id, step, data)

        logger.info(f"Rollback point created: {migration_id}/{step}")
        return str(rollback_file)

    def _create_file_backup(self, migration_id: str, step: str, data: Dict[str, Any]):
        """Create backup of critical files"""

        backup_dir = self.storage_path / migration_id / "backups" / step
        backup_dir.mkdir(parents=True, exist_ok=True)

        # Backup templates if they exist
        if 'templates' in data:
            templates_backup = backup_dir / "templates"
            templates_backup.mkdir(exist_ok=True)

            for template_name, template_content in data['templates'].items():
                template_file = templates_backup / f"{template_name}.html"
                with open(template_file, 'w', encoding='utf-8') as f:
                    f.write(template_content)

        # Backup CSS files
        if 'styles' in data:
            styles_backup = backup_dir / "styles"
            styles_backup.mkdir(exist_ok=True)

            for style_name, style_content in data['styles'].items():
                style_file = styles_backup / f"{style_name}.css"
                with open(style_file, 'w', encoding='utf-8') as f:
                    f.write(style_content)

    def rollback_to_step(self, migration_id: str, step: str) -> Dict[str, Any]:
        """Rollback to a specific step"""

        try:
            migration_dir = self.storage_path / migration_id

            # Find rollback point
            rollback_files = list(migration_dir.glob(f"{step}_*.json"))
            if not rollback_files:
                raise ValueError(f"No rollback point found for step: {step}")

            # Get the latest rollback point for this step
            rollback_file = max(rollback_files, key=lambda x: x.stat().st_mtime)

            # Load rollback data
            with open(rollback_file, 'r') as f:
                rollback_data = json.load(f)

            # Verify checksum
            if not self._verify_checksum(rollback_data):
                raise ValueError("Rollback data integrity check failed")

            # Perform rollback
            restored_data = self._perform_rollback(migration_id, rollback_data)

            logger.info(f"Rollback completed: {migration_id} -> {step}")

            return {
                'success': True,
                'migration_id': migration_id,
                'step': step,
                'restored_data': restored_data,
                'timestamp': datetime.utcnow().isoformat()
            }

        except Exception as e:
            logger.error(f"Rollback failed: {e}")
            return {
                'success': False,
                'error': str(e),
                'migration_id': migration_id,
                'step': step
            }

    def rollback_to_previous(self, migration_id: str) -> Dict[str, Any]:
        """Rollback to the previous step"""

        try:
            migration_dir = self.storage_path / migration_id
            rollback_files = list(migration_dir.glob("*.json"))

            if len(rollback_files) < 2:
                raise ValueError("No previous rollback point available")

            # Sort by timestamp (descending)
            rollback_files.sort(key=lambda x: x.stat().st_mtime, reverse=True)

            # Get the second latest (previous step)
            previous_file = rollback_files[1]

            # Extract step name from filename
            step_name = previous_file.stem.split('_')[0]

            return self.rollback_to_step(migration_id, step_name)

        except Exception as e:
            logger.error(f"Rollback to previous failed: {e}")
            return {
                'success': False,
                'error': str(e),
                'migration_id': migration_id
            }

    def complete_rollback(self, migration_id: str) -> Dict[str, Any]:
        """Complete rollback to initial state"""

        try:
            migration_dir = self.storage_path / migration_id

            # Find initial rollback point
            initial_files = list(migration_dir.glob("initial_*.json"))
            if not initial_files:
                raise ValueError("No initial rollback point found")

            initial_file = max(initial_files, key=lambda x: x.stat().st_mtime)

            with open(initial_file, 'r') as f:
                initial_data = json.load(f)

            # Verify checksum
            if not self._verify_checksum(initial_data):
                raise ValueError("Initial data integrity check failed")

            # Perform complete rollback
            restored_data = self._perform_rollback(migration_id, initial_data)

            # Clean up rollback files
            self._cleanup_rollback_files(migration_id)

            logger.info(f"Complete rollback completed: {migration_id}")

            return {
                'success': True,
                'migration_id': migration_id,
                'step': 'initial',
                'restored_data': restored_data,
                'timestamp': datetime.utcnow().isoformat()
            }

        except Exception as e:
            logger.error(f"Complete rollback failed: {e}")
            return {
                'success': False,
                'error': str(e),
                'migration_id': migration_id
            }

    def _verify_checksum(self, data: Dict[str, Any]) -> bool:
        """Verify data integrity using checksum"""

        try:
            stored_checksum = data.get('checksum')
            if not stored_checksum:
                return False

            import hashlib
            calculated_checksum = hashlib.md5(
                json.dumps(data['data'], sort_keys=True).encode()
            ).hexdigest()

            return stored_checksum == calculated_checksum

        except Exception:
            return False

    def _perform_rollback(self, migration_id: str, rollback_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform the actual rollback operations"""

        restored_data = {}

        # Restore templates
        if 'templates' in rollback_data['data']:
            restored_data['templates'] = rollback_data['data']['templates']

        # Restore styles
        if 'styles' in rollback_data['data']:
            restored_data['styles'] = rollback_data['data']['styles']

        # Restore configuration
        if 'config' in rollback_data['data']:
            restored_data['config'] = rollback_data['data']['config']

        return restored_data

    def _cleanup_rollback_files(self, migration_id: str):
        """Clean up rollback files for a migration"""

        migration_dir = self.storage_path / migration_id
        if migration_dir.exists():
            shutil.rmtree(migration_dir)

    def get_rollback_history(self, migration_id: str) -> List[Dict[str, Any]]:
        """Get rollback history for a migration"""

        try:
            migration_dir = self.storage_path / migration_id
            rollback_files = list(migration_dir.glob("*.json"))

            history = []
            for file in rollback_files:
                with open(file, 'r') as f:
                    data = json.load(f)
                    history.append({
                        'step': data['step'],
                        'timestamp': data['timestamp'],
                        'migration_id': data['migration_id']
                    })

            return sorted(history, key=lambda x: x['timestamp'])

        except Exception as e:
            logger.error(f"Failed to get rollback history: {e}")
            return []

    def get_migration_status(self, migration_id: str) -> Dict[str, Any]:
        """Get current migration status including rollback points"""

        try:
            history = self.get_rollback_history(migration_id)

            if not history:
                return {
                    'migration_id': migration_id,
                    'status': 'no_data',
                    'rollback_points': 0,
                    'current_step': None,
                    'can_rollback': False
                }

            current_step = history[-1]['step']

            return {
                'migration_id': migration_id,
                'status': 'active',
                'rollback_points': len(history),
                'current_step': current_step,
                'can_rollback': len(history) > 1,
                'history': history
            }

        except Exception as e:
            logger.error(f"Failed to get migration status: {e}")
            return {
                'migration_id': migration_id,
                'status': 'error',
                'error': str(e)
            }

    def schedule_cleanup(self, max_age_days: int = 7):
        """Schedule cleanup of old rollback files"""

        try:
            cutoff_date = datetime.utcnow().timestamp() - (max_age_days * 24 * 60 * 60)

            for migration_dir in self.storage_path.iterdir():
                if migration_dir.is_dir():
                    # Check if directory is older than cutoff
                    dir_mtime = migration_dir.stat().st_mtime
                    if dir_mtime < cutoff_date:
                        shutil.rmtree(migration_dir)
                        logger.info(f"Cleaned up old rollback data: {migration_dir.name}")

        except Exception as e:
            logger.error(f"Cleanup failed: {e}")

    def export_rollback_data(self, migration_id: str, export_path: str) -> bool:
        """Export rollback data for backup"""

        try:
            migration_dir = self.storage_path / migration_id
            if not migration_dir.exists():
                return False

            export_file = Path(export_path) / f"rollback_{migration_id}_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.zip"
            export_file.parent.mkdir(parents=True, exist_ok=True)

            shutil.make_archive(
                str(export_file.with_suffix('')),
                'zip',
                str(migration_dir)
            )

            return True

        except Exception as e:
            logger.error(f"Export failed: {e}")
            return False

class ErrorRecovery:
    """Handles error recovery during migration"""

    def __init__(self):
        self.error_log = []
        self.recovery_strategies = {
            'network_error': self._handle_network_error,
            'parsing_error': self._handle_parsing_error,
            'validation_error': self._handle_validation_error,
            'storage_error': self._handle_storage_error
        }

    def log_error(self, error_type: str, error_details: Dict[str, Any]):
        """Log error for recovery analysis"""

        error_record = {
            'timestamp': datetime.utcnow().isoformat(),
            'type': error_type,
            'details': error_details,
            'recovery_attempted': False,
            'recovery_successful': False
        }

        self.error_log.append(error_record)
        logger.error(f"Migration error: {error_type} - {error_details}")

    def recover_from_error(self, error_type: str, context: Dict[str, Any]) -> Dict[str, Any]:
        """Attempt to recover from a specific error"""

        if error_type in self.recovery_strategies:
            return self.recovery_strategies[error_type](context)

        return {
            'success': False,
            'error': f"No recovery strategy for error type: {error_type}",
            'fallback_action': 'manual_intervention_required'
        }

    def _handle_network_error(self, context: Dict[str, Any]) -> Dict[str, Any]:
        """Handle network-related errors"""

        return {
            'success': True,
            'action': 'retry_with_backoff',
            'retry_count': 3,
            'backoff_multiplier': 2,
            'fallback_action': 'skip_resource'
        }

    def _handle_parsing_error(self, context: Dict[str, Any]) -> Dict[str, Any]:
        """Handle content parsing errors"""

        return {
            'success': True,
            'action': 'use_fallback_parser',
            'fallback_parser': 'html5lib',
            'preserve_content': True,
            'mark_as_review_required': True
        }

    def _handle_validation_error(self, context: Dict[str, Any]) -> Dict[str, Any]:
        """Handle data validation errors"""

        return {
            'success': True,
            'action': 'apply_fixes',
            'auto_fixes': [
                'remove_invalid_characters',
                'normalize_urls',
                'validate_html_structure'
            ],
            'fallback_action': 'manual_review'
        }

    def _handle_storage_error(self, context: Dict[str, Any]) -> Dict[str, Any]:
        """Handle storage-related errors"""

        return {
            'success': True,
            'action': 'switch_storage',
            'fallback_storage': '/tmp/emergency_backup',
            'preserve_data': True,
            'notify_admin': True
        }

    def get_error_summary(self) -> Dict[str, Any]:
        """Get summary of all errors and recovery attempts"""

        if not self.error_log:
            return {
                'total_errors': 0,
                'recovery_rate': 100,
                'error_types': {},
                'recommendations': ['No errors found']
            }

        error_types = {}
        for error in self.error_log:
            error_type = error['type']
            error_types[error_type] = error_types.get(error_type, 0) + 1

        recovered_count = sum(1 for e in self.error_log if e['recovery_successful'])
        recovery_rate = (recovered_count / len(self.error_log)) * 100

        return {
            'total_errors': len(self.error_log),
            'recovery_rate': recovery_rate,
            'error_types': error_types,
            'recommendations': [
                f"Review {error_types.get('validation_error', 0)} validation errors",
                f"Check network configuration for {error_types.get('network_error', 0)} network errors",
                f"Review storage capacity for {error_types.get('storage_error', 0)} storage errors"
            ]
        }

"""
Website Scraping Service for Template Migration
Provides robust scraping with error handling and content extraction
"""

import asyncio
import aiohttp
import re
import json
import logging
from typing import Dict, List, Optional, Any
from urllib.parse import urljoin, urlparse, parse_qs
from bs4 import BeautifulSoup
import cssutils
from pathlib import Path
import hashlib
from datetime import datetime

logger = logging.getLogger(__name__)

class ScrapingError(Exception):
    """Custom exception for scraping errors"""
    pass

class WebsiteScraper:
    """Advanced website scraper for template migration"""

    def __init__(self, max_concurrent=10, timeout=30):
        self.max_concurrent = max_concurrent
        self.timeout = timeout
        self.session = None
        self.visited_urls = set()
        self.scraped_content = {}
        self.error_log = []

    async def __aenter__(self):
        """Async context manager entry"""
        connector = aiohttp.TCPConnector(limit=self.max_concurrent, limit_per_host=5)
        timeout = aiohttp.ClientTimeout(total=self.timeout)
        self.session = aiohttp.ClientSession(
            connector=connector,
            timeout=timeout,
            headers={
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
            }
        )
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        """Async context manager exit"""
        if self.session:
            await self.session.close()

    async def scrape_website(self, url: str, depth: int = 3) -> Dict[str, Any]:
        """
        Main scraping method - scrapes entire website structure

        Args:
            url: Base URL to scrape
            depth: Maximum crawl depth

        Returns:
            Dict containing scraped content and metadata
        """
        try:
            if not self.session:
                raise ScrapingError("Scraper not initialized. Use async context manager.")

            base_url = self._normalize_url(url)
            logger.info(f"Starting scrape of {base_url} with depth {depth}")

            # Initialize scraping state
            self.visited_urls.clear()
            self.scraped_content = {
                'base_url': base_url,
                'pages': {},
                'assets': {},
                'styles': {},
                'scripts': {},
                'metadata': {
                    'start_time': datetime.utcnow().isoformat(),
                    'total_pages': 0,
                    'total_assets': 0,
                    'errors': []
                }
            }

            # Start recursive scraping
            await self._crawl_page(base_url, depth)

            # Process and optimize content
            await self._process_content()

            self.scraped_content['metadata'].update({
                'end_time': datetime.utcnow().isoformat(),
                'total_pages': len(self.scraped_content['pages']),
                'total_assets': len(self.scraped_content['assets']),
                'errors': self.error_log
            })

            return self.scraped_content

        except Exception as e:
            logger.error(f"Failed to scrape website: {str(e)}")
            raise ScrapingError(f"Website scraping failed: {str(e)}")

    async def _crawl_page(self, url: str, depth: int):
        """Recursively crawl pages"""
        if depth <= 0 or url in self.visited_urls:
            return

        self.visited_urls.add(url)

        try:
            content = await self._fetch_page(url)
            if not content:
                return

            soup = BeautifulSoup(content, 'html.parser')

            # Extract page content
            page_data = await self._extract_page_content(url, soup)
            self.scraped_content['pages'][url] = page_data

            # Extract assets
            await self._extract_assets(url, soup)

            # Find and crawl internal links
            if depth > 1:
                links = self._extract_internal_links(url, soup)
                tasks = [self._crawl_page(link, depth - 1) for link in links]
                await asyncio.gather(*tasks, return_exceptions=True)

        except Exception as e:
            error_msg = f"Error crawling {url}: {str(e)}"
            logger.error(error_msg)
            self.error_log.append(error_msg)

    async def _fetch_page(self, url: str) -> Optional[str]:
        """Fetch page content with retries"""
        max_retries = 3

        for attempt in range(max_retries):
            try:
                async with self.session.get(url) as response:
                    if response.status == 200:
                        content_type = response.headers.get('content-type', '')
                        if 'text/html' in content_type:
                            return await response.text()
                        else:
                            logger.warning(f"Skipping non-HTML content at {url}")
                            return None
                    else:
                        logger.warning(f"HTTP {response.status} for {url}")

            except asyncio.TimeoutError:
                logger.warning(f"Timeout fetching {url} (attempt {attempt + 1})")
            except Exception as e:
                logger.error(f"Error fetching {url}: {str(e)}")

        return None

    async def _extract_page_content(self, url: str, soup: BeautifulSoup) -> Dict[str, Any]:
        """Extract structured content from HTML page"""

        # Remove script and style tags for cleaner content
        for script in soup(["script", "style"]):
            script.decompose()

        # Extract metadata
        title = soup.find('title')
        meta_description = soup.find('meta', attrs={'name': 'description'})
        meta_keywords = soup.find('meta', attrs={'name': 'keywords'})

        # Extract structured content
        content = {
            'url': url,
            'title': title.string if title else '',
            'meta': {
                'description': meta_description.get('content', '') if meta_description else '',
                'keywords': meta_keywords.get('content', '') if meta_keywords else '',
                'canonical': self._extract_canonical_url(soup, url)
            },
            'structure': {
                'h1': [h.get_text(strip=True) for h in soup.find_all('h1')],
                'h2': [h.get_text(strip=True) for h in soup.find_all('h2')],
                'h3': [h.get_text(strip=True) for h in soup.find_all('h3')],
                'images': self._extract_images(soup, url),
                'links': self._extract_link_structure(soup, url),
                'forms': self._extract_forms(soup),
            },
            'content': {
                'text': soup.get_text(strip=True, separator='\n'),
                'html': str(soup.body) if soup.body else str(soup),
                'selectors': self._generate_selectors(soup)
            },
            'seo': {
                'og_tags': self._extract_og_tags(soup),
                'twitter_tags': self._extract_twitter_tags(soup),
                'schema_markup': self._extract_schema_markup(soup)
            }
        }

        return content

    async def _extract_assets(self, base_url: str, soup: BeautifulSoup):
        """Extract CSS, JS, and image assets"""

        # Extract CSS
        for link in soup.find_all('link', rel='stylesheet'):
            css_url = urljoin(base_url, link.get('href', ''))
            if css_url not in self.scraped_content['styles']:
                try:
                    async with self.session.get(css_url) as response:
                        if response.status == 200:
                            css_content = await response.text()
                            self.scraped_content['styles'][css_url] = {
                                'content': css_content,
                                'url': css_url,
                                'type': 'external'
                            }
                except Exception as e:
                    logger.error(f"Failed to fetch CSS {css_url}: {e}")

        # Extract inline CSS
        for style in soup.find_all('style'):
            style_hash = hashlib.md5(style.get_text().encode()).hexdigest()
            self.scraped_content['styles'][f'inline_{style_hash}'] = {
                'content': style.get_text(),
                'url': base_url,
                'type': 'inline'
            }

        # Extract JavaScript
        for script in soup.find_all('script', src=True):
            js_url = urljoin(base_url, script.get('src'))
            if js_url not in self.scraped_content['scripts']:
                try:
                    async with self.session.get(js_url) as response:
                        if response.status == 200:
                            js_content = await response.text()
                            self.scraped_content['scripts'][js_url] = {
                                'content': js_content,
                                'url': js_url,
                                'type': 'external'
                            }
                except Exception as e:
                    logger.error(f"Failed to fetch JS {js_url}: {e}")

        # Extract inline JavaScript
        for script in soup.find_all('script', src=None):
            if script.get_text().strip():
                script_hash = hashlib.md5(script.get_text().encode()).hexdigest()
                self.scraped_content['scripts'][f'inline_{script_hash}'] = {
                    'content': script.get_text(),
                    'url': base_url,
                    'type': 'inline'
                }

        # Extract images and other assets
        for img in soup.find_all('img'):
            img_url = urljoin(base_url, img.get('src', ''))
            if img_url not in self.scraped_content['assets']:
                self.scraped_content['assets'][img_url] = {
                    'type': 'image',
                    'alt': img.get('alt', ''),
                    'url': img_url
                }

    def _extract_internal_links(self, base_url: str, soup: BeautifulSoup) -> List[str]:
        """Extract internal links for crawling"""
        base_domain = urlparse(base_url).netloc
        links = []

        for link in soup.find_all('a', href=True):
            href = link.get('href')
            full_url = urljoin(base_url, href)
            parsed = urlparse(full_url)

            # Only include internal links
            if parsed.netloc == base_domain and full_url not in self.visited_urls:
                # Skip common non-content URLs
                if not any(skip in full_url.lower() for skip in [
                    '.pdf', '.zip', '.exe', '.mp4', '.mp3',
                    'mailto:', 'tel:', 'javascript:', '#'
                ]):
                    links.append(full_url)

        return list(set(links))[:20]  # Limit to prevent excessive crawling

    def _extract_images(self, soup: BeautifulSoup, base_url: str) -> List[Dict[str, str]]:
        """Extract image information"""
        images = []
        for img in soup.find_all('img'):
            src = urljoin(base_url, img.get('src', ''))
            images.append({
                'src': src,
                'alt': img.get('alt', ''),
                'width': img.get('width', ''),
                'height': img.get('height', ''),
                'class': img.get('class', [])
            })
        return images

    def _extract_link_structure(self, soup: BeautifulSoup, base_url: str) -> List[Dict[str, str]]:
        """Extract link structure"""
        links = []
        for link in soup.find_all('a', href=True):
            links.append({
                'text': link.get_text(strip=True),
                'href': urljoin(base_url, link.get('href')),
                'title': link.get('title', ''),
                'rel': link.get('rel', [])
            })
        return links

    def _extract_forms(self, soup: BeautifulSoup) -> List[Dict[str, Any]]:
        """Extract form structure"""
        forms = []
        for form in soup.find_all('form'):
            form_data = {
                'action': form.get('action', ''),
                'method': form.get('method', 'get'),
                'inputs': []
            }

            for input_tag in form.find_all(['input', 'textarea', 'select']):
                input_data = {
                    'type': input_tag.get('type', input_tag.name),
                    'name': input_tag.get('name', ''),
                    'id': input_tag.get('id', ''),
                    'placeholder': input_tag.get('placeholder', ''),
                    'required': input_tag.get('required') is not None
                }
                form_data['inputs'].append(input_data)

            forms.append(form_data)
        return forms

    def _extract_og_tags(self, soup: BeautifulSoup) -> Dict[str, str]:
        """Extract Open Graph tags"""
        og_tags = {}
        for tag in soup.find_all('meta', property=re.compile(r'^og:')):
            prop = tag.get('property', '').replace('og:', '')
            content = tag.get('content', '')
            og_tags[prop] = content
        return og_tags

    def _extract_twitter_tags(self, soup: BeautifulSoup) -> Dict[str, str]:
        """Extract Twitter card tags"""
        twitter_tags = {}
        for tag in soup.find_all('meta', attrs={'name': re.compile(r'^twitter:')}):
            name = tag.get('name', '').replace('twitter:', '')
            content = tag.get('content', '')
            twitter_tags[name] = content
        return twitter_tags

    def _extract_schema_markup(self, soup: BeautifulSoup) -> List[Dict[str, Any]]:
        """Extract JSON-LD schema markup"""
        schemas = []
        for script in soup.find_all('script', type='application/ld+json'):
            try:
                schema_data = json.loads(script.string)
                schemas.append(schema_data)
            except json.JSONDecodeError:
                logger.warning("Invalid JSON-LD schema found")
        return schemas

    def _extract_canonical_url(self, soup: BeautifulSoup, current_url: str) -> str:
        """Extract canonical URL"""
        canonical = soup.find('link', rel='canonical')
        if canonical and canonical.get('href'):
            return urljoin(current_url, canonical.get('href'))
        return current_url

    def _generate_selectors(self, soup: BeautifulSoup) -> Dict[str, List[str]]:
        """Generate CSS selectors for common elements"""
        selectors = {
            'headers': [],
            'navigation': [],
            'content': [],
            'sidebar': [],
            'footer': []
        }

        # Common selectors for different sections
        nav_selectors = ['nav', '.nav', '.navbar', '.navigation', '#nav', '#navigation']
        for selector in nav_selectors:
            elements = soup.select(selector)
            if elements:
                selectors['navigation'].append(selector)

        content_selectors = ['main', '.main', '.content', '#content', '.container', '#main']
        for selector in content_selectors:
            elements = soup.select(selector)
            if elements:
                selectors['content'].append(selector)

        return selectors

    def _normalize_url(self, url: str) -> str:
        """Normalize URL format"""
        if not url.startswith(('http://', 'https://')):
            url = 'https://' + url
        return url.rstrip('/')

    async def _process_content(self):
        """Post-process scraped content for optimization"""
        # Analyze CSS for theme extraction
        await self._extract_themes_from_css()

        # Generate asset manifest
        self._generate_asset_manifest()

        # Detect common patterns
        self._detect_layout_patterns()

    async def _extract_themes_from_css(self):
        """Extract theme information from CSS"""
        themes = {
            'colors': {},
            'fonts': {},
            'spacing': {},
            'breakpoints': {}
        }

        for css_url, css_data in self.scraped_content['styles'].items():
            try:
                sheet = cssutils.parseString(css_data['content'])

                for rule in sheet:
                    if rule.type == rule.STYLE_RULE:
                        for prop in rule.style:
                            if 'color' in prop.name:
                                themes['colors'][prop.value] = themes['colors'].get(prop.value, 0) + 1
                            elif 'font-family' in prop.name:
                                themes['fonts'][prop.value] = themes['fonts'].get(prop.value, 0) + 1
                            elif 'margin' in prop.name or 'padding' in prop.name:
                                themes['spacing'][prop.value] = themes['spacing'].get(prop.value, 0) + 1
                            elif 'max-width' in prop.name and 'px' in prop.value:
                                themes['breakpoints'][prop.value] = themes['breakpoints'].get(prop.value, 0) + 1

            except Exception as e:
                logger.error(f"Error parsing CSS from {css_url}: {e}")

        self.scraped_content['themes'] = themes

    def _generate_asset_manifest(self):
        """Generate manifest of all assets with metadata"""
        manifest = {
            'version': '1.0',
            'generated': datetime.utcnow().isoformat(),
            'assets': {}
        }

        for asset_url, asset_data in self.scraped_content['assets'].items():
            manifest['assets'][asset_url] = {
                'type': asset_data['type'],
                'hash': hashlib.md5(asset_url.encode()).hexdigest()[:8]
            }

        self.scraped_content['asset_manifest'] = manifest

    def _detect_layout_patterns(self):
        """Detect common layout patterns across pages"""
        patterns = {
            'header_patterns': [],
            'navigation_patterns': [],
            'content_patterns': [],
            'footer_patterns': []
        }

        # Analyze page structures for common patterns
        for url, page_data in self.scraped_content['pages'].items():
            # This is a simplified pattern detection
            # In practice, you'd use more sophisticated DOM analysis
            structure = page_data.get('structure', {})

            # Detect navigation patterns based on link structure
            nav_links = structure.get('links', [])
            if len(nav_links) > 3 and len(nav_links) < 10:
                patterns['navigation_patterns'].append({
                    'page': url,
                    'link_count': len(nav_links),
                    'links': [link['text'] for link in nav_links[:5]]
                })

        self.scraped_content['layout_patterns'] = patterns


class MigrationAnalyzer:
    """Analyzes scraped content for migration planning"""

    @staticmethod
    def analyze_migration_feasibility(scraped_data: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze if website is suitable for migration"""

        analysis = {
            'feasible': True,
            'complexity': 'medium',
            'warnings': [],
            'recommendations': [],
            'estimated_time': '2-4 hours'
        }

        # Check for complex JavaScript frameworks
        js_content = ' '.join([js.get('content', '') for js in scraped_data.get('scripts', {}).values()])

        complex_frameworks = ['React', 'Angular', 'Vue', 'Ember']
        for framework in complex_frameworks:
            if framework.lower() in js_content.lower():
                analysis['warnings'].append(f"Detected {framework} - migration complexity increases")
                analysis['complexity'] = 'high'
                analysis['estimated_time'] = '4-8 hours'

        # Check page count
        page_count = len(scraped_data.get('pages', {}))
        if page_count > 50:
            analysis['warnings'].append(f"Large site detected ({page_count} pages)")
            analysis['estimated_time'] = '8-16 hours'

        # Check for dynamic content
        dynamic_indicators = ['api/', 'ajax', 'fetch(', '$.get', '$.post']
        for indicator in dynamic_indicators:
            if indicator in js_content.lower():
                analysis['warnings'].append("Dynamic content detected - manual review required")
                break

        return analysis

    @staticmethod
    def generate_migration_report(scraped_data: Dict[str, Any]) -> Dict[str, Any]:
        """Generate comprehensive migration report"""

        report = {
            'summary': {
                'total_pages': len(scraped_data.get('pages', {})),
                'total_assets': len(scraped_data.get('assets', {})),
                'total_styles': len(scraped_data.get('styles', {})),
                'total_scripts': len(scraped_data.get('scripts', {}))
            },
            'content_analysis': {
                'pages_by_type': {},
                'common_elements': {},
                'seo_score': 0
            },
            'technical_details': {
                'frameworks': [],
                'libraries': [],
                'compatibility': []
            },
            'migration_plan': {
                'steps': [],
                'timeline': '',
                'risks': []
            }
        }

        # Analyze pages by content type
        for url, page_data in scraped_data.get('pages', {}).items():
            page_type = 'content'  # Default
            if 'product' in url.lower():
                page_type = 'product'
            elif 'blog' in url.lower() or 'news' in url.lower():
                page_type = 'blog'
            elif 'contact' in url.lower():
                page_type = 'contact'

            report['content_analysis']['pages_by_type'][page_type] = \
                report['content_analysis']['pages_by_type'].get(page_type, 0) + 1

        # Generate migration steps
        report['migration_plan']['steps'] = [
            "Setup new template structure",
            "Migrate content and assets",
            "Recreate styling and layout",
            "Implement interactive features",
            "Test and optimize",
            "Deploy and monitor"
        ]

        return report

"""
SEO Preservation Service
Maintains SEO rankings during website migration
"""

import json
import re
from typing import Dict, List, Optional, Any
from urllib.parse import urljoin, urlparse
from pathlib import Path
from bs4 import BeautifulSoup
import logging

logger = logging.getLogger(__name__)

class SEOPreserver:
    """Preserves SEO elements during migration"""

    def __init__(self):
        self.redirects = []
        self.meta_data = {}
        self.url_mapping = {}
        self.broken_links = []
        self.performance_metrics = {}

    def extract_seo_data(self, scraped_data: Dict[str, Any]) -> Dict[str, Any]:
        """Extract all SEO-relevant data from scraped website"""

        seo_data = {
            'meta_tags': {},
            'url_structure': {},
            'content_structure': {},
            'internal_links': {},
            'external_links': {},
            'images': {},
            'schema_markup': {},
            'performance_baseline': {}
        }

        base_url = scraped_data.get('base_url', '')

        # Process each page for SEO data
        for url, page_data in scraped_data.get('pages', {}).items():
            page_seo = self._extract_page_seo(url, page_data)
            seo_data['meta_tags'][url] = page_seo['meta_tags']
            seo_data['content_structure'][url] = page_seo['content_structure']
            seo_data['internal_links'][url] = page_seo['internal_links']
            seo_data['external_links'][url] = page_seo['external_links']
            seo_data['images'][url] = page_seo['images']
            seo_data['schema_markup'][url] = page_seo['schema_markup']

        # Extract URL structure patterns
        seo_data['url_structure'] = self._analyze_url_structure(scraped_data)

        # Generate redirect mapping
        seo_data['redirect_mapping'] = self._generate_redirect_mapping(scraped_data)

        return seo_data

    def _extract_page_seo(self, url: str, page_data: Dict[str, Any]) -> Dict[str, Any]:
        """Extract SEO data from individual page"""

        return {
            'meta_tags': {
                'title': page_data.get('title', ''),
                'description': page_data.get('meta', {}).get('description', ''),
                'keywords': page_data.get('meta', {}).get('keywords', ''),
                'canonical': page_data.get('meta', {}).get('canonical', url),
                'og_tags': page_data.get('seo', {}).get('og_tags', {}),
                'twitter_tags': page_data.get('seo', {}).get('twitter_tags', {})
            },
            'content_structure': {
                'h1': page_data.get('structure', {}).get('h1', []),
                'h2': page_data.get('structure', {}).get('h2', []),
                'h3': page_data.get('structure', {}).get('h3', []),
                'word_count': len(page_data.get('content', {}).get('text', '').split()),
                'content_length': len(page_data.get('content', {}).get('text', ''))
            },
            'internal_links': page_data.get('structure', {}).get('links', []),
            'external_links': [
                link for link in page_data.get('structure', {}).get('links', [])
                if not link['href'].startswith(urlparse(url).netloc)
            ],
            'images': [
                {
                    'src': img['src'],
                    'alt': img['alt'],
                    'title': img.get('title', ''),
                    'caption': self._extract_image_caption(img['src'], page_data)
                }
                for img in page_data.get('structure', {}).get('images', [])
            ],
            'schema_markup': page_data.get('seo', {}).get('schema_markup', [])
        }

    def _analyze_url_structure(self, scraped_data: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze URL structure for SEO optimization"""

        urls = list(scraped_data.get('pages', {}).keys())

        structure = {
            'depth_analysis': {},
            'keyword_usage': {},
            'url_patterns': [],
            'optimization_recommendations': []
        }

        for url in urls:
            parsed = urlparse(url)
            path_parts = [p for p in parsed.path.split('/') if p]

            # Analyze URL depth
            structure['depth_analysis'][url] = len(path_parts)

            # Extract keywords from URLs
            keywords = []
            for part in path_parts:
                keywords.extend(re.findall(r'[a-zA-Z]+', part.lower()))
            structure['keyword_usage'][url] = keywords

        # Generate recommendations
        structure['optimization_recommendations'] = self._generate_url_recommendations(structure)

        return structure

    def _generate_redirect_mapping(self, scraped_data: Dict[str, Any]) -> List[Dict[str, str]]:
        """Generate redirect mapping to preserve SEO value"""

        mapping = []
        base_url = scraped_data.get('base_url', '')

        for url in scraped_data.get('pages', {}).keys():
            if url.startswith(base_url):
                old_path = url[len(base_url):]
                if old_path:
                    # Generate new URL structure
                    new_path = self._optimize_url_path(old_path)

                    mapping.append({
                        'old_url': url,
                        'new_url': urljoin(base_url, new_path),
                        'old_path': old_path,
                        'new_path': new_path,
                        'redirect_type': '301',  # Permanent redirect
                        'priority': 'high'
                    })

        return mapping

    def _optimize_url_path(self, path: str) -> str:
        """Optimize URL path for SEO"""

        # Remove trailing slashes
        path = path.rstrip('/')

        # Convert to lowercase
        path = path.lower()

        # Replace spaces and special characters with hyphens
        path = re.sub(r'[^a-zA-Z0-9-]', '-', path)
        path = re.sub(r'-+', '-', path)

        # Remove leading hyphen
        path = path.lstrip('-')

        return path

    def _generate_url_recommendations(self, structure: Dict[str, Any]) -> List[str]:
        """Generate URL optimization recommendations"""

        recommendations = []

        # Check URL depth
        deep_urls = [url for url, depth in structure['depth_analysis'].items() if depth > 3]
        if deep_urls:
            recommendations.append(
                f"Consider flattening URL structure for {len(deep_urls)} deep URLs"
            )

        # Check for dynamic parameters
        for url in structure['depth_analysis'].keys():
            if '?' in url or '=' in url:
                recommendations.append(
                    f"Consider creating static URLs for dynamic content: {url}"
                )

        return recommendations

    def _extract_image_caption(self, img_src: str, page_data: Dict[str, Any]) -> str:
        """Extract image caption from surrounding content"""

        # This would require HTML parsing to find captions
        # For now, return alt text as caption
        for img in page_data.get('structure', {}).get('images', []):
            if img['src'] == img_src:
                return img.get('alt', '')
        return ''

    def generate_robots_txt(self, scraped_data: Dict[str, Any]) -> str:
        """Generate robots.txt for the migrated site"""

        base_url = scraped_data.get('base_url', '')
        parsed = urlparse(base_url)

        robots_content = [
            "User-agent: *",
            "Allow: /",
            "",
            "# Sitemap",
            f"Sitemap: {urljoin(base_url, '/sitemap.xml')}",
            "",
            "# Common directories to block",
            "Disallow: /admin/",
            "Disallow: /wp-admin/",
            "Disallow: /cgi-bin/",
            "Disallow: /private/"
        ]

        return '\n'.join(robots_content)

    def generate_sitemap_xml(self, scraped_data: Dict[str, Any]) -> str:
        """Generate XML sitemap for the migrated site"""

        base_url = scraped_data.get('base_url', '')
        pages = scraped_data.get('pages', {})

        sitemap_content = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
        ]

        for url, page_data in pages.items():
            # Generate new URL
            parsed = urlparse(url)
            new_path = self._optimize_url_path(parsed.path)
            new_url = urljoin(base_url, new_path)

            # Calculate priority based on URL depth
            depth = len([p for p in parsed.path.split('/') if p])
            priority = max(0.1, 1.0 - (depth * 0.2))

            # Use last modified date or current date
            lastmod = '2024-01-01'  # Default, should be actual last modified

            sitemap_content.extend([
                '  <url>',
                f'    <loc>{new_url}</loc>',
                f'    <lastmod>{lastmod}</lastmod>',
                '    <changefreq>weekly</changefreq>',
                f'    <priority>{priority:.1f}</priority>',
                '  </url>'
            ])

        sitemap_content.append('</urlset>')

        return '\n'.join(sitemap_content)

    def generate_meta_redirects(self, redirect_mapping: List[Dict[str, str]]) -> str:
        """Generate HTML meta redirects as fallback"""

        redirects_html = []

        for redirect in redirect_mapping:
            redirects_html.append(
                f'<meta http-equiv="refresh" content="0; url={redirect["new_url"]}" />'
            )

        return '\n'.join(redirects_html)

    def analyze_seo_impact(self, original_data: Dict[str, Any], migrated_data: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze SEO impact after migration"""

        impact_analysis = {
            'meta_tags': {
                'preserved': 0,
                'modified': 0,
                'lost': 0
            },
            'url_changes': {
                'total': 0,
                'redirects_created': 0,
                'potential_issues': []
            },
            'content_changes': {
                'word_count_diff': 0,
                'heading_preservation': 0,
                'image_alt_preservation': 0
            },
            'recommendations': []
        }

        original_pages = original_data.get('pages', {})
        migrated_pages = migrated_data.get('processed_pages', {})

        # Analyze meta tags preservation
        for url, original_page in original_pages.items():
            migrated_page = migrated_pages.get(url, {})

            original_meta = original_page.get('meta', {})
            migrated_meta = migrated_page.get('optimized', {}).get('metadata', {})

            if original_meta.get('title') == migrated_meta.get('title'):
                impact_analysis['meta_tags']['preserved'] += 1
            else:
                impact_analysis['meta_tags']['modified'] += 1

        # Generate recommendations
        if impact_analysis['meta_tags']['modified'] > 0:
            impact_analysis['recommendations'].append(
                f"Review {impact_analysis['meta_tags']['modified']} modified meta tags"
            )

        return impact_analysis

class RedirectManager:
    """Manages URL redirects for SEO preservation"""

    def __init__(self):
        self.redirects = []
        self.htaccess_rules = []
        self.nginx_rules = []

    def generate_redirects(self, redirect_mapping: List[Dict[str, str]], 
                          server_type: str = 'apache') -> str:
        """Generate server-specific redirect rules"""

        if server_type == 'apache':
            return self._generate_apache_redirects(redirect_mapping)
        elif server_type == 'nginx':
            return self._generate_nginx_redirects(redirect_mapping)
        else:
            return self._generate_generic_redirects(redirect_mapping)

    def _generate_apache_redirects(self, redirect_mapping: List[Dict[str, str]]) -> str:
        """Generate Apache .htaccess redirect rules"""

        rules = [
            "# SEO Redirect Rules - Generated for migration",
            "RewriteEngine On",
            ""
        ]

        for redirect in redirect_mapping:
            rules.append(
                f"Redirect 301 {redirect['old_path']} {redirect['new_path']}"
            )

        return '\n'.join(rules)

    def _generate_nginx_redirects(self, redirect_mapping: List[Dict[str, str]]) -> str:
        """Generate Nginx redirect rules"""

        rules = [
            "# SEO Redirect Rules - Generated for migration",
            "server {",
            "    listen 80;",
            "    server_name _;",
            ""
        ]

        for redirect in redirect_mapping:
            rules.append(
                f"    rewrite ^{redirect['old_path']}$ {redirect['new_path']} permanent;"
            )

        rules.extend(["}", ""])

        return '\n'.join(rules)

    def _generate_generic_redirects(self, redirect_mapping: List[Dict[str, str]]) -> str:
        """Generate generic redirect rules for JavaScript/Node.js"""

        rules = []
        for redirect in redirect_mapping:
            rules.append({
                'from': redirect['old_path'],
                'to': redirect['new_path'],
                'status': 301,
                'permanent': True
            })

        return json.dumps(rules, indent=2)

    def validate_redirects(self, redirect_mapping: List[Dict[str, str]]) -> Dict[str, Any]:
        """Validate redirect mapping for issues"""

        validation = {
            'valid': True,
            'issues': [],
            'warnings': [],
            'duplicates': [],
            'cycles': []
        }

        # Check for duplicates
        old_paths = [r['old_path'] for r in redirect_mapping]
        duplicates = [path for path in old_paths if old_paths.count(path) > 1]
        if duplicates:
            validation['duplicates'] = list(set(duplicates))
            validation['issues'].append(f"Duplicate redirects found: {duplicates}")

        # Check for redirect chains/cycles
        path_map = {r['old_path']: r['new_path'] for r in redirect_mapping}
        for old_path, new_path in path_map.items():
            if new_path in path_map:
                validation['cycles'].append(f"Redirect chain: {old_path} -> {new_path}")

        return validation

"""Site generation service for converting components to static HTML."""

import os
import json
import hashlib
import tempfile
import shutil
from typing import Dict, List, Any, Optional, Tuple
from pathlib import Path
from datetime import datetime
from jinja2 import Environment, FileSystemLoader, Template as Jinja2Template
import cssmin
import jsmin
from PIL import Image
import boto3
from botocore.exceptions import ClientError

from ..core.config import settings
from ..models.sites import Site, Component, PublishedSite, BuildStatus


class SiteGenerator:
    """Handles static site generation from component data."""

    def __init__(self):
        self.templates_dir = Path(__file__).parent.parent / "templates"
        self.static_dir = Path(__file__).parent.parent / "static"
        self.jinja_env = Environment(
            loader=FileSystemLoader([str(self.templates_dir)]),
            trim_blocks=True,
            lstrip_blocks=True
        )

        # AWS S3 client for file storage
        self.s3_client = None
        if settings.aws_access_key_id and settings.aws_secret_access_key:
            self.s3_client = boto3.client(
                's3',
                aws_access_key_id=settings.aws_access_key_id,
                aws_secret_access_key=settings.aws_secret_access_key,
                region_name=settings.aws_region
            )

    async def generate_site(self, site: Site) -> Dict[str, Any]:
        """
        Generate static site from component data.

        Args:
            site: Site model instance

        Returns:
            Dictionary with build results
        """
        build_start = datetime.utcnow()

        try:
            # Create temporary build directory
            with tempfile.TemporaryDirectory() as temp_dir:
                build_dir = Path(temp_dir) / "build"
                build_dir.mkdir(exist_ok=True)

                # Generate site structure
                await self._generate_site_structure(site, build_dir)

                # Generate HTML from components
                html_content = await self._generate_html(site)

                # Generate CSS
                css_content = await self._generate_css(site)

                # Generate JavaScript
                js_content = await self._generate_javascript(site)

                # Optimize images
                await self._optimize_images(site, build_dir)

                # Write main files
                await self._write_site_files(
                    build_dir, html_content, css_content, js_content, site
                )

                # Generate SEO files
                await self._generate_seo_files(site, build_dir)

                # Calculate build hash
                build_hash = await self._calculate_build_hash(build_dir)

                # Calculate build size
                build_size = await self._calculate_build_size(build_dir)

                # Upload to S3/CDN
                cdn_url = await self._upload_to_cdn(build_dir, site)

                build_end = datetime.utcnow()
                build_duration = int((build_end - build_start).total_seconds())

                return {
                    "status": BuildStatus.SUCCESS,
                    "build_hash": build_hash,
                    "build_size": build_size,
                    "build_duration": build_duration,
                    "cdn_url": cdn_url,
                    "build_started_at": build_start,
                    "build_completed_at": build_end
                }

        except Exception as e:
            build_end = datetime.utcnow()
            build_duration = int((build_end - build_start).total_seconds())

            return {
                "status": BuildStatus.FAILED,
                "build_duration": build_duration,
                "build_started_at": build_start,
                "build_completed_at": build_end,
                "error": str(e)
            }

    async def _generate_site_structure(self, site: Site, build_dir: Path) -> None:
        """Create basic site directory structure."""
        directories = [
            "assets/css",
            "assets/js",
            "assets/images",
            "assets/fonts"
        ]

        for directory in directories:
            (build_dir / directory).mkdir(parents=True, exist_ok=True)

    async def _generate_html(self, site: Site) -> str:
        """Generate main HTML content from components."""
        # Load base template
        base_template = self.jinja_env.get_template("base.html")

        # Generate component HTML
        components_html = []
        sorted_components = sorted(site.components, key=lambda c: c.order_index)

        for component in sorted_components:
            component_html = await self._generate_component_html(component)
            components_html.append(component_html)

        # Render final HTML
        html_content = base_template.render(
            site=site,
            components_html="\n".join(components_html),
            meta_title=site.meta_title or site.name,
            meta_description=site.meta_description or site.description,
            favicon_url=site.favicon_url
        )

        return html_content

    async def _generate_component_html(self, component: Component) -> str:
        """Generate HTML for a single component."""
        component_type = component.type.value
        template_name = f"components/{component_type}.html"

        try:
            template = self.jinja_env.get_template(template_name)
            return template.render(
                component=component,
                config=component.config,
                styles=component.styles
            )
        except Exception:
            # Fallback to generic component template
            generic_template = self.jinja_env.get_template("components/generic.html")
            return generic_template.render(component=component)

    async def _generate_css(self, site: Site) -> str:
        """Generate and optimize CSS."""
        css_parts = []

        # Add base CSS
        base_css_path = self.static_dir / "css" / "base.css"
        if base_css_path.exists():
            css_parts.append(base_css_path.read_text())

        # Add Tailwind CSS (would be compiled from config)
        tailwind_css = await self._compile_tailwind_css(site)
        css_parts.append(tailwind_css)

        # Add component-specific styles
        for component in site.components:
            if component.styles:
                component_css = await self._generate_component_css(component)
                css_parts.append(component_css)

        # Combine all CSS
        combined_css = "\n".join(css_parts)

        # Minify if enabled
        if settings.css_minification:
            combined_css = cssmin.cssmin(combined_css)

        return combined_css

    async def _compile_tailwind_css(self, site: Site) -> str:
        """Compile Tailwind CSS based on site configuration."""
        # This would integrate with Tailwind CLI or PostCSS
        # For now, return basic Tailwind classes used

        base_classes = [
            "container", "mx-auto", "px-4", "py-8", "text-center",
            "bg-blue-500", "text-white", "rounded", "shadow-lg",
            "hover:bg-blue-600", "transition-colors", "duration-200"
        ]

        # Extract classes used in components
        used_classes = set(base_classes)
        for component in site.components:
            if isinstance(component.config, dict):
                # Extract Tailwind classes from component config
                classes = self._extract_tailwind_classes(component.config)
                used_classes.update(classes)

        # Generate minimal Tailwind CSS
        # In production, this would use Tailwind's purge functionality
        return self._generate_minimal_tailwind(used_classes)

    def _extract_tailwind_classes(self, config: Dict[str, Any]) -> List[str]:
        """Extract Tailwind classes from component configuration."""
        classes = []

        def extract_from_value(value):
            if isinstance(value, str) and any(prefix in value for prefix in ['bg-', 'text-', 'p-', 'm-', 'w-', 'h-']):
                classes.extend(value.split())
            elif isinstance(value, dict):
                for v in value.values():
                    extract_from_value(v)
            elif isinstance(value, list):
                for item in value:
                    extract_from_value(item)

        extract_from_value(config)
        return classes

    def _generate_minimal_tailwind(self, classes: set) -> str:
        """Generate minimal Tailwind CSS for used classes."""
        # This is a simplified version - in production would use actual Tailwind
        css_rules = []

        for class_name in classes:
            if class_name.startswith('bg-'):
                color = class_name.replace('bg-', '')
                css_rules.append(f".{class_name} {{ background-color: var(--color-{color}); }}")
            elif class_name.startswith('text-'):
                if class_name.endswith('-center'):
                    css_rules.append(f".{class_name} {{ text-align: center; }}")
                else:
                    color = class_name.replace('text-', '')
                    css_rules.append(f".{class_name} {{ color: var(--color-{color}); }}")
            elif class_name.startswith('p-'):
                size = class_name.replace('p-', '')
                css_rules.append(f".{class_name} {{ padding: {size}rem; }}")

        return "\n".join(css_rules)

    async def _generate_component_css(self, component: Component) -> str:
        """Generate CSS for component custom styles."""
        if not component.styles:
            return ""

        css_rules = []
        component_selector = f".component-{component.component_id}"

        # Convert styles dict to CSS
        for property_name, value in component.styles.items():
            css_property = property_name.replace('_', '-')
            css_rules.append(f"  {css_property}: {value};")

        if css_rules:
            return f"{component_selector} {{\n" + "\n".join(css_rules) + "\n}"

        return ""

    async def _generate_javascript(self, site: Site) -> str:
        """Generate and bundle JavaScript."""
        js_parts = []

        # Add base JavaScript
        base_js_path = self.static_dir / "js" / "base.js"
        if base_js_path.exists():
            js_parts.append(base_js_path.read_text())

        # Add component-specific JavaScript
        for component in site.components:
            component_js = await self._generate_component_js(component)
            if component_js:
                js_parts.append(component_js)

        # Add analytics tracking
        if site.settings.get('analytics_id'):
            analytics_js = self._generate_analytics_js(site.settings['analytics_id'])
            js_parts.append(analytics_js)

        # Combine all JavaScript
        combined_js = "\n".join(js_parts)

        # Minify if enabled
        if settings.js_bundling:
            combined_js = jsmin.jsmin(combined_js)

        return combined_js

    async def _generate_component_js(self, component: Component) -> str:
        """Generate JavaScript for interactive components."""
        if component.type.value == "contact_form":
            return self._generate_form_js(component)
        elif component.type.value == "newsletter_signup":
            return self._generate_newsletter_js(component)
        elif component.type.value == "cta_button":
            return self._generate_cta_js(component)

        return ""

    def _generate_form_js(self, component: Component) -> str:
        """Generate JavaScript for contact forms."""
        return f"""
        document.addEventListener('DOMContentLoaded', function() {{
            const form = document.getElementById('{component.component_id}');
            if (form) {{
                form.addEventListener('submit', async function(e) {{
                    e.preventDefault();
                    const formData = new FormData(form);

                    try {{
                        const response = await fetch('/api/v1/forms/submit', {{
                            method: 'POST',
                            body: formData
                        }});

                        if (response.ok) {{
                            form.innerHTML = '<div class="success-message">Thank you for your message!</div>';
                        }}
                    }} catch (error) {{
                        console.error('Form submission error:', error);
                    }}
                }});
            }}
        }});
        """

    def _generate_newsletter_js(self, component: Component) -> str:
        """Generate JavaScript for newsletter signup."""
        return f"""
        document.addEventListener('DOMContentLoaded', function() {{
            const form = document.getElementById('{component.component_id}');
            if (form) {{
                form.addEventListener('submit', async function(e) {{
                    e.preventDefault();
                    const email = form.querySelector('input[type="email"]').value;

                    try {{
                        const response = await fetch('/api/v1/newsletter/subscribe', {{
                            method: 'POST',
                            headers: {{ 'Content-Type': 'application/json' }},
                            body: JSON.stringify({{ email }})
                        }});

                        if (response.ok) {{
                            form.innerHTML = '<div class="success-message">Successfully subscribed!</div>';
                        }}
                    }} catch (error) {{
                        console.error('Newsletter subscription error:', error);
                    }}
                }});
            }}
        }});
        """

    def _generate_cta_js(self, component: Component) -> str:
        """Generate JavaScript for CTA buttons."""
        return f"""
        document.addEventListener('DOMContentLoaded', function() {{
            const button = document.getElementById('{component.component_id}');
            if (button) {{
                button.addEventListener('click', function() {{
                    // Track CTA click
                    if (window.gtag) {{
                        gtag('event', 'click', {{
                            'event_category': 'CTA',
                            'event_label': '{component.name}'
                        }});
                    }}
                }});
            }}
        }});
        """

    def _generate_analytics_js(self, analytics_id: str) -> str:
        """Generate Google Analytics JavaScript."""
        return f"""
        <!-- Google Analytics -->
        <script async src="https://www.googletagmanager.com/gtag/js?id={analytics_id}"></script>
        <script>
            window.dataLayer = window.dataLayer || [];
            function gtag(){{dataLayer.push(arguments);}}
            gtag('js', new Date());
            gtag('config', '{analytics_id}');
        </script>
        """

    async def _optimize_images(self, site: Site, build_dir: Path) -> None:
        """Optimize images for web delivery."""
        if not settings.image_optimization:
            return

        images_dir = build_dir / "assets" / "images"

        # Process images from components
        for component in site.components:
            if isinstance(component.config, dict):
                await self._process_component_images(component.config, images_dir)

    async def _process_component_images(self, config: Dict[str, Any], images_dir: Path) -> None:
        """Process and optimize images from component configuration."""
        def process_value(value):
            if isinstance(value, str) and (value.startswith('http') or value.endswith(('.jpg', '.jpeg', '.png', '.gif'))):
                # This would download and optimize the image
                # For now, just log the image URL
                pass
            elif isinstance(value, dict):
                for v in value.values():
                    process_value(v)
            elif isinstance(value, list):
                for item in value:
                    process_value(item)

        process_value(config)

    async def _write_site_files(
        self, 
        build_dir: Path, 
        html_content: str, 
        css_content: str, 
        js_content: str, 
        site: Site
    ) -> None:
        """Write generated files to build directory."""
        # Write main HTML file
        (build_dir / "index.html").write_text(html_content, encoding='utf-8')

        # Write CSS file
        if css_content:
            (build_dir / "assets" / "css" / "main.css").write_text(css_content, encoding='utf-8')

        # Write JavaScript file
        if js_content:
            (build_dir / "assets" / "js" / "main.js").write_text(js_content, encoding='utf-8')

    async def _generate_seo_files(self, site: Site, build_dir: Path) -> None:
        """Generate SEO-related files."""
        # Generate sitemap.xml
        sitemap_content = f"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
    <url>
        <loc>{site.url}</loc>
        <lastmod>{datetime.utcnow().strftime('%Y-%m-%d')}</lastmod>
        <changefreq>weekly</changefreq>
        <priority>1.0</priority>
    </url>
</urlset>"""

        (build_dir / "sitemap.xml").write_text(sitemap_content, encoding='utf-8')

        # Generate robots.txt
        robots_content = f"""User-agent: *
Allow: /

Sitemap: {site.url}/sitemap.xml"""

        (build_dir / "robots.txt").write_text(robots_content, encoding='utf-8')

        # Generate manifest.json for PWA
        manifest_content = {
            "name": site.name,
            "short_name": site.name[:12],
            "description": site.description or "",
            "start_url": "/",
            "display": "standalone",
            "background_color": "#ffffff",
            "theme_color": "#000000"
        }

        (build_dir / "manifest.json").write_text(
            json.dumps(manifest_content, indent=2), 
            encoding='utf-8'
        )

    async def _calculate_build_hash(self, build_dir: Path) -> str:
        """Calculate SHA256 hash of build artifacts."""
        hasher = hashlib.sha256()

        for file_path in sorted(build_dir.rglob("*")):
            if file_path.is_file():
                hasher.update(file_path.read_bytes())

        return hasher.hexdigest()

    async def _calculate_build_size(self, build_dir: Path) -> int:
        """Calculate total size of build artifacts in bytes."""
        total_size = 0

        for file_path in build_dir.rglob("*"):
            if file_path.is_file():
                total_size += file_path.stat().st_size

        return total_size

    async def _upload_to_cdn(self, build_dir: Path, site: Site) -> Optional[str]:
        """Upload build artifacts to S3/CDN."""
        if not self.s3_client:
            return None

        try:
            # Upload all files to S3
            for file_path in build_dir.rglob("*"):
                if file_path.is_file():
                    relative_path = file_path.relative_to(build_dir)
                    s3_key = f"sites/{site.id}/{relative_path}"

                    # Determine content type
                    content_type = self._get_content_type(file_path.suffix)

                    self.s3_client.upload_file(
                        str(file_path),
                        settings.s3_bucket_name,
                        s3_key,
                        ExtraArgs={
                            'ContentType': content_type,
                            'CacheControl': 'max-age=31536000' if file_path.suffix in ['.css', '.js', '.png', '.jpg', '.jpeg', '.gif'] else 'max-age=3600'
                        }
                    )

            # Return CDN URL
            if settings.cloudfront_distribution_id:
                return f"https://{settings.cloudfront_distribution_id}.cloudfront.net/sites/{site.id}"
            else:
                return f"https://{settings.s3_bucket_name}.s3.{settings.aws_region}.amazonaws.com/sites/{site.id}"

        except Exception as e:
            print(f"CDN upload error: {e}")
            return None

    def _get_content_type(self, file_extension: str) -> str:
        """Get appropriate content type for file extension."""
        content_types = {
            '.html': 'text/html',
            '.css': 'text/css',
            '.js': 'application/javascript',
            '.json': 'application/json',
            '.xml': 'application/xml',
            '.txt': 'text/plain',
            '.png': 'image/png',
            '.jpg': 'image/jpeg',
            '.jpeg': 'image/jpeg',
            '.gif': 'image/gif',
            '.svg': 'image/svg+xml',
            '.ico': 'image/x-icon'
        }

        return content_types.get(file_extension.lower(), 'application/octet-stream')

"""Celery tasks for background processing of site publishing operations."""

import asyncio
from typing import Dict, Any, Optional
from celery import Celery
from datetime import datetime, timedelta

from ..core.config import settings
from .publishing_service import PublishingService
from .domain_manager import DomainManager

# Initialize Celery app
celery_app = Celery(
    "aiwebbuilder",
