model_file = "app/models/workflow.py" required_content = [ "class WorkflowCategory", "class TriggerType", "class Workflow", "class WorkflowExecution", "class WorkflowNode", "category: Mapped[WorkflowCategory]", "trigger_type: Mapped[TriggerType]", "template_id: Mapped[Optional[str]]", "component_id: Mapped[Optional[str]]" ]
