            expected_effect_size=0.05,
            statistical_power=0.8,
            significance_level=0.05
        )

        return ABTestConfiguration(
            base_template=base_template,
            variants=variants,
            conversion_tracking=conversion_config,
            statistical_config=statistical_config,
