#!/usr/bin/env node
/**
 * Epic 2: Analytics Collector - Comprehensive Workflow Analytics
 * Collects, analyzes and reports on workflow performance metrics
 */

const { Octokit } = require('@octokit/rest');
const fs = require('fs').promises;
const path = require('path');

class WorkflowAnalytics {
  constructor() {
    this.octokit = new Octokit({
      auth: process.env.GITHUB_TOKEN
    });
    this.owner = process.env.GITHUB_REPOSITORY?.split('/')[0] || 'gpb360';
    this.repo = process.env.GITHUB_REPOSITORY?.split('/')[1] || 'AI-Marketing-Web-Builder';
    this.analytics = {
      timestamp: new Date().toISOString(),
      epic: 'Epic 2: Workflow Automation System',
      metrics: {},
      trends: {},
      insights: [],
      performance: {}
    };
  }

  async collectWorkflowMetrics() {
    console.log('📊 Collecting Workflow Performance Metrics...');

    try {
      // Get workflow runs for the last 30 days
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const { data: workflows } = await this.octokit.rest.actions.listWorkflowRuns({
        owner: this.owner,
        repo: this.repo,
        per_page: 100,
        created: `>=${thirtyDaysAgo.toISOString()}`
      });

      const metrics = {
        total_runs: workflows.workflow_runs.length,
        successful_runs: workflows.workflow_runs.filter(r => r.conclusion === 'success').length,
        failed_runs: workflows.workflow_runs.filter(r => r.conclusion === 'failure').length,
        cancelled_runs: workflows.workflow_runs.filter(r => r.conclusion === 'cancelled').length,
        average_duration: 0,
        success_rate: 0,
        failure_rate: 0,
        by_workflow: {},
        by_trigger: {},
        daily_statistics: {}
      };

      // Calculate averages and rates
      if (metrics.total_runs > 0) {
        metrics.success_rate = (metrics.successful_runs / metrics.total_runs * 100).toFixed(2);
        metrics.failure_rate = (metrics.failed_runs / metrics.total_runs * 100).toFixed(2);
      }

      // Analyze by workflow type
      const workflowStats = {};
      const dailyStats = {};
      let totalDuration = 0;
      let durationCount = 0;

      for (const run of workflows.workflow_runs) {
        // Workflow-specific stats
        if (!workflowStats[run.name]) {
          workflowStats[run.name] = {
            total: 0,
            success: 0,
            failed: 0,
            average_duration: 0,
            durations: []
          };
        }

        workflowStats[run.name].total++;
        if (run.conclusion === 'success') workflowStats[run.name].success++;
        if (run.conclusion === 'failure') workflowStats[run.name].failed++;

        // Calculate duration
        if (run.run_started_at && run.updated_at) {
          const duration = new Date(run.updated_at) - new Date(run.run_started_at);
          workflowStats[run.name].durations.push(duration);
          totalDuration += duration;
          durationCount++;
        }

        // Daily statistics
        const date = new Date(run.created_at).toDateString();
        if (!dailyStats[date]) {
          dailyStats[date] = { total: 0, success: 0, failed: 0 };
        }
        dailyStats[date].total++;
        if (run.conclusion === 'success') dailyStats[date].success++;
        if (run.conclusion === 'failure') dailyStats[date].failed++;

        // Trigger analysis
        const trigger = run.event;
        if (!metrics.by_trigger[trigger]) {
          metrics.by_trigger[trigger] = { count: 0, success: 0, failed: 0 };
        }
        metrics.by_trigger[trigger].count++;
        if (run.conclusion === 'success') metrics.by_trigger[trigger].success++;
        if (run.conclusion === 'failure') metrics.by_trigger[trigger].failed++;
      }

      // Calculate workflow averages
      for (const [name, stats] of Object.entries(workflowStats)) {
        if (stats.durations.length > 0) {
          stats.average_duration = stats.durations.reduce((a, b) => a + b, 0) / stats.durations.length;
        }
        stats.success_rate = stats.total > 0 ? (stats.success / stats.total * 100).toFixed(2) : 0;
        delete stats.durations; // Remove raw data
      }

      metrics.by_workflow = workflowStats;
      metrics.daily_statistics = dailyStats;
      metrics.average_duration = durationCount > 0 ? (totalDuration / durationCount) : 0;

      this.analytics.metrics.workflows = metrics;
      return metrics;
    } catch (error) {
      console.error('❌ Error collecting workflow metrics:', error);
      return null;
    }
  }

  async collectPRMetrics() {
    console.log('🔄 Collecting Pull Request Analytics...');

    try {
      const { data: pulls } = await this.octokit.rest.pulls.list({
        owner: this.owner,
        repo: this.repo,
        state: 'all',
        per_page: 100,
        sort: 'updated',
        direction: 'desc'
      });

      const prMetrics = {
        total_prs: pulls.length,
        open_prs: pulls.filter(pr => pr.state === 'open').length,
        merged_prs: pulls.filter(pr => pr.merged_at).length,
        closed_prs: pulls.filter(pr => pr.state === 'closed' && !pr.merged_at).length,
        average_review_time: 0,
        average_merge_time: 0,
        by_author: {},
        by_label: {},
        review_statistics: {
          total_reviews: 0,
          average_reviews_per_pr: 0,
          review_response_time: []
        }
      };

      let totalReviewTime = 0;
      let totalMergeTime = 0;
      let reviewTimeCount = 0;
      let mergeTimeCount = 0;

      for (const pr of pulls) {
        // Author statistics
        const author = pr.user.login;
        if (!prMetrics.by_author[author]) {
          prMetrics.by_author[author] = { total: 0, merged: 0, open: 0 };
        }
        prMetrics.by_author[author].total++;
        if (pr.merged_at) prMetrics.by_author[author].merged++;
        if (pr.state === 'open') prMetrics.by_author[author].open++;

        // Label analysis
        for (const label of pr.labels) {
          if (!prMetrics.by_label[label.name]) {
            prMetrics.by_label[label.name] = 0;
          }
          prMetrics.by_label[label.name]++;
        }

        // Review analysis
        try {
          const { data: reviews } = await this.octokit.rest.pulls.listReviews({
            owner: this.owner,
            repo: this.repo,
            pull_number: pr.number
          });

          prMetrics.review_statistics.total_reviews += reviews.length;

          if (reviews.length > 0) {
            const firstReviewTime = new Date(reviews[0].submitted_at) - new Date(pr.created_at);
            prMetrics.review_statistics.review_response_time.push(firstReviewTime);
            totalReviewTime += firstReviewTime;
            reviewTimeCount++;
          }
        } catch (error) {
          console.log(`Warning: Could not fetch reviews for PR #${pr.number}`);
        }

        // Merge time calculation
        if (pr.merged_at) {
          const mergeTime = new Date(pr.merged_at) - new Date(pr.created_at);
          totalMergeTime += mergeTime;
          mergeTimeCount++;
        }
      }

      // Calculate averages
      prMetrics.average_review_time = reviewTimeCount > 0 ? (totalReviewTime / reviewTimeCount) : 0;
      prMetrics.average_merge_time = mergeTimeCount > 0 ? (totalMergeTime / mergeTimeCount) : 0;
      prMetrics.review_statistics.average_reviews_per_pr = prMetrics.total_prs > 0 ? 
        (prMetrics.review_statistics.total_reviews / prMetrics.total_prs).toFixed(2) : 0;

      this.analytics.metrics.pull_requests = prMetrics;
      return prMetrics;
    } catch (error) {
      console.error('❌ Error collecting PR metrics:', error);
      return null;
    }
  }

  async collectAgentMetrics() {
    console.log('🤖 Collecting Agent Performance Metrics...');

    try {
      // Analyze commit patterns for agent activity
      const { data: commits } = await this.octokit.rest.repos.listCommits({
        owner: this.owner,
        repo: this.repo,
        per_page: 100
      });

      const agentMetrics = {
        total_agent_commits: 0,
        agents_active: new Set(),
        commit_patterns: {},
        isolation_compliance: 0,
        branch_patterns: {}
      };

      // Analyze commits for agent patterns
      for (const commit of commits) {
        const message = commit.commit.message;

        // Detect agent commits
        const agentPattern = /\[([\w-]+)\]/;
        const agentMatch = message.match(agentPattern);

        if (agentMatch) {
          agentMetrics.total_agent_commits++;
          const agent = agentMatch[1];
          agentMetrics.agents_active.add(agent);

          if (!agentMetrics.commit_patterns[agent]) {
            agentMetrics.commit_patterns[agent] = 0;
          }
          agentMetrics.commit_patterns[agent]++;
        }
      }

      // Convert Set to array for JSON serialization
      agentMetrics.agents_active = Array.from(agentMetrics.agents_active);
      agentMetrics.active_agent_count = agentMetrics.agents_active.length;

      // Analyze branch patterns for isolation compliance
      const { data: branches } = await this.octokit.rest.repos.listBranches({
        owner: this.owner,
        repo: this.repo,
        per_page: 100
      });

      let isolationCompliantBranches = 0;
      const agentBranchPattern = /^(frontend|backend|template|ai|integration|performance|workflow|deployment)\//;

      for (const branch of branches.branches) {
        if (agentBranchPattern.test(branch.name)) {
          isolationCompliantBranches++;
          const category = branch.name.split('/')[0];
          if (!agentMetrics.branch_patterns[category]) {
            agentMetrics.branch_patterns[category] = 0;
          }
          agentMetrics.branch_patterns[category]++;
        }
      }

      agentMetrics.isolation_compliance = branches.branches.length > 0 ? 
        (isolationCompliantBranches / branches.branches.length * 100).toFixed(2) : 0;

      this.analytics.metrics.agents = agentMetrics;
      return agentMetrics;
    } catch (error) {
      console.error('❌ Error collecting agent metrics:', error);
      return null;
    }
  }

  async generateInsights() {
    console.log('🧠 Generating Performance Insights...');

    const insights = [];
    const workflows = this.analytics.metrics.workflows;
    const prs = this.analytics.metrics.pull_requests;
    const agents = this.analytics.metrics.agents;

    // Workflow insights
    if (workflows) {
      if (workflows.success_rate < 90) {
        insights.push({
          type: 'warning',
          category: 'workflows',
          title: 'Low Workflow Success Rate',
          description: `Current success rate is ${workflows.success_rate}%. Target is >90%.`,
          recommendation: 'Review failed workflows and implement reliability improvements.',
          priority: 'high'
        });
      }

      if (workflows.average_duration > 10 * 60 * 1000) { // 10 minutes
        insights.push({
          type: 'performance',
          category: 'workflows',
          title: 'Long Workflow Duration',
          description: `Average workflow duration is ${(workflows.average_duration / 60000).toFixed(1)} minutes.`,
          recommendation: 'Optimize CI/CD pipelines and implement parallel job execution.',
          priority: 'medium'
        });
      }
    }

    // PR insights
    if (prs) {
      if (prs.average_review_time > 5 * 60 * 1000) { // 5 minutes
        insights.push({
          type: 'sla_violation',
          category: 'pull_requests',
          title: 'Slow PR Review Times',
          description: `Average review time is ${(prs.average_review_time / 60000).toFixed(1)} minutes. SLA is 5 minutes.`,
          recommendation: 'Implement automated reviewer assignment and review reminders.',
          priority: 'high'
        });
      }

      const openPRRatio = prs.total_prs > 0 ? (prs.open_prs / prs.total_prs) : 0;
      if (openPRRatio > 0.3) { // More than 30% open PRs
        insights.push({
          type: 'bottleneck',
          category: 'pull_requests',
          title: 'High Open PR Ratio',
          description: `${(openPRRatio * 100).toFixed(1)}% of PRs are currently open.`,
          recommendation: 'Implement stricter review deadlines and automated merge policies.',
          priority: 'medium'
        });
      }
    }

    // Agent insights
    if (agents) {
      if (agents.isolation_compliance < 80) {
        insights.push({
          type: 'process_violation',
          category: 'agents',
          title: 'Poor Branch Isolation Compliance',
          description: `Only ${agents.isolation_compliance}% of branches follow agent isolation patterns.`,
          recommendation: 'Enforce agent branch naming conventions and provide training.',
          priority: 'high'
        });
      }

      if (agents.active_agent_count < 5) {
        insights.push({
          type: 'utilization',
          category: 'agents',
          title: 'Low Agent Utilization',
          description: `Only ${agents.active_agent_count} agents are actively contributing.`,
          recommendation: 'Distribute work more evenly across agent specializations.',
          priority: 'low'
        });
      }
    }

    this.analytics.insights = insights;
    return insights;
  }

  async generateReport() {
    console.log('📋 Generating Comprehensive Analytics Report...');

    // Set performance score
    const workflows = this.analytics.metrics.workflows;
    const prs = this.analytics.metrics.pull_requests;

    let performanceScore = 100;

    if (workflows && workflows.success_rate < 90) performanceScore -= 20;
    if (prs && prs.average_review_time > 5 * 60 * 1000) performanceScore -= 15;
    if (this.analytics.insights.filter(i => i.priority === 'high').length > 0) performanceScore -= 10;

    this.analytics.performance = {
      overall_score: Math.max(0, performanceScore),
      grade: performanceScore >= 90 ? 'A' : performanceScore >= 80 ? 'B' : performanceScore >= 70 ? 'C' : 'D',
      status: performanceScore >= 80 ? 'excellent' : performanceScore >= 60 ? 'good' : 'needs_improvement'
    };

    // Save report
    const reportPath = path.join(__dirname, '../../reports/analytics-report.json');
    await fs.mkdir(path.dirname(reportPath), { recursive: true });
    await fs.writeFile(reportPath, JSON.stringify(this.analytics, null, 2));

    console.log(`✅ Analytics report saved to: ${reportPath}`);
    console.log(`📊 Overall Performance Score: ${this.analytics.performance.overall_score}/100 (${this.analytics.performance.grade})`);

    return this.analytics;
  }
}

// Main execution
async function main() {
  const args = process.argv.slice(2);
  const analytics = new WorkflowAnalytics();

  try {
    if (args.includes('--collect-all')) {
      console.log('🚀 Starting Epic 2 Analytics Collection...');
      await analytics.collectWorkflowMetrics();
      await analytics.collectPRMetrics();
      await analytics.collectAgentMetrics();
      console.log('✅ All metrics collected successfully');
    } else if (args.includes('--generate-insights')) {
      await analytics.generateInsights();
      console.log('✅ Insights generated successfully');
    } else {
      // Full analytics run
      console.log('🚀 Starting Comprehensive Epic 2 Analytics...');
      await analytics.collectWorkflowMetrics();
      await analytics.collectPRMetrics();
      await analytics.collectAgentMetrics();
      await analytics.generateInsights();
      await analytics.generateReport();

      console.log(`✅ Epic 2 Analytics Complete: Score ${analytics.analytics.performance.overall_score}/100`);
    }
  } catch (error) {
    console.error('❌ Analytics Error:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = { WorkflowAnalytics };

#!/usr/bin/env node
/**
 * Epic 2: SLA Monitor - Advanced Performance Tracking
 * Monitors and enforces Service Level Agreements across the development pipeline
 */

const { Octokit } = require('@octokit/rest');
const fs = require('fs').promises;
const path = require('path');

// SLA Configuration
const SLA_THRESHOLDS = {
  pr_review_time: 5 * 60 * 1000,      // 5 minutes in milliseconds
  build_time: 10 * 60 * 1000,         // 10 minutes
  test_execution: 8 * 60 * 1000,      // 8 minutes
  deployment_time: 15 * 60 * 1000,    // 15 minutes
  agent_response: 2 * 60 * 1000,      // 2 minutes for agent responses
  task_completion: 4 * 60 * 60 * 1000 // 4 hours for task completion
};

class SLAMonitor {
  constructor() {
    this.octokit = new Octokit({
      auth: process.env.GITHUB_TOKEN
    });
    this.owner = process.env.GITHUB_REPOSITORY?.split('/')[0] || 'gpb360';
    this.repo = process.env.GITHUB_REPOSITORY?.split('/')[1] || 'AI-Marketing-Web-Builder';
    this.violations = [];
    this.metrics = {};
  }

  async monitorPRReviewTimes() {
    console.log('📊 Monitoring PR Review Times...');

    try {
      const { data: pulls } = await this.octokit.rest.pulls.list({
        owner: this.owner,
        repo: this.repo,
        state: 'open',
        per_page: 50
      });

      for (const pull of pulls) {
        const { data: reviews } = await this.octokit.rest.pulls.listReviews({
          owner: this.owner,
          repo: this.repo,
          pull_number: pull.number
        });

        const createdAt = new Date(pull.created_at);
        const now = new Date();
        const timeSinceCreation = now - createdAt;

        // Check if PR has been reviewed
        if (reviews.length === 0 && timeSinceCreation > SLA_THRESHOLDS.pr_review_time) {
          this.violations.push({
            type: 'pr_review_time',
            pr_number: pull.number,
            title: pull.title,
            time_elapsed: timeSinceCreation,
            threshold: SLA_THRESHOLDS.pr_review_time,
            severity: 'high'
          });
        }

        // Check review response times
        for (const review of reviews) {
          const reviewTime = new Date(review.submitted_at) - createdAt;
          if (reviewTime > SLA_THRESHOLDS.pr_review_time) {
            this.violations.push({
              type: 'pr_review_response',
              pr_number: pull.number,
              review_id: review.id,
              response_time: reviewTime,
              threshold: SLA_THRESHOLDS.pr_review_time,
              severity: 'medium'
            });
          }
        }
      }

      this.metrics.pr_review_violations = this.violations.filter(v => 
        v.type === 'pr_review_time' || v.type === 'pr_review_response'
      ).length;

      return this.violations.length > 0;
    } catch (error) {
      console.error('❌ Error monitoring PR review times:', error);
      return false;
    }
  }

  async monitorBuildTimes() {
    console.log('🏗️ Monitoring Build Performance...');

    try {
      const { data: workflows } = await this.octokit.rest.actions.listWorkflowRuns({
        owner: this.owner,
        repo: this.repo,
        per_page: 20,
        status: 'completed'
      });

      for (const run of workflows.workflow_runs) {
        if (run.conclusion !== 'success' && run.conclusion !== 'failure') continue;

        const startTime = new Date(run.run_started_at || run.created_at);
        const endTime = new Date(run.updated_at);
        const buildTime = endTime - startTime;

        if (buildTime > SLA_THRESHOLDS.build_time) {
          this.violations.push({
            type: 'build_time',
            workflow: run.name,
            run_id: run.id,
            build_time: buildTime,
            threshold: SLA_THRESHOLDS.build_time,
            severity: buildTime > SLA_THRESHOLDS.build_time * 1.5 ? 'critical' : 'high'
          });
        }
      }

      this.metrics.build_time_violations = this.violations.filter(v => 
        v.type === 'build_time'
      ).length;

      return this.violations.filter(v => v.type === 'build_time').length > 0;
    } catch (error) {
      console.error('❌ Error monitoring build times:', error);
      return false;
    }
  }

  async monitorTestExecution() {
    console.log('🧪 Monitoring Test Execution Performance...');

    try {
      const { data: workflows } = await this.octokit.rest.actions.listWorkflowRuns({
        owner: this.owner,
        repo: this.repo,
        per_page: 10
      });

      for (const run of workflows.workflow_runs) {
        if (!run.name.toLowerCase().includes('test')) continue;

        const { data: jobs } = await this.octokit.rest.actions.listJobsForWorkflowRun({
          owner: this.owner,
          repo: this.repo,
          run_id: run.id
        });

        for (const job of jobs.jobs) {
          if (job.started_at && job.completed_at) {
            const testTime = new Date(job.completed_at) - new Date(job.started_at);

            if (testTime > SLA_THRESHOLDS.test_execution) {
              this.violations.push({
                type: 'test_execution',
                job_name: job.name,
                run_id: run.id,
                execution_time: testTime,
                threshold: SLA_THRESHOLDS.test_execution,
                severity: 'medium'
              });
            }
          }
        }
      }

      this.metrics.test_execution_violations = this.violations.filter(v => 
        v.type === 'test_execution'
      ).length;

      return this.violations.filter(v => v.type === 'test_execution').length > 0;
    } catch (error) {
      console.error('❌ Error monitoring test execution:', error);
      return false;
    }
  }

  async generateReport() {
    console.log('📋 Generating SLA Report...');

    const report = {
      timestamp: new Date().toISOString(),
      epic: 'Epic 2: Workflow Automation System',
      summary: {
        total_violations: this.violations.length,
        critical_violations: this.violations.filter(v => v.severity === 'critical').length,
        high_violations: this.violations.filter(v => v.severity === 'high').length,
        medium_violations: this.violations.filter(v => v.severity === 'medium').length
      },
      metrics: this.metrics,
      violations: this.violations,
      sla_thresholds: {
        'PR Review Time': '5 minutes',
        'Build Time': '10 minutes',
        'Test Execution': '8 minutes',
        'Deployment Time': '15 minutes',
        'Agent Response': '2 minutes',
        'Task Completion': '4 hours'
      },
      recommendations: this.generateRecommendations()
    };

    // Save report
    const reportPath = path.join(__dirname, '../../reports/sla-report.json');
    await fs.mkdir(path.dirname(reportPath), { recursive: true });
    await fs.writeFile(reportPath, JSON.stringify(report, null, 2));

    // Output for GitHub Actions
    console.log(`::set-output name=total_violations::${report.summary.total_violations}`);
    console.log(`::set-output name=critical_violations::${report.summary.critical_violations}`);
    console.log(`::set-output name=report_path::${reportPath}`);

    return report;
  }

  generateRecommendations() {
    const recommendations = [];

    if (this.metrics.pr_review_violations > 0) {
      recommendations.push({
        area: 'PR Reviews',
        issue: `${this.metrics.pr_review_violations} PR review SLA violations detected`,
        solution: 'Implement automated reviewer assignment and escalation policies',
        priority: 'high'
      });
    }

    if (this.metrics.build_time_violations > 0) {
      recommendations.push({
        area: 'Build Performance',
        issue: `${this.metrics.build_time_violations} build time violations detected`,
        solution: 'Optimize CI/CD pipelines, implement build caching, parallelize jobs',
        priority: 'medium'
      });
    }

    if (this.metrics.test_execution_violations > 0) {
      recommendations.push({
        area: 'Test Performance',
        issue: `${this.metrics.test_execution_violations} test execution violations detected`,
        solution: 'Optimize test suites, implement test sharding, use faster test runners',
        priority: 'medium'
      });
    }

    return recommendations;
  }

  async updateDashboard() {
    console.log('📊 Updating SLA Dashboard...');

    // Create dashboard update comment on latest commit
    try {
      const { data: commits } = await this.octokit.rest.repos.listCommits({
        owner: this.owner,
        repo: this.repo,
        per_page: 1
      });

      if (commits.length > 0) {
        const dashboardContent = this.generateDashboardContent();

        await this.octokit.rest.repos.createCommitComment({
          owner: this.owner,
          repo: this.repo,
          commit_sha: commits[0].sha,
          body: dashboardContent
        });
      }
    } catch (error) {
      console.error('❌ Error updating dashboard:', error);
    }
  }

  generateDashboardContent() {
    const violationsByType = this.violations.reduce((acc, v) => {
      acc[v.type] = (acc[v.type] || 0) + 1;
      return acc;
    }, {});

    return `## 📊 Epic 2: SLA Monitor Dashboard

### Current Status: ${this.violations.length === 0 ? '✅ All SLAs Met' : '⚠️ Violations Detected'}

**Violations Summary:**
- **Total Violations:** ${this.violations.length}
- **Critical:** ${this.violations.filter(v => v.severity === 'critical').length}
- **High:** ${this.violations.filter(v => v.severity === 'high').length}
- **Medium:** ${this.violations.filter(v => v.severity === 'medium').length}

**Performance Metrics:**
${Object.entries(violationsByType).map(([type, count]) => 
  `- **${type.replace('_', ' ').toUpperCase()}:** ${count} violations`
).join('\n')}

**SLA Thresholds:**
- PR Review Time: ≤5 minutes
- Build Time: ≤10 minutes  
- Test Execution: ≤8 minutes
- Deployment Time: ≤15 minutes

*Last Updated: ${new Date().toISOString()}*
*Generated by Epic 2 Workflow Automation System*`;
  }
}

// Main execution
async function main() {
  const args = process.argv.slice(2);
  const monitor = new SLAMonitor();

  try {
    if (args.includes('--metric=pr_review_time')) {
      const hasViolations = await monitor.monitorPRReviewTimes();
      console.log(`::set-output name=violation::${hasViolations}`);
    } else if (args.includes('--metric=build_time')) {
      const hasViolations = await monitor.monitorBuildTimes();
      console.log(`::set-output name=violation::${hasViolations}`);
    } else if (args.includes('--metric=test_execution')) {
      const hasViolations = await monitor.monitorTestExecution();
      console.log(`::set-output name=violation::${hasViolations}`);
    } else if (args.includes('--generate-report')) {
      await monitor.monitorPRReviewTimes();
      await monitor.monitorBuildTimes();
      await monitor.monitorTestExecution();
      await monitor.generateReport();
    } else if (args.includes('--update-dashboard')) {
      await monitor.updateDashboard();
    } else {
      // Run all monitoring by default
      console.log('🚀 Starting Epic 2 SLA Monitoring...');
      await monitor.monitorPRReviewTimes();
      await monitor.monitorBuildTimes();
      await monitor.monitorTestExecution();
      await monitor.generateReport();
      await monitor.updateDashboard();

      console.log(`✅ SLA Monitoring Complete: ${monitor.violations.length} violations detected`);
    }
  } catch (error) {
    console.error('❌ SLA Monitor Error:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = { SLAMonitor };

# AI Marketing Web Builder - Commit and PR Workflow Script (PowerShell)
# Integrates with GitHub MCP Server and follows Archon workflow patterns
# Author: AI IDE Agent System
# Version: 1.0.0

param(
    [string]$TargetBranch = "main",
    [switch]$AutoCommit,
    [switch]$SkipPR,
    [string]$CommitMessage,
    [switch]$Help
)

# Configuration
$GITHUB_OWNER = "gpb360"
$GITHUB_REPO = "AI-Marketing-Web-Builder"

# Color output functions
function Write-Info { param($Message) Write-Host "[INFO] $Message" -ForegroundColor Blue }
function Write-Success { param($Message) Write-Host "[SUCCESS] $Message" -ForegroundColor Green }
function Write-Warning { param($Message) Write-Host "[WARNING] $Message" -ForegroundColor Yellow }
function Write-Error { param($Message) Write-Host "[ERROR] $Message" -ForegroundColor Red }

function Show-Help {
    Write-Host @"
AI Marketing Web Builder - Commit and PR Workflow Script

USAGE:
    .\commit-and-pr-workflow.ps1 [OPTIONS]

OPTIONS:
    -TargetBranch <branch>    Target branch for PR (default: main)
    -AutoCommit               Skip interactive commit message generation
    -SkipPR                   Don't create PR, just commit and push
    -CommitMessage <msg>      Use specific commit message
    -Help                     Show this help message

EXAMPLES:
    .\commit-and-pr-workflow.ps1
    .\commit-and-pr-workflow.ps1 -TargetBranch develop
    .\commit-and-pr-workflow.ps1 -AutoCommit -CommitMessage "feat: add new feature"
    .\commit-and-pr-workflow.ps1 -SkipPR

REQUIREMENTS:
    - Git installed and configured
    - Docker installed and running
    - GITHUB_TOKEN environment variable set
    - GitHub MCP server image available
"@
}

function Test-Prerequisites {
    Write-Info "Checking prerequisites..."

    # Check if we're in a git repository
    try {
        git rev-parse --git-dir | Out-Null
    } catch {
        Write-Error "Not in a git repository!"
        exit 1
    }

    # Check if GitHub token is configured
    if (-not $env:GITHUB_TOKEN -and -not (Get-Content .env -ErrorAction SilentlyContinue | Select-String "GITHUB_TOKEN")) {
        Write-Error "GITHUB_TOKEN not found in environment or .env file!"
        Write-Error "Please set your GitHub personal access token"
        exit 1
    }

    # Check if Docker is running
    try {
        docker info | Out-Null
    } catch {
        Write-Error "Docker is not running! GitHub MCP server requires Docker."
        exit 1
    }

    # Check if GitHub MCP server image exists
    $images = docker images --format "{{.Repository}}:{{.Tag}}" | Select-String "github-mcp-server"
    if (-not $images) {
        Write-Warning "GitHub MCP server image not found. Pulling latest version..."
        docker pull ghcr.io/github/github-mcp-server:latest
    }

    Write-Success "Prerequisites check completed"
}

function Get-CurrentBranch {
    return git branch --show-current
}

function Test-BranchNaming {
    param($BranchName)

    $validPatterns = @(
        "^[a-z-]+/[a-z-]+/[a-z0-9-]+$",  # agent-type/agent-name/feature
        "^feature/[0-9.]+-.+$",           # feature/story-number-description
        "^hotfix/.+$",                    # hotfix/description
        "^bugfix/.+$"                     # bugfix/description
    )

    $isValid = $false
    foreach ($pattern in $validPatterns) {
        if ($BranchName -match $pattern) {
            $isValid = $true
            break
        }
    }

    if (-not $isValid) {
        Write-Warning "Branch name '$BranchName' doesn't follow standard conventions"
        Write-Warning "Recommended patterns:"
        Write-Warning "  - agent-type/agent-name/feature-description"
        Write-Warning "  - feature/story-number-description"
        Write-Warning "  - hotfix/description"
        Write-Warning "Proceeding anyway..."
    }
}

function Invoke-PreCommitChecks {
    Write-Info "Running pre-commit validation checks..."

    # Check if changes exist
    $stagedChanges = git diff --staged --name-only
    if (-not $stagedChanges) {
        Write-Error "No staged changes found! Please stage your changes first."
        exit 1
    }

    # Check for large files
    Write-Info "Checking for large files..."
    foreach ($file in $stagedChanges) {
        if (Test-Path $file) {
            $fileSize = (Get-Item $file).Length
            if ($fileSize -gt 10MB) {
                Write-Warning "Large file detected: $file ($(($fileSize/1MB).ToString('F1'))MB)"
            }
        }
    }

    # Check for sensitive files
    Write-Info "Checking for sensitive files..."
    $sensitivePatterns = @("*.key", "*.pem", "*.p12", "*.pfx", ".env", "*.env", "secrets.*")
    foreach ($pattern in $sensitivePatterns) {
        $matches = $stagedChanges | Where-Object { $_ -like $pattern }
        if ($matches) {
            Write-Warning "Potentially sensitive files detected: $($matches -join ', ')"
        }
    }

    # Frontend checks
    if (Test-Path "web-builder\package.json") {
        Write-Info "Running frontend checks..."
        Push-Location "web-builder"

        if (-not (Test-Path "pnpm-lock.yaml") -and (Test-Path "package.json")) {
            Write-Warning "pnpm-lock.yaml not found. Consider running 'pnpm install'"
        }

        # TypeScript type check
        if (Get-Command pnpm -ErrorAction SilentlyContinue) {
            Write-Info "Running TypeScript type check..."
            try {
                pnpm run type-check
            } catch {
                Write-Warning "TypeScript type check failed"
            }
        }

        Pop-Location
    }

    # Backend checks
    if (Test-Path "backend\requirements.txt") {
        Write-Info "Running backend checks..."
        if (-not $env:VIRTUAL_ENV) {
            Write-Warning "Virtual environment not activated"
        }
    }

    Write-Success "Pre-commit checks completed"
}

function New-ConventionalCommitMessage {
    Write-Host "`n🚀 Conventional Commit Message Generator"
    Write-Host "========================================"

    $commitTypes = @{
        1 = @{type="feat"; desc="New feature"}
        2 = @{type="fix"; desc="Bug fix"}
        3 = @{type="docs"; desc="Documentation"}
        4 = @{type="style"; desc="Formatting, missing semicolons, etc"}
        5 = @{type="refactor"; desc="Code change that neither fixes a bug nor adds a feature"}
        6 = @{type="perf"; desc="Performance improvements"}
        7 = @{type="test"; desc="Adding or updating tests"}
        8 = @{type="build"; desc="Build system or external dependencies"}
        9 = @{type="ci"; desc="CI/CD changes"}
        10 = @{type="chore"; desc="Other changes that don't modify src or test files"}
    }

    Write-Host "Select commit type:"
    foreach ($key in $commitTypes.Keys | Sort-Object) {
        Write-Host "$key) $($commitTypes[$key].type) - $($commitTypes[$key].desc)"
    }

    do {
        $choice = Read-Host "Enter choice (1-10)"
        $choiceInt = [int]$choice
    } while ($choiceInt -lt 1 -or $choiceInt -gt 10)

    $commitType = $commitTypes[$choiceInt].type

    $scope = Read-Host "Enter scope (optional, e.g., auth, api, ui)"
    $description = Read-Host "Enter short description"
    $isBreaking = (Read-Host "Is this a breaking change? (y/N)") -match "^[Yy]"

    $breakingMarker = if ($isBreaking) { "!" } else { "" }

    $commitMsg = if ($scope) {
        "$commitType($scope)$breakingMarker`: $description"
    } else {
        "$commitType$breakingMarker`: $description"
    }

    if ($isBreaking) {
        $breakingDetails = Read-Host "Enter detailed description of breaking changes"
        $commitMsg += "`n`nBREAKING CHANGE: $breakingDetails"
    } else {
        $body = Read-Host "Enter detailed commit body (optional, press Enter to skip)"
        if ($body) {
            $commitMsg += "`n`n$body"
        }
    }

    return $commitMsg
}

function Invoke-GitCommit {
    param($Message)

    Write-Info "Committing changes..."
    try {
        git commit --no-verify -m $Message
        Write-Success "Changes committed successfully!"
    } catch {
        Write-Error "Commit failed: $_"
        exit 1
    }
}

function Push-Branch {
    param($BranchName)

    Write-Info "Pushing branch '$BranchName' to origin..."

    $maxRetries = 3
    for ($i = 1; $i -le $maxRetries; $i++) {
        try {
            git push --no-verify origin $BranchName
            Write-Success "Branch pushed successfully!"
            return
        } catch {
            if ($i -lt $maxRetries) {
                Write-Warning "Push failed, retrying in 5 seconds... (attempt $i/$maxRetries)"
                Start-Sleep -Seconds 5
            }
        }
    }

    Write-Error "Failed to push branch after $maxRetries attempts"
    exit 1
}

function New-GitHubPR {
    param(
        $HeadBranch,
        $BaseBranch,
        $Title,
        $Body
    )

    Write-Info "Creating pull request using GitHub MCP server..."

    # Load GitHub token from environment or .env file
    $githubToken = $env:GITHUB_TOKEN
    if (-not $githubToken) {
        $envContent = Get-Content .env -ErrorAction SilentlyContinue
        $tokenLine = $envContent | Select-String "GITHUB_TOKEN=(.+)" | Select-Object -First 1
        if ($tokenLine) {
            $githubToken = $tokenLine.Matches[0].Groups[1].Value
        }
    }

    if (-not $githubToken) {
        Write-Error "GitHub token not found!"
        return
    }

    # Prepare MCP command
    $prData = @{
        owner = $GITHUB_OWNER
        repo = $GITHUB_REPO
        title = $Title
        head = $HeadBranch
        base = $BaseBranch
        body = $Body
    } | ConvertTo-Json -Compress

    Write-Info "PR Data prepared: $Title"

    try {
        # Use GitHub MCP server via Docker
        $env:GITHUB_PERSONAL_ACCESS_TOKEN = $githubToken
        $result = $prData | docker run --rm -i --env GITHUB_PERSONAL_ACCESS_TOKEN ghcr.io/github/github-mcp-server:latest

        Write-Success "Pull request created successfully!"
        Write-Info "Result: $result"
    } catch {
        Write-Warning "GitHub MCP creation failed, providing manual instructions..."
        Write-Info "Please create PR manually at:"
        Write-Info "https://github.com/$GITHUB_OWNER/$GITHUB_REPO/compare/$HeadBranch"
        Write-Info "Title: $Title"
        Write-Info "Body: $Body"
    }
}

function Main {
    if ($Help) {
        Show-Help
        return
    }

    Write-Info "🚀 AI Marketing Web Builder - Commit and PR Workflow"
    Write-Info "======================================================"

    # Prerequisites
    Test-Prerequisites

    # Get current branch
    $currentBranch = Get-CurrentBranch
    Write-Info "Current branch: $currentBranch"

    # Validate branch name
    Test-BranchNaming $currentBranch

    # Check for changes
    $hasUnstagedChanges = git diff --quiet; $LASTEXITCODE -ne 0
    $hasStagedChanges = git diff --staged --quiet; $LASTEXITCODE -ne 0

    if (-not $hasUnstagedChanges -and -not $hasStagedChanges) {
        Write-Error "No changes detected! Please make some changes first."
        exit 1
    }

    # Stage changes if needed
    if (-not $hasStagedChanges) {
        Write-Info "Staging all changes..."
        git add .
    }

    # Run pre-commit checks  
    Invoke-PreCommitChecks

    # Handle commit message
    if ($CommitMessage) {
        $message = $CommitMessage
    } elseif ($AutoCommit) {
        $lastCommit = git log -1 --format="%s"
        $message = "feat: $lastCommit"
    } else {
        $generateInteractive = (Read-Host "Generate conventional commit message interactively? (y/N)") -match "^[Yy]"
        if ($generateInteractive) {
            $message = New-ConventionalCommitMessage
        } else {
            $message = Read-Host "Enter commit message"
        }
    }

    # Commit changes
    Invoke-GitCommit $message

    # Push branch
    Push-Branch $currentBranch

    # Create PR
    if (-not $SkipPR) {
        $createPR = (Read-Host "Create pull request? (y/N)") -match "^[Yy]"
        if ($createPR) {
            $targetBranch = if ($TargetBranch) { $TargetBranch } else { Read-Host "Target branch (default: main)" }
            if (-not $targetBranch) { $targetBranch = "main" }

            # Generate PR details
            $agentName = ($currentBranch -split "/")[1]
            $prTitle = "[$($agentName.ToUpper())] $(git log -1 --format='%s')"

            $prBody = @"
## Summary
Automated PR creation from branch: ``$currentBranch``

## Changes
$(git log --oneline $targetBranch..$currentBranch | Select-Object -First 10 | Out-String)

## Testing
- [ ] Unit tests pass
- [ ] Integration tests pass
- [ ] Manual testing completed  
- [ ] E2E tests pass (if applicable)

## Checklist
- [x] Code follows project conventions
- [x] Commit messages follow conventional commit format
- [x] Pre-commit checks passed
- [ ] Documentation updated (if needed)
- [ ] Breaking changes documented (if any)

## Archon Integration
- Branch: ``$currentBranch``
- Agent: $agentName
- Task Status: Ready for Review

---
*This PR was created automatically using the GitHub MCP workflow script.*
"@

            New-GitHubPR -HeadBranch $currentBranch -BaseBranch $targetBranch -Title $prTitle -Body $prBody
        }
    }

    Write-Success "🎉 Workflow completed successfully!"
    Write-Info "Next steps:"
    Write-Info "1. Review the pull request on GitHub"
    Write-Info "2. Address any review comments"
    Write-Info "3. Merge when approved"
}

# Execute main function
Main

# AI Marketing Web Builder - Pre-commit Validation Script (PowerShell)
# Comprehensive quality checks before commits
# Author: AI IDE Agent System
# Version: 1.0.0

param(
    [string]$CommitMessageFile,
    [switch]$SkipWarnings,
    [switch]$Help
)

# Configuration
$MAX_FILE_SIZE_MB = 10
$MAX_LINE_LENGTH = 120
$PROJECT_ROOT = git rev-parse --show-toplevel

# Counters
$script:Warnings = 0
$script:Errors = 0

# Color output functions
function Write-Info { param($Message) Write-Host "[INFO] $Message" -ForegroundColor Blue }
function Write-Success { param($Message) Write-Host "[SUCCESS] $Message" -ForegroundColor Green }
function Write-Warning { 
    param($Message) 
    Write-Host "[WARNING] $Message" -ForegroundColor Yellow
    $script:Warnings++
}
function Write-Error { 
    param($Message) 
    Write-Host "[ERROR] $Message" -ForegroundColor Red
    $script:Errors++
}

function Show-Help {
    Write-Host @"
AI Marketing Web Builder - Pre-commit Validation Script

USAGE:
    .\pre-commit-validation.ps1 [OPTIONS]

OPTIONS:
    -CommitMessageFile <file>  Path to commit message file for validation
    -SkipWarnings              Don't prompt for warnings, auto-continue
    -Help                      Show this help message

DESCRIPTION:
    Comprehensive pre-commit validation including:
    - File size checks
    - Sensitive file detection
    - Secret scanning
    - Code quality checks
    - Line length validation
    - JSON validation
    - Branch protection compliance
    - Frontend/backend specific checks

EXAMPLES:
    .\pre-commit-validation.ps1
    .\pre-commit-validation.ps1 -CommitMessageFile .git\COMMIT_EDITMSG
    .\pre-commit-validation.ps1 -SkipWarnings
"@
}

function Test-Command {
    param($CommandName)
    return Get-Command $CommandName -ErrorAction SilentlyContinue
}

function Test-FileSizes {
    Write-Info "Checking file sizes..."

    $stagedFiles = git diff --cached --name-only
    $largeFiles = @()

    foreach ($file in $stagedFiles) {
        if (Test-Path $file) {
            $sizeBytes = (Get-Item $file).Length
            $sizeMB = [math]::Round($sizeBytes / 1MB, 2)

            if ($sizeMB -gt $MAX_FILE_SIZE_MB) {
                $largeFiles += "$file (${sizeMB}MB)"
            }
        }
    }

    if ($largeFiles.Count -gt 0) {
        Write-Warning "Large files detected (>$MAX_FILE_SIZE_MB MB):"
        foreach ($file in $largeFiles) {
            Write-Warning "  - $file"
        }
    } else {
        Write-Success "File size check passed"
    }
}

function Test-SensitiveFiles {
    Write-Info "Checking for sensitive files..."

    $sensitivePatterns = @(
        "*.key", "*.pem", "*.p12", "*.pfx", "*.crt", "*.cert",
        "id_rsa", "id_dsa", "*.env", "secrets.*", "*.secret",
        "config/database.yml", "config/secrets.yml"
    )

    $stagedFiles = git diff --cached --name-only
    $sensitiveFiles = @()

    foreach ($pattern in $sensitivePatterns) {
        $matches = $stagedFiles | Where-Object { $_ -like $pattern }
        $sensitiveFiles += $matches
    }

    if ($sensitiveFiles.Count -gt 0) {
        Write-Error "Potentially sensitive files detected:"
        foreach ($file in $sensitiveFiles) {
            Write-Error "  - $file"
        }
        Write-Error "Please remove sensitive files or add them to .gitignore"
    } else {
        Write-Success "Sensitive file check passed"
    }
}

function Test-SecretsInContent {
    Write-Info "Scanning for secrets in code..."

    $secretPatterns = @(
        "password\s*=\s*['\`"][^'\`"]+['\`"]",
        "api[_-]?key\s*=\s*['\`"][^'\`"]+['\`"]",
        "secret[_-]?key\s*=\s*['\`"][^'\`"]+['\`"]",
        "access[_-]?token\s*=\s*['\`"][^'\`"]+['\`"]",
        "private[_-]?key\s*=\s*['\`"][^'\`"]+['\`"]",
        "['\`"]ghp_[a-zA-Z0-9]{36}['\`"]",  # GitHub personal access tokens
        "['\`"]sk-[a-zA-Z0-9]{48}['\`"]",   # OpenAI API keys
        "['\`"]xoxb-[a-zA-Z0-9-]+['\`"]"    # Slack bot tokens
    )

    $secretsFound = $false
    $diffContent = git diff --cached

    foreach ($pattern in $secretPatterns) {
        $matches = $diffContent | Select-String -Pattern $pattern -AllMatches
        if ($matches) {
            $secretsFound = $true
            foreach ($match in $matches) {
                Write-Error "Potential secret found: $($match.Line.Trim())"
            }
        }
    }

    if (-not $secretsFound) {
        Write-Success "Secret scanning passed"
    }
}

function Test-CommitMessage {
    param($MessageFile)

    if (-not $MessageFile -or -not (Test-Path $MessageFile)) {
        return
    }

    Write-Info "Validating commit message format..."

    $commitMsg = Get-Content $MessageFile -Raw | Out-String
    $commitMsg = $commitMsg.Trim()

    # Conventional commit pattern
    $conventionalPattern = "^(feat|fix|docs|style|refactor|perf|test|build|ci|chore)(\(.+\))?!?: .+"

    if ($commitMsg -notmatch $conventionalPattern) {
        Write-Warning "Commit message doesn't follow conventional commit format"
        Write-Warning "Expected format: type(scope): description"
        Write-Warning "Types: feat, fix, docs, style, refactor, perf, test, build, ci, chore"
        Write-Warning "Current message: $commitMsg"
    } else {
        Write-Success "Commit message format is valid"
    }
}

function Test-LineLengths {
    Write-Info "Checking line lengths..."

    $stagedFiles = git diff --cached --name-only
    $codeFiles = $stagedFiles | Where-Object { $_ -match "\.(js|ts|jsx|tsx|py|sh|bash|ps1)$" }
    $longLines = @()

    foreach ($file in $codeFiles) {
        if (Test-Path $file) {
            $lines = Get-Content $file
            for ($i = 0; $i -lt $lines.Count; $i++) {
                if ($lines[$i].Length -gt $MAX_LINE_LENGTH) {
                    $longLines += "$file`:$($i+1): $($lines[$i].Substring(0, [Math]::Min(100, $lines[$i].Length)))..."
                    if ($longLines.Count -ge 5) { break }  # Limit output
                }
            }
        }
    }

    if ($longLines.Count -gt 0) {
        Write-Warning "Lines longer than $MAX_LINE_LENGTH characters found:"
        foreach ($line in $longLines) {
            Write-Warning "  - $line"
        }
    } else {
        Write-Success "Line length check passed"
    }
}

function Test-Frontend {
    $packageJsonPath = Join-Path $PROJECT_ROOT "web-builder\package.json"
    if (-not (Test-Path $packageJsonPath)) {
        return
    }

    Write-Info "Running frontend checks..."

    Push-Location (Join-Path $PROJECT_ROOT "web-builder")

    try {
        # Check for lockfile consistency
        $hasPackageLock = Test-Path "package-lock.json"
        $hasPnpmLock = Test-Path "pnpm-lock.yaml"

        if ($hasPackageLock -and $hasPnpmLock) {
            Write-Warning "Both package-lock.json and pnpm-lock.yaml found"
            Write-Warning "Consider using only one package manager"
        }

        # Check if pnpm is preferred but not installed
        if ($hasPnpmLock -and -not (Test-Command pnpm)) {
            Write-Error "pnpm-lock.yaml found but pnpm is not installed"
            Write-Error "Install pnpm: npm install -g pnpm"
        }

        # Run type checking if TypeScript is configured
        if (Test-Path "tsconfig.json") {
            $packageManager = if (Test-Command pnpm) { "pnpm" } elseif (Test-Command npm) { "npm" } else { $null }

            if ($packageManager) {
                Write-Info "Running TypeScript type check..."
                try {
                    & $packageManager run type-check 2>$null
                    Write-Success "TypeScript type check passed"
                } catch {
                    Write-Warning "TypeScript type check failed or type-check script not found"
                }
            }
        }

        # Run linting if configured
        $packageManager = if (Test-Command pnpm) { "pnpm" } elseif (Test-Command npm) { "npm" } else { $null }

        if ($packageManager) {
            try {
                & $packageManager run lint 2>$null
                Write-Success "Linting passed"
            } catch {
                Write-Warning "Linting failed or lint script not found"
            }
        }

        # Check for outdated dependencies (informational)
        if (Test-Command pnpm) {
            Write-Info "Checking for outdated dependencies..."
            try {
                $outdated = & pnpm outdated --format=table 2>$null
                if ($outdated -and $outdated.Count -gt 1) {
                    Write-Warning "$($outdated.Count - 1) outdated dependencies found"
                    Write-Warning "Run 'pnpm outdated' to see details"
                }
            } catch {
                # Ignore errors in outdated check
            }
        }
    }
    finally {
        Pop-Location
    }
}

function Test-Backend {
    $requirementsPath = Join-Path $PROJECT_ROOT "backend\requirements.txt"
    if (-not (Test-Path $requirementsPath)) {
        return
    }

    Write-Info "Running backend checks..."

    Push-Location (Join-Path $PROJECT_ROOT "backend")

    try {
        # Check if virtual environment is activated
        if (-not $env:VIRTUAL_ENV) {
            Write-Warning "Virtual environment not activated"
            Write-Warning "Activate with: venv\Scripts\activate (Windows) or source venv/bin/activate (Unix)"
        }

        # Check Python version if python is available
        if (Test-Command python) {
            $pythonVersion = python --version 2>&1
            Write-Info "Python version: $pythonVersion"

            # Check if requirements are satisfied
            if (Test-Command pip) {
                Write-Info "Checking Python requirements..."
                try {
                    pip check 2>$null
                    Write-Success "Python requirements check passed"
                } catch {
                    Write-Warning "Python requirements check failed"
                    Write-Warning "Run 'pip check' for details"
                }
            }
        }

        # Run flake8 if available
        if (Test-Command flake8) {
            Write-Info "Running flake8 linting..."
            try {
                flake8 . --max-line-length=120 --exclude=venv,migrations 2>$null
                Write-Success "Flake8 linting passed"
            } catch {
                Write-Warning "Flake8 linting found issues"
            }
        }

        # Run mypy if available
        if (Test-Command mypy) {
            Write-Info "Running mypy type checking..."
            try {
                mypy . --ignore-missing-imports 2>$null
                Write-Success "MyPy type checking passed"
            } catch {
                Write-Warning "MyPy type checking found issues"
            }
        }
    }
    finally {
        Pop-Location
    }
}

function Test-GitHooks {
    Write-Info "Checking git hooks setup..."

    $hooksDir = Join-Path $PROJECT_ROOT ".git\hooks"
    $preCommitHook = Join-Path $hooksDir "pre-commit"

    if (Test-Path $preCommitHook) {
        Write-Success "Pre-commit hook is configured"
    } else {
        Write-Warning "Pre-commit hook not found"
        Write-Warning "Consider setting up pre-commit hooks for automated validation"
    }
}

function Test-TodoComments {
    Write-Info "Checking for TODO/FIXME comments..."

    $todoPatterns = @("TODO", "FIXME", "HACK", "XXX")
    $todoFound = $false
    $diffContent = git diff --cached

    foreach ($pattern in $todoPatterns) {
        $matches = $diffContent | Select-String -Pattern $pattern
        if ($matches) {
            $todoFound = $true
            foreach ($match in $matches) {
                Write-Warning "Found $pattern`: $($match.Line.Trim())"
            }
        }
    }

    if (-not $todoFound) {
        Write-Success "No TODO/FIXME comments in staged changes"
    }
}

function Test-JsonFiles {
    Write-Info "Validating JSON files..."

    $stagedFiles = git diff --cached --name-only
    $jsonFiles = $stagedFiles | Where-Object { $_ -match "\.json$" }
    $jsonErrors = $false

    foreach ($file in $jsonFiles) {
        if (Test-Path $file) {
            try {
                Get-Content $file | ConvertFrom-Json | Out-Null
            } catch {
                Write-Error "Invalid JSON format in $file`: $($_.Exception.Message)"
                $jsonErrors = $true
            }
        }
    }

    if (-not $jsonErrors -and $jsonFiles.Count -gt 0) {
        Write-Success "JSON validation passed for $($jsonFiles.Count) files"
    } elseif ($jsonFiles.Count -eq 0) {
        Write-Success "No JSON files to validate"
    }
}

function Test-BranchProtection {
    Write-Info "Checking branch protection compliance..."

    $currentBranch = git branch --show-current

    # Check if trying to commit directly to main/master
    if ($currentBranch -eq "main" -or $currentBranch -eq "master") {
        Write-Error "Direct commits to $currentBranch are not allowed"
        Write-Error "Create a feature branch and submit a pull request"
    } else {
        Write-Success "Branch protection compliance check passed"
    }
}

function Main {
    if ($Help) {
        Show-Help
        return
    }

    Write-Info "🔒 AI Marketing Web Builder - Pre-commit Validation"
    Write-Info "=================================================="

    # Check if there are staged changes
    $stagedChanges = git diff --cached --name-only
    if (-not $stagedChanges) {
        Write-Error "No staged changes found!"
        exit 1
    }

    # Run all checks
    Test-FileSizes
    Test-SensitiveFiles
    Test-SecretsInContent
    Test-LineLengths
    Test-TodoComments
    Test-JsonFiles
    Test-BranchProtection
    Test-Frontend
    Test-Backend
    Test-GitHooks

    # Validate commit message if provided
    if ($CommitMessageFile) {
        Test-CommitMessage $CommitMessageFile
    }

    # Summary
    Write-Info "=================================================="
    Write-Info "Pre-commit validation summary:"

    if ($script:Errors -gt 0) {
        Write-Error "❌ $($script:Errors) error(s) found"
        Write-Error "Please fix the errors before committing"
        exit 1
    } elseif ($script:Warnings -gt 0) {
        Write-Warning "⚠️  $($script:Warnings) warning(s) found"
        Write-Warning "Consider addressing the warnings"

        # Allow commit with warnings but ask for confirmation
        if (-not $SkipWarnings) {
            $continue = Read-Host "Continue with commit despite warnings? (y/N)"
            if ($continue -notmatch "^[Yy]$") {
                Write-Info "Commit aborted by user"
                exit 1
            }
        }
    } else {
        Write-Success "✅ All checks passed!"
    }

    Write-Success "Pre-commit validation completed successfully"
}

# Execute main function
Main

# AI Marketing Web Builder - Git Configuration Setup Script
# Configures git for conventional commits and quality standards
# Author: AI IDE Agent System
# Version: 1.0.0

param(
    [switch]$Force,
    [switch]$Help
)

function Show-Help {
    Write-Host @"
AI Marketing Web Builder - Git Configuration Setup

USAGE:
    .\setup-git-config.ps1 [OPTIONS]

OPTIONS:
    -Force    Overwrite existing git configuration
    -Help     Show this help message

DESCRIPTION:
    This script configures git for the AI Marketing Web Builder project with:
    - Conventional commit message template
    - Git hooks for commit message validation
    - Recommended git settings for the project
    - Branch protection and workflow standards

WHAT IT DOES:
    1. Sets commit message template (.gitmessage)
    2. Configures git hooks (commit-msg, pre-commit)
    3. Sets recommended git configuration
    4. Creates helper aliases for conventional commits
    5. Configures branch protection preferences

EXAMPLES:
    .\setup-git-config.ps1
    .\setup-git-config.ps1 -Force
"@
}

function Write-Info { param($Message) Write-Host "[INFO] $Message" -ForegroundColor Blue }
function Write-Success { param($Message) Write-Host "[SUCCESS] $Message" -ForegroundColor Green }
function Write-Warning { param($Message) Write-Host "[WARNING] $Message" -ForegroundColor Yellow }
function Write-Error { param($Message) Write-Host "[ERROR] $Message" -ForegroundColor Red }

function Test-GitRepository {
    try {
        git rev-parse --git-dir | Out-Null
        return $true
    } catch {
        return $false
    }
}

function Set-GitCommitTemplate {
    Write-Info "Setting up commit message template..."

    $templatePath = ".gitmessage"
    if (Test-Path $templatePath) {
        try {
            git config commit.template $templatePath
            Write-Success "Commit template configured: $templatePath"
        } catch {
            Write-Error "Failed to set commit template: $_"
        }
    } else {
        Write-Warning "Commit template file not found: $templatePath"
    }
}

function Set-GitHooks {
    Write-Info "Setting up git hooks..."

    $hooksDir = ".git\hooks"

    # Ensure hooks directory exists
    if (-not (Test-Path $hooksDir)) {
        New-Item -ItemType Directory -Path $hooksDir -Force | Out-Null
    }

    # Set up commit-msg hook
    $commitMsgHook = Join-Path $hooksDir "commit-msg"
    if (Test-Path $commitMsgHook) {
        Write-Success "commit-msg hook already exists"

        # Make sure it's executable (Windows doesn't need chmod, but we'll ensure the script works)
        try {
            # Test the hook by checking if it contains our validation logic
            $hookContent = Get-Content $commitMsgHook -Raw
            if ($hookContent -match "conventional commit") {
                Write-Success "commit-msg hook is properly configured"
            } else {
                Write-Warning "commit-msg hook exists but may not be the expected version"
            }
        } catch {
            Write-Warning "Could not verify commit-msg hook content"
        }
    } else {
        Write-Warning "commit-msg hook not found at: $commitMsgHook"
        Write-Warning "Please ensure the hook file exists and is properly configured"
    }

    # Set up pre-commit hook (if validation script exists)
    $preCommitHook = Join-Path $hooksDir "pre-commit"
    $validationScript = "scripts\pre-commit-validation.ps1"

    if (Test-Path $validationScript) {
        $hookContent = @"
#!/bin/bash
# AI Marketing Web Builder - Pre-commit Hook
# Runs pre-commit validation script

# Run PowerShell validation script
powershell.exe -ExecutionPolicy Bypass -File "scripts/pre-commit-validation.ps1"
exit_code=$?

if [ $exit_code -ne 0 ]; then
    echo "Pre-commit validation failed. Commit aborted."
    exit $exit_code
fi

exit 0
"@

        if (-not (Test-Path $preCommitHook) -or $Force) {
            $hookContent | Out-File -FilePath $preCommitHook -Encoding ASCII
            Write-Success "pre-commit hook configured"
        } else {
            Write-Info "pre-commit hook already exists (use -Force to overwrite)"
        }
    } else {
        Write-Warning "Pre-commit validation script not found: $validationScript"
    }
}

function Set-GitConfiguration {
    Write-Info "Configuring git settings..."

    # Core settings
    try {
        # Set line ending handling
        git config core.autocrlf true
        Write-Success "Configured line ending handling (autocrlf=true)"

        # Set default branch name
        git config init.defaultBranch main
        Write-Success "Set default branch name to 'main'"

        # Configure merge strategy
        git config pull.rebase false
        Write-Success "Configured pull strategy (merge, not rebase)"

        # Set push behavior
        git config push.default simple
        Write-Success "Set push default to 'simple'"

        # Configure editor (if not already set)
        $currentEditor = git config --get core.editor
        if (-not $currentEditor) {
            # Try to set a reasonable default editor
            if (Get-Command code -ErrorAction SilentlyContinue) {
                git config core.editor "code --wait"
                Write-Success "Set editor to VS Code"
            } elseif (Get-Command notepad -ErrorAction SilentlyContinue) {
                git config core.editor "notepad"
                Write-Success "Set editor to Notepad"
            }
        } else {
            Write-Info "Editor already configured: $currentEditor"
        }

    } catch {
        Write-Error "Failed to configure git settings: $_"
    }
}

function Set-GitAliases {
    Write-Info "Setting up helpful git aliases..."

    $aliases = @{
        "co" = "checkout"
        "br" = "branch"
        "ci" = "commit"
        "st" = "status"
        "unstage" = "reset HEAD --"
        "last" = "log -1 HEAD"
        "visual" = "!gitk"
        "type-check" = "!powershell.exe -ExecutionPolicy Bypass -File scripts/pre-commit-validation.ps1"
        "conventional" = "!f() { echo 'Conventional commit types:'; echo 'feat: New feature'; echo 'fix: Bug fix'; echo 'docs: Documentation'; echo 'style: Formatting'; echo 'refactor: Code restructuring'; echo 'perf: Performance'; echo 'test: Tests'; echo 'build: Build system'; echo 'ci: CI/CD'; echo 'chore: Maintenance'; }; f"
        "pr-ready" = "!powershell.exe -ExecutionPolicy Bypass -File scripts/commit-and-pr-workflow.ps1"
    }

    foreach ($alias in $aliases.GetEnumerator()) {
        try {
            $existing = git config --get alias.$($alias.Key) 2>$null
            if (-not $existing -or $Force) {
                git config alias.$($alias.Key) $($alias.Value)
                Write-Success "Set alias: git $($alias.Key) = $($alias.Value)"
            } else {
                Write-Info "Alias already exists: git $($alias.Key) (use -Force to overwrite)"
            }
        } catch {
            Write-Warning "Failed to set alias $($alias.Key): $_"
        }
    }
}

function Set-ProjectSettings {
    Write-Info "Configuring project-specific settings..."

    # Set up gitignore patterns for this project
    $gitignorePath = ".gitignore"
    if (Test-Path $gitignorePath) {
        Write-Success "Project .gitignore already exists"
    } else {
        Write-Warning ".gitignore file not found - consider creating one"
    }

    # Configure GitHub integration
    try {
        $origin = git config --get remote.origin.url
        if ($origin) {
            Write-Success "Remote origin configured: $origin"

            # Extract repository info for GitHub MCP
            if ($origin -match "github\.com[:/]([^/]+)/([^/.]+)") {
                $owner = $matches[1]
                $repo = $matches[2]
                Write-Info "Detected GitHub repository: $owner/$repo"
            }
        } else {
            Write-Warning "No remote origin configured"
        }
    } catch {
        Write-Warning "Could not check remote configuration"
    }
}

function Test-Configuration {
    Write-Info "Testing git configuration..."

    # Test commit template
    $template = git config --get commit.template
    if ($template) {
        if (Test-Path $template) {
            Write-Success "✅ Commit template: $template"
        } else {
            Write-Error "❌ Commit template file not found: $template"
        }
    } else {
        Write-Warning "⚠️  No commit template configured"
    }

    # Test hooks
    $hooksDir = ".git\hooks"
    $hooks = @("commit-msg", "pre-commit")

    foreach ($hook in $hooks) {
        $hookPath = Join-Path $hooksDir $hook
        if (Test-Path $hookPath) {
            Write-Success "✅ Hook configured: $hook"
        } else {
            Write-Warning "⚠️  Hook not found: $hook"
        }
    }

    # Test aliases
    $testAliases = @("conventional", "pr-ready", "type-check")
    foreach ($alias in $testAliases) {
        $aliasValue = git config --get alias.$alias
        if ($aliasValue) {
            Write-Success "✅ Alias configured: git $alias"
        } else {
            Write-Warning "⚠️  Alias not configured: git $alias"
        }
    }
}

function Main {
    if ($Help) {
        Show-Help
        return
    }

    Write-Info "🔧 AI Marketing Web Builder - Git Configuration Setup"
    Write-Info "====================================================="

    # Check if we're in a git repository
    if (-not (Test-GitRepository)) {
        Write-Error "Not in a git repository! Please run this script from the project root."
        exit 1
    }

    Write-Info "Setting up git configuration for AI Marketing Web Builder..."

    # Run configuration steps
    Set-GitCommitTemplate
    Set-GitHooks
    Set-GitConfiguration
    Set-GitAliases
    Set-ProjectSettings

    Write-Info "====================================================="
    Write-Info "Testing configuration..."
    Test-Configuration

    Write-Success "🎉 Git configuration setup completed!"
    Write-Info ""
    Write-Info "Next steps:"
    Write-Info "1. Try 'git conventional' to see commit types"
    Write-Info "2. Use 'git pr-ready' to run the full workflow"
    Write-Info "3. Commit messages will now be validated automatically"
    Write-Info "4. Pre-commit checks will run before each commit"
    Write-Info ""
    Write-Info "For help with conventional commits, check the .gitmessage template"
}

