const categories = [
  { id: 'all', name: 'All Templates', count: 8, icon: '🎯' },
  { id: 'SaaS', name: 'SaaS', count: 1, icon: '💼' },
  { id: 'E-commerce', name: 'E-commerce', count: 1, icon: '🛒' },
  { id: 'Agency', name: 'Agency', count: 1, icon: '🏢' },
  { id: 'Startup', name: 'Startup', count: 1, icon: '🚀' },
