// Visual regression test helpers
export const themeValidationHelpers = {
  checkColorConsistency: (element: HTMLElement, expectedColors: string[]) => {
    const computedStyle = window.getComputedStyle(element);
    const backgroundColor = computedStyle.backgroundColor;
    const textColor = computedStyle.color;

    return expectedColors.some(color => 
      backgroundColor.includes(color) || textColor.includes(color)
    );
  },

  checkElevationConsistency: (element: HTMLElement) => {
    const computedStyle = window.getComputedStyle(element);
    const boxShadow = computedStyle.boxShadow;
    return boxShadow !== 'none';
  },

  checkTypographyConsistency: (element: HTMLElement) => {
    const computedStyle = window.getComputedStyle(element);
    const fontFamily = computedStyle.fontFamily;
    const fontSize = computedStyle.fontSize;

    return fontFamily && fontSize;
  },
};

// Integration test utilities
export const integrationTestUtils = {
  simulateDragAndDrop: async (draggableSelector: string, dropTargetSelector: string) => {
    const draggable = document.querySelector(draggableSelector);
    const dropTarget = document.querySelector(dropTargetSelector);

    if (!draggable || !dropTarget) {
      throw new Error('Elements not found for drag and drop simulation');
    }

    // Create drag events
    const dragStartEvent = new DragEvent('dragstart', {
      bubbles: true,
      cancelable: true,
    });

    const dragOverEvent = new DragEvent('dragover', {
      bubbles: true,
      cancelable: true,
    });

    const dropEvent = new DragEvent('drop', {
      bubbles: true,
      cancelable: true,
    });

    draggable.dispatchEvent(dragStartEvent);
    dropTarget.dispatchEvent(dragOverEvent);
    dropTarget.dispatchEvent(dropEvent);

    await waitFor(() => {
      expect(dropTarget).toHaveClass('bg-blue-50');
    });
  },

  validateComponentGeneration: async (description: string, expectedCode: string) => {
    const descriptionInput = screen.getByPlaceholderText('Describe your component...');
    fireEvent.change(descriptionInput, { target: { value: description } });

    const generateButton = screen.getByText('Generate Component');
    fireEvent.click(generateButton);

    await waitFor(() => {
      expect(screen.getByText('Component Generated Successfully!')).toBeInTheDocument();
    });

    const codePreview = screen.getByRole('textbox');
    expect(codePreview).toContain(expectedCode);
  },
};

// Performance test utilities
export const performanceTestUtils = {
  measureRenderTime: async (component: React.ReactElement) => {
    const startTime = performance.now();
    render(component);
    const endTime = performance.now();

    return endTime - startTime;
  },

  measureInteractionTime: async (interaction: () => void) => {
    const startTime = performance.now();
    interaction();
    const endTime = performance.now();

    return endTime - startTime;
  },
};

// AI Editing System - Main exports
export { ComponentEditorWithAI } from '../ComponentEditorWithAI';
export { IntegratedEditor } from '../IntegratedEditor';
export { EnhancedCanvas } from '../builder/EnhancedCanvas';
export { AICustomizationPanel } from '../builder/AICustomizationPanel';

// Hooks
export { useAIEditor } from '@/hooks/useAIEditor';

// Types
export type { AIEdit, AIEditorState } from '@/hooks/useAIEditor';
export type { AIEditHistory } from '../builder/AICustomizationPanel';

// Integration utilities
export { AIEditorIntegration } from '../builder/EnhancedCanvas';

# AI Editing Integration

This directory contains the complete AI editing system that integrates seamlessly with the existing manual component controls.

## Overview

The AI editing system provides three levels of integration:

1. **Visual AI Assistant** - Sidebar-based AI suggestions for existing components
2. **Code AI Editor** - Full-featured code editor with AI assistance
3. **Integrated Editor** - Unified interface combining all editing modes

## Components

### Core Components

- **ComponentEditorWithAI** - Enhanced code editor with AI sidebar
- **IntegratedEditor** - Unified visual/code/AI editing interface
- **EnhancedCanvas** - Canvas with AI editing integration
- **AICustomizationPanel** - Enhanced AI sidebar panel

### Hooks

- **useAIEditor** - Hook for managing AI editing state

## Usage

### Basic Integration

```tsx
import { EnhancedCanvas } from '@/components/ai-editing';

function MyApp() {
  return (
    <EnhancedCanvas 
      onComponentEdit={(component, mode) => {
        // Handle component editing
      }}
    />
  );
}
```

### Advanced Integration

```tsx
import { useAIEditor, ComponentEditorWithAI } from '@/components/ai-editing';

function AdvancedEditor() {
  const { 
    state, 
    openEditor, 
    processAIPrompt, 
    applyAIEdit 
  } = useAIEditor();

  const handleAIEdit = async (prompt: string) => {
    const edit = await processAIPrompt(prompt);
    await applyAIEdit(edit);
  };

  return (
    <ComponentEditorWithAI
      initialCode={initialCode}
      componentType="react"
      onCodeChange={handleCodeChange}
    />
  );
}
```

## Features

### AI Editing Capabilities

- **Natural Language Processing** - "Make this button blue and larger"
- **Context-Aware Suggestions** - Based on component type and current state
- **Undo/Redo System** - Full history management for AI edits
- **Quick Actions** - Pre-defined improvements for common use cases
- **Edit History** - Track and revert AI changes

### Manual Controls Preserved

- **Original drag-and-drop** functionality unchanged
- **Manual property editing** fully supported
- **Component positioning** and sizing works as before
- **Visual builder** integration maintained

### Seamless Integration

- **No breaking changes** to existing components
- **Progressive enhancement** - AI features are optional
- **Fallback handling** - Manual controls always available
- **Performance optimized** - AI processing is async and debounced

## Integration Points

### 1. Canvas Integration

The `EnhancedCanvas` component adds AI editing capabilities to the existing canvas:

- Floating AI toggle button
- Contextual editing controls
- Modal editor overlay
- Seamless switching between modes

### 2. Component-Level Integration

Individual components can use AI editing:

```tsx
import { AIEditorIntegration } from '@/components/ai-editing';

function MyComponent({ component }) {
  return (
    <AIEditorIntegration
      component={component}
      onEdit={handleComponentUpdate}
    />
  );
}
```

### 3. Store Integration

AI edits are applied through the existing builder store:

```tsx
const { updateComponent } = useBuilderStore();

// AI edit applies through same mechanism as manual edits
updateComponent(component.id, aiGeneratedChanges);
```

## API Reference

### useAIEditor Hook

```typescript
interface UseAIEditorReturn {
  state: AIEditorState;
  openEditor: (component: ComponentData, initialCode?: string) => void;
  closeEditor: () => void;
  applyAIEdit: (edit: AIEdit) => Promise<void>;
  undoLastEdit: () => void;
  redoLastEdit: () => void;
  resetToOriginal: () => void;
  processAIPrompt: (prompt: string) => Promise<AIEdit>;
  generateCodeFromComponent: (component: ComponentData) => string;
}
```

### ComponentEditorWithAI Props

```typescript
interface ComponentEditorWithAIProps {
  initialCode: string;
  componentType: 'react' | 'html' | 'vue';
  componentId?: string;
  onCodeChange?: (code: string) => void;
  className?: string;
}
```

## Configuration

### AI Processing

The AI processing is currently simulated for demo purposes. To integrate real AI:

1. Replace `simulateAIEdit` in `useAIEditor` hook with actual API calls
2. Implement proper AST parsing for code-to-props conversion
3. Add validation and error handling
4. Configure rate limiting and caching

### Quick Actions

Quick actions are defined per component type:

- **Buttons**: Styling, animations, sizing
- **Text**: Typography, spacing, responsiveness
- **Containers**: Layout, spacing, shadows
- **Forms**: UX improvements, validation, responsiveness

## Testing

### Manual Testing

1. Select a component on canvas
2. Try AI suggestions from sidebar
3. Switch between visual/code/AI modes
4. Test undo/redo functionality
5. Verify manual controls still work

### Automated Testing

```bash
# Run integration tests
npm test src/components/ai-editing/__tests__/

# Run E2E tests
npm run test:e2e ai-editing
```

## Performance

- **Lazy loading** - AI components loaded on demand
- **Debounced processing** - AI requests debounced by 500ms
- **Caching** - Previous AI responses cached
- **Background processing** - Heavy AI work in web workers

## Security

- **Input sanitization** - All prompts sanitized before processing
- **Output validation** - AI responses validated before application
- **Rate limiting** - Configurable rate limits
- **Audit trail** - All AI edits logged for review

## Migration Guide

### From Manual to AI Editing

1. **No breaking changes** - Existing code continues to work
2. **Opt-in features** - AI editing is additional, not replacement
3. **Gradual rollout** - Enable features incrementally
4. **User training** - Provide guided tours for new features

### Backward Compatibility

- All existing hooks and components remain unchanged
- New AI features are additive only
- Manual editing always available as fallback
- No changes to data structures or APIs

## Examples

### Basic Usage

```tsx
// Simple canvas with AI editing
import { EnhancedCanvas } from '@/components/ai-editing';

function Builder() {
  return (
    <div className="h-screen">
      <EnhancedCanvas />
    </div>
  );
}
```

### Advanced Usage

```tsx
// Custom integration
import { useAIEditor, ComponentEditorWithAI } from '@/components/ai-editing';

function CustomBuilder() {
  const { openEditor, processAIPrompt } = useAIEditor();

  return (
    <div>
      <button onClick={() => openEditor(selectedComponent)}>
        Edit with AI
      </button>

      <ComponentEditorWithAI
        initialCode={generateCode(selectedComponent)}
        onCodeChange={handleCodeChange}
      />
    </div>
  );
}
```

## Support

For issues or questions:
- Check the component documentation
- Review the integration examples
- Test with the provided playground
- Refer to the troubleshooting guide

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { 
  Lightbulb, 
  Sparkles, 
  TrendingUp, 
  Target, 
  CheckCircle2, 
  XCircle, 
  RefreshCw,
  Brain,
  Zap,
  Star
} from 'lucide-react';
import { cn } from '@/lib/utils';

// Types for Epic 4 AI Features
interface BuilderContext {
  industry: string;
  business_type: string;
  page_type: string;
  goals: string[];
  target_audience: string;
  brand_guidelines?: any;
  existing_components: any[];
}

interface ComponentSuggestion {
  component_type: string;
  reasoning: string;
  priority: 'high' | 'medium' | 'low';
  expected_impact: string;
  customization_suggestions: string[];
  confidence_score: number;
  ranking_score?: number;
  recommended_component_id?: string;
  performance_data?: {
    conversion_rate: number;
    engagement_score: number;
    performance_score: number;
    usage_count: number;
  };
}

interface ComponentSuggestionsResponse {
  suggestions: ComponentSuggestion[];
  context_analysis: {
    industry: string;
    page_type: string;
    completeness_score: number;
    conversion_funnel_stage: string;
    missing_essentials: string[];
    user_journey_gaps: string[];
  };
  processing_time_ms: number;
  ai_model_used: string;
  cache_hit: boolean;
}

interface ComponentSuggestionsProps {
  context: BuilderContext;
  onAddComponent: (componentType: string, customization?: any) => void;
  onRefreshSuggestions?: () => void;
  className?: string;
}

export function ComponentSuggestions({ 
  context, 
  onAddComponent, 
  onRefreshSuggestions,
  className 
}: ComponentSuggestionsProps) {
  const [suggestions, setSuggestions] = useState<ComponentSuggestion[]>([]);
  const [contextAnalysis, setContextAnalysis] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [processingTime, setProcessingTime] = useState<number>(0);
  const [acceptedSuggestions, setAcceptedSuggestions] = useState<Set<string>>(new Set());

  // Load suggestions when context changes
  useEffect(() => {
    if (context.industry && context.business_type) {
      loadSuggestions();
    }
  }, [context.industry, context.business_type, context.page_type]);

  const loadSuggestions = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/v1/ai/component-suggestions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        },
        body: JSON.stringify({
          context: context,
          current_components: context.existing_components || [],
          max_suggestions: 5,
          preferences: {}
        })
      });

      if (!response.ok) {
        throw new Error('Failed to get component suggestions');
      }

      const data: ComponentSuggestionsResponse = await response.json();
      setSuggestions(data.suggestions);
      setContextAnalysis(data.context_analysis);
      setProcessingTime(data.processing_time_ms);

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load suggestions');
      console.error('Component suggestions error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptSuggestion = async (suggestion: ComponentSuggestion, index: number) => {
    try {
      // Add component to builder
      onAddComponent(suggestion.component_type, {
        customizations: suggestion.customization_suggestions,
        aiGenerated: true,
        confidence: suggestion.confidence_score
      });

      // Track acceptance
      setAcceptedSuggestions(prev => new Set(prev).add(suggestion.component_type));

      // Send feedback to API
      await fetch('/api/v1/ai/suggestions/feedback', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        },
        body: JSON.stringify({
          suggestion_id: `${suggestion.component_type}_${index}`,
          accepted: true,
          feedback_score: 5
        })
      });

    } catch (err) {
      console.error('Failed to accept suggestion:', err);
    }
  };

  const handleRejectSuggestion = async (suggestion: ComponentSuggestion, index: number) => {
    try {
      // Send feedback to API
      await fetch('/api/v1/ai/suggestions/feedback', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('access_token')}`
        },
        body: JSON.stringify({
          suggestion_id: `${suggestion.component_type}_${index}`,
          accepted: false,
          feedback_score: 2
        })
      });

      // Remove from suggestions
      setSuggestions(prev => prev.filter((_, i) => i !== index));

    } catch (err) {
      console.error('Failed to reject suggestion:', err);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'bg-red-100 text-red-800';
      case 'medium': return 'bg-yellow-100 text-yellow-800';
      case 'low': return 'bg-green-100 text-green-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'high': return <Zap className="w-3 h-3" />;
      case 'medium': return <Target className="w-3 h-3" />;
      case 'low': return <TrendingUp className="w-3 h-3" />;
      default: return <Lightbulb className="w-3 h-3" />;
    }
  };

  const formatComponentName = (componentType: string) => {
    return componentType
      .split(/[-_]/)
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  if (loading) {
    return (
      <Card className={cn("w-full", className)}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Brain className="w-5 h-5 text-blue-500" />
            AI Component Suggestions
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={cn("w-full", className)}>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Brain className="w-5 h-5 text-blue-500" />
            AI Component Suggestions
            <Badge variant="secondary" className="ml-2">
              <Sparkles className="w-3 h-3 mr-1" />
              Epic 4
            </Badge>
          </div>
          <Button
            onClick={onRefreshSuggestions || loadSuggestions}
            variant="outline"
            size="sm"
            disabled={loading}
            className="flex items-center gap-1"
          >
            <RefreshCw className={cn("w-4 h-4", loading && "animate-spin")} />
            Refresh
          </Button>
        </CardTitle>

        {processingTime > 0 && (
          <div className="text-sm text-gray-500">
            Generated in {processingTime}ms using AI analysis
          </div>
        )}
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Context Analysis Summary */}
        {contextAnalysis && (
          <div className="p-4 bg-blue-50 rounded-lg border border-blue-200">
            <div className="flex items-start gap-3">
              <Target className="w-5 h-5 text-blue-600 mt-0.5" />
              <div>
                <h4 className="font-medium text-blue-900 mb-2">Page Analysis</h4>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="font-medium">Completeness:</span>
                    <div className="flex items-center gap-2 mt-1">
                      <div className="flex-1 bg-gray-200 rounded-full h-2">
                        <div 
                          className="bg-blue-500 h-2 rounded-full transition-all"
                          style={{ width: `${Math.min(contextAnalysis.completeness_score * 100, 100)}%` }}
                        />
                      </div>
                      <span className="text-xs">
                        {Math.round(contextAnalysis.completeness_score * 100)}%
                      </span>
                    </div>
                  </div>
                  <div>
                    <span className="font-medium">Stage:</span>
                    <Badge variant="outline" className="ml-2 capitalize">
                      {contextAnalysis.conversion_funnel_stage}
                    </Badge>
                  </div>
                </div>

                {contextAnalysis.missing_essentials?.length > 0 && (
                  <div className="mt-2">
                    <span className="font-medium text-xs">Missing Essentials:</span>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {contextAnalysis.missing_essentials.slice(0, 3).map((essential: string) => (
                        <Badge key={essential} variant="destructive" className="text-xs">
                          {formatComponentName(essential)}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="p-4 bg-red-50 rounded-lg border border-red-200">
            <div className="flex items-center gap-2 text-red-800">
              <XCircle className="w-5 h-5" />
              <span className="font-medium">Error loading suggestions</span>
            </div>
            <p className="text-red-600 text-sm mt-1">{error}</p>
            <Button 
              onClick={loadSuggestions}
              variant="outline"
              size="sm"
              className="mt-2"
            >
              Try Again
            </Button>
          </div>
        )}

        {/* Suggestions List */}
        {suggestions.length === 0 && !loading && !error && (
          <div className="text-center py-8 text-gray-500">
            <Lightbulb className="w-12 h-12 mx-auto mb-4 text-gray-300" />
            <p>No suggestions available at the moment.</p>
            <p className="text-sm">Try adjusting your context or adding more components.</p>
          </div>
        )}

        {suggestions.map((suggestion, index) => (
          <div
            key={`${suggestion.component_type}_${index}`}
            className={cn(
              "p-4 rounded-lg border transition-all",
              acceptedSuggestions.has(suggestion.component_type)
                ? "bg-green-50 border-green-200"
                : "bg-white border-gray-200 hover:border-gray-300"
            )}
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-start gap-3 flex-1">
                <div className="flex items-center gap-2">
                  {getPriorityIcon(suggestion.priority)}
                  <h4 className="font-semibold text-gray-900">
                    {formatComponentName(suggestion.component_type)}
                  </h4>
                </div>
                <div className="flex items-center gap-2">
                  <Badge className={getPriorityColor(suggestion.priority)} variant="secondary">
                    {suggestion.priority}
                  </Badge>
                  <Badge variant="outline" className="text-xs">
                    {Math.round(suggestion.confidence_score * 100)}% confident
                  </Badge>
                  {suggestion.performance_data && (
                    <Badge variant="secondary" className="text-xs">
                      <Star className="w-3 h-3 mr-1" />
                      {Math.round(suggestion.performance_data.performance_score * 100)}% performance
                    </Badge>
                  )}
                </div>
              </div>

              <div className="flex items-center gap-2">
                {!acceptedSuggestions.has(suggestion.component_type) && (
                  <>
                    <Button
                      onClick={() => handleAcceptSuggestion(suggestion, index)}
                      size="sm"
                      className="flex items-center gap-1"
                    >
                      <CheckCircle2 className="w-4 h-4" />
                      Add
                    </Button>
                    <Button
                      onClick={() => handleRejectSuggestion(suggestion, index)}
                      variant="ghost"
                      size="sm"
                      className="text-gray-500 hover:text-red-600"
                    >
                      <XCircle className="w-4 h-4" />
                    </Button>
                  </>
                )}
                {acceptedSuggestions.has(suggestion.component_type) && (
                  <Badge variant="secondary" className="text-green-700 bg-green-100">
                    <CheckCircle2 className="w-3 h-3 mr-1" />
                    Added
                  </Badge>
                )}
              </div>
            </div>

            <p className="text-gray-600 text-sm mb-3">
              {suggestion.reasoning}
            </p>

            <div className="space-y-2">
              <div>
                <span className="text-xs font-medium text-gray-700 uppercase tracking-wide">
                  Expected Impact
                </span>
                <p className="text-sm text-gray-600 mt-1">
                  {suggestion.expected_impact}
                </p>
              </div>

              {suggestion.customization_suggestions?.length > 0 && (
                <div>
                  <span className="text-xs font-medium text-gray-700 uppercase tracking-wide">
                    Customization Tips
                  </span>
                  <ul className="text-sm text-gray-600 mt-1 space-y-1">
                    {suggestion.customization_suggestions.slice(0, 2).map((tip, tipIndex) => (
                      <li key={tipIndex} className="flex items-start gap-2">
                        <span className="text-blue-500 mt-1">•</span>
                        <span>{tip}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {suggestion.performance_data && (
                <div className="grid grid-cols-3 gap-4 pt-2 border-t border-gray-100">
                  <div className="text-center">
                    <div className="text-xs text-gray-500">Conversion Rate</div>
                    <div className="text-sm font-medium text-green-600">
                      {Math.round(suggestion.performance_data.conversion_rate * 100)}%
                    </div>
                  </div>
                  <div className="text-center">
                    <div className="text-xs text-gray-500">Engagement</div>
                    <div className="text-sm font-medium text-blue-600">
                      {Math.round(suggestion.performance_data.engagement_score * 100)}%
                    </div>
                  </div>
                  <div className="text-center">
                    <div className="text-xs text-gray-500">Usage</div>
                    <div className="text-sm font-medium text-gray-600">
                      {suggestion.performance_data.usage_count}×
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {suggestions.length > 0 && (
          <div className="pt-4 border-t border-gray-200">
            <div className="flex items-center justify-between text-sm text-gray-500">
              <span>
                Showing {suggestions.length} AI-powered suggestions
              </span>
              <span>
                Powered by Epic 4 Intelligence
              </span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * A/B Testing Interface Component
 * 
 * A/B testing capabilities for workflow variations with automated winner selection
 * Part of Story 3.3 - Performance Analytics Dashboard
 */

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { 
  TestTube2, 
  Play, 
  Pause, 
  Trophy, 
  Target, 
  BarChart3, 
  Calculator, 
  CheckCircle2, 
  AlertCircle, 
  Clock,
  Users,
  TrendingUp,
  Settings,
  Plus,
  Edit,
  Trash2,
  Eye,
  Activity
} from 'lucide-react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  PieChart,
  Pie,
  Cell
} from 'recharts';

// Types for A/B testing
interface ABTest {
  id: string;
  name: string;
  description: string;
  status: 'draft' | 'running' | 'completed' | 'paused';
  workflowId: string;
  workflowName: string;
  startDate: string;
  endDate?: string;
  trafficSplit: number; // 0-100 percentage for variant A
  variants: {
    variantA: ABTestVariant;
    variantB: ABTestVariant;
  };
  results?: ABTestResults;
  settings: {
    minSampleSize: number;
    maxDuration: number; // days
    significanceLevel: number; // 0.95 for 95%
    autoStop: boolean;
    earlyWinnerDetection: boolean;
  };
}

interface ABTestVariant {
  id: string;
  name: string;
  description: string;
  configuration: Record<string, any>;
  metrics: {
    participants: number;
    conversions: number;
    conversionRate: number;
    avgResponseTime: number;
    successRate: number;
  };
}

interface ABTestResults {
  winner?: 'variantA' | 'variantB' | 'inconclusive';
  confidence: number;
  pValue: number;
  effectSize: number;
  improvementPercent: number;
  statisticalSignificance: boolean;
  recommendation: string;
  detailedAnalysis: {
    conversionRateImprovement: number;
    responseTimeImprovement: number;
    successRateImprovement: number;
    businessImpact: number;
  };
}

export const ABTestingInterface: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [selectedTest, setSelectedTest] = useState<string>('test-001');
  const [showCreateForm, setShowCreateForm] = useState(false);

  // Mock A/B test data
  const [abTests, setAbTests] = useState<ABTest[]>([
    {
      id: 'test-001',
      name: 'Lead Generation Optimization',
      description: 'Testing improved lead capture form vs current implementation',
      status: 'running',
      workflowId: 'wf-001',
      workflowName: 'Lead Generation Workflow',
      startDate: '2024-01-15T10:00:00Z',
      trafficSplit: 50,
      variants: {
        variantA: {
          id: 'variant-a-001',
          name: 'Current Implementation',
          description: 'Existing lead generation workflow',
          configuration: { formFields: 3, validation: 'basic' },
          metrics: {
            participants: 1245,
            conversions: 89,
            conversionRate: 7.15,
            avgResponseTime: 2.8,
            successRate: 94.2
          }
        },
        variantB: {
          id: 'variant-b-001',
          name: 'Optimized Form',
          description: 'Streamlined form with better UX',
          configuration: { formFields: 2, validation: 'smart' },
          metrics: {
            participants: 1189,
            conversions: 103,
            conversionRate: 8.66,
            avgResponseTime: 2.1,
            successRate: 96.8
          }
        }
      },
      results: {
        winner: 'variantB',
        confidence: 97.5,
        pValue: 0.012,
        effectSize: 0.21,
        improvementPercent: 21.1,
        statisticalSignificance: true,
        recommendation: 'Deploy Variant B - significant improvement in conversion rate',
        detailedAnalysis: {
          conversionRateImprovement: 21.1,
          responseTimeImprovement: 25.0,
          successRateImprovement: 2.8,
          businessImpact: 15600
        }
      },
      settings: {
        minSampleSize: 1000,
        maxDuration: 30,
        significanceLevel: 0.95,
        autoStop: true,
        earlyWinnerDetection: true
      }
    },
    {
      id: 'test-002',
      name: 'Email Template Comparison',
      description: 'Testing personalized vs standard email templates',
      status: 'running',
      workflowId: 'wf-002',
      workflowName: 'Email Marketing Workflow',
      startDate: '2024-01-20T14:00:00Z',
      trafficSplit: 60,
      variants: {
        variantA: {
          id: 'variant-a-002',
          name: 'Standard Template',
          description: 'Current email template design',
          configuration: { personalization: false, subject: 'standard' },
          metrics: {
            participants: 892,
            conversions: 41,
            conversionRate: 4.6,
            avgResponseTime: 1.2,
            successRate: 92.1
          }
        },
        variantB: {
          id: 'variant-b-002',
          name: 'Personalized Template',
          description: 'AI-personalized email content',
          configuration: { personalization: true, subject: 'dynamic' },
          metrics: {
            participants: 595,
            conversions: 34,
            conversionRate: 5.7,
            avgResponseTime: 1.4,
            successRate: 94.3
          }
        }
      },
      settings: {
        minSampleSize: 800,
        maxDuration: 21,
        significanceLevel: 0.95,
        autoStop: false,
        earlyWinnerDetection: true
      }
    }
  ]);

  // Performance comparison data for charts
  const performanceComparisonData = [
    { metric: 'Conversion Rate', variantA: 7.15, variantB: 8.66, improvement: 21.1 },
    { metric: 'Response Time', variantA: 2.8, variantB: 2.1, improvement: 25.0 },
    { metric: 'Success Rate', variantA: 94.2, variantB: 96.8, improvement: 2.8 }
  ];

  // Time series data for the running test
  const timeSeriesData = Array.from({ length: 14 }, (_, i) => {
    const date = new Date(Date.now() - (13 - i) * 24 * 60 * 60 * 1000);
    return {
      date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      variantA: 7.0 + Math.random() * 0.5 + i * 0.01,
      variantB: 8.0 + Math.random() * 0.8 + i * 0.05,
      participants: 50 + i * 10
    };
  });

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 1000);
    return () => clearTimeout(timer);
  }, []);

  const currentTest = abTests.find(test => test.id === selectedTest);

  // Render test status badge
  const renderStatusBadge = (status: ABTest['status']) => {
    const statusConfig = {
      draft: { color: 'bg-gray-100 text-gray-800', icon: Edit },
      running: { color: 'bg-green-100 text-green-800', icon: Play },
      completed: { color: 'bg-blue-100 text-blue-800', icon: CheckCircle2 },
      paused: { color: 'bg-yellow-100 text-yellow-800', icon: Pause }
    };

    const config = statusConfig[status];
    const Icon = config.icon;

    return (
      <Badge className={config.color}>
        <Icon className="h-3 w-3 mr-1" />
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    );
  };

  // Render variant comparison card
  const renderVariantCard = (variant: ABTestVariant, label: string, isWinner?: boolean) => (
    <Card className={`relative ${isWinner ? 'border-green-500 bg-green-50' : ''}`}>
      {isWinner && (
        <div className="absolute top-2 right-2">
          <Badge className="bg-green-100 text-green-800">
            <Trophy className="h-3 w-3 mr-1" />
            Winner
          </Badge>
        </div>
      )}
      <CardHeader>
        <CardTitle className="text-lg">
          {label}: {variant.name}
        </CardTitle>
        <CardDescription>{variant.description}</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center">
            <div className="text-2xl font-bold">{variant.metrics.participants.toLocaleString()}</div>
            <div className="text-sm text-muted-foreground">Participants</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">{variant.metrics.conversionRate.toFixed(2)}%</div>
            <div className="text-sm text-muted-foreground">Conversion Rate</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">{variant.metrics.avgResponseTime.toFixed(1)}s</div>
            <div className="text-sm text-muted-foreground">Response Time</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-orange-600">{variant.metrics.successRate.toFixed(1)}%</div>
            <div className="text-sm text-muted-foreground">Success Rate</div>
          </div>
        </div>
      </CardContent>
    </Card>
  );

  // Render test results
  const renderTestResults = (results: ABTestResults) => (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Calculator className="h-5 w-5" />
          Statistical Analysis Results
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <div className="text-center p-4 border rounded-lg">
            <div className="text-2xl font-bold text-green-600">{results.confidence.toFixed(1)}%</div>
            <div className="text-sm text-muted-foreground">Confidence Level</div>
          </div>
          <div className="text-center p-4 border rounded-lg">
            <div className="text-2xl font-bold text-blue-600">{results.pValue.toFixed(3)}</div>
            <div className="text-sm text-muted-foreground">P-Value</div>
          </div>
          <div className="text-center p-4 border rounded-lg">
            <div className="text-2xl font-bold text-orange-600">+{results.improvementPercent.toFixed(1)}%</div>
            <div className="text-sm text-muted-foreground">Improvement</div>
          </div>
          <div className="text-center p-4 border rounded-lg">
            <div className="text-2xl font-bold text-purple-600">${results.detailedAnalysis.businessImpact.toLocaleString()}</div>
            <div className="text-sm text-muted-foreground">Business Impact</div>
          </div>
        </div>

        <div className="space-y-4">
          <div className={`p-4 rounded-lg border ${
            results.statisticalSignificance ? 'bg-green-50 border-green-200' : 'bg-yellow-50 border-yellow-200'
          }`}>
            <div className="flex items-center gap-2 mb-2">
              {results.statisticalSignificance ? (
                <CheckCircle2 className="h-5 w-5 text-green-600" />
              ) : (
                <AlertCircle className="h-5 w-5 text-yellow-600" />
              )}
              <span className="font-semibold">
                {results.statisticalSignificance ? 'Statistically Significant' : 'Not Yet Significant'}
              </span>
            </div>
            <p className="text-sm">{results.recommendation}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <h4 className="font-medium mb-2">Conversion Rate</h4>
              <div className="flex items-center gap-2">
                <Progress value={Math.abs(results.detailedAnalysis.conversionRateImprovement)} className="flex-1" />
                <span className="text-sm font-medium">+{results.detailedAnalysis.conversionRateImprovement.toFixed(1)}%</span>
              </div>
            </div>
            <div>
              <h4 className="font-medium mb-2">Response Time</h4>
              <div className="flex items-center gap-2">
                <Progress value={Math.abs(results.detailedAnalysis.responseTimeImprovement)} className="flex-1" />
                <span className="text-sm font-medium">+{results.detailedAnalysis.responseTimeImprovement.toFixed(1)}%</span>
              </div>
            </div>
            <div>
              <h4 className="font-medium mb-2">Success Rate</h4>
              <div className="flex items-center gap-2">
                <Progress value={Math.abs(results.detailedAnalysis.successRateImprovement)} className="flex-1" />
                <span className="text-sm font-medium">+{results.detailedAnalysis.successRateImprovement.toFixed(1)}%</span>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {[...Array(2)].map((_, i) => (
            <Card key={i} className="p-6">
              <div className="h-6 w-32 bg-gray-200 rounded animate-pulse mb-4"></div>
              <div className="space-y-2">
                <div className="h-4 w-full bg-gray-200 rounded animate-pulse"></div>
                <div className="h-4 w-3/4 bg-gray-200 rounded animate-pulse"></div>
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <TestTube2 className="h-5 w-5" />
          <h2 className="text-lg font-semibold">A/B Testing</h2>
        </div>

        <div className="flex gap-2">
          <Select value={selectedTest} onValueChange={setSelectedTest}>
            <SelectTrigger className="w-64">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {abTests.map(test => (
                <SelectItem key={test.id} value={test.id}>
                  {test.name} - {renderStatusBadge(test.status)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Button onClick={() => setShowCreateForm(true)}>
            <Plus className="h-4 w-4 mr-2" />
            New Test
          </Button>
        </div>
      </div>

      {currentTest && (
        <>
          {/* Test Overview */}
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>{currentTest.name}</CardTitle>
                  <CardDescription>{currentTest.description}</CardDescription>
                </div>
                <div className="flex items-center gap-4">
                  {renderStatusBadge(currentTest.status)}
                  <div className="text-right text-sm">
                    <div>Started: {new Date(currentTest.startDate).toLocaleDateString()}</div>
                    <div className="text-muted-foreground">
                      Traffic Split: {currentTest.trafficSplit}% / {100 - currentTest.trafficSplit}%
                    </div>
                  </div>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <div className="flex gap-4">
                <Button variant="outline" size="sm">
                  <Settings className="h-4 w-4 mr-2" />
                  Configure
                </Button>
                <Button variant="outline" size="sm">
                  <Eye className="h-4 w-4 mr-2" />
                  View Details
                </Button>
                {currentTest.status === 'running' ? (
                  <Button variant="outline" size="sm">
                    <Pause className="h-4 w-4 mr-2" />
                    Pause Test
                  </Button>
                ) : (
                  <Button variant="outline" size="sm">
                    <Play className="h-4 w-4 mr-2" />
                    Resume Test
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Variant Comparison */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {renderVariantCard(
              currentTest.variants.variantA, 
              'Variant A', 
              currentTest.results?.winner === 'variantA'
            )}
            {renderVariantCard(
              currentTest.variants.variantB, 
              'Variant B', 
              currentTest.results?.winner === 'variantB'
            )}
          </div>

          {/* Performance Trends */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <BarChart3 className="h-5 w-5" />
                Performance Trends
              </CardTitle>
              <CardDescription>
                Conversion rate comparison over time
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={timeSeriesData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" />
                    <YAxis />
                    <Tooltip 
                      formatter={(value: number, name: string) => [
                        `${value.toFixed(2)}%`,
                        name === 'variantA' ? 'Variant A' : 'Variant B'
                      ]}
                    />
                    <Legend />
                    <Line 
                      type="monotone" 
                      dataKey="variantA" 
                      stroke="#3b82f6" 
                      strokeWidth={2}
                      name="Variant A"
                    />
                    <Line 
                      type="monotone" 
                      dataKey="variantB" 
                      stroke="#10b981" 
                      strokeWidth={2}
                      name="Variant B"
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>

          {/* Performance Comparison Chart */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Target className="h-5 w-5" />
                Detailed Metrics Comparison
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={performanceComparisonData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="metric" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="variantA" fill="#3b82f6" name="Variant A" />
                    <Bar dataKey="variantB" fill="#10b981" name="Variant B" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>

          {/* Test Results */}
          {currentTest.results && renderTestResults(currentTest.results)}

          {/* Test Actions */}
          {currentTest.results?.statisticalSignificance && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Trophy className="h-5 w-5" />
                  Winner Recommendation
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-between p-4 bg-green-50 border border-green-200 rounded-lg">
                  <div>
                    <h4 className="font-semibold text-green-800">
                      Variant B shows significant improvement
                    </h4>
                    <p className="text-sm text-green-700">
                      Deploy Variant B for {currentTest.results.improvementPercent.toFixed(1)}% improvement 
                      and ${currentTest.results.detailedAnalysis.businessImpact.toLocaleString()} business impact
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <Button variant="outline">
                      Deploy Gradually
                    </Button>
                    <Button>
                      Deploy to All Traffic
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* Active Tests Summary */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Activity className="h-5 w-5" />
            All A/B Tests Summary
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {abTests.map(test => (
              <div key={test.id} className="flex items-center justify-between p-3 border rounded-lg">
                <div>
                  <h4 className="font-medium">{test.name}</h4>
                  <p className="text-sm text-muted-foreground">
                    {test.workflowName} • Started {new Date(test.startDate).toLocaleDateString()}
                  </p>
                </div>
                <div className="flex items-center gap-4">
                  {renderStatusBadge(test.status)}
                  {test.results?.statisticalSignificance && (
                    <Badge className="bg-green-100 text-green-800">
                      +{test.results.improvementPercent.toFixed(1)}%
                    </Badge>
                  )}
                  <Button 
                    variant="ghost" 
                    size="sm"
                    onClick={() => setSelectedTest(test.id)}
                  >
                    View Details
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

/**
 * Analytics Configuration Component
 * 
 * Configuration settings for analytics dashboard and external integrations
 * Part of Story 3.3 - Performance Analytics Dashboard
 */

'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Slider } from '@/components/ui/slider';
import { Checkbox } from '@/components/ui/checkbox';
import { 
  Settings, 
  Database, 
  Bell, 
  Eye, 
  Shield, 
  Zap, 
  Globe, 
  Clock, 
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Plus,
  Trash2,
  Edit,
  Link,
  Unlink,
  Key
} from 'lucide-react';

// Types for configuration
interface DashboardSettings {
  refreshInterval: number; // seconds
  autoRefresh: boolean;
  realTimeUpdates: boolean;
  darkMode: boolean;
  compactView: boolean;
  defaultTimeRange: string;
  enableNotifications: boolean;
  enableAlerts: boolean;
}

interface AlertThreshold {
  id: string;
  metric: string;
  condition: 'above' | 'below' | 'equals';
  value: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
  enabled: boolean;
  notifications: {
    email: boolean;
    dashboard: boolean;
    webhook?: string;
  };
}

interface ExternalIntegration {
  id: string;
  platform: 'google_analytics' | 'hubspot' | 'salesforce' | 'mixpanel' | 'segment';
  name: string;
  status: 'connected' | 'disconnected' | 'error' | 'configuring';
  lastSync?: string;
  configuration: {
    apiKey?: string;
    accountId?: string;
    propertyId?: string;
    customFields?: Record<string, string>;
  };
  syncSettings: {
    frequency: 'realtime' | 'hourly' | 'daily';
    metrics: string[];
    enabled: boolean;
  };
}

interface DataRetentionSettings {
  analyticsData: number; // days
  exportedReports: number; // days
  auditLogs: number; // days
  alertHistory: number; // days
  autoCleanup: boolean;
}

export const AnalyticsConfiguration: React.FC = () => {
  const [activeSection, setActiveSection] = useState<'dashboard' | 'alerts' | 'integrations' | 'data'>('dashboard');

  // Dashboard settings state
  const [dashboardSettings, setDashboardSettings] = useState<DashboardSettings>({
    refreshInterval: 30,
    autoRefresh: true,
    realTimeUpdates: true,
    darkMode: false,
    compactView: false,
    defaultTimeRange: '30d',
    enableNotifications: true,
    enableAlerts: true
  });

  // Alert thresholds state
  const [alertThresholds, setAlertThresholds] = useState<AlertThreshold[]>([
    {
      id: 'threshold-001',
      metric: 'conversion_rate',
      condition: 'below',
      value: 5.0,
      severity: 'high',
      enabled: true,
      notifications: {
        email: true,
        dashboard: true,
        webhook: 'https://hooks.slack.com/services/...'
      }
    },
    {
      id: 'threshold-002',
      metric: 'response_time',
      condition: 'above',
      value: 5000,
      severity: 'medium',
      enabled: true,
      notifications: {
        email: false,
        dashboard: true
      }
    },
    {
      id: 'threshold-003',
      metric: 'error_rate',
      condition: 'above',
      value: 2.0,
      severity: 'critical',
      enabled: true,
      notifications: {
        email: true,
        dashboard: true
      }
    }
  ]);

  // External integrations state
  const [externalIntegrations, setExternalIntegrations] = useState<ExternalIntegration[]>([
    {
      id: 'integration-ga',
      platform: 'google_analytics',
      name: 'Google Analytics 4',
      status: 'connected',
      lastSync: '2024-01-20T16:30:00Z',
      configuration: {
        propertyId: 'GA4-PROPERTY-ID',
        accountId: 'GA-ACCOUNT-ID'
      },
      syncSettings: {
        frequency: 'hourly',
        metrics: ['page_views', 'sessions', 'conversions', 'bounce_rate'],
        enabled: true
      }
    },
    {
      id: 'integration-hubspot',
      platform: 'hubspot',
      name: 'HubSpot CRM',
      status: 'connected',
      lastSync: '2024-01-20T15:45:00Z',
      configuration: {
        apiKey: 'hubspot-api-key-***'
      },
      syncSettings: {
        frequency: 'realtime',
        metrics: ['contacts', 'deals', 'emails', 'calls'],
        enabled: true
      }
    },
    {
      id: 'integration-sf',
      platform: 'salesforce',
      name: 'Salesforce',
      status: 'disconnected',
      configuration: {},
      syncSettings: {
        frequency: 'daily',
        metrics: ['leads', 'opportunities', 'accounts'],
