            <div className="flex items-center justify-between">
              <div>
                <Label>Encrypt at Rest</Label>
                <p className="text-sm text-muted-foreground">Encrypt stored analytics data</p>
              </div>
              <Switch defaultChecked />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <Label>Access Logging</Label>
