            <div className="flex items-center justify-between">
              <div>
                <Label>GDPR Compliance</Label>
                <p className="text-sm text-muted-foreground">Enable GDPR compliance features</p>
              </div>
              <Switch defaultChecked />
            </div>
          </div>
        </CardContent>
      </Card>
