  return (
    <div className="space-y-6">
      {/* Section Navigation */}
      <div className="flex flex-wrap border-b gap-1">
        <Button 
          variant={activeSection === 'dashboard' ? 'default' : 'ghost'}
          onClick={() => setActiveSection('dashboard')}
