        </Button>
        <Button 
          variant={activeSection === 'alerts' ? 'default' : 'ghost'}
          onClick={() => setActiveSection('alerts')}
        >
          <Bell className="h-4 w-4 mr-2" />
          Alerts
        </Button>
        <Button 
          variant={activeSection === 'integrations' ? 'default' : 'ghost'}
          onClick={() => setActiveSection('integrations')}
        >
          <Globe className="h-4 w-4 mr-2" />
          Integrations
        </Button>
        <Button 
          variant={activeSection === 'data' ? 'default' : 'ghost'}
          onClick={() => setActiveSection('data')}
        >
          <Database className="h-4 w-4 mr-2" />
          Data
        </Button>
      </div>

      {/* Section Content */}
      {activeSection === 'dashboard' && renderDashboardSettings()}
      {activeSection === 'alerts' && renderAlertsSection()}
      {activeSection === 'integrations' && renderIntegrationsSection()}
      {activeSection === 'data' && renderDataSection()}

      {/* Save Settings */}
      <div className="flex justify-end">
        <Button>
          <Settings className="h-4 w-4 mr-2" />
          Save Configuration
        </Button>
      </div>
    </div>
  );
};

/**
 * Comprehensive Analytics Dashboard Component
 * 
 * Main dashboard for Story 3.3 - Performance Analytics Dashboard
 * Features: conversion rates, engagement metrics, time savings, drill-down capabilities
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { 
  BarChart3, 
  TrendingUp, 
  TrendingDown, 
  Users, 
  DollarSign, 
  Clock, 
  Target, 
  AlertTriangle, 
  CheckCircle2, 
  RefreshCw,
  Filter,
  Download,
  Calendar,
  Activity,
  Zap,
  Eye,
  MousePointer,
  Gauge
} from 'lucide-react';
