  Legend
} from 'recharts';

// Types for analytics data
interface PerformanceMetric {
  id: string;
  name: string;
  value: number;
  previousValue: number;
  unit: string;
  trend: 'up' | 'down' | 'stable';
  changePercent: number;
  status: 'excellent' | 'good' | 'warning' | 'critical';
}

interface ConversionFunnelStage {
  stage: string;
  users: number;
  conversionRate: number;
  dropOffRate: number;
}

interface WorkflowPerformanceData {
  workflowId: string;
  workflowName: string;
  executionCount: number;
  successRate: number;
  avgExecutionTime: number;
  conversionRate: number;
  timesSaved: number;
  roi: number;
  trend: number[];
  lastUpdated: string;
}

interface AnalyticsDashboardProps {
  detailed?: boolean;
  timeRange?: '24h' | '7d' | '30d' | '90d';
  onTimeRangeChange?: (range: string) => void;
}

export const ComprehensiveAnalyticsDashboard: React.FC<AnalyticsDashboardProps> = ({
  detailed = false,
  timeRange = '30d',
  onTimeRangeChange
}) => {
  // State management
  const [loading, setLoading] = useState(true);
  const [selectedTimeRange, setSelectedTimeRange] = useState(timeRange);
  const [refreshing, setRefreshing] = useState(false);
  const [selectedWorkflow, setSelectedWorkflow] = useState<string>('all');
  const [drillDownData, setDrillDownData] = useState<any>(null);

  // Mock data - replace with real API calls
  const [performanceMetrics, setPerformanceMetrics] = useState<PerformanceMetric[]>([
    {
      id: 'conversion_rate',
      name: 'Conversion Rate',
      value: 8.5,
      previousValue: 7.2,
      unit: '%',
      trend: 'up',
      changePercent: 18.1,
      status: 'excellent'
    },
    {
      id: 'engagement_score',
      name: 'Engagement Score',
      value: 92,
      previousValue: 88,
      unit: '/100',
      trend: 'up',
      changePercent: 4.5,
      status: 'excellent'
    },
    {
      id: 'time_saved',
      name: 'Time Saved',
      value: 42.5,
      previousValue: 38.2,
      unit: 'hours',
      trend: 'up',
      changePercent: 11.3,
      status: 'good'
    },
    {
      id: 'roi',
      name: 'ROI',
      value: 325,
      previousValue: 280,
      unit: '%',
      trend: 'up',
      changePercent: 16.1,
      status: 'excellent'
    }
  ]);

  const [conversionFunnel, setConversionFunnel] = useState<ConversionFunnelStage[]>([
    { stage: 'Landing Page', users: 10000, conversionRate: 100, dropOffRate: 0 },
    { stage: 'Sign Up', users: 6500, conversionRate: 65, dropOffRate: 35 },
    { stage: 'Onboarding', users: 5200, conversionRate: 80, dropOffRate: 20 },
    { stage: 'First Action', users: 3900, conversionRate: 75, dropOffRate: 25 },
    { stage: 'Conversion', users: 2340, conversionRate: 60, dropOffRate: 40 }
