/**
 * Performance Comparison Panel Component
 * 
 * Comparison between different workflow versions with statistical significance testing
 * Part of Story 3.3 - Performance Analytics Dashboard
 */

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  TrendingUp, 
  TrendingDown, 
  GitCompare, 
  BarChart3, 
  Calculator, 
  CheckCircle2, 
  AlertCircle, 
  Info,
  ArrowRight,
  Trophy,
  Target,
  Clock,
  DollarSign
} from 'lucide-react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ComposedChart,
  Area,
  AreaChart
} from 'recharts';

// Types for comparison data
interface WorkflowVersion {
  id: string;
  name: string;
  version: string;
  createdAt: string;
  isActive: boolean;
  performance: {
    successRate: number;
    avgExecutionTime: number;
    conversionRate: number;
    errorRate: number;
    throughput: number;
    userSatisfaction: number;
  };
  statistics: {
    sampleSize: number;
    confidenceLevel: number;
    pValue: number;
    effectSize: number;
    isSignificant: boolean;
  };
}

interface ComparisonResult {
  metric: string;
  versionA: {
    value: number;
    confidence: [number, number];
  };
  versionB: {
    value: number;
    confidence: [number, number];
  };
  improvement: number;
  pValue: number;
  isSignificant: boolean;
  recommendation: 'version_a' | 'version_b' | 'inconclusive';
}

export const PerformanceComparisonPanel: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [selectedVersionA, setSelectedVersionA] = useState<string>('v1.2.0');
  const [selectedVersionB, setSelectedVersionB] = useState<string>('v1.3.0');
  const [comparisonType, setComparisonType] = useState<'versions' | 'periods' | 'segments'>('versions');

  // Mock data for workflow versions
  const workflowVersions: WorkflowVersion[] = [
    {
      id: 'v1.2.0',
      name: 'Lead Generation Workflow',
      version: 'v1.2.0',
      createdAt: '2024-01-15',
      isActive: false,
      performance: {
        successRate: 92.5,
        avgExecutionTime: 2.8,
        conversionRate: 7.2,
        errorRate: 7.5,
        throughput: 156,
        userSatisfaction: 4.2
      },
      statistics: {
        sampleSize: 1245,
        confidenceLevel: 95,
        pValue: 0.032,
        effectSize: 0.18,
        isSignificant: true
      }
    },
    {
      id: 'v1.3.0',
      name: 'Lead Generation Workflow',
      version: 'v1.3.0',
      createdAt: '2024-02-01',
      isActive: true,
      performance: {
        successRate: 95.8,
        avgExecutionTime: 2.1,
        conversionRate: 8.7,
        errorRate: 4.2,
        throughput: 203,
        userSatisfaction: 4.6
      },
      statistics: {
        sampleSize: 1089,
        confidenceLevel: 95,
        pValue: 0.008,
        effectSize: 0.24,
        isSignificant: true
      }
    }
  ];

  // Mock comparison results
  const comparisonResults: ComparisonResult[] = [
    {
      metric: 'Success Rate',
      versionA: { value: 92.5, confidence: [91.2, 93.8] },
      versionB: { value: 95.8, confidence: [94.6, 97.0] },
      improvement: 3.6,
      pValue: 0.008,
      isSignificant: true,
      recommendation: 'version_b'
    },
    {
      metric: 'Conversion Rate',
      versionA: { value: 7.2, confidence: [6.8, 7.6] },
      versionB: { value: 8.7, confidence: [8.2, 9.2] },
      improvement: 20.8,
      pValue: 0.003,
      isSignificant: true,
      recommendation: 'version_b'
    },
    {
      metric: 'Avg Execution Time',
      versionA: { value: 2.8, confidence: [2.6, 3.0] },
      versionB: { value: 2.1, confidence: [1.9, 2.3] },
      improvement: 25.0,
      pValue: 0.001,
      isSignificant: true,
      recommendation: 'version_b'
    },
    {
      metric: 'User Satisfaction',
      versionA: { value: 4.2, confidence: [4.0, 4.4] },
      versionB: { value: 4.6, confidence: [4.4, 4.8] },
      improvement: 9.5,
      pValue: 0.012,
      isSignificant: true,
      recommendation: 'version_b'
    }
  ];

  // Time series comparison data
  const timeSeriesComparison = Array.from({ length: 30 }, (_, i) => {
    const date = new Date(Date.now() - (29 - i) * 24 * 60 * 60 * 1000);
    return {
      date: date.toISOString().split('T')[0],
      versionA: Math.random() * 20 + 80 + Math.sin(i / 5) * 5,
      versionB: Math.random() * 20 + 88 + Math.sin(i / 4) * 6,
    };
  });

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 1000);
    return () => clearTimeout(timer);
  }, []);

  const versionA = workflowVersions.find(v => v.id === selectedVersionA);
  const versionB = workflowVersions.find(v => v.id === selectedVersionB);

  // Render statistical significance badge
  const renderSignificanceBadge = (pValue: number, isSignificant: boolean) => (
    <div className="flex items-center gap-2">
      {isSignificant ? (
        <Badge variant="default" className="bg-green-100 text-green-800">
          <CheckCircle2 className="h-3 w-3 mr-1" />
          Significant
        </Badge>
      ) : (
        <Badge variant="secondary">
          <AlertCircle className="h-3 w-3 mr-1" />
          Not Significant
        </Badge>
      )}
      <span className="text-sm text-muted-foreground">
        p = {pValue.toFixed(3)}
      </span>
    </div>
  );

  // Render comparison metric card
  const renderComparisonCard = (result: ComparisonResult) => {
    const isImprovement = result.improvement > 0;
    const ImprovementIcon = isImprovement ? TrendingUp : TrendingDown;

    return (
      <Card key={result.metric} className="transition-all hover:shadow-md">
        <CardHeader className="pb-4">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base">{result.metric}</CardTitle>
            {renderSignificanceBadge(result.pValue, result.isSignificant)}
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Version Comparison */}
            <div className="grid grid-cols-2 gap-4">
              <div className="text-center p-3 border rounded-lg">
                <div className="text-sm text-muted-foreground mb-1">Version A</div>
                <div className="text-2xl font-bold">
                  {result.versionA.value}
                  {result.metric === 'Avg Execution Time' ? 's' : 
                   result.metric.includes('Rate') ? '%' : ''}
                </div>
                <div className="text-xs text-muted-foreground">
                  CI: {result.versionA.confidence[0].toFixed(1)} - {result.versionA.confidence[1].toFixed(1)}
                </div>
              </div>
              <div className="text-center p-3 border rounded-lg">
                <div className="text-sm text-muted-foreground mb-1">Version B</div>
                <div className="text-2xl font-bold">
                  {result.versionB.value}
                  {result.metric === 'Avg Execution Time' ? 's' : 
                   result.metric.includes('Rate') ? '%' : ''}
                </div>
                <div className="text-xs text-muted-foreground">
                  CI: {result.versionB.confidence[0].toFixed(1)} - {result.versionB.confidence[1].toFixed(1)}
                </div>
              </div>
            </div>

            {/* Improvement Indicator */}
            <div className="text-center">
              <div className={`flex items-center justify-center gap-2 ${
                isImprovement ? 'text-green-600' : 'text-red-600'
              }`}>
                <ImprovementIcon className="h-4 w-4" />
                <span className="font-semibold">
                  {Math.abs(result.improvement).toFixed(1)}% 
                  {isImprovement ? ' improvement' : ' decline'}
                </span>
              </div>
            </div>

            {/* Recommendation */}
            <div className="text-center">
              {result.recommendation === 'version_b' ? (
                <Badge className="bg-green-100 text-green-800">
                  <Trophy className="h-3 w-3 mr-1" />
                  Version B Recommended
                </Badge>
              ) : result.recommendation === 'version_a' ? (
                <Badge className="bg-blue-100 text-blue-800">
                  <Trophy className="h-3 w-3 mr-1" />
                  Version A Recommended
                </Badge>
              ) : (
                <Badge variant="outline">
                  <Info className="h-3 w-3 mr-1" />
                  Inconclusive
                </Badge>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    );
  };

  // Render version summary
  const renderVersionSummary = (version: WorkflowVersion, label: string) => (
    <Card className="relative">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg">
            {label}: {version.version}
          </CardTitle>
          {version.isActive && (
            <Badge variant="default">Active</Badge>
          )}
        </div>
        <CardDescription>
          Created {new Date(version.createdAt).toLocaleDateString()} • 
          Sample size: {version.statistics.sampleSize.toLocaleString()}
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">{version.performance.successRate}%</div>
            <div className="text-sm text-muted-foreground">Success Rate</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">{version.performance.conversionRate}%</div>
            <div className="text-sm text-muted-foreground">Conversion</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-orange-600">{version.performance.avgExecutionTime}s</div>
            <div className="text-sm text-muted-foreground">Avg Time</div>
          </div>
        </div>
      </CardContent>
    </Card>
  );

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {[...Array(2)].map((_, i) => (
            <Card key={i} className="p-6">
              <div className="h-6 w-32 bg-gray-200 rounded animate-pulse mb-4"></div>
              <div className="space-y-2">
                <div className="h-4 w-full bg-gray-200 rounded animate-pulse"></div>
                <div className="h-4 w-3/4 bg-gray-200 rounded animate-pulse"></div>
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Controls */}
      <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
        <div className="flex items-center gap-2">
          <GitCompare className="h-5 w-5" />
          <h2 className="text-lg font-semibold">Performance Comparison</h2>
        </div>

        <div className="flex flex-wrap gap-2">
          <Select value={comparisonType} onValueChange={setComparisonType}>
            <SelectTrigger className="w-40">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="versions">Compare Versions</SelectItem>
              <SelectItem value="periods">Compare Periods</SelectItem>
              <SelectItem value="segments">Compare Segments</SelectItem>
            </SelectContent>
          </Select>

          <Select value={selectedVersionA} onValueChange={setSelectedVersionA}>
            <SelectTrigger className="w-32">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {workflowVersions.map(version => (
                <SelectItem key={version.id} value={version.id}>
                  {version.version}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <ArrowRight className="h-4 w-4 self-center text-muted-foreground" />

          <Select value={selectedVersionB} onValueChange={setSelectedVersionB}>
            <SelectTrigger className="w-32">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {workflowVersions.map(version => (
                <SelectItem key={version.id} value={version.id}>
                  {version.version}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Version Summaries */}
      {versionA && versionB && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {renderVersionSummary(versionA, 'Version A')}
          {renderVersionSummary(versionB, 'Version B')}
        </div>
      )}

      {/* Performance Trends Comparison */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BarChart3 className="h-5 w-5" />
            Performance Trends Comparison
          </CardTitle>
          <CardDescription>
            30-day performance comparison with statistical analysis
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={timeSeriesComparison}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={(value) => new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                />
                <YAxis />
                <Tooltip 
                  labelFormatter={(value) => new Date(value).toLocaleDateString()}
                  formatter={(value: number, name: string) => [
                    `${value.toFixed(1)}%`,
                    name === 'versionA' ? 'Version A' : 'Version B'
                  ]}
                />
                <Legend />
                <Line 
                  type="monotone" 
                  dataKey="versionA" 
                  stroke="#3b82f6" 
                  strokeWidth={2}
                  name="Version A"
                />
                <Line 
                  type="monotone" 
                  dataKey="versionB" 
                  stroke="#10b981" 
                  strokeWidth={2}
                  name="Version B"
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* Detailed Metric Comparisons */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {comparisonResults.map(renderComparisonCard)}
      </div>

      {/* Statistical Summary */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Calculator className="h-5 w-5" />
            Statistical Analysis Summary
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {comparisonResults.filter(r => r.isSignificant).length}
              </div>
              <div className="text-sm text-muted-foreground">
                Statistically Significant Improvements
              </div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">95%</div>
              <div className="text-sm text-muted-foreground">Confidence Level</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-orange-600">
                {versionB?.statistics.effectSize.toFixed(2)}
              </div>
              <div className="text-sm text-muted-foreground">Overall Effect Size</div>
            </div>
          </div>

          <div className="mt-6 p-4 bg-green-50 border border-green-200 rounded-lg">
            <div className="flex items-center gap-2 text-green-800 mb-2">
              <CheckCircle2 className="h-5 w-5" />
              <span className="font-semibold">Recommendation</span>
            </div>
            <p className="text-green-700">
              Version B shows statistically significant improvements across all key metrics. 
              Recommend deploying Version B to all users for an estimated{' '}
              <strong>20.8% improvement in conversion rate</strong> and{' '}
              <strong>25% reduction in execution time</strong>.
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

/**
 * Real-Time Monitoring Panel Component
 * 
 * Real-time performance monitoring with anomaly detection and intelligent alerting
 * Part of Story 3.3 - Performance Analytics Dashboard
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { 
  Activity, 
  AlertTriangle, 
  CheckCircle2, 
  Bell, 
  BellOff, 
  Zap, 
  Clock, 
  Users, 
  TrendingUp,
  TrendingDown,
  Pause,
  Play,
  Settings,
  Eye,
  XCircle,
  Info,
  Wifi,
  WifiOff
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  AreaChart,
  Area
} from 'recharts';

// Types for real-time monitoring
interface RealTimeMetric {
  id: string;
  name: string;
  value: number;
  unit: string;
  status: 'normal' | 'warning' | 'critical' | 'error';
  threshold: number;
  trend: number[];
  lastUpdated: string;
}

interface SystemAlert {
  id: string;
  type: 'anomaly' | 'threshold' | 'error' | 'performance';
  severity: 'low' | 'medium' | 'high' | 'critical';
  title: string;
  message: string;
  timestamp: string;
  workflowId?: string;
  isRead: boolean;
  isResolved: boolean;
}

interface WorkflowStatus {
  id: string;
  name: string;
  status: 'running' | 'idle' | 'error' | 'maintenance';
  currentExecutions: number;
  avgResponseTime: number;
  successRate: number;
  lastExecution: string;
  queueSize: number;
}

export const RealTimeMonitoringPanel: React.FC = () => {
  const [isMonitoring, setIsMonitoring] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'connected' | 'connecting' | 'disconnected'>('connected');
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [refreshInterval, setRefreshInterval] = useState('5');
  const [notifications, setNotifications] = useState(true);

  // Real-time metrics state
  const [realTimeMetrics, setRealTimeMetrics] = useState<RealTimeMetric[]>([
    {
      id: 'active_workflows',
      name: 'Active Workflows',
      value: 23,
      unit: '',
      status: 'normal',
      threshold: 50,
      trend: [20, 22, 21, 23, 22, 23],
      lastUpdated: new Date().toISOString()
    },
    {
      id: 'avg_response_time',
      name: 'Avg Response Time',
      value: 285,
      unit: 'ms',
      status: 'normal',
      threshold: 500,
      trend: [300, 295, 290, 285, 280, 285],
      lastUpdated: new Date().toISOString()
    },
    {
      id: 'success_rate',
      name: 'Success Rate',
      value: 98.7,
      unit: '%',
      status: 'normal',
      threshold: 95,
      trend: [98.2, 98.5, 98.3, 98.7, 98.6, 98.7],
      lastUpdated: new Date().toISOString()
    },
    {
      id: 'queue_size',
      name: 'Queue Size',
      value: 12,
      unit: '',
      status: 'warning',
      threshold: 10,
      trend: [8, 9, 10, 11, 12, 12],
      lastUpdated: new Date().toISOString()
    }
  ]);

  // System alerts state
  const [systemAlerts, setSystemAlerts] = useState<SystemAlert[]>([
    {
      id: 'alert-001',
      type: 'threshold',
      severity: 'medium',
      title: 'Queue Size Above Threshold',
      message: 'Workflow queue size has exceeded the warning threshold of 10 items',
      timestamp: new Date(Date.now() - 300000).toISOString(),
      workflowId: 'wf-001',
      isRead: false,
      isResolved: false
    },
    {
      id: 'alert-002',
      type: 'anomaly',
      severity: 'low',
      title: 'Response Time Spike Detected',
      message: 'Detected unusual response time pattern in lead generation workflow',
      timestamp: new Date(Date.now() - 600000).toISOString(),
      workflowId: 'wf-002',
      isRead: true,
      isResolved: false
    },
    {
      id: 'alert-003',
      type: 'performance',
      severity: 'high',
      title: 'High Error Rate',
      message: 'Email automation workflow showing increased error rate (5.2%)',
      timestamp: new Date(Date.now() - 900000).toISOString(),
      workflowId: 'wf-003',
      isRead: false,
      isResolved: true
    }
  ]);

  // Workflow status state
  const [workflowStatuses, setWorkflowStatuses] = useState<WorkflowStatus[]>([
    {
      id: 'wf-001',
      name: 'Lead Generation',
      status: 'running',
      currentExecutions: 5,
      avgResponseTime: 245,
      successRate: 98.5,
      lastExecution: new Date(Date.now() - 30000).toISOString(),
      queueSize: 8
    },
    {
      id: 'wf-002',
      name: 'Customer Onboarding',
      status: 'running',
      currentExecutions: 3,
      avgResponseTime: 180,
      successRate: 99.2,
      lastExecution: new Date(Date.now() - 45000).toISOString(),
      queueSize: 2
    },
    {
      id: 'wf-003',
      name: 'Email Automation',
      status: 'error',
      currentExecutions: 0,
      avgResponseTime: 520,
      successRate: 94.8,
      lastExecution: new Date(Date.now() - 120000).toISOString(),
      queueSize: 15
    }
  ]);

  // Real-time data points for charts
  const [chartData, setChartData] = useState(
    Array.from({ length: 20 }, (_, i) => ({
      time: new Date(Date.now() - (19 - i) * 5000).toLocaleTimeString(),
      responseTime: Math.floor(Math.random() * 100) + 200,
      successRate: 95 + Math.random() * 5,
      activeUsers: Math.floor(Math.random() * 20) + 40
    }))
  );

  // Simulate real-time updates
  useEffect(() => {
    if (!isMonitoring || !autoRefresh) return;

    const interval = setInterval(() => {
      // Update metrics
      setRealTimeMetrics(prev => prev.map(metric => ({
        ...metric,
        value: metric.value + (Math.random() - 0.5) * 2,
        trend: [...metric.trend.slice(1), metric.value],
        lastUpdated: new Date().toISOString()
      })));

      // Update chart data
      setChartData(prev => [
        ...prev.slice(1),
        {
          time: new Date().toLocaleTimeString(),
          responseTime: Math.floor(Math.random() * 100) + 200,
          successRate: 95 + Math.random() * 5,
          activeUsers: Math.floor(Math.random() * 20) + 40
        }
      ]);
    }, parseInt(refreshInterval) * 1000);

    return () => clearInterval(interval);
  }, [isMonitoring, autoRefresh, refreshInterval]);

  // Handle alert actions
  const markAlertAsRead = useCallback((alertId: string) => {
    setSystemAlerts(prev => prev.map(alert => 
      alert.id === alertId ? { ...alert, isRead: true } : alert
    ));
  }, []);

  const resolveAlert = useCallback((alertId: string) => {
    setSystemAlerts(prev => prev.map(alert => 
      alert.id === alertId ? { ...alert, isResolved: true } : alert
    ));
  }, []);

  // Render real-time metric card
  const renderMetricCard = (metric: RealTimeMetric) => {
    const statusColors = {
      normal: 'border-green-200 bg-green-50',
      warning: 'border-yellow-200 bg-yellow-50',
      critical: 'border-red-200 bg-red-50',
      error: 'border-red-300 bg-red-100'
    };

    const statusIcons = {
      normal: <CheckCircle2 className="h-4 w-4 text-green-600" />,
      warning: <AlertTriangle className="h-4 w-4 text-yellow-600" />,
      critical: <XCircle className="h-4 w-4 text-red-600" />,
      error: <XCircle className="h-4 w-4 text-red-700" />
    };

    return (
      <Card key={metric.id} className={`transition-all ${statusColors[metric.status]}`}>
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">{metric.name}</CardTitle>
            {statusIcons[metric.status]}
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="text-2xl font-bold">
              {metric.value.toFixed(metric.unit === '%' ? 1 : 0)}{metric.unit}
            </div>

            <div className="h-8">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={metric.trend.map((value, index) => ({ index, value }))}>
                  <Line 
                    type="monotone" 
                    dataKey="value" 
                    stroke={metric.status === 'normal' ? '#10b981' : 
                           metric.status === 'warning' ? '#f59e0b' : '#ef4444'} 
                    strokeWidth={2}
                    dot={false}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>

            <div className="text-xs text-muted-foreground">
              Last updated: {new Date(metric.lastUpdated).toLocaleTimeString()}
            </div>
          </div>
        </CardContent>
      </Card>
    );
  };

  // Render alert item
  const renderAlert = (alert: SystemAlert) => {
    const severityColors = {
      low: 'border-blue-200 bg-blue-50',
      medium: 'border-yellow-200 bg-yellow-50',
      high: 'border-orange-200 bg-orange-50',
      critical: 'border-red-200 bg-red-50'
    };

    const severityIcons = {
      low: <Info className="h-4 w-4 text-blue-600" />,
      medium: <AlertTriangle className="h-4 w-4 text-yellow-600" />,
      high: <AlertTriangle className="h-4 w-4 text-orange-600" />,
      critical: <XCircle className="h-4 w-4 text-red-600" />
    };

    return (
      <div
        key={alert.id}
        className={`p-3 border rounded-lg transition-all ${severityColors[alert.severity]} ${
          alert.isRead ? 'opacity-75' : ''
        }`}
      >
        <div className="flex items-start justify-between mb-2">
          <div className="flex items-center gap-2">
            {severityIcons[alert.severity]}
            <span className="font-medium">{alert.title}</span>
            {!alert.isRead && (
              <Badge variant="destructive" className="text-xs px-1 py-0">
                New
              </Badge>
            )}
          </div>
          <div className="text-xs text-muted-foreground">
            {new Date(alert.timestamp).toLocaleTimeString()}
          </div>
        </div>

        <p className="text-sm text-muted-foreground mb-3">{alert.message}</p>

        <div className="flex items-center gap-2">
          {!alert.isRead && (
            <Button size="sm" variant="outline" onClick={() => markAlertAsRead(alert.id)}>
              Mark as Read
            </Button>
          )}
          {!alert.isResolved && (
            <Button size="sm" variant="outline" onClick={() => resolveAlert(alert.id)}>
              Resolve
            </Button>
          )}
          {alert.isResolved && (
            <Badge variant="secondary" className="text-xs">
              Resolved
            </Badge>
          )}
        </div>
      </div>
    );
  };

  // Render workflow status
  const renderWorkflowStatus = (workflow: WorkflowStatus) => {
    const statusColors = {
      running: 'bg-green-100 text-green-800',
      idle: 'bg-gray-100 text-gray-800',
      error: 'bg-red-100 text-red-800',
      maintenance: 'bg-yellow-100 text-yellow-800'
    };

    const statusIcons = {
      running: <Activity className="h-3 w-3" />,
      idle: <Pause className="h-3 w-3" />,
      error: <XCircle className="h-3 w-3" />,
      maintenance: <Settings className="h-3 w-3" />
    };

    return (
      <div key={workflow.id} className="border rounded-lg p-4">
        <div className="flex items-center justify-between mb-3">
          <h4 className="font-semibold">{workflow.name}</h4>
          <Badge className={statusColors[workflow.status]}>
            {statusIcons[workflow.status]}
            {workflow.status.charAt(0).toUpperCase() + workflow.status.slice(1)}
          </Badge>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
          <div>
            <div className="text-muted-foreground">Executions</div>
            <div className="font-medium">{workflow.currentExecutions}</div>
          </div>
          <div>
            <div className="text-muted-foreground">Avg Time</div>
            <div className="font-medium">{workflow.avgResponseTime}ms</div>
          </div>
          <div>
            <div className="text-muted-foreground">Success Rate</div>
            <div className="font-medium">{workflow.successRate}%</div>
          </div>
          <div>
            <div className="text-muted-foreground">Queue</div>
            <div className="font-medium">{workflow.queueSize}</div>
          </div>
        </div>

        <div className="mt-3 text-xs text-muted-foreground">
          Last execution: {new Date(workflow.lastExecution).toLocaleString()}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Monitoring Controls */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Activity className="h-5 w-5" />
              <CardTitle>Real-Time Monitoring</CardTitle>
              <div className="flex items-center gap-1">
                {connectionStatus === 'connected' ? (
                  <Wifi className="h-4 w-4 text-green-600" />
                ) : (
                  <WifiOff className="h-4 w-4 text-red-600" />
                )}
                <span className={`text-xs ${
                  connectionStatus === 'connected' ? 'text-green-600' : 'text-red-600'
                }`}>
                  {connectionStatus}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <Switch 
                  checked={isMonitoring} 
                  onCheckedChange={setIsMonitoring}
                />
                <span className="text-sm">
                  {isMonitoring ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
                </span>
              </div>

              <div className="flex items-center gap-2">
                <Switch 
                  checked={notifications} 
                  onCheckedChange={setNotifications}
                />
                {notifications ? <Bell className="h-4 w-4" /> : <BellOff className="h-4 w-4" />}
              </div>

              <Select value={refreshInterval} onValueChange={setRefreshInterval}>
                <SelectTrigger className="w-24">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="1">1s</SelectItem>
                  <SelectItem value="5">5s</SelectItem>
                  <SelectItem value="10">10s</SelectItem>
                  <SelectItem value="30">30s</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardHeader>
      </Card>

      {/* Real-Time Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {realTimeMetrics.map(renderMetricCard)}
      </div>

      {/* Real-Time Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5" />
              Live Performance Metrics
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="time" />
                  <YAxis />
                  <Tooltip />
                  <Line 
                    type="monotone" 
                    dataKey="responseTime" 
                    stroke="#3b82f6" 
                    strokeWidth={2}
                    name="Response Time (ms)"
                  />
                  <Line 
                    type="monotone" 
                    dataKey="successRate" 
                    stroke="#10b981" 
                    strokeWidth={2}
                    name="Success Rate (%)"
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Users className="h-5 w-5" />
              Active Users
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="time" />
                  <YAxis />
                  <Tooltip />
                  <Area 
                    type="monotone" 
                    dataKey="activeUsers" 
                    stroke="#f59e0b" 
                    fill="#f59e0b" 
                    fillOpacity={0.3}
                    name="Active Users"
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* System Alerts */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5" />
              System Alerts
              {systemAlerts.filter(a => !a.isRead).length > 0 && (
                <Badge variant="destructive">
                  {systemAlerts.filter(a => !a.isRead).length} new
                </Badge>
              )}
            </CardTitle>
            <Button variant="outline" size="sm">
              <Eye className="h-4 w-4 mr-2" />
              View All
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-3 max-h-64 overflow-y-auto">
            {systemAlerts.length > 0 ? (
              systemAlerts.map(renderAlert)
            ) : (
              <div className="text-center py-8 text-muted-foreground">
                <CheckCircle2 className="h-8 w-8 mx-auto mb-2" />
                <p>No active alerts</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Workflow Status */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Zap className="h-5 w-5" />
            Workflow Status
          </CardTitle>
          <CardDescription>
            Real-time status of all active workflows
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {workflowStatuses.map(renderWorkflowStatus)}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

/**
 * ROI Analytics Panel Component
 * 
