// Types for ROI analytics
interface ROIMetric {
  id: string;
  name: string;
  value: number;
  previousValue: number;
  unit: string;
  trend: 'positive' | 'negative' | 'neutral';
  changePercent: number;
  benchmark?: number;
}

interface CostBreakdown {
  category: string;
  amount: number;
  percentage: number;
  change: number;
  color: string;
}

interface TimeSavingsAnalysis {
  workflow: string;
  manualTime: number;
  automatedTime: number;
  timeSaved: number;
  costSavings: number;
  frequency: number;
  totalSavings: number;
}

interface BusinessImpactMetric {
  metric: string;
  beforeAutomation: number;
  afterAutomation: number;
  improvement: number;
  businessValue: number;
  unit: string;
}

