interface AuthContextValue {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

interface AuthProviderProps {
  children: React.ReactNode;
}

// Routes that don't require authentication
const publicRoutes = [
  '/', // Landing page - CRITICAL ADDITION
  '/auth/login',
  '/auth/register',
  '/auth/forgot-password',
  '/auth/reset-password',
  '/templates', // Public template showcase
  '/pricing',   // Public pricing page
  '/about',     // Public about page
];

// Routes that should redirect authenticated users
const authRoutes = [
  '/auth/login',
  '/auth/register',
];

export function AuthProvider({ children }: AuthProviderProps) {
  const { user, isAuthenticated, isLoading, logout } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    if (!isLoading) {
      setIsInitialized(true);
    }
  }, [isLoading]);

  useEffect(() => {
    if (!isInitialized) return;

    const isPublicRoute = publicRoutes.some(route => pathname.startsWith(route));
    const isAuthRoute = authRoutes.some(route => pathname.startsWith(route));

    // Redirect authenticated users away from auth pages to dashboard
    if (isAuthenticated && isAuthRoute) {
      router.push('/dashboard');
      return;
    }

    // Redirect unauthenticated users to login (except for public routes)
    if (!isAuthenticated && !isPublicRoute) {
      router.push('/auth/login');
      return;
    }
  }, [isAuthenticated, pathname, router, isInitialized]);

  const value: AuthContextValue = {
    user,
    isAuthenticated,
    isLoading: isLoading || !isInitialized,
    logout,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuthContext() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuthContext must be used within an AuthProvider');
  }
  return context;
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { useAuth } from '@/hooks/useAuth';
import { LoginCredentials } from '@/lib/api/types';
import theme from '@/lib/theme';

const { luxuryTheme, themeUtils } = theme;

export function LoginForm() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { login, isAuthenticated } = useAuth();
  const router = useRouter();
  const searchParams = useSearchParams();
  const returnUrl = searchParams.get('returnUrl') || '/dashboard';

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      router.push(returnUrl);
    }
  }, [isAuthenticated, router, returnUrl]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSubmitting(true);

    try {
      const credentials: LoginCredentials = { email, password };
      await login(credentials);
      // Redirect will happen via useEffect after isAuthenticated changes
    } catch (err: any) {
      setError(err.message || 'Login failed. Please check your credentials.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className={luxuryTheme.components.authForm.container}>
      <div className={luxuryTheme.components.authForm.wrapper}>
        <div className={luxuryTheme.components.authForm.header}>
          <h2 className={luxuryTheme.components.authForm.title}>
            Sign in to your account
          </h2>
          <p className={`mt-2 text-sm ${luxuryTheme.colors.text.secondary}`}>
            Or{' '}
            <Link
              href="/auth/register"
              className={luxuryTheme.components.authForm.link}
            >
              create a new account
            </Link>
          </p>
        </div>

        <Card className={`${luxuryTheme.components.authForm.card} ${luxuryTheme.components.authForm.cardHover}`}>
          <CardHeader className="text-center">
            <CardTitle className={luxuryTheme.colors.text.primary}>Welcome Back</CardTitle>
            <CardDescription className={luxuryTheme.colors.text.secondary}>
              Enter your credentials to access your account
            </CardDescription>
          </CardHeader>

          <form onSubmit={handleSubmit}>
            <CardContent className="space-y-6">
              {error && (
                <div className={luxuryTheme.colors.status.error.full}>
                  <div className={`text-sm ${luxuryTheme.colors.status.error.text}`}>{error}</div>
                </div>
              )}

              <div className="space-y-2">
                <Label htmlFor="email" className={luxuryTheme.colors.text.primary}>Email address</Label>
                <Input
                  id="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Enter your email"
                  disabled={isSubmitting}
                  className={luxuryTheme.components.input.full}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="password" className={luxuryTheme.colors.text.primary}>Password</Label>
                <Input
                  id="password"
                  type="password"
                  autoComplete="current-password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  disabled={isSubmitting}
                  className={luxuryTheme.components.input.full}
                />
              </div>

              <div className="flex items-center justify-between">
                <div className="text-sm">
                  <Link
                    href="/auth/forgot-password"
                    className={luxuryTheme.components.authForm.link}
                  >
                    Forgot your password?
                  </Link>
                </div>
              </div>
            </CardContent>

            <CardFooter>
              <Button
                type="submit"
                className={`w-full ${themeUtils.getButtonClasses('primary')}`}
                disabled={isSubmitting || !email || !password}
              >
                {isSubmitting ? 'Signing in...' : 'Sign in'}
              </Button>
            </CardFooter>
          </form>
        </Card>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { useAuthContext } from './AuthProvider';

interface ProtectedRouteProps {
  children: React.ReactNode;
  fallback?: React.ReactNode;
}

export function ProtectedRoute({ children, fallback = null }: ProtectedRouteProps) {
  const { isAuthenticated, isLoading } = useAuthContext();

  if (isLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return fallback ? <>{fallback}</> : null;
  }

  return <>{children}</>;
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { useAuth } from '@/hooks/useAuth';
import { RegisterData } from '@/lib/api/types';
import theme from '@/lib/theme';

const { luxuryTheme, themeUtils } = theme;

export function RegisterForm() {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    confirmPassword: '',
    firstName: '',
    lastName: '',
    acceptTerms: false,
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { register } = useAuth();
  const router = useRouter();

  const handleChange = (field: string, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const validateForm = () => {
    if (!formData.email || !formData.password || !formData.firstName || !formData.lastName) {
      setError('All fields are required.');
      return false;
    }

    if (formData.password.length < 8) {
      setError('Password must be at least 8 characters long.');
      return false;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match.');
      return false;
    }

    if (!formData.acceptTerms) {
      setError('You must accept the terms and conditions.');
      return false;
    }

    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const userData: RegisterData = {
        email: formData.email,
        password: formData.password,
        first_name: formData.firstName,
        last_name: formData.lastName,
      };

      await register(userData);
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.message || 'Registration failed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className={luxuryTheme.components.authForm.container}>
      <div className={luxuryTheme.components.authForm.wrapper}>
        <div className={luxuryTheme.components.authForm.header}>
          <h2 className={luxuryTheme.components.authForm.title}>
            Create your account
          </h2>
          <p className={`mt-2 text-sm ${luxuryTheme.colors.text.secondary}`}>
            Or{' '}
            <Link
              href="/auth/login"
              className={luxuryTheme.components.authForm.link}
            >
              sign in to your existing account
            </Link>
          </p>
        </div>

        <Card className={`${luxuryTheme.components.authForm.card} ${luxuryTheme.components.authForm.cardHover}`}>
          <CardHeader className="text-center">
            <CardTitle className={luxuryTheme.colors.text.primary}>Join AI Marketing Pro</CardTitle>
            <CardDescription className={luxuryTheme.colors.text.secondary}>
              Create a new account to get started with intelligent marketing
            </CardDescription>
          </CardHeader>

          <form onSubmit={handleSubmit}>
            <CardContent className="space-y-6">
              {error && (
                <div className={luxuryTheme.colors.status.error.full}>
                  <div className={`text-sm ${luxuryTheme.colors.status.error.text}`}>{error}</div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="firstName" className={luxuryTheme.colors.text.primary}>First name</Label>
                  <Input
                    id="firstName"
                    type="text"
                    autoComplete="given-name"
                    required
                    value={formData.firstName}
                    onChange={(e) => handleChange('firstName', e.target.value)}
                    placeholder="Enter your first name"
                    disabled={isSubmitting}
                    className={luxuryTheme.components.input.full}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="lastName" className={luxuryTheme.colors.text.primary}>Last name</Label>
                  <Input
                    id="lastName"
                    type="text"
                    autoComplete="family-name"
                    required
                    value={formData.lastName}
                    onChange={(e) => handleChange('lastName', e.target.value)}
                    placeholder="Enter your last name"
                    disabled={isSubmitting}
                    className={luxuryTheme.components.input.full}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="email" className={luxuryTheme.colors.text.primary}>Email address</Label>
                <Input
                  id="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={formData.email}
                  onChange={(e) => handleChange('email', e.target.value)}
                  placeholder="Enter your email"
                  disabled={isSubmitting}
                  className={luxuryTheme.components.input.full}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="password" className={luxuryTheme.colors.text.primary}>Password</Label>
                <Input
                  id="password"
                  type="password"
                  autoComplete="new-password"
                  required
                  value={formData.password}
                  onChange={(e) => handleChange('password', e.target.value)}
                  placeholder="Create a password (min. 8 characters)"
                  disabled={isSubmitting}
                  className={luxuryTheme.components.input.full}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="confirmPassword" className={luxuryTheme.colors.text.primary}>Confirm password</Label>
                <Input
                  id="confirmPassword"
                  type="password"
                  autoComplete="new-password"
                  required
                  value={formData.confirmPassword}
                  onChange={(e) => handleChange('confirmPassword', e.target.value)}
                  placeholder="Confirm your password"
                  disabled={isSubmitting}
                  className={luxuryTheme.components.input.full}
                />
              </div>

              <div className="flex items-start space-x-3">
                <Checkbox
                  id="acceptTerms"
                  checked={formData.acceptTerms}
                  onCheckedChange={(checked) => handleChange('acceptTerms', checked as boolean)}
                  disabled={isSubmitting}
                  className="mt-1"
                />
                <Label htmlFor="acceptTerms" className={`text-sm leading-relaxed ${luxuryTheme.colors.text.secondary}`}>
                  I agree to the{' '}
                  <Link href="/terms" className={luxuryTheme.components.authForm.link}>
                    Terms and Conditions
                  </Link>{' '}
                  and{' '}
                  <Link href="/privacy" className={luxuryTheme.components.authForm.link}>
                    Privacy Policy
                  </Link>
                </Label>
              </div>
            </CardContent>

            <CardFooter>
              <Button
                type="submit"
                className={`w-full ${themeUtils.getButtonClasses('primary')}`}
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Creating account...' : 'Create account'}
              </Button>
            </CardFooter>
          </form>
        </Card>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { useAuthContext } from './AuthProvider';
import theme from '@/lib/theme';

const { luxuryTheme, componentStyles } = theme;
import { User, LogOut, Settings } from 'lucide-react';

interface UserNavProps {
  isMobile?: boolean;
}

export function UserNav({ isMobile = false }: UserNavProps) {
  const { user, isAuthenticated, logout } = useAuthContext();
  const router = useRouter();

  const handleLogout = async () => {
    await logout();
    router.push('/');
  };

  if (!isAuthenticated || !user) {
    // Professional unauthenticated state with luxury styling
    return (
      <div className={`flex items-center ${isMobile ? 'flex-col space-y-3 w-full' : 'space-x-3'}`}>
        {/* Sign In Button - Ghost variant with white text and yellow hover */}
        <motion.button
          onClick={() => router.push('/auth/login')}
          className={`${
            isMobile
              ? 'w-full justify-center py-3 px-6'
              : 'px-4 py-2.5'
          } bg-transparent ${luxuryTheme.colors.text.primary} font-medium rounded-xl transition-all duration-200 hover:${luxuryTheme.colors.text.accent} hover:bg-yellow-400/10 border border-transparent hover:border-yellow-400/20`}
          whileHover={{ scale: isMobile ? 1 : 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          Sign In
        </motion.button>

        {/* Sign Up Button - Primary CTA with luxury gold gradient */}
        <motion.button
          onClick={() => router.push('/auth/register')}
          className={`${
            isMobile
              ? 'w-full justify-center py-3 px-6'
              : 'px-6 py-2.5'
          } bg-gradient-to-r from-yellow-400 to-yellow-500 hover:from-yellow-500 hover:to-yellow-600 text-black font-semibold rounded-xl transition-all duration-200 shadow-lg shadow-yellow-400/25 hover:shadow-yellow-400/40`}
          whileHover={{ scale: isMobile ? 1 : 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          Get Started
        </motion.button>
      </div>
    );
  }

  // Professional authenticated state
  return (
    <div className={`flex items-center ${isMobile ? 'flex-col space-y-4 w-full' : 'space-x-4'}`}>
      {/* Professional User Profile Section */}
      <motion.div 
        className={`flex items-center space-x-3 ${
          isMobile 
            ? 'w-full justify-center p-4 bg-gray-800/50 backdrop-blur-md rounded-xl border border-gray-700'
            : 'bg-gray-800/30 backdrop-blur-md border border-gray-700/50 rounded-xl px-4 py-2'
        }`}
        whileHover={{ scale: 1.02 }}
      >
        {/* Luxury Avatar */}
        <div className="relative">
          <div className="w-10 h-10 bg-gradient-to-br from-yellow-400 to-yellow-500 rounded-xl flex items-center justify-center shadow-lg shadow-yellow-400/20">
            <User className="w-5 h-5 text-black" />
          </div>
          <div className="absolute -inset-1 bg-gradient-to-br from-yellow-400/20 to-transparent rounded-xl blur-sm opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
        </div>

        {/* User Welcome Text */}
        <div className="flex flex-col">
          <span className={`text-sm font-semibold ${luxuryTheme.colors.text.primary}`}>
            Welcome back!
          </span>
          <span className={`text-xs ${luxuryTheme.colors.text.accent} font-medium`}>
            {user.first_name || user.email.split('@')[0]}
          </span>
        </div>
      </motion.div>

      {/* Professional Action Buttons */}
      <div className={`flex ${isMobile ? 'w-full space-x-3' : 'space-x-2'}`}>
        {/* Settings Button */}
        <motion.button 
          onClick={() => router.push('/settings')}
          className={`${
            isMobile ? 'flex-1 py-3' : 'p-2.5'
          } bg-gray-800/50 backdrop-blur-md border border-gray-700 ${luxuryTheme.colors.text.secondary} hover:${luxuryTheme.colors.text.accent} hover:border-yellow-400/50 hover:bg-yellow-400/10 rounded-xl transition-all duration-200 flex items-center justify-center space-x-2`}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          <Settings className="w-4 h-4" />
          {isMobile && <span className="text-sm font-medium">Settings</span>}
        </motion.button>

        {/* Logout Button - Professional red styling */}
        <motion.button 
          onClick={handleLogout}
          className={`${
            isMobile ? 'flex-1 py-3' : 'p-2.5'
          } bg-red-900/30 backdrop-blur-md border border-red-700 text-red-300 hover:text-red-200 hover:border-red-500 hover:bg-red-900/50 rounded-xl transition-all duration-200 flex items-center justify-center space-x-2`}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          <LogOut className="w-4 h-4" />
          {isMobile && <span className="text-sm font-medium">Sign Out</span>}
        </motion.button>
      </div>
    </div>
  );
}

