  useWorkflowStatus: jest.fn()
}));

// Mock WebSocket
const mockWebSocket = {
  send: jest.fn(),
  close: jest.fn(),
  readyState: WebSocket.OPEN
};
// @ts-ignore
global.WebSocket = jest.fn(() => mockWebSocket);

describe('Story 3.1: Visual Workflow Debugging', () => {

