        steps: [
          {
            ...mockExecutionData.steps[0],
            performance_metrics: {
              cpu_usage: 25.5,
              memory_usage: 128.7
            }
          }
        ]
      };

      render(
        <ExecutionTimeline 
          executionData={executionDataWithMetrics}
          showMetrics={true}
        />
      );

      expect(screen.getByText(/CPU: 25.5%/)).toBeInTheDocument();
      expect(screen.getByText(/Memory: 128.7MB/)).toBeInTheDocument();
    });

    it('handles step selection', () => {
      const mockStepSelect = jest.fn();

      render(
        <ExecutionTimeline 
          executionData={mockExecutionData}
          onStepSelect={mockStepSelect}
        />
      );

      const firstStep = screen.getByText('First Step');
      fireEvent.click(firstStep.closest('div')!);

      expect(mockStepSelect).toHaveBeenCalledWith('step-1');
    });

    it('provides export functionality', () => {
      const mockExport = jest.fn();

      render(
        <ExecutionTimeline 
          executionData={mockExecutionData}
          onExport={mockExport}
        />
      );

      const exportButton = screen.getByText('Export');
      fireEvent.click(exportButton);

      expect(mockExport).toHaveBeenCalledWith('json');
    });

    it('filters steps by status', () => {
      render(
        <ExecutionTimeline 
          executionData={mockExecutionData}
        />
      );

      // Click failed filter
      const failedFilter = screen.getByText('Failed');
      fireEvent.click(failedFilter);

      // Should show no steps since none are failed
      expect(screen.getByText('No steps match the current filter')).toBeInTheDocument();
    });
  });

  // ========================================================================
  // WEBSOCKET INTEGRATION TESTS (AC: 2)
  // ========================================================================

  describe('useWorkflowStatus Hook Integration', () => {
    it('establishes WebSocket connection when enabled', () => {
      const mockConnect = jest.fn();
      (useWorkflowStatus as jest.Mock).mockReturnValue({
        ...mockWorkflowStatusReturn,
        connect: mockConnect
      });

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
          isDebugging={true}
        />
      );

      // Should connect when debugging is enabled
      expect(mockConnect).toHaveBeenCalled();
    });

    it('handles real-time status updates', async () => {
      const { rerender } = render(
        <WorkflowStatusOverlay node={mockNodeData} />
      );

      // Simulate status update
      const updatedNodeData = {
        ...mockNodeData,
        status: 'success' as const,
        progress: 100
      };

      (useWorkflowStatus as jest.Mock).mockReturnValue({
        ...mockWorkflowStatusReturn,
        nodeStatuses: {
          'test-node-1': updatedNodeData
        }
      });

      rerender(<WorkflowStatusOverlay node={updatedNodeData} />);

      // Should reflect the updated status
      expect(screen.getByRole('button')).toHaveAttribute(
        'aria-label', 
        expect.stringContaining('success')
      );
    });

    it('handles connection errors gracefully', () => {
      (useWorkflowStatus as jest.Mock).mockReturnValue({
        ...mockWorkflowStatusReturn,
        isConnected: false,
        error: 'Connection failed'
      });

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
          isDebugging={true}
        />
      );

      expect(screen.getByText('Error')).toBeInTheDocument();
    });
  });

  // ========================================================================
  // INTEGRATION TESTS (AC: 5)
  // ========================================================================

  describe('WorkflowDebuggingPanel Integration', () => {
    it('highlights current execution flow', () => {
      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test Workflow' } as any}
          isDebugging={true}
        />
      );

      // Should show workflow canvas with highlighted nodes
      expect(screen.getByText('Test Workflow')).toBeInTheDocument();
    });

    it('handles workflow execution', async () => {
      const mockExecute = jest.fn().mockResolvedValue({});

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
          isDebugging={true}
          onExecuteWorkflow={mockExecute}
        />
      );

      const executeButton = screen.getByText('Execute');
      fireEvent.click(executeButton);

      expect(mockExecute).toHaveBeenCalled();
    });

    it('switches between canvas and timeline views', () => {
      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
        />
      );

      // Should have tabs for different views
      expect(screen.getByText('Workflow Canvas')).toBeInTheDocument();
      expect(screen.getByText('Execution Timeline')).toBeInTheDocument();

      // Click timeline tab
      fireEvent.click(screen.getByText('Execution Timeline'));

      // Should show timeline content
      expect(screen.getByText('Execution Overview')).toBeInTheDocument();
    });

    it('handles export functionality', () => {
      const mockExport = jest.fn();

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
          onExport={mockExport}
        />
      );

      // Navigate to timeline tab
      fireEvent.click(screen.getByText('Execution Timeline'));

      // Find and click export button
      const exportButton = screen.getByText('Export');
      fireEvent.click(exportButton);

      expect(mockExport).toHaveBeenCalled();
    });
  });

  // ========================================================================
  // PERFORMANCE AND ACCESSIBILITY TESTS
  // ========================================================================

  describe('Performance and Accessibility', () => {
    it('meets accessibility requirements', () => {
      render(<WorkflowStatusOverlay node={mockNodeData} />);

      const statusButton = screen.getByRole('button');
      expect(statusButton).toHaveAttribute('aria-label');
      expect(statusButton).toHaveAttribute('title');
    });

    it('handles keyboard navigation', () => {
      render(<WorkflowStatusOverlay node={mockFailedNodeData} onErrorClick={jest.fn()} />);

      const statusButton = screen.getByRole('button');
      expect(statusButton).toHaveAttribute('tabIndex', '0');

      // Test keyboard activation
      fireEvent.keyDown(statusButton, { key: 'Enter' });
      // Should trigger click behavior
    });

    it('optimizes re-renders with memoization', () => {
      const mockOnClick = jest.fn();

      const { rerender } = render(
        <WorkflowStatusOverlay node={mockNodeData} onClick={mockOnClick} />
      );

      // Rerender with same props
      rerender(
        <WorkflowStatusOverlay node={mockNodeData} onClick={mockOnClick} />
      );

      // Component should be memoized and not cause unnecessary re-renders
      expect(screen.getByRole('button')).toBeInTheDocument();
    });
  });

  // ========================================================================
  // ERROR HANDLING TESTS
  // ========================================================================

  describe('Error Handling', () => {
    it('handles missing node data gracefully', () => {
      const incompleteNode = {
        id: 'incomplete',
        status: 'pending' as const
      };

      render(<WorkflowStatusOverlay node={incompleteNode} />);

      // Should render without errors
      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    it('handles WebSocket connection failures', () => {
      (useWorkflowStatus as jest.Mock).mockReturnValue({
        ...mockWorkflowStatusReturn,
        isConnected: false,
        error: 'WebSocket connection failed',
        connectionAttempts: 3
      });

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
          isDebugging={true}
        />
      );

      expect(screen.getByText(/Retry/)).toBeInTheDocument();
    });

    it('provides fallback when real-time updates fail', () => {
      const mockRefresh = jest.fn();
      (useWorkflowStatus as jest.Mock).mockReturnValue({
        ...mockWorkflowStatusReturn,
        isConnected: false,
        retry: mockRefresh
      });

      render(
        <WorkflowDebuggingPanel
          workflow={{ id: 1, name: 'Test' } as any}
        />
      );

      // Should provide manual refresh option
      const refreshButton = screen.getByLabelText(/refresh/i) || screen.getByRole('button', { name: /refresh/i });
      fireEvent.click(refreshButton);

      expect(mockRefresh).toHaveBeenCalled();
    });
  });
});

'use client';

import React, { useState, useEffect } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { cn } from '@/lib/utils';
import { AISuggestionEngine, PageContext } from '@/lib/ai/suggestion-engine';
import { PromptProcessor } from '@/lib/ai/prompt-processor';
import { ComponentIntelligence } from '@/lib/ai/component-intelligence';
import {
  Sparkles,
  Send,
  Wand2,
  Palette,
  Settings,
  Zap,
  X,
  Lightbulb,
  CheckCircle,
  Code,
  History,
  Copy,
  RotateCcw,
  Bot,
  User,
  Check,
  ChevronRight,
  Clock,
  TrendingUp,
  Eye
} from 'lucide-react';

interface AICustomizationPanelProps {
  className?: string;
  onOpenEditor?: () => void;
}

export interface AIEditHistory {
  id: string;
  prompt: string;
  changes: any;
  timestamp: Date;
  applied: boolean;
  description: string;
}

export function AICustomizationPanel({ className, onOpenEditor }: AICustomizationPanelProps) {
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [editHistory, setEditHistory] = useState<AIEditHistory[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(true);
  const [contextAnalysis, setContextAnalysis] = useState<any>(null);
  const [aiSuggestionEngine, setAiSuggestionEngine] = useState<AISuggestionEngine | null>(null);
  const [promptProcessor] = useState(() => new PromptProcessor());
  const [componentIntelligence] = useState(() => new ComponentIntelligence());
  const [smartSuggestions, setSmartSuggestions] = useState<any[]>([]);
  const [promptAnalysis, setPromptAnalysis] = useState<any>(null);

  const {
    components,
    aiContext,
    setAIContext,
    requestAICustomization,
    updateComponent,
    getSelectedComponent,
  } = useBuilderStore();

  const selectedComponent = getSelectedComponent();

  useEffect(() => {
    if (selectedComponent) {
      // Initialize AI engines with current page context
      initializeAIEngines();
      // Analyze component context for better AI suggestions
      analyzeComponentContext(selectedComponent);
      // Generate smart suggestions
      generateSmartSuggestions(selectedComponent);
    }
  }, [selectedComponent]);

  const initializeAIEngines = () => {
    const pageContext: PageContext = {
      existingComponents: components,
      pageGoals: ['conversion', 'engagement'],
      templateType: 'landing-page', // Could be derived from current template
      industry: 'tech' // Could be from user settings
    };

    const engine = new AISuggestionEngine(pageContext);
    setAiSuggestionEngine(engine);
  };

  const generateSmartSuggestions = (component: any) => {
    if (!aiSuggestionEngine) return;

    const suggestions = aiSuggestionEngine.generateContextualSuggestions(component);
    setSmartSuggestions(suggestions);
  };

  const analyzeComponentContext = (component: any) => {
    const analysis = {
      type: component.type,
      hasStyle: !!component.props.style,
      hasAnimation: !!(component.props.className?.includes('animate') || component.props.animation),
      hasForm: component.type === 'form' || component.type === 'input',
      hasButton: component.type === 'button',
      hasText: component.type === 'text' || component.props.content,
      isContainer: component.type === 'container' || component.type === 'div',
      complexity: 'medium',
      recommendations: []
    };

    // Generate contextual recommendations
    const recommendations: string[] = [];

    if (analysis.hasButton) {
      recommendations.push('button-enhancement');
    }
    if (analysis.hasText) {
      recommendations.push('text-optimization');
    }
    if (analysis.hasForm) {
      recommendations.push('form-ux');
    }
    if (!analysis.hasAnimation) {
      recommendations.push('add-animation');
    }
    if (analysis.isContainer) {
      recommendations.push('layout-optimization');
    }

    setContextAnalysis({ ...analysis, recommendations });
  };

  const handleSubmitPrompt = async () => {
    if (!prompt.trim() || !selectedComponent) return;

    setIsProcessing(true);
    try {
      // Analyze prompt with advanced NLP
      const analysis = promptProcessor.analyzePrompt(prompt);
      setPromptAnalysis(analysis);

      // Enhanced AI processing with component context and intelligence
      const response = await processAIRequestWithIntelligence(selectedComponent, prompt, analysis);

      // Add to history
      const newEdit: AIEditHistory = {
        id: `ai-${Date.now()}`,
        prompt,
        changes: response.changes,
        timestamp: new Date(),
        applied: false,
        description: response.description
      };

      setEditHistory(prev => [newEdit, ...prev]);

      // Apply changes
      updateComponent(selectedComponent.id, response.changes);

      // Regenerate suggestions after changes
      generateSmartSuggestions({ ...selectedComponent, ...response.changes });

      setPrompt('');
    } catch (error) {
      console.error('AI customization failed:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  const processAIRequestWithIntelligence = async (component: any, userPrompt: string, analysis: any) => {
    // Simulate AI processing with enhanced intelligence
    return new Promise<any>((resolve) => {
      setTimeout(() => {
        const changes = generateIntelligentAIChanges(component, userPrompt, analysis);
        resolve({
          changes,
          description: `Applied: ${analysis.expandedPrompt.substring(0, 50)}...`,
          confidence: analysis.confidence,
          suggestions: analysis.suggestions
        });
      }, 1200);
    });
  };

  const generateIntelligentAIChanges = (component: any, prompt: string, analysis: any) => {
    const changes: any = { props: { ...component.props } };

    // Apply color changes based on extracted entities
    if (analysis.entities.colors.length > 0) {
      const primaryColor = normalizeColor(analysis.entities.colors[0]);
      changes.props.style = {
        ...changes.props.style,
        backgroundColor: primaryColor,
        color: getContrastColor(primaryColor)
      };
    }

    // Apply dimension changes
    analysis.entities.dimensions.forEach((dimension: string) => {
      if (dimension === 'large' || dimension === 'bigger') {
        changes.props.style = {
          ...changes.props.style,
          padding: '20px 24px',
          fontSize: '18px'
        };
      } else if (dimension === 'small' || dimension === 'compact') {
        changes.props.style = {
          ...changes.props.style,
          padding: '8px 12px',
          fontSize: '14px'
        };
      }
    });

    // Apply animation changes
    if (analysis.entities.animations.length > 0) {
      const animationClasses = analysis.entities.animations
        .map(anim => getAnimationClass(anim))
        .join(' ');
      changes.props.className = `${changes.props.className || ''} ${animationClasses}`.trim();
    }

    // Apply style properties
    if (analysis.entities.properties.length > 0) {
      analysis.entities.properties.forEach((property: string) => {
        if (property === 'border-radius') {
          changes.props.style = {
            ...changes.props.style,
            borderRadius: '12px'
          };
        } else if (property === 'box-shadow') {
          changes.props.style = {
            ...changes.props.style,
            boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
          };
        }
      });
    }

    // Apply intent-based changes
    switch (analysis.intent) {
      case 'style':
        changes.props.style = {
          ...changes.props.style,
          borderRadius: '8px',
          boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
        };
        break;
      case 'interaction':
        changes.props.className = `${changes.props.className || ''} hover:scale-105 transition-all duration-200`.trim();
        break;
      case 'layout':
        changes.props.style = {
          ...changes.props.style,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        };
        break;
    }

    return changes;
  };

  // Utility functions
  const normalizeColor = (color: string): string => {
    const colorMap: Record<string, string> = {
      'blue': '#3B82F6',
      'red': '#EF4444',
      'green': '#10B981',
      'yellow': '#F59E0B',
      'purple': '#8B5CF6',
      'pink': '#EC4899'
    };
    return colorMap[color.toLowerCase()] || color;
  };

  const getContrastColor = (backgroundColor: string): string => {
    // Simple contrast calculation - in production would use proper color theory
    const darkColors = ['#EF4444', '#8B5CF6', '#3B82F6'];
    return darkColors.includes(backgroundColor) ? '#FFFFFF' : '#000000';
  };

  const getAnimationClass = (animation: string): string => {
    const animationMap: Record<string, string> = {
      'hover': 'hover:scale-105',
      'transition': 'transition-all duration-200',
      'fade': 'hover:opacity-80',
      'scale': 'hover:scale-105',
      'bounce': 'hover:animate-bounce'
    };
    return animationMap[animation] || 'transition-all duration-200';
  };

  const applyEdit = (edit: AIEditHistory) => {
    if (!selectedComponent) return;

    updateComponent(selectedComponent.id, edit.changes);

    setEditHistory(prev => 
      prev.map(e => e.id === edit.id ? { ...e, applied: true } : e)
    );
  };

  const revertEdit = (edit: AIEditHistory) => {
    // Find the previous state
    const currentIndex = editHistory.findIndex(e => e.id === edit.id);
    if (currentIndex > 0) {
      const previousEdit = editHistory[currentIndex - 1];
      updateComponent(selectedComponent!.id, previousEdit.changes);
    } else {
      // Revert to original
      updateComponent(selectedComponent!.id, { props: {} });
    }

    setEditHistory(prev => 
      prev.map(e => e.id === edit.id ? { ...e, applied: false } : e)
    );
  };

  const handleClose = () => {
    setAIContext(null);
  };

  const getQuickActions = () => {
    if (!contextAnalysis) return [];

    const actions = [
      {
        id: 'modernize',
        title: 'Modern Look',
        icon: Wand2,
        prompt: 'Make this component look modern and professional with proper spacing and shadows',
        color: 'purple'
      },
      {
        id: 'colors',
        title: 'Brand Colors',
        icon: Palette,
        prompt: 'Apply my brand colors to this component',
        color: 'blue'
      },
      {
        id: 'animate',
        title: 'Add Animation',
        icon: Zap,
        prompt: 'Add subtle hover animations and transitions',
        color: 'yellow'
      },
      {
        id: 'mobile',
        title: 'Mobile Optimize',
        icon: Settings,
        prompt: 'Optimize this component for mobile devices',
        color: 'green'
      }
    ];

    return actions.filter(action => 
      contextAnalysis.recommendations.includes(`${action.id}-enhancement`) ||
      contextAnalysis.recommendations.includes(action.id)
    );
  };

  const getContextualSuggestions = () => {
    if (!smartSuggestions.length) return getBasicSuggestions();

    return smartSuggestions
      .filter(suggestion => suggestion.priority === 'high')
      .slice(0, 3)
      .map(suggestion => suggestion.prompt);
  };

  const getBasicSuggestions = () => {
    if (!selectedComponent) return [];

    const suggestions: string[] = [];

    if (selectedComponent.type === 'button') {
      suggestions.push(
        'Make this button more prominent with better contrast',
        'Add smooth hover animations and micro-interactions',
        'Apply consistent brand colors and typography'
      );
    }

    if (selectedComponent.type === 'text') {
      suggestions.push(
        'Optimize typography hierarchy and readability',
        'Add responsive font scaling for mobile devices',
        'Improve line spacing and visual rhythm'
      );
    }

    if (selectedComponent.type === 'container') {
      suggestions.push(
        'Add structured spacing using design system',
        'Include depth with subtle shadows and borders',
        'Optimize layout for responsive breakpoints'
      );
    }

    return suggestions.slice(0, 3);
  };

  if (!selectedComponent) {
    return (
      <div className={cn("w-80 bg-white border-l border-gray-200 p-6", className)}>
        <div className="text-center text-gray-500">
          <Bot className="w-12 h-12 mx-auto mb-4 text-gray-300" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">
            AI Assistant
          </h3>
          <p className="text-sm mb-4">
            Select a component to start customizing with AI
          </p>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-left">
            <h4 className="text-sm font-medium text-blue-900 mb-2">
              🎯 How to use:
            </h4>
            <ul className="text-xs text-blue-700 space-y-1">
              <li>• Click any component on the canvas</li>
              <li>• Use natural language prompts</li>
              <li>• Apply AI suggestions instantly</li>
              <li>• Undo/redo changes easily</li>
            </ul>
          </div>

          {onOpenEditor && (
            <button
              onClick={onOpenEditor}
              className="mt-4 w-full px-4 py-2 bg-purple-500 text-white rounded-lg text-sm font-medium hover:bg-purple-600 transition-colors"
            >
              Open Advanced Editor
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className={cn("w-80 bg-white border-l border-gray-200 flex flex-col", className)}>
      {/* Header */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Bot className="w-5 h-5 text-purple-500" />
            <h3 className="text-lg font-semibold text-gray-900">
              AI Assistant
            </h3>
          </div>
          <button
            onClick={handleClose}
            className="text-gray-400 hover:text-gray-600"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="mt-2 text-sm text-gray-600">
          Customizing: <span className="font-medium">{selectedComponent.name}</span>
          <span className="text-xs text-gray-500 ml-2">({selectedComponent.type})</span>
        </div>
      </div>

      {/* Context Analysis */}
      {contextAnalysis && (
        <div className="p-3 bg-blue-50 border-b border-gray-200">
          <div className="flex items-center justify-between text-xs">
            <span className="text-blue-700 font-medium">AI Analysis</span>
            <span className="text-blue-600">{contextAnalysis.recommendations.length} suggestions</span>
          </div>
        </div>
      )}

      {/* AI Prompt Input */}
      <div className="p-4 border-b border-gray-200">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Describe what you want:
        </label>
        <div className="relative">
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="e.g., Make this button larger with blue color..."
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent resize-none text-sm"
            rows={3}
          />
          <button
            onClick={handleSubmitPrompt}
            disabled={!prompt.trim() || isProcessing}
            className={cn(
              "absolute bottom-2 right-2 p-2 rounded-lg transition-colors duration-200",
              prompt.trim() && !isProcessing
                ? "bg-purple-500 text-white hover:bg-purple-600"
                : "bg-gray-100 text-gray-400 cursor-not-allowed"
            )}
          >
            {isProcessing ? (
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <Send className="w-4 h-4" />
            )}
          </button>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-sm font-medium text-gray-700">Quick Actions</h4>
          <button
            onClick={() => setShowSuggestions(!showSuggestions)}
            className="text-xs text-gray-500 hover:text-gray-700"
          >
            {showSuggestions ? 'Hide' : 'Show'}
          </button>
        </div>

        {showSuggestions && (
          <div className="space-y-2">
            {/* AI-Powered Smart Suggestions */}
            {smartSuggestions.length > 0 && (
              <div className="mb-3">
                <div className="text-xs text-blue-600 font-medium mb-2 flex items-center gap-1">
                  <Bot className="w-3 h-3" />
                  AI Recommendations
                </div>
                {smartSuggestions.slice(0, 2).map((suggestion, index) => (
                  <button
                    key={`smart-${index}`}
                    onClick={() => setPrompt(suggestion.prompt)}
                    className={cn(
                      "w-full text-left p-2 text-xs border rounded-lg transition-colors mb-1",
                      suggestion.priority === 'high' 
                        ? 'bg-blue-50 border-blue-200 hover:bg-blue-100 text-blue-700'
                        : 'bg-gray-50 border-gray-200 hover:bg-gray-100 text-gray-700'
                    )}
                  >
                    <div className="flex items-start gap-2">
                      <span className={cn(
                        "w-1.5 h-1.5 rounded-full mt-1.5 flex-shrink-0",
                        suggestion.priority === 'high' ? 'bg-blue-500' : 'bg-gray-400'
                      )} />
                      <div>
                        <div className="font-medium">{suggestion.title}</div>
                        <div className="text-xs opacity-75 mt-0.5">{suggestion.description}</div>
                      </div>
                      <div className="ml-auto text-xs opacity-60">
                        {Math.round(suggestion.confidence * 100)}%
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}

            {/* Basic Contextual Suggestions */}
            <div className="text-xs text-gray-600 font-medium mb-2">Quick Suggestions</div>
            {getContextualSuggestions().map((suggestion, index) => (
              <button
                key={`basic-${index}`}
                onClick={() => setPrompt(suggestion)}
                className="w-full text-left p-2 text-xs bg-gray-50 border border-gray-200 rounded-lg hover:bg-gray-100 transition-colors"
              >
                💡 {suggestion}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Smart Actions */}
      <div className="p-4 border-b border-gray-200">
        <h4 className="text-sm font-medium text-gray-700 mb-3">Smart Actions</h4>
        <div className="grid grid-cols-2 gap-2">
          {getQuickActions().map((action) => (
            <button
              key={action.id}
              onClick={() => setPrompt(action.prompt)}
              className={cn(
                "flex items-center space-x-2 p-2 border rounded-lg transition-colors duration-200 text-xs",
                `border-${action.color}-200 bg-${action.color}-50 hover:bg-${action.color}-100`
              )}
            >
              <action.icon className={cn("w-3 h-3", `text-${action.color}-500`)} />
              <span className={cn(`text-${action.color}-700`)}>{action.title}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Edit History */}
      <div className="flex-1 overflow-y-auto">
        <div className="p-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-medium text-gray-700 flex items-center">
              <History className="w-4 h-4 mr-2" />
              Edit History
            </h4>
            <button
              onClick={() => setShowHistory(!showHistory)}
              className="text-xs text-gray-500 hover:text-gray-700"
            >
              {showHistory ? 'Hide' : 'Show'}
            </button>
          </div>
        </div>

        {showHistory && (
          <div className="p-4 space-y-2">
            {editHistory.length === 0 ? (
              <p className="text-xs text-gray-500 text-center py-4">
                No AI edits yet. Start customizing!
              </p>
            ) : (
              editHistory.map((edit) => (
                <div
                  key={edit.id}
                  className={cn(
                    "p-3 border rounded-lg text-xs",
                    edit.applied 
                      ? "border-green-200 bg-green-50" 
                      : "border-gray-200 bg-gray-50"
                  )}
                >
                  <div className="flex items-start justify-between mb-1">
                    <div className="flex-1">
                      <div className="font-medium text-gray-800">{edit.description}</div>
                      <div className="text-gray-500">
                        {edit.timestamp.toLocaleTimeString()}
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      {edit.applied ? (
                        <button
                          onClick={() => revertEdit(edit)}
                          className="text-blue-600 hover:text-blue-800"
                          title="Revert"
                        >
                          <RotateCcw className="w-3 h-3" />
                        </button>
                      ) : (
                        <button
                          onClick={() => applyEdit(edit)}
                          className="text-green-600 hover:text-green-800"
                          title="Apply"
                        >
                          <Check className="w-3 h-3" />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* Current Properties */}
      <div className="border-t border-gray-200 p-4">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-sm font-medium text-gray-700">
            Properties
          </h4>
          {onOpenEditor && (
            <button
              onClick={onOpenEditor}
              className="text-xs text-purple-600 hover:text-purple-800 flex items-center gap-1"
            >
              <Code className="w-3 h-3" />
              Advanced
            </button>
          )}
        </div>

        <div className="space-y-2 max-h-32 overflow-y-auto">
          {Object.entries(selectedComponent.props || {}).map(([key, value]) => (
            <div key={key} className="flex justify-between text-xs">
              <span className="text-gray-600 capitalize">{key}:</span>
              <span className="text-gray-900 font-mono truncate ml-2 max-w-[100px]">
                {typeof value === 'object' ? JSON.stringify(value) : String(value)}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { PublishingModal } from './PublishingModal';
import { cn } from '@/lib/utils';
import {
  Save,
  Undo,
  Redo,
  Eye,
  Grid,
  ZoomIn,
  ZoomOut,
  RotateCcw,
  Copy,
  Trash2,
  Settings,
  Play,
  Download,
  Share,
  Smartphone,
  Tablet,
  Monitor,
  Globe,
} from 'lucide-react';

type ViewportSize = 'mobile' | 'tablet' | 'desktop';

export function BuilderToolbar() {
  const [viewport, setViewport] = useState<ViewportSize>('desktop');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [isPublishingModalOpen, setIsPublishingModalOpen] = useState(false);

  const {
    components,
    selectedComponentId,
    zoom,
    gridEnabled,
    snapToGrid,
    setZoom,
    toggleGrid,
    toggleSnapToGrid,
    clearCanvas,
    removeComponent,
    duplicateComponent,
    getSelectedComponent,
  } = useBuilderStore();

  const selectedComponent = getSelectedComponent();
  const hasComponents = components.length > 0;
  const hasSelection = selectedComponentId !== null;

  const handleZoomIn = () => setZoom(Math.min(3, zoom + 0.25));
  const handleZoomOut = () => setZoom(Math.max(0.25, zoom - 0.25));
  const handleResetZoom = () => setZoom(1);

  const handleSave = () => {
    // TODO: Implement actual save functionality
    const siteData = {
      components,
      timestamp: new Date().toISOString(),
      version: '1.0.0',
    };

    // Save to localStorage for now
    localStorage.setItem('builder-project', JSON.stringify(siteData));

    // Show success feedback
    console.log('Project saved successfully!', siteData);
  };

  const handlePreview = () => {
    setIsPreviewMode(!isPreviewMode);
  };

  const handleExport = () => {
    // Generate HTML export
    const htmlContent = generateHTMLExport();
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'my-site.html';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const generateHTMLExport = () => {
    const componentHTML = components.map(component => 
      `<div class="component" data-type="${component.type}" style="position: absolute; left: ${component.position.x}px; top: ${component.position.y}px; width: ${component.size.width}px; height: ${component.size.height}px;">
        ${component.props?.content || `${component.type} component`}
      </div>`
    ).join('\n');

    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>My Site</title>
    <style>
        body { margin: 0; font-family: Arial, sans-serif; }
        .component { border: 1px solid #ccc; padding: 10px; }
    </style>
</head>
<body>
    <div class="site-container">
        ${componentHTML}
    </div>
</body>
</html>`;
  };

  const handleShare = () => {
    // Generate shareable link
    const shareData = {
      components,
      metadata: {
        title: 'My Awesome Site',
        created: new Date().toISOString(),
      }
    };

    // Generate a shareable URL (in real implementation, this would be saved to backend)
    const shareId = btoa(JSON.stringify(shareData)).substring(0, 12);
    const shareUrl = `${window.location.origin}/preview/${shareId}`;

    // Copy to clipboard
    navigator.clipboard.writeText(shareUrl).then(() => {
      console.log('Share URL copied to clipboard:', shareUrl);
    });
  };

  const handleDeleteSelected = () => {
    if (selectedComponentId) {
      removeComponent(selectedComponentId);
    }
  };

  const handleDuplicateSelected = () => {
    if (selectedComponentId) {
      duplicateComponent(selectedComponentId);
    }
  };

  const handlePublish = () => {
    setIsPublishingModalOpen(true);
  };

  const viewportConfigs = {
    mobile: { width: '375px', icon: Smartphone, label: 'Mobile' },
    tablet: { width: '768px', icon: Tablet, label: 'Tablet' },
    desktop: { width: '100%', icon: Monitor, label: 'Desktop' },
  };

  return (
    <>
      <div className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4">
        {/* Left Section - File Operations */}
        <div className="flex items-center space-x-2">
          <button
            onClick={handleSave}
            className="flex items-center space-x-2 px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors duration-200"
            title="Save project to local storage"
          >
            <Save className="w-4 h-4" />
            <span className="text-sm font-medium">Save</span>
          </button>

          <div className="w-px h-6 bg-gray-300" />

          <button
            className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors duration-200"
            title="Undo (Not implemented)"
            disabled
          >
            <Undo className="w-4 h-4" />
          </button>
          <button
            className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors duration-200"
            title="Redo (Not implemented)"
            disabled
          >
            <Redo className="w-4 h-4" />
          </button>
        </div>

        {/* Center Section - Viewport Controls */}
        <div className="flex items-center space-x-1 bg-gray-100 rounded-lg p-1">
          {Object.entries(viewportConfigs).map(([key, config]) => {
            const Icon = config.icon;
            return (
              <button
                key={key}
                onClick={() => setViewport(key as ViewportSize)}
                className={cn(
                  "flex items-center space-x-1 px-3 py-1.5 rounded-md text-sm font-medium transition-colors duration-200",
                  viewport === key
                    ? "bg-white text-gray-900 shadow-sm"
                    : "text-gray-600 hover:text-gray-900"
                )}
                title={config.label}
              >
                <Icon className="w-4 h-4" />
                <span className="hidden sm:inline">{config.label}</span>
              </button>
            );
          })}
        </div>

        {/* Right Section - Tools */}
        <div className="flex items-center space-x-2">
          {/* Canvas Tools */}
          <div className="flex items-center space-x-1 bg-gray-100 rounded-lg p-1">
            <button
              onClick={toggleGrid}
              className={cn(
                "p-2 rounded-md transition-colors duration-200",
                gridEnabled
                  ? "bg-blue-500 text-white"
                  : "text-gray-600 hover:text-gray-900 hover:bg-gray-200"
              )}
              title="Toggle Grid"
            >
              <Grid className="w-4 h-4" />
            </button>

            <button
              onClick={handleZoomOut}
              className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-200 rounded-md transition-colors duration-200"
              title="Zoom Out"
            >
              <ZoomOut className="w-4 h-4" />
            </button>

            <button
              onClick={handleResetZoom}
              className="px-2 py-1 text-xs font-medium text-gray-600 hover:text-gray-900 hover:bg-gray-200 rounded-md transition-colors duration-200 min-w-[3rem]"
              title="Reset Zoom"
            >
              {Math.round(zoom * 100)}%
            </button>

            <button
              onClick={handleZoomIn}
              className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-200 rounded-md transition-colors duration-200"
              title="Zoom In"
            >
              <ZoomIn className="w-4 h-4" />
            </button>
          </div>

          <div className="w-px h-6 bg-gray-300" />

          {/* Selection Tools */}
          {hasSelection && (
            <>
              <button
                onClick={handleDuplicateSelected}
                className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors duration-200"
                title="Duplicate Selected"
              >
                <Copy className="w-4 h-4" />
              </button>
              <button
                onClick={handleDeleteSelected}
                className="p-2 text-red-600 hover:text-red-700 hover:bg-red-50 rounded-lg transition-colors duration-200"
                title="Delete Selected"
              >
                <Trash2 className="w-4 h-4" />
              </button>
              <div className="w-px h-6 bg-gray-300" />
            </>
          )}

          {/* Canvas Actions */}
          {hasComponents && (
            <button
              onClick={clearCanvas}
              className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors duration-200"
              title="Clear Canvas"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          )}

          <div className="w-px h-6 bg-gray-300" />

          {/* Preview & Export */}
          <button
            onClick={handlePreview}
            className={cn(
              "flex items-center space-x-2 px-3 py-2 rounded-lg transition-colors duration-200",
              isPreviewMode
                ? "bg-green-500 text-white hover:bg-green-600"
                : "bg-gray-100 text-gray-700 hover:bg-gray-200"
            )}
            title="Toggle Preview Mode"
          >
            <Eye className="w-4 h-4" />
            <span className="text-sm font-medium">
              {isPreviewMode ? 'Edit' : 'Preview'}
            </span>
          </button>

          <button
            onClick={handleExport}
            className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors duration-200"
            title="Export as HTML"
            disabled={!hasComponents}
          >
            <Download className="w-4 h-4" />
          </button>

          <button
            onClick={handleShare}
            className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors duration-200"
            title="Generate Shareable Link"
            disabled={!hasComponents}
          >
            <Share className="w-4 h-4" />
          </button>

          {/* Publish Button - Primary Action */}
          <button
            onClick={handlePublish}
            disabled={!hasComponents}
            className={cn(
              "flex items-center space-x-2 px-4 py-2 rounded-lg font-medium transition-all duration-200",
              hasComponents
                ? "bg-gradient-to-r from-green-500 to-green-600 text-white hover:from-green-600 hover:to-green-700 shadow-lg hover:shadow-xl hover:scale-105"
                : "bg-gray-300 text-gray-500 cursor-not-allowed"
            )}
            title={hasComponents ? "Publish your site live" : "Add components before publishing"}
          >
            <Globe className="w-4 h-4" />
            <span>Publish</span>
          </button>

          <button
            className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors duration-200"
            title="Settings"
          >
            <Settings className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Publishing Modal */}
      <PublishingModal
        isOpen={isPublishingModalOpen}
        onClose={() => setIsPublishingModalOpen(false)}
      />
    </>
  );
}

/**
 * Business Context Analyzer Component
 * 
 * Analyzes business information and provides context for template recommendations
 * Part of Story 3.7: Context-Aware Template Recommendations
 */

'use client';

import React, { useState, useCallback, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Loader2, Brain, Target, Palette, Globe, TrendingUp, CheckCircle2 } from 'lucide-react';

import {
  BusinessContextAnalyzerProps,
  BusinessAnalysisRequest,
  BusinessAnalysisResult,
  BusinessIndustry
} from '@/types/context-aware-templates';

const industries: BusinessIndustry[] = [
  'technology', 'healthcare', 'finance', 'education', 'retail',
  'manufacturing', 'real-estate', 'food-service', 'professional-services',
  'nonprofit', 'entertainment', 'fitness', 'automotive', 'beauty', 'travel', 'other'
];

const businessGoals = [
  'Generate leads',
  'Increase brand awareness',
  'Drive online sales',
  'Educate customers',
  'Build community',
  'Showcase portfolio',
  'Collect feedback',
  'Support customers',
  'Recruit talent',
  'Partner outreach'
];

const designStyles = ['modern', 'classic', 'minimal', 'bold'] as const;

export const BusinessContextAnalyzer: React.FC<BusinessContextAnalyzerProps> = ({
  onAnalysisComplete,
  initialData,
  isLoading: externalLoading,
  className = ''
}) => {
  // Form State
  const [formData, setFormData] = useState<BusinessAnalysisRequest>({
    business_name: initialData?.business_name || '',
    business_description: initialData?.business_description || '',
    industry: initialData?.industry || undefined,
    target_audience: initialData?.target_audience || '',
    business_goals: initialData?.business_goals || [],
    existing_brand_colors: initialData?.existing_brand_colors || [],
    preferred_style: initialData?.preferred_style || undefined,
    website_url: initialData?.website_url || '',
    competitors: initialData?.competitors || []
  });

  // UI State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisStep, setAnalysisStep] = useState('');
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});
  const [analysisResult, setAnalysisResult] = useState<BusinessAnalysisResult | null>(null);

  // Brand Colors State
  const [colorInput, setColorInput] = useState('');
  const [competitorInput, setCompetitorInput] = useState('');

  // Validation
  const validateForm = useCallback((): boolean => {
    const errors: Record<string, string> = {};

    if (!formData.business_name.trim()) {
      errors.business_name = 'Business name is required';
    }

    if (!formData.business_description.trim() || formData.business_description.length < 20) {
      errors.business_description = 'Business description must be at least 20 characters';
    }

    if (formData.business_goals.length === 0) {
      errors.business_goals = 'Please select at least one business goal';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  }, [formData]);

  // Form Handlers
  const handleInputChange = (field: keyof BusinessAnalysisRequest, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear validation error when user starts typing
    if (validationErrors[field]) {
      setValidationErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const handleGoalToggle = (goal: string) => {
    const currentGoals = formData.business_goals;
    const updatedGoals = currentGoals.includes(goal)
      ? currentGoals.filter(g => g !== goal)
      : [...currentGoals, goal];

    handleInputChange('business_goals', updatedGoals);
  };

  const handleAddColor = () => {
    if (colorInput.trim() && !formData.existing_brand_colors?.includes(colorInput.trim())) {
      const updatedColors = [...(formData.existing_brand_colors || []), colorInput.trim()];
      handleInputChange('existing_brand_colors', updatedColors);
      setColorInput('');
    }
  };

  const handleRemoveColor = (color: string) => {
    const updatedColors = formData.existing_brand_colors?.filter(c => c !== color) || [];
    handleInputChange('existing_brand_colors', updatedColors);
  };

  const handleAddCompetitor = () => {
    if (competitorInput.trim() && !formData.competitors?.includes(competitorInput.trim())) {
      const updatedCompetitors = [...(formData.competitors || []), competitorInput.trim()];
      handleInputChange('competitors', updatedCompetitors);
      setCompetitorInput('');
    }
  };

  const handleRemoveCompetitor = (competitor: string) => {
    const updatedCompetitors = formData.competitors?.filter(c => c !== competitor) || [];
    handleInputChange('competitors', updatedCompetitors);
  };

  // Analysis Simulation (replace with actual API call)
  const performAnalysis = useCallback(async () => {
    if (!validateForm()) return;

    setIsAnalyzing(true);
    setAnalysisProgress(0);

    try {
      // Simulate analysis steps
      const steps = [
        { message: 'Analyzing business description...', duration: 1000 },
        { message: 'Classifying industry and market...', duration: 1500 },
        { message: 'Identifying target audience...', duration: 1200 },
        { message: 'Analyzing competitors...', duration: 800 },
        { message: 'Generating recommendations...', duration: 1000 }
      ];

      for (let i = 0; i < steps.length; i++) {
        const step = steps[i];
        setAnalysisStep(step.message);
        setAnalysisProgress(((i + 1) / steps.length) * 100);

        await new Promise(resolve => setTimeout(resolve, step.duration));
      }

      // Mock analysis result
      const mockResult: BusinessAnalysisResult = {
        industry_classification: {
          primary: formData.industry || 'technology',
          secondary: ['software', 'digital services'],
          confidence: 0.87
        },
        target_audience: {
          demographics: ['25-45 years', 'professionals', 'tech-savvy'],
          psychographics: ['efficiency-focused', 'growth-oriented', 'innovation-seeking'],
          confidence: 0.92
        },
        business_type: formData.business_goals.includes('Drive online sales') ? 'b2c' : 'b2b',
        content_requirements: [
          'Clear value proposition',
          'Feature comparisons',
          'Customer testimonials',
          'Pricing information',
          'Contact forms'
        ],
        design_preferences: {
          modern: 0.85,
          minimal: 0.70,
          professional: 0.80,
          colorful: 0.45
        },
        brand_personality: {
          traits: ['innovative', 'trustworthy', 'efficient'],
          tone: 'professional',
          confidence: 0.78
        }
      };

      setAnalysisResult(mockResult);
      onAnalysisComplete(mockResult);

    } catch (error) {
      console.error('Analysis failed:', error);
      // Handle error appropriately
    } finally {
      setIsAnalyzing(false);
      setAnalysisStep('');
      setAnalysisProgress(0);
    }
  }, [formData, validateForm, onAnalysisComplete]);

  // Render Analysis Results
  const renderAnalysisResults = () => {
    if (!analysisResult) return null;

    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2 text-green-600">
          <CheckCircle2 className="h-5 w-5" />
          <h3 className="text-lg font-semibold">Analysis Complete</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Industry Classification */}
          <Card className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="h-4 w-4" />
              <h4 className="font-medium">Industry Classification</h4>
            </div>
            <div className="space-y-2">
              <div>
                <span className="text-sm text-gray-600">Primary: </span>
                <Badge variant="default">{analysisResult.industry_classification.primary}</Badge>
              </div>
              <div>
                <span className="text-sm text-gray-600">Secondary: </span>
                <div className="flex gap-1 flex-wrap">
                  {analysisResult.industry_classification.secondary.map(sec => (
                    <Badge key={sec} variant="secondary" className="text-xs">{sec}</Badge>
                  ))}
                </div>
              </div>
              <div className="text-sm text-gray-600">
                Confidence: {Math.round(analysisResult.industry_classification.confidence * 100)}%
              </div>
            </div>
          </Card>

          {/* Target Audience */}
          <Card className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Target className="h-4 w-4" />
              <h4 className="font-medium">Target Audience</h4>
            </div>
            <div className="space-y-2">
              <div>
                <span className="text-sm text-gray-600">Demographics: </span>
                <div className="flex gap-1 flex-wrap">
                  {analysisResult.target_audience.demographics.slice(0, 3).map(demo => (
                    <Badge key={demo} variant="outline" className="text-xs">{demo}</Badge>
                  ))}
                </div>
              </div>
              <div>
                <span className="text-sm text-gray-600">Psychographics: </span>
                <div className="flex gap-1 flex-wrap">
                  {analysisResult.target_audience.psychographics.slice(0, 2).map(psycho => (
                    <Badge key={psycho} variant="outline" className="text-xs">{psycho}</Badge>
                  ))}
                </div>
              </div>
            </div>
          </Card>

          {/* Business Type & Brand Personality */}
          <Card className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Globe className="h-4 w-4" />
              <h4 className="font-medium">Business Profile</h4>
            </div>
            <div className="space-y-2">
              <div>
                <span className="text-sm text-gray-600">Type: </span>
                <Badge variant={analysisResult.business_type === 'b2b' ? 'default' : 'secondary'}>
                  {analysisResult.business_type.toUpperCase()}
                </Badge>
              </div>
              <div>
                <span className="text-sm text-gray-600">Brand Tone: </span>
                <Badge variant="outline">{analysisResult.brand_personality.tone}</Badge>
              </div>
              <div>
                <span className="text-sm text-gray-600">Traits: </span>
                <div className="flex gap-1 flex-wrap">
                  {analysisResult.brand_personality.traits.map(trait => (
                    <Badge key={trait} variant="secondary" className="text-xs">{trait}</Badge>
                  ))}
                </div>
              </div>
            </div>
          </Card>

          {/* Design Preferences */}
          <Card className="p-4">
            <div className="flex items-center gap-2 mb-2">
              <Palette className="h-4 w-4" />
              <h4 className="font-medium">Design Preferences</h4>
            </div>
            <div className="space-y-2">
              {Object.entries(analysisResult.design_preferences)
                .sort(([,a], [,b]) => b - a)
                .slice(0, 3)
                .map(([style, score]) => (
                  <div key={style} className="flex items-center justify-between">
                    <span className="text-sm capitalize">{style}</span>
                    <div className="flex items-center gap-2">
                      <Progress value={score * 100} className="w-16 h-2" />
                      <span className="text-xs text-gray-500">{Math.round(score * 100)}%</span>
                    </div>
                  </div>
                ))
              }
            </div>
          </Card>
        </div>
      </div>
    );
  };

  return (
    <div className={`space-y-6 ${className}`}>
      <div className="flex items-center gap-2">
        <Brain className="h-6 w-6 text-blue-600" />
        <h2 className="text-xl font-semibold">Business Context Analysis</h2>
      </div>

      {!analysisResult ? (
        <Card className="p-6">
          <form onSubmit={(e) => { e.preventDefault(); performAnalysis(); }} className="space-y-6">
            {/* Basic Information */}
            <div className="space-y-4">
              <h3 className="text-lg font-medium">Basic Information</h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="business_name">Business Name *</Label>
                  <Input
                    id="business_name"
                    value={formData.business_name}
                    onChange={(e) => handleInputChange('business_name', e.target.value)}
                    placeholder="Enter your business name"
                    className={validationErrors.business_name ? 'border-red-500' : ''}
                  />
                  {validationErrors.business_name && (
                    <p className="text-red-500 text-sm mt-1">{validationErrors.business_name}</p>
                  )}
                </div>

                <div>
                  <Label htmlFor="industry">Industry</Label>
                  <Select value={formData.industry} onValueChange={(value) => handleInputChange('industry', value)}>
                    <SelectTrigger>
