                          className="ml-1 hover:text-red-500"
                        >
                          ×
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Additional Information */}
            <div className="space-y-4">
              <h3 className="text-lg font-medium">Additional Information</h3>

              <div>
                <Label htmlFor="website_url">Current Website (optional)</Label>
                <Input
                  id="website_url"
                  type="url"
                  value={formData.website_url}
                  onChange={(e) => handleInputChange('website_url', e.target.value)}
                  placeholder="https://yourwebsite.com"
                />
              </div>

              <div>
                <Label>Key Competitors</Label>
                <p className="text-sm text-gray-600">Add competitor websites or company names for analysis</p>
                <div className="flex gap-2 mb-2">
                  <Input
                    value={competitorInput}
                    onChange={(e) => setCompetitorInput(e.target.value)}
                    placeholder="competitor.com or Company Name"
                    onKeyPress={(e) => e.key === 'Enter' && handleAddCompetitor()}
                  />
                  <Button type="button" onClick={handleAddCompetitor} size="sm">Add</Button>
                </div>
                {formData.competitors && formData.competitors.length > 0 && (
                  <div className="flex gap-2 flex-wrap">
                    {formData.competitors.map(competitor => (
                      <Badge key={competitor} variant="outline" className="gap-1">
                        {competitor}
                        <button
                          type="button"
                          onClick={() => handleRemoveCompetitor(competitor)}
                          className="ml-1 hover:text-red-500"
                        >
                          ×
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Submit Button */}
            <div className="flex justify-center pt-4">
              <Button
                type="submit"
                disabled={isAnalyzing || externalLoading}
                className="w-full md:w-auto min-w-48"
              >
                {isAnalyzing || externalLoading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Analyzing...
                  </>
                ) : (
                  <>
                    <Brain className="mr-2 h-4 w-4" />
                    Analyze Business Context
                  </>
                )}
              </Button>
            </div>

            {/* Progress Indicator */}
            {(isAnalyzing || externalLoading) && (
              <div className="space-y-2">
                <Progress value={analysisProgress} className="w-full" />
                <p className="text-sm text-center text-gray-600">{analysisStep}</p>
              </div>
            )}
          </form>
        </Card>
      ) : (
        renderAnalysisResults()
      )}
    </div>
  );
};

'use client';

import React, { useCallback, useEffect, useRef, useState, useMemo } from 'react';
import { useDrop } from 'react-dnd';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData, DragItem, DropCollectedProps, DropResult } from '@/types/builder';
import CanvasComponent from './CanvasComponent';
import { DropZone } from './DropZone';
import { GridOverlay } from './GridOverlay';
import { SelectionBox } from './SelectionBox';
import { cn } from '@/lib/utils';

interface CanvasProps {
  className?: string;
  onComponentSelect?: (componentId: string | null) => void;
}

// PERFORMANCE: Memoized CanvasComponent to prevent unnecessary re-renders
const MemoizedCanvasComponent = React.memo(CanvasComponent, (prevProps, nextProps) => {
  return (
    prevProps.component.id === nextProps.component.id &&
    prevProps.isSelected === nextProps.isSelected &&
    prevProps.zoom === nextProps.zoom &&
    prevProps.component.position.x === nextProps.component.position.x &&
    prevProps.component.position.y === nextProps.component.position.y &&
    prevProps.component.size.width === nextProps.component.size.width &&
    prevProps.component.size.height === nextProps.component.size.height &&
    JSON.stringify(prevProps.component.props) === JSON.stringify(nextProps.component.props)
  );
});

// PERFORMANCE: Memoized SelectionBox to prevent re-renders
const MemoizedSelectionBox = React.memo(SelectionBox, (prevProps, nextProps) => {
  return (
    prevProps.componentId === nextProps.componentId &&
    prevProps.zoom === nextProps.zoom
  );
});

// PERFORMANCE: Virtual viewport for large component counts
function useVirtualCanvas(components: ComponentData[], canvasSize: { width: number; height: number }) {
  const [viewport, setViewport] = useState({ x: 0, y: 0, width: 1200, height: 800 });

  // PERFORMANCE: Only render components within or near the viewport
  const visibleComponents = useMemo(() => {
    if (components.length <= 20) {
      // For small component counts, render all
      return components;
    }

    const buffer = 200; // Render components slightly outside viewport
    return components.filter(component => {
      const compRight = component.position.x + component.size.width;
      const compBottom = component.position.y + component.size.height;

      return (
        component.position.x < viewport.x + viewport.width + buffer &&
        compRight > viewport.x - buffer &&
        component.position.y < viewport.y + viewport.height + buffer &&
        compBottom > viewport.y - buffer
      );
    });
  }, [components, viewport]);

  return { visibleComponents, setViewport };
}

// PERFORMANCE: Throttled canvas size calculation
function useThrottledCanvasResize(components: ComponentData[], canvasSize: { width: number; height: number }, setCanvasSize: (size: { width: number; height: number }) => void) {
  const timeoutRef = useRef<NodeJS.Timeout>();

  useEffect(() => {
    if (components.length === 0) return;

    // PERFORMANCE: Throttle canvas resize calculations
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      const maxX = Math.max(...components.map(c => c.position.x + c.size.width));
      const maxY = Math.max(...components.map(c => c.position.y + c.size.height));

      const newSize = {
        width: Math.max(canvasSize.width, maxX + 100),
        height: Math.max(canvasSize.height, maxY + 100),
      };

      if (newSize.width !== canvasSize.width || newSize.height !== canvasSize.height) {
        setCanvasSize(newSize);
      }
    }, 100); // Throttle to 100ms

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [components, canvasSize, setCanvasSize]);
}

export const Canvas = React.memo(React.forwardRef<HTMLDivElement, CanvasProps>(function Canvas({ className, onComponentSelect }, ref) {
  const internalRef = useRef<HTMLDivElement>(null);
  const canvasRef = typeof ref === 'function' ? internalRef : (ref || internalRef);

  const setRef = useCallback((element: HTMLDivElement | null) => {
    if (internalRef.current) {
      internalRef.current = element;
    }
    if (typeof ref === 'function') {
      ref(element);
    } else if (ref) {
      ref.current = element;
    }
  }, [ref]);
  const [isDragging, setIsDragging] = useState(false);
  const [dragPosition, setDragPosition] = useState<{ x: number; y: number } | null>(null);

  const {
    components,
    selectedComponentId,
    canvasSize,
    zoom,
    gridEnabled,
    snapToGrid,
    viewport,
    responsiveSettings,
    addComponent,
    selectComponent,
    updateComponentPosition,
    getComponentById,
    setCanvasSize,
    getResponsiveCanvasSize,
  } = useBuilderStore();

  // Get responsive canvas size
  const responsiveCanvasSize = getResponsiveCanvasSize();

  // PERFORMANCE: Virtual canvas for large component counts
  const { visibleComponents } = useVirtualCanvas(components, responsiveCanvasSize);

  // PERFORMANCE: Throttled canvas resize
  useThrottledCanvasResize(components, canvasSize, setCanvasSize);

  // PERFORMANCE: Memoized drag handlers to prevent recreation
  const handleDrop = useCallback((item: DragItem, monitor: any): DropResult | undefined => {
    if (!monitor.didDrop()) {
      const offset = monitor.getClientOffset();
      const canvasRect = canvasRef.current?.getBoundingClientRect();

      if (offset && canvasRect) {
        const position = {
          x: (offset.x - canvasRect.left) / zoom,
          y: (offset.y - canvasRect.top) / zoom,
        };

        if (snapToGrid) {
          position.x = Math.round(position.x / 20) * 20;
          position.y = Math.round(position.y / 20) * 20;
        }

        // If it's a new component from the palette
        if (item.type === 'component') {
          const newComponent: ComponentData = {
            id: `${item.componentType}-${Date.now()}`,
            type: item.componentType,
            name: item.name,
            props: { ...item.defaultProps },
            position,
            size: { width: 200, height: 100 },
            isConnectedToWorkflow: false,
          };

          addComponent(newComponent);
        }
        // If it's an existing canvas component being moved
        else if (item.type === 'canvas-component') {
          updateComponentPosition(item.id, position);
        }

        setIsDragging(false);
        setDragPosition(null);

        return { 
          dropEffect: 'move', 
          position,
        };
      }
    }

    setIsDragging(false);
    setDragPosition(null);
    return undefined;
  }, [zoom, snapToGrid, addComponent, updateComponentPosition]);

  // PERFORMANCE: Optimized hover handler with throttling
  const hoverTimeoutRef = useRef<NodeJS.Timeout>();
  const handleHover = useCallback((item: DragItem, monitor: any) => {
    // Clear previous timeout
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current);
    }

    // Throttle hover updates to improve performance
    hoverTimeoutRef.current = setTimeout(() => {
      const dragState = monitor.getItem() !== null;
      if (dragState !== isDragging) {
        setIsDragging(dragState);
      }

      // Update drag position for preview
      if (dragState) {
        const offset = monitor.getClientOffset();
        const currentRef = typeof canvasRef === 'object' ? canvasRef.current : null;
        const canvasRect = currentRef?.getBoundingClientRect();

        if (offset && canvasRect) {
          const position = {
            x: (offset.x - canvasRect.left) / zoom,
            y: (offset.y - canvasRect.top) / zoom,
          };
          setDragPosition(position);
        }
      }
    }, 16); // Throttle to ~60fps
  }, [isDragging, zoom]);

  const [{ isOver, canDrop }, drop] = useDrop<DragItem, DropResult, DropCollectedProps>({
    accept: ['component', 'canvas-component'],
    drop: handleDrop,
    collect: (monitor) => ({
      isOver: monitor.isOver(),
      canDrop: monitor.canDrop(),
    }),
    hover: handleHover,
  });

  // PERFORMANCE: Memoized click handler
  const handleCanvasClick = useCallback((event: React.MouseEvent) => {
    const currentRef = typeof canvasRef === 'object' ? canvasRef.current : null;
    if (event.target === currentRef) {
      selectComponent(null);
      onComponentSelect?.(null);
    }
  }, [selectComponent, onComponentSelect, canvasRef]);

  // PERFORMANCE: Optimized keyboard handler with memoization
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (!selectedComponentId) return;

    const selectedComponent = getComponentById(selectedComponentId);
    if (!selectedComponent) return;

    // Prevent default for handled keys
    const handledKeys = ['Delete', 'Backspace', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'];
    if (handledKeys.includes(event.key) || (event.key === 'd' && (event.ctrlKey || event.metaKey))) {
      event.preventDefault();
    }

    const store = useBuilderStore.getState();

    switch (event.key) {
      case 'Delete':
      case 'Backspace':
        store.removeComponent(selectedComponentId);
        break;
      case 'ArrowUp':
        store.moveComponent(selectedComponentId, 'up');
        break;
      case 'ArrowDown':
        store.moveComponent(selectedComponentId, 'down');
        break;
      case 'ArrowLeft':
        store.moveComponent(selectedComponentId, 'left');
        break;
      case 'ArrowRight':
        store.moveComponent(selectedComponentId, 'right');
        break;
      case 'd':
        if (event.ctrlKey || event.metaKey) {
          store.duplicateComponent(selectedComponentId);
        }
        break;
    }
  }, [selectedComponentId, getComponentById]);

  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      // PERFORMANCE: Cleanup hover timeout
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current);
      }
    };
  }, [handleKeyDown]);

  drop(setRef);

  // PERFORMANCE: Memoized canvas stats
  const canvasStats = useMemo(() => ({
    total: components.length,
    visible: visibleComponents.length,
    zoom: Math.round(zoom * 100)
  }), [components.length, visibleComponents.length, zoom]);

  return (
    <div className={cn("relative overflow-auto bg-gray-50", className)}>
      {/* Canvas Container */}
      <div
        ref={setRef}
        className={cn(
          "relative bg-white border-2 border-dashed transition-colors duration-200",
          isOver && canDrop ? "border-blue-400 bg-blue-50/50" : "border-gray-300",
          isDragging && "border-blue-400"
        )}
        style={{
          width: responsiveCanvasSize.width * zoom,
          height: responsiveCanvasSize.height * zoom,
          minWidth: viewport.currentBreakpoint === 'desktop' ? '100%' : `${responsiveCanvasSize.width}px`,
          minHeight: viewport.currentBreakpoint === 'desktop' ? '100%' : `${responsiveCanvasSize.height}px`,
          maxWidth: viewport.currentBreakpoint !== 'desktop' ? `${responsiveCanvasSize.width * zoom}px` : 'none',
          maxHeight: viewport.currentBreakpoint !== 'desktop' ? `${responsiveCanvasSize.height * zoom}px` : 'none',
          transform: `scale(${zoom})`,
          transformOrigin: 'top left',
          margin: viewport.currentBreakpoint !== 'desktop' ? '20px auto' : '0',
          border: responsiveSettings.showBreakpointBorders ? '2px solid #3b82f6' : undefined,
          borderRadius: viewport.currentBreakpoint === 'mobile' ? '12px' : undefined,
        }}
        onClick={handleCanvasClick}
      >
        {/* Grid Overlay - PERFORMANCE: Only render when enabled */}
        {gridEnabled && <GridOverlay zoom={zoom} />}

        {/* Responsive Grid Overlay */}
        {responsiveSettings.showResponsiveGrid && (
          <div className="absolute inset-0 pointer-events-none">
            {/* Responsive grid lines */}
            <div className="grid grid-cols-12 h-full opacity-20">
              {Array.from({ length: 12 }).map((_, i) => (
                <div key={i} className="border-r border-blue-400" />
              ))}
            </div>
            {/* Breakpoint indicators */}
            <div className="absolute top-2 right-2 bg-blue-600 text-white text-xs px-2 py-1 rounded">
              {viewport.currentBreakpoint.toUpperCase()} - {responsiveCanvasSize.width}×{responsiveCanvasSize.height}
            </div>
          </div>
        )}

        {/* Drop Zones */}
        <DropZone
          id="main-canvas"
          accepts={['*']}
          className="absolute inset-0"
        />

        {/* Canvas Components - PERFORMANCE: Only render visible components */}
        {visibleComponents.map((component) => (
          <MemoizedCanvasComponent
            key={component.id}
            component={component}
            isSelected={selectedComponentId === component.id}
            zoom={zoom}
          />
        ))}

        {/* Selection Box - PERFORMANCE: Only render when component selected */}
        {selectedComponentId && (
          <MemoizedSelectionBox
            componentId={selectedComponentId}
            zoom={zoom}
          />
        )}

        {/* Drag Preview - PERFORMANCE: Only render during drag */}
        {isDragging && dragPosition && (
          <div 
            className="absolute pointer-events-none bg-blue-500/20 border-2 border-blue-500 border-dashed rounded-lg"
            style={{
              left: dragPosition.x,
              top: dragPosition.y,
              width: 200,
              height: 100,
              zIndex: 1000,
            }}
          />
        )}

        {/* Drop Indicator - PERFORMANCE: Only render when hovering */}
        {isOver && canDrop && (
          <div className="absolute inset-0 bg-blue-500/10 border-2 border-blue-500 border-dashed rounded-lg flex items-center justify-center pointer-events-none">
            <div className="bg-blue-500 text-white px-4 py-2 rounded-lg font-medium">
              Drop component here
            </div>
          </div>
        )}
      </div>

      {/* Canvas Info - PERFORMANCE: Memoized stats */}
      <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-2 rounded-lg text-sm text-gray-600 border">
        {canvasStats.visible}/{canvasStats.total} components • {canvasStats.zoom}% zoom
        {canvasStats.visible < canvasStats.total && (
          <div className="text-xs text-blue-600 mt-1">
            Virtualized view active
          </div>
        )}
      </div>
    </div>
  );
}));

'use client';

import React, { useRef, useState, useCallback, useMemo } from 'react';
import { useDrag, useDrop } from 'react-dnd';
import { getEmptyImage } from 'react-dnd-html5-backend';
import { ComponentData, DragItem, DragCollectedProps, DropCollectedProps } from '@/types/builder';
import { useBuilderStore } from '@/store/builderStore';
import { SimpleResizeHandles } from './SimpleResizeHandles';
import { EnhancedComponentRenderer } from './EnhancedComponentRenderer';
import { WorkflowConnector } from './WorkflowConnector';
import { ResponsiveComponentWrapper } from './ResponsiveComponentWrapper';
import { cn } from '@/lib/utils';
import { Zap, Settings2, Move } from 'lucide-react';

interface CanvasComponentProps {
  component: ComponentData;
  isSelected: boolean;
  zoom: number;
  isBuilderMode?: boolean;
}

// PERFORMANCE: Memoized EnhancedComponentRenderer to prevent unnecessary re-renders
const MemoizedComponentRenderer = React.memo(EnhancedComponentRenderer, (prevProps, nextProps) => {
  return (
    prevProps.component.id === nextProps.component.id &&
    prevProps.isSelected === nextProps.isSelected &&
    prevProps.isBuilderMode === nextProps.isBuilderMode &&
    JSON.stringify(prevProps.component.props) === JSON.stringify(nextProps.component.props) &&
    JSON.stringify(prevProps.component.style) === JSON.stringify(nextProps.component.style)
  );
});

// PERFORMANCE: Memoized WorkflowConnector
const MemoizedWorkflowConnector = React.memo(WorkflowConnector, (prevProps, nextProps) => {
  return (
    prevProps.componentId === nextProps.componentId &&
    prevProps.isConnected === nextProps.isConnected &&
    prevProps.workflowId === nextProps.workflowId
  );
});

// PERFORMANCE: Memoized SimpleResizeHandles
const MemoizedResizeHandles = React.memo(SimpleResizeHandles, (prevProps, nextProps) => {
  return (
    prevProps.componentId === nextProps.componentId &&
    prevProps.size.width === nextProps.size.width &&
    prevProps.size.height === nextProps.size.height &&
    prevProps.zoom === nextProps.zoom &&
    prevProps.isContainer === nextProps.isContainer
  );
});

export const CanvasComponent = React.memo(function CanvasComponent({ 
  component, 
  isSelected, 
  zoom, 
  isBuilderMode = true 
}: CanvasComponentProps) {
  const componentRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const {
    selectComponent,
    updateComponentSize,
    updateComponentProps,
    connectToWorkflow,
    disconnectFromWorkflow,
    setAIContext,
  } = useBuilderStore();

  // PERFORMANCE: Memoize drag item to prevent recreation
  const dragItem = useMemo((): DragItem => ({
    type: 'canvas-component',
    id: component.id,
    componentType: component.type,
    name: component.name,
    defaultProps: component.props,
    category: 'layout', // Default category for existing components
    preview: {
      thumbnail: '',
      description: component.name,
    },
  }), [component.id, component.type, component.name, component.props]);

  // PERFORMANCE: Memoized drag configuration
  const dragConfig = useMemo(() => ({
    type: 'canvas-component',
    item: dragItem,
    collect: (monitor: any) => ({
      isDragging: monitor.isDragging(),
      opacity: monitor.isDragging() ? 0.5 : 1,
    }),
    end: () => setIsDragging(false),
  }), [dragItem]);

  const [{ opacity }, drag, preview] = useDrag<DragItem, unknown, DragCollectedProps>(dragConfig);

  // PERFORMANCE: Memoized drop configuration
  const dropConfig = useMemo(() => ({
    accept: ['component', 'canvas-component'],
    hover: (draggedItem: DragItem) => {
      if (draggedItem.id === component.id) return;

      // Allow dropping on containers
      if (component.type === 'container' || component.type === 'section') {
        // Handle nested component logic here if needed
      }
    },
    collect: (monitor: any) => ({
      isOver: monitor.isOver(),
      canDrop: monitor.canDrop(),
    }),
  }), [component.id, component.type]);

  const [, drop] = useDrop<DragItem, unknown, DropCollectedProps>(dropConfig);

  // Use empty image for drag preview to avoid default browser drag image
  React.useEffect(() => {
    preview(getEmptyImage(), { captureDraggingState: true });
  }, [preview]);

  // PERFORMANCE: Memoized event handlers
  const handleClick = useCallback((event: React.MouseEvent) => {
    event.stopPropagation();
    if (!isDragging && !isResizing) {
      selectComponent(component.id);
    }
  }, [isDragging, isResizing, selectComponent, component.id]);

  const handleDoubleClick = useCallback((event: React.MouseEvent) => {
    event.stopPropagation();
    // Open component editor or AI customization
    setAIContext({
      componentId: component.id,
      currentProps: component.props,
      availableActions: ['modify', 'style', 'enhance', 'connect'],
      suggestedModifications: [],
    });
  }, [setAIContext, component.id, component.props]);

  const handleWorkflowConnect = useCallback((workflowId: string) => {
    connectToWorkflow(component.id, workflowId);
  }, [connectToWorkflow, component.id]);

  const handleWorkflowDisconnect = useCallback(() => {
    disconnectFromWorkflow(component.id);
  }, [disconnectFromWorkflow, component.id]);

  const handleResize = useCallback((newSize: { width: number; height: number }) => {
    updateComponentSize(component.id, newSize);
  }, [updateComponentSize, component.id]);

  const handlePropsUpdate = useCallback((newProps: Partial<ComponentData['props']>) => {
    updateComponentProps(component.id, {
      ...component.props,
      ...newProps,
    });
  }, [updateComponentProps, component.id, component.props]);

  const handleToggleSettings = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    setShowSettings(prev => !prev);
  }, []);

  const handleResizeStart = useCallback(() => setIsResizing(true), []);
  const handleResizeEnd = useCallback(() => setIsResizing(false), []);

  // PERFORMANCE: Memoized ref callback to prevent unnecessary re-renders
  const combinedRef = useCallback((node: HTMLDivElement | null) => {
    if (componentRef.current !== node) {
      // Only update if the node has actually changed
      Object.defineProperty(componentRef, 'current', {
        value: node,
        writable: true,
        configurable: true
      });
    }
    drag(node);
    drop(node);
  }, [drag, drop]);

  // PERFORMANCE: Memoize component style to prevent recalculation
  const componentStyle = useMemo(() => ({
    left: component.position.x,
    top: component.position.y,
    width: component.size.width,
    height: component.size.height,
    opacity,
    zIndex: isSelected ? 10 : 1,
    ...component.style,
  }), [
    component.position.x,
    component.position.y,
    component.size.width,
    component.size.height,
    opacity,
    isSelected,
    component.style
  ]);

  // PERFORMANCE: Memoize CSS classes
  const componentClasses = useMemo(() => cn(
    "absolute transition-all duration-200 group",
    // Clean selection indicator
    isSelected && "ring-2 ring-blue-500",
    // Dragging state
    isDragging && "z-50 opacity-75 cursor-grabbing",
    // Connected state with subtle indicator
    component.isConnectedToWorkflow && "ring-2 ring-emerald-400 ring-offset-1",
    // Hover state for better UX
    !isSelected && !isDragging && "hover:ring-1 hover:ring-blue-300 cursor-pointer"
  ), [isSelected, isDragging, component.isConnectedToWorkflow]);

  // PERFORMANCE: Memoize resize handles to prevent recreation
  const resizeHandles = useMemo(() => {
    if (!isSelected || isDragging) return null;

    return (
      <MemoizedResizeHandles
        componentId={component.id}
        size={component.size}
        onResize={handleResize}
        onResizeStart={handleResizeStart}
        onResizeEnd={handleResizeEnd}
        zoom={zoom}
        isContainer={component.type === 'container' || component.type === 'section'}
      />
    );
  }, [
    isSelected,
    isDragging,
    component.id,
    component.size,
    component.type,
    handleResize,
    handleResizeStart,
    handleResizeEnd,
    zoom
  ]);

  // PERFORMANCE: Memoize selection UI elements
  const selectionUI = useMemo(() => {
    if (!isSelected) return null;

    return (
      <>
        {/* Component Label */}
        <div className="absolute -top-6 left-0 bg-blue-500 text-white text-xs px-2 py-1 rounded shadow-sm">
          {component.name}
        </div>

        {/* Move Handle - Clean and simple */}
        <div 
          className="absolute -top-3 -left-3 bg-blue-500 text-white rounded-full p-1.5 shadow-sm hover:bg-blue-600 transition-colors cursor-move"
          title="Drag to move"
        >
          <Move className="w-3 h-3" />
        </div>

        {/* Settings Button - Only for advanced users */}
        <button
          className="absolute -top-3 -right-3 bg-gray-600 text-white rounded-full p-1.5 shadow-sm hover:bg-gray-700 transition-colors opacity-0 group-hover:opacity-100"
          onClick={handleToggleSettings}
          title="Component Settings"
        >
          <Settings2 className="w-3 h-3" />
        </button>
      </>
    );
  }, [isSelected, component.name, handleToggleSettings]);

  // PERFORMANCE: Memoize workflow UI elements
  const workflowUI = useMemo(() => {
    const isInteractiveComponent = ['form', 'button', 'contact'].includes(component.type);
    if (!isSelected || !isInteractiveComponent) return null;

    return (
      <>
        {/* Connection Indicator */}
        {component.isConnectedToWorkflow && (
          <div className="absolute -bottom-2 -right-2 bg-emerald-500 text-white rounded-full p-1 shadow-sm">
            <Zap className="w-3 h-3" />
          </div>
        )}

        {/* Workflow Connector - Only for interactive components */}
        <MemoizedWorkflowConnector
          componentId={component.id}
          isConnected={component.isConnectedToWorkflow || false}
          workflowId={component.workflowId}
          onConnect={handleWorkflowConnect}
          onDisconnect={handleWorkflowDisconnect}
        />
      </>
    );
  }, [
    isSelected,
    component.type,
    component.id,
    component.isConnectedToWorkflow,
    component.workflowId,
    handleWorkflowConnect,
    handleWorkflowDisconnect
  ]);

  return (
    <div
      ref={combinedRef}
      className={componentClasses}
      style={componentStyle}
      onClick={handleClick}
      onDoubleClick={handleDoubleClick}
    >
      {/* Component Content */}
      <div className="w-full h-full relative">
        <ResponsiveComponentWrapper component={component}>
          <MemoizedComponentRenderer
            component={component}
            isSelected={isSelected}
            isBuilderMode={isBuilderMode}
            onUpdateProps={handlePropsUpdate}
          />
        </ResponsiveComponentWrapper>

        {/* Selection UI */}
        {selectionUI}

        {/* Workflow UI */}
        {workflowUI}
      </div>

      {/* Resize Handles */}
      {resizeHandles}
    </div>
  );
});

// Helper to determine if we should use enhanced renderer
export const ComponentRenderer = React.memo(function ComponentRenderer({ 
  component, 
  isSelected, 
  isBuilderMode 
}: {
  component: ComponentData;
  isSelected: boolean;
  isBuilderMode: boolean;
}) {
  const { updateComponentProps } = useBuilderStore();

  const handlePropsUpdate = useCallback((newProps: Partial<ComponentData['props']>) => {
    updateComponentProps(component.id, {
      ...component.props,
      ...newProps,
    });
  }, [updateComponentProps, component.id, component.props]);

  return (
    <MemoizedComponentRenderer
      component={component}
      isSelected={isSelected}
      isBuilderMode={isBuilderMode}
      onUpdateProps={handlePropsUpdate}
    />
  );
});

export default CanvasComponent;

/**
 * CollaborativeBuilder Component
 * Enhanced builder with real-time collaboration features
 */

'use client';

import React, { useRef, useEffect, useState } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { CollaborationProvider } from '../collaboration/CollaborationProvider';
import { Canvas } from './Canvas';
import { ComponentPalette } from './ComponentPalette';
import { BuilderToolbar } from './BuilderToolbar';
import { ComponentEditorWithAI as ComponentEditor } from '../ComponentEditorWithAI';

interface CollaborativeBuilderProps {
  projectId: string;
  userId: string;
  userName: string;
  userEmail: string;
  authToken: string;
  className?: string;
}

export const CollaborativeBuilder: React.FC<CollaborativeBuilderProps> = ({
  projectId,
  userId,
  userName,
  userEmail,
  authToken,
  className = '',
}) => {
  const canvasRef = useRef<HTMLDivElement>(null);
  const [isComponentEditorOpen, setIsComponentEditorOpen] = useState(false);

  const { 
    selectedComponentId, 
    getSelectedComponent,
    selectComponent,
  } = useBuilderStore();

  const selectedComponent = getSelectedComponent();

  // Handle component selection
  const handleComponentSelect = (componentId: string | null) => {
    selectComponent(componentId);
    setIsComponentEditorOpen(!!componentId);
  };

  // Handle component editor close
  const handleComponentEditorClose = () => {
    setIsComponentEditorOpen(false);
    selectComponent(null);
  };

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Escape to deselect
      if (event.key === 'Escape') {
        handleComponentSelect(null);
      }

      // Delete selected component
      if (event.key === 'Delete' && selectedComponentId) {
        // TODO: Check if component is locked before deleting
        // This would be handled by the collaboration system
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [selectedComponentId]);

  return (
    <CollaborationProvider
      projectId={projectId}
      userId={userId}
      userName={userName}
      userEmail={userEmail}
      authToken={authToken}
      canvasRef={canvasRef}
      className={`h-screen flex flex-col ${className}`}
    >
      {/* Builder Toolbar */}
      <BuilderToolbar className="border-b border-gray-200" />

      {/* Main Builder Area */}
      <div className="flex-1 flex overflow-hidden">
        {/* Component Palette */}
        <div className="w-64 border-r border-gray-200 bg-gray-50">
          <ComponentPalette />
        </div>

        {/* Canvas Area */}
        <div className="flex-1 relative overflow-hidden">
          <Canvas 
            ref={canvasRef}
            onComponentSelect={handleComponentSelect}
            className="w-full h-full"
          />
        </div>

        {/* Component Editor Panel */}
        {isComponentEditorOpen && selectedComponent && (
          <div className="w-80 border-l border-gray-200 bg-white">
            <ComponentEditor
              componentId={selectedComponent.id}
              initialCode={`// Component: ${selectedComponent.name}\n// Type: ${selectedComponent.type}`}
              componentType="react"
              enableAI={true}
              onCodeChange={(code) => {
                // Updates will be synchronized automatically
                // through the collaboration system
              }}
            />
          </div>
        )}
      </div>
    </CollaborationProvider>
  );
};

// Enhanced Canvas with collaboration features
const EnhancedCanvas = React.forwardRef<HTMLDivElement, {
  onComponentSelect: (componentId: string | null) => void;
  className?: string;
}>(({ onComponentSelect, className }, ref) => {
  const { 
    components, 
    selectedComponentId,
    zoom,
    gridEnabled,
    updateComponentPosition,
    updateComponentSize,
  } = useBuilderStore();

  // Handle component interactions with collaboration awareness
  const handleComponentClick = (componentId: string, event: React.MouseEvent) => {
    event.stopPropagation();

    // TODO: Check if component is locked by another user
    // If locked, show tooltip or prevent selection

    onComponentSelect(componentId);
  };

  const handleCanvasClick = () => {
    onComponentSelect(null);
  };

  // Emit drag start events for collaboration locking
  const handleDragStart = (componentId: string) => {
    // Emit custom event for collaboration system
    const event = new CustomEvent('component-drag-start', {
      detail: { componentId }
    });
    document.dispatchEvent(event);
  };

  const handleResizeStart = (componentId: string) => {
    // Emit custom event for collaboration system  
    const event = new CustomEvent('component-resize-start', {
      detail: { componentId }
    });
    document.dispatchEvent(event);
  };

  return (
    <div
      ref={ref}
      className={`relative bg-white ${className}`}
      onClick={handleCanvasClick}
      style={{
        backgroundImage: gridEnabled ? 
          `radial-gradient(circle, #e5e7eb 1px, transparent 1px)` : 
          undefined,
        backgroundSize: gridEnabled ? 
          `${20 * zoom}px ${20 * zoom}px` : 
          undefined,
      }}
    >
      {/* Canvas Components */}
      {components.map((component) => (
        <div
          key={component.id}
          className={`absolute cursor-pointer transition-all duration-150 ${
            selectedComponentId === component.id 
              ? 'ring-2 ring-blue-500 ring-opacity-50' 
              : 'hover:ring-1 hover:ring-gray-300'
          }`}
          style={{
            left: component.position.x * zoom,
            top: component.position.y * zoom,
            width: component.size.width * zoom,
            height: component.size.height * zoom,
            transform: `scale(${zoom})`,
            transformOrigin: 'top left',
          }}
          onClick={(e) => handleComponentClick(component.id, e)}
        >
          {/* Component Content */}
          <div className="w-full h-full border border-gray-200 bg-white rounded shadow-sm">
            {/* Render component based on type */}
            {component.type === 'text' && (
              <div className="p-4 text-sm">
                {component.props.content || 'Text Component'}
              </div>
            )}
            {component.type === 'button' && (
              <button className="w-full h-full bg-blue-500 text-white rounded hover:bg-blue-600">
                {component.props.content || 'Button'}
              </button>
            )}
            {component.type === 'image' && (
              <div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-500">
                {component.props.imageUrl ? (
                  <img 
                    src={component.props.imageUrl} 
                    alt={component.props.imageAlt || 'Image'} 
                    className="w-full h-full object-cover rounded"
                  />
                ) : (
                  'Image'
                )}
              </div>
            )}
            {/* Add more component types as needed */}
          </div>

          {/* Component drag handles */}
          {selectedComponentId === component.id && (
            <div className="absolute inset-0 pointer-events-none">
              {/* Resize handles */}
              <div className="absolute -top-1 -left-1 w-3 h-3 bg-blue-500 border border-white rounded-full pointer-events-auto cursor-nw-resize"
                onMouseDown={() => handleResizeStart(component.id)} />
              <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-500 border border-white rounded-full pointer-events-auto cursor-ne-resize"
                onMouseDown={() => handleResizeStart(component.id)} />
              <div className="absolute -bottom-1 -left-1 w-3 h-3 bg-blue-500 border border-white rounded-full pointer-events-auto cursor-sw-resize"
                onMouseDown={() => handleResizeStart(component.id)} />
              <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-blue-500 border border-white rounded-full pointer-events-auto cursor-se-resize"
                onMouseDown={() => handleResizeStart(component.id)} />
            </div>
          )}
        </div>
      ))}
    </div>
  );
});

EnhancedCanvas.displayName = 'EnhancedCanvas';

