  navigation: Navigation,
  media: Image,
  interactive: MousePointer,
  'ai-powered': Zap,
};

interface DraggableComponentProps {
  component: DragItem;
}

function DraggableComponent({ component }: DraggableComponentProps) {
  const ref = useRef<HTMLDivElement>(null);

  const [{ isDragging }, drag] = useDrag<DragItem, unknown, DragCollectedProps>({
    type: 'component',
    item: component,
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  // Apply the drag ref
  drag(ref);

  return (
    <div
      ref={ref}
      className={cn(
        "flex items-center p-3 bg-white border border-gray-200 rounded-lg cursor-grab hover:border-blue-300 hover:shadow-sm transition-all duration-200",
        isDragging && "opacity-50 cursor-grabbing"
      )}
    >
      <div className="flex items-center space-x-3 flex-1">
        <div className="flex-shrink-0">
          <Grip className="w-4 h-4 text-gray-400" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-gray-900 truncate">
            {component.name}
          </p>
          <p className="text-xs text-gray-500 truncate">
            {component.preview.description}
          </p>
        </div>
      </div>
      {component.category === 'ai-powered' && (
        <Zap className="w-4 h-4 text-blue-500 flex-shrink-0" />
      )}
    </div>
  );
}

interface ComponentPaletteProps {
  className?: string;
}

export function ComponentPalette({ className }: ComponentPaletteProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedCategories, setExpandedCategories] = useState<Set<ComponentCategory>>(
    new Set(['layout', 'content', 'forms'])
  );

  const toggleCategory = (category: ComponentCategory) => {
    const newExpanded = new Set(expandedCategories);
    if (newExpanded.has(category)) {
      newExpanded.delete(category);
    } else {
      newExpanded.add(category);
    }
    setExpandedCategories(newExpanded);
  };

  const filteredComponents = Object.entries(componentLibrary).reduce(
    (acc, [category, components]) => {
      const filtered = components.filter(
        (component) =>
          component.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          component.preview.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filtered.length > 0) {
        acc[category as ComponentCategory] = filtered;
      }
      return acc;
    },
    {} as Record<ComponentCategory, DragItem[]>
  );

  return (
    <div className={cn("w-80 bg-gray-50 border-r border-gray-200 flex flex-col", className)}>
      {/* Header */}
      <div className="p-4 border-b border-gray-200 bg-white">
        <h3 className="text-lg font-semibold text-gray-900 mb-3">
          Components
        </h3>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search components..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Component Categories */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {Object.entries(filteredComponents).map(([category, components]) => {
          const categoryKey = category as ComponentCategory;
          const Icon = categoryIcons[categoryKey];
          const isExpanded = expandedCategories.has(categoryKey);

          return (
            <div key={category} className="space-y-2">
              {/* Category Header */}
              <button
                onClick={() => toggleCategory(categoryKey)}
                className="w-full flex items-center justify-between p-2 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors duration-200"
              >
                <div className="flex items-center space-x-2">
                  <Icon className="w-4 h-4 text-gray-600" />
                  <span className="text-sm font-medium text-gray-900 capitalize">
                    {category.replace('-', ' ')}
                  </span>
                  <span className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
                    {components.length}
                  </span>
                </div>
                {isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-gray-400" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-gray-400" />
                )}
              </button>

              {/* Category Components */}
              {isExpanded && (
                <div className="space-y-2 pl-2">
                  {components.map((component) => (
                    <DraggableComponent
                      key={component.id}
                      component={component}
                    />
                  ))}
                </div>
              )}
            </div>
          );
        })}

        {Object.keys(filteredComponents).length === 0 && (
          <div className="text-center py-8 text-gray-500">
            <Search className="w-8 h-8 mx-auto mb-2 text-gray-300" />
            <p className="text-sm">No components found</p>
            <p className="text-xs">Try adjusting your search terms</p>
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-4 border-t border-gray-200 bg-white">
        <div className="text-xs text-gray-500 text-center">
          Drag components to the canvas to start building
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { ComponentData } from '@/types/builder';
import { cn } from '@/lib/utils';

interface ComponentRendererProps {
  component: ComponentData;
  isSelected: boolean;
  isBuilderMode: boolean;
}

export function ComponentRenderer({ component, isSelected, isBuilderMode }: ComponentRendererProps) {
  const baseClasses = cn(
    "w-full h-full",
    isBuilderMode && "pointer-events-none select-none"
  );

  switch (component.type) {
    case 'container':
      return (
        <div
          className={cn(baseClasses, "border-2 border-dashed border-gray-300 flex items-center justify-center")}
          style={{
            padding: component.props.padding,
            backgroundColor: component.props.backgroundColor,
            borderRadius: component.props.borderRadius,
          }}
        >
          <div className="text-gray-500 text-sm">Container</div>
        </div>
      );

    case 'section':
      return (
        <div
          className={cn(baseClasses, "border border-gray-200")}
          style={{
            padding: component.props.padding,
            backgroundColor: component.props.backgroundColor,
          }}
        >
          <div className="text-gray-500 text-sm">Section</div>
        </div>
      );

    case 'heading':
      return React.createElement(
        `h${component.props.level}`,
        {
          className: cn(baseClasses, "font-bold"),
          style: {
            fontSize: component.props.fontSize,
            color: component.props.color,
            fontWeight: component.props.fontWeight,
          },
        },
        component.props.text
      );

    case 'paragraph':
      return (
        <p
          className={baseClasses}
          style={{
            fontSize: component.props.fontSize,
            lineHeight: component.props.lineHeight,
            color: component.props.color,
          }}
        >
          {component.props.text}
        </p>
      );

    case 'button':
      return (
        <button
          className={cn(
            baseClasses,
            "px-4 py-2 rounded-lg font-medium transition-colors duration-200",
            component.props.variant === 'primary' && "bg-blue-500 text-white hover:bg-blue-600",
            component.props.variant === 'secondary' && "bg-gray-200 text-gray-900 hover:bg-gray-300",
            component.props.size === 'small' && "px-3 py-1.5 text-sm",
            component.props.size === 'large' && "px-6 py-3 text-lg"
          )}
          style={{
            backgroundColor: component.props.backgroundColor,
            color: component.props.color,
          }}
        >
          {component.props.text}
        </button>
      );

    case 'input':
      return (
        <div className={baseClasses}>
          {component.props.label && (
            <label className="block text-sm font-medium text-gray-700 mb-1">
              {component.props.label}
              {component.props.required && <span className="text-red-500 ml-1">*</span>}
            </label>
          )}
          <input
            type={component.props.type}
            placeholder={component.props.placeholder}
            required={component.props.required}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      );

    case 'image':
      return (
        <div className={cn(baseClasses, "overflow-hidden rounded-lg")}>
          <img
            src={component.props.src}
            alt={component.props.alt}
            className="w-full h-full"
            style={{
              objectFit: component.props.objectFit,
            }}
          />
        </div>
      );

    case 'grid':
      return (
        <div
          className={cn(baseClasses, "grid border-2 border-dashed border-gray-300")}
          style={{
            gridTemplateColumns: `repeat(${component.props.columns}, 1fr)`,
            gap: component.props.gap,
          }}
        >
          {Array.from({ length: component.props.columns }).map((_, index) => (
            <div
              key={index}
              className="min-h-[60px] border border-gray-200 bg-gray-50 flex items-center justify-center"
            >
              <span className="text-gray-400 text-xs">Grid Item {index + 1}</span>
            </div>
          ))}
        </div>
      );

    case 'flexbox':
      return (
        <div
          className={cn(baseClasses, "flex border-2 border-dashed border-gray-300")}
          style={{
            flexDirection: component.props.direction,
            justifyContent: component.props.justify,
            alignItems: component.props.align,
            gap: component.props.gap,
          }}
        >
          <div className="min-w-[80px] min-h-[40px] bg-gray-100 border border-gray-200 flex items-center justify-center">
            <span className="text-gray-400 text-xs">Flex 1</span>
          </div>
          <div className="min-w-[80px] min-h-[40px] bg-gray-100 border border-gray-200 flex items-center justify-center">
            <span className="text-gray-400 text-xs">Flex 2</span>
          </div>
        </div>
      );

    case 'list':
      const ListTag = component.props.type === 'ordered' ? 'ol' : 'ul';
      return (
        <ListTag className={cn(baseClasses, "space-y-1 pl-6")}>
          {component.props.items.map((item: string, index: number) => (
            <li key={index} className="text-gray-700">
              {item}
            </li>
          ))}
        </ListTag>
      );

    case 'navbar':
      return (
        <nav className={cn(baseClasses, "flex items-center justify-between px-6 py-4 bg-white border-b border-gray-200")}>
          <div className="font-bold text-lg">{component.props.logo}</div>
          <div className="flex space-x-6">
            {component.props.links.map((link: any, index: number) => (
              <a
                key={index}
                href={link.href}
                className="text-gray-700 hover:text-blue-600 transition-colors duration-200"
              >
                {link.text}
              </a>
            ))}
          </div>
        </nav>
      );

    case 'ai-chatbot':
      return (
        <div className={cn(baseClasses, "bg-blue-500 text-white rounded-lg p-4 flex items-center justify-center")}>
          <div className="text-center">
            <div className="text-sm font-medium mb-1">AI Chatbot</div>
            <div className="text-xs opacity-80">{component.props.greeting}</div>
          </div>
        </div>
      );

    case 'ai-form':
      return (
        <div className={cn(baseClasses, "bg-gradient-to-br from-purple-50 to-blue-50 border-2 border-purple-200 rounded-lg p-4")}>
          <div className="text-center">
            <div className="text-sm font-medium text-purple-800 mb-1">
              {component.props.title}
            </div>
            <div className="text-xs text-purple-600">
              {component.props.description}
            </div>
          </div>
        </div>
      );

    default:
      return (
        <div className={cn(baseClasses, "border-2 border-dashed border-red-300 bg-red-50 flex items-center justify-center")}>
          <div className="text-red-500 text-sm">
            Unknown component: {component.type}
          </div>
        </div>
      );
  }
}

'use client';

import React from 'react';
import { ComponentData } from '@/types/builder';
import { WorkflowConnector } from './WorkflowConnector';
import { cn } from '@/lib/utils';

interface ComponentTypeHandlerProps {
  component: ComponentData;
  isSelected: boolean;
  children: React.ReactNode;
  onWorkflowConnect: (workflowId: string) => void;
  onWorkflowDisconnect: () => void;
}

// Define which component types can connect to workflows
const WORKFLOW_COMPATIBLE_TYPES = [
  'form',
  'contact-form', 
  'button',
  'cta-button',
  'newsletter-signup',
  'booking-form',
  'survey',
  'quiz',
  'calculator',
  'chat-widget'
] as const;

type WorkflowCompatibleType = typeof WORKFLOW_COMPATIBLE_TYPES[number];

function isWorkflowCompatible(type: string): type is WorkflowCompatibleType {
  return WORKFLOW_COMPATIBLE_TYPES.includes(type as WorkflowCompatibleType);
}

export function ComponentTypeHandler({
  component,
  isSelected,
  children,
  onWorkflowConnect,
  onWorkflowDisconnect,
}: ComponentTypeHandlerProps) {
  const canConnectToWorkflow = isWorkflowCompatible(component.type);
  const isConnected = component.isConnectedToWorkflow || false;

  return (
    <div className="relative">
      {children}

      {/* Only show workflow features for compatible component types */}
      {canConnectToWorkflow && isSelected && (
        <>
          {/* Connection Status Indicator */}
          {isConnected && (
            <div 
              className={cn(
                "absolute -bottom-2 -right-2 w-5 h-5 rounded-full",
                "bg-emerald-500 text-white flex items-center justify-center",
                "shadow-sm animate-pulse"
              )}
              title="Connected to workflow"
            >
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M11.3 1.046A1 1 0 0112 2v5h4a1 1 0 01.82 1.573l-7 10A1 1 0 018 18v-5H4a1 1 0 01-.82-1.573l7-10a1 1 0 011.12-.38z" clipRule="evenodd" />
              </svg>
            </div>
          )}

          {/* Workflow Connector */}
          <WorkflowConnector
            componentId={component.id}
            isConnected={isConnected}
            workflowId={component.workflowId}
            onConnect={onWorkflowConnect}
            onDisconnect={onWorkflowDisconnect}
          />
        </>
      )}

      {/* Component Type Badge for Development/Debug */}
      {process.env.NODE_ENV === 'development' && isSelected && (
        <div className="absolute -top-4 right-0 bg-gray-700 text-white text-xs px-2 py-1 rounded-full">
          {component.type}
          {canConnectToWorkflow && (
            <span className="ml-1 text-emerald-300">🔗</span>
          )}
        </div>
      )}
    </div>
  );
}

// Helper component for showing workflow suggestions
export function WorkflowSuggestions({ componentType }: { componentType: string }) {
  const suggestions = getWorkflowSuggestions(componentType);

  if (!suggestions.length) return null;

  return (
    <div className="mt-3 p-3 bg-blue-50 border border-blue-200 rounded-lg">
      <div className="text-sm font-medium text-blue-800 mb-2">
        💡 Suggested Workflows
      </div>
      <div className="space-y-2">
        {suggestions.map((suggestion, index) => (
          <div 
            key={index}
            className="flex items-start space-x-2 text-xs text-blue-700"
          >
            <span className="flex-shrink-0 w-1 h-1 bg-blue-400 rounded-full mt-1.5" />
            <span>{suggestion}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

