            </div>
          </div>
        </div>

        {/* Description */}
        <p className={`text-gray-600 mb-3 ${
          viewMode === 'list' ? 'text-sm line-clamp-1' : 'text-sm line-clamp-2'
        }`}>
          {template.description}
