import type { WorkflowStatusEvent } from '@/hooks/useWorkflowStatus';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface ErrorLog {
  timestamp: string;
  level: 'ERROR' | 'WARN' | 'INFO' | 'DEBUG';
  message: string;
  stack?: string;
  context?: Record<string, any>;
}

export interface ErrorMetrics {
  execution_time_ms: number;
  memory_usage: string;
  cpu_usage: string;
  retry_count?: number;
  last_success?: string;
  error_frequency?: number;
}

export interface SLAViolationInfo {
  id: string;
  violation_type: string;
  threshold_value: number;
  actual_value: number;
  current_level: 1 | 2 | 3;
  created_at: string;
}

export interface ErrorContext {
  workflow_id: number;
  execution_id?: number;
  workflow_name?: string;
  node_type?: string;
  input_data?: Record<string, any>;
  configuration?: Record<string, any>;
  previous_nodes?: string[];
  expected_outputs?: string[];
}

export interface ErrorDetailsModalProps {
  /** Whether the modal is open */
  isOpen: boolean;
  /** Close handler */
  onClose: () => void;
  /** Failed workflow node data */
  node: WorkflowNodeData;
  /** Additional error context */
  errorContext?: ErrorContext;
  /** Error logs */
  errorLogs?: ErrorLog[];
  /** Performance metrics */
  metrics?: ErrorMetrics;
  /** Related SLA violation */
  slaViolation?: SLAViolationInfo;
  /** Restart node handler */
  onRestartNode?: (nodeId: string) => void;
  /** Skip node handler */
  onSkipNode?: (nodeId: string) => void;
  /** Debug node handler */
  onDebugNode?: (nodeId: string) => void;
  /** Export error details handler */
  onExportError?: (nodeId: string, format: 'json' | 'pdf' | 'csv') => void;
  /** Custom CSS classes */
  className?: string;
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

function formatTimestamp(timestamp: string | Date): string {
  const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
  return date.toLocaleString();
}

function formatDuration(milliseconds: number): string {
  if (milliseconds < 1000) {
    return `${milliseconds}ms`;
  } else if (milliseconds < 60000) {
    return `${(milliseconds / 1000).toFixed(1)}s`;
  } else {
    const minutes = Math.floor(milliseconds / 60000);
    const seconds = ((milliseconds % 60000) / 1000).toFixed(0);
    return `${minutes}:${seconds.padStart(2, '0')}`;
  }
}

function getErrorSeverityColor(level: string): string {
  switch (level.toLowerCase()) {
    case 'error':
      return 'bg-red-100 text-red-800 border-red-200';
    case 'warn':
      return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    case 'info':
      return 'bg-blue-100 text-blue-800 border-blue-200';
    case 'debug':
      return 'bg-gray-100 text-gray-800 border-gray-200';
    default:
      return 'bg-gray-100 text-gray-800 border-gray-200';
  }
}

function getSLALevelColor(level: 1 | 2 | 3): string {
  switch (level) {
    case 1:
      return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    case 2:
      return 'bg-orange-100 text-orange-800 border-orange-200';
    case 3:
      return 'bg-red-100 text-red-800 border-red-200';
    default:
      return 'bg-gray-100 text-gray-800 border-gray-200';
  }
}

// ============================================================================
// SUB-COMPONENTS
// ============================================================================

