// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const ErrorDetailsModal = React.memo<ErrorDetailsModalProps>(({
  isOpen,
  onClose,
  node,
  errorContext,
  errorLogs,
  metrics,
  slaViolation,
  onRestartNode,
  onSkipNode,
  onDebugNode,
  onExportError,
  className
}) => {
  const [activeTab, setActiveTab] = useState<string>('summary');
  const [isActionLoading, setIsActionLoading] = useState<string | null>(null);

  // ============================================================================
  // ACTION HANDLERS
  // ============================================================================

  const handleAction = useCallback(async (action: string, handler?: (nodeId: string) => void) => {
    if (!handler) return;

    setIsActionLoading(action);
    try {
      await handler(node.id);
    } catch (error) {
      console.error(`Failed to ${action} node:`, error);
    } finally {
      setIsActionLoading(null);
    }
  }, [node.id]);

  const handleCopyError = useCallback(() => {
    const errorDetails = {
      nodeId: node.id,
      errorMessage: node.errorMessage,
      timestamp: node.lastUpdated,
      executionTime: node.executionTime,
      context: errorContext
    };

    navigator.clipboard.writeText(JSON.stringify(errorDetails, null, 2));
  }, [node, errorContext]);

  const handleExport = useCallback((format: 'json' | 'pdf' | 'csv') => {
    onExportError?.(node.id, format);
  }, [node.id, onExportError]);

  // ============================================================================
  // COMPUTED VALUES
  // ============================================================================

  const hasLogs = useMemo(() => errorLogs && errorLogs.length > 0, [errorLogs]);
  const hasMetrics = useMemo(() => Boolean(metrics), [metrics]);
  const hasConfiguration = useMemo(() => Boolean(errorContext?.configuration), [errorContext]);

  // ============================================================================
  // RENDER
  // ============================================================================

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className={cn('max-w-4xl max-h-[90vh] overflow-hidden', className)}>
        <DialogHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-red-100 rounded-lg">
                <Bug className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <DialogTitle>Node Execution Error</DialogTitle>
                <DialogDescription>
                  Detailed error information for node {node.id}
                </DialogDescription>
              </div>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              className="shrink-0"
            >
              <X className="w-4 h-4" />
            </Button>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-hidden">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="h-full flex flex-col">
            <TabsList className="grid w-full grid-cols-4">
              <TabsTrigger value="summary">Summary</TabsTrigger>
              <TabsTrigger value="logs" disabled={!hasLogs}>
                Logs {hasLogs && `(${errorLogs?.length})`}
              </TabsTrigger>
              <TabsTrigger value="metrics" disabled={!hasMetrics}>
                Metrics
              </TabsTrigger>
              <TabsTrigger value="config" disabled={!hasConfiguration}>
                Configuration
              </TabsTrigger>
            </TabsList>

            <div className="flex-1 overflow-hidden mt-4">
              <TabsContent value="summary" className="h-full overflow-auto">
                <ErrorSummary
                  node={node}
                  errorContext={errorContext}
                  slaViolation={slaViolation}
                />
              </TabsContent>

              <TabsContent value="logs" className="h-full overflow-auto">
                <ErrorLogs logs={errorLogs} />
              </TabsContent>

              <TabsContent value="metrics" className="h-full overflow-auto">
                <PerformanceMetrics metrics={metrics} />
              </TabsContent>

              <TabsContent value="config" className="h-full overflow-auto">
                <NodeConfiguration errorContext={errorContext} />
              </TabsContent>
            </div>
          </Tabs>
        </div>

        <Separator />

        <DialogFooter className="flex-col sm:flex-row gap-2">
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleCopyError}
              className="flex items-center gap-2"
            >
              <Copy className="w-4 h-4" />
              Copy Error
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={() => handleExport('json')}
              className="flex items-center gap-2"
            >
              <Download className="w-4 h-4" />
              Export
            </Button>
          </div>

          <div className="flex gap-2">
            {onDebugNode && (
              <Button
                variant="outline"
                onClick={() => handleAction('debug', onDebugNode)}
                disabled={isActionLoading === 'debug'}
                className="flex items-center gap-2"
              >
                {isActionLoading === 'debug' ? (
                  <RefreshCw className="w-4 h-4 animate-spin" />
                ) : (
                  <ExternalLink className="w-4 h-4" />
                )}
                Debug
              </Button>
            )}

            {onSkipNode && (
              <Button
                variant="outline"
                onClick={() => handleAction('skip', onSkipNode)}
                disabled={isActionLoading === 'skip'}
                className="flex items-center gap-2"
              >
                {isActionLoading === 'skip' ? (
                  <RefreshCw className="w-4 h-4 animate-spin" />
                ) : (
                  <Clock className="w-4 h-4" />
                )}
                Skip
              </Button>
            )}

            {onRestartNode && (
              <Button
                onClick={() => handleAction('restart', onRestartNode)}
                disabled={isActionLoading === 'restart'}
                className="flex items-center gap-2"
              >
                {isActionLoading === 'restart' ? (
                  <RefreshCw className="w-4 h-4 animate-spin" />
                ) : (
                  <RefreshCw className="w-4 h-4" />
                )}
                Restart Node
              </Button>
            )}
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
});

ErrorDetailsModal.displayName = 'ErrorDetailsModal';

// ============================================================================
// EXPORTS
// ============================================================================

export default ErrorDetailsModal;

export type {
  ErrorLog,
  ErrorMetrics,
  SLAViolationInfo,
  ErrorContext,
  ErrorDetailsModalProps
};

/**
 * ExecutionTimeline Component
 * 
 * Visual timeline showing step-by-step workflow execution progress
 * Part of Story 3.1: Visual Workflow Debugging - Integration Component
 * 
 * Features:
 * - Real-time execution progress visualization
 * - Performance metrics integration
 * - Interactive timeline with drill-down capability
 * - Export functionality for execution data
 * - Integration with SLA monitoring
 * 
 * @author Integration Coordinator - Story 3.1 Implementation
 */

'use client';

import React, { useMemo, useCallback, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import { Progress } from '@/components/ui/progress';
import {
  Play,
  Pause,
  CheckCircle,
  XCircle,
  Clock,
  Activity,
  Download,
  Filter,
  ZoomIn,
  TrendingUp,
  AlertTriangle
} from 'lucide-react';
import { cn } from '@/lib/utils';
import type { WorkflowNodeData, WorkflowNodeStatus } from './WorkflowStatusOverlay';
import type { WorkflowStatusEvent } from '@/hooks/useWorkflowStatus';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface ExecutionStep {
  id: string;
  node_id: string;
  node_name?: string;
  node_type?: string;
  status: WorkflowNodeStatus;
  started_at?: string;
  finished_at?: string;
  execution_time_ms?: number;
  input_data?: Record<string, any>;
  output_data?: Record<string, any>;
  error_message?: string;
  retry_count?: number;
  parent_step?: string;
  child_steps?: string[];
  performance_metrics?: {
    cpu_usage?: number;
    memory_usage?: number;
    network_io?: number;
    disk_io?: number;
  };
}

export interface ExecutionTimelineData {
  execution_id: number;
  workflow_id: number;
  workflow_name?: string;
  status: 'pending' | 'running' | 'completed' | 'failed' | 'paused';
  started_at: string;
  finished_at?: string;
  total_duration_ms?: number;
  total_steps: number;
  completed_steps: number;
  failed_steps: number;
  success_rate: number;
  steps: ExecutionStep[];
  sla_violations?: Array<{
    id: string;
    violation_type: string;
    threshold_value: number;
    actual_value: number;
    current_level: 1 | 2 | 3;
  }>;
}

export interface ExecutionTimelineProps {
  /** Timeline execution data */
  executionData: ExecutionTimelineData | null;
  /** Whether timeline is loading */
  isLoading?: boolean;
  /** Selected step for detailed view */
  selectedStepId?: string;
  /** Step selection handler */
  onStepSelect?: (stepId: string) => void;
  /** Step retry handler */
  onStepRetry?: (stepId: string) => void;
  /** Export handler */
  onExport?: (format: 'json' | 'csv' | 'pdf') => void;
  /** Real-time updates enabled */
  realTimeUpdates?: boolean;
  /** Show performance metrics */
  showMetrics?: boolean;
  /** Custom CSS classes */
  className?: string;
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

function formatTimestamp(timestamp: string | Date): string {
  const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
  return date.toLocaleString();
}

function formatDuration(milliseconds: number): string {
  if (milliseconds < 1000) {
    return `${milliseconds}ms`;
  } else if (milliseconds < 60000) {
    return `${(milliseconds / 1000).toFixed(1)}s`;
  } else {
    const minutes = Math.floor(milliseconds / 60000);
    const seconds = ((milliseconds % 60000) / 1000).toFixed(0);
    return `${minutes}:${seconds.padStart(2, '0')}`;
  }
}

function getStatusColor(status: WorkflowNodeStatus): string {
  switch (status) {
    case 'pending':
      return 'text-yellow-600 bg-yellow-100 border-yellow-200';
    case 'running':
      return 'text-blue-600 bg-blue-100 border-blue-200';
    case 'success':
      return 'text-green-600 bg-green-100 border-green-200';
    case 'failed':
      return 'text-red-600 bg-red-100 border-red-200';
    case 'paused':
      return 'text-gray-600 bg-gray-100 border-gray-200';
    default:
      return 'text-gray-600 bg-gray-100 border-gray-200';
  }
}

function getStatusIcon(status: WorkflowNodeStatus, size = 'w-4 h-4') {
  const iconClass = cn(size);

  switch (status) {
    case 'pending':
      return <Clock className={cn(iconClass, 'text-yellow-600')} />;
    case 'running':
      return <Play className={cn(iconClass, 'text-blue-600')} />;
    case 'success':
      return <CheckCircle className={cn(iconClass, 'text-green-600')} />;
    case 'failed':
      return <XCircle className={cn(iconClass, 'text-red-600')} />;
    case 'paused':
      return <Pause className={cn(iconClass, 'text-gray-600')} />;
    default:
      return <Clock className={cn(iconClass, 'text-gray-600')} />;
  }
}

