/**
 * Magic Connector Component
 * 
 * The heart of the Magic Moment - analyzes components and suggests relevant workflows
 * Provides one-click workflow connection with AI-powered intelligence
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { 
  Zap, 
  Wand2, 
  ArrowRight, 
  CheckCircle2, 
  Sparkles, 
  Brain, 
  TrendingUp,
  Users,
  Target,
  Lightbulb,
  RefreshCw,
  X,
  Settings,
  ExternalLink,
  Star
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { componentAnalyzer, ComponentAnalysis, WorkflowSuggestion } from '@/lib/ai/component-analyzer';

interface MagicConnectorProps {
  component: any;
  onWorkflowConnect: (workflowId: string, component: any) => void;
  onClose?: () => void;
  className?: string;
  autoShow?: boolean;
}

export const MagicConnector: React.FC<MagicConnectorProps> = ({
  component,
  onWorkflowConnect,
  onClose,
  className = '',
  autoShow = true
}) => {
  const [analysis, setAnalysis] = useState<ComponentAnalysis | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [selectedSuggestion, setSelectedSuggestion] = useState<WorkflowSuggestion | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [showDetails, setShowDetails] = useState(false);
  const [magicMomentTriggered, setMagicMomentTriggered] = useState(false);

  // Analyze component when it changes
  useEffect(() => {
    if (component && autoShow) {
      analyzeComponent();
    }
  }, [component, autoShow]);

  const analyzeComponent = useCallback(async () => {
    if (!component) return;

    setIsAnalyzing(true);
    try {
      // Add timeout and fallback for analysis
      const analysisPromise = componentAnalyzer.analyzeComponent(component);
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error('Analysis timeout')), 5000)
      );

      const result = await Promise.race([analysisPromise, timeoutPromise]);

      setAnalysis(result);

      // Auto-select the highest confidence suggestion
      if (result.suggestedWorkflows.length > 0) {
        setSelectedSuggestion(result.suggestedWorkflows[0]);
      }

      // Trigger magic moment animation for high-confidence suggestions
      if (result.confidence > 0.8 && result.suggestedWorkflows.length > 0) {
        setMagicMomentTriggered(true);
        setTimeout(() => setMagicMomentTriggered(false), 2000);
      }
    } catch (error) {
      console.error('Error analyzing component:', error);

      // Provide fallback analysis for timeout or API errors
      setAnalysis({
        confidence: 0.5,
        semanticPurpose: 'generic_component',
        workflowTriggers: [],
        suggestedWorkflows: [],
        businessContext: {
          industry: 'general',
          targetAudience: 'all_users',
          businessGoals: ['engagement']
        }
      });

    } finally {
      setIsAnalyzing(false);
    }
  }, [component]);

  const handleConnectWorkflow = useCallback(async (suggestion: WorkflowSuggestion) => {
    if (!suggestion || !component) return;

    setIsConnecting(true);
    try {
      await onWorkflowConnect(suggestion.workflowId, component);

      // Success animation
      setTimeout(() => {
        setIsConnecting(false);
        if (onClose) onClose();
      }, 1500);
    } catch (error) {
      console.error('Error connecting workflow:', error);
      setIsConnecting(false);
    }
  }, [component, onWorkflowConnect, onClose]);

  const renderConfidenceIndicator = (confidence: number) => {
    const percentage = Math.round(confidence * 100);
    const color = confidence > 0.8 ? 'text-green-600' : 
                  confidence > 0.6 ? 'text-yellow-600' : 'text-gray-600';

    return (
      <div className="flex items-center gap-2">
        <Brain className={`h-4 w-4 ${color}`} />
        <span className={`text-sm font-medium ${color}`}>
          {percentage}% confidence
        </span>
        <Progress value={percentage} className="w-16 h-2" />
      </div>
    );
  };

  const renderWorkflowSuggestion = (suggestion: WorkflowSuggestion, index: number) => {
    const isSelected = selectedSuggestion?.workflowId === suggestion.workflowId;
    const relevancePercentage = Math.round(suggestion.relevanceScore * 100);

    return (
      <div
        key={suggestion.workflowId}
        className={cn(
          "border rounded-lg p-4 cursor-pointer transition-all duration-200",
          isSelected 
            ? "border-blue-500 bg-blue-50 shadow-md" 
            : "border-gray-200 hover:border-blue-300 hover:bg-gray-50"
        )}
        onClick={() => setSelectedSuggestion(suggestion)}
      >
        <div className="flex items-start justify-between mb-3">
          <div className="flex items-center gap-2">
            <div className={`p-2 rounded-lg ${
              suggestion.category === 'marketing' ? 'bg-green-100 text-green-600' :
              suggestion.category === 'sales' ? 'bg-blue-100 text-blue-600' :
              suggestion.category === 'support' ? 'bg-purple-100 text-purple-600' :
              suggestion.category === 'ecommerce' ? 'bg-orange-100 text-orange-600' :
              'bg-gray-100 text-gray-600'
            }`}>
              {suggestion.category === 'marketing' && <TrendingUp className="h-4 w-4" />}
              {suggestion.category === 'sales' && <Target className="h-4 w-4" />}
              {suggestion.category === 'support' && <Users className="h-4 w-4" />}
              {suggestion.category === 'ecommerce' && <Sparkles className="h-4 w-4" />}
              {suggestion.category === 'automation' && <Zap className="h-4 w-4" />}
            </div>
            <div>
              <h4 className="font-semibold text-gray-900">{suggestion.workflowName}</h4>
              <p className="text-sm text-gray-600 mt-1">{suggestion.description}</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Badge variant={suggestion.autoConnectable ? "default" : "secondary"} className="text-xs">
              {relevancePercentage}% match
            </Badge>
            {suggestion.autoConnectable && (
              <div className="flex items-center gap-1 text-green-600">
                <Sparkles className="h-3 w-3" />
                <span className="text-xs font-medium">Auto-connect</span>
              </div>
            )}
          </div>
        </div>

        {isSelected && (
          <div className="space-y-3 border-t border-gray-200 pt-3">
            {/* Benefits */}
            <div>
              <h5 className="text-sm font-medium text-gray-900 mb-2">Key Benefits:</h5>
              <div className="grid grid-cols-2 gap-2">
                {suggestion.benefits.map((benefit, idx) => (
                  <div key={idx} className="flex items-center gap-2 text-sm text-gray-600">
                    <CheckCircle2 className="h-3 w-3 text-green-500" />
                    <span>{benefit}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Required Fields */}
            {suggestion.requiredFields.length > 0 && (
              <div>
                <h5 className="text-sm font-medium text-gray-900 mb-2">Required Fields:</h5>
                <div className="flex flex-wrap gap-1">
                  {suggestion.requiredFields.map((field, idx) => (
                    <Badge key={idx} variant="outline" className="text-xs">
                      {field}
                    </Badge>
                  ))}
                </div>
              </div>
            )}

            {/* Action Buttons */}
            <div className="flex items-center gap-2 pt-2">
              <Button
                onClick={(e) => {
                  e.stopPropagation();
                  handleConnectWorkflow(suggestion);
                }}
                disabled={isConnecting}
                className="flex-1"
                size="sm"
              >
                {isConnecting ? (
                  <>
                    <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                    Connecting...
                  </>
                ) : (
                  <>
                    <Wand2 className="h-4 w-4 mr-2" />
                    Connect Workflow
                  </>
                )}
              </Button>

              <Button
                variant="outline"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  setShowDetails(true);
                }}
              >
                <ExternalLink className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}
      </div>
    );
  };

  if (!component || !autoShow) return null;

  return (
    <div className={cn("fixed inset-0 bg-black/50 flex items-center justify-center z-50", className)}>
      <Card className={cn(
        "w-full max-w-2xl mx-4 transition-all duration-300",
        magicMomentTriggered && "animate-pulse border-blue-500 shadow-2xl"
      )}>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className={cn(
                "p-3 rounded-lg transition-all duration-300",
                magicMomentTriggered 
                  ? "bg-gradient-to-r from-blue-500 to-purple-600 text-white" 
                  : "bg-blue-100 text-blue-600"
              )}>
                <Wand2 className={cn(
                  "h-6 w-6 transition-all duration-300",
                  magicMomentTriggered && "animate-bounce"
                )} />
              </div>
              <div>
                <CardTitle className="flex items-center gap-2">
                  Magic Connector
                  {magicMomentTriggered && (
                    <Star className="h-5 w-5 text-yellow-500 animate-spin" />
                  )}
                </CardTitle>
                <CardDescription>
                  AI-powered workflow suggestions for your component
                </CardDescription>
              </div>
            </div>

            <div className="flex items-center gap-2">
              {analysis && renderConfidenceIndicator(analysis.confidence)}
              {onClose && (
                <Button variant="ghost" size="sm" onClick={onClose}>
                  <X className="h-4 w-4" />
                </Button>
              )}
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {isAnalyzing ? (
            <div className="flex items-center justify-center py-8">
              <div className="flex items-center gap-3">
                <Brain className="h-5 w-5 text-blue-600 animate-pulse" />
                <span className="text-gray-600">Analyzing component for workflow opportunities...</span>
                <RefreshCw className="h-4 w-4 animate-spin text-blue-600" />
              </div>
            </div>
          ) : analysis ? (
            <>
              {/* Component Analysis Summary */}
              <div className="bg-gray-50 rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <Lightbulb className="h-4 w-4 text-amber-600" />
                  <span className="font-medium text-gray-900">Component Analysis</span>
                </div>
                <p className="text-sm text-gray-600">
                  Detected <strong>{analysis.semanticPurpose.replace('_', ' ')}</strong> component 
                  with <strong>{analysis.workflowTriggers.length}</strong> workflow triggers.
                  {analysis.confidence > 0.8 && (
                    <span className="text-green-600 font-medium ml-1">
                      ✨ High-confidence match found!
                    </span>
                  )}
                </p>
              </div>

              {/* Workflow Suggestions */}
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                  <Sparkles className="h-5 w-5 text-purple-600" />
                  Suggested Workflows ({analysis.suggestedWorkflows.length})
                </h3>

                {analysis.suggestedWorkflows.length > 0 ? (
                  <div className="space-y-3">
                    {analysis.suggestedWorkflows.slice(0, 3).map(renderWorkflowSuggestion)}

                    {analysis.suggestedWorkflows.length > 3 && (
                      <Button variant="outline" size="sm" className="w-full">
                        <ArrowRight className="h-4 w-4 mr-2" />
                        View {analysis.suggestedWorkflows.length - 3} More Suggestions
                      </Button>
                    )}
                  </div>
                ) : (
                  <div className="text-center py-6 text-gray-500">
                    <Wand2 className="h-8 w-8 mx-auto mb-2 opacity-50" />
                    <p>No specific workflow suggestions for this component type.</p>
                    <Button variant="outline" size="sm" className="mt-2" onClick={analyzeComponent}>
                      <RefreshCw className="h-4 w-4 mr-2" />
                      Re-analyze
                    </Button>
                  </div>
                )}
              </div>

              {/* Magic Moment Call to Action */}
              {selectedSuggestion && selectedSuggestion.autoConnectable && (
                <div className="bg-gradient-to-r from-blue-50 to-purple-50 border border-blue-200 rounded-lg p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles className="h-5 w-5 text-purple-600" />
                    <span className="font-semibold text-gray-900">✨ Magic Moment Ready!</span>
                  </div>
                  <p className="text-sm text-gray-600 mb-3">
                    This workflow can be auto-connected with one click. 
                    No configuration required - we'll set up everything for you!
                  </p>
                  <Button 
                    onClick={() => handleConnectWorkflow(selectedSuggestion)}
                    disabled={isConnecting}
                    className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700"
                  >
                    {isConnecting ? (
                      <>
                        <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                        Creating Magic Moment...
                      </>
                    ) : (
                      <>
                        <Wand2 className="h-4 w-4 mr-2" />
                        Create Magic Moment
                      </>
                    )}
                  </Button>
                </div>
              )}
            </>
          ) : (
            <div className="text-center py-6 text-gray-500">
              <Brain className="h-8 w-8 mx-auto mb-2 opacity-50" />
              <p>Component analysis failed. Please try again.</p>
              <Button variant="outline" size="sm" className="mt-2" onClick={analyzeComponent}>
                <RefreshCw className="h-4 w-4 mr-2" />
                Retry Analysis
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default MagicConnector;

'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Sparkles, 
  Zap, 
  Target, 
  TrendingUp, 
  Workflow,
  ArrowRight,
  CheckCircle,
  X,
  Info
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData } from '@/types/builder';
import { 
  magicConnector, 
  MagicConnectorAnalysis,
  MagicConnectorSuggestion 
} from '@/lib/ai/magic-connector';

interface MagicConnectorOverlayProps {
  className?: string;
  enabled?: boolean;
  onComponentSelect?: (componentId: string) => void;
  onSuggestionClick?: (componentId: string, suggestion: MagicConnectorSuggestion) => void;
}

interface ComponentMagicState {
  componentId: string;
  analysis: MagicConnectorAnalysis | null;
  loading: boolean;
  hasHighPrioritySuggestions: boolean;
  topSuggestion: MagicConnectorSuggestion | null;
  position: { x: number; y: number };
  size: { width: number; height: number };
}

export function MagicConnectorOverlay({ 
  className, 
  enabled = true, 
  onComponentSelect,
  onSuggestionClick 
}: MagicConnectorOverlayProps) {
  const [componentStates, setComponentStates] = useState<Map<string, ComponentMagicState>>(new Map());
  const [showSuggestionTooltip, setShowSuggestionTooltip] = useState<string | null>(null);
  const [analysisQueue, setAnalysisQueue] = useState<Set<string>>(new Set());

  const { components, selectedComponentId, zoom } = useBuilderStore();

  // Memoized component analysis
  const analyzeComponentsBatch = useCallback(async (componentsToAnalyze: ComponentData[]) => {
    if (componentsToAnalyze.length === 0) return;

    const analysisPromises = componentsToAnalyze.map(async (component) => {
      try {
        const context = {
          pageContent: components.map(c => c.name).join(' '),
          businessType: 'general',
          userBehavior: {
            scrollDepth: 75,
            timeOnPage: 30000,
            previousActions: ['page_view']
          }
        };

        const analysis = await magicConnector.analyzeComponent(component, context);

        return {
          componentId: component.id,
          analysis,
          loading: false,
          hasHighPrioritySuggestions: analysis.suggestions.some(s => s.priority === 'high'),
          topSuggestion: analysis.suggestions[0] || null,
          position: component.position,
          size: component.size
        };
      } catch (error) {
        console.error(`Failed to analyze component ${component.id}:`, error);
        return {
          componentId: component.id,
          analysis: null,
          loading: false,
          hasHighPrioritySuggestions: false,
          topSuggestion: null,
          position: component.position,
          size: component.size
        };
      }
    });

    const results = await Promise.all(analysisPromises);

    setComponentStates(prev => {
      const newStates = new Map(prev);
      results.forEach(result => {
        newStates.set(result.componentId, result);
      });
      return newStates;
    });
  }, [components]);

  // Analyze components when they change
  useEffect(() => {
    if (!enabled || components.length === 0) return;

    // Filter components that haven't been analyzed yet
    const unanalyzedComponents = components.filter(component => 
      !componentStates.has(component.id) && !analysisQueue.has(component.id)
    );

    if (unanalyzedComponents.length > 0) {
      // Add to analysis queue
      setAnalysisQueue(prev => {
        const newQueue = new Set(prev);
        unanalyzedComponents.forEach(component => newQueue.add(component.id));
        return newQueue;
      });

      // Mark components as loading
      setComponentStates(prev => {
        const newStates = new Map(prev);
        unanalyzedComponents.forEach(component => {
          newStates.set(component.id, {
            componentId: component.id,
            analysis: null,
            loading: true,
            hasHighPrioritySuggestions: false,
            topSuggestion: null,
            position: component.position,
            size: component.size
          });
        });
        return newStates;
      });

      // Analyze components (debounced)
      const timeoutId = setTimeout(() => {
        analyzeComponentsBatch(unanalyzedComponents);
        setAnalysisQueue(prev => {
          const newQueue = new Set(prev);
          unanalyzedComponents.forEach(component => newQueue.delete(component.id));
          return newQueue;
        });
      }, 500);

      return () => clearTimeout(timeoutId);
    }
  }, [components, enabled, componentStates, analysisQueue, analyzeComponentsBatch]);

  // Update positions when components move
  useEffect(() => {
    setComponentStates(prev => {
      const newStates = new Map(prev);
      components.forEach(component => {
        const existingState = newStates.get(component.id);
        if (existingState) {
          newStates.set(component.id, {
            ...existingState,
            position: component.position,
            size: component.size
          });
        }
      });
      return newStates;
    });
  }, [components]);

  // Clean up removed components
  useEffect(() => {
    const componentIds = new Set(components.map(c => c.id));
    setComponentStates(prev => {
      const newStates = new Map();
      Array.from(prev.entries()).forEach(([id, state]) => {
        if (componentIds.has(id)) {
          newStates.set(id, state);
        }
      });
      return newStates;
    });
  }, [components]);

  const handleIndicatorClick = useCallback((componentId: string, suggestion?: MagicConnectorSuggestion) => {
    if (suggestion && onSuggestionClick) {
      onSuggestionClick(componentId, suggestion);
    } else if (onComponentSelect) {
      onComponentSelect(componentId);
    }
  }, [onComponentSelect, onSuggestionClick]);

  const handleConnectSuggestion = useCallback(async (componentId: string, suggestion: MagicConnectorSuggestion) => {
    try {
      await magicConnector.connectWorkflow(componentId, suggestion.workflow.workflowId);

      // Update component state to show it's connected
      setComponentStates(prev => {
        const newStates = new Map(prev);
        const state = newStates.get(componentId);
        if (state && state.analysis) {
          newStates.set(componentId, {
            ...state,
            analysis: {
              ...state.analysis,
              // Mark suggestion as connected
              suggestions: state.analysis.suggestions.map(s => 
                s.workflow.workflowId === suggestion.workflow.workflowId 
                  ? { ...s, title: `✓ ${s.title.replace('✨ ', '')}` }
                  : s
              )
            }
          });
        }
        return newStates;
      });

      // Update component in store
      useBuilderStore.getState().connectToWorkflow(componentId, suggestion.workflow.workflowId);

    } catch (error) {
      console.error('Failed to connect workflow:', error);
    }
  }, []);

  if (!enabled) return null;

  return (
    <div className={cn("absolute inset-0 pointer-events-none", className)}>
      {Array.from(componentStates.values()).map(state => (
        <MagicConnectorIndicator
          key={state.componentId}
          state={state}
          zoom={zoom}
          isSelected={selectedComponentId === state.componentId}
          onIndicatorClick={handleIndicatorClick}
          onConnectSuggestion={handleConnectSuggestion}
          showTooltip={showSuggestionTooltip === state.componentId}
          onShowTooltip={() => setShowSuggestionTooltip(state.componentId)}
          onHideTooltip={() => setShowSuggestionTooltip(null)}
        />
      ))}
    </div>
  );
}

interface MagicConnectorIndicatorProps {
  state: ComponentMagicState;
  zoom: number;
  isSelected: boolean;
  onIndicatorClick: (componentId: string, suggestion?: MagicConnectorSuggestion) => void;
  onConnectSuggestion: (componentId: string, suggestion: MagicConnectorSuggestion) => void;
  showTooltip: boolean;
  onShowTooltip: () => void;
  onHideTooltip: () => void;
}

function MagicConnectorIndicator({
  state,
  zoom,
  isSelected,
  onIndicatorClick,
  onConnectSuggestion,
  showTooltip,
  onShowTooltip,
  onHideTooltip
}: MagicConnectorIndicatorProps) {
  const { componentId, analysis, loading, hasHighPrioritySuggestions, topSuggestion, position, size } = state;

  const indicatorPosition = {
    left: (position.x + size.width - 15) * zoom,
    top: (position.y - 5) * zoom,
  };

  const tooltipPosition = {
    left: (position.x + size.width + 10) * zoom,
    top: position.y * zoom,
  };

  if (loading) {
    return (
      <div
        className="absolute pointer-events-auto"
        style={indicatorPosition}
      >
        <div className="w-6 h-6 bg-purple-100 border-2 border-purple-300 rounded-full flex items-center justify-center">
          <div className="w-3 h-3 border-2 border-purple-500 border-t-transparent rounded-full animate-spin"></div>
        </div>
      </div>
    );
  }

  if (!analysis || analysis.suggestions.length === 0) {
    return null;
  }

  const priorityColors = {
    high: 'bg-red-500 border-red-600 shadow-red-200',
    medium: 'bg-yellow-500 border-yellow-600 shadow-yellow-200',
    low: 'bg-blue-500 border-blue-600 shadow-blue-200'
  };

  const priority = hasHighPrioritySuggestions ? 'high' : 
    analysis.suggestions.some(s => s.priority === 'medium') ? 'medium' : 'low';

  return (
    <>
      {/* Magic Connector Indicator */}
      <motion.div
        className="absolute pointer-events-auto"
        style={indicatorPosition}
        initial={{ scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
      >
        <div
          className={cn(
            "relative w-6 h-6 border-2 rounded-full flex items-center justify-center cursor-pointer shadow-lg transition-all",
            priorityColors[priority],
            isSelected && "ring-2 ring-purple-400 ring-offset-1"
          )}
          onClick={() => onIndicatorClick(componentId, topSuggestion || undefined)}
          onMouseEnter={onShowTooltip}
          onMouseLeave={onHideTooltip}
        >
          <Sparkles className="w-3 h-3 text-white" />

          {/* Pulse animation for high priority */}
          {priority === 'high' && (
            <div className="absolute inset-0 rounded-full bg-red-400 animate-ping opacity-75"></div>
          )}

          {/* Connection count badge */}
          {analysis.suggestions.filter(s => s.title.includes('✓')).length > 0 && (
            <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 border border-white rounded-full flex items-center justify-center">
              <CheckCircle className="w-2 h-2 text-white" />
            </div>
          )}
        </div>
      </motion.div>

      {/* Suggestion Tooltip */}
      <AnimatePresence>
        {showTooltip && topSuggestion && (
          <motion.div
            className="absolute pointer-events-auto z-50"
            style={tooltipPosition}
            initial={{ opacity: 0, x: -10, scale: 0.9 }}
            animate={{ opacity: 1, x: 0, scale: 1 }}
            exit={{ opacity: 0, x: -10, scale: 0.9 }}
            transition={{ duration: 0.2 }}
          >
            <div className="bg-white rounded-lg shadow-xl border border-gray-200 p-4 max-w-xs">
              {/* Header */}
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center">
                  <div className="p-1 bg-purple-100 rounded">
                    {topSuggestion.category === 'conversion' && <Target className="w-3 h-3 text-purple-600" />}
                    {topSuggestion.category === 'engagement' && <TrendingUp className="w-3 h-3 text-purple-600" />}
                    {topSuggestion.category === 'automation' && <Workflow className="w-3 h-3 text-purple-600" />}
                    {topSuggestion.category === 'analytics' && <Info className="w-3 h-3 text-purple-600" />}
                  </div>
                  <span className={cn(
                    "ml-2 px-2 py-1 text-xs font-medium rounded-full",
                    priority === 'high' ? 'bg-red-100 text-red-700' :
                    priority === 'medium' ? 'bg-yellow-100 text-yellow-700' :
                    'bg-blue-100 text-blue-700'
                  )}>
                    {priority.toUpperCase()}
                  </span>
                </div>
                <button
                  onClick={onHideTooltip}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>

              {/* Content */}
              <h4 className="font-semibold text-gray-800 text-sm mb-1">
                {topSuggestion.title}
              </h4>
              <p className="text-xs text-gray-600 mb-3">
                {topSuggestion.description}
              </p>

              {/* Impact Preview */}
              <div className="grid grid-cols-2 gap-2 mb-3 text-xs">
                <div className="text-center">
                  <div className="text-gray-500">Conversion</div>
                  <div className="font-semibold text-green-600">
                    {topSuggestion.estimatedImpact.conversionIncrease}
                  </div>
                </div>
                <div className="text-center">
                  <div className="text-gray-500">Time Saved</div>
                  <div className="font-semibold text-blue-600">
                    {topSuggestion.estimatedImpact.timesSaved}
                  </div>
                </div>
              </div>

              {/* Actions */}
              <div className="flex space-x-2">
                {topSuggestion.oneClickSetup && (
                  <button
                    onClick={() => onConnectSuggestion(componentId, topSuggestion)}
                    className="flex-1 bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded text-xs font-medium transition-colors flex items-center justify-center"
                  >
                    <Zap className="w-3 h-3 mr-1" />
                    Connect
                  </button>
                )}
                <button
                  onClick={() => onIndicatorClick(componentId, topSuggestion)}
                  className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-2 rounded text-xs font-medium transition-colors flex items-center justify-center"
                >
                  View All
                  <ArrowRight className="w-3 h-3 ml-1" />
                </button>
              </div>

              {/* Additional suggestions count */}
              {analysis.suggestions.length > 1 && (
                <div className="mt-2 text-center text-xs text-gray-500">
                  +{analysis.suggestions.length - 1} more suggestions
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

export default MagicConnectorOverlay;

'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Sparkles, 
  Zap, 
  TrendingUp, 
  Clock, 
  CheckCircle, 
  AlertCircle,
  ArrowRight,
  Settings,
  BarChart3,
  Target,
  Workflow,
  Brain,
  X,
  Lightbulb
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData } from '@/types/builder';
import { 
  magicConnector, 
  MagicConnectorAnalysis, 
  MagicConnectorSuggestion,
  WorkflowConnection 
} from '@/lib/ai/magic-connector';

interface MagicConnectorPanelProps {
  className?: string;
  selectedComponentId?: string | null;
  onClose?: () => void;
}

export function MagicConnectorPanel({ 
  className, 
  selectedComponentId, 
  onClose 
}: MagicConnectorPanelProps) {
  const [analysis, setAnalysis] = useState<MagicConnectorAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'suggestions' | 'insights' | 'connections'>('suggestions');
  const [connections, setConnections] = useState<WorkflowConnection[]>([]);

  const { getSelectedComponent, components } = useBuilderStore();

  // Get current component
  const selectedComponent = useMemo(() => {
    return selectedComponentId ? 
      components.find(c => c.id === selectedComponentId) || getSelectedComponent() : 
      getSelectedComponent();
  }, [selectedComponentId, components, getSelectedComponent]);

  // Analyze component when selection changes
  useEffect(() => {
    if (selectedComponent) {
      analyzeComponent(selectedComponent);
    } else {
      setAnalysis(null);
    }
  }, [selectedComponent]);

  const analyzeComponent = useCallback(async (component: ComponentData) => {
    setLoading(true);
    setError(null);

    try {
      // Enhanced context for better analysis
      const context = {
        pageContent: components.map(c => c.name).join(' '),
        businessType: 'general', // Could be inferred from page content
        userBehavior: {
          scrollDepth: 75,
          timeOnPage: 30000,
          previousActions: ['page_view', 'component_select']
        }
      };

      const componentAnalysis = await magicConnector.analyzeComponent(component, context);
      setAnalysis(componentAnalysis);
    } catch (err) {
      console.error('Magic Connector analysis failed:', err);
      setError('Failed to analyze component. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [components]);

  const handleConnectWorkflow = useCallback(async (suggestion: MagicConnectorSuggestion) => {
    if (!selectedComponent) return;

    try {
      setLoading(true);
      const connection = await magicConnector.connectWorkflow(
        selectedComponent.id,
        suggestion.workflow.workflowId,
        { source: 'magic_connector_panel' }
      );

      setConnections(prev => [...prev, connection]);

      // Update component in store to show it's connected
      useBuilderStore.getState().connectToWorkflow(
        selectedComponent.id, 
        suggestion.workflow.workflowId
      );

      // Show success message (could use toast notification)
      console.log('Workflow connected successfully!');
    } catch (err) {
      console.error('Failed to connect workflow:', err);
      setError('Failed to connect workflow. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [selectedComponent]);

  if (!selectedComponent) {
    return (
      <div className={cn("p-6 text-center", className)}>
        <div className="mb-4">
          <Sparkles className="w-12 h-12 text-purple-400 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-gray-800 mb-2">
            Magic Connector
          </h3>
          <p className="text-gray-600 text-sm">
            Select a component to see intelligent workflow suggestions
          </p>
        </div>

        <div className="bg-gradient-to-r from-purple-50 to-blue-50 rounded-lg p-4 text-left">
          <h4 className="font-medium text-gray-800 mb-2 flex items-center">
            <Brain className="w-4 h-4 mr-2 text-purple-600" />
            How Magic Connector Works
          </h4>
          <ul className="text-sm text-gray-600 space-y-1">
            <li>• Analyzes component purpose and context</li>
            <li>• Suggests relevant automation workflows</li>
            <li>• Enables one-click workflow connections</li>
            <li>• Predicts performance improvements</li>
          </ul>
        </div>
      </div>
    );
  }

  return (
    <div className={cn("h-full flex flex-col", className)}>
      {/* Header */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-semibold text-gray-800 flex items-center">
            <Sparkles className="w-5 h-5 mr-2 text-purple-500" />
            Magic Connector
          </h3>
          {onClose && (
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>

        <div className="text-sm text-gray-600">
          Analyzing: <span className="font-medium">{selectedComponent.name}</span>
        </div>

        {/* Performance Predictions */}
        {analysis?.performancePredictions && (
          <div className="mt-3 grid grid-cols-3 gap-2">
            <div className="bg-green-50 rounded p-2 text-center">
              <div className="text-xs text-green-600 font-medium">Conversion</div>
              <div className="text-sm font-bold text-green-700">
                {Math.round(analysis.performancePredictions.conversionProbability * 100)}%
              </div>
            </div>
            <div className="bg-blue-50 rounded p-2 text-center">
              <div className="text-xs text-blue-600 font-medium">Engagement</div>
              <div className="text-sm font-bold text-blue-700">
                {Math.round(analysis.performancePredictions.engagementScore * 100)}%
              </div>
            </div>
            <div className="bg-purple-50 rounded p-2 text-center">
              <div className="text-xs text-purple-600 font-medium">Auto Potential</div>
              <div className="text-sm font-bold text-purple-700">
                {Math.round(analysis.performancePredictions.automationPotential * 100)}%
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <div className="flex">
          {[
            { id: 'suggestions', label: 'Workflows', icon: Workflow },
            { id: 'insights', label: 'Insights', icon: Lightbulb },
            { id: 'connections', label: 'Active', icon: CheckCircle }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={cn(
                "flex-1 px-3 py-3 text-sm font-medium transition-colors flex items-center justify-center",
                activeTab === tab.id
                  ? "border-b-2 border-purple-500 text-purple-600"
                  : "text-gray-500 hover:text-gray-700"
              )}
            >
              <tab.icon className="w-4 h-4 mr-1" />
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {loading && (
          <div className="p-6 text-center">
            <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full mx-auto mb-3"></div>
            <p className="text-gray-600">Analyzing component...</p>
          </div>
        )}

        {error && (
          <div className="p-4 m-4 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center mb-2">
              <AlertCircle className="w-4 h-4 text-red-500 mr-2" />
              <span className="text-red-700 font-medium">Analysis Error</span>
            </div>
            <p className="text-red-600 text-sm">{error}</p>
          </div>
        )}

        {!loading && !error && analysis && (
          <AnimatePresence mode="wait">
            {activeTab === 'suggestions' && (
              <WorkflowSuggestions 
                key="suggestions"
                suggestions={analysis.suggestions}
                quickActions={analysis.quickActions}
                onConnect={handleConnectWorkflow}
              />
            )}

            {activeTab === 'insights' && (
              <ComponentInsights 
                key="insights"
                insights={analysis.contextualInsights}
                opportunities={analysis.automationOpportunities}
                analysis={analysis.analysis}
              />
            )}

            {activeTab === 'connections' && (
              <ActiveConnections 
                key="connections"
                connections={connections}
                componentId={selectedComponent.id}
              />
            )}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
}

// Sub-components

function WorkflowSuggestions({ 
  suggestions, 
  quickActions, 
  onConnect 
}: {
  suggestions: MagicConnectorSuggestion[];
  quickActions: any[];
  onConnect: (suggestion: MagicConnectorSuggestion) => void;
}) {
  if (suggestions.length === 0) {
    return (
      <div className="p-6 text-center">
        <Workflow className="w-12 h-12 text-gray-400 mx-auto mb-3" />
        <p className="text-gray-600">No workflow suggestions available for this component.</p>
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="p-4 space-y-4"
    >
      {/* Quick Actions */}
      {quickActions.length > 0 && (
        <div className="mb-6">
          <h4 className="text-sm font-semibold text-gray-800 mb-3 flex items-center">
            <Zap className="w-4 h-4 mr-2 text-yellow-500" />
            Quick Actions
          </h4>
          <div className="space-y-2">
            {quickActions.map(action => (
              <button
                key={action.id}
                onClick={action.action}
                className="w-full p-3 bg-gradient-to-r from-yellow-50 to-orange-50 border border-yellow-200 rounded-lg text-left hover:from-yellow-100 hover:to-orange-100 transition-colors"
              >
                <div className="font-medium text-gray-800">{action.label}</div>
                <div className="text-sm text-gray-600">{action.description}</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Workflow Suggestions */}
      <div>
        <h4 className="text-sm font-semibold text-gray-800 mb-3">
          Recommended Workflows
        </h4>
        <div className="space-y-3">
          {suggestions.map((suggestion, index) => (
            <SuggestionCard 
              key={index}
              suggestion={suggestion}
              onConnect={() => onConnect(suggestion)}
            />
          ))}
        </div>
      </div>
    </motion.div>
  );
}

function SuggestionCard({ 
  suggestion, 
  onConnect 
}: {
  suggestion: MagicConnectorSuggestion;
  onConnect: () => void;
}) {
  const priorityColors = {
    high: 'from-red-50 to-pink-50 border-red-200',
    medium: 'from-yellow-50 to-orange-50 border-yellow-200',
    low: 'from-gray-50 to-gray-100 border-gray-200'
  };

  const categoryIcons = {
    conversion: Target,
    engagement: TrendingUp,
    automation: Workflow,
    analytics: BarChart3
  };

  const CategoryIcon = categoryIcons[suggestion.category];

  return (
    <div className={cn(
      "p-4 bg-gradient-to-r border rounded-lg",
      priorityColors[suggestion.priority]
    )}>
      {/* Header */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center">
          <div className="p-2 bg-white rounded-lg mr-3">
            <CategoryIcon className="w-4 h-4 text-purple-600" />
          </div>
          <div>
            <h5 className="font-semibold text-gray-800">{suggestion.title}</h5>
            <div className="flex items-center mt-1">
              <span className={cn(
                "px-2 py-1 text-xs font-medium rounded-full",
                suggestion.priority === 'high' ? 'bg-red-100 text-red-700' :
                suggestion.priority === 'medium' ? 'bg-yellow-100 text-yellow-700' :
                'bg-gray-100 text-gray-700'
              )}>
                {suggestion.priority.toUpperCase()}
              </span>
              <span className="mx-2 text-gray-400">•</span>
              <span className="text-xs text-gray-600 capitalize">
                {suggestion.category}
              </span>
            </div>
          </div>
        </div>

        {suggestion.oneClickSetup && (
          <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded-full">
            1-Click
          </span>
        )}
      </div>

      {/* Description */}
      <p className="text-sm text-gray-700 mb-3">{suggestion.description}</p>

      {/* Impact Metrics */}
      <div className="grid grid-cols-3 gap-2 mb-4">
        <div className="text-center">
          <div className="text-xs text-gray-600">Conversion</div>
          <div className="font-semibold text-green-600 text-sm">
            {suggestion.estimatedImpact.conversionIncrease}
          </div>
        </div>
        <div className="text-center">
          <div className="text-xs text-gray-600">Time Saved</div>
          <div className="font-semibold text-blue-600 text-sm">
            {suggestion.estimatedImpact.timesSaved}
          </div>
        </div>
        <div className="text-center">
          <div className="text-xs text-gray-600">Engagement</div>
          <div className="font-semibold text-purple-600 text-sm">
            {suggestion.estimatedImpact.engagementBoost}
          </div>
        </div>
      </div>

      {/* Benefits */}
      <div className="mb-4">
        <div className="text-xs font-medium text-gray-700 mb-2">Key Benefits:</div>
        <div className="grid grid-cols-1 gap-1">
          {suggestion.workflow.benefits.slice(0, 2).map((benefit, idx) => (
            <div key={idx} className="flex items-center text-xs text-gray-600">
              <CheckCircle className="w-3 h-3 text-green-500 mr-2 flex-shrink-0" />
              {benefit}
            </div>
          ))}
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center text-xs text-gray-500">
          <Clock className="w-3 h-3 mr-1" />
          {suggestion.setupComplexity} setup
        </div>

        <button
          onClick={onConnect}
          className="bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center"
        >
          Connect
          <ArrowRight className="w-4 h-4 ml-1" />
        </button>
      </div>
    </div>
  );
}

