          {responsiveSettings.simulateTouch && (
            <span className="text-blue-300">• Touch Simulation</span>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData } from '@/types/builder';
import { BreakpointSize, ResponsiveComponentProps } from '@/types/responsive';
import { cn } from '@/lib/utils';

interface ResponsiveComponentWrapperProps {
  component: ComponentData;
  children: React.ReactNode;
  className?: string;
}

/**
 * Wrapper component that applies responsive styles and props to components
 * based on the current viewport breakpoint
 */
export function ResponsiveComponentWrapper({
  component,
  children,
  className
}: ResponsiveComponentWrapperProps) {
  const { viewport } = useBuilderStore();

  // Get responsive props for current breakpoint
  const responsiveProps = useMemo(() => {
    const props = component.props as ResponsiveComponentProps;
    const currentBreakpoint = viewport.currentBreakpoint;

    // Start with base props and override with breakpoint-specific props
    let mergedProps = { ...props };

    // Apply breakpoint-specific props in mobile-first order
    if (props.mobile && (currentBreakpoint === 'mobile' || shouldInheritFromMobile(currentBreakpoint, props))) {
      mergedProps = { ...mergedProps, ...props.mobile };
    }

    if (props.tablet && (currentBreakpoint === 'tablet' || shouldInheritFromTablet(currentBreakpoint, props))) {
      mergedProps = { ...mergedProps, ...props.tablet };
    }

    if (props.desktop && (currentBreakpoint === 'desktop' || currentBreakpoint === 'wide')) {
      mergedProps = { ...mergedProps, ...props.desktop };
    }

    if (props.wide && currentBreakpoint === 'wide') {
      mergedProps = { ...mergedProps, ...props.wide };
    }

    return mergedProps;
  }, [component.props, viewport.currentBreakpoint]);

  // Calculate responsive size based on breakpoint
  const responsiveSize = useMemo(() => {
    const baseSize = component.size;
    const breakpoint = viewport.currentBreakpoint;

    // Apply mobile-first responsive sizing
    switch (breakpoint) {
      case 'mobile':
        return {
          width: Math.min(baseSize.width, viewport.width - 40), // Leave 20px margin on each side
          height: baseSize.height
        };
      case 'tablet':
        return {
          width: Math.min(baseSize.width, viewport.width - 60), // Leave 30px margin on each side
          height: baseSize.height
        };
      default:
        return baseSize;
    }
  }, [component.size, viewport]);

  // Generate responsive classes based on component type and breakpoint
  const responsiveClasses = useMemo(() => {
    const breakpoint = viewport.currentBreakpoint;
    const componentType = component.type;

    const classes = [];

    // Base responsive classes
    classes.push('transition-all duration-200');

    // Component type specific responsive behavior
    switch (componentType) {
      case 'text':
        classes.push(
          breakpoint === 'mobile' ? 'text-sm' : 
          breakpoint === 'tablet' ? 'text-base' : 'text-lg'
        );
        break;
      case 'button':
        classes.push(
          breakpoint === 'mobile' ? 'px-3 py-2 text-sm' : 
          breakpoint === 'tablet' ? 'px-4 py-2' : 'px-6 py-3'
        );
        break;
      case 'container':
        classes.push(
          breakpoint === 'mobile' ? 'p-4' : 
          breakpoint === 'tablet' ? 'p-6' : 'p-8'
        );
        break;
      case 'image':
        classes.push('w-full h-auto object-cover');
        if (breakpoint === 'mobile') {
          classes.push('rounded-lg');
        }
        break;
    }

    // Spacing adjustments for mobile
    if (breakpoint === 'mobile') {
      classes.push('mb-4'); // Increased spacing between components on mobile
    }

    return classes.join(' ');
  }, [component.type, viewport.currentBreakpoint]);

  // Handle touch interactions for mobile
  const touchProps = viewport.currentBreakpoint === 'mobile' ? {
    style: {
      ...responsiveSize,
      touchAction: 'manipulation', // Optimized for touch
      WebkitTapHighlightColor: 'transparent', // Remove tap highlight on mobile
    }
  } : {
    style: responsiveSize
  };

  return (
    <div
      className={cn(responsiveClasses, className)}
      data-responsive-breakpoint={viewport.currentBreakpoint}
      data-component-type={component.type}
      {...touchProps}
    >
      {React.cloneElement(children as React.ReactElement, {
        ...responsiveProps,
        // Pass through responsive context
        responsiveBreakpoint: viewport.currentBreakpoint,
        isResponsivePreview: viewport.currentBreakpoint !== 'desktop'
      })}

      {/* Mobile-specific overlay for touch interaction feedback */}
      {viewport.currentBreakpoint === 'mobile' && (
        <div className="absolute inset-0 pointer-events-none">
          {/* Touch interaction indicator */}
          <div className="absolute top-1 right-1 w-2 h-2 bg-blue-400 rounded-full opacity-0 group-hover:opacity-100 transition-opacity" />
        </div>
      )}
    </div>
  );
}

/**
 * Helper functions for responsive prop inheritance
 */
function shouldInheritFromMobile(currentBreakpoint: BreakpointSize, props: ResponsiveComponentProps): boolean {
  // Inherit mobile props for tablet if no tablet-specific props exist
  return currentBreakpoint === 'tablet' && !props.tablet;
}

function shouldInheritFromTablet(currentBreakpoint: BreakpointSize, props: ResponsiveComponentProps): boolean {
  // Inherit tablet props for desktop if no desktop-specific props exist
  return currentBreakpoint === 'desktop' && !props.desktop && props.tablet;
}

'use client';

import React, { useState } from 'react';
import { Monitor, Smartphone, Tablet, Tv, RotateCcw, Settings } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { 
  BREAKPOINTS, 
  MOBILE_PREVIEW_DEVICES, 
  BreakpointSize, 
  ViewportState,
  ResponsivePreviewSettings 
} from '@/types/responsive';
import { cn } from '@/lib/utils';

interface ResponsiveControlsProps {
  viewport: ViewportState;
  settings: ResponsivePreviewSettings;
  onViewportChange: (viewport: Partial<ViewportState>) => void;
  onSettingsChange: (settings: Partial<ResponsivePreviewSettings>) => void;
  className?: string;
}

const BREAKPOINT_ICONS = {
  mobile: Smartphone,
  tablet: Tablet,
  desktop: Monitor,
  wide: Tv
};

export function ResponsiveControls({
  viewport,
  settings,
  onViewportChange,
  onSettingsChange,
  className
}: ResponsiveControlsProps) {
  const [customDevice, setCustomDevice] = useState<string>('');

  const handleBreakpointChange = (breakpoint: BreakpointSize) => {
    const bp = BREAKPOINTS[breakpoint];
    onViewportChange({
      currentBreakpoint: breakpoint,
      width: bp.width,
      height: bp.height,
      orientation: bp.width < bp.height ? 'portrait' : 'landscape'
    });
  };

  const handleDeviceChange = (deviceName: string) => {
    const device = MOBILE_PREVIEW_DEVICES.find(d => d.name === deviceName);
    if (device) {
      setCustomDevice(deviceName);
      onViewportChange({
        currentBreakpoint: 'mobile',
        width: device.width,
        height: device.height,
        orientation: device.width < device.height ? 'portrait' : 'landscape'
      });
    }
  };

  const handleOrientationToggle = () => {
    const newOrientation = viewport.orientation === 'portrait' ? 'landscape' : 'portrait';
    onViewportChange({
      orientation: newOrientation,
      width: viewport.height,
      height: viewport.width
    });
  };

  const getCurrentBreakpointInfo = () => {
    const bp = BREAKPOINTS[viewport.currentBreakpoint];
    return `${bp.name} (${viewport.width}×${viewport.height})`;
  };

  return (
    <div className={cn(
      "flex items-center gap-2 p-2 bg-white border rounded-lg shadow-sm",
      className
    )}>
      {/* Breakpoint Selection */}
      <div className="flex items-center gap-1 border-r pr-2">
        {Object.entries(BREAKPOINTS).map(([key, breakpoint]) => {
          const Icon = BREAKPOINT_ICONS[key as BreakpointSize];
          const isActive = viewport.currentBreakpoint === key;

          return (
            <Button
              key={key}
              variant={isActive ? "default" : "ghost"}
              size="sm"
              onClick={() => handleBreakpointChange(key as BreakpointSize)}
              className={cn(
                "w-9 h-9 p-0",
                isActive && "bg-blue-600 hover:bg-blue-700"
              )}
              title={`${breakpoint.name} (${breakpoint.width}×${breakpoint.height})`}
            >
              <Icon className="w-4 h-4" />
            </Button>
          );
        })}
      </div>

      {/* Device Presets for Mobile */}
      {viewport.currentBreakpoint === 'mobile' && (
        <div className="border-r pr-2">
          <Select value={customDevice} onValueChange={handleDeviceChange}>
            <SelectTrigger className="w-[140px] h-8">
              <SelectValue placeholder="Device preset" />
            </SelectTrigger>
            <SelectContent>
              {MOBILE_PREVIEW_DEVICES.map((device) => (
                <SelectItem key={device.name} value={device.name}>
                  {device.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      )}

      {/* Orientation Toggle */}
      <Button
        variant="ghost"
        size="sm"
        onClick={handleOrientationToggle}
        className="w-9 h-9 p-0"
        title={`Switch to ${viewport.orientation === 'portrait' ? 'landscape' : 'portrait'}`}
      >
        <RotateCcw className="w-4 h-4" />
      </Button>

      {/* Current Viewport Info */}
      <div className="text-sm text-gray-600 font-medium border-r pr-2">
        {getCurrentBreakpointInfo()}
      </div>

      {/* Zoom Level */}
      <div className="text-sm text-gray-500 border-r pr-2">
        {Math.round(viewport.zoom * 100)}%
      </div>

      {/* Settings Popover */}
      <Popover>
        <PopoverTrigger asChild>
          <Button variant="ghost" size="sm" className="w-9 h-9 p-0">
            <Settings className="w-4 h-4" />
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-80" align="end">
          <div className="space-y-4">
            <h4 className="font-medium">Responsive Preview Settings</h4>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <Label htmlFor="breakpoint-borders" className="text-sm">
                  Show breakpoint borders
                </Label>
                <Switch
                  id="breakpoint-borders"
                  checked={settings.showBreakpointBorders}
                  onCheckedChange={(checked) => 
                    onSettingsChange({ showBreakpointBorders: checked })
                  }
                />
              </div>

              <div className="flex items-center justify-between">
                <Label htmlFor="responsive-grid" className="text-sm">
                  Show responsive grid
                </Label>
                <Switch
                  id="responsive-grid"
                  checked={settings.showResponsiveGrid}
                  onCheckedChange={(checked) => 
                    onSettingsChange({ showResponsiveGrid: checked })
                  }
                />
              </div>

              <div className="flex items-center justify-between">
                <Label htmlFor="auto-rotate" className="text-sm">
                  Auto-rotate preview
                </Label>
                <Switch
                  id="auto-rotate"
                  checked={settings.autoRotate}
                  onCheckedChange={(checked) => 
                    onSettingsChange({ autoRotate: checked })
                  }
                />
              </div>

              <div className="flex items-center justify-between">
                <Label htmlFor="simulate-touch" className="text-sm">
                  Simulate touch interactions
                </Label>
                <Switch
                  id="simulate-touch"
                  checked={settings.simulateTouch}
                  onCheckedChange={(checked) => 
                    onSettingsChange({ simulateTouch: checked })
                  }
                />
              </div>
            </div>

            <div className="pt-3 border-t">
              <p className="text-xs text-gray-500">
                Changes apply to canvas preview only. Published sites will be fully responsive.
              </p>
            </div>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

