interface SimpleContainerProps {
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  isSelected?: boolean;
  isEmpty?: boolean;
  onDrop?: (e: React.DragEvent) => void;
  onDragOver?: (e: React.DragEvent) => void;
}

export function SimpleContainer({
  children,
  className,
  style,
  isSelected = false,
  isEmpty = false,
  onDrop,
  onDragOver,
}: SimpleContainerProps) {
  return (
    <div
      className={cn(
        // Base container styles
        "relative min-h-[120px] w-full rounded-lg transition-all duration-200",

        // Empty state styling
        isEmpty && [
          "border-2 border-dashed border-gray-300",
          "bg-gray-50/50",
          "flex items-center justify-center"
        ],

        // With content styling
        !isEmpty && [
          "border border-gray-200",
          "bg-white"
        ],

        // Selection state
        isSelected && "ring-2 ring-blue-500",

        // Hover state for empty containers
        isEmpty && "hover:border-blue-300 hover:bg-blue-50/30",

        // Custom classes
        className
      )}
      style={style}
      onDrop={onDrop}
      onDragOver={onDragOver}
    >
      {isEmpty ? (
        <div className="text-center p-8">
          <div className="text-gray-400 text-sm font-medium mb-2">
            Container Section
          </div>
          <div className="text-gray-500 text-xs">
            Drop components here to build your layout
          </div>
        </div>
      ) : (
        <div className="p-4">
          {children}
        </div>
      )}
    </div>
  );
}

