/**
 * Converts node status data to timeline steps
 */
function convertNodesToTimelineSteps(
  nodes: WorkflowNode[],
  statusData: Record<string, WorkflowNodeData>
): TimelineStep[] {
  return nodes.map(node => {
    const status = statusData[node.id];

    return {
      id: node.id,
      node_id: node.id,
      node_name: node.name,
      node_type: node.type,
      status: status?.status || 'pending',
      started_at: status?.lastUpdated || new Date(),
      completed_at: status?.status === 'success' || status?.status === 'failed' 
        ? status.lastUpdated 
        : undefined,
      execution_time_ms: status?.executionTime,
      error_message: status?.errorMessage,
      // Mock additional data for demo
      input_data: { node_config: node.config },
      output_data: status?.status === 'success' ? { result: 'processed' } : undefined,
      performance_metrics: {
        memory_usage_mb: Math.random() * 50,
        cpu_usage_percent: Math.random() * 80
      }
    };
  });
}

/**
 * Converts node status to workflow error for modal
 */
function convertNodeStatusToError(
  node: WorkflowNode,
  status: WorkflowNodeData
): WorkflowError | null {
  if (status.status !== 'failed' || !status.errorMessage) return null;

  return {
    id: `error-${node.id}-${Date.now()}`,
    workflow_id: 1, // Mock
    execution_id: 1, // Mock
    node_id: node.id,
    node_name: node.name,
    node_type: node.type,
    error_message: status.errorMessage,
    error_stack_trace: 'Mock stack trace for demo purposes',
    error_code: 'EXECUTION_FAILED',
    timestamp: status.lastUpdated?.toISOString() || new Date().toISOString(),
    execution_time_ms: status.executionTime,
    retry_count: 0,
    debug_logs: [
      {
        timestamp: new Date().toISOString(),
        level: 'ERROR' as const,
        message: status.errorMessage,
        context: { node_id: node.id, node_type: node.type }
      }
    ],
    input_data: { node_config: node.config },
    performance_metrics: {
      memory_usage_mb: Math.random() * 50,
      cpu_usage_percent: Math.random() * 80
    },
    suggested_actions: [
      {
        action: 'Retry Node Execution',
        description: 'Retry this node with the same configuration',
        type: 'retry',
        confidence: 0.9
      },
      {
        action: 'Check Node Configuration',
        description: 'Review and update node parameters',
        type: 'config',
        confidence: 0.7
      }
    ]
  };
}

// ============================================================================
// SUB-COMPONENTS
// ============================================================================

/**
 * Workflow canvas with status overlays
 */
const WorkflowCanvas = memo<{
  nodes: WorkflowNode[];
  statusData: Record<string, WorkflowNodeData>;
  onNodeClick: (node: WorkflowNode, status: WorkflowNodeData) => void;
  showStatusOverlays: boolean;
}>(({ nodes, statusData, onNodeClick, showStatusOverlays }) => {
  const canvasStyle = {
    width: '800px',
    height: '500px',
    position: 'relative' as const,
    background: 'radial-gradient(circle at 20% 50%, rgba(120, 119, 198, 0.1) 0%, transparent 50%), radial-gradient(circle at 80% 50%, rgba(255, 202, 84, 0.1) 0%, transparent 50%)',
    borderRadius: '12px',
    border: '1px solid rgb(55 65 81)', // border-gray-700
  };

  return (
    <div className="p-6 border border-gray-700 rounded-xl bg-gray-900/50 backdrop-blur-sm">
      <div style={canvasStyle}>
        {/* Connection lines */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none">
          {nodes.map(node => 
            node.connections.map(connectedNodeId => {
              const connectedNode = nodes.find(n => n.id === connectedNodeId);
              if (!connectedNode) return null;

              return (
                <line
                  key={`${node.id}-${connectedNodeId}`}
                  x1={node.position.x + 60}
                  y1={node.position.y + 30}
                  x2={connectedNode.position.x + 60}
                  y2={connectedNode.position.y + 30}
                  stroke="rgb(75 85 99)" // gray-600
                  strokeWidth="2"
                  strokeDasharray="5,5"
                />
              );
            })
          )}
        </svg>

        {/* Workflow nodes */}
        {nodes.map(node => {
          const status = statusData[node.id];

          return (
            <div
              key={node.id}
              className={cn(
                'absolute w-32 h-16 p-3 rounded-lg border border-gray-600',
                'bg-gray-800 hover:bg-gray-700 transition-colors cursor-pointer',
                'flex flex-col justify-center items-center text-center',
                status?.status === 'running' && 'animate-pulse border-blue-400',
                status?.status === 'success' && 'border-green-400',
                status?.status === 'failed' && 'border-red-400'
              )}
              style={{
                left: `${node.position.x}px`,
                top: `${node.position.y}px`
              }}
              onClick={() => status && onNodeClick(node, status)}
            >
              <div className="text-xs font-medium text-white truncate w-full">
                {node.name}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {node.type.replace('_', ' ').toUpperCase()}
              </div>

              {/* Status overlay */}
              {showStatusOverlays && status && (
                <WorkflowStatusOverlay
                  node={status}
                  position="top-right"
                  size="sm"
                  showProgress={true}
                  showExecutionTime={true}
                  animate={true}
                  className="z-10"
                />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
});

WorkflowCanvas.displayName = 'WorkflowCanvas';

/**
 * Debugging controls panel
 */
const DebuggingControls = memo<{
  isDebugging: boolean;
  isExecuting: boolean;
  connectionState: {
    status: string;
    reconnectCount?: number;
  };
  onStartDebugging: () => void;
  onStopDebugging: () => void;
  onExecuteWorkflow: () => void;
  onRefreshStatus: () => void;
  showStatusOverlays: boolean;
  onToggleStatusOverlays: (show: boolean) => void;
}>(({ 
  isDebugging, 
  isExecuting, 
  connectionState,
  onStartDebugging, 
  onStopDebugging, 
  onExecuteWorkflow,
  onRefreshStatus,
  showStatusOverlays,
  onToggleStatusOverlays
}) => {
  const connectionStatusDisplay = {
    connected: { color: 'text-green-400', label: 'Connected' },
    connecting: { color: 'text-yellow-400', label: 'Connecting...' },
    disconnected: { color: 'text-gray-400', label: 'Disconnected' },
    error: { color: 'text-red-400', label: 'Error' },
  };

  const currentStatus = connectionStatusDisplay[connectionState.status as keyof typeof connectionStatusDisplay] || 
    connectionStatusDisplay.disconnected;

  return (
    <div className="flex items-center justify-between p-4 bg-gray-800/50 border-b border-gray-700">
      <div className="flex items-center space-x-4">
        <div className="flex items-center space-x-2">
          <div className={cn('w-2 h-2 rounded-full', currentStatus.color.replace('text-', 'bg-'))} />
          <span className={cn('text-sm font-medium', currentStatus.color)}>
            {currentStatus.label}
          </span>
          {connectionState.reconnectCount && connectionState.reconnectCount > 0 && (
            <Badge variant="outline" className="text-xs">
              Retry {connectionState.reconnectCount}
            </Badge>
          )}
        </div>
      </div>

      <div className="flex items-center space-x-2">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onToggleStatusOverlays(!showStatusOverlays)}
          className={showStatusOverlays ? 'bg-yellow-400/10 border-yellow-400/30' : ''}
        >
          {showStatusOverlays ? <Eye className="w-3 h-3" /> : <EyeOff className="w-3 h-3" />}
        </Button>

        <Button
          variant="outline"
          size="sm"
          onClick={onRefreshStatus}
          disabled={isExecuting}
        >
          <RefreshCw className={cn('w-3 h-3', isExecuting && 'animate-spin')} />
        </Button>

        <Button
          variant="outline"
          size="sm"
          onClick={onExecuteWorkflow}
          disabled={isExecuting || !isDebugging}
        >
          <Play className="w-3 h-3 mr-2" />
          Execute
        </Button>

        {!isDebugging ? (
          <Button
            onClick={onStartDebugging}
            className="bg-yellow-400 text-black hover:bg-yellow-300"
          >
            <Activity className="w-3 h-3 mr-2" />
            Start Debugging
          </Button>
        ) : (
          <Button
            variant="outline"
            onClick={onStopDebugging}
          >
            <Square className="w-3 h-3 mr-2" />
            Stop Debugging
          </Button>
        )}
      </div>
    </div>
  );
});

DebuggingControls.displayName = 'DebuggingControls';

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const WorkflowDebuggingPanel = memo<WorkflowDebuggingPanelProps>(({
  workflow,
  isDebugging = false,
  onStartDebugging,
  onStopDebugging,
  onExecuteWorkflow,
  onEditNode,
  onExport,
  className
}) => {
  // ===== STATE =====
  const [selectedError, setSelectedError] = useState<WorkflowError | null>(null);
  const [showStatusOverlays, setShowStatusOverlays] = useState(true);
  const [isExecuting, setIsExecuting] = useState(false);

  // ===== WORKFLOW STATUS HOOK =====
  const workflowStatus = useWorkflowStatus({
    workflowId: workflow?.id || null,
    autoConnect: isDebugging,
    onStatusUpdate: (nodeId, status) => {
      console.log(`Node ${nodeId} status updated:`, status);
    },
    onExecutionComplete: (execution) => {
      console.log('Execution completed:', execution);
      setIsExecuting(false);
    },
    onError: (error) => {
      console.error('Workflow status error:', error);
    }
  });

  // ===== DERIVED DATA =====
  const nodes = useMemo(() => mockWorkflowNodes, []); // In real app, would come from workflow.nodes

  const timelineSteps = useMemo(() => 
    convertNodesToTimelineSteps(nodes, workflowStatus.nodeStatuses),
    [nodes, workflowStatus.nodeStatuses]
  );

  const executionStats = useMemo(() => {
    const statuses = Object.values(workflowStatus.nodeStatuses);
    const total = statuses.length;
    const completed = statuses.filter(s => s.status === 'success' || s.status === 'failed').length;
    const failed = statuses.filter(s => s.status === 'failed').length;
    const running = statuses.filter(s => s.status === 'running').length;

    return { total, completed, failed, running };
  }, [workflowStatus.nodeStatuses]);

  // ===== HANDLERS =====
  const handleStartDebugging = useCallback(() => {
    workflowStatus.connect();
    onStartDebugging?.();
  }, [workflowStatus, onStartDebugging]);

  const handleStopDebugging = useCallback(() => {
    workflowStatus.disconnect();
    onStopDebugging?.();
  }, [workflowStatus, onStopDebugging]);

  const handleExecuteWorkflow = useCallback(async () => {
    if (!onExecuteWorkflow) {
      // Mock execution for demo
      setIsExecuting(true);

      // Simulate node execution sequence
      const nodeIds = nodes.map(n => n.id);

      for (let i = 0; i < nodeIds.length; i++) {
        const nodeId = nodeIds[i];
        const node = nodes.find(n => n.id === nodeId)!;

        // Set to running
        const runningStatus: WorkflowNodeData = {
          id: nodeId,
          status: 'running',
          progress: 0,
          lastUpdated: new Date()
        };

        // Simulate progress updates
        for (let progress = 0; progress <= 100; progress += 25) {
          setTimeout(() => {
            // Mock status update - in real app this would come from WebSocket
          }, i * 2000 + (progress / 25) * 500);
        }

        // Complete with success or failure (10% chance of failure)
        setTimeout(() => {
          const isSuccess = Math.random() > 0.1;
          const finalStatus: WorkflowNodeData = {
            id: nodeId,
            status: isSuccess ? 'success' : 'failed',
            executionTime: Math.floor(Math.random() * 3000) + 500,
            lastUpdated: new Date(),
            errorMessage: isSuccess ? undefined : 'Simulated execution error'
          };

          // Mock status update - in real app this would come from WebSocket
        }, (i + 1) * 2000);
      }

      // Complete execution
      setTimeout(() => {
        setIsExecuting(false);
      }, (nodeIds.length + 1) * 2000);

      return;
    }

    try {
      setIsExecuting(true);
      await onExecuteWorkflow();
    } catch (error) {
      console.error('Workflow execution failed:', error);
      setIsExecuting(false);
    }
  }, [onExecuteWorkflow, nodes]);

  const handleNodeClick = useCallback((node: WorkflowNode, status: WorkflowNodeData) => {
    if (status.status === 'failed') {
      const error = convertNodeStatusToError(node, status);
      if (error) {
        setSelectedError(error);
      }
    }
  }, []);

  const handleRetryNode = useCallback((nodeId: string) => {
    console.log('Retrying node:', nodeId);
    setSelectedError(null);
    // In real app, would trigger node retry
  }, []);

  const handleEditNodeConfig = useCallback((nodeId: string) => {
    console.log('Editing node config:', nodeId);
    setSelectedError(null);
    onEditNode?.(nodeId);
  }, [onEditNode]);

  const handleViewLogs = useCallback((executionId: number) => {
    console.log('Viewing logs for execution:', executionId);
    // In real app, would open logs viewer
  }, []);

  const handleExport = useCallback((format: 'pdf' | 'csv') => {
    const exportData = {
      workflow_id: workflow?.id,
      workflow_name: workflow?.name,
      execution_stats: executionStats,
      timeline_steps: timelineSteps,
      node_statuses: workflowStatus.nodeStatuses,
      timestamp: new Date().toISOString()
    };

    console.log(`Exporting ${format}:`, exportData);
    onExport?.(format, exportData);
  }, [workflow, executionStats, timelineSteps, workflowStatus.nodeStatuses, onExport]);

  // ===== RENDER =====
  return (
    <div className={cn(
      'flex flex-col bg-gray-900 border border-gray-700 rounded-xl overflow-hidden',
      className
    )}>
      {/* Header */}
      <div className="p-6 border-b border-gray-700">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-white mb-2">
              Workflow Debugging Panel
            </h1>
            {workflow && (
              <div className="flex items-center space-x-4 text-sm text-gray-400">
                <span>Workflow: {workflow.name}</span>
                <span>•</span>
                <span>Nodes: {executionStats.total}</span>
                {executionStats.running > 0 && (
                  <>
                    <span>•</span>
                    <span className="text-blue-400">Running: {executionStats.running}</span>
                  </>
                )}
                {executionStats.failed > 0 && (
                  <>
                    <span>•</span>
                    <span className="text-red-400">Failed: {executionStats.failed}</span>
                  </>
                )}
              </div>
            )}
          </div>

          <div className="flex items-center space-x-2">
            <Badge 
              variant="outline" 
              className={cn(
                isDebugging 
                  ? 'text-green-400 border-green-400/30' 
                  : 'text-gray-400 border-gray-400/30'
              )}
            >
              {isDebugging ? 'Debugging Active' : 'Debugging Inactive'}
            </Badge>
          </div>
        </div>
      </div>

      {/* Controls */}
      <DebuggingControls
        isDebugging={isDebugging}
        isExecuting={isExecuting}
        connectionState={workflowStatus}
        onStartDebugging={handleStartDebugging}
        onStopDebugging={handleStopDebugging}
        onExecuteWorkflow={handleExecuteWorkflow}
        onRefreshStatus={workflowStatus.retry}
        showStatusOverlays={showStatusOverlays}
        onToggleStatusOverlays={setShowStatusOverlays}
      />

      {/* Main Content */}
      <div className="flex-1 overflow-hidden">
        <Tabs defaultValue="canvas" className="h-full flex flex-col">
          <TabsList className="mx-6 mt-4 w-fit">
            <TabsTrigger value="canvas">Workflow Canvas</TabsTrigger>
            <TabsTrigger value="timeline">Execution Timeline</TabsTrigger>
            <TabsTrigger value="metrics">Performance Metrics</TabsTrigger>
          </TabsList>

          <TabsContent value="canvas" className="flex-1 m-0 p-6">
            <WorkflowCanvas
              nodes={nodes}
              statusData={workflowStatus.nodeStatuses}
              onNodeClick={handleNodeClick}
              showStatusOverlays={showStatusOverlays}
            />
          </TabsContent>

          <TabsContent value="timeline" className="flex-1 m-0 p-6">
            <ExecutionTimeline
              steps={timelineSteps}
              isRunning={isExecuting}
              showMetrics={true}
              detailedView={false}
              onExport={handleExport}
              className="h-full"
            />
          </TabsContent>

          <TabsContent value="metrics" className="flex-1 m-0 p-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm font-medium text-gray-400">
                    Execution Status
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-white mb-2">
                    {executionStats.completed}/{executionStats.total}
                  </div>
                  <div className="text-xs text-gray-400">
                    {executionStats.total > 0 
                      ? Math.round((executionStats.completed / executionStats.total) * 100)
                      : 0}% Complete
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm font-medium text-gray-400">
                    Success Rate
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-green-400 mb-2">
                    {executionStats.completed > 0 
                      ? Math.round(((executionStats.completed - executionStats.failed) / executionStats.completed) * 100)
                      : 0}%
                  </div>
                  <div className="text-xs text-gray-400">
                    {executionStats.failed} failures
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm font-medium text-gray-400">
                    Avg Execution Time
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-blue-400 mb-2">
                    {Math.round(Math.random() * 2000 + 500)}ms
                  </div>
                  <div className="text-xs text-gray-400">
                    Per node average
                  </div>
                </CardContent>
              </Card>
            </div>
          </TabsContent>
        </Tabs>
      </div>

      {/* Error Details Modal */}
      <ErrorDetailsModal
        isOpen={!!selectedError}
        onClose={() => setSelectedError(null)}
        error={selectedError}
        onRetry={handleRetryNode}
        onEditConfig={handleEditNodeConfig}
        onViewLogs={handleViewLogs}
      />
    </div>
  );
});

WorkflowDebuggingPanel.displayName = 'WorkflowDebuggingPanel';

// ============================================================================
// EXPORTS
// ============================================================================

export default WorkflowDebuggingPanel;

export type {
  WorkflowNode,
  WorkflowDebuggingPanelProps,
};

/**
 * Workflow Intelligence Hub
 * 
 * Integration component that combines Magic Connector and Smart Component Suggestions
 * Provides a unified interface for AI-powered workflow building and optimization
 */

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Brain, 
  Workflow, 
  Target, 
  Sparkles, 
  Zap,
  ArrowRight,
  Settings,
  BarChart3,
  Lightbulb,
  CheckCircle2,
  Clock,
  Users,
  TrendingUp
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { SmartComponentSuggestions } from './SmartComponentSuggestions';
import { MagicConnector } from './MagicConnector';
import { 
  ComponentSuggestion, 
  WorkflowContext, 
  componentSuggestionEngine 
} from '@/lib/ai/component-suggestion-engine';
import { 
  ComponentAnalysis,
  componentAnalyzer 
} from '@/lib/ai/component-analyzer';

interface WorkflowIntelligenceHubProps {
  workflowId?: string;
  currentComponents: any[];
  onComponentAdd: (component: any) => void;
  onWorkflowConnect: (workflowId: string, component: any) => void;
  businessContext?: {
    industry: string;
    target_audience: string;
    business_goals: string[];
    workflow_type: WorkflowContext['workflow_type'];
    conversion_stage: WorkflowContext['conversion_funnel_stage'];
  };
  className?: string;
}

interface IntelligenceInsight {
  type: 'component_gap' | 'workflow_optimization' | 'conversion_opportunity' | 'automation_potential';
  title: string;
  description: string;
  impact: 'high' | 'medium' | 'low';
  action_required: boolean;
  quick_fix_available: boolean;
}

export const WorkflowIntelligenceHub: React.FC<WorkflowIntelligenceHubProps> = ({
  workflowId,
  currentComponents,
  onComponentAdd,
  onWorkflowConnect,
  businessContext,
  className = ''
}) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [workflowContext, setWorkflowContext] = useState<WorkflowContext | null>(null);
  const [selectedComponent, setSelectedComponent] = useState<any>(null);
  const [showMagicConnector, setShowMagicConnector] = useState(false);
  const [insights, setInsights] = useState<IntelligenceInsight[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Initialize workflow context
  useEffect(() => {
    if (businessContext) {
      const context: WorkflowContext = {
        workflow_id: workflowId,
        workflow_type: businessContext.workflow_type,
        current_components: currentComponents,
        missing_components: [],
        business_goals: businessContext.business_goals,
        target_audience: businessContext.target_audience,
        industry: businessContext.industry,
        conversion_funnel_stage: businessContext.conversion_stage
      };
      setWorkflowContext(context);
    }
  }, [businessContext, currentComponents, workflowId]);

  // Generate intelligence insights
  useEffect(() => {
    if (workflowContext) {
      generateInsights();
    }
  }, [workflowContext]);

  const generateInsights = useCallback(async () => {
    if (!workflowContext) return;

    setIsAnalyzing(true);
    try {
      // Analyze workflow gaps
      const gapAnalysis = await componentSuggestionEngine.analyzeWorkflowGaps(workflowContext);

      // Generate component analyses
      const componentAnalyses = await Promise.all(
        currentComponents.map(component => componentAnalyzer.analyzeComponent(component))
      );

      const newInsights: IntelligenceInsight[] = [];

      // Component gap insights
      if (gapAnalysis.critical_gaps.length > 0) {
        newInsights.push({
          type: 'component_gap',
          title: 'Critical Component Gaps Detected',
          description: `Missing ${gapAnalysis.critical_gaps.length} essential components for optimal workflow performance`,
          impact: 'high',
          action_required: true,
          quick_fix_available: true
        });
      }

      // Workflow optimization insights
      if (gapAnalysis.completeness_score < 0.8) {
        newInsights.push({
          type: 'workflow_optimization',
          title: 'Workflow Optimization Available',
          description: `Current completeness: ${Math.round(gapAnalysis.completeness_score * 100)}%. Add suggested components to improve performance.`,
          impact: 'medium',
          action_required: false,
          quick_fix_available: true
        });
      }

      // Automation potential insights
      const highAutomationComponents = componentAnalyses.filter(
        analysis => analysis.suggestedWorkflows.some(w => w.autoConnectable)
      );

      if (highAutomationComponents.length > 0) {
        newInsights.push({
          type: 'automation_potential',
          title: 'Automation Opportunities Found',
          description: `${highAutomationComponents.length} components can be automatically connected to workflows`,
          impact: 'high',
          action_required: false,
          quick_fix_available: true
        });
      }

      // Conversion optimization insights
      const formComponents = currentComponents.filter(c => c.type === 'form' || c.type === 'contact-form');
      if (formComponents.length > 0 && workflowContext.conversion_funnel_stage === 'consideration') {
        newInsights.push({
          type: 'conversion_opportunity',
          title: 'Conversion Optimization Potential',
          description: 'Form components detected in consideration stage. Add trust signals and social proof.',
          impact: 'medium',
          action_required: false,
          quick_fix_available: true
        });
      }

      setInsights(newInsights);
    } catch (error) {
      console.error('Failed to generate insights:', error);
    } finally {
      setIsAnalyzing(false);
    }
  }, [workflowContext, currentComponents]);

  const handleComponentSelect = (suggestion: ComponentSuggestion) => {
    // Convert suggestion to actual component data
    const component = {
      id: `component-${Date.now()}`,
      type: suggestion.type,
      name: suggestion.name,
      props: suggestion.component_config.default_props,
      metadata: {
        ai_suggested: true,
        suggestion_id: suggestion.id,
        confidence: suggestion.confidence
      }
    };

    onComponentAdd(component);
  };

  const handleWorkflowOptimize = (suggestions: ComponentSuggestion[]) => {
    // Auto-add top 3 highest confidence suggestions
    const topSuggestions = suggestions
      .filter(s => s.confidence > 0.8)
      .slice(0, 3);

    topSuggestions.forEach(suggestion => {
      handleComponentSelect(suggestion);
    });
  };

  const openMagicConnectorForComponent = (component: any) => {
    setSelectedComponent(component);
    setShowMagicConnector(true);
  };

  const getInsightIcon = (type: IntelligenceInsight['type']) => {
    switch (type) {
      case 'component_gap':
        return <Target className="h-4 w-4" />;
      case 'workflow_optimization':
        return <Workflow className="h-4 w-4" />;
      case 'conversion_opportunity':
        return <TrendingUp className="h-4 w-4" />;
      case 'automation_potential':
        return <Zap className="h-4 w-4" />;
      default:
        return <Lightbulb className="h-4 w-4" />;
    }
  };

  const getInsightColor = (impact: IntelligenceInsight['impact']) => {
    switch (impact) {
      case 'high':
        return 'text-red-600 bg-red-50 border-red-200';
      case 'medium':
        return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      case 'low':
        return 'text-green-600 bg-green-50 border-green-200';
      default:
        return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const renderInsightCard = (insight: IntelligenceInsight, index: number) => (
    <Card key={index} className="hover:shadow-md transition-shadow">
      <CardContent className="p-4">
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3">
            <div className={cn(
              "p-2 rounded-lg",
              getInsightColor(insight.impact)
            )}>
              {getInsightIcon(insight.type)}
            </div>
            <div className="flex-1">
              <h4 className="font-medium">{insight.title}</h4>
              <p className="text-sm text-gray-600 mt-1">{insight.description}</p>
              <div className="flex items-center gap-2 mt-2">
                <Badge variant="outline" className={`text-xs ${getInsightColor(insight.impact)}`}>
                  {insight.impact} impact
                </Badge>
                {insight.quick_fix_available && (
                  <Badge variant="secondary" className="text-xs">
                    Quick fix available
                  </Badge>
                )}
              </div>
            </div>
          </div>
          {insight.action_required && (
            <Button size="sm" variant="outline">
              Take Action
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  );

  const renderOverview = () => (
    <div className="space-y-6">
      {/* Workflow Health Score */}
      <Card className="border-l-4 border-l-blue-500">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BarChart3 className="h-5 w-5 text-blue-600" />
            Workflow Intelligence Overview
          </CardTitle>
          <CardDescription>
            AI analysis of your workflow completeness and optimization opportunities
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center p-4 bg-blue-50 rounded-lg">
              <div className="text-2xl font-bold text-blue-600">{currentComponents.length}</div>
              <div className="text-sm text-blue-700">Active Components</div>
            </div>
            <div className="text-center p-4 bg-green-50 rounded-lg">
              <div className="text-2xl font-bold text-green-600">
                {insights.filter(i => i.quick_fix_available).length}
              </div>
              <div className="text-sm text-green-700">Quick Wins Available</div>
            </div>
            <div className="text-center p-4 bg-purple-50 rounded-lg">
              <div className="text-2xl font-bold text-purple-600">
                {insights.filter(i => i.impact === 'high').length}
              </div>
              <div className="text-sm text-purple-700">High Impact Opportunities</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Intelligence Insights */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold">Intelligence Insights</h3>
          {isAnalyzing && (
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600"></div>
              Analyzing...
            </div>
          )}
        </div>

        {insights.length > 0 ? (
          <div className="space-y-3">
            {insights.map(renderInsightCard)}
          </div>
        ) : (
          <Card>
            <CardContent className="p-8 text-center">
              <Brain className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h4 className="font-medium">No Insights Available</h4>
              <p className="text-sm text-gray-600">
                {isAnalyzing ? 'Analyzing your workflow...' : 'Your workflow appears to be well optimized.'}
              </p>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Quick Actions */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-purple-600" />
            Quick Actions
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <Button 
              variant="outline" 
              className="gap-2 h-12"
              onClick={() => setActiveTab('suggestions')}
            >
              <Target className="h-4 w-4" />
              View Component Suggestions
            </Button>
            <Button 
              variant="outline" 
              className="gap-2 h-12"
              onClick={() => setActiveTab('magic-connector')}
            >
              <Zap className="h-4 w-4" />
              Auto-Connect Components
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );

  const renderMagicConnectorTab = () => (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Zap className="h-5 w-5 text-purple-600" />
            Magic Connector
          </CardTitle>
          <CardDescription>
            AI-powered component analysis and automatic workflow connection
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {currentComponents.map((component, index) => (
                <Card key={index} className="hover:shadow-md transition-shadow cursor-pointer"
                      onClick={() => openMagicConnectorForComponent(component)}>
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="font-medium">{component.name || component.type}</h4>
                        <p className="text-sm text-gray-600">Type: {component.type}</p>
                      </div>
                      <Button size="sm" variant="outline">
                        <Sparkles className="h-3 w-3 mr-1" />
                        Analyze
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {currentComponents.length === 0 && (
              <div className="text-center py-8">
                <Target className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <h4 className="font-medium">No Components Yet</h4>
                <p className="text-sm text-gray-600">
                  Add components to your workflow to see Magic Connector suggestions.
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-3 bg-gradient-to-r from-blue-500 via-purple-600 to-indigo-600 text-white rounded-lg">
            <Brain className="h-6 w-6" />
          </div>
          <div>
            <h1 className="text-2xl font-bold">Workflow Intelligence Hub</h1>
            <p className="text-gray-600">
              AI-powered workflow analysis and optimization recommendations
            </p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="overview" className="gap-2">
            <BarChart3 className="h-4 w-4" />
            Overview
          </TabsTrigger>
          <TabsTrigger value="suggestions" className="gap-2">
            <Target className="h-4 w-4" />
            Component Suggestions
          </TabsTrigger>
          <TabsTrigger value="magic-connector" className="gap-2">
            <Zap className="h-4 w-4" />
            Magic Connector
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="mt-6">
          {renderOverview()}
        </TabsContent>

        <TabsContent value="suggestions" className="mt-6">
          {workflowContext ? (
            <SmartComponentSuggestions
              workflowContext={workflowContext}
              onComponentSelect={handleComponentSelect}
              onWorkflowOptimize={handleWorkflowOptimize}
              maxSuggestions={8}
              showAnalysis={true}
            />
          ) : (
            <Card>
              <CardContent className="p-8 text-center">
                <Settings className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <h3 className="font-medium">Business Context Required</h3>
                <p className="text-sm text-gray-600">
                  Please provide business context to generate component suggestions.
                </p>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="magic-connector" className="mt-6">
          {renderMagicConnectorTab()}
        </TabsContent>
      </Tabs>

      {/* Magic Connector Modal */}
      {showMagicConnector && selectedComponent && (
        <MagicConnector
          component={selectedComponent}
          onWorkflowConnect={onWorkflowConnect}
          onClose={() => setShowMagicConnector(false)}
          autoShow={true}
        />
      )}
    </div>
  );
};

export default WorkflowIntelligenceHub;

/**
 * WorkflowStatusOverlay Component - Mock for Testing
 * 
 * This is a mock component for testing purposes
 */

import React from 'react';

export interface WorkflowNodeData {
  id: string;
  status: 'pending' | 'running' | 'success' | 'failed';
  progress?: number;
  executionTime?: number;
  lastUpdated?: Date;
  errorMessage?: string;
  metadata?: Record<string, any>;
}

interface WorkflowStatusOverlayProps {
  node: WorkflowNodeData;
  showProgress?: boolean;
  showExecutionTime?: boolean;
  animate?: boolean;
  onErrorClick?: (node: WorkflowNodeData, error: string) => void;
  onClick?: () => void;
}

const WorkflowStatusOverlay: React.FC<WorkflowStatusOverlayProps> = ({
  node,
  showProgress = false,
  showExecutionTime = false,
  animate = false,
  onErrorClick,
  onClick
}) => {
  const handleClick = () => {
    if (node.status === 'failed' && onErrorClick && node.errorMessage) {
      onErrorClick(node, node.errorMessage);
    } else if (onClick) {
      onClick();
    }
  };

  const getStatusClass = () => {
    switch (node.status) {
      case 'running': return 'status-running';
      case 'success': return 'status-success';
      case 'failed': return 'status-failed';
      default: return 'status-pending';
    }
  };

  const getTitle = () => {
    let title = `Status: ${node.status}`;
    if (showProgress && node.progress) {
      title += `, Progress: ${node.progress}%`;
    }
    if (showExecutionTime && node.executionTime) {
      title += `, Execution Time: ${(node.executionTime / 1000).toFixed(1)}s`;
    }
    return title;
  };

  return (
    <button
      data-testid={`node-status-${node.id}`}
      className={`workflow-status-overlay ${getStatusClass()} ${animate ? 'shadow-lg' : ''}`}
      onClick={handleClick}
      aria-label={`Node ${node.id} ${node.status}`}
      title={getTitle()}
      tabIndex={0}
    >
      <div className="status-indicator" />
      {showProgress && node.progress && (
        <div data-testid={`progress-${node.id}`} className="progress">
          {node.progress}%
        </div>
      )}
    </button>
  );
};

export default WorkflowStatusOverlay;

'use client';

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Database, 
  TrendingUp, 
  DollarSign, 
  Zap, 
  HardDrive, 
  Clock,
  RefreshCw,
  Trash2,
  BarChart3,
  CheckCircle,
  AlertTriangle
} from 'lucide-react';

interface CacheStats {
  total_requests: number;
  cache_hits: number;
  cache_misses: number;
  hit_rate_percent: number;
  total_cost_saved: number;
  avg_response_time_ms: number;
  storage_usage_mb: number;
}

interface CacheEfficiencyReport {
  cache_performance: {
    hit_rate_percent: number;
    cost_efficiency_percent: number;
    total_cost_saved: number;
    estimated_without_cache: number;
  };
  usage_comparison: {
    actual_cost: number;
    requests_served_from_cache: number;
    requests_requiring_ai: number;
    cache_to_ai_ratio: number;
  };
  recommendations: string[];
}

interface CacheEfficiencyDashboardProps {
  className?: string;
}

export function CacheEfficiencyDashboard({ className = '' }: CacheEfficiencyDashboardProps) {
  const [stats, setStats] = useState<CacheStats | null>(null);
  const [report, setReport] = useState<CacheEfficiencyReport | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadCacheData();
  }, []);

  const loadCacheData = async () => {
    setIsLoading(true);
    setError(null);

    try {
      // Load cache stats and efficiency report in parallel
      const [statsResponse, reportResponse] = await Promise.all([
        fetch('/api/ai/cache-stats', {
          headers: {
            'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
          }
        }),
        fetch('/api/ai/cache-efficiency-report?days=30', {
          headers: {
            'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
          }
        })
      ]);

      if (statsResponse.ok) {
        const statsData = await statsResponse.json();
        if (statsData.cache_statistics?.stats) {
          setStats(statsData.cache_statistics.stats);
        }
      }

      if (reportResponse.ok) {
        const reportData = await reportResponse.json();
        if (reportData.report) {
          setReport(reportData.report);
        }
      }

      setLastUpdated(new Date());

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load cache data';
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const optimizeCache = async () => {
    setIsOptimizing(true);

    try {
      const response = await fetch('/api/ai/optimize-cache', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
        }
      });

      if (response.ok) {
        // Reload data after optimization
        await loadCacheData();
      } else {
        throw new Error('Cache optimization failed');
      }

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Cache optimization failed';
      setError(errorMessage);
    } finally {
      setIsOptimizing(false);
    }
  };

  const clearCache = async () => {
    if (!confirm('Are you sure you want to clear all cached data? This cannot be undone.')) {
      return;
    }

    try {
      const response = await fetch('/api/ai/cache', {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
        }
      });

      if (response.ok) {
        // Reload data after clearing
        await loadCacheData();
      } else {
        throw new Error('Cache clearing failed');
      }

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Cache clearing failed';
      setError(errorMessage);
    }
  };

  const getHitRateColor = (hitRate: number) => {
    if (hitRate >= 80) return 'text-green-600';
    if (hitRate >= 60) return 'text-blue-600';
    if (hitRate >= 40) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getHitRateBackground = (hitRate: number) => {
    if (hitRate >= 80) return 'bg-green-100';
    if (hitRate >= 60) return 'bg-blue-100';
    if (hitRate >= 40) return 'bg-yellow-100';
    return 'bg-red-100';
  };

  if (error) {
    return (
      <div className={`bg-white rounded-xl border border-gray-200 p-6 shadow-sm ${className}`}>
        <div className="flex items-center gap-3 mb-4">
          <Database className="w-5 h-5 text-red-500" />
          <h4 className="font-semibold text-gray-800">Cache Performance</h4>
        </div>
        <div className="text-center py-8">
          <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-3" />
          <p className="text-red-600 mb-4">{error}</p>
          <button
            onClick={loadCacheData}
            className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
            <Database className="w-4 h-4 text-blue-600" />
          </div>
          <h4 className="font-semibold text-gray-800">Cache Performance Dashboard</h4>
        </div>

        <div className="flex items-center gap-2">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={loadCacheData}
            disabled={isLoading}
            className="p-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg transition-all disabled:opacity-50"
            title="Refresh data"
          >
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
          </motion.button>

          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={optimizeCache}
            disabled={isOptimizing}
            className="px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 transition-all flex items-center gap-2"
          >
            {isOptimizing ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                Optimizing...
              </>
            ) : (
              <>
                <Zap className="w-4 h-4" />
                Optimize
              </>
            )}
          </motion.button>

          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={clearCache}
            className="p-2 bg-red-100 hover:bg-red-200 text-red-600 rounded-lg transition-all"
            title="Clear cache"
          >
            <Trash2 className="w-4 h-4" />
          </motion.button>
        </div>
      </div>

      {lastUpdated && (
        <p className="text-sm text-gray-500">
          Last updated: {lastUpdated.toLocaleTimeString()}
        </p>
      )}

      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* Hit Rate */}
          <div className={`p-4 rounded-xl ${getHitRateBackground(stats.hit_rate_percent)}`}>
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-4 h-4 text-gray-600" />
              <span className="text-sm font-medium text-gray-700">Hit Rate</span>
            </div>
            <div className={`text-2xl font-bold ${getHitRateColor(stats.hit_rate_percent)}`}>
              {stats.hit_rate_percent.toFixed(1)}%
            </div>
            <p className="text-xs text-gray-600 mt-1">
              {stats.cache_hits} hits / {stats.total_requests} requests
            </p>
          </div>

          {/* Cost Saved */}
          <div className="p-4 bg-green-100 rounded-xl">
            <div className="flex items-center gap-2 mb-2">
              <DollarSign className="w-4 h-4 text-gray-600" />
              <span className="text-sm font-medium text-gray-700">Cost Saved</span>
            </div>
            <div className="text-2xl font-bold text-green-600">
              ${stats.total_cost_saved.toFixed(4)}
            </div>
            <p className="text-xs text-gray-600 mt-1">
              Total savings
            </p>
          </div>

          {/* Response Time */}
          <div className="p-4 bg-purple-100 rounded-xl">
            <div className="flex items-center gap-2 mb-2">
              <Clock className="w-4 h-4 text-gray-600" />
              <span className="text-sm font-medium text-gray-700">Avg Response</span>
            </div>
            <div className="text-2xl font-bold text-purple-600">
              {stats.avg_response_time_ms.toFixed(0)}ms
            </div>
            <p className="text-xs text-gray-600 mt-1">
              From cache
            </p>
          </div>

          {/* Storage Usage */}
          <div className="p-4 bg-orange-100 rounded-xl">
            <div className="flex items-center gap-2 mb-2">
              <HardDrive className="w-4 h-4 text-gray-600" />
              <span className="text-sm font-medium text-gray-700">Storage</span>
            </div>
            <div className="text-2xl font-bold text-orange-600">
              {stats.storage_usage_mb.toFixed(1)}MB
            </div>
            <p className="text-xs text-gray-600 mt-1">
              Cache size
            </p>
          </div>
        </div>
      )}

      {report && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Performance Analysis */}
          <div className="bg-white border border-gray-200 rounded-xl p-6">
            <div className="flex items-center gap-3 mb-4">
              <BarChart3 className="w-5 h-5 text-blue-500" />
              <h5 className="font-semibold text-gray-800">Performance Analysis</h5>
            </div>

            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-gray-600">Cost Efficiency:</span>
                <span className="font-semibold text-green-600">
                  {report.cache_performance.cost_efficiency_percent.toFixed(1)}%
                </span>
              </div>

              <div className="flex justify-between items-center">
                <span className="text-gray-600">Without Cache:</span>
                <span className="font-semibold text-gray-800">
                  ${report.cache_performance.estimated_without_cache.toFixed(4)}
                </span>
              </div>

              <div className="flex justify-between items-center">
                <span className="text-gray-600">Actual Cost:</span>
                <span className="font-semibold text-gray-800">
                  ${report.usage_comparison.actual_cost.toFixed(4)}
                </span>
              </div>

              <div className="flex justify-between items-center">
                <span className="text-gray-600">Cache vs AI Ratio:</span>
                <span className="font-semibold text-blue-600">
                  {report.usage_comparison.cache_to_ai_ratio.toFixed(1)}:1
                </span>
              </div>
            </div>
          </div>

          {/* Recommendations */}
          <div className="bg-white border border-gray-200 rounded-xl p-6">
            <div className="flex items-center gap-3 mb-4">
              <CheckCircle className="w-5 h-5 text-green-500" />
              <h5 className="font-semibold text-gray-800">Recommendations</h5>
            </div>

            <div className="space-y-3">
              {report.recommendations.map((recommendation, index) => (
                <div key={index} className="flex items-start gap-2">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full mt-2 flex-shrink-0" />
                  <p className="text-sm text-gray-600">{recommendation}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {isLoading && !stats && (
        <div className="bg-white border border-gray-200 rounded-xl p-12 text-center">
          <div className="w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-gray-600">Loading cache performance data...</p>
        </div>
      )}

      {!isLoading && !stats && !error && (
        <div className="bg-white border border-gray-200 rounded-xl p-12 text-center">
          <Database className="w-12 h-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 mb-4">No cache data available</p>
          <p className="text-sm text-gray-500">
            Generate some components to see cache performance metrics
          </p>
        </div>
      )}
    </div>
  );
}

/**
 * CollaborationChat Component
 * Team chat for collaborative editing
 */

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  MessageSquare, 
  Send, 
  X, 
  Minimize2, 
  Maximize2,
  Clock,
  AtSign
} from 'lucide-react';
import { ChatMessage, CollaborationUser } from '@/types/collaboration';

interface CollaborationChatProps {
  messages: ChatMessage[];
  currentUser: CollaborationUser | null;
  onSendMessage: (message: string, componentId?: string) => void;
  isOpen: boolean;
  onToggle: () => void;
  onClose: () => void;
  className?: string;
}

interface ChatMessageProps {
  message: ChatMessage;
  currentUserId: string | null;
  onMentionClick?: (userId: string) => void;
}

const formatTimestamp = (timestamp: Date): string => {
  const now = new Date();
  const diff = now.getTime() - timestamp.getTime();
  const minutes = Math.floor(diff / 60000);
  const hours = Math.floor(diff / 3600000);
  const days = Math.floor(diff / 86400000);

  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days < 7) return `${days}d ago`;

  return timestamp.toLocaleDateString();
};

const ChatMessageItem: React.FC<ChatMessageProps> = ({ 
  message, 
  currentUserId,
  onMentionClick 
}) => {
  const isOwnMessage = message.userId === currentUserId;
  const isSystemMessage = message.type === 'system';

  if (isSystemMessage) {
    return (
      <div className="flex justify-center my-2">
        <div className="px-3 py-1 bg-gray-100 rounded-full text-xs text-gray-600">
          {message.message}
        </div>
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className={`flex ${isOwnMessage ? 'justify-end' : 'justify-start'} mb-3`}
    >
      <div className={`max-w-xs ${isOwnMessage ? 'order-2' : 'order-1'}`}>
        {/* User info */}
        {!isOwnMessage && (
          <div className="flex items-center gap-2 mb-1">
            <div
              className="w-4 h-4 rounded-full border border-white"
              style={{ backgroundColor: message.user.color }}
            />
            <span className="text-xs font-medium text-gray-700">
              {message.user.name}
            </span>
            <span className="text-xs text-gray-400">
              {formatTimestamp(message.timestamp)}
            </span>
          </div>
        )}

        {/* Message bubble */}
        <div
          className={`px-3 py-2 rounded-lg ${
            isOwnMessage
              ? 'bg-blue-500 text-white'
              : 'bg-gray-100 text-gray-900'
          }`}
        >
          <div className="text-sm whitespace-pre-wrap break-words">
            {message.message}
          </div>

          {isOwnMessage && (
            <div className="text-xs opacity-75 mt-1">
              {formatTimestamp(message.timestamp)}
            </div>
          )}
        </div>

        {/* Component mention indicator */}
        {message.type === 'component_mention' && message.componentId && (
          <div className="text-xs text-blue-600 mt-1 flex items-center gap-1">
            <AtSign className="w-3 h-3" />
            Referenced component
          </div>
        )}
      </div>
    </motion.div>
  );
};

const ChatInput: React.FC<{
  onSendMessage: (message: string) => void;
  disabled?: boolean;
  placeholder?: string;
}> = ({ onSendMessage, disabled = false, placeholder = "Type a message..." }) => {
  const [message, setMessage] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (message.trim() && !disabled) {
      onSendMessage(message.trim());
      setMessage('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="flex gap-2 p-3 border-t border-gray-200">
      <input
        ref={inputRef}
        type="text"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        disabled={disabled}
        className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
      />
      <button
        type="submit"
        disabled={!message.trim() || disabled}
        className="px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors"
      >
        <Send className="w-4 h-4" />
      </button>
    </form>
  );
};

export const CollaborationChat: React.FC<CollaborationChatProps> = ({
  messages,
  currentUser,
  onSendMessage,
  isOpen,
  onToggle,
  onClose,
  className = '',
}) => {
  const [isMinimized, setIsMinimized] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    if (messagesEndRef.current && !isMinimized) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isMinimized]);

  // Mark unread messages as read when chat is opened
  useEffect(() => {
    if (isOpen && !isMinimized) {
      // TODO: Mark messages as read
    }
  }, [isOpen, isMinimized]);

  if (!isOpen) return null;

  const unreadCount = messages.filter(m => 
    m.userId !== currentUser?.id && 
    m.timestamp > (currentUser?.lastSeen || new Date(0))
  ).length;

  return (
    <motion.div
      initial={{ opacity: 0, x: 300 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 300 }}
      className={`fixed right-4 bottom-4 w-80 bg-white rounded-lg shadow-xl border border-gray-200 z-50 ${className}`}
    >
      {/* Chat header */}
      <div className="flex items-center justify-between p-3 border-b border-gray-200 bg-gray-50 rounded-t-lg">
        <div className="flex items-center gap-2">
          <MessageSquare className="w-4 h-4 text-gray-600" />
          <span className="font-medium text-gray-900">Team Chat</span>
          {unreadCount > 0 && !isMinimized && (
            <span className="px-2 py-1 bg-red-500 text-white text-xs rounded-full">
              {unreadCount}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1">
          <button
            onClick={() => setIsMinimized(!isMinimized)}
            className="p-1 rounded hover:bg-gray-200 transition-colors"
            title={isMinimized ? 'Maximize' : 'Minimize'}
          >
            {isMinimized ? (
              <Maximize2 className="w-4 h-4 text-gray-600" />
            ) : (
              <Minimize2 className="w-4 h-4 text-gray-600" />
            )}
          </button>

          <button
            onClick={onClose}
            className="p-1 rounded hover:bg-gray-200 transition-colors"
            title="Close chat"
          >
            <X className="w-4 h-4 text-gray-600" />
          </button>
        </div>
      </div>

      {!isMinimized && (
        <>
          {/* Messages container */}
          <div
            ref={messagesContainerRef}
            className="h-64 overflow-y-auto p-3 bg-white"
          >
            {messages.length === 0 ? (
              <div className="flex items-center justify-center h-full text-gray-500 text-sm">
                <div className="text-center">
                  <MessageSquare className="w-8 h-8 mx-auto mb-2 opacity-50" />
                  <p>No messages yet</p>
                  <p className="text-xs mt-1">Start a conversation with your team</p>
                </div>
              </div>
            ) : (
              <>
                <AnimatePresence>
                  {messages.map((message) => (
                    <ChatMessageItem
                      key={message.id}
                      message={message}
                      currentUserId={currentUser?.id || null}
                    />
                  ))}
                </AnimatePresence>
                <div ref={messagesEndRef} />
              </>
            )}
          </div>

          {/* Message input */}
          <ChatInput
            onSendMessage={onSendMessage}
            disabled={!currentUser}
            placeholder={
              currentUser 
                ? "Type a message..." 
                : "Connect to start chatting..."
            }
          />
        </>
      )}

      {/* Minimized state */}
      {isMinimized && unreadCount > 0 && (
        <div className="p-2 text-center bg-blue-50 rounded-b-lg">
          <span className="text-sm text-blue-600">
            {unreadCount} new message{unreadCount !== 1 ? 's' : ''}
          </span>
        </div>
      )}
    </motion.div>
  );
};

// Chat toggle button for when chat is closed
export const ChatToggleButton: React.FC<{
  onClick: () => void;
  unreadCount?: number;
  className?: string;
}> = ({ onClick, unreadCount = 0, className = '' }) => {
  return (
    <motion.button
      initial={{ scale: 0 }}
      animate={{ scale: 1 }}
      whileHover={{ scale: 1.1 }}
      whileTap={{ scale: 0.9 }}
      onClick={onClick}
      className={`fixed bottom-4 right-4 w-12 h-12 bg-blue-500 text-white rounded-full shadow-lg hover:bg-blue-600 transition-colors z-40 ${className}`}
      title="Open team chat"
    >
      <MessageSquare className="w-6 h-6 mx-auto" />

      {unreadCount > 0 && (
        <div className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
          {unreadCount > 9 ? '9+' : unreadCount}
        </div>
      )}
    </motion.button>
  );
};

/**
 * CollaborationProvider Component
 * Main provider that integrates all collaboration features
 */

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { useCollaboration } from '@/hooks/useCollaboration';
import { useCursorTracking } from './UserCursors';
import { useComponentLocking } from './ComponentLocks';
import { PresenceBar } from './PresenceBar';
import { UserCursors } from './UserCursors';
import { ComponentLocks } from './ComponentLocks';
import { CollaborationChat, ChatToggleButton } from './CollaborationChat';
import { SyncPreferences } from '@/types/collaboration';

interface CollaborationProviderProps {
  projectId: string;
  userId: string;
  userName: string;
  userEmail: string;
  authToken: string;
  children: React.ReactNode;
  canvasRef?: React.RefObject<HTMLElement>;
  className?: string;
  syncPreferences?: Partial<SyncPreferences>;
}

export const CollaborationProvider: React.FC<CollaborationProviderProps> = ({
  projectId,
  userId,
  userName,
  userEmail,
  authToken,
  children,
  canvasRef,
  className = '',
}) => {
  // Builder store state
  const { 
    components, 
    selectedComponentId, 
    zoom,
    selectComponent: selectComponentInStore,
  } = useBuilderStore();

  // Collaboration state and actions
  const collaboration = useCollaboration({
    projectId,
    userId,
    userName,
    userEmail,
    authToken,
    autoConnect: true,
  });

  // Local UI state
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [showPresenceBar, setShowPresenceBar] = useState(true);
  const internalCanvasRef = useRef<HTMLDivElement>(null);

  // Use provided canvasRef or internal one
  const activeCanvasRef = canvasRef || internalCanvasRef;

  // Component locking for selected component
  const componentLocking = useComponentLocking(
    selectedComponentId,
    collaboration.isComponentLocked,
    collaboration.lockComponent,
    collaboration.unlockComponent,
    collaboration.syncPreferences.enableComponentLocking
  );

  // Cursor tracking
  useCursorTracking(
    activeCanvasRef,
    collaboration.updateCursor,
    collaboration.syncPreferences.enableCursorSharing && collaboration.isConnected,
    zoom
  );

  // Handle component selection with locking
  const handleComponentSelect = (componentId: string | null) => {
    // Unlock previous component
    if (selectedComponentId) {
      componentLocking.stopEditing();
    }

    // Select new component
    collaboration.selectComponent(componentId);

    // Lock new component if it's not locked by others
    if (componentId && !collaboration.isComponentLocked(componentId)) {
      componentLocking.startEditing('editing');
    }
  };

  // Auto-lock component when starting drag/resize operations
  useEffect(() => {
    const handleDragStart = () => {
      if (selectedComponentId && !collaboration.isComponentLocked(selectedComponentId)) {
        componentLocking.startEditing('moving');
      }
    };

    const handleResizeStart = () => {
      if (selectedComponentId && !collaboration.isComponentLocked(selectedComponentId)) {
        componentLocking.startEditing('resizing');
      }
    };

    // Listen for drag/resize events from the builder
    // This would typically be integrated with your existing drag/drop system
    document.addEventListener('component-drag-start', handleDragStart);
    document.addEventListener('component-resize-start', handleResizeStart);

    return () => {
      document.removeEventListener('component-drag-start', handleDragStart);
      document.removeEventListener('component-resize-start', handleResizeStart);
    };
  }, [selectedComponentId, collaboration.isComponentLocked, componentLocking]);

  // Calculate unread messages count
  const unreadMessagesCount = collaboration.chatMessages.filter(m => 
    m.userId !== userId && 
    m.timestamp > (collaboration.currentUser?.lastSeen || new Date(0))
  ).length;

  // Handle chat toggle
  const handleChatToggle = () => {
    setIsChatOpen(!isChatOpen);
  };

  const handleChatClose = () => {
    setIsChatOpen(false);
  };

  // Render connection error state
  if (collaboration.error && !collaboration.error.recoverable) {
    return (
      <div className={`flex flex-col h-full ${className}`}>
        <div className="bg-red-50 border-l-4 border-red-400 p-4">
          <div className="flex">
            <div className="ml-3">
              <p className="text-sm text-red-700">
                <strong>Collaboration Error:</strong> {collaboration.error.message}
              </p>
              <button
                onClick={collaboration.reconnect}
                className="mt-2 text-sm text-red-600 underline hover:text-red-800"
              >
                Try reconnecting
              </button>
            </div>
          </div>
        </div>
        {children}
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-full relative ${className}`}>
      {/* Presence bar */}
      {showPresenceBar && (
        <PresenceBar
          activeUsers={collaboration.activeUsers}
          connectionStatus={collaboration.connectionStatus}
          isConnected={collaboration.isConnected}
        />
      )}

      {/* Main content area */}
      <div className="flex-1 relative overflow-hidden">
        {/* Canvas wrapper with internal ref if none provided */}
        {!canvasRef ? (
          <div ref={internalCanvasRef} className="w-full h-full">
            {children}
          </div>
        ) : (
          children
        )}

        {/* Collaboration overlays */}
        {collaboration.isConnected && (
          <>
            {/* Component locks */}
            <ComponentLocks
              componentLocks={collaboration.componentLocks}
              activeUsers={collaboration.activeUsers}
              components={components}
              currentUserId={userId}
              zoom={zoom}
              className="absolute inset-0 pointer-events-none"
            />

            {/* User cursors */}
            <UserCursors
              userCursors={collaboration.userCursors}
              activeUsers={collaboration.activeUsers}
              canvasRef={activeCanvasRef}
              zoom={zoom}
            />
          </>
        )}
      </div>

      {/* Chat system */}
      {collaboration.isConnected && (
        <>
          <CollaborationChat
            messages={collaboration.chatMessages}
            currentUser={collaboration.currentUser}
            onSendMessage={collaboration.sendChatMessage}
            isOpen={isChatOpen}
            onToggle={handleChatToggle}
            onClose={handleChatClose}
          />

          {!isChatOpen && (
            <ChatToggleButton
              onClick={handleChatToggle}
              unreadCount={unreadMessagesCount}
            />
          )}
        </>
      )}

      {/* Connection status overlay for disconnected state */}
      {!collaboration.isConnected && collaboration.connectionStatus !== 'disconnected' && (
        <div className="absolute inset-0 bg-black bg-opacity-10 flex items-center justify-center pointer-events-none z-50">
          <div className="bg-white rounded-lg shadow-lg p-4 flex items-center gap-3">
            <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-blue-500"></div>
            <span className="text-gray-700">
              {collaboration.connectionStatus === 'connecting' && 'Connecting to collaboration...'}
              {collaboration.connectionStatus === 'reconnecting' && 'Reconnecting...'}
              {collaboration.connectionStatus === 'error' && 'Connection failed. Retrying...'}
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

// Enhanced version with additional customization options
export interface CollaborationConfigProps extends CollaborationProviderProps {
  enablePresenceBar?: boolean;
  enableChat?: boolean;
  enableCursorSharing?: boolean;
  enableComponentLocking?: boolean;
  customCursorColors?: Record<string, string>;
  onUserJoin?: (user: any) => void;
  onUserLeave?: (userId: string) => void;
  onComponentLock?: (componentId: string, userId: string) => void;
  onComponentUnlock?: (componentId: string) => void;
}

export const CollaborationProviderWithConfig: React.FC<CollaborationConfigProps> = ({
  enablePresenceBar = true,
  enableChat = true,
  enableCursorSharing = true,
  enableComponentLocking = true,
  onUserJoin,
  onUserLeave,
  onComponentLock,
  onComponentUnlock,
  ...props
}) => {
  // Apply configuration overrides
  const configuredProps = {
    ...props,
    syncPreferences: {
      enableRealTimeSync: true,
      enableCursorSharing,
      enableComponentLocking,
      enableChatNotifications: enableChat,
      autoSaveInterval: 5000,
      conflictResolutionStrategy: 'auto' as const,
      ...props.syncPreferences,
    },
  };

  return <CollaborationProvider {...configuredProps} />;
};

// Hook for accessing collaboration context in child components
export const useCollaborationContext = () => {
  // This would typically use React Context to access collaboration state
  // For now, we'll return the hook directly
  return {
    // These would be provided by context
    isConnected: false,
    activeUsers: [],
    currentUser: null,
    sendMessage: () => {},
    lockComponent: () => {},
    unlockComponent: () => {},
  };
};

/**
 * ComponentLocks Component
 * Visual indicators for components being edited by other users
 */

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, Edit3, Move, MousePointer2 } from 'lucide-react';
import { ComponentLock, CollaborationUser } from '@/types/collaboration';
import { ComponentData } from '@/types/builder';

interface ComponentLocksProps {
  componentLocks: Map<string, ComponentLock>;
  activeUsers: CollaborationUser[];
  components: ComponentData[];
  currentUserId: string;
  zoom?: number;
  className?: string;
}

interface LockIndicatorProps {
  lock: ComponentLock;
  user: CollaborationUser;
  component: ComponentData;
  zoom: number;
}

const LockIcon: React.FC<{ lockType: ComponentLock['lockType']; size?: number }> = ({ 
  lockType, 
  size = 16 
}) => {
  const iconProps = { size, className: "text-white drop-shadow-sm" };

  switch (lockType) {
    case 'editing':
      return <Edit3 {...iconProps} />;
    case 'moving':
      return <Move {...iconProps} />;
    case 'resizing':
      return <MousePointer2 {...iconProps} />;
    default:
      return <Lock {...iconProps} />;
  }
};

const LockIndicator: React.FC<LockIndicatorProps> = ({ 
  lock, 
  user, 
  component, 
  zoom 
}) => {
  const isExpired = new Date() > lock.expiresAt;

  if (isExpired) return null;

  const getLockTypeText = () => {
    switch (lock.lockType) {
      case 'editing':
        return 'editing';
      case 'moving':
        return 'moving';
      case 'resizing':
        return 'resizing';
      default:
        return 'locked';
    }
  };

  const timeRemaining = Math.max(0, lock.expiresAt.getTime() - Date.now());
  const timeRemainingSeconds = Math.ceil(timeRemaining / 1000);

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.8 }}
      className="absolute pointer-events-none z-40"
      style={{
        left: (component.position.x * zoom) - 2,
        top: (component.position.y * zoom) - 2,
        width: (component.size.width * zoom) + 4,
        height: (component.size.height * zoom) + 4,
      }}
    >
      {/* Lock border */}
      <div
        className="absolute inset-0 border-2 border-dashed rounded-md"
        style={{ 
          borderColor: user.color,
          boxShadow: `0 0 0 1px rgba(255, 255, 255, 0.8)`,
        }}
      />

      {/* Lock indicator badge */}
      <div
        className="absolute -top-6 left-0 flex items-center gap-1 px-2 py-1 rounded-md text-white text-xs font-medium whitespace-nowrap shadow-lg"
        style={{ backgroundColor: user.color }}
      >
        <LockIcon lockType={lock.lockType} size={12} />
        <span>{user.name} is {getLockTypeText()}</span>
        {timeRemainingSeconds > 0 && (
          <span className="opacity-75">({timeRemainingSeconds}s)</span>
        )}
      </div>

      {/* Pulsing animation for active editing */}
      {lock.lockType === 'editing' && (
        <motion.div
          className="absolute inset-0 border-2 rounded-md"
          style={{ borderColor: user.color }}
          animate={{
            opacity: [0.3, 0.7, 0.3],
          }}
          transition={{
            duration: 2,
            repeat: Infinity,
            ease: "easeInOut",
          }}
        />
      )}
    </motion.div>
  );
};

const ComponentOverlay: React.FC<{
  component: ComponentData;
  lock: ComponentLock;
  user: CollaborationUser;
  zoom: number;
}> = ({ component, lock, user, zoom }) => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 0.1 }}
      exit={{ opacity: 0 }}
      className="absolute pointer-events-none z-30"
      style={{
        left: component.position.x * zoom,
        top: component.position.y * zoom,
        width: component.size.width * zoom,
        height: component.size.height * zoom,
        backgroundColor: user.color,
      }}
    />
  );
};

export const ComponentLocks: React.FC<ComponentLocksProps> = ({
  componentLocks,
  activeUsers,
  components,
  currentUserId,
  zoom = 1,
  className = '',
}) => {
  // Create user lookup map
  const userMap = new Map(activeUsers.map(user => [user.id, user]));

  // Create component lookup map
  const componentMap = new Map(components.map(comp => [comp.id, comp]));

  // Filter out expired locks and locks from current user
  const activeLocks = Array.from(componentLocks.entries())
    .filter(([, lock]) => {
      return lock.userId !== currentUserId && 
             new Date() <= lock.expiresAt;
    })
    .map(([componentId, lock]) => ({
      componentId,
      lock,
      user: userMap.get(lock.userId),
      component: componentMap.get(componentId),
    }))
    .filter(item => item.user && item.component);

  if (activeLocks.length === 0) return null;

  return (
    <div className={`absolute inset-0 pointer-events-none ${className}`}>
      <AnimatePresence>
        {activeLocks.map(({ componentId, lock, user, component }) => (
          <React.Fragment key={componentId}>
            {/* Component overlay */}
            <ComponentOverlay
              component={component!}
              lock={lock}
              user={user!}
              zoom={zoom}
            />

            {/* Lock indicator */}
            <LockIndicator
              lock={lock}
              user={user!}
              component={component!}
              zoom={zoom}
            />
          </React.Fragment>
        ))}
      </AnimatePresence>
    </div>
  );
};

// Hook for managing component locking
export const useComponentLocking = (
  componentId: string | null,
  isComponentLocked: (componentId: string) => boolean,
  lockComponent: (componentId: string, lockType: ComponentLock['lockType']) => void,
  unlockComponent: (componentId: string) => void,
  enabled: boolean = true
) => {
  const lockTimeoutRef = React.useRef<NodeJS.Timeout | null>(null);

  // Auto-lock component when starting to edit
  const startEditing = React.useCallback((lockType: ComponentLock['lockType'] = 'editing') => {
    if (!enabled || !componentId || isComponentLocked(componentId)) return false;

    lockComponent(componentId, lockType);

    // Set auto-unlock timer (25 seconds, gives 5 second buffer before server expires it)
    if (lockTimeoutRef.current) {
      clearTimeout(lockTimeoutRef.current);
    }

    lockTimeoutRef.current = setTimeout(() => {
      unlockComponent(componentId);
    }, 25000);

    return true;
  }, [enabled, componentId, isComponentLocked, lockComponent, unlockComponent]);

  // Stop editing and unlock component
  const stopEditing = React.useCallback(() => {
    if (!componentId) return;

    if (lockTimeoutRef.current) {
      clearTimeout(lockTimeoutRef.current);
      lockTimeoutRef.current = null;
    }

    unlockComponent(componentId);
  }, [componentId, unlockComponent]);

  // Extend lock if still editing
  const extendLock = React.useCallback((lockType: ComponentLock['lockType'] = 'editing') => {
    if (!enabled || !componentId) return;

    lockComponent(componentId, lockType);

    // Reset auto-unlock timer
    if (lockTimeoutRef.current) {
      clearTimeout(lockTimeoutRef.current);
    }

    lockTimeoutRef.current = setTimeout(() => {
      unlockComponent(componentId);
    }, 25000);
  }, [enabled, componentId, lockComponent, unlockComponent]);

  // Check if component is locked by another user
  const isLockedByOthers = React.useCallback(() => {
    return componentId ? isComponentLocked(componentId) : false;
  }, [componentId, isComponentLocked]);

  // Cleanup on unmount or component change
  React.useEffect(() => {
    return () => {
      if (lockTimeoutRef.current) {
        clearTimeout(lockTimeoutRef.current);
      }
      if (componentId) {
        unlockComponent(componentId);
      }
    };
  }, [componentId, unlockComponent]);

  return {
    startEditing,
    stopEditing,
    extendLock,
    isLockedByOthers,
  };
};

'use client';

import React from 'react';
import { Users } from 'lucide-react';

interface PresenceBarProps {
  activeUsers: any[];
  isConnected: boolean;
  connectionStatus: string;
  className?: string;
}

export function PresenceBar({ activeUsers, isConnected, connectionStatus, className = '' }: PresenceBarProps) {
  return (
    <div className={`bg-gray-900 border-b border-gray-800 px-4 py-2 ${className}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <div className={`flex items-center space-x-1 ${
            isConnected ? 'text-green-500' : 'text-red-500'
          }`}>
            <span className="text-sm font-medium">
              {isConnected ? 'Connected' : 'Disconnected'}
            </span>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2">
            <Users className="w-4 h-4 text-gray-400" />
            <span className="text-sm text-gray-300">
              {activeUsers.length} {activeUsers.length === 1 ? 'user' : 'users'} online
            </span>
          </div>

          <div className="flex items-center space-x-2">
            {activeUsers.map((user) => (
              <div 
                key={user.id}
                className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white"
                style={{ backgroundColor: user.color || '#3b82f6' }}
                title={user.name}
              >
                {user.name?.[0]?.toUpperCase() || 'U'}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export function FloatingPresenceIndicator({ activeUsers, isConnected, className = '' }: { 
  activeUsers: any[]; 
  isConnected: boolean; 
  className?: string;
}) {
  return (
    <div className={`fixed bottom-4 right-4 bg-gray-900 border border-gray-700 rounded-lg px-3 py-2 shadow-lg ${className}`}>
      <div className="flex items-center space-x-2">
        <div className={`w-2 h-2 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`} />
        <span className="text-sm text-white">
          {isConnected ? `${activeUsers.length} viewing` : 'Offline'}
        </span>

        <div className="flex -space-x-1">
          {activeUsers.slice(0, 3).map((user) => (
            <div
              key={user.id}
              className="w-6 h-6 rounded-full border-2 border-gray-900 flex items-center justify-center text-xs font-bold"
              style={{ backgroundColor: user.color || '#3b82f6' }}
              title={user.name}
            >
              {user.name?.[0]?.toUpperCase() || 'U'}
            </div>
          ))}
          {activeUsers.length > 3 && (
            <div className="w-6 h-6 rounded-full bg-gray-700 border-2 border-gray-900 flex items-center justify-center text-xs font-bold text-white">
              +{activeUsers.length - 3}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * UserCursors Component
 * Displays live cursors of other users in the canvas
 */

'use client';

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserCursor, CollaborationUser } from '@/types/collaboration';

interface UserCursorsProps {
  userCursors: Map<string, UserCursor>;
  activeUsers: CollaborationUser[];
  canvasRef: React.RefObject<HTMLElement>;
  zoom?: number;
  className?: string;
}

interface CursorPosition {
  x: number;
  y: number;
  visible: boolean;
  user: CollaborationUser;
  timestamp: Date;
}

const CursorIcon: React.FC<{ color: string; size?: number }> = ({ 
  color, 
  size = 20 
}) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none"
    className="drop-shadow-md"
  >
    <path
      d="M3 3L10.3 20.3L12.6 12.6L20.3 10.3L3 3Z"
      fill={color}
      stroke="white"
      strokeWidth="1"
      strokeLinejoin="round"
    />
  </svg>
);

const UserLabel: React.FC<{ 
  user: CollaborationUser; 
  position: { x: number; y: number };
  visible: boolean;
}> = ({ user, position, visible }) => {
  if (!visible) return null;

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.8 }}
      className="absolute pointer-events-none z-50"
      style={{
        left: position.x + 20,
        top: position.y - 10,
      }}
    >
      <div
        className="px-2 py-1 rounded-md text-white text-xs font-medium whitespace-nowrap shadow-lg"
        style={{ backgroundColor: user.color }}
      >
        {user.name}
      </div>
    </motion.div>
  );
};

const AnimatedCursor: React.FC<{
  cursor: UserCursor;
  user: CollaborationUser;
  canvasRect: DOMRect | null;
  zoom: number;
}> = ({ cursor, user, canvasRect, zoom }) => {
  const [showLabel, setShowLabel] = useState(true);
  const [lastMoveTime, setLastMoveTime] = useState(Date.now());

  // Calculate cursor position relative to viewport
  const getScreenPosition = () => {
    if (!canvasRect) return { x: 0, y: 0 };

    return {
      x: canvasRect.left + (cursor.position.x * zoom),
      y: canvasRect.top + (cursor.position.y * zoom),
    };
  };

  const screenPosition = getScreenPosition();

  // Hide label after 3 seconds of no movement
  useEffect(() => {
    setLastMoveTime(Date.now());
    setShowLabel(true);

    const timer = setTimeout(() => {
      setShowLabel(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, [cursor.position.x, cursor.position.y]);

  if (!cursor.visible || !canvasRect) return null;

  return (
    <>
      {/* Cursor */}
      <motion.div
        className="fixed pointer-events-none z-50"
        initial={false}
        animate={{
          x: screenPosition.x,
          y: screenPosition.y,
        }}
        transition={{
          type: "spring",
          damping: 30,
          stiffness: 800,
          mass: 0.1,
        }}
      >
        <CursorIcon color={user.color} />
      </motion.div>

      {/* User label */}
      <AnimatePresence>
        {showLabel && (
          <UserLabel
            user={user}
            position={screenPosition}
            visible={cursor.visible}
          />
        )}
      </AnimatePresence>
    </>
  );
};

export const UserCursors: React.FC<UserCursorsProps> = ({
  userCursors,
  activeUsers,
  canvasRef,
  zoom = 1,
  className = '',
}) => {
  const [canvasRect, setCanvasRect] = useState<DOMRect | null>(null);

  // Update canvas rect on resize or scroll
  useEffect(() => {
    const updateCanvasRect = () => {
      if (canvasRef.current) {
        setCanvasRect(canvasRef.current.getBoundingClientRect());
      }
    };

    updateCanvasRect();

    // Update on window resize and scroll
    const handleUpdate = () => {
      requestAnimationFrame(updateCanvasRect);
    };

    window.addEventListener('resize', handleUpdate);
    window.addEventListener('scroll', handleUpdate);

    // Also update when canvas element changes
    const resizeObserver = new ResizeObserver(handleUpdate);
    if (canvasRef.current) {
      resizeObserver.observe(canvasRef.current);
    }

    return () => {
      window.removeEventListener('resize', handleUpdate);
      window.removeEventListener('scroll', handleUpdate);
      resizeObserver.disconnect();
    };
  }, [canvasRef]);

  // Create map of users for quick lookup
  const userMap = new Map(activeUsers.map(user => [user.id, user]));

  return (
    <div className={className}>
      <AnimatePresence>
        {Array.from(userCursors.entries()).map(([userId, cursor]) => {
          const user = userMap.get(userId);
          if (!user) return null;

          return (
            <AnimatedCursor
              key={userId}
              cursor={cursor}
              user={user}
              canvasRect={canvasRect}
              zoom={zoom}
            />
          );
        })}
      </AnimatePresence>
    </div>
  );
};

// Hook for tracking and sending cursor position
export const useCursorTracking = (
  canvasRef: React.RefObject<HTMLElement>,
  onCursorUpdate: (position: { x: number; y: number }, visible: boolean) => void,
  enabled: boolean = true,
  zoom: number = 1
) => {
  useEffect(() => {
    if (!enabled || !canvasRef.current) return;

    const canvas = canvasRef.current;
    let isMouseInCanvas = false;
    let lastUpdateTime = 0;
    const updateThrottle = 50; // 20fps max

    const handleMouseMove = (event: MouseEvent) => {
      const now = Date.now();
      if (now - lastUpdateTime < updateThrottle) return;

      const rect = canvas.getBoundingClientRect();
      const position = {
        x: (event.clientX - rect.left) / zoom,
        y: (event.clientY - rect.top) / zoom,
      };

      onCursorUpdate(position, isMouseInCanvas);
      lastUpdateTime = now;
    };

    const handleMouseEnter = () => {
      isMouseInCanvas = true;
    };

    const handleMouseLeave = () => {
      isMouseInCanvas = false;
      onCursorUpdate({ x: 0, y: 0 }, false);
    };

    // Add event listeners
    canvas.addEventListener('mousemove', handleMouseMove);
    canvas.addEventListener('mouseenter', handleMouseEnter);
    canvas.addEventListener('mouseleave', handleMouseLeave);

    // Handle window blur/focus for cursor visibility
    const handleWindowBlur = () => {
      onCursorUpdate({ x: 0, y: 0 }, false);
    };

    window.addEventListener('blur', handleWindowBlur);

    return () => {
      canvas.removeEventListener('mousemove', handleMouseMove);
      canvas.removeEventListener('mouseenter', handleMouseEnter);
      canvas.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('blur', handleWindowBlur);
    };
  }, [enabled, canvasRef, onCursorUpdate, zoom]);
};

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Zap, Settings, Brain, Rocket, Star } from 'lucide-react';

interface ComplexitySliderProps {
  value: number;
  onChange: (value: number) => void;
  className?: string;
}

export function ComplexitySlider({ value, onChange, className = '' }: ComplexitySliderProps) {
  const complexityLevels = [
    {
      value: 1,
      label: 'Simple',
      description: 'Basic structure, minimal styling',
      icon: Zap,
      color: 'from-green-400 to-green-500',
      examples: ['Simple button', 'Basic text input', 'Static card'],
      features: ['Clean HTML structure', 'Basic CSS styling', 'Minimal JavaScript']
    },
    {
      value: 2,
      label: 'Basic',
      description: 'Interactive elements, hover effects',
      icon: Settings,
      color: 'from-blue-400 to-blue-500',
      examples: ['Button with hover', 'Form with labels', 'Card with image'],
      features: ['Hover animations', 'Basic interactivity', 'Improved styling']
    },
    {
      value: 3,
      label: 'Standard',
      description: 'Responsive design, multiple states',
      icon: Brain,
      color: 'from-purple-400 to-purple-500',
      examples: ['Modal dialog', 'Navigation menu', 'Form validation'],
      features: ['Responsive breakpoints', 'State management', 'Error handling']
    },
    {
      value: 4,
      label: 'Advanced',
      description: 'Complex logic, animations, APIs',
      icon: Rocket,
      color: 'from-orange-400 to-orange-500',
      examples: ['Data table', 'Multi-step form', 'File uploader'],
      features: ['Complex state logic', 'API integration', 'Advanced animations']
    },
    {
      value: 5,
      label: 'Expert',
      description: 'Enterprise features, optimizations',
      icon: Star,
      color: 'from-red-400 to-red-500',
      examples: ['Dashboard', 'Code editor', 'Real-time chat'],
      features: ['Performance optimization', 'Advanced patterns', 'Enterprise features']
    }
  ];

  const currentLevel = complexityLevels.find(level => level.value === value) || complexityLevels[2];

  return (
    <div className={`space-y-6 ${className}`}>
      <div>
        <h4 className="text-sm font-semibold text-gray-800 mb-2">Complexity Level</h4>
        <p className="text-xs text-gray-500">Higher complexity adds more features and interactivity</p>
      </div>

      {/* Visual Slider */}
      <div className="relative">
        <div className="flex justify-between mb-4">
          {complexityLevels.map((level) => {
            const IconComponent = level.icon;
            const isActive = value >= level.value;
            const isCurrent = value === level.value;

            return (
              <button
                key={level.value}
                onClick={() => onChange(level.value)}
                className={`
                  relative flex flex-col items-center p-2 rounded-lg transition-all duration-200
                  ${isCurrent ? 'transform scale-110' : 'hover:scale-105'}
                `}
              >
                <motion.div
                  className={`
                    w-10 h-10 rounded-full flex items-center justify-center mb-2 transition-all duration-200
                    ${isActive 
                      ? `bg-gradient-to-br ${level.color} text-white shadow-lg` 
                      : 'bg-gray-200 text-gray-400'
                    }
                  `}
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.95 }}
                >
                  <IconComponent className="w-5 h-5" />
                </motion.div>

                <span className={`
                  text-xs font-medium transition-colors
                  ${isActive ? 'text-gray-800' : 'text-gray-500'}
                `}>
                  {level.label}
                </span>

                {/* Connection Line */}
                {level.value < 5 && (
                  <div className={`
                    absolute top-7 left-full w-8 h-0.5 transition-colors duration-200
                    ${value > level.value ? 'bg-blue-500' : 'bg-gray-300'}
                  `} style={{ transform: 'translateX(-50%)' }} />
                )}
              </button>
            );
          })}
        </div>

        {/* Range Input (Hidden but functional) */}
        <input
          type="range"
          min={1}
          max={5}
          value={value}
          onChange={(e) => onChange(parseInt(e.target.value))}
          className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer opacity-0 absolute top-0"
        />
      </div>

      {/* Current Level Details */}
      <motion.div
        key={value}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
        className={`
          p-4 rounded-xl border-2 border-gray-200
          bg-gradient-to-br ${currentLevel.color} bg-opacity-5
        `}
      >
        <div className="flex items-center gap-3 mb-3">
          <div className={`
            w-8 h-8 rounded-lg flex items-center justify-center
            bg-gradient-to-br ${currentLevel.color} text-white
          `}>
            <currentLevel.icon className="w-4 h-4" />
          </div>
          <div>
            <h5 className="font-semibold text-gray-800">{currentLevel.label} Complexity</h5>
            <p className="text-sm text-gray-600">{currentLevel.description}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <h6 className="text-sm font-medium text-gray-700 mb-2">Features included:</h6>
            <ul className="space-y-1">
              {currentLevel.features.map((feature, index) => (
                <li key={index} className="flex items-center gap-2 text-sm text-gray-600">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full" />
                  {feature}
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h6 className="text-sm font-medium text-gray-700 mb-2">Example components:</h6>
            <div className="flex flex-wrap gap-1">
              {currentLevel.examples.map((example, index) => (
                <span
                  key={index}
                  className="px-2 py-1 bg-gray-100 text-gray-700 text-xs rounded-md"
                >
                  {example}
                </span>
              ))}
            </div>
          </div>
        </div>

        {/* Cost Impact */}
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-600">Estimated generation cost:</span>
          <span className="font-medium text-gray-800">
            ${(0.0001 * value * 2).toFixed(6)}
          </span>
        </div>
      </motion.div>

      {/* Tips */}
      <div className="bg-gray-50 rounded-lg p-3">
        <h6 className="text-sm font-medium text-gray-700 mb-2">💡 Tips for better results:</h6>
        <ul className="text-xs text-gray-600 space-y-1">
          {value <= 2 && (
            <>
              <li>• Perfect for prototyping and quick mockups</li>
              <li>• Ideal when you need fast turnaround times</li>
            </>
          )}
          {value === 3 && (
            <>
              <li>• Great balance of features and simplicity</li>
              <li>• Includes responsive design and basic interactions</li>
            </>
          )}
          {value >= 4 && (
            <>
              <li>• Suitable for production applications</li>
              <li>• Includes advanced patterns and optimizations</li>
              <li>• May require additional customization for specific needs</li>
            </>
          )}
        </ul>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Editor } from '@monaco-editor/react';
import { 
  Play, 
  Pause, 
  RotateCcw, 
  Settings, 
  Maximize2, 
  Minimize2,
  Smartphone,
  Tablet,
  Monitor,
  Eye,
  EyeOff,
  RefreshCw,
  Sparkles,
  Wand2,
  Palette,
  Zap,
  Lightbulb,
  CheckCircle,
  X,
  Bot,
  User,
  Copy,
  History,
  Undo,
  Redo,
  Send
} from 'lucide-react';
import { useBuilderStore } from '@/store/builderStore';
