            <button
              key={filter}
              onClick={() => setSelectedFilter(filter)}
              className={`px-6 py-3 rounded-lg text-sm font-medium transition-all duration-200 ${
                selectedFilter === filter
                  ? 'bg-gradient-to-r from-yellow-400 to-yellow-500 text-black shadow-lg shadow-yellow-400/30'
                  : `${luxuryTheme.colors.text.secondary} hover:${luxuryTheme.colors.text.accent} hover:bg-yellow-400/10`
              }`}
            >
              {filter.charAt(0).toUpperCase() + filter.slice(1)}
              <span className={`ml-2 text-xs px-2 py-1 rounded-full ${
                selectedFilter === filter
                  ? 'bg-black/20 text-black'
                  : 'bg-gray-700 text-gray-300'
              }`}>
                {filter === 'all' ? projects.length : projects.filter(p => p.status === filter).length}
              </span>
            </button>
          ))}
        </div>

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map((project, index) => (
            <motion.div
              key={project.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <Card className={`${luxuryTheme.components.dashboard.cardHover} group cursor-pointer`}>
                <CardHeader>
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <CardTitle className={`text-lg line-clamp-1 ${luxuryTheme.colors.text.primary} group-hover:${luxuryTheme.colors.text.accent} transition-colors`}>
                        {project.name}
                      </CardTitle>
                      <p className={`text-sm mt-1 line-clamp-2 ${luxuryTheme.colors.text.secondary}`}>
                        {project.description}
                      </p>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(project.status)}`}>
                      {project.status}
                    </span>
                  </div>
                </CardHeader>

                <CardContent>
                  <div className="space-y-4">
                    {/* Template & URL */}
                    <div className="space-y-2">
                      <p className={`text-xs ${luxuryTheme.colors.text.tertiary}`}>
                        Template: {project.template}
                      </p>
                      {project.url && (
                        <div className="flex items-center space-x-2">
                          <Globe className={`w-4 h-4 ${luxuryTheme.colors.text.tertiary}`} />
                          <a 
                            href={project.url} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className={`text-sm ${luxuryTheme.colors.text.accent} hover:${luxuryTheme.colors.text.accentHover} truncate transition-colors`}
                          >
                            {project.url}
                          </a>
                          <ExternalLink className={`w-3 h-3 ${luxuryTheme.colors.text.tertiary}`} />
                        </div>
                      )}
                    </div>

                    {/* Stats */}
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <p className={luxuryTheme.colors.text.tertiary}>Views</p>
                        <p className={`font-semibold ${luxuryTheme.colors.text.primary}`}>
                          {project.views.toLocaleString()}
                        </p>
                      </div>
                      <div>
                        <p className={luxuryTheme.colors.text.tertiary}>Conversions</p>
                        <p className={`font-semibold ${luxuryTheme.colors.text.primary}`}>
                          {project.conversions}
                        </p>
                      </div>
                    </div>

                    {/* Dates */}
                    <div className={`text-xs ${luxuryTheme.colors.text.tertiary}`}>
                      <p>Created: {project.createdAt.toLocaleDateString()}</p>
                      <p>Updated: {project.updatedAt.toLocaleDateString()}</p>
                    </div>

                    {/* Actions */}
                    <div className="flex space-x-2 pt-2">
                      <Button
                        size="sm"
                        onClick={() => handleEditProject(project.id)}
                        className={`flex-1 ${componentStyles.button.primary}`}
                      >
                        <Edit className="w-3 h-3 mr-1" />
                        Edit
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleDuplicateProject(project)}
                        className={componentStyles.button.ghost}
                      >
                        <Copy className="w-3 h-3" />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleDeleteProject(project.id)}
                        className={`${componentStyles.button.ghost} hover:text-red-400 hover:border-red-400`}
                      >
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>

        {/* Luxury Empty State */}
        {filteredProjects.length === 0 && (
          <div className="text-center py-16">
            <div className="p-6 bg-gradient-to-br from-gray-800 to-gray-900 rounded-2xl border border-gray-700 inline-block mb-6">
              <Globe className={`w-16 h-16 ${luxuryTheme.colors.text.tertiary} mx-auto`} />
            </div>
            <h3 className={`text-xl font-semibold mb-2 ${luxuryTheme.colors.text.primary}`}>
              {selectedFilter === 'all' ? 'No sites yet' : `No ${selectedFilter} sites`}
            </h3>
            <p className={`mb-8 ${luxuryTheme.colors.text.secondary} max-w-md mx-auto`}>
              {selectedFilter === 'all' 
                ? 'Get started by creating your first intelligent marketing website'
                : `You don't have any ${selectedFilter} sites yet`
              }
            </p>
            <Button 
              onClick={handleCreateNew}
              className={componentStyles.button.primary}
            >
              <Plus className="w-4 h-4 mr-2" />
              Create Your First Site
            </Button>
          </div>
        )}
      </main>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Sparkles, 
  Workflow, 
  Target, 
  TrendingUp, 
  Clock, 
  Zap,
  CheckCircle,
  ArrowRight,
  BarChart3,
  Users,
  DollarSign,
  Mail,
  ShoppingCart,
  Calendar
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useBuilderStore } from '@/store/builderStore';
import { useMagicConnector } from '@/hooks/useMagicConnector';
import { ComponentData } from '@/types/builder';

interface MagicConnectorDemoProps {
  className?: string;
}

export function MagicConnectorDemo({ className }: MagicConnectorDemoProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [demoComponents, setDemoComponents] = useState<ComponentData[]>([]);

  const { addComponent, clearCanvas, components } = useBuilderStore();
  const { 
    analyzeAllComponents, 
    canvasInsights, 
    analyses, 
    connections,
    connectAllHighPriority,
    generateCanvasReport 
  } = useMagicConnector({ autoAnalyze: true });

  // Demo steps
  const demoSteps = [
    {
      title: "Add Components to Canvas",
      description: "Let's start by adding some common components to see Magic Connector in action",
      action: addDemoComponents,
      icon: Target,
      color: "blue"
    },
    {
      title: "AI Analysis in Progress",
      description: "Magic Connector analyzes each component's purpose and context",
      action: () => analyzeAllComponents(),
      icon: Sparkles,
      color: "purple"
    },
    {
      title: "Workflow Suggestions Generated",
      description: "AI suggests relevant automation workflows for each component",
      action: () => new Promise(resolve => setTimeout(resolve, 2000)),
      icon: Workflow,
      color: "green"
    },
    {
      title: "One-Click Connections",
      description: "Connect high-priority workflow suggestions automatically",
      action: connectAllHighPriority,
      icon: Zap,
      color: "yellow"
    },
    {
      title: "Performance Insights",
      description: "View the impact and optimization recommendations",
      action: generateCanvasReport,
      icon: BarChart3,
      color: "indigo"
    }
  ];

  // Demo component templates
  const componentTemplates = [
    {
      type: 'form',
      name: 'Contact Form',
      props: {
        nameLabel: 'Full Name',
        emailLabel: 'Email Address',
        submitText: 'Get Free Quote'
      },
      position: { x: 100, y: 100 },
      size: { width: 350, height: 200 }
    },
    {
      type: 'button',
      name: 'CTA Button',
      props: {
        text: 'Start Free Trial',
        backgroundColor: '#3B82F6',
        color: '#FFFFFF'
      },
      position: { x: 500, y: 150 },
      size: { width: 200, height: 60 }
    },
    {
      type: 'hero',
      name: 'Hero Section',
      props: {
        title: 'Transform Your Business with AI',
        subtitle: 'Join thousands of companies using our platform to automate their workflows',
        primaryButtonText: 'Get Started',
        secondaryButtonText: 'Watch Demo'
      },
      position: { x: 50, y: 350 },
      size: { width: 600, height: 300 }
    },
    {
      type: 'card',
      name: 'Feature Card',
      props: {
        title: 'Smart Automation',
        description: 'AI-powered workflows that save you time and increase conversions',
        buttonText: 'Learn More'
      },
      position: { x: 750, y: 100 },
      size: { width: 300, height: 250 }
    }
  ];

  async function addDemoComponents() {
    clearCanvas();

    for (const template of componentTemplates) {
      const component: ComponentData = {
        id: `demo-${template.type}-${Date.now()}-${Math.random()}`,
        type: template.type,
        name: template.name,
        props: template.props,
        position: template.position,
        size: template.size,
        isConnectedToWorkflow: false
      };

      addComponent(component);
      setDemoComponents(prev => [...prev, component]);

      // Add small delay for visual effect
      await new Promise(resolve => setTimeout(resolve, 300));
    }
  }

  async function runDemo() {
    setIsRunning(true);
    setCurrentStep(0);

    for (let i = 0; i < demoSteps.length; i++) {
      setCurrentStep(i);

      try {
        await demoSteps[i].action();
        await new Promise(resolve => setTimeout(resolve, 1500));
      } catch (error) {
        console.error(`Demo step ${i} failed:`, error);
      }
    }

    setIsRunning(false);
  }

  function resetDemo() {
    clearCanvas();
    setDemoComponents([]);
    setCurrentStep(0);
    setIsRunning(false);
  }

  return (
    <div className={cn("p-6 bg-gradient-to-br from-purple-50 to-blue-50 rounded-xl", className)}>
      {/* Header */}
      <div className="text-center mb-8">
        <div className="flex items-center justify-center mb-4">
          <div className="p-3 bg-purple-500 rounded-full mr-3">
            <Workflow className="w-8 h-8 text-white" />
          </div>
          <h2 className="text-3xl font-bold text-gray-800">Magic Connector Demo</h2>
        </div>
        <p className="text-gray-600 max-w-2xl mx-auto">
          Experience the power of AI-driven workflow automation. Watch as Magic Connector 
          analyzes your components and suggests intelligent automation workflows.
        </p>
      </div>

      {/* Demo Controls */}
      <div className="flex justify-center space-x-4 mb-8">
        <button
          onClick={runDemo}
          disabled={isRunning}
          className={cn(
            "px-6 py-3 rounded-lg font-semibold transition-all flex items-center",
            isRunning 
              ? "bg-gray-300 text-gray-500 cursor-not-allowed"
              : "bg-purple-600 text-white hover:bg-purple-700 shadow-lg hover:shadow-xl"
          )}
        >
          {isRunning ? (
            <>
              <div className="animate-spin w-5 h-5 border-2 border-white border-t-transparent rounded-full mr-2"></div>
              Running Demo...
            </>
          ) : (
            <>
              <Sparkles className="w-5 h-5 mr-2" />
              Start Demo
            </>
          )}
        </button>

        <button
          onClick={resetDemo}
          className="px-6 py-3 bg-gray-500 text-white rounded-lg font-semibold hover:bg-gray-600 transition-all"
        >
          Reset
        </button>
      </div>

      {/* Demo Steps Progress */}
      <div className="mb-8">
        <div className="flex justify-between items-center mb-4">
          {demoSteps.map((step, index) => {
            const StepIcon = step.icon;
            const isActive = index === currentStep && isRunning;
            const isCompleted = index < currentStep || !isRunning;

            return (
              <div key={index} className="flex flex-col items-center flex-1">
                <div className={cn(
                  "w-12 h-12 rounded-full border-2 flex items-center justify-center mb-2 transition-all",
                  isActive ? `border-${step.color}-500 bg-${step.color}-500 text-white` :
                  isCompleted ? "border-green-500 bg-green-500 text-white" :
                  "border-gray-300 bg-white text-gray-400"
                )}>
                  {isCompleted && !isActive ? (
                    <CheckCircle className="w-6 h-6" />
                  ) : (
                    <StepIcon className={cn(
                      "w-6 h-6",
                      isActive && "animate-pulse"
                    )} />
                  )}
                </div>
                <div className="text-center">
                  <div className={cn(
                    "text-sm font-medium",
                    isActive ? "text-gray-800" : 
                    isCompleted ? "text-green-600" : "text-gray-500"
                  )}>
                    {step.title}
                  </div>
                  <div className="text-xs text-gray-500 mt-1 max-w-24">
                    {step.description}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Progress Bar */}
        <div className="w-full bg-gray-200 rounded-full h-2">
          <motion.div
            className="bg-purple-600 h-2 rounded-full"
            initial={{ width: 0 }}
            animate={{ 
              width: isRunning ? `${(currentStep / (demoSteps.length - 1)) * 100}%` : '0%' 
            }}
            transition={{ duration: 0.5 }}
          />
        </div>
      </div>

      {/* Current Step Details */}
      {isRunning && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg p-6 mb-8 shadow-lg"
        >
          <div className="flex items-center mb-3">
            <div className={`p-2 bg-${demoSteps[currentStep].color}-100 rounded-lg mr-3`}>
              {React.createElement(demoSteps[currentStep].icon, {
                className: `w-5 h-5 text-${demoSteps[currentStep].color}-600`
              })}
            </div>
            <h3 className="text-lg font-semibold text-gray-800">
              {demoSteps[currentStep].title}
            </h3>
          </div>
          <p className="text-gray-600">{demoSteps[currentStep].description}</p>
        </motion.div>
      )}

      {/* Canvas Insights */}
      {components.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg p-6 shadow-lg"
        >
          <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
            <BarChart3 className="w-5 h-5 mr-2 text-blue-600" />
            Real-Time Magic Connector Insights
          </h3>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
            <InsightCard
              icon={Target}
              label="Total Suggestions"
              value={canvasInsights.totalSuggestions}
              color="blue"
            />
            <InsightCard
              icon={Zap}
              label="High Priority"
              value={canvasInsights.highPrioritySuggestions}
              color="red"
            />
            <InsightCard
              icon={Clock}
              label="Time Saved"
              value={canvasInsights.estimatedTimesSaved}
              color="green"
            />
            <InsightCard
              icon={TrendingUp}
              label="Conversion Boost"
              value={canvasInsights.estimatedConversionIncrease}
              color="purple"
            />
          </div>

          {/* Analysis Details */}
          {analyses.size > 0 && (
            <div>
              <h4 className="font-semibold text-gray-800 mb-3">Component Analysis</h4>
              <div className="space-y-3">
                {Array.from(analyses.values()).map(analysis => (
                  <ComponentAnalysisCard key={analysis.componentId} analysis={analysis} />
                ))}
              </div>
            </div>
          )}

          {/* Active Connections */}
          {connections.length > 0 && (
            <div className="mt-6">
              <h4 className="font-semibold text-gray-800 mb-3 flex items-center">
                <CheckCircle className="w-4 h-4 mr-2 text-green-600" />
                Active Connections ({connections.length})
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {connections.map(connection => (
                  <ConnectionCard key={connection.id} connection={connection} />
                ))}
              </div>
            </div>
          )}
        </motion.div>
      )}

      {/* Feature Highlights */}
      <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
        <FeatureCard
          icon={Sparkles}
          title="AI-Powered Analysis"
          description="Advanced AI analyzes component purpose, context, and user intent"
          gradient="from-purple-500 to-pink-500"
        />
        <FeatureCard
          icon={Workflow}
          title="Smart Suggestions"
          description="Relevant workflow suggestions based on component type and business context"
          gradient="from-blue-500 to-indigo-500"
        />
        <FeatureCard
          icon={Zap}
          title="One-Click Setup"
          description="Connect complex automation workflows with a single click"
          gradient="from-green-500 to-teal-500"
        />
      </div>
    </div>
  );
}

// Helper Components

function InsightCard({ 
  icon: Icon, 
  label, 
  value, 
  color 
}: {
  icon: any;
  label: string;
  value: string | number;
  color: string;
}) {
  return (
    <div className="bg-gray-50 rounded-lg p-4 text-center">
      <Icon className={`w-6 h-6 text-${color}-600 mx-auto mb-2`} />
      <div className="text-2xl font-bold text-gray-800">{value}</div>
      <div className="text-sm text-gray-600">{label}</div>
    </div>
  );
}

function ComponentAnalysisCard({ analysis }: { analysis: any }) {
  const priorityColors = {
    high: 'red',
    medium: 'yellow',
    low: 'blue'
  };

  const topSuggestion = analysis.suggestions[0];
  const priority = topSuggestion?.priority || 'low';

  return (
    <div className="bg-gray-50 rounded-lg p-4 flex items-center justify-between">
      <div className="flex items-center">
        <div className={`w-3 h-3 bg-${priorityColors[priority]}-500 rounded-full mr-3`}></div>
        <div>
          <div className="font-medium text-gray-800">
            Component: {analysis.componentId.split('-')[1] || 'Unknown'}
          </div>
          <div className="text-sm text-gray-600">
            {analysis.suggestions.length} suggestions • {Math.round(analysis.performancePredictions.automationPotential * 100)}% automation potential
          </div>
        </div>
      </div>
      <div className="text-sm text-gray-500">
        {analysis.analysis.confidence > 0.8 ? 'High' : 
         analysis.analysis.confidence > 0.6 ? 'Medium' : 'Low'} Confidence
      </div>
    </div>
  );
}

function ConnectionCard({ connection }: { connection: any }) {
  const statusColors = {
    active: 'green',
    connected: 'blue',
    suggested: 'yellow',
    paused: 'gray'
  };

  return (
    <div className="bg-gray-50 rounded-lg p-3">
      <div className="flex items-center justify-between mb-2">
        <div className="font-medium text-gray-800 text-sm">
          {connection.workflowName}
        </div>
        <div className={`px-2 py-1 bg-${statusColors[connection.status]}-100 text-${statusColors[connection.status]}-700 text-xs rounded-full`}>
          {connection.status}
        </div>
      </div>
      <div className="text-xs text-gray-600">
        Trigger: {connection.triggerType} • Confidence: {Math.round(connection.confidence * 100)}%
      </div>
    </div>
  );
}

function FeatureCard({ 
  icon: Icon, 
  title, 
  description, 
  gradient 
}: {
  icon: any;
  title: string;
  description: string;
  gradient: string;
}) {
  return (
    <div className="bg-white rounded-lg p-6 shadow-lg">
      <div className={`w-12 h-12 bg-gradient-to-r ${gradient} rounded-lg flex items-center justify-center mb-4`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
      <h3 className="text-lg font-semibold text-gray-800 mb-2">{title}</h3>
      <p className="text-gray-600 text-sm">{description}</p>
    </div>
  );
}

export default MagicConnectorDemo;

'use client';

import { useState, useEffect } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { RefreshCw, Server, AlertCircle, CheckCircle } from 'lucide-react';

interface BackendStatus {
  isConnected: boolean;
  status: 'healthy' | 'unhealthy' | 'unknown';
  responseTime?: number;
  lastChecked: Date;
  error?: string;
}

/**
 * Development component to show backend connection status
 * Helps diagnose "Failed to fetch" errors
 */
export function BackendStatusIndicator() {
  const [status, setStatus] = useState<BackendStatus>({
    isConnected: false,
    status: 'unknown',
    lastChecked: new Date(),
  });
  const [isChecking, setIsChecking] = useState(false);

  const checkBackendStatus = async () => {
    setIsChecking(true);
    const startTime = Date.now();

    try {
      const response = await fetch('/api/backend/health', {
        method: 'GET',
        headers: {
          'Cache-Control': 'no-cache',
        },
      });

      const responseTime = Date.now() - startTime;

      if (response.ok) {
        const data = await response.json();
        setStatus({
          isConnected: true,
          status: 'healthy',
          responseTime,
          lastChecked: new Date(),
        });
      } else {
        setStatus({
          isConnected: false,
          status: 'unhealthy',
          responseTime,
          lastChecked: new Date(),
          error: `HTTP ${response.status}`,
        });
      }
    } catch (error) {
      setStatus({
        isConnected: false,
        status: 'unhealthy',
        lastChecked: new Date(),
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    } finally {
      setIsChecking(false);
    }
  };

  useEffect(() => {
    // Check status on mount
    checkBackendStatus();

    // Set up periodic checks every 30 seconds
    const interval = setInterval(checkBackendStatus, 30000);

    return () => clearInterval(interval);
  }, []);

  // Only show in development
  if (process.env.NODE_ENV !== 'development') {
    return null;
  }

  const getStatusColor = () => {
    switch (status.status) {
      case 'healthy':
        return 'bg-green-500';
      case 'unhealthy':
        return 'bg-red-500';
      default:
        return 'bg-yellow-500';
    }
  };

  const getStatusIcon = () => {
    switch (status.status) {
      case 'healthy':
        return <CheckCircle className="h-3 w-3" />;
      case 'unhealthy':
        return <AlertCircle className="h-3 w-3" />;
      default:
        return <Server className="h-3 w-3" />;
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 bg-white border border-gray-200 rounded-lg shadow-lg p-3 max-w-sm">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center space-x-2">
          <div className={`w-2 h-2 rounded-full ${getStatusColor()}`} />
          <span className="text-sm font-medium">Backend Status</span>
        </div>
        <Button
          size="sm"
          variant="ghost"
          onClick={checkBackendStatus}
          disabled={isChecking}
          className="h-6 w-6 p-0"
        >
          <RefreshCw className={`h-3 w-3 ${isChecking ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      <div className="space-y-1 text-xs text-gray-600">
        <div className="flex items-center justify-between">
          <span>Connection:</span>
          <Badge variant={status.isConnected ? 'default' : 'destructive'} className="text-xs">
            {getStatusIcon()}
            <span className="ml-1">
              {status.isConnected ? 'Connected' : 'Disconnected'}
            </span>
          </Badge>
        </div>

        {status.responseTime && (
          <div className="flex items-center justify-between">
            <span>Response Time:</span>
            <span className="font-mono">{status.responseTime}ms</span>
          </div>
        )}

        <div className="flex items-center justify-between">
          <span>Last Checked:</span>
          <span className="font-mono">
            {status.lastChecked.toLocaleTimeString()}
          </span>
        </div>

        {status.error && (
          <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-red-700">
            <div className="font-medium">Error:</div>
            <div className="text-xs">{status.error}</div>
          </div>
        )}
      </div>

      {!status.isConnected && (
        <div className="mt-2 p-2 bg-yellow-50 border border-yellow-200 rounded text-yellow-700 text-xs">
          <div className="font-medium">Troubleshooting:</div>
          <ul className="list-disc list-inside mt-1 space-y-1">
            <li>Check if backend server is running</li>
            <li>Verify backend is on port 8000</li>
            <li>Check network connectivity</li>
          </ul>
        </div>
      )}
    </div>
  );
}

export default BackendStatusIndicator;

'use client';

import React, { useCallback, useRef, useMemo } from 'react';
import {
  DndContext,
  DragOverlay,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragOverEvent,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { motion, AnimatePresence } from 'framer-motion';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData, ComponentElement } from '@/types/builder';
import CanvasComponent from './builder/CanvasComponent';
import { ElementToolbar } from './ElementToolbar';
import { DropIndicator } from './DropIndicator';
import { CSSProperties } from 'react';
import { 
  Eye, 
  Edit3, 
  ZoomIn, 
  ZoomOut, 
  RotateCcw, 
  Redo,
  Grid3X3,
  Monitor,
  Tablet,
  Smartphone
} from 'lucide-react';

interface DragDropCanvasProps {
  className?: string;
}

type ViewportSize = 'mobile' | 'tablet' | 'desktop';

// PERFORMANCE: Memoized CanvasComponent to prevent unnecessary re-renders
const MemoizedCanvasComponent = React.memo(CanvasComponent, (prevProps, nextProps) => {
  return (
    prevProps.component.id === nextProps.component.id &&
    prevProps.isSelected === nextProps.isSelected &&
    prevProps.zoom === nextProps.zoom &&
    prevProps.isBuilderMode === nextProps.isBuilderMode &&
    prevProps.component.position.x === nextProps.component.position.x &&
    prevProps.component.position.y === nextProps.component.position.y &&
    prevProps.component.size.width === nextProps.component.size.width &&
    prevProps.component.size.height === nextProps.component.size.height
  );
});

// PERFORMANCE: Memoized ElementToolbar
const MemoizedElementToolbar = React.memo(ElementToolbar, (prevProps, nextProps) => {
  return prevProps.elementId === nextProps.elementId;
});

// PERFORMANCE: Optimized viewport hook with memoization
function useViewportSettings() {
  const [viewport, setViewport] = React.useState<ViewportSize>('desktop');

  const dimensions = useMemo(() => {
    switch (viewport) {
      case 'mobile':
        return { width: 375, height: 812 };
      case 'tablet':
        return { width: 768, height: 1024 };
      case 'desktop':
        return { width: 1200, height: 800 };
    }
  }, [viewport]);

  return { viewport, setViewport, dimensions };
}

// PERFORMANCE: Optimized canvas state hook
function useCanvasState() {
  const [hoveredElementId, setHoveredElementId] = React.useState<string | null>(null);
  const [canvasMode, setCanvasMode] = React.useState<'design' | 'preview'>('design');
  const [isDropTarget, setIsDropTarget] = React.useState(false);
  const [activeId, setActiveId] = React.useState<string | null>(null);
  const [showGrid, setShowGrid] = React.useState(true);
  const [draggedElementType, setDraggedElementType] = React.useState<string | null>(null);

  // PERFORMANCE: Memoized state object to prevent unnecessary re-renders
  return useMemo(() => ({
    hoveredElementId,
    setHoveredElementId,
    canvasMode,
    setCanvasMode,
    isDropTarget,
    setIsDropTarget,
    activeId,
    setActiveId,
    showGrid,
    setShowGrid,
    draggedElementType,
    setDraggedElementType,
  }), [
    hoveredElementId,
    canvasMode,
    isDropTarget,
    activeId,
    showGrid,
    draggedElementType
  ]);
}

export const DragDropCanvas = React.memo(function DragDropCanvas({ className = '' }: DragDropCanvasProps) {
  const {
    components: elements,
    selectedComponentId: selectedElementId,
    zoom,
    selectComponent: selectElement,
    addComponent: addElement,
    updateComponentPosition: moveElement,
    setZoom,
  } = useBuilderStore();

  const canvasRef = useRef<HTMLDivElement>(null);
  const { viewport, setViewport, dimensions } = useViewportSettings();
  const canvasState = useCanvasState();

  // PERFORMANCE: Memoized sensors configuration
  const sensors = useMemo(() => useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  ), []);

  // PERFORMANCE: Memoized root elements calculation
  const rootElements = useMemo(() => 
    elements.filter(el => el.parentId === null || el.parentId === undefined),
    [elements]
  );

  // PERFORMANCE: Memoized element creation function
  const createElementFromType = useCallback((type: string, parentId: string | null) => {
    const baseElement: ComponentData = {
      id: `${type}-${Date.now()}`,
      type: type,
      name: `${type.charAt(0).toUpperCase() + type.slice(1)} Component`,
      props: {
        content: getDefaultContent(type),
        styles: getDefaultStyles(type),
        ...getDefaultProps(type),
      },
      children: [],
      position: { x: 20, y: 20 },
      size: { width: 300, height: 100 },
      parentId,
      order: 0,
    };

    return baseElement;
  }, []);

  // PERFORMANCE: Optimized drag handlers with throttling
  const dragHandlers = useMemo(() => ({
    handleDragStart: (event: DragStartEvent) => {
      const { active } = event;
      canvasState.setActiveId(active.id as string);

      // Check if this is a new element being dragged from the component library
      if (typeof active.id === 'string' && active.id.startsWith('new-')) {
        const elementType = active.id.replace('new-', '');
        canvasState.setDraggedElementType(elementType);
      }
    },

    handleDragOver: (event: DragOverEvent) => {
      const { over } = event;
      canvasState.setIsDropTarget(!!over);
    },

    handleDragEnd: (event: DragEndEvent) => {
      const { active, over } = event;

      canvasState.setActiveId(null);
      canvasState.setIsDropTarget(false);

      if (!over) return;

      // Handle new element creation
      if (typeof active.id === 'string' && active.id.startsWith('new-')) {
        const elementType = active.id.replace('new-', '');
        const dropTargetId = over.id === 'canvas-root' ? null : over.id as string;

        const newElement = createElementFromType(elementType, dropTargetId);
        if (newElement) {
          addElement(newElement);
        }
        return;
      }

      // Handle existing element movement
      const activeElement = elements.find(el => el.id === active.id);
      if (activeElement && active.id !== over.id) {
        const newParentId = over.id === 'canvas-root' ? null : over.id as string;
        // Update position instead of order for now
        moveElement(activeElement.id, { x: 0, y: 0 });
      }
    }
  }), [
    canvasState,
    createElementFromType,
    addElement,
    elements,
    moveElement
  ]);

  // PERFORMANCE: Memoized scaled dimensions
  const scaledDimensions = useMemo(() => ({
    width: (dimensions.width * zoom) / 100,
    height: (dimensions.height * zoom) / 100,
  }), [dimensions, zoom]);

  // PERFORMANCE: Memoized toolbar controls
  const toolbarControls = useMemo(() => (
    <div className="absolute top-4 left-1/2 transform -translate-x-1/2 z-50">
      <div className="bg-white rounded-lg shadow-lg border border-gray-200 p-2 flex items-center gap-2">
        {/* Mode Toggle */}
        <div className="flex bg-gray-100 rounded-md p-1">
          <button
            onClick={() => canvasState.setCanvasMode('design')}
            className={`px-3 py-1.5 rounded text-sm font-medium transition-all ${
              canvasState.canvasMode === 'design'
                ? 'bg-white text-gray-900 shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            <Edit3 className="w-4 h-4" />
          </button>
          <button
            onClick={() => canvasState.setCanvasMode('preview')}
            className={`px-3 py-1.5 rounded text-sm font-medium transition-all ${
              canvasState.canvasMode === 'preview'
                ? 'bg-white text-gray-900 shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            <Eye className="w-4 h-4" />
          </button>
        </div>

        <div className="w-px h-6 bg-gray-300" />

        {/* Viewport Controls */}
        <div className="flex gap-1">
          {(['mobile', 'tablet', 'desktop'] as ViewportSize[]).map((size) => {
            const Icon = size === 'mobile' ? Smartphone : size === 'tablet' ? Tablet : Monitor;
            return (
              <button
                key={size}
                onClick={() => setViewport(size)}
                className={`p-2 rounded transition-all ${
                  viewport === size
                    ? 'bg-blue-500 text-white'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
                title={`${size.charAt(0).toUpperCase() + size.slice(1)} view`}
              >
                <Icon className="w-4 h-4" />
              </button>
            );
          })}
        </div>

        <div className="w-px h-6 bg-gray-300" />

        {/* Zoom Controls */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => setZoom(zoom - 10)}
            disabled={zoom <= 25}
            className="p-2 rounded text-gray-600 hover:text-gray-900 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <ZoomOut className="w-4 h-4" />
          </button>
          <span className="text-sm font-medium text-gray-700 min-w-[3rem] text-center">
            {zoom}%
          </span>
          <button
            onClick={() => setZoom(zoom + 10)}
            disabled={zoom >= 200}
            className="p-2 rounded text-gray-600 hover:text-gray-900 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <ZoomIn className="w-4 h-4" />
          </button>
        </div>

        <div className="w-px h-6 bg-gray-300" />

        {/* Grid Toggle */}
        <button
          onClick={() => canvasState.setShowGrid(!canvasState.showGrid)}
          className={`p-2 rounded transition-all ${
            canvasState.showGrid
              ? 'bg-purple-500 text-white'
              : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
          }`}
          title="Toggle grid"
        >
          <Grid3X3 className="w-4 h-4" />
        </button>
      </div>
    </div>
  ), [
    canvasState,
    viewport,
    setViewport,
    zoom,
    setZoom
  ]);

  // PERFORMANCE: Memoized empty state
  const emptyState = useMemo(() => (
    rootElements.length === 0 ? (
      <div className="absolute inset-0 flex items-center justify-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center"
        >
          <div className="w-24 h-24 mx-auto mb-4 bg-gray-100 rounded-full flex items-center justify-center">
            <Grid3X3 className="w-8 h-8 text-gray-400" />
          </div>
          <h3 className="text-lg font-semibold text-gray-600 mb-2">
            Start Building
          </h3>
          <p className="text-gray-500 max-w-sm">
            Drag components from the sidebar to start building your page
          </p>
        </motion.div>
      </div>
    ) : null
  ), [rootElements.length]);

  return (
    <div className={`flex-1 bg-gray-50 relative overflow-hidden ${className}`}>
      {/* Canvas Toolbar */}
      {toolbarControls}

      {/* Canvas Container */}
      <div 
        className="flex-1 overflow-auto p-8 flex items-center justify-center"
        style={{ minHeight: '100vh' }}
      >
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={dragHandlers.handleDragStart}
          onDragOver={dragHandlers.handleDragOver}
          onDragEnd={dragHandlers.handleDragEnd}
        >
          {/* Canvas */}
          <div
            ref={canvasRef}
            className={`relative bg-white shadow-xl border border-gray-200 overflow-hidden ${
              canvasState.canvasMode === 'preview' ? 'pointer-events-none' : ''
            }`}
            style={{
              width: scaledDimensions.width,
              height: scaledDimensions.height,
              minHeight: scaledDimensions.height,
              transform: `scale(${zoom / 100})`,
              transformOrigin: 'center',
            }}
          >
            {/* Grid Overlay - PERFORMANCE: Only render when enabled */}
            {canvasState.showGrid && canvasState.canvasMode === 'design' && (
              <div
                className="absolute inset-0 pointer-events-none opacity-20"
                style={{
                  backgroundImage: `
                    linear-gradient(rgba(59, 130, 246, 0.3) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(59, 130, 246, 0.3) 1px, transparent 1px)
                  `,
                  backgroundSize: '20px 20px',
                }}
              />
            )}

            {/* Drop Zone */}
            <div
              id="canvas-root"
              className={`w-full h-full relative ${
                canvasState.isDropTarget ? 'bg-blue-50 border-2 border-dashed border-blue-300' : ''
              }`}
              onMouseLeave={() => canvasState.setHoveredElementId(null)}
            >
              <SortableContext 
                items={rootElements.map(el => el.id)} 
                strategy={verticalListSortingStrategy}
              >
                {rootElements.map((element) => (
                  <MemoizedCanvasComponent
                    key={element.id}
                    component={element}
                    isSelected={selectedElementId === element.id}
                    zoom={zoom / 100} // Convert percentage to decimal
                    isBuilderMode={canvasState.canvasMode === 'design'}
                  />
                ))}
              </SortableContext>

              {/* Empty State */}
              {emptyState}
            </div>

            {/* Drop Indicator */}
            <DropIndicator />
          </div>

          {/* Drag Overlay - PERFORMANCE: Only render when dragging */}
          <DragOverlay>
            {canvasState.activeId && elements.find(el => el.id === canvasState.activeId) && (
              <div className="bg-white border border-gray-300 rounded-lg p-4 shadow-lg opacity-80">
                <span className="text-sm font-medium text-gray-700">
                  {elements.find(el => el.id === canvasState.activeId)?.name}
                </span>
              </div>
            )}
          </DragOverlay>
        </DndContext>
      </div>

      {/* Element Toolbar - PERFORMANCE: Only render when component selected */}
      <AnimatePresence>
        {selectedElementId && canvasState.canvasMode === 'design' && (
          <MemoizedElementToolbar elementId={selectedElementId} />
        )}
      </AnimatePresence>
    </div>
  );
});

// PERFORMANCE: Memoized helper functions to prevent recreation
const getDefaultContent = (type: string): string => {
  switch (type) {
    case 'text':
      return 'Your text here';
    case 'button':
      return 'Click me';
    case 'hero':
      return 'Hero Section';
    case 'card':
      return 'Card Content';
    default:
      return '';
  }
};

const getDefaultStyles = (type: string): CSSProperties => {
  const baseStyles: CSSProperties = {
    position: 'relative' as const,
    width: '100%',
  };

  switch (type) {
    case 'container':
      return {
        ...baseStyles,
        padding: '20px',
        backgroundColor: '#ffffff',
        borderRadius: '8px',
        border: '1px solid #e5e7eb',
        minHeight: '100px',
      } as CSSProperties;
    case 'text':
      return {
        ...baseStyles,
        fontSize: '16px',
        color: '#374151',
        lineHeight: '1.5',
      } as CSSProperties;
    case 'button':
      return {
        ...baseStyles,
        padding: '14px 28px',
        background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
        color: '#ffffff',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        fontSize: '16px',
        fontWeight: '600',
        display: 'inline-block',
        width: 'auto',
        boxShadow: '0 4px 14px 0 rgba(59, 130, 246, 0.25)',
        transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
      } as CSSProperties;
    case 'image':
      return {
        ...baseStyles,
        width: '100%',
        height: '200px',
        backgroundColor: '#f3f4f6',
        borderRadius: '8px',
        objectFit: 'cover' as const,
      } as CSSProperties;
    case 'hero':
      return {
        ...baseStyles,
        padding: '80px 20px',
        backgroundColor: '#1f2937',
        color: '#ffffff',
        textAlign: 'center' as const,
        minHeight: '400px',
      } as CSSProperties;
    default:
      return baseStyles as CSSProperties;
  }
};

const getDefaultProps = (type: string): Record<string, any> => {
  switch (type) {
    case 'button':
      return {
        href: '#',
        target: '_self',
      };
    case 'image':
      return {
        src: '/placeholder-image.jpg',
        alt: 'Placeholder image',
      };
    default:
      return {};
  }
};

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useBuilderStore } from '@/store/builderStore';

export function DropIndicator() {
  const { draggedComponent } = useBuilderStore();
  const draggedElementType = draggedComponent?.componentType;
  const isDropTarget = false; // TODO: Implement drop target logic

  return (
    <AnimatePresence>
      {draggedElementType && isDropTarget && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="absolute inset-0 pointer-events-none z-40"
        >
          {/* Drop zone overlay */}
          <div className="absolute inset-0 bg-blue-50 bg-opacity-50 border-2 border-dashed border-blue-300 rounded-lg">
            <div className="absolute inset-0 flex items-center justify-center">
              <motion.div
                initial={{ scale: 0.8 }}
                animate={{ scale: 1 }}
                className="bg-blue-500 text-white px-4 py-2 rounded-lg shadow-lg font-medium"
              >
                Drop {draggedElementType} here
              </motion.div>
            </div>
          </div>

          {/* Animated particles */}
          <div className="absolute inset-0">
            {[...Array(6)].map((_, i) => (
              <motion.div
                key={i}
                className="absolute w-2 h-2 bg-blue-400 rounded-full"
                initial={{
                  x: ((i * 15) % 100) + '%',
                  y: ((i * 25) % 100) + '%',
                  scale: 0,
                }}
                animate={{
                  scale: [0, 1, 0],
                  opacity: [0, 1, 0],
                }}
                transition={{
                  duration: 2,
                  repeat: Infinity,
                  delay: i * 0.2,
                  ease: 'easeInOut',
                }}
              />
            ))}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { useBuilderStore } from '@/store/builderStore';
import { 
  Copy, 
  Trash2, 
  Edit3, 

  Layers,
  Palette,
  Type,
  Layout
} from 'lucide-react';

interface ElementToolbarProps {
  elementId: string;
}

export function ElementToolbar({ elementId }: ElementToolbarProps) {
  const { 
    getComponentById, 
    updateComponent, 
    removeComponent, 
    duplicateComponent,
    selectComponent 
  } = useBuilderStore();

  const element = getComponentById(elementId);

  if (!element) return null;

  const handleDelete = () => {
    removeComponent(elementId);
    selectComponent(null);
  };

  const handleDuplicate = () => {
    duplicateComponent(elementId);
  };

  const handleStyleChange = (property: string, value: string) => {
    if (!element) return;
    updateComponent(elementId, {
      style: {
        ...element.style,
        [property]: value,
      },
    });
  };

  const handleContentChange = (content: string) => {
    updateComponent(elementId, {
      props: {
        ...element?.props,
        content
      }
    });
  };

  const handleNameChange = (name: string) => {
    updateComponent(elementId, { name });
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 20 }}
      className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-50"
    >
      <div className="bg-white rounded-lg shadow-xl border border-gray-200 p-4 min-w-[600px]">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center">
              <Layers className="w-4 h-4 text-white" />
            </div>
            <div>
              <input
                type="text"
                value={element?.name || ''}
                onChange={(e) => handleNameChange(e.target.value)}
                className="font-semibold text-gray-900 bg-transparent border-none outline-none focus:bg-gray-50 rounded px-1"
              />
              <p className="text-sm text-gray-500 capitalize">{element?.type} element</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={handleDuplicate}
              className="p-2 rounded hover:bg-gray-100 text-gray-600 hover:text-gray-900 transition-colors"
              title="Duplicate element"
            >
              <Copy className="w-4 h-4" />
            </button>
            <button
              onClick={handleDelete}
              className="p-2 rounded hover:bg-red-50 text-red-500 hover:text-red-700 transition-colors"
              title="Delete element"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 mb-4">
          <button className="px-4 py-2 border-b-2 border-blue-500 text-blue-600 font-medium">
            <div className="flex items-center gap-2">
              <Edit3 className="w-4 h-4" />
              Content
            </div>
          </button>
          <button className="px-4 py-2 text-gray-600 hover:text-gray-900">
            <div className="flex items-center gap-2">
              <Palette className="w-4 h-4" />
              Style
            </div>
          </button>
          <button className="px-4 py-2 text-gray-600 hover:text-gray-900">
            <div className="flex items-center gap-2">
              <Layout className="w-4 h-4" />
              Layout
            </div>
          </button>
        </div>

        {/* Content Tab */}
        <div className="space-y-4">
          {/* Content Editor */}
          {element && (element?.type === 'text' || element?.type === 'button' || element?.type === 'hero') && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                <Type className="w-4 h-4 inline mr-1" />
                Content
              </label>
              {element?.type === 'text' ? (
                <textarea
                  value={element?.props?.content || ''}
                  onChange={(e) => handleContentChange(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none"
                  rows={3}
                  placeholder="Enter your text content..."
                />
              ) : (
                <input
                  type="text"
                  value={element?.props?.content || ''}
                  onChange={(e) => handleContentChange(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder={element?.type === 'button' ? 'Button text' : 'Hero title'}
                />
              )}
            </div>
          )}

          {/* Quick Style Controls */}
          <div className="grid grid-cols-2 gap-4">
            {/* Background Color */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Background
              </label>
              <div className="flex gap-2">
                <input
                  type="color"
                  value={(element?.style?.backgroundColor as string) || '#ffffff'}
                  onChange={(e) => handleStyleChange('backgroundColor', e.target.value)}
                  className="w-10 h-8 border border-gray-300 rounded cursor-pointer"
                />
                <input
                  type="text"
                  value={(element?.style?.backgroundColor as string) || '#ffffff'}
