}

'use client';

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Button } from '@/components/ui/button';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  isNetworkError: boolean;
}

/**
 * Enhanced Error Boundary for handling navigation and API errors
 * Specifically designed to handle "Failed to fetch" errors in Next.js App Router
 */
export class NavigationErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      isNetworkError: false,
    };
  }

  static getDerivedStateFromError(error: Error): State {
    // Check if it's a network-related error
    const isNetworkError = error.message.toLowerCase().includes('failed to fetch') ||
                          error.message.toLowerCase().includes('network') ||
                          error.message.toLowerCase().includes('connection');

    return {
      hasError: true,
      error,
      errorInfo: null,
      isNetworkError,
    };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({
      error,
      errorInfo,
    });

    // Log error for debugging
    console.group('🚨 Navigation Error Boundary');
    console.error('Error:', error);
    console.error('Error Info:', errorInfo);
    console.groupEnd();

    // Call custom error handler if provided
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }

    // In production, send to error tracking service
    if (process.env.NODE_ENV === 'production') {
      // Example: Send to Sentry, LogRocket, etc.
      // errorTrackingService.captureException(error, { extra: errorInfo });
    }
  }

  handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      isNetworkError: false,
    });
  };

  handleGoHome = () => {
    window.location.href = '/';
  };

  handleRefresh = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      // Custom fallback UI
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // Default error UI
      return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
          <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-6 text-center">
            <div className="flex justify-center mb-4">
              <AlertTriangle className="h-12 w-12 text-red-500" />
            </div>

            <h1 className="text-xl font-semibold text-gray-900 mb-2">
              {this.state.isNetworkError ? 'Connection Error' : 'Something went wrong'}
            </h1>

            <p className="text-gray-600 mb-6">
              {this.state.isNetworkError
                ? 'Unable to connect to the server. Please check your internet connection and try again.'
                : 'An unexpected error occurred while loading the page.'}
            </p>

            {/* Error details in development */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mb-6 text-left">
                <summary className="cursor-pointer text-sm text-gray-500 mb-2">
                  Error Details (Development)
                </summary>
                <pre className="text-xs bg-gray-100 p-2 rounded overflow-auto max-h-32">
                  {this.state.error.message}
                  {this.state.errorInfo?.componentStack}
                </pre>
              </details>
            )}

            <div className="space-y-3">
              <Button
                onClick={this.handleRetry}
                className="w-full"
                variant="default"
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                Try Again
              </Button>

              {this.state.isNetworkError && (
                <Button
                  onClick={this.handleRefresh}
                  className="w-full"
                  variant="outline"
                >
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Refresh Page
                </Button>
              )}

              <Button
                onClick={this.handleGoHome}
                className="w-full"
                variant="outline"
              >
                <Home className="h-4 w-4 mr-2" />
                Go Home
              </Button>
            </div>

            {/* Network status indicator */}
            <div className="mt-4 text-xs text-gray-500">
              Status: {navigator.onLine ? '🟢 Online' : '🔴 Offline'}
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

// Functional wrapper for easier use
export function withErrorBoundary<P extends object>(
  Component: React.ComponentType<P>,
  errorBoundaryProps?: Omit<Props, 'children'>
) {
  return function WrappedComponent(props: P) {
    return (
      <NavigationErrorBoundary {...errorBoundaryProps}>
        <Component {...props} />
      </NavigationErrorBoundary>
    );
  };
}

export default NavigationErrorBoundary;

'use client';

import React from 'react';

interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
  errorInfo?: React.ErrorInfo;
}

interface ErrorBoundaryProps {
  children: React.ReactNode;
  fallback?: React.ComponentType<{ error?: Error; errorInfo?: React.ErrorInfo; reset: () => void }>;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return {
      hasError: true,
      error,
    };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({
      error,
      errorInfo,
    });
  }

  reset = () => {
    this.setState({ hasError: false, error: undefined, errorInfo: undefined });
  };

  render() {
    if (this.state.hasError) {
      const FallbackComponent = this.props.fallback || DefaultErrorFallback;
      return (
        <FallbackComponent
          error={this.state.error}
          errorInfo={this.state.errorInfo}
          reset={this.reset}
        />
      );
    }

    return this.props.children;
  }
}

function DefaultErrorFallback({ 
  error, 
  errorInfo, 
  reset 
}: { 
  error?: Error; 
  errorInfo?: React.ErrorInfo; 
  reset: () => void; 
}) {
  return (
    <div className="min-h-screen bg-red-50 flex items-center justify-center p-4">
      <div className="bg-white p-6 rounded-lg shadow-lg max-w-2xl w-full">
        <h1 className="text-2xl font-bold text-red-600 mb-4">Something went wrong</h1>

        <div className="mb-4">
          <h2 className="text-lg font-semibold mb-2">Error Details:</h2>
          <pre className="bg-gray-100 p-3 rounded text-sm overflow-auto">
            {error?.message || 'Unknown error'}
          </pre>
        </div>

        {error?.stack && (
          <div className="mb-4">
            <h2 className="text-lg font-semibold mb-2">Stack Trace:</h2>
            <pre className="bg-gray-100 p-3 rounded text-xs overflow-auto max-h-60">
              {error.stack}
            </pre>
          </div>
        )}

        {errorInfo?.componentStack && (
          <div className="mb-4">
            <h2 className="text-lg font-semibold mb-2">Component Stack:</h2>
            <pre className="bg-gray-100 p-3 rounded text-xs overflow-auto max-h-40">
              {errorInfo.componentStack}
            </pre>
          </div>
        )}

        <div className="flex gap-3">
          <button
            onClick={reset}
            className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
          >
            Try Again
          </button>
          <button
            onClick={() => window.location.reload()}
            className="bg-gray-500 text-white px-4 py-2 rounded hover:bg-gray-600"
          >
            Reload Page
          </button>
        </div>
      </div>
    </div>
  );
}

export default ErrorBoundary;

'use client';

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useIsClient } from '@/lib/utils/hydration';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error | undefined;
}

/**
 * Error boundary specifically designed to catch hydration errors
 * and provide a graceful fallback during the hydration process
 */
class HydrationErrorBoundaryClass extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: Error): State {
    // Check if this is a hydration error
    const isHydrationError = 
      error.message.includes('Hydration') ||
      error.message.includes('hydration') ||
      error.message.includes('server HTML') ||
      error.message.includes('client-side HTML');

    return {
      hasError: isHydrationError,
      error: isHydrationError ? error : undefined
    };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log hydration errors for debugging
    if (this.state.hasError) {
      console.warn('Hydration error caught:', error.message);
      console.warn('Error info:', errorInfo);

      // In development, provide more detailed information
      if (process.env.NODE_ENV === 'development') {
        console.group('Hydration Error Details');
        console.log('Error:', error);
        console.log('Component Stack:', errorInfo.componentStack);
        console.log('Possible causes:');
        console.log('- Browser extensions modifying DOM');
        console.log('- Client-side only logic in components');
        console.log('- Non-deterministic values (Date.now(), Math.random())');
        console.log('- Conditional rendering based on window/document');
        console.groupEnd();
      }
    }
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback || (
        <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-md">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg className="h-5 w-5 text-yellow-400" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
            </div>
            <div className="ml-3">
              <h3 className="text-sm font-medium text-yellow-800">
                Hydration Issue Detected
              </h3>
              <div className="mt-2 text-sm text-yellow-700">
                <p>
                  The component is being re-rendered on the client to fix a hydration mismatch.
                  This is likely caused by browser extensions or dynamic content.
                </p>
              </div>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Wrapper component that only renders children after hydration is complete
 * This prevents hydration mismatches for components that behave differently on server vs client
 */
export function HydrationSafeWrapper({ 
  children, 
  fallback = null 
}: { 
  children: ReactNode;
  fallback?: ReactNode;
}) {
  const isClient = useIsClient();

  if (!isClient) {
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

/**
 * Main hydration error boundary component
 * Use this to wrap components that might have hydration issues
 */
export function HydrationErrorBoundary({ children, fallback }: Props) {
  return (
    <HydrationErrorBoundaryClass fallback={fallback}>
      {children}
    </HydrationErrorBoundaryClass>
  );
}

/**
 * Higher-order component to wrap components with hydration error boundary
 */
export function withHydrationErrorBoundary<P extends object>(
  Component: React.ComponentType<P>,
  fallback?: ReactNode
) {
  const WrappedComponent = (props: P) => (
    <HydrationErrorBoundary fallback={fallback}>
      <Component {...props} />
    </HydrationErrorBoundary>
  );

  WrappedComponent.displayName = `withHydrationErrorBoundary(${Component.displayName || Component.name})`;

  return WrappedComponent;
}

export default HydrationErrorBoundary;

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Upload, Eye, AlertCircle, CheckCircle, Loader } from 'lucide-react';

interface ImageAnalysis {
  width: number;
  height: number;
  format: string;
  size_kb: number;
  aspect_ratio: number;
  layout_hint: string;
  responsive_hint: string;
  component_type: string;
  suggested_complexity: number;
  layout_elements: string[];
  color_palette: {
    primary: string;
    secondary: string;
    accent: string;
    background: string;
    text: string;
  };
}

interface ImageAnalyzerProps {
  onAnalysisComplete?: (analysis: ImageAnalysis, file: File) => void;
  className?: string;
}

export function ImageAnalyzer({ onAnalysisComplete, className = '' }: ImageAnalyzerProps) {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [analysis, setAnalysis] = useState<ImageAnalysis | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const handleFileSelect = async (file: File) => {
    setError(null);
    setSelectedFile(file);

    // Create preview URL
    const url = URL.createObjectURL(file);
    setPreviewUrl(url);

    // Auto-analyze
    await analyzeImage(file);
  };

  const analyzeImage = async (file: File) => {
    if (!file) return;

    setIsAnalyzing(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('image', file);

      const response = await fetch('/api/ai/analyze-image', {
        method: 'POST',
        body: formData,
        headers: {
          'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
        }
      });

      if (!response.ok) {
        throw new Error(`Analysis failed: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        const analysisData = {
          ...data.analysis,
          ...data.suggestions
        };
        setAnalysis(analysisData);

        if (onAnalysisComplete) {
          onAnalysisComplete(analysisData, file);
        }
      } else {
        throw new Error('Analysis failed on server');
      }

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Analysis failed';
      setError(errorMessage);
      console.error('Image analysis error:', err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const files = Array.from(e.dataTransfer.files);
    const imageFile = files.find(file => file.type.startsWith('image/'));

    if (imageFile) {
      handleFileSelect(imageFile);
    }
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleFileSelect(file);
    }
  };

  return (
    <div className={`bg-white rounded-xl border border-gray-200 p-6 shadow-sm ${className}`}>
      <div className="flex items-center gap-3 mb-6">
        <div className="w-8 h-8 bg-purple-100 rounded-lg flex items-center justify-center">
          <Eye className="w-4 h-4 text-purple-600" />
        </div>
        <h4 className="font-semibold text-gray-800">Image Analysis</h4>
      </div>

      {!selectedFile ? (
        // Upload Area
        <div
          className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center hover:border-purple-500 transition-colors cursor-pointer"
          onDrop={handleDrop}
          onDragOver={(e) => e.preventDefault()}
          onClick={() => document.getElementById('image-input')?.click()}
        >
          <div className="flex flex-col items-center gap-4">
            <div className="w-16 h-16 bg-gray-100 rounded-xl flex items-center justify-center">
              <Upload className="w-8 h-8 text-gray-400" />
            </div>
            <div>
              <p className="text-lg font-medium text-gray-800 mb-1">Upload Component Image</p>
              <p className="text-sm text-gray-500">Drop an image here or click to browse</p>
            </div>
            <div className="text-xs text-gray-400">
              Supports JPG, PNG, WebP • Max 10MB
            </div>
          </div>
          <input
            id="image-input"
            type="file"
            accept="image/*"
            onChange={handleFileInput}
            className="hidden"
          />
        </div>
      ) : (
        // Analysis Results
        <div className="space-y-6">
          {/* Image Preview */}
          <div className="flex items-start gap-4">
            <div className="w-24 h-24 bg-gray-100 rounded-lg overflow-hidden flex-shrink-0">
              {previewUrl && (
                <img
                  src={previewUrl}
                  alt="Upload preview"
                  className="w-full h-full object-cover"
                />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <h5 className="font-medium text-gray-800 truncate">{selectedFile.name}</h5>
              <p className="text-sm text-gray-500 mb-2">
                {(selectedFile.size / 1024).toFixed(1)} KB
              </p>
              <button
                onClick={() => {
                  setSelectedFile(null);
                  setAnalysis(null);
                  setError(null);
                  if (previewUrl) {
                    URL.revokeObjectURL(previewUrl);
                    setPreviewUrl(null);
                  }
                }}
                className="text-sm text-purple-600 hover:text-purple-700 transition-colors"
              >
                Upload different image
              </button>
            </div>
          </div>

          {/* Analysis Status */}
          <AnimatePresence mode="wait">
            {isAnalyzing && (
              <motion.div
                key="analyzing"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="flex items-center gap-3 p-4 bg-blue-50 border border-blue-200 rounded-lg"
              >
                <Loader className="w-5 h-5 text-blue-600 animate-spin" />
                <div>
                  <p className="font-medium text-blue-800">Analyzing Image...</p>
                  <p className="text-sm text-blue-600">Extracting design patterns and layout information</p>
                </div>
              </motion.div>
            )}

            {error && (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="flex items-start gap-3 p-4 bg-red-50 border border-red-200 rounded-lg"
              >
                <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="font-medium text-red-800">Analysis Failed</p>
                  <p className="text-sm text-red-600">{error}</p>
                  <button
                    onClick={() => selectedFile && analyzeImage(selectedFile)}
                    className="text-sm text-red-600 hover:text-red-700 underline mt-1"
                  >
                    Try again
                  </button>
                </div>
              </motion.div>
            )}

            {analysis && !isAnalyzing && (
              <motion.div
                key="success"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="space-y-4"
              >
                {/* Success Header */}
                <div className="flex items-center gap-3 p-4 bg-green-50 border border-green-200 rounded-lg">
                  <CheckCircle className="w-5 h-5 text-green-600" />
                  <div>
                    <p className="font-medium text-green-800">Analysis Complete</p>
                    <p className="text-sm text-green-600">Ready to generate similar component</p>
                  </div>
                </div>

                {/* Analysis Results */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Image Properties */}
                  <div className="p-4 bg-gray-50 rounded-lg">
                    <h6 className="font-medium text-gray-700 mb-3">Image Properties</h6>
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-600">Dimensions:</span>
                        <span className="font-medium">{analysis.width}×{analysis.height}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">Aspect Ratio:</span>
                        <span className="font-medium">{analysis.aspect_ratio}:1</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">Format:</span>
                        <span className="font-medium">{analysis.format}</span>
                      </div>
                    </div>
                  </div>

                  {/* Component Suggestions */}
                  <div className="p-4 bg-gray-50 rounded-lg">
                    <h6 className="font-medium text-gray-700 mb-3">Component Suggestions</h6>
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-600">Type:</span>
                        <span className="font-medium">{analysis.component_type}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">Complexity:</span>
                        <span className="font-medium">{analysis.suggested_complexity}/5</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">Layout:</span>
                        <span className="font-medium">{analysis.layout_hint}</span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Layout Elements */}
                {analysis.layout_elements && analysis.layout_elements.length > 0 && (
                  <div className="p-4 bg-purple-50 rounded-lg">
                    <h6 className="font-medium text-purple-800 mb-3">Detected Elements</h6>
                    <div className="flex flex-wrap gap-2">
                      {analysis.layout_elements.map((element, index) => (
                        <span
                          key={index}
                          className="px-2 py-1 bg-purple-100 text-purple-700 text-xs rounded-md"
                        >
                          {element}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* Color Palette */}
                {analysis.color_palette && (
                  <div className="p-4 bg-gray-50 rounded-lg">
                    <h6 className="font-medium text-gray-700 mb-3">Extracted Color Palette</h6>
                    <div className="flex gap-3">
                      {Object.entries(analysis.color_palette).map(([name, color]) => (
                        <div key={name} className="text-center">
                          <div
                            className="w-8 h-8 rounded-lg border border-gray-300 mb-1"
                            style={{ backgroundColor: color }}
                          />
                          <span className="text-xs text-gray-600 capitalize">{name}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Responsive Hints */}
                <div className="p-4 bg-blue-50 rounded-lg">
                  <h6 className="font-medium text-blue-800 mb-2">Responsive Design Recommendations</h6>
                  <p className="text-sm text-blue-700">{analysis.responsive_hint}</p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useBuilderStore } from '@/store/builderStore';
import { useAIEditor } from '@/hooks/useAIEditor';
import ComponentEditorWithAI from './ComponentEditorWithAI'; // CONSOLIDATED: Using unified editor
import { AICustomizationPanel } from './builder/AICustomizationPanel';
import { 
  Code, 
  Sparkles, 
  Settings, 
  X, 
  RotateCcw,
  Eye,
  EyeOff,
  Bot,
  User,
  Layers,
  Palette,
  Zap
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { ComponentData } from '@/types/builder';

interface IntegratedEditorProps {
  className?: string;
  onClose?: () => void;
}

export function IntegratedEditor({ className, onClose }: IntegratedEditorProps) {
  const [editorMode, setEditorMode] = useState<'visual' | 'code' | 'ai'>('visual');
  const [showPreview, setShowPreview] = useState(true);
  const [selectedComponent, setSelectedComponent] = useState<ComponentData | null>(null);

  const {
    selectedComponentId,
    getSelectedComponent,
  } = useBuilderStore();

  const {
    state: aiState,
    openEditor,
    closeEditor: closeAIEditor,
    applyAIEdit,
    undoLastEdit,
    redoLastEdit,
    resetToOriginal,
    processAIPrompt
  } = useAIEditor();

  useEffect(() => {
    const component = getSelectedComponent();
    setSelectedComponent(component || null);

    if (component && editorMode === 'code') {
      // Auto-open AI editor when switching to code mode
      openEditor(component);
    }
  }, [selectedComponentId, getSelectedComponent, editorMode, openEditor]);

  const handleModeChange = (mode: 'visual' | 'code' | 'ai') => {
    setEditorMode(mode);

    if (mode === 'code' && selectedComponent) {
      openEditor(selectedComponent);
    } else if (mode !== 'code') {
      closeAIEditor();
    }
  };

  const generateComponentCode = (component: ComponentData): string => {
    const { type, props, content } = component;

    // Generate appropriate code based on component type
    const baseProps = Object.entries(props || {})
      .filter(([key]) => !['style', 'className', 'content'].includes(key))
      .map(([key, value]) => `${key}={${typeof value === 'string' ? `"${value}"` : JSON.stringify(value)}}`)
      .join(' ');

    const styleProp = props?.style ? ` style={${JSON.stringify(props.style)}}` : '';
    const classNameProp = props?.className ? ` className="${props.className}"` : '';

    switch (type) {
      case 'button':
        return `<button${classNameProp}${styleProp} ${baseProps}>
  ${content || props?.text || 'Click me'}
</button>`;

      case 'text':
        return `<p${classNameProp}${styleProp} ${baseProps}>
  ${content || props?.text || 'Text content'}
</p>`;

      case 'input':
        return `<input${classNameProp}${styleProp} ${baseProps} />`;

      case 'container':
        return `<div${classNameProp}${styleProp} ${baseProps}>
  ${content || ''}
</div>`;

      case 'image':
        return `<img src="${props?.src || ''}" alt="${props?.alt || ''}"${classNameProp}${styleProp} ${baseProps} />`;

      // CONSOLIDATED: Enhanced with new component types
      case 'hero':
        return `<section${classNameProp}${styleProp} ${baseProps}>
  <div className="max-w-4xl mx-auto text-center">
    <h1 className="text-4xl md:text-6xl font-bold mb-6">
      ${content || props?.title || 'Hero Title'}
    </h1>
    <p className="text-xl md:text-2xl mb-8 opacity-90">
      ${props?.subtitle || 'Your compelling hero subtitle goes here'}
    </p>
    <div className="space-x-4">
      <button className="bg-white text-gray-900 px-8 py-4 rounded-xl font-bold text-lg hover:bg-gray-100 hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl">
        ${props?.primaryButtonText || 'Get Started'}
      </button>
      <button className="border-2 border-white text-white px-8 py-4 rounded-xl font-bold text-lg hover:bg-white hover:text-gray-900 hover:scale-105 transition-all duration-300 shadow-lg backdrop-blur-sm">
        ${props?.secondaryButtonText || 'Learn More'}
      </button>
    </div>
  </div>
</section>`;

      case 'card':
        return `<div${classNameProp}${styleProp} ${baseProps}>
  <h3 className="text-lg font-semibold mb-2">${props?.title || 'Card Title'}</h3>
  <p className="text-gray-600 mb-4">
    ${content || props?.description || 'Card description goes here.'}
  </p>
  <button className="bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 text-white px-6 py-3 rounded-lg font-semibold hover:scale-105 transition-all duration-300 shadow-md hover:shadow-lg">
    ${props?.buttonText || 'Action'}
  </button>
</div>`;

      case 'form':
        return `<form${classNameProp}${styleProp} ${baseProps}>
  <div className="space-y-4">
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        ${props?.nameLabel || 'Name'}
      </label>
      <input
        type="text"
        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
        placeholder="${props?.namePlaceholder || 'Enter your name'}"
      />
    </div>
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        ${props?.emailLabel || 'Email'}
      </label>
      <input
        type="email"
        className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
        placeholder="${props?.emailPlaceholder || 'Enter your email'}"
      />
    </div>
    <button
      type="submit"
      className="w-full bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 text-white py-3 px-6 rounded-lg font-semibold hover:scale-[1.02] transition-all duration-300 shadow-md hover:shadow-lg"
    >
      ${props?.submitText || 'Submit'}
    </button>
  </div>
</form>`;

      case 'navigation':
      case 'navbar':
        return `<nav${classNameProp}${styleProp} ${baseProps}>
  <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
    <div className="flex justify-between items-center h-16">
      <div className="font-bold text-xl text-gray-900">
        ${props?.logo || 'Logo'}
      </div>
      <div className="hidden md:flex space-x-8">
        <a href="#" className="text-gray-700 hover:text-gray-900 transition-colors">Home</a>
        <a href="#" className="text-gray-700 hover:text-gray-900 transition-colors">About</a>
        <a href="#" className="text-gray-700 hover:text-gray-900 transition-colors">Services</a>
        <a href="#" className="text-gray-700 hover:text-gray-900 transition-colors">Contact</a>
      </div>
      <button className="bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-600 hover:to-blue-700 text-white px-6 py-3 rounded-lg font-semibold hover:scale-105 transition-all duration-300 shadow-md hover:shadow-lg">
        ${props?.ctaText || 'Get Started'}
      </button>
    </div>
  </div>
</nav>`;

      default:
        return `<div${classNameProp}${styleProp} ${baseProps}>
  ${content || 'Component'}
</div>`;
    }
  };

  const renderEditor = () => {
    if (!selectedComponent) {
      return (
        <div className="flex-1 flex items-center justify-center bg-gray-50">
          <div className="text-center">
            <Layers className="w-16 h-16 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No Component Selected</h3>
            <p className="text-sm text-gray-500">
              Click on any component to start editing
            </p>
          </div>
        </div>
      );
    }

    switch (editorMode) {
      case 'visual':
        return (
          <div className="flex-1 flex">
            <div className="flex-1 bg-white">
              <AICustomizationPanel 
                onOpenEditor={() => handleModeChange('code')}
              />
            </div>
          </div>
        );

      case 'code':
        // CONSOLIDATED: Using the unified ComponentEditorWithAI with AI enabled
        return (
          <ComponentEditorWithAI
            initialCode={generateComponentCode(selectedComponent)}
            componentType="react"
            componentId={selectedComponent.id}
            onCodeChange={(newCode) => {
              // Handle code changes - could update the component
              console.log('Code updated:', newCode);
            }}
            className="flex-1"
            enableAI={true}
            showAIPanel={false}
            enableAdvancedFeatures={true}
          />
        );

      case 'ai':
        // CONSOLIDATED: Using the unified ComponentEditorWithAI with AI panel open
        return (
          <div className="flex-1 flex">
            <div className="flex-1">
              <ComponentEditorWithAI
                initialCode={generateComponentCode(selectedComponent)}
                componentType="react"
                componentId={selectedComponent.id}
                onCodeChange={(newCode) => {
                  console.log('AI Code updated:', newCode);
                }}
                className="h-full"
                enableAI={true}
                showAIPanel={true}
                enableAdvancedFeatures={true}
              />
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className={cn("bg-white rounded-lg shadow-lg overflow-hidden", className)}>
      {/* Enhanced Header */}
      <div className="flex items-center justify-between p-4 bg-gray-50 border-b border-gray-200">
        <div className="flex items-center gap-4">
          <h3 className="font-semibold text-gray-800">Component Editor</h3>

          {/* Enhanced Mode Selector */}
          <div className="flex bg-white rounded-lg p-1 border border-gray-200">
            <button
              onClick={() => handleModeChange('visual')}
              className={cn(
                "flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all",
                editorMode === 'visual'
                  ? 'bg-blue-500 text-white shadow-sm'
                  : 'text-gray-600 hover:text-gray-800'
              )}
            >
              <Eye className="w-3 h-3" />
              Visual
            </button>
            <button
              onClick={() => handleModeChange('code')}
              className={cn(
                "flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all",
                editorMode === 'code'
                  ? 'bg-purple-500 text-white shadow-sm'
                  : 'text-gray-600 hover:text-gray-800'
              )}
            >
              <Code className="w-3 h-3" />
              Code
            </button>
            <button
              onClick={() => handleModeChange('ai')}
              className={cn(
                "flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all",
                editorMode === 'ai'
                  ? 'bg-gradient-to-r from-purple-500 to-blue-500 text-white shadow-sm'
                  : 'text-gray-600 hover:text-gray-800'
              )}
            >
              <Sparkles className="w-3 h-3" />
              AI Enhanced
            </button>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowPreview(!showPreview)}
            className="p-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg transition-all"
            title={showPreview ? 'Hide preview' : 'Show preview'}
          >
            {showPreview ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
          </button>

          <button
            onClick={() => {
              resetToOriginal();
            }}
            className="p-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg transition-all"
            title="Reset to original"
          >
            <RotateCcw className="w-4 h-4" />
          </button>

          {onClose && (
            <button
              onClick={onClose}
              className="p-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg transition-all"
              title="Close editor"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 min-h-[500px]">
        <AnimatePresence mode="wait">
          <motion.div
            key={editorMode}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="h-full"
          >
            {renderEditor()}
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Enhanced Footer */}
      <div className="px-4 py-2 bg-gray-50 border-t border-gray-200 text-xs text-gray-500 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <span>Mode: {editorMode.charAt(0).toUpperCase() + editorMode.slice(1)}</span>
          {selectedComponent && (
            <span>Editing: {selectedComponent.name}</span>
          )}
          {editorMode === 'ai' && (
            <span className="text-purple-600">AI Enhanced Editing</span>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button className="hover:text-gray-700" title="Color Palette">
            <Palette className="w-3 h-3" />
          </button>
          <button className="hover:text-gray-700" title="Quick Actions">
            <Zap className="w-3 h-3" />
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * CanvasWithDebugger Integration Component
 * 
 * Integration wrapper for Story 3.1: Visual Workflow Debugging
 * Provides Canvas debugging integration while maintaining separation of concerns
 * 
 * Features:
 * - Wraps existing Canvas component with debugging capabilities
 * - Integrates WorkflowDebugger with sliding panel
 * - Canvas-to-debugger data transformation
 * - Performance-optimized integration patterns
 * - Non-breaking enhancement of existing Canvas
 * 
 * @author Integration Coordinator - Story 3.1 Implementation
 */

'use client';

import React, { useCallback, useEffect, useState, useMemo } from 'react';
import { Canvas } from '../builder/Canvas';
import { WorkflowDebugger } from '../builder/WorkflowDebugger';
import { useBuilderStore } from '@/store/builderStore';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Bug, ChevronRight, ChevronLeft, Activity } from 'lucide-react';
import { cn } from '@/lib/utils';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface CanvasWithDebuggerProps {
  className?: string;
  onComponentSelect?: (componentId: string | null) => void;
  // Debugging Integration Props
  enableDebugging?: boolean;
  workflowId?: number | null;
  debugMode?: 'basic' | 'detailed' | 'expert';
  showWorkflowOverlays?: boolean;
  onDebugToggle?: (enabled: boolean) => void;
  // Canvas passthrough props
  canvasProps?: Record<string, any>;
}

interface DebugPanelState {
  isPanelOpen: boolean;
  debuggingActive: boolean;
  panelWidth: number;
}

// ============================================================================
// HOOKS
// ============================================================================

/**
 * Hook for managing debugging panel state with Canvas integration
 */
function useCanvasDebuggingIntegration(
  enableDebugging: boolean, 
  workflowId: number | null
) {
  const [panelState, setPanelState] = useState<DebugPanelState>({
    isPanelOpen: false,
    debuggingActive: false,
    panelWidth: 320, // Default panel width
  });

  // Auto-close panel when debugging is disabled
  useEffect(() => {
    if (!enableDebugging) {
      setPanelState(prev => ({
        ...prev,
        isPanelOpen: false,
        debuggingActive: false
      }));
    }
  }, [enableDebugging]);

  const togglePanel = useCallback(() => {
    if (enableDebugging && workflowId) {
      setPanelState(prev => ({
        ...prev,
        isPanelOpen: !prev.isPanelOpen
      }));
    }
  }, [enableDebugging, workflowId]);

  const startDebugging = useCallback(() => {
    if (enableDebugging && workflowId) {
      setPanelState(prev => ({
        ...prev,
        debuggingActive: true,
        isPanelOpen: true
      }));
    }
  }, [enableDebugging, workflowId]);

  const stopDebugging = useCallback(() => {
    setPanelState(prev => ({
      ...prev,
      debuggingActive: false
    }));
  }, []);

  const setPanelOpen = useCallback((open: boolean) => {
    setPanelState(prev => ({
      ...prev,
      isPanelOpen: open
    }));
  }, []);

  return {
    ...panelState,
    togglePanel,
    startDebugging,
    stopDebugging,
    setPanelOpen
  };
}

/**
 * Hook for transforming Canvas data to WorkflowDebugger format
 */
function useCanvasDataTransformation() {
  const { components } = useBuilderStore();

  // Transform Canvas components to WorkflowDebugger node format
  const canvasNodes = useMemo(() => {
    return components.map(component => ({
      id: component.id,
      type: component.type,
      name: component.name,
      position: component.position,
      size: component.size,
      isWorkflowNode: component.isConnectedToWorkflow || false
    }));
  }, [components]);

  // Count workflow-connected components
  const workflowNodeCount = useMemo(() => {
    return components.filter(c => c.isConnectedToWorkflow).length;
  }, [components]);

  // Calculate Canvas statistics for debugging info
  const canvasStats = useMemo(() => ({
    total: components.length,
    workflowNodes: workflowNodeCount,
    connectedRatio: components.length > 0 ? (workflowNodeCount / components.length) * 100 : 0
  }), [components.length, workflowNodeCount]);

  return {
    canvasNodes,
    workflowNodeCount,
    canvasStats
  };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const CanvasWithDebugger = React.memo<CanvasWithDebuggerProps>(({
  className,
  onComponentSelect,
  enableDebugging = false,
  workflowId = null,
  debugMode = 'detailed',
  showWorkflowOverlays = true,
  onDebugToggle,
  canvasProps = {}
}) => {
  // ============================================================================
  // HOOKS
  // ============================================================================

  const {
    isPanelOpen,
    debuggingActive,
    panelWidth,
    togglePanel,
    startDebugging,
    stopDebugging,
    setPanelOpen
  } = useCanvasDebuggingIntegration(enableDebugging, workflowId);

  const {
    canvasNodes,
    workflowNodeCount,
    canvasStats
  } = useCanvasDataTransformation();

  // ============================================================================
  // EVENT HANDLERS
  // ============================================================================

  const handleDebugToggle = useCallback(() => {
    const newState = !debuggingActive;
    if (newState) {
      startDebugging();
    } else {
      stopDebugging();
    }
    onDebugToggle?.(newState);
  }, [debuggingActive, startDebugging, stopDebugging, onDebugToggle]);

  const handlePanelClose = useCallback(() => {
    setPanelOpen(false);
  }, [setPanelOpen]);

  // ============================================================================
  // RENDER HELPERS
  // ============================================================================

  const renderDebuggingControls = () => {
    if (!enableDebugging || !workflowId) return null;

    return (
      <div className="absolute top-4 right-4 flex items-center gap-2 z-10">
        {workflowNodeCount > 0 && (
          <Badge variant="outline" className="text-xs bg-white/90 backdrop-blur-sm">
            <Activity className="w-3 h-3 mr-1" />
            {workflowNodeCount} workflow node{workflowNodeCount !== 1 ? 's' : ''}
          </Badge>
        )}

        <Button
          variant={debuggingActive ? "default" : "outline"}
          size="sm"
          onClick={handleDebugToggle}
          className={cn(
            "bg-white/90 backdrop-blur-sm transition-all duration-200",
            debuggingActive && "bg-blue-600 hover:bg-blue-700 text-white"
          )}
        >
          <Bug className="w-4 h-4 mr-1" />
          {debuggingActive ? "Stop Debug" : "Debug"}
        </Button>

        {debuggingActive && (
          <Button
            variant="outline"
            size="sm"
            onClick={togglePanel}
            className="bg-white/90 backdrop-blur-sm"
          >
            {isPanelOpen ? (
              <ChevronRight className="w-4 h-4" />
            ) : (
              <ChevronLeft className="w-4 h-4" />
            )}
          </Button>
        )}
      </div>
    );
  };

  const renderDebuggingPanel = () => {
    if (!enableDebugging || !workflowId || !isPanelOpen) return null;

    return (
      <div className={cn(
        "fixed right-0 top-0 bottom-0 bg-white border-l shadow-2xl transform transition-transform duration-300 ease-in-out z-50",
        isPanelOpen ? "translate-x-0" : "translate-x-full"
      )}
      style={{ width: panelWidth }}
      >
        <div className="h-full overflow-hidden flex flex-col">
          <WorkflowDebugger
            workflowId={workflowId}
            isActive={debuggingActive}
            canvasNodes={canvasNodes}
            showStatusOverlays={showWorkflowOverlays}
            showSLAMonitoring={true}
            enableRealTime={true}
            debugMode={debugMode}
            className="flex-1 h-full border-0 shadow-none"
            onClose={handlePanelClose}
          />
        </div>
      </div>
    );
  };

  // ============================================================================
  // RENDER
  // ============================================================================

  return (
    <div className={cn("relative flex overflow-hidden", className)}>
      {/* Enhanced Canvas Container */}
      <div className={cn(
        "flex-1 transition-all duration-300 ease-in-out",
        isPanelOpen ? `mr-[${panelWidth}px]` : "mr-0"
      )}>
        {/* Canvas with Integration Overlay */}
        <div className="relative">
          <Canvas
            className="w-full h-full"
            onComponentSelect={onComponentSelect}
            {...canvasProps}
          />

          {/* Debugging Controls Overlay */}
          {renderDebuggingControls()}

          {/* Enhanced Canvas Info with Debug Stats */}
          {enableDebugging && workflowId && canvasStats.total > 0 && (
            <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-2 rounded-lg text-sm text-gray-600 border">
              <div className="flex items-center gap-2">
                <div className="text-xs">
                  {canvasStats.total} components
                </div>
                {canvasStats.workflowNodes > 0 && (
                  <>
                    <div className="w-1 h-1 bg-gray-400 rounded-full" />
                    <div className="text-xs text-purple-600">
                      {canvasStats.connectedRatio.toFixed(0)}% workflow connected
                    </div>
                  </>
                )}
              </div>

              {debuggingActive && (
                <div className="text-xs text-blue-600 mt-1 flex items-center gap-1">
                  <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse" />
                  Debugging active
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* WorkflowDebugger Panel */}
      {renderDebuggingPanel()}
    </div>
  );
});

CanvasWithDebugger.displayName = 'CanvasWithDebugger';

// ============================================================================
// EXPORTS
// ============================================================================

export default CanvasWithDebugger;

export type { CanvasWithDebuggerProps };

