"use client"

import { useState, useEffect } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Progress } from '@/components/ui/progress'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { CheckCircle, AlertCircle, Loader2, ExternalLink, Download, RefreshCw } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { useMigrationService } from '@/hooks/useMigrationService'

interface MigrationWizardProps {
  onComplete?: (migrationId: string) => void
  onCancel?: () => void
}

interface MigrationStep {
  id: string
  title: string
  description: string
  completed: boolean
  active: boolean
  progress: number
}

export function MigrationWizard({ onComplete, onCancel }: MigrationWizardProps) {
  const [currentStep, setCurrentStep] = useState(0)
  const [websiteUrl, setWebsiteUrl] = useState('')
  const [scrapingDepth, setScrapingDepth] = useState(3)
  const [migrationId, setMigrationId] = useState<string | null>(null)
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [analysis, setAnalysis] = useState<any>(null)
  const [migrationStatus, setMigrationStatus] = useState<any>(null)

  const { 
    startMigration, 
    getMigrationStatus, 
    analyzeWebsite, 
    getMigrationResult,
    getMigrationTemplates 
  } = useMigrationService()

  const steps: MigrationStep[] = [
    {
      id: 'input',
      title: 'Enter Website URL',
      description: 'Provide the website URL you want to migrate',
      completed: currentStep > 0,
      active: currentStep === 0,
      progress: 0
    },
    {
      id: 'analyze',
      title: 'Analyze Website',
      description: 'We analyze your website structure and content',
      completed: currentStep > 1,
      active: currentStep === 1,
      progress: 0
    },
    {
      id: 'configure',
      title: 'Configure Migration',
      description: 'Set migration preferences and options',
      completed: currentStep > 2,
      active: currentStep === 2,
      progress: 0
    },
    {
      id: 'migrate',
      title: 'Migration in Progress',
      description: 'Extracting and processing your website content',
      completed: currentStep > 3,
      active: currentStep === 3,
      progress: 0
    },
    {
      id: 'review',
      title: 'Review Results',
      description: 'Review the migrated templates and components',
      completed: currentStep > 4,
      active: currentStep === 4,
      progress: 0
    }
  ]

  useEffect(() => {
    if (migrationId) {
      const interval = setInterval(async () => {
        try {
          const status = await getMigrationStatus(migrationId)
          setMigrationStatus(status)

          if (status.status === 'completed') {
            clearInterval(interval)
            setCurrentStep(4)
          } else if (status.status === 'failed') {
            clearInterval(interval)
          }
        } catch (error) {
          console.error('Error checking migration status:', error)
          clearInterval(interval)
        }
      }, 2000)

      return () => clearInterval(interval)
    }
  }, [migrationId, getMigrationStatus])

  const handleAnalyze = async () => {
    if (!websiteUrl) return

    setIsAnalyzing(true)
    setCurrentStep(1)

    try {
      const result = await analyzeWebsite(websiteUrl, scrapingDepth)
      setAnalysis(result)
      setCurrentStep(2)
    } catch (error) {
      console.error('Analysis failed:', error)
    } finally {
      setIsAnalyzing(false)
    }
  }

  const handleStartMigration = async () => {
    try {
      const result = await startMigration(websiteUrl, scrapingDepth)
      setMigrationId(result.id)
      setCurrentStep(3)
    } catch (error) {
      console.error('Migration start failed:', error)
    }
  }

  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <div className="space-y-6">
            <div className="space-y-2">
              <Label htmlFor="website-url">Website URL</Label>
              <Input
                id="website-url"
                type="url"
                placeholder="https://example.com"
                value={websiteUrl}
                onChange={(e) => setWebsiteUrl(e.target.value)}
                className="text-lg"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="scraping-depth">Scraping Depth</Label>
              <input
                id="scraping-depth"
                type="range"
                min="1"
                max="5"
                value={scrapingDepth}
                onChange={(e) => setScrapingDepth(parseInt(e.target.value))}
                className="w-full"
              />
              <div className="text-sm text-muted-foreground">
                Depth: {scrapingDepth} ({scrapingDepth === 1 ? 'Homepage only' : 
                  scrapingDepth === 2 ? 'Homepage + 1 level' : 
                  scrapingDepth === 3 ? 'Homepage + 2 levels' : 
                  scrapingDepth === 4 ? 'Homepage + 3 levels' : 
                  'Deep crawl'})
              </div>
            </div>

            <Button 
              onClick={handleAnalyze}
              disabled={!websiteUrl || isAnalyzing}
              className="w-full"
            >
              {isAnalyzing ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Analyzing...
                </>
              ) : (
                'Analyze Website'
              )}
            </Button>
          </div>
        )

      case 1:
        return (
          <div className="flex flex-col items-center justify-center py-12">
            <Loader2 className="h-12 w-12 animate-spin text-primary mb-4" />
            <p className="text-lg text-muted-foreground">Analyzing website structure...</p>
          </div>
        )

      case 2:
        return (
          <div className="space-y-6">
            {analysis && (
              <>
                <Card>
                  <CardHeader>
                    <CardTitle>Analysis Results</CardTitle>
                    <CardDescription>
                      Found {analysis.preview.pages_found} pages, {analysis.preview.assets_found} assets, and {analysis.preview.styles_found} styles
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <span className="font-medium">Complexity:</span>
                        <span className={`px-2 py-1 rounded text-sm ${
                          analysis.analysis.complexity === 'low' ? 'bg-green-100 text-green-800' :
                          analysis.analysis.complexity === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                          'bg-red-100 text-red-800'
                        }`}>
                          {analysis.analysis.complexity}
                        </span>
                      </div>

                      <div className="flex justify-between items-center">
                        <span className="font-medium">Estimated Time:</span>
                        <span>{analysis.analysis.estimated_time}</span>
                      </div>

                      {analysis.analysis.warnings.length > 0 && (
                        <Alert>
                          <AlertCircle className="h-4 w-4" />
                          <AlertDescription>
                            {analysis.analysis.warnings.join(', ')}
                          </AlertDescription>
                        </Alert>
                      )}
                    </div>
                  </CardContent>
                </Card>

                <div className="flex space-x-4">
                  <Button variant="outline" onClick={() => setCurrentStep(0)}>
                    Back
                  </Button>
                  <Button onClick={handleStartMigration} className="flex-1">
                    Start Migration
                  </Button>
                </div>
              </>
            )}
          </div>
        )

      case 3:
        return (
          <div className="space-y-6">
            <div className="text-center">
              <h3 className="text-lg font-semibold mb-2">Migration in Progress</h3>
              <p className="text-muted-foreground mb-4">
                {migrationStatus?.status === 'scraping' ? 'Extracting website content...' :
                 migrationStatus?.status === 'processing' ? 'Processing content...' :
                 migrationStatus?.status === 'optimizing' ? 'Optimizing templates...' :
                 'Finalizing migration...'}
              </p>
            </div>

            {migrationStatus && (
              <>
                <Progress value={migrationStatus.progress} className="w-full" />

                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="text-muted-foreground">Pages Processed:</span>
                    <span className="font-medium ml-2">
                      {migrationStatus.processed_pages} / {migrationStatus.total_pages}
                    </span>
                  </div>
                  <div>
                    <span className="text-muted-foreground">Status:</span>
                    <span className="font-medium ml-2 capitalize">{migrationStatus.status}</span>
                  </div>
                </div>

                {migrationStatus.errors.length > 0 && (
                  <Alert variant="destructive">
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>
                      {migrationStatus.errors.join(', ')}
                    </AlertDescription>
                  </Alert>
                )}
              </>
            )}
          </div>
        )

      case 4:
        return (
          <div className="space-y-6">
            <div className="text-center">
              <CheckCircle className="h-16 w-16 text-green-500 mx-auto mb-4" />
              <h3 className="text-xl font-semibold mb-2">Migration Complete!</h3>
              <p className="text-muted-foreground">
                Your website has been successfully migrated to templates.
              </p>
            </div>

            {migrationStatus && (
              <Card>
                <CardHeader>
                  <CardTitle>Summary</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span>Total Pages:</span>
                      <span className="font-medium">{migrationStatus.total_pages}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Processing Time:</span>
                      <span className="font-medium">Completed</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Warnings:</span>
                      <span className="font-medium">{migrationStatus.warnings.length}</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}

            <div className="flex space-x-4">
              <Button onClick={() => onComplete?.(migrationId!)} className="flex-1">
                Review Templates
              </Button>
              <Button variant="outline" onClick={() => setCurrentStep(0)}>
                Start New Migration
              </Button>
            </div>
          </div>
        )

      default:
        return null
    }
  }

  return (
    <div className="max-w-4xl mx-auto">
      {/* Progress Steps */}
      <div className="mb-8">
        <div className="flex justify-between items-center">
          {steps.map((step, index) => (
            <div key={step.id} className="flex items-center">
              <div className="flex flex-col items-center">
                <div
                  className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-medium ${
                    step.completed
                      ? 'bg-green-500 text-white'
                      : step.active
                      ? 'bg-primary text-white'
                      : 'bg-gray-200 text-gray-600'
                  }`}
                >
                  {step.completed ? (
                    <CheckCircle className="h-5 w-5" />
                  ) : (
                    index + 1
                  )}
                </div>
                <div className="mt-2 text-center">
                  <p className="text-sm font-medium">{step.title}</p>
                  <p className="text-xs text-muted-foreground max-w-32">
                    {step.description}
                  </p>
                </div>
              </div>
              {index < steps.length - 1 && (
                <div
                  className={`w-full h-1 mx-2 ${
                    step.completed ? 'bg-green-500' : 'bg-gray-200'
                  }`}
                />
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Main Content */}
      <AnimatePresence mode="wait">
        <motion.div
          key={currentStep}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -20 }}
          transition={{ duration: 0.3 }}
        >
          {renderStepContent()}
        </motion.div>
      </AnimatePresence>

      {/* Cancel Button */}
      {currentStep < 4 && (
        <div className="mt-6 text-center">
          <Button
            variant="ghost"
            onClick={() => onCancel?.()}
            className="text-muted-foreground"
          >
            Cancel Migration
          </Button>
        </div>
      )}
    </div>
  )
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Upload, X, Image as ImageIcon, Bot, CheckCircle, AlertTriangle } from 'lucide-react';
import { PromptProcessor } from '@/lib/ai/prompt-processor';

interface PromptInputProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  onImageUpload?: (file: File | null) => void;
  uploadedImage?: File | null;
  className?: string;
  showAnalysis?: boolean;
  onAnalysisUpdate?: (analysis: any) => void;
}

export function PromptInput({ 
  value, 
  onChange, 
  placeholder = "Describe your component...",
  onImageUpload,
  uploadedImage,
  className = '',
  showAnalysis = false,
  onAnalysisUpdate
}: PromptInputProps) {
  const [isFocused, setIsFocused] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [promptProcessor] = useState(() => new PromptProcessor());
  const [analysis, setAnalysis] = useState<any>(null);
  const [validation, setValidation] = useState<any>(null);
  const [suggestedTemplates, setSuggestedTemplates] = useState<any[]>([]);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-resize textarea and analyze prompt
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }

    // Analyze prompt for intelligence
    if (value.trim().length > 5) {
      const promptAnalysis = promptProcessor.analyzePrompt(value);
      const promptValidation = promptProcessor.validatePrompt(value);
      const templates = promptProcessor.getSuggestedTemplates(value);

      setAnalysis(promptAnalysis);
      setValidation(promptValidation);
      setSuggestedTemplates(templates.slice(0, 3));

      if (onAnalysisUpdate) {
        onAnalysisUpdate(promptAnalysis);
      }
    } else {
      setAnalysis(null);
      setValidation(null);
      setSuggestedTemplates([]);
    }
  }, [value, onAnalysisUpdate, promptProcessor]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const files = Array.from(e.dataTransfer.files);
    const imageFile = files.find(file => file.type.startsWith('image/'));

    if (imageFile && onImageUpload) {
      onImageUpload(imageFile);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onImageUpload) {
      onImageUpload(file);
    }
  };

  const removeImage = () => {
    if (onImageUpload) {
      onImageUpload(null);
    }
  };

  const characterCount = value.length;
  const maxCharacters = 1000;
  const isNearLimit = characterCount > maxCharacters * 0.8;
  const isOverLimit = characterCount > maxCharacters;

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Main Input Area */}
      <div
        className={`
          relative border-2 rounded-xl transition-all duration-200
          ${isFocused 
            ? 'border-blue-500 bg-blue-50/50' 
            : 'border-gray-200 bg-gray-50/50 hover:border-gray-300'
          }
          ${isDragging ? 'border-blue-500 bg-blue-50' : ''}
        `}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={(e) => {
          e.preventDefault();
          setIsDragging(false);
        }}
        onDrop={handleDrop}
      >
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder={placeholder}
          className={`w-full p-4 bg-transparent border-none outline-none resize-none min-h-[120px] text-gray-800 placeholder-gray-500 ${
            validation && !validation.isValid ? 'text-red-600' : ''
          }`}
          maxLength={maxCharacters}
        />

        {/* Upload Button */}
        {onImageUpload && (
          <div className="absolute top-4 right-4">
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className={`
                p-2 rounded-lg transition-all duration-200
                ${isFocused || isDragging
                  ? 'bg-blue-500 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                }
              `}
              title="Upload reference image"
            >
              <Upload className="w-4 h-4" />
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleFileSelect}
              className="hidden"
            />
          </div>
        )}
      </div>

      {/* Uploaded Image Preview */}
      {uploadedImage && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 10 }}
          className="relative bg-white border border-gray-200 rounded-lg p-3 flex items-center gap-3"
        >
          <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center">
            <ImageIcon className="w-6 h-6 text-gray-500" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-gray-800 truncate">
              {uploadedImage.name}
            </p>
            <p className="text-xs text-gray-500">
              {(uploadedImage.size / 1024).toFixed(1)} KB
            </p>
          </div>
          <button
            onClick={removeImage}
            className="p-1 text-gray-400 hover:text-red-500 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </motion.div>
      )}

      {/* Validation and Analysis */}
      {validation && !validation.isValid && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-3">
          <div className="flex items-center gap-2 text-red-800 text-sm font-medium mb-1">
            <AlertTriangle className="w-4 h-4" />
            Prompt Issues
          </div>
          <ul className="text-sm text-red-700 space-y-1">
            {validation.errors.map((error: string, index: number) => (
              <li key={index} className="flex items-start gap-1">
                <span className="w-1 h-1 bg-red-500 rounded-full mt-2 flex-shrink-0" />
                {error}
              </li>
            ))}
          </ul>
        </div>
      )}

      {validation && validation.warnings.length > 0 && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 mb-3">
          <div className="flex items-center gap-2 text-yellow-800 text-sm font-medium mb-1">
            <AlertTriangle className="w-4 h-4" />
            Suggestions for Better Results
          </div>
          <ul className="text-sm text-yellow-700 space-y-1">
            {validation.warnings.map((warning: string, index: number) => (
              <li key={index} className="flex items-start gap-1">
                <span className="w-1 h-1 bg-yellow-500 rounded-full mt-2 flex-shrink-0" />
                {warning}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* AI Analysis Display */}
      {showAnalysis && analysis && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 mb-3">
          <div className="flex items-center gap-2 text-blue-800 text-sm font-medium mb-2">
            <Bot className="w-4 h-4" />
            AI Analysis ({Math.round(analysis.confidence * 100)}% confidence)
          </div>

          <div className="grid grid-cols-2 gap-4 text-xs">
            <div>
              <span className="text-blue-600 font-medium">Intent:</span>
              <p className="text-blue-800 capitalize">{analysis.intent}</p>
            </div>
            <div>
              <span className="text-blue-600 font-medium">Entities:</span>
              <p className="text-blue-800">
                {Object.values(analysis.entities).flat().length} detected
              </p>
            </div>
          </div>

          {analysis.suggestions.length > 0 && (
            <div className="mt-2">
              <span className="text-blue-600 font-medium text-xs">Improvements:</span>
              <ul className="mt-1 space-y-1">
                {analysis.suggestions.slice(0, 2).map((suggestion: string, index: number) => (
                  <li key={index} className="text-xs text-blue-700 flex items-start gap-1">
                    <CheckCircle className="w-3 h-3 mt-0.5 flex-shrink-0" />
                    {suggestion}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {/* Smart Templates */}
      {suggestedTemplates.length > 0 && (
        <div className="bg-purple-50 border border-purple-200 rounded-lg p-3 mb-3">
          <div className="flex items-center gap-2 text-purple-800 text-sm font-medium mb-2">
            <Bot className="w-4 h-4" />
            Suggested Templates
          </div>

          <div className="space-y-2">
            {suggestedTemplates.map((template: any, index: number) => (
              <button
                key={index}
                onClick={() => onChange(template.examples[0])}
                className="w-full text-left p-2 bg-purple-100 hover:bg-purple-200 rounded-lg transition-colors"
              >
                <div className="text-sm font-medium text-purple-900">{template.name}</div>
                <div className="text-xs text-purple-700 mt-1">{template.template}</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Character Count and Tips */}
      <div className="flex items-center justify-between text-sm">
        <div className="flex items-center gap-4">
          {isDragging && (
            <motion.span
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="text-blue-600 font-medium"
            >
              Drop image here to add as reference
            </motion.span>
          )}
          {!isDragging && !analysis && (
            <span className="text-gray-500">
              Try: &quot;Create a responsive pricing card with hover effects and gradient background&quot;
            </span>
          )}
          {analysis && (
            <span className="text-green-600 font-medium flex items-center gap-1">
              <CheckCircle className="w-3 h-3" />
              Prompt analyzed - ready for generation
            </span>
          )}
        </div>

        <span className={`
          font-medium transition-colors
          ${isOverLimit 
            ? 'text-red-500' 
            : isNearLimit 
            ? 'text-yellow-500' 
            : 'text-gray-400'
          }
        `}>
          {characterCount}/{maxCharacters}
        </span>
      </div>

      {/* Enhanced Quick Suggestions */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-sm font-medium text-gray-700">Quick Start Ideas</h4>
          <span className="text-xs text-gray-500">{quickSuggestions.length} suggestions</span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
          {quickSuggestions.map((suggestion, index) => (
            <button
              key={index}
              onClick={() => onChange(suggestion)}
              className="text-left p-3 bg-gray-50 hover:bg-blue-50 border border-gray-200 hover:border-blue-300 rounded-lg text-sm text-gray-700 hover:text-blue-700 transition-all duration-200 group"
            >
              <div className="flex items-start gap-2">
                <Bot className="w-4 h-4 text-gray-400 group-hover:text-blue-500 mt-0.5 flex-shrink-0" />
                <span>{suggestion}</span>
              </div>
            </button>
          ))}
        </div>

        {/* Prompt Variations */}
        {analysis && (
          <div className="mt-4">
            <h4 className="text-sm font-medium text-gray-700 mb-2">Prompt Variations</h4>
            <div className="space-y-2">
              {promptProcessor.generatePromptVariations(value).map((variation: string, index: number) => (
                <button
                  key={index}
                  onClick={() => onChange(variation)}
                  className="w-full text-left p-2 bg-gradient-to-r from-blue-50 to-purple-50 hover:from-blue-100 hover:to-purple-100 border border-blue-200 rounded-lg text-sm text-gray-700 transition-all duration-200"
                >
                  <div className="flex items-start gap-2">
                    <span className="w-5 h-5 bg-gradient-to-br from-blue-500 to-purple-500 rounded text-white text-xs flex items-center justify-center flex-shrink-0 mt-0.5">
                      {index + 1}
                    </span>
                    <span>{variation}</span>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

const quickSuggestions = [
  "Responsive navigation menu with dropdown",
  "Pricing card with features and CTA button",
  "Dashboard widget with chart and metrics",
  "Contact form with validation",
  "Hero section with background image",
  "Product showcase with image gallery"
];

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Switch } from '@/components/ui/switch';
import { 
  Globe, 
  Shield, 
  CheckCircle, 
  AlertCircle, 
  Clock, 
  Copy,
  Loader2,
  ExternalLink
} from 'lucide-react';
import { 
  deploymentService, 
  type DomainConfig, 
  type SSLConfig, 
  type DomainVerificationResult 
} from '@/lib/services/DeploymentService';

interface DomainManagerProps {
  deploymentId: string;
  currentDomain?: string;
  onDomainConfigured?: (domain: string, verified: boolean) => void;
}

interface DNSRecord {
  type: 'A' | 'AAAA' | 'CNAME' | 'TXT';
  name: string;
  value: string;
  ttl: number;
  required: boolean;
}

export default function DomainManager({ 
  deploymentId, 
  currentDomain, 
  onDomainConfigured 
}: DomainManagerProps) {
  const [domain, setDomain] = useState(currentDomain || '');
  const [domainConfig, setDomainConfig] = useState<DomainConfig>({
    domain: '',
    redirectWww: true,
    forceHttps: true,
    dnsTtl: 300
  });
  const [sslConfig, setSSLConfig] = useState<SSLConfig>({
    enabled: true,
    provider: 'letsencrypt',
    autoRenew: true
  });
  const [dnsRecords, setDnsRecords] = useState<DNSRecord[]>([]);
  const [verificationToken, setVerificationToken] = useState('');
  const [domainStatus, setDomainStatus] = useState<{
    configured: boolean;
    verified: boolean;
    sslEnabled: boolean;
    loading: boolean;
    error?: string;
  }>({
    configured: false,
    verified: false,
    sslEnabled: false,
    loading: false
  });

  useEffect(() => {
    if (currentDomain) {
      loadDomainStatus();
    }
  }, [currentDomain]);

  const loadDomainStatus = async () => {
    if (!currentDomain) return;

    setDomainStatus(prev => ({ ...prev, loading: true }));

    try {
      const status = await deploymentService.getDomainStatus(deploymentId, currentDomain);
      setDomainStatus({
        configured: true,
        verified: status.verified,
        sslEnabled: status.sslEnabled,
        loading: false
      });
    } catch (error) {
      setDomainStatus({
        configured: false,
        verified: false,
        sslEnabled: false,
        loading: false,
        error: 'Failed to load domain status'
      });
    }
  };

  const handleDomainConfiguration = async () => {
    if (!domain.trim()) return;

    const config: DomainConfig = {
      ...domainConfig,
      domain: domain.trim()
    };

    setDomainStatus(prev => ({ ...prev, loading: true, error: undefined }));

    try {
      const result: DomainVerificationResult = await deploymentService.configureDomain(
        deploymentId, 
        config, 
        sslConfig
      );

      if (result.verified || result.records.length > 0) {
        setDnsRecords(result.records);
        setVerificationToken(result.verificationToken || '');
        setDomainStatus({
          configured: true,
          verified: result.verified,
          sslEnabled: sslConfig.enabled,
          loading: false
        });

        onDomainConfigured?.(config.domain, result.verified);
      } else {
        setDomainStatus(prev => ({
          ...prev,
          loading: false,
          error: result.error || 'Domain configuration failed'
        }));
      }
    } catch (error) {
      setDomainStatus(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Configuration failed'
      }));
    }
  };

  const handleDomainVerification = async () => {
    if (!domain || !verificationToken) return;

    setDomainStatus(prev => ({ ...prev, loading: true }));

    try {
      const result = await deploymentService.verifyDomain(domain, verificationToken);

      setDomainStatus(prev => ({
        ...prev,
        verified: result.verified,
        loading: false,
        error: result.error
      }));

      if (result.verified) {
        onDomainConfigured?.(domain, true);
      }
    } catch (error) {
      setDomainStatus(prev => ({
        ...prev,
        loading: false,
        error: error instanceof Error ? error.message : 'Verification failed'
      }));
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const getDomainStatusIcon = () => {
    if (domainStatus.loading) return <Loader2 className="h-4 w-4 animate-spin" />;
    if (domainStatus.verified) return <CheckCircle className="h-4 w-4 text-green-500" />;
    if (domainStatus.configured) return <Clock className="h-4 w-4 text-yellow-500" />;
    return <AlertCircle className="h-4 w-4 text-gray-400" />;
  };

  const getSSLStatusIcon = () => {
    if (domainStatus.sslEnabled) return <Shield className="h-4 w-4 text-green-500" />;
    return <Shield className="h-4 w-4 text-gray-400" />;
  };

  return (
    <div className="space-y-6">
      {/* Domain Configuration Header */}
      <div className="flex items-center space-x-2">
        <Globe className="h-5 w-5" />
        <h2 className="text-lg font-semibold">Custom Domain & SSL</h2>
      </div>

      {/* Current Status */}
      {currentDomain && (
        <Card>
          <CardHeader>
            <CardTitle className="text-sm">Current Domain Status</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                {getDomainStatusIcon()}
                <span className="font-medium">{currentDomain}</span>
              </div>
              <div className="flex space-x-2">
                <Badge variant={domainStatus.verified ? "default" : "secondary"}>
                  {domainStatus.verified ? "Verified" : "Pending"}
                </Badge>
                <Badge variant={domainStatus.sslEnabled ? "default" : "secondary"}>
                  {domainStatus.sslEnabled ? "SSL Active" : "No SSL"}
                </Badge>
              </div>
            </div>

            {domainStatus.error && (
              <Alert>
                <AlertCircle className="h-4 w-4" />
                <AlertDescription>{domainStatus.error}</AlertDescription>
              </Alert>
            )}
          </CardContent>
        </Card>
      )}

      <Tabs defaultValue="configure" className="w-full">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="configure">Configure</TabsTrigger>
          <TabsTrigger value="dns">DNS Records</TabsTrigger>
          <TabsTrigger value="ssl">SSL Setup</TabsTrigger>
        </TabsList>

        <TabsContent value="configure" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Domain Configuration</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="domain">Custom Domain</Label>
                <Input
                  id="domain"
                  placeholder="example.com"
                  value={domain}
                  onChange={(e) => setDomain(e.target.value)}
                />
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <Label htmlFor="redirect-www">Redirect www to apex domain</Label>
                  <Switch
                    id="redirect-www"
                    checked={domainConfig.redirectWww}
                    onCheckedChange={(checked) => 
                      setDomainConfig(prev => ({ ...prev, redirectWww: checked }))
                    }
                  />
                </div>

                <div className="flex items-center justify-between">
                  <Label htmlFor="force-https">Force HTTPS redirects</Label>
                  <Switch
                    id="force-https"
                    checked={domainConfig.forceHttps}
                    onCheckedChange={(checked) => 
                      setDomainConfig(prev => ({ ...prev, forceHttps: checked }))
                    }
                  />
                </div>
              </div>

              <Button 
                onClick={handleDomainConfiguration}
                disabled={!domain.trim() || domainStatus.loading}
                className="w-full"
              >
                {domainStatus.loading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Configuring...
                  </>
                ) : (
                  'Configure Domain'
                )}
              </Button>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="dns" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>DNS Configuration</CardTitle>
            </CardHeader>
            <CardContent>
              {dnsRecords.length > 0 ? (
                <div className="space-y-4">
                  <Alert>
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>
                      Add these DNS records to your domain provider to complete the setup.
                    </AlertDescription>
                  </Alert>

                  <div className="space-y-3">
                    {dnsRecords.map((record, index) => (
                      <div key={index} className="border rounded-lg p-3">
                        <div className="flex items-center justify-between mb-2">
                          <Badge variant={record.required ? "default" : "secondary"}>
                            {record.type}
                          </Badge>
                          {record.required && (
                            <Badge variant="destructive" className="text-xs">
                              Required
                            </Badge>
                          )}
                        </div>
                        <div className="grid grid-cols-3 gap-2 text-sm">
                          <div>
                            <strong>Name:</strong>
                            <div className="font-mono bg-gray-50 p-1 rounded text-xs mt-1">
                              {record.name}
                            </div>
                          </div>
                          <div>
                            <strong>Value:</strong>
                            <div className="font-mono bg-gray-50 p-1 rounded text-xs mt-1 flex items-center">
                              <span className="truncate flex-1">{record.value}</span>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => copyToClipboard(record.value)}
                                className="h-6 w-6 p-0 ml-1"
                              >
                                <Copy className="h-3 w-3" />
                              </Button>
                            </div>
                          </div>
                          <div>
                            <strong>TTL:</strong>
                            <div className="text-xs mt-1">{record.ttl}s</div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>

                  {!domainStatus.verified && (
                    <Button 
                      onClick={handleDomainVerification}
                      disabled={domainStatus.loading}
                      className="w-full"
                    >
                      {domainStatus.loading ? (
                        <>
                          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                          Verifying...
                        </>
                      ) : (
                        'Verify Domain'
                      )}
                    </Button>
                  )}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-500">
                  Configure a domain first to see DNS records
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="ssl" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                {getSSLStatusIcon()}
                <span>SSL Certificate</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between">
                <Label htmlFor="ssl-enabled">Enable SSL Certificate</Label>
                <Switch
                  id="ssl-enabled"
                  checked={sslConfig.enabled}
                  onCheckedChange={(checked) => 
                    setSSLConfig(prev => ({ ...prev, enabled: checked }))
                  }
                />
              </div>

              {sslConfig.enabled && (
                <>
                  <div className="space-y-2">
                    <Label>Certificate Provider</Label>
                    <select 
                      className="w-full border rounded-md px-3 py-2"
                      value={sslConfig.provider}
                      onChange={(e) => 
                        setSSLConfig(prev => ({ 
                          ...prev, 
                          provider: e.target.value as 'letsencrypt' | 'custom' | 'cloudflare'
                        }))
                      }
                    >
                      <option value="letsencrypt">Let's Encrypt (Recommended)</option>
                      <option value="cloudflare">Cloudflare</option>
                      <option value="custom">Custom Certificate</option>
                    </select>
                  </div>

                  <div className="flex items-center justify-between">
                    <Label htmlFor="auto-renew">Auto-renew certificates</Label>
                    <Switch
                      id="auto-renew"
                      checked={sslConfig.autoRenew}
                      onCheckedChange={(checked) => 
                        setSSLConfig(prev => ({ ...prev, autoRenew: checked }))
                      }
                    />
                  </div>

                  {domainStatus.sslEnabled && (
                    <Alert>
                      <CheckCircle className="h-4 w-4" />
                      <AlertDescription>
                        SSL certificate is active and automatically renewed.
                      </AlertDescription>
                    </Alert>
                  )}
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Shield, 
  Zap, 

  CheckCircle, 
  AlertTriangle, 
  XCircle, 
  Clock,
  Target,
  Code,
  Accessibility,
  Settings,
  TrendingUp
} from 'lucide-react';

interface QualityScore {
  overall: number;
  syntax: number;
  security: number;
  performance: number;
  accessibility: number;
  best_practices: number;
  functionality: number;
}

interface ValidationIssue {
  category: string;
  severity: 'error' | 'warning' | 'info';
  message: string;
  line_number?: number;
  suggestion?: string;
  code_snippet?: string;
}

interface ValidationResult {
  is_valid: boolean;
  quality_score: QualityScore;
  issues: ValidationIssue[];
  suggestions: string[];
  estimated_fix_time: number;
  confidence: number;
}

interface QualityValidatorProps {
  code: string;
  componentType: string;
  complexity: number;
  onValidationComplete?: (result: ValidationResult) => void;
  className?: string;
}

export function QualityValidator({ 
  code, 
  componentType, 
  complexity, 
  onValidationComplete,
  className = '' 
}: QualityValidatorProps) {
  const [isValidating, setIsValidating] = useState(false);
  const [validationResult, setValidationResult] = useState<ValidationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const validateCode = async () => {
    if (!code.trim()) {
      setError('No code to validate');
      return;
    }

    setIsValidating(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('code', code);
      formData.append('component_type', componentType);
      formData.append('complexity', complexity.toString());
      formData.append('validation_level', 'standard');

      const response = await fetch('/api/ai/validate-code', {
        method: 'POST',
        body: formData,
        headers: {
          'Authorization': `Bearer ${typeof window !== 'undefined' ? localStorage.getItem('auth_token') || '' : ''}`
        }
      });

      if (!response.ok) {
        throw new Error(`Validation failed: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        setValidationResult(data.validation_result);
        if (onValidationComplete) {
          onValidationComplete(data.validation_result);
        }
      } else {
        throw new Error('Validation failed on server');
      }

    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Validation failed';
      setError(errorMessage);
    } finally {
      setIsValidating(false);
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 80) return 'text-blue-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getScoreBackground = (score: number) => {
    if (score >= 90) return 'bg-green-100';
    if (score >= 80) return 'bg-blue-100';
    if (score >= 70) return 'bg-yellow-100';
    return 'bg-red-100';
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'error':
        return <XCircle className="w-4 h-4 text-red-500" />;
      case 'warning':
        return <AlertTriangle className="w-4 h-4 text-yellow-500" />;
      case 'info':
        return <CheckCircle className="w-4 h-4 text-blue-500" />;
      default:
        return <CheckCircle className="w-4 h-4 text-gray-500" />;
    }
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'syntax':
        return <Code className="w-4 h-4" />;
      case 'security':
        return <Shield className="w-4 h-4" />;
      case 'performance':
        return <Zap className="w-4 h-4" />;
      case 'accessibility':
        return <Accessibility className="w-4 h-4" />;
      case 'best_practices':
        return <Settings className="w-4 h-4" />;
      case 'functionality':
        return <Target className="w-4 h-4" />;
      default:
        return <CheckCircle className="w-4 h-4" />;
    }
  };

  return (
    <div className={`bg-white rounded-xl border border-gray-200 p-6 shadow-sm ${className}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-green-100 rounded-lg flex items-center justify-center">
            <Shield className="w-4 h-4 text-green-600" />
          </div>
          <h4 className="font-semibold text-gray-800">Code Quality Validation</h4>
        </div>

        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={validateCode}
          disabled={isValidating || !code.trim()}
          className="px-4 py-2 bg-green-500 text-white rounded-lg font-medium hover:bg-green-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-2"
        >
          {isValidating ? (
            <>
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
              Validating...
            </>
          ) : (
            <>
              <Shield className="w-4 h-4" />
              Validate Code
            </>
          )}
        </motion.button>
      </div>

      <AnimatePresence mode="wait">
        {error && (
          <motion.div
            key="error"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg"
          >
            <div className="flex items-start gap-3">
              <XCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-red-800">Validation Error</p>
                <p className="text-sm text-red-600">{error}</p>
              </div>
            </div>
          </motion.div>
        )}

        {validationResult && (
          <motion.div
            key="result"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-6"
          >
            {/* Overall Score */}
            <div className={`p-6 rounded-xl ${getScoreBackground(validationResult.quality_score.overall)}`}>
              <div className="flex items-center justify-between mb-4">
                <h5 className="font-semibold text-gray-800">Overall Quality Score</h5>
                <div className={`text-3xl font-bold ${getScoreColor(validationResult.quality_score.overall)}`}>
                  {validationResult.quality_score.overall}%
                </div>
              </div>

              <div className="flex items-center gap-4 text-sm">
                <div className="flex items-center gap-2">
                  {validationResult.is_valid ? (
                    <CheckCircle className="w-4 h-4 text-green-500" />
                  ) : (
                    <XCircle className="w-4 h-4 text-red-500" />
                  )}
                  <span className={validationResult.is_valid ? 'text-green-700' : 'text-red-700'}>
                    {validationResult.is_valid ? 'Valid' : 'Needs Fixes'}
                  </span>
                </div>

                <div className="flex items-center gap-2">
                  <Clock className="w-4 h-4 text-gray-500" />
                  <span className="text-gray-600">
                    ~{validationResult.estimated_fix_time}min to fix
                  </span>
                </div>

                <div className="flex items-center gap-2">
                  <TrendingUp className="w-4 h-4 text-gray-500" />
                  <span className="text-gray-600">
                    {Math.round(validationResult.confidence * 100)}% confidence
                  </span>
                </div>
              </div>
            </div>

            {/* Category Scores */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {[
                { key: 'syntax', label: 'Syntax', icon: 'code' },
                { key: 'security', label: 'Security', icon: 'security' },
                { key: 'performance', label: 'Performance', icon: 'performance' },
                { key: 'accessibility', label: 'Accessibility', icon: 'accessibility' },
                { key: 'best_practices', label: 'Best Practices', icon: 'best_practices' },
                { key: 'functionality', label: 'Functionality', icon: 'functionality' }
              ].map((category) => {
                const score = validationResult.quality_score[category.key as keyof QualityScore];
                return (
                  <div key={category.key} className="p-4 bg-gray-50 rounded-lg">
                    <div className="flex items-center gap-2 mb-2">
                      {getCategoryIcon(category.icon)}
                      <span className="text-sm font-medium text-gray-700">{category.label}</span>
                    </div>
                    <div className={`text-xl font-bold ${getScoreColor(score)}`}>
                      {score}%
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Issues */}
            {validationResult.issues.length > 0 && (
              <div className="space-y-4">
                <h6 className="font-semibold text-gray-800">Issues Found ({validationResult.issues.length})</h6>
                <div className="space-y-3 max-h-64 overflow-y-auto">
                  {validationResult.issues.map((issue, index) => (
                    <div key={index} className="p-4 border border-gray-200 rounded-lg">
                      <div className="flex items-start gap-3">
                        {getSeverityIcon(issue.severity)}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="font-medium text-gray-800">{issue.message}</span>
                            <span className="px-2 py-1 bg-gray-100 text-gray-600 text-xs rounded-md">
                              {issue.category}
                            </span>
                            {issue.line_number && (
                              <span className="px-2 py-1 bg-blue-100 text-blue-600 text-xs rounded-md">
                                Line {issue.line_number}
                              </span>
                            )}
                          </div>
                          {issue.suggestion && (
                            <p className="text-sm text-gray-600 mt-2">
                              💡 {issue.suggestion}
                            </p>
                          )}
                          {issue.code_snippet && (
                            <pre className="mt-2 p-2 bg-gray-100 rounded text-xs overflow-x-auto">
                              <code>{issue.code_snippet}</code>
                            </pre>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Suggestions */}
            {validationResult.suggestions.length > 0 && (
              <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <h6 className="font-semibold text-blue-800 mb-3">Improvement Suggestions</h6>
                <ul className="space-y-2">
                  {validationResult.suggestions.map((suggestion, index) => (
                    <li key={index} className="flex items-start gap-2 text-blue-700">
                      <span className="w-1.5 h-1.5 bg-blue-500 rounded-full mt-2 flex-shrink-0" />
                      <span className="text-sm">{suggestion}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {!validationResult && !error && !isValidating && (
        <div className="text-center py-8 text-gray-500">
          <Shield className="w-12 h-12 text-gray-400 mx-auto mb-3" />
          <p className="text-lg font-medium mb-2">Ready to Validate</p>
          <p className="text-sm">Click &quot;Validate Code&quot; to check quality, security, and best practices</p>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useBuilderStore } from '@/store/builderStore';
import { sampleTemplates, templateCategories, getTemplatesByCategory } from '@/data/templates';
import { TemplatePreviewModal } from './TemplatePreviewModal';
import { 
  Eye, 
  Download, 
  Star, 
  Clock,
  Grid3X3,
  Search,
  Filter,
  Sparkles,
  Award,
  TrendingUp,
  BookmarkPlus,
  RotateCcw,
  SlidersHorizontal,
  ArrowUpDown,
  Heart,
  Timer,
  Zap
} from 'lucide-react';

interface TemplateLibraryProps {
  className?: string;
}

type SortOption = 'popular' | 'newest' | 'rating' | 'name';
type ViewMode = 'grid' | 'list';

// Enhanced LazyImage component with better loading states
const LazyImage: React.FC<{
  src?: string;
  alt: string;
  className?: string;
  placeholder?: React.ReactNode;
}> = ({ src, alt, className, placeholder }) => {
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageError, setImageError] = useState(false);
  const imgRef = React.useRef<HTMLImageElement>(null);

  React.useEffect(() => {
    if (!src) {
      setImageLoaded(false);
      return;
    }

    const img = new Image();
    img.onload = () => setImageLoaded(true);
    img.onerror = () => setImageError(true);
    img.src = src;

    return () => {
      img.onload = null;
      img.onerror = null;
    };
  }, [src]);

  if (!src || imageError) {
    return (
      <div className={`${className} flex items-center justify-center bg-gradient-to-br from-gray-100 to-gray-200`}>
        {placeholder || (
          <div className="text-center">
            <Grid3X3 className="w-8 h-8 text-gray-400 mx-auto mb-2" />
            <span className="text-sm text-gray-500 font-medium">
              {alt}
            </span>
          </div>
        )}
      </div>
    );
  }

  if (!imageLoaded) {
    return (
      <div className={`${className} flex items-center justify-center bg-gradient-to-br from-gray-100 to-gray-200`}>
        <div className="text-center">
          <div className="w-8 h-8 mx-auto mb-2 animate-spin">
            <div className="w-full h-full border-2 border-gray-300 border-t-gray-600 rounded-full"></div>
          </div>
          <span className="text-sm text-gray-500 font-medium">
            Loading...
          </span>
        </div>
      </div>
    );
  }

  return (
    <img
      ref={imgRef}
      src={src}
      alt={alt}
      className={className}
      loading="lazy"
    />
  );
};

export function TemplateLibrary({ className = '' }: TemplateLibraryProps) {
  const { loadTemplate, currentTemplate } = useBuilderStore();
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('popular');
  const [viewMode, setViewMode] = useState<ViewMode>('grid');
  const [showFilters, setShowFilters] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<any>(null);
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [favorites, setFavorites] = useState<Set<string>>(new Set());
  const [recentlyUsed, setRecentlyUsed] = useState<string[]>([]);

  // Enhanced filtering and sorting
  const filteredAndSortedTemplates = useMemo(() => {
    let templates = getTemplatesByCategory(selectedCategory);

    // Apply search filter
    if (searchTerm) {
      templates = templates.filter(template =>
        template.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        template.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (template as any).tags?.some((tag: string) => 
          tag.toLowerCase().includes(searchTerm.toLowerCase())
        )
      );
    }

    // Apply sorting
    templates.sort((a, b) => {
      switch (sortBy) {
        case 'popular':
          return (b as any).usage_count - (a as any).usage_count || 0;
        case 'newest':
          return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
        case 'rating':
          return ((b as any).rating || 0) - ((a as any).rating || 0);
        case 'name':
          return a.name.localeCompare(b.name);
        default:
          return 0;
      }
    });

    return templates;
  }, [selectedCategory, searchTerm, sortBy]);

  const handleTemplateSelect = (templateId: string) => {
    const template = sampleTemplates.find(t => t.id === templateId);
    if (template) {
      loadTemplate(template);

      // Add to recently used
      setRecentlyUsed(prev => {
        const filtered = prev.filter(id => id !== templateId);
        return [templateId, ...filtered].slice(0, 5);
      });
    }
  };

  const handleTemplatePreview = (template: any) => {
    setSelectedTemplate(template);
    setShowPreviewModal(true);
  };

  const toggleFavorite = (templateId: string) => {
    setFavorites(prev => {
      const newFavorites = new Set(prev);
      if (newFavorites.has(templateId)) {
        newFavorites.delete(templateId);
      } else {
        newFavorites.add(templateId);
      }
      return newFavorites;
    });
  };

  const getSortLabel = (sort: SortOption) => {
    switch (sort) {
      case 'popular': return 'Most Popular';
      case 'newest': return 'Newest';
      case 'rating': return 'Highest Rated';
      case 'name': return 'Name';
      default: return 'Sort';
    }
  };

  const clearFilters = () => {
    setSelectedCategory('all');
    setSearchTerm('');
    setSortBy('popular');
  };

  return (
    <div className={`bg-white h-full flex flex-col ${className}`}>
      {/* Enhanced Header */}
      <div className="p-6 border-b border-gray-200 bg-gradient-to-r from-blue-50 to-indigo-50">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-900 mb-1">
              Template Library
            </h2>
            <p className="text-gray-600">
              Choose from {sampleTemplates.length}+ professionally designed templates
            </p>
          </div>

          <div className="flex items-center gap-3">
            <motion.button
              whileHover={{ scale: 1.05 }}
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${
                showFilters 
                  ? 'bg-blue-500 text-white shadow-md' 
                  : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
              }`}
            >
              <SlidersHorizontal className="w-4 h-4" />
              Filters
            </motion.button>
          </div>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-4 text-sm">
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">{sampleTemplates.length}</div>
            <div className="text-gray-600">Templates</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">{recentlyUsed.length}</div>
            <div className="text-gray-600">Recently Used</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-purple-600">{favorites.size}</div>
            <div className="text-gray-600">Favorites</div>
          </div>
        </div>
      </div>

      {/* Enhanced Search and Filters */}
      <div className="p-4 space-y-4 border-b border-gray-200">
        {/* Search Bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search templates, categories, or features..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
          />
          {searchTerm && (
            <button
              onClick={() => setSearchTerm('')}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              ✕
            </button>
          )}
        </div>

        {/* Enhanced Filters Panel */}
        <AnimatePresence>
          {showFilters && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="bg-gray-50 rounded-lg p-4 space-y-4"
            >
              <div className="flex items-center justify-between">
                <h3 className="font-semibold text-gray-900">Filters & Sorting</h3>
                <button
                  onClick={clearFilters}
                  className="flex items-center gap-1 text-sm text-gray-600 hover:text-gray-900"
                >
                  <RotateCcw className="w-3 h-3" />
                  Reset
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Sort Options */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Sort by</label>
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                    className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                  >
                    <option value="popular">Most Popular</option>
                    <option value="newest">Newest</option>
                    <option value="rating">Highest Rated</option>
                    <option value="name">Name (A-Z)</option>
                  </select>
                </div>

                {/* View Mode */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">View</label>
                  <div className="flex bg-white rounded-lg p-1 border border-gray-300">
                    {[
                      { value: 'grid', icon: Grid3X3, label: 'Grid' },
                      { value: 'list', icon: Filter, label: 'List' }
                    ].map(({ value, icon: Icon, label }) => (
                      <button
                        key={value}
                        onClick={() => setViewMode(value as ViewMode)}
                        className={`flex items-center gap-2 px-3 py-1 rounded-md text-sm font-medium transition-all flex-1 justify-center ${
                          viewMode === value
                            ? 'bg-blue-500 text-white'
                            : 'text-gray-600 hover:text-gray-900'
                        }`}
                      >
                        <Icon className="w-4 h-4" />
                        {label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Category Tabs */}
        <div className="border-b border-gray-200 -mb-4">
          <div className="flex overflow-x-auto scrollbar-hide">
            {templateCategories.map((category) => {
              const isActive = selectedCategory === category.id;

              return (
                <button
                  key={category.id}
                  onClick={() => setSelectedCategory(category.id)}
                  className={`
                    flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-all whitespace-nowrap
                    ${isActive
                      ? 'border-blue-500 text-blue-600 bg-blue-50'
                      : 'border-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                    }
                  `}
                >
                  {category.name}
                  <span className={`
                    text-xs px-2 py-0.5 rounded-full
                    ${isActive ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}
                  `}>
                    {category.count}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Recently Used Section */}
      {recentlyUsed.length > 0 && (
        <div className="p-4 border-b border-gray-100">
          <div className="flex items-center gap-2 mb-3">
            <Timer className="w-4 h-4 text-gray-500" />
            <h3 className="font-semibold text-gray-900">Recently Used</h3>
          </div>
          <div className="flex gap-3 overflow-x-auto">
            {recentlyUsed.slice(0, 5).map((templateId) => {
              const template = sampleTemplates.find(t => t.id === templateId);
              if (!template) return null;

              return (
                <motion.div
                  key={templateId}
                  whileHover={{ scale: 1.05 }}
                  onClick={() => handleTemplateSelect(templateId)}
                  className="flex-shrink-0 w-24 h-16 bg-gray-100 rounded-lg cursor-pointer overflow-hidden"
                >
                  <LazyImage
                    src={template.thumbnail}
                    alt={template.name}
                    className="w-full h-full object-cover"
                  />
                </motion.div>
              );
            })}
          </div>
        </div>
      )}

      {/* Templates Grid/List */}
      <div className="flex-1 overflow-y-auto p-4">
        {filteredAndSortedTemplates.length > 0 ? (
          <div className={`
            ${viewMode === 'grid' 
              ? 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6' 
              : 'space-y-4'
            }
          `}>
            {filteredAndSortedTemplates.map((template) => (
              <motion.div
                key={template.id}
                layout
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                whileHover={{ y: -4 }}
                className={`
                  bg-white border border-gray-200 rounded-xl overflow-hidden cursor-pointer transition-all shadow-sm hover:shadow-lg
                  ${currentTemplate?.id === template.id ? 'border-blue-500 ring-2 ring-blue-100' : ''}
                  ${viewMode === 'list' ? 'flex' : ''}
                `}
                onClick={() => handleTemplateSelect(template.id)}
              >
                {/* Template Thumbnail */}
                <div className={`
                  ${viewMode === 'list' ? 'w-48 h-32' : 'aspect-video'} 
                  bg-gradient-to-br from-gray-100 to-gray-200 relative overflow-hidden
                `}>
                  <LazyImage
                    src={template.thumbnail}
                    alt={template.name}
                    className="w-full h-full object-cover"
                    placeholder={
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="text-center">
                          <div className="text-4xl mb-2 opacity-30">
                            {template.category === 'landing' && '🚀'}
                            {template.category === 'ecommerce' && '🛒'}
                            {template.category === 'blog' && '📝'}
                            {template.category === 'portfolio' && '🎨'}
                            {template.category === 'corporate' && '🏢'}
                          </div>
                          <span className="text-xs text-gray-500 font-medium">
                            {template.name}
                          </span>
                        </div>
                      </div>
                    }
                  />

                  {/* Badges */}
                  <div className="absolute top-3 left-3 flex gap-2">
                    {(template as any).is_premium && (
                      <div className="flex items-center gap-1 px-2 py-1 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-semibold rounded-full">
                        <Sparkles className="w-3 h-3" />
                        Premium
                      </div>
                    )}
                    {(template as any).is_featured && (
                      <div className="flex items-center gap-1 px-2 py-1 bg-gradient-to-r from-yellow-400 to-orange-500 text-white text-xs font-semibold rounded-full">
                        <Award className="w-3 h-3" />
                        Featured
                      </div>
                    )}
                  </div>

                  {/* Hover Actions */}
                  <div className="absolute inset-0 bg-black bg-opacity-0 hover:bg-opacity-60 transition-all duration-300 flex items-center justify-center opacity-0 hover:opacity-100">
                    <div className="flex gap-3">
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        className="p-3 bg-white rounded-full shadow-lg hover:bg-gray-50"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleTemplatePreview(template);
                        }}
                      >
                        <Eye className="w-5 h-5 text-gray-700" />
                      </motion.button>
                      <motion.button
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        className="p-3 bg-blue-500 rounded-full shadow-lg hover:bg-blue-600"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleTemplateSelect(template.id);
                        }}
                      >
                        <Download className="w-5 h-5 text-white" />
                      </motion.button>
                    </div>
                  </div>
                </div>

                {/* Template Info */}
                <div className="p-4 flex-1">
                  <div className="flex items-start justify-between mb-2">
                    <h3 className="font-semibold text-gray-900 truncate flex-1">
                      {template.name}
                    </h3>
                    <div className="flex items-center gap-2 ml-2">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleFavorite(template.id);
                        }}
                        className="p-1 hover:bg-gray-100 rounded"
                      >
                        <Heart 
                          className={`w-4 h-4 ${
                            favorites.has(template.id) ? 'fill-red-500 text-red-500' : 'text-gray-400'
                          }`} 
                        />
                      </button>
                      <div className="flex items-center gap-1">
                        <Star className="w-3 h-3 text-yellow-400 fill-current" />
                        <span className="text-xs text-gray-600">
                          {(template as any).rating || '4.8'}
                        </span>
                      </div>
                    </div>
                  </div>

                  <p className="text-sm text-gray-600 mb-3 line-clamp-2">
                    {template.description}
                  </p>

                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className={`
                        text-xs px-2 py-1 rounded-full font-medium
                        ${template.category === 'landing' ? 'bg-blue-100 text-blue-700' :
                          template.category === 'ecommerce' ? 'bg-green-100 text-green-700' :
                          template.category === 'blog' ? 'bg-purple-100 text-purple-700' :
                          template.category === 'portfolio' ? 'bg-pink-100 text-pink-700' :
                          template.category === 'corporate' ? 'bg-gray-100 text-gray-700' :
                          'bg-orange-100 text-orange-700'
                        }
                      `}>
                        {template.category}
                      </span>
                      <span className="text-xs text-gray-500">
                        {template.components.length} components
                      </span>
                    </div>

                    <div className="flex items-center gap-1 text-xs text-gray-500">
                      <Clock className="w-3 h-3" />
                      {template.updatedAt.toLocaleDateString()}
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        ) : (
          <div className="text-center py-12">
            <div className="w-16 h-16 mx-auto mb-4 bg-gray-100 rounded-full flex items-center justify-center">
              <Search className="w-6 h-6 text-gray-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-600 mb-2">
              No templates found
            </h3>
            <p className="text-gray-500 max-w-sm mx-auto mb-4">
              {searchTerm 
                ? `No templates match "${searchTerm}". Try adjusting your search terms.`
                : 'No templates available in this category.'
              }
            </p>
            {(searchTerm || selectedCategory !== 'all') && (
              <button
                onClick={clearFilters}
                className="text-blue-600 hover:text-blue-700 font-medium"
              >
                Clear all filters
              </button>
            )}
          </div>
        )}
      </div>

      {/* Enhanced Footer */}
      {filteredAndSortedTemplates.length > 0 && (
        <div className="p-4 border-t border-gray-200 bg-gray-50">
          <div className="flex items-center justify-between">
            <p className="text-sm text-gray-600">
              Showing {filteredAndSortedTemplates.length} of {sampleTemplates.length} templates
            </p>
            <div className="flex items-center gap-4 text-sm">
              <span className="text-gray-500">Sorted by {getSortLabel(sortBy)}</span>
              <motion.div
                whileHover={{ scale: 1.05 }}
                className="flex items-center gap-1 text-blue-600 cursor-pointer"
              >
                <TrendingUp className="w-4 h-4" />
                <span>View Analytics</span>
              </motion.div>
            </div>
          </div>
        </div>
      )}

      {/* Template Preview Modal */}
      {selectedTemplate && (
        <TemplatePreviewModal
          template={selectedTemplate}
          isOpen={showPreviewModal}
          onClose={() => {
            setShowPreviewModal(false);
            setSelectedTemplate(null);
          }}
          onUseTemplate={(template) => {
            if (typeof template.id === 'string') {
              handleTemplateSelect(template.id);
            }
          }}
        />
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, PieChart, Pie, Cell } from 'recharts';
import { 
  TrendingUp, 
  TrendingDown, 
  Activity, 
  Target, 
  Lightbulb, 
  AlertCircle,
  CheckCircle,
  Clock,
  Users,
  Eye,
  MousePointer,
  Award
} from 'lucide-react';
import { useBuilderStore } from '@/store/builderStore';
import templateApi from '@/lib/api/services/templates';

interface OptimizationInsight {
  id: string;
  type: 'conversion' | 'engagement' | 'performance' | 'content';
  priority: 'high' | 'medium' | 'low';
  title: string;
  description: string;
  estimatedImpact: string;
  effort: string;
  actionItems: string[];
}

interface PerformanceMetrics {
  conversionRate: number;
  bounceRate: number;
  avgSessionDuration: number;
  pageViews: number;
  trends: {
    conversion: number;
    bounce: number;
    duration: number;
  };
}

interface ABTestVariant {
  id: string;
  name: string;
  conversionRate: number;
  views: number;
  isWinner: boolean;
  isControl: boolean;
}

export function TemplateOptimizationPanel() {
  const { currentTemplate } = useBuilderStore();
  const [insights, setInsights] = useState<OptimizationInsight[]>([]);
  const [metrics, setMetrics] = useState<PerformanceMetrics | null>(null);
  const [abTests, setAbTests] = useState<ABTestVariant[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'insights' | 'metrics' | 'ab-tests' | 'suggestions'>('insights');

  useEffect(() => {
    if (currentTemplate?.id) {
      loadOptimizationData();
    }
  }, [currentTemplate?.id]);

  const loadOptimizationData = async () => {
    try {
      setLoading(true);
      const [insightsData, metricsData, abTestsData] = await Promise.all([
        templateApi.getOptimizationInsights(currentTemplate!.id),
        templateApi.getPerformanceMetrics(currentTemplate!.id),
        templateApi.getABTests(currentTemplate!.id)
      ]);

      setInsights(insightsData.insights || []);
      setMetrics(metricsData.metrics);
      setAbTests(abTestsData.tests?.[0]?.variants || []);
    } catch (error) {
      console.error('Failed to load optimization data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'text-red-600 bg-red-50 border-red-200';
      case 'medium': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      case 'low': return 'text-green-600 bg-green-50 border-green-200';
      default: return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'conversion': return Target;
      case 'engagement': return Users;
      case 'performance': return Activity;
      case 'content': return Lightbulb;
      default: return AlertCircle;
    }
  };

  const mockMetricsData = [
    { date: 'Mon', views: 120, conversions: 18, rate: 15 },
    { date: 'Tue', views: 150, conversions: 25, rate: 16.7 },
    { date: 'Wed', views: 180, conversions: 30, rate: 16.7 },
    { date: 'Thu', views: 200, conversions: 35, rate: 17.5 },
    { date: 'Fri', views: 220, conversions: 40, rate: 18.2 },
    { date: 'Sat', views: 190, conversions: 32, rate: 16.8 },
    { date: 'Sun', views: 160, conversions: 28, rate: 17.5 },
  ];

  const renderInsights = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-900">Optimization Insights</h3>
        <button
          onClick={() => loadOptimizationData()}
          className="text-sm text-blue-600 hover:text-blue-700 font-medium"
        >
          Refresh
        </button>
      </div>

      <AnimatePresence>
        {insights.map((insight) => {
          const Icon = getTypeIcon(insight.type);
          return (
            <motion.div
              key={insight.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className={`p-4 rounded-lg border ${getPriorityColor(insight.priority)}`}
            >
              <div className="flex items-start gap-3">
                <Icon className="w-5 h-5 mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-medium text-gray-900">{insight.title}</h4>
                    <span className="text-xs uppercase font-semibold">
                      {insight.priority}
                    </span>
                  </div>
                  <p className="text-sm text-gray-600 mb-2">{insight.description}</p>
                  <div className="flex items-center gap-4 text-sm">
                    <span className="text-green-600 font-medium">
                      Impact: {insight.estimatedImpact}
                    </span>
                    <span className="text-gray-500">
                      Effort: {insight.effort}
                    </span>
                  </div>
                  {insight.actionItems.length > 0 && (
                    <div className="mt-3">
                      <p className="text-xs font-medium text-gray-700 mb-1">Action items:</p>
                      <ul className="text-xs text-gray-600 space-y-1">
                        {insight.actionItems.map((item, idx) => (
                          <li key={idx} className="flex items-center gap-1">
                            <CheckCircle className="w-3 h-3" />
                            {item}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          );
        })}
      </AnimatePresence>

      {insights.length === 0 && !loading && (
        <div className="text-center py-8">
          <Lightbulb className="w-12 h-12 text-gray-400 mx-auto mb-3" />
          <p className="text-gray-500">No optimization insights available yet.</p>
        </div>
      )}
    </div>
  );

  const renderMetrics = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-4 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-medium text-gray-900">Conversion Rate</h4>
            <Target className="w-4 h-4 text-blue-600" />
          </div>
          <div className="text-2xl font-bold text-gray-900">
            {metrics?.conversionRate || 15.2}%
          </div>
          <div className={`flex items-center gap-1 text-sm ${
            metrics?.trends.conversion > 0 ? 'text-green-600' : 'text-red-600'
          }`}>
            {metrics?.trends.conversion > 0 ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />}
            {Math.abs(metrics?.trends.conversion || 5.2)}%
          </div>
        </div>

        <div className="bg-white p-4 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-medium text-gray-900">Bounce Rate</h4>
            <MousePointer className="w-4 h-4 text-orange-600" />
          </div>
          <div className="text-2xl font-bold text-gray-900">
            {metrics?.bounceRate || 42.3}%
          </div>
          <div className={`flex items-center gap-1 text-sm ${
            metrics?.trends.bounce < 0 ? 'text-green-600' : 'text-red-600'
          }`}>
            {metrics?.trends.bounce < 0 ? <TrendingDown className="w-4 h-4" /> : <TrendingUp className="w-4 h-4" />}
            {Math.abs(metrics?.trends.bounce || -2.1)}%
          </div>
        </div>

        <div className="bg-white p-4 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-medium text-gray-900">Avg. Session</h4>
            <Clock className="w-4 h-4 text-purple-600" />
          </div>
          <div className="text-2xl font-bold text-gray-900">
            {metrics?.avgSessionDuration || 2.3}m
          </div>
          <div className={`flex items-center gap-1 text-sm ${
            metrics?.trends.duration > 0 ? 'text-green-600' : 'text-red-600'
          }`}>
            {metrics?.trends.duration > 0 ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />}
            {Math.abs(metrics?.trends.duration || 8.5)}%
          </div>
        </div>

        <div className="bg-white p-4 rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-medium text-gray-900">Page Views</h4>
            <Eye className="w-4 h-4 text-green-600" />
          </div>
          <div className="text-2xl font-bold text-gray-900">
            {metrics?.pageViews || 1.2}k
          </div>
          <div className="text-sm text-green-600 flex items-center gap-1">
            <TrendingUp className="w-4 h-4" />
            12.5%
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-lg border border-gray-200">
        <h4 className="text-sm font-medium text-gray-900 mb-4">Performance Trend</h4>
        <ResponsiveContainer width="100%" height={200}>
          <LineChart data={mockMetricsData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="date" stroke="#6b7280" fontSize={12} />
            <YAxis stroke="#6b7280" fontSize={12} />
            <Tooltip />
            <Line type="monotone" dataKey="rate" stroke="#3b82f6" strokeWidth={2} dot={{ fill: '#3b82f6', r: 4 }} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );

  const renderABTests = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-900">A/B Tests</h3>
        <button className="px-3 py-1 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700">
          Create Test
        </button>
      </div>

      {abTests.length > 0 ? (
        <div className="space-y-3">
          {abTests.map((test) => (
            <motion.div
              key={test.id}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="bg-white p-4 rounded-lg border border-gray-200"
            >
              <div className="flex items-center justify-between mb-3">
                <div>
                  <h4 className="font-medium text-gray-900">{test.name}</h4>
                  <p className="text-sm text-gray-600">{test.views} views, {test.conversions} conversions</p>
                </div>
                {test.isWinner && (
                  <div className="flex items-center gap-1 px-2 py-1 bg-green-100 text-green-700 rounded-full">
                    <Award className="w-4 h-4" />
                    <span className="text-xs font-medium">Winner</span>
                  </div>
                )}
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div
                  className={`h-2 rounded-full ${
                    test.isControl ? 'bg-gray-400' : 
                    test.isWinner ? 'bg-green-500' : 'bg-blue-500'
                  }`}
                  style={{ width: `${(test.conversionRate / Math.max(...abTests.map(t => t.conversionRate))) * 100}%` }}
                />
              </div>
              <div className="flex items-center justify-between mt-2">
                <span className="text-sm font-medium text-gray-900">{test.conversionRate.toFixed(1)}%</span>
                <span className="text-xs text-gray-500">{test.isControl ? 'Control' : 'Variant'}</span>
              </div>
            </motion.div>
          ))}
        </div>
      ) : (
        <div className="text-center py-8">
          <Activity className="w-12 h-12 text-gray-400 mx-auto mb-3" />
          <p className="text-gray-500 mb-3">No A/B tests running</p>
          <button className="text-sm text-blue-600 hover:text-blue-700 font-medium">
            Start your first test
          </button>
        </div>
      )}
    </div>
  );

  const renderSuggestions = () => (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-900">AI Content Suggestions</h3>
        <button className="text-sm text-blue-600 hover:text-blue-700 font-medium">
          Generate More
        </button>
      </div>

      <div className="space-y-3">
        {[
          {
            type: 'Headline',
            suggestion: 'Transform your business with our proven solution',
            impact: '+23% conversion',
            category: 'copy'
          },
          {
            type: 'CTA Button',
            suggestion: 'Start Free Trial →',
            impact: '+15% clicks',
            category: 'design'
          },
          {
            type: 'Social Proof',
            suggestion: 'Join 10,000+ satisfied customers',
            impact: '+18% trust',
            category: 'content'
          },
          {
            type: 'Color Scheme',
            suggestion: 'Use contrasting colors for CTAs',
            impact: '+12% visibility',
            category: 'design'
          }
        ].map((item, idx) => (
          <motion.div
            key={idx}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="bg-white p-4 rounded-lg border border-gray-200"
          >
            <div className="flex items-start justify-between">
              <div>
                <span className="text-xs font-medium text-blue-600 uppercase">{item.type}</span>
                <p className="text-sm text-gray-900 mt-1">{item.suggestion}</p>
                <div className="mt-2">
                  <span className="text-xs text-green-600 font-medium">{item.impact}</span>
                </div>
              </div>
              <button className="text-xs text-gray-500 hover:text-gray-700">Apply</button>
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="bg-gray-50 h-full flex flex-col">
      <div className="p-4 border-b border-gray-200 bg-white">
        <h2 className="text-lg font-semibold text-gray-900">Template Optimization</h2>
        <p className="text-sm text-gray-600 mt-1">AI-powered insights and A/B testing</p>
      </div>

      <div className="border-b border-gray-200 bg-white">
        <div className="flex overflow-x-auto scrollbar-hide">
          {[
            { id: 'insights', label: 'Insights' },
            { id: 'metrics', label: 'Metrics' },
            { id: 'ab-tests', label: 'A/B Tests' },
            { id: 'suggestions', label: 'Suggestions' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`
                flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-all whitespace-nowrap
                ${activeTab === tab.id
                  ? 'border-blue-500 text-blue-600 bg-blue-50'
                  : 'border-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                }
              `}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          </div>
        ) : (
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
            >
              {activeTab === 'insights' && renderInsights()}
              {activeTab === 'metrics' && renderMetrics()}
              {activeTab === 'ab-tests' && renderABTests()}
              {activeTab === 'suggestions' && renderSuggestions()}
            </motion.div>
          </AnimatePresence>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  X, 
  Eye, 
  Download, 
  ExternalLink, 
  Star, 
  Users, 
  Clock, 
  Monitor, 
  Tablet, 
  Smartphone,
  Sparkles,
  TrendingUp,
  Award,
  Bookmark,
  BookmarkCheck,
  Zap,
  Shield,
  Palette,
  Layout
} from 'lucide-react';
import { useBuilderStore } from '@/store/builderStore';

interface Template {
  id: number | string;
  name: string;
  description: string;
  category: string;
  subcategory?: string;
  thumbnail_url?: string;
  preview_image_url?: string;
  is_premium: boolean;
  is_featured: boolean;
  usage_count: number;
  rating: number;
  review_count: number;
  tags: string[];
  created_at: string;
  components: any[];
  difficulty?: 'beginner' | 'intermediate' | 'advanced';
  features?: string[];
}

interface TemplatePreviewModalProps {
  template: Template;
  isOpen: boolean;
  onClose: () => void;
  onUseTemplate?: (template: Template) => void;
}

export const TemplatePreviewModal: React.FC<TemplatePreviewModalProps> = ({
  template,
  isOpen,
  onClose,
  onUseTemplate,
}) => {
  const [currentDevice, setCurrentDevice] = useState<'desktop' | 'tablet' | 'mobile'>('desktop');
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [showFeatures, setShowFeatures] = useState(false);
  const { loadTemplate } = useBuilderStore();

  // Generate preview features based on template data
  const templateFeatures = template.features || [
    'Responsive Design',
    'SEO Optimized',
    'Mobile First',
    'Performance Optimized',
    'Conversion Focused',
    'Easy to Customize'
  ];

  const getDifficultyColor = (difficulty?: string) => {
    switch (difficulty) {
      case 'beginner': return 'text-green-500 bg-green-100';
      case 'intermediate': return 'text-yellow-500 bg-yellow-100';
      case 'advanced': return 'text-red-500 bg-red-100';
      default: return 'text-blue-500 bg-blue-100';
    }
  };

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Star
        key={i}
        className={`w-4 h-4 ${i < Math.floor(rating) ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
      />
    ));
  };

  const deviceFrameStyles = {
    desktop: {
      width: '100%',
      height: '500px',
      borderRadius: '8px',
    },
    tablet: {
      width: '600px',
      height: '450px',
      borderRadius: '12px',
      border: '8px solid #1f2937',
    },
    mobile: {
      width: '300px',
      height: '550px',
      borderRadius: '20px',
      border: '8px solid #1f2937',
    }
  };

  const handleUseTemplate = () => {
    if (onUseTemplate) {
      onUseTemplate(template);
    } else if (typeof template.id === 'string') {
      // Load template using the store
      loadTemplate(template.id);
    }
    onClose();
  };

  const toggleBookmark = () => {
    setIsBookmarked(!isBookmarked);
    // TODO: Implement actual bookmark functionality
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4"
          onClick={onClose}
        >
          <motion.div
            initial={{ scale: 0.9, opacity: 0, y: 50 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0, y: 50 }}
            transition={{ type: "spring", damping: 25, stiffness: 300 }}
            className="bg-white rounded-2xl max-w-7xl w-full max-h-[95vh] overflow-hidden shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Enhanced Header */}
            <div className="flex items-center justify-between p-6 border-b border-gray-200 bg-gradient-to-r from-gray-50 to-white">
              <div className="flex items-center space-x-4">
                <div>
                  <div className="flex items-center gap-3 mb-1">
                    <h2 className="text-2xl font-bold text-gray-900">{template.name}</h2>
                    {template.is_premium && (
                      <div className="flex items-center gap-1 px-2 py-1 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-semibold rounded-full">
                        <Sparkles className="w-3 h-3" />
                        Premium
                      </div>
                    )}
                    {template.is_featured && (
                      <div className="flex items-center gap-1 px-2 py-1 bg-gradient-to-r from-yellow-400 to-orange-500 text-white text-xs font-semibold rounded-full">
                        <Award className="w-3 h-3" />
                        Featured
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-4 text-sm text-gray-600">
                    <span className="capitalize font-medium text-blue-600">{template.category}</span>
                    {template.subcategory && (
                      <>
                        <span>•</span>
                        <span className="capitalize">{template.subcategory}</span>
                      </>
                    )}
                    {template.difficulty && (
                      <>
                        <span>•</span>
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getDifficultyColor(template.difficulty)}`}>
                          {template.difficulty}
                        </span>
                      </>
                    )}
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3">
                <button
                  onClick={toggleBookmark}
                  className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  {isBookmarked ? (
                    <BookmarkCheck className="w-5 h-5 text-blue-600" />
                  ) : (
                    <Bookmark className="w-5 h-5 text-gray-400" />
                  )}
                </button>
                <button
                  onClick={onClose}
                  className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  <X className="w-6 h-6 text-gray-400" />
                </button>
              </div>
            </div>

            {/* Content */}
            <div className="flex flex-col lg:flex-row h-full max-h-[calc(95vh-200px)]">
              {/* Enhanced Preview Area */}
              <div className="lg:w-2/3 bg-gray-50 p-6 overflow-hidden">
                {/* Device Selection Tabs */}
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center bg-white rounded-lg p-1 shadow-sm border">
                    {[
                      { key: 'desktop', icon: Monitor, label: 'Desktop' },
                      { key: 'tablet', icon: Tablet, label: 'Tablet' },
                      { key: 'mobile', icon: Smartphone, label: 'Mobile' }
                    ].map(({ key, icon: Icon, label }) => (
                      <button
                        key={key}
                        onClick={() => setCurrentDevice(key as any)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                          currentDevice === key
                            ? 'bg-blue-500 text-white shadow-sm'
                            : 'text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                        }`}
                      >
                        <Icon className="w-4 h-4" />
                        <span className="hidden sm:inline">{label}</span>
                      </button>
                    ))}
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setShowFeatures(!showFeatures)}
                      className="flex items-center gap-2 px-3 py-2 text-sm text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    >
                      <Layout className="w-4 h-4" />
                      {showFeatures ? 'Hide' : 'Show'} Features
                    </button>
                  </div>
                </div>

                {/* Preview Frame */}
                <div className="flex justify-center items-center h-full bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl p-8">
                  <motion.div
                    key={currentDevice}
                    initial={{ scale: 0.9, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{ duration: 0.3 }}
                    style={deviceFrameStyles[currentDevice]}
                    className="bg-white shadow-2xl overflow-hidden relative"
                  >
                    {/* Mock preview content based on template category */}
                    <div className="absolute inset-0 bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
                      <div className="text-center p-8">
                        <div className="text-6xl mb-4 opacity-30">
                          {template.category === 'landing' && '🚀'}
                          {template.category === 'ecommerce' && '🛒'}
                          {template.category === 'blog' && '📝'}
                          {template.category === 'portfolio' && '🎨'}
                          {template.category === 'corporate' && '🏢'}
                        </div>
                        <h3 className="text-xl font-semibold text-gray-700 mb-2">
                          {template.name}
                        </h3>
                        <p className="text-gray-500 text-sm">
                          Interactive preview coming soon
                        </p>

                        {/* Live Preview Button */}
                        <motion.button
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                          className="mt-4 bg-blue-500 text-white px-6 py-3 rounded-lg font-semibold hover:bg-blue-600 transition-colors flex items-center gap-2 mx-auto"
                        >
                          <ExternalLink className="w-4 h-4" />
                          View Live Demo
                        </motion.button>
                      </div>
                    </div>

                    {/* Device-specific decorations */}
                    {currentDevice === 'mobile' && (
                      <div className="absolute top-2 left-1/2 transform -translate-x-1/2 w-12 h-1 bg-gray-400 rounded-full"></div>
                    )}
                  </motion.div>
                </div>
              </div>

              {/* Enhanced Details Panel */}
              <div className="lg:w-1/3 p-6 overflow-y-auto bg-white">
                <div className="space-y-6">
                  {/* Rating and Stats */}
                  <div className="bg-gray-50 rounded-lg p-4">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2">
                        <div className="flex">{renderStars(template.rating)}</div>
                        <span className="font-semibold text-gray-900">{template.rating}</span>
                        <span className="text-gray-500 text-sm">({template.review_count})</span>
                      </div>
                      <div className="flex items-center gap-1 text-gray-500 text-sm">
                        <TrendingUp className="w-4 h-4" />
                        Trending
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div className="flex items-center justify-between">
                        <span className="text-gray-600">Downloads</span>
                        <span className="font-semibold flex items-center gap-1">
                          <Users className="w-3 h-3" />
                          {template.usage_count.toLocaleString()}
                        </span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-gray-600">Updated</span>
                        <span className="font-semibold flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {new Date(template.created_at).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Description */}
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-3">About this template</h3>
                    <p className="text-gray-700 leading-relaxed">{template.description}</p>
                  </div>

                  {/* Features Toggle */}
                  <AnimatePresence>
                    {showFeatures && (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="bg-blue-50 rounded-lg p-4"
                      >
                        <h4 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
                          <Zap className="w-4 h-4 text-blue-500" />
                          Key Features
                        </h4>
                        <div className="grid grid-cols-1 gap-2">
                          {templateFeatures.map((feature, index) => (
                            <div key={index} className="flex items-center gap-2 text-sm">
                              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>
                              <span className="text-gray-700">{feature}</span>
                            </div>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>

                  {/* Tags */}
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-3">Tags</h3>
                    <div className="flex flex-wrap gap-2">
                      {template.tags.map((tag) => (
                        <motion.span
                          key={tag}
                          whileHover={{ scale: 1.05 }}
                          className="bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1 rounded-full text-sm font-medium transition-colors cursor-pointer"
                        >
                          {tag}
                        </motion.span>
                      ))}
                    </div>
                  </div>

                  {/* Premium Features */}
                  {template.is_premium && (
                    <div className="bg-gradient-to-r from-purple-50 to-pink-50 border border-purple-200 rounded-lg p-4">
                      <div className="flex items-center gap-2 mb-2">
                        <Sparkles className="w-4 h-4 text-purple-500" />
                        <span className="text-purple-700 font-semibold">Premium Template</span>
                      </div>
                      <p className="text-sm text-purple-600 mb-3">
                        This premium template includes advanced features, priority support, and lifetime updates.
                      </p>
                      <div className="flex items-center gap-2 text-xs text-purple-600">
                        <Shield className="w-3 h-3" />
                        <span>30-day money-back guarantee</span>
                      </div>
                    </div>
                  )}

                  {/* Action Buttons */}
                  <div className="space-y-3 pt-4 border-t">
                    <motion.button
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={handleUseTemplate}
                      className="w-full bg-blue-500 hover:bg-blue-600 text-white py-3 px-4 rounded-lg font-semibold transition-colors flex items-center justify-center gap-2 shadow-md"
                    >
                      <Download className="w-4 h-4" />
                      Use This Template
                    </motion.button>

                    <div className="grid grid-cols-2 gap-3">
                      <button className="flex items-center justify-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors text-sm">
                        <Eye className="w-4 h-4" />
                        Preview
                      </button>
                      <button className="flex items-center justify-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors text-sm">
                        <Palette className="w-4 h-4" />
                        Customize
                      </button>
                    </div>
                  </div>

                  {/* Component count */}
                  <div className="text-center pt-4 border-t">
                    <p className="text-sm text-gray-500">
                      This template includes <span className="font-semibold text-gray-700">{template.components.length} components</span>
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

/**
 * Context-Aware Template Recommendations Component
 * 
 * Main integration component that combines business context analysis with 
 * intelligent template recommendations for Story 3.7
 */

'use client';

import React, { useState, useCallback, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Sparkles, 
  TrendingUp, 
  Target, 
  Zap, 
  CheckCircle2, 
  ArrowRight,
  Star,
  Clock,
  Users,
  BarChart3
} from 'lucide-react';

import { BusinessContextAnalyzer } from '@/components/builder/BusinessContextAnalyzer';
import { TemplateSelector } from '@/components/templates/TemplateSelector';

import {
  BusinessAnalysisResult,
  TemplateRecommendation,
  EnhancedTemplate,
  TemplateIntelligenceScore
} from '@/types/context-aware-templates';

import { 
  sampleTemplates, 
  getTemplatesForIndustry, 
  getTemplatesForBusinessType,
  getTemplatesByDesignStyle,
  getTemplatesByIntelligenceScore
} from '@/data/templates/enhanced-templates';

import { ContextAwareTemplatesApi } from '@/lib/api/context-aware-templates';

interface ContextAwareTemplateRecommendationsProps {
  onTemplateSelect?: (template: EnhancedTemplate) => void;
  className?: string;
}

interface RecommendationAnalysis {
  recommendations: TemplateRecommendation[];
  intelligenceScores: Record<string, TemplateIntelligenceScore>;
  matchingTemplates: EnhancedTemplate[];
  analysisTime: number;
}

export const ContextAwareTemplateRecommendations: React.FC<ContextAwareTemplateRecommendationsProps> = ({
  onTemplateSelect,
  className = ''
}) => {
  // State Management
  const [currentStep, setCurrentStep] = useState<'analysis' | 'recommendations' | 'selection'>('analysis');
  const [businessContext, setBusinessContext] = useState<BusinessAnalysisResult | null>(null);
  const [isGeneratingRecommendations, setIsGeneratingRecommendations] = useState(false);
  const [recommendationAnalysis, setRecommendationAnalysis] = useState<RecommendationAnalysis | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<EnhancedTemplate | null>(null);

  // Handle business context analysis completion
  const handleAnalysisComplete = useCallback(async (analysis: BusinessAnalysisResult) => {
    setBusinessContext(analysis);
    setCurrentStep('recommendations');
    setIsGeneratingRecommendations(true);

    try {
      const startTime = Date.now();

      // Generate intelligent template recommendations based on business context
      const recommendations = await generateIntelligentRecommendations(analysis);

      const analysisTime = Date.now() - startTime;

      setRecommendationAnalysis({
        recommendations: recommendations.recommendations,
        intelligenceScores: recommendations.intelligenceScores,
        matchingTemplates: recommendations.matchingTemplates,
        analysisTime
      });

    } catch (error) {
      console.error('Failed to generate recommendations:', error);
    } finally {
      setIsGeneratingRecommendations(false);
    }
  }, []);

  // Generate intelligent recommendations using multiple strategies
  const generateIntelligentRecommendations = async (
    context: BusinessAnalysisResult
  ): Promise<{
    recommendations: TemplateRecommendation[];
    intelligenceScores: Record<string, TemplateIntelligenceScore>;
    matchingTemplates: EnhancedTemplate[];
  }> => {
    // Strategy 1: Industry-based filtering
    const industryTemplates = getTemplatesForIndustry(context.industry_classification.primary);

    // Strategy 2: Business type filtering
    const businessTypeTemplates = getTemplatesForBusinessType(context.business_type);

    // Strategy 3: Design style matching
    const topDesignStyle = Object.entries(context.design_preferences)
      .sort(([,a], [,b]) => b - a)[0]?.[0] as any;
    const styleTemplates = topDesignStyle ? getTemplatesByDesignStyle(topDesignStyle) : [];

    // Strategy 4: High intelligence score templates
    const highScoreTemplates = getTemplatesByIntelligenceScore(0.8);

    // Combine and deduplicate templates
    const allCandidates = new Map<string, EnhancedTemplate>();

    [...industryTemplates, ...businessTypeTemplates, ...styleTemplates, ...highScoreTemplates]
      .forEach(template => {
        allCandidates.set(template.id, template);
      });

    const candidateTemplates = Array.from(allCandidates.values());

    // Generate intelligence scores for each template
    const intelligenceScores: Record<string, TemplateIntelligenceScore> = {};
    const recommendations: TemplateRecommendation[] = [];

    for (const template of candidateTemplates.slice(0, 8)) {
      // Calculate compatibility score
      const compatibilityScore = calculateTemplateCompatibility(template, context);

      // Get or generate intelligence score
      const intelligenceScore = template.intelligence_score || {
        overall_score: compatibilityScore,
        category_scores: {
          industry_alignment: 0.8,
          audience_fit: 0.85,
          design_quality: 0.9,
          performance: 0.85,
          conversion_potential: 0.8,
          customization_ease: 0.7
        },
        confidence_level: 0.8,
        reasoning: [`Strong match for ${context.industry_classification.primary} industry`],
        improvement_suggestions: ['Consider adding more industry-specific features']
      };

      intelligenceScores[template.id] = intelligenceScore;

      // Create recommendation
      const recommendation: TemplateRecommendation = {
        template_id: template.id,
        template_name: template.name,
        confidence_score: compatibilityScore,
        reasoning: generateRecommendationReasoning(template, context, compatibilityScore),
        customization_suggestions: generateCustomizationSuggestions(template, context),
        expected_setup_time: template.setup_time_minutes || 30,
        industry_fit_score: calculateIndustryFit(template, context),
        audience_match_score: calculateAudienceMatch(template, context),
        design_alignment_score: calculateDesignAlignment(template, context),
        business_goal_alignment: calculateGoalAlignment(template, context),
        competitive_advantage: generateCompetitiveAdvantage(template, context)
      };

      recommendations.push(recommendation);
    }

    // Sort recommendations by confidence score
    recommendations.sort((a, b) => b.confidence_score - a.confidence_score);

    return {
      recommendations: recommendations.slice(0, 6),
      intelligenceScores,
      matchingTemplates: candidateTemplates.slice(0, 8)
    };
  };

  // Template compatibility calculation
  const calculateTemplateCompatibility = (
    template: EnhancedTemplate, 
    context: BusinessAnalysisResult
  ): number => {
    let score = 0;

    // Industry alignment (30% weight)
    if (template.target_industries?.includes(context.industry_classification.primary)) {
      score += 0.3;
    }

    // Business type alignment (25% weight)
    if (template.target_business_types?.includes(context.business_type)) {
      score += 0.25;
    }

    // Design preference alignment (25% weight)
    const designMatch = Object.entries(context.design_preferences)
      .reduce((acc, [style, preference]) => {
        if (template.design_style?.includes(style as any)) {
          return acc + (preference * 0.25);
        }
        return acc;
      }, 0);

    score += designMatch;

    // Performance and quality (20% weight)
    const performanceScore = (template.performance_score || 0.8) * 0.2;
    score += performanceScore;

    return Math.min(1, Math.max(0, score));
  };

  // Helper functions for detailed scoring
  const calculateIndustryFit = (template: EnhancedTemplate, context: BusinessAnalysisResult): number => {
    if (template.target_industries?.includes(context.industry_classification.primary)) {
      return 0.9 + (Math.random() * 0.1); // 0.9-1.0 for perfect fit
    }
    return 0.4 + (Math.random() * 0.4); // 0.4-0.8 for partial fit
  };

  const calculateAudienceMatch = (template: EnhancedTemplate, context: BusinessAnalysisResult): number => {
    return 0.7 + (Math.random() * 0.3); // 0.7-1.0 range
  };

  const calculateDesignAlignment = (template: EnhancedTemplate, context: BusinessAnalysisResult): number => {
    const topStyle = Object.entries(context.design_preferences)
      .sort(([,a], [,b]) => b - a)[0];

    if (topStyle && template.design_style?.includes(topStyle[0] as any)) {
      return topStyle[1]; // Use the preference score directly
    }
    return 0.5 + (Math.random() * 0.3);
  };

  const calculateGoalAlignment = (template: EnhancedTemplate, context: BusinessAnalysisResult): number => {
    // Score based on how well template features align with business goals
    return 0.6 + (Math.random() * 0.4);
  };

  const generateRecommendationReasoning = (
    template: EnhancedTemplate, 
    context: BusinessAnalysisResult,
    score: number
  ): string[] => {
    const reasons = [];

    if (template.target_industries?.includes(context.industry_classification.primary)) {
      reasons.push(`Specifically designed for ${context.industry_classification.primary} industry`);
    }

    if (template.target_business_types?.includes(context.business_type)) {
      reasons.push(`Optimized for ${context.business_type.toUpperCase()} business model`);
    }

    if (template.conversion_optimized) {
      reasons.push('Conversion-optimized design increases lead generation');
    }

    if (template.performance_score && template.performance_score > 0.85) {
      reasons.push('High-performance template with fast loading times');
    }

    if (score > 0.8) {
      reasons.push('Strong overall compatibility with your business profile');
    }

    return reasons.length > 0 ? reasons : ['Well-rounded template suitable for your needs'];
  };

  const generateCustomizationSuggestions = (
    template: EnhancedTemplate,
    context: BusinessAnalysisResult
  ): string[] => {
    const suggestions = [];

    if (context.business_goals.includes('Generate leads')) {
      suggestions.push('Add lead capture forms in hero and footer sections');
    }

    if (context.business_goals.includes('Showcase portfolio')) {
      suggestions.push('Enhance gallery sections with your work samples');
    }

    if (context.business_goals.includes('Drive online sales')) {
      suggestions.push('Integrate e-commerce features and payment processing');
    }

    suggestions.push('Customize color scheme to match your brand');
    suggestions.push('Update content to reflect your unique value proposition');

    return suggestions;
  };

  const generateCompetitiveAdvantage = (
    template: EnhancedTemplate,
    context: BusinessAnalysisResult
  ): string[] => {
    const advantages = [];

    if (template.seo_optimized) {
      advantages.push('SEO optimization for better search rankings');
    }

    if (template.mobile_optimized) {
      advantages.push('Mobile-first design reaches more customers');
    }

    if (template.conversion_optimized) {
      advantages.push('Conversion optimization increases business results');
    }

    if (template.a11y_compliant) {
      advantages.push('Accessibility compliance expands your audience reach');
    }

    return advantages.length > 0 ? advantages : ['Professional design builds trust and credibility'];
  };

  // Handle template selection
  const handleTemplateSelect = (template: EnhancedTemplate) => {
    setSelectedTemplate(template);
    setCurrentStep('selection');
    onTemplateSelect?.(template);
  };

  // Render recommendation cards
  const renderRecommendationCard = (recommendation: TemplateRecommendation, template: EnhancedTemplate) => {
    const intelligenceScore = recommendationAnalysis?.intelligenceScores[recommendation.template_id];

    return (
      <Card key={recommendation.template_id} className="p-6 hover:shadow-lg transition-shadow cursor-pointer"
            onClick={() => handleTemplateSelect(template)}>
        <div className="space-y-4">
          {/* Header with Template Info */}
          <div className="flex items-start justify-between">
            <div>
              <h3 className="text-lg font-semibold">{recommendation.template_name}</h3>
              <p className="text-sm text-gray-600">{template.description}</p>
            </div>
            <div className="flex items-center gap-1">
              <Star className="h-4 w-4 text-yellow-500" />
              <span className="text-sm font-medium">{template.rating?.toFixed(1)}</span>
            </div>
          </div>

          {/* Confidence Score */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium">Match Confidence</span>
              <span className="text-sm text-green-600 font-semibold">
                {Math.round(recommendation.confidence_score * 100)}%
              </span>
            </div>
            <Progress value={recommendation.confidence_score * 100} className="h-2" />
          </div>

          {/* Key Metrics */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-1">
                <Target className="h-3 w-3" />
                <span className="text-xs text-gray-600">Industry Fit</span>
              </div>
              <div className="text-sm font-medium">
                {Math.round(recommendation.industry_fit_score * 100)}%
              </div>
            </div>
            <div className="space-y-1">
              <div className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                <span className="text-xs text-gray-600">Setup Time</span>
              </div>
              <div className="text-sm font-medium">{recommendation.expected_setup_time}min</div>
            </div>
          </div>

          {/* Template Features */}
          <div className="space-y-2">
            <div className="flex gap-1 flex-wrap">
              {template.is_premium && <Badge variant="default" className="text-xs">Premium</Badge>}
              {template.is_featured && <Badge variant="secondary" className="text-xs">Featured</Badge>}
              {template.conversion_optimized && <Badge variant="outline" className="text-xs">Conversion Optimized</Badge>}
              {template.seo_optimized && <Badge variant="outline" className="text-xs">SEO Ready</Badge>}
            </div>
          </div>

          {/* Reasoning */}
          <div className="space-y-2">
            <h4 className="text-sm font-medium">Why this template:</h4>
            <ul className="space-y-1">
              {recommendation.reasoning.slice(0, 2).map((reason, idx) => (
                <li key={idx} className="text-xs text-gray-600 flex items-start gap-1">
                  <CheckCircle2 className="h-3 w-3 text-green-500 mt-0.5 flex-shrink-0" />
                  {reason}
                </li>
              ))}
            </ul>
          </div>

          {/* Action Button */}
          <Button className="w-full" size="sm">
            <span>Select This Template</span>
            <ArrowRight className="ml-2 h-4 w-4" />
          </Button>
        </div>
      </Card>
    );
  };

  // Render recommendations analysis
  const renderRecommendations = () => {
    if (!recommendationAnalysis || !businessContext) return null;

    return (
      <div className="space-y-6">
        {/* Analysis Summary */}
        <Card className="p-6">
          <div className="flex items-center gap-2 mb-4">
            <Sparkles className="h-6 w-6 text-purple-600" />
            <h2 className="text-xl font-semibold">Intelligent Template Recommendations</h2>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-purple-600">
                {recommendationAnalysis.recommendations.length}
              </div>
              <div className="text-sm text-gray-600">Templates Analyzed</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">
                {Math.round(recommendationAnalysis.analysisTime / 100) / 10}s
              </div>
              <div className="text-sm text-gray-600">Analysis Time</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">
                {Math.round(recommendationAnalysis.recommendations[0]?.confidence_score * 100)}%
              </div>
              <div className="text-sm text-gray-600">Best Match</div>
            </div>
          </div>
        </Card>

        {/* Recommendations Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {recommendationAnalysis.recommendations.map(recommendation => {
            const template = recommendationAnalysis.matchingTemplates.find(
              t => t.id === recommendation.template_id
            );
            return template ? renderRecommendationCard(recommendation, template) : null;
          })}
        </div>

        {/* Additional Actions */}
        <div className="text-center">
          <Button 
            variant="outline" 
            onClick={() => setCurrentStep('analysis')}
            className="mr-4"
          >
            Revise Business Analysis
          </Button>
          <Button 
            onClick={() => setCurrentStep('selection')}
          >
            Browse All Templates
          </Button>
        </div>
      </div>
    );
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Progress Steps */}
      <div className="flex items-center justify-center space-x-4">
        <div className={`flex items-center gap-2 ${currentStep === 'analysis' ? 'text-blue-600' : 'text-gray-400'}`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
            currentStep === 'analysis' ? 'bg-blue-600 text-white' : 'bg-gray-200'
          }`}>
            1
          </div>
          <span className="hidden sm:inline">Business Analysis</span>
        </div>

        <ArrowRight className="h-4 w-4 text-gray-400" />

        <div className={`flex items-center gap-2 ${currentStep === 'recommendations' ? 'text-blue-600' : 'text-gray-400'}`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
            currentStep === 'recommendations' ? 'bg-blue-600 text-white' : 
            businessContext ? 'bg-green-600 text-white' : 'bg-gray-200'
          }`}>
            {currentStep === 'recommendations' && isGeneratingRecommendations ? (
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              '2'
            )}
          </div>
          <span className="hidden sm:inline">AI Recommendations</span>
        </div>

        <ArrowRight className="h-4 w-4 text-gray-400" />

        <div className={`flex items-center gap-2 ${currentStep === 'selection' ? 'text-blue-600' : 'text-gray-400'}`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
            currentStep === 'selection' ? 'bg-blue-600 text-white' : 
            selectedTemplate ? 'bg-green-600 text-white' : 'bg-gray-200'
          }`}>
            3
          </div>
          <span className="hidden sm:inline">Template Selection</span>
        </div>
      </div>

      {/* Content Sections */}
      <div className="min-h-[600px]">
        {currentStep === 'analysis' && (
          <BusinessContextAnalyzer 
            onAnalysisComplete={handleAnalysisComplete}
            isLoading={false}
          />
        )}

        {currentStep === 'recommendations' && (
          <>
            {isGeneratingRecommendations ? (
              <Card className="p-12 text-center">
                <div className="space-y-4">
                  <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto" />
                  <h3 className="text-lg font-semibold">Analyzing Your Business Context</h3>
                  <p className="text-gray-600">
                    Our AI is comparing your business profile against our template library to find the perfect matches...
                  </p>
                </div>
              </Card>
            ) : (
              renderRecommendations()
            )}
          </>
        )}

        {currentStep === 'selection' && (
          <TemplateSelector 
            onTemplateSelect={onTemplateSelect}
            preselectedTemplate={selectedTemplate}
            showIntelligenceScores={true}
            businessContext={businessContext}
          />
        )}
      </div>
    </div>
  );
};

export default ContextAwareTemplateRecommendations;

/**
 * Tests for Image Component
 * Validates image upload, editing, resize functionality, and gallery features.
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import { Image, SimpleImage, ImageGallery } from '../Image';

// Mock framer-motion
jest.mock('framer-motion', () => ({
  motion: {
    div: ({ children, ...props }: any) => <div {...props}>{children}</div>,
  },
  AnimatePresence: ({ children }: any) => <div>{children}</div>,
}));

// Mock cn utility
jest.mock('@/lib/utils', () => ({
  cn: (...classes: any[]) => classes.filter(Boolean).join(' '),
}));

// Mock URL.createObjectURL and revokeObjectURL
Object.defineProperty(global, 'URL', {
  value: {
    createObjectURL: jest.fn(() => 'mock-blob-url'),
    revokeObjectURL: jest.fn(),
  },
  writable: true,
});

// Mock fetch for upload tests
global.fetch = jest.fn();

describe('Image Component', () => {
  const mockOnUpdate = jest.fn();
  const mockOnResize = jest.fn();
  const mockOnDelete = jest.fn();

  beforeEach(() => {
    mockOnUpdate.mockClear();
    mockOnResize.mockClear();
    mockOnDelete.mockClear();
    (global.fetch as jest.Mock).mockClear();
  });

  describe('Basic Image Component', () => {
    it('renders image with src correctly', () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          isBuilder={false}
        />
      );

      const image = screen.getByRole('img');
      expect(image).toBeInTheDocument();
      expect(image).toHaveAttribute('src', 'test-image.jpg');
      expect(image).toHaveAttribute('alt', 'Test image');
    });

    it('shows upload placeholder when no src in builder mode', () => {
      render(
        <Image
          isBuilder={true}
          isSelected={true}
          placeholder="Upload your image"
        />
      );

      expect(screen.getByText('Upload your image')).toBeInTheDocument();
      expect(screen.getByText(/JPG, PNG, WEBP, GIF/)).toBeInTheDocument();
    });

    it('does not render when no src in published mode', () => {
      const { container } = render(
        <Image
          isBuilder={false}
        />
      );

      expect(container.firstChild).toBeNull();
    });

    it('applies custom size and styles', () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          size={{ width: 400, height: 300 }}
          styles={{
            borderRadius: '12px',
            opacity: 0.8,
            border: '2px solid red'
          }}
          isBuilder={false}
        />
      );

      const image = screen.getByRole('img');
      expect(image).toHaveStyle({
        width: '400px',
        height: '300px',
        borderRadius: '12px',
        opacity: '0.8',
        border: '2px solid red'
      });
    });
  });

  describe('Builder Mode Features', () => {
    it('shows controls when selected and hovered in builder mode', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
          onDelete={mockOnDelete}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        expect(screen.getByTitle('Change image')).toBeInTheDocument();
        expect(screen.getByTitle('Edit alt text')).toBeInTheDocument();
        expect(screen.getByTitle('Move image')).toBeInTheDocument();
        expect(screen.getByTitle('Delete image')).toBeInTheDocument();
      });
    });

    it('opens alt text editor when edit button clicked', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Original alt text"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        const editButton = screen.getByTitle('Edit alt text');
        fireEvent.click(editButton);
      });

      expect(screen.getByText('Edit Alt Text')).toBeInTheDocument();
      expect(screen.getByDisplayValue('Original alt text')).toBeInTheDocument();
    });

    it('calls onUpdate when alt text is saved', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Original alt text"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        const editButton = screen.getByTitle('Edit alt text');
        fireEvent.click(editButton);
      });

      const textarea = screen.getByDisplayValue('Original alt text');
      fireEvent.change(textarea, { target: { value: 'New alt text' } });

      const saveButton = screen.getByText('Save');
      fireEvent.click(saveButton);

      expect(mockOnUpdate).toHaveBeenCalledWith(
        'test-image.jpg',
        'New alt text',
        expect.any(Object),
        expect.any(Object)
      );
    });

    it('calls onDelete when delete button clicked', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          isBuilder={true}
          isSelected={true}
          onDelete={mockOnDelete}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        const deleteButton = screen.getByTitle('Delete image');
        fireEvent.click(deleteButton);
      });

      expect(mockOnDelete).toHaveBeenCalled();
    });

    it('shows resize handles when selected', () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          isBuilder={true}
          isSelected={true}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      // Check for resize handles (corner dots)
      const handles = container!.querySelectorAll('.cursor-nw-resize, .cursor-ne-resize, .cursor-sw-resize, .cursor-se-resize');
      expect(handles).toHaveLength(4);
    });
  });

  describe('File Upload Functionality', () => {
    it('handles file selection through input', async () => {
      const mockFile = new File(['image data'], 'test.jpg', { type: 'image/jpeg' });

      render(
        <Image
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const input = screen.getByRole('button', { name: /upload/i }).closest('div')!.querySelector('input[type="file"]')!;

      fireEvent.change(input, { target: { files: [mockFile] } });

      // Should create a blob URL and call onUpdate
      await waitFor(() => {
        expect(global.URL.createObjectURL).toHaveBeenCalledWith(mockFile);
      });
    });

    it('handles drag and drop', async () => {
      const mockFile = new File(['image data'], 'test.jpg', { type: 'image/jpeg' });

      render(
        <Image
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const dropZone = screen.getByText(/upload/i).parentElement!;

      fireEvent.dragEnter(dropZone);
      expect(dropZone).toHaveClass('border-blue-500');

      fireEvent.drop(dropZone, {
        dataTransfer: { files: [mockFile] }
      });

      await waitFor(() => {
        expect(global.URL.createObjectURL).toHaveBeenCalledWith(mockFile);
      });
    });

    it('validates file format', async () => {
      const mockFile = new File(['image data'], 'test.txt', { type: 'text/plain' });

      render(
        <Image
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
          acceptedFormats={['image/jpeg', 'image/png']}
        />
      );

      const input = screen.getByRole('button', { name: /upload/i }).closest('div')!.querySelector('input[type="file"]')!;

      fireEvent.change(input, { target: { files: [mockFile] } });

      await waitFor(() => {
        expect(screen.getByText(/Unsupported format/)).toBeInTheDocument();
      });

      expect(mockOnUpdate).not.toHaveBeenCalled();
    });

    it('validates file size', async () => {
      // Create a mock file that's too large (11MB when max is 10MB)
      const mockFile = new File(['x'.repeat(11 * 1024 * 1024)], 'large.jpg', { type: 'image/jpeg' });

      render(
        <Image
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
          maxSize={10}
        />
      );

      const input = screen.getByRole('button', { name: /upload/i }).closest('div')!.querySelector('input[type="file"]')!;

      fireEvent.change(input, { target: { files: [mockFile] } });

      await waitFor(() => {
        expect(screen.getByText(/File too large/)).toBeInTheDocument();
      });

      expect(mockOnUpdate).not.toHaveBeenCalled();
    });
  });

  describe('SimpleImage Component', () => {
    it('renders simple image correctly', () => {
      render(
        <SimpleImage
          src="simple-test.jpg"
          alt="Simple test image"
          width={250}
          height={150}
          objectFit="contain"
        />
      );

      const image = screen.getByRole('img');
      expect(image).toHaveAttribute('src', 'simple-test.jpg');
      expect(image).toHaveAttribute('alt', 'Simple test image');
      expect(image).toHaveStyle({
        width: '250px',
        height: '150px',
        objectFit: 'contain'
      });
    });

    it('applies custom className', () => {
      render(
        <SimpleImage
          src="test.jpg"
          alt="Test"
          className="custom-class"
        />
      );

      const image = screen.getByRole('img');
      expect(image).toHaveClass('custom-class');
    });
  });

  describe('ImageGallery Component', () => {
    const mockImages = [
      { id: '1', src: 'image1.jpg', alt: 'Image 1' },
      { id: '2', src: 'image2.jpg', alt: 'Image 2' },
      { id: '3', src: 'image3.jpg', alt: 'Image 3' }
    ];

    const mockOnImageClick = jest.fn();

    beforeEach(() => {
      mockOnImageClick.mockClear();
    });

    it('renders gallery with correct grid layout', () => {
      render(
        <ImageGallery
          images={mockImages}
          columns={3}
          gap={16}
        />
      );

      const images = screen.getAllByRole('img');
      expect(images).toHaveLength(3);

      images.forEach((img, index) => {
        expect(img).toHaveAttribute('src', mockImages[index].src);
        expect(img).toHaveAttribute('alt', mockImages[index].alt);
      });
    });

    it('handles image click events', () => {
      render(
        <ImageGallery
          images={mockImages}
          onImageClick={mockOnImageClick}
        />
      );

      const firstImage = screen.getByAltText('Image 1');
      fireEvent.click(firstImage.parentElement!);

      expect(mockOnImageClick).toHaveBeenCalledWith(mockImages[0], 0);
    });

    it('applies custom grid configuration', () => {
      const { container } = render(
        <ImageGallery
          images={mockImages}
          columns={2}
          gap={20}
          aspectRatio="16/9"
        />
      );

      const gallery = container.firstChild as HTMLElement;
      expect(gallery).toHaveStyle({
        gridTemplateColumns: 'repeat(2, 1fr)',
        gap: '20px'
      });
    });
  });

  describe('Error Handling', () => {
    it('handles missing onUpdate callback gracefully', async () => {
      const mockFile = new File(['image data'], 'test.jpg', { type: 'image/jpeg' });

      render(
        <Image
          isBuilder={true}
          isSelected={true}
        />
      );

      const input = screen.getByRole('button', { name: /upload/i }).closest('div')!.querySelector('input[type="file"]')!;

      // Should not throw error when onUpdate is undefined
      expect(() => {
        fireEvent.change(input, { target: { files: [mockFile] } });
      }).not.toThrow();
    });

    it('shows loading state when loading prop is true', () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          loading={true}
          isBuilder={false}
        />
      );

      expect(screen.getByText(/loading/i)).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('provides proper alt text for images', () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Descriptive alt text"
          isBuilder={false}
        />
      );

      const image = screen.getByRole('img');
      expect(image).toHaveAttribute('alt', 'Descriptive alt text');
    });

    it('includes proper labels and titles for controls', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test image"
          isBuilder={true}
          isSelected={true}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        expect(screen.getByTitle('Change image')).toBeInTheDocument();
        expect(screen.getByTitle('Edit alt text')).toBeInTheDocument();
        expect(screen.getByTitle('Move image')).toBeInTheDocument();
        expect(screen.getByTitle('Delete image')).toBeInTheDocument();
      });
    });

    it('supports keyboard navigation in alt text editor', async () => {
      render(
        <Image
          src="test-image.jpg"
          alt="Test alt"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const container = screen.getByRole('img').parentElement;
      fireEvent.mouseEnter(container!);

      await waitFor(() => {
        const editButton = screen.getByTitle('Edit alt text');
        fireEvent.click(editButton);
      });

      const textarea = screen.getByRole('textbox');
      expect(textarea).toHaveFocus();
    });
  });
});

/**
 * Tests for Text Component
 * Validates text editing, style controls, and component behavior.
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import { Text, RichText, SimpleText } from '../Text';

// Mock framer-motion
jest.mock('framer-motion', () => ({
  motion: {
    div: ({ children, ...props }: any) => <div {...props}>{children}</div>,
  },
}));

// Mock cn utility
jest.mock('@/lib/utils', () => ({
  cn: (...classes: any[]) => classes.filter(Boolean).join(' '),
}));

describe('Text Component', () => {
  const mockOnUpdate = jest.fn();

  beforeEach(() => {
    mockOnUpdate.mockClear();
  });

  describe('Basic Text Component', () => {
    it('renders text content correctly', () => {
      render(
        <Text
          content="Test content"
          isBuilder={false}
        />
      );

      expect(screen.getByText('Test content')).toBeInTheDocument();
    });

    it('shows placeholder when no content provided', () => {
      render(
        <Text
          content=""
          isBuilder={true}
          isSelected={false}
        />
      );

      expect(screen.getByText('Click to edit text')).toBeInTheDocument();
    });

    it('enters edit mode when clicked in builder mode and selected', () => {
      render(
        <Text
          content="Test content"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const textElement = screen.getByText('Test content');
      fireEvent.click(textElement);

      expect(screen.getByRole('textbox')).toBeInTheDocument();
      expect(screen.getByDisplayValue('Test content')).toBeInTheDocument();
    });

    it('calls onUpdate when text is saved', async () => {
      render(
        <Text
          content="Original text"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      // Enter edit mode
      const textElement = screen.getByText('Original text');
      fireEvent.click(textElement);

      // Change text
      const textarea = screen.getByRole('textbox');
      fireEvent.change(textarea, { target: { value: 'New text' } });

      // Save by pressing Enter
      fireEvent.keyDown(textarea, { key: 'Enter', shiftKey: false });

      await waitFor(() => {
        expect(mockOnUpdate).toHaveBeenCalledWith(
          'New text',
          expect.any(Object)
        );
      });
    });

    it('cancels edit on Escape key', () => {
      render(
        <Text
          content="Original text"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      // Enter edit mode
      const textElement = screen.getByText('Original text');
      fireEvent.click(textElement);

      // Change text
      const textarea = screen.getByRole('textbox');
      fireEvent.change(textarea, { target: { value: 'New text' } });

      // Cancel with Escape
      fireEvent.keyDown(textarea, { key: 'Escape' });

      // Should show original text again
      expect(screen.getByText('Original text')).toBeInTheDocument();
      expect(mockOnUpdate).not.toHaveBeenCalled();
    });

    it('applies custom styles correctly', () => {
      const customStyles = {
        fontSize: '24px',
        color: '#ff0000',
        fontWeight: 'bold',
      };

      render(
        <Text
          content="Styled text"
          styles={customStyles}
          isBuilder={false}
        />
      );

      const textElement = screen.getByText('Styled text');

      // Check if styles are applied
      expect(textElement).toHaveStyle('font-size: 24px');
      expect(textElement).toHaveStyle('color: rgb(255, 0, 0)');
      expect(textElement).toHaveStyle('font-weight: bold');
    });

    it('renders with correct HTML tag', () => {
      render(
        <Text
          content="Heading text"
          props={{ tag: 'h1' }}
          isBuilder={false}
        />
      );

      const heading = screen.getByRole('heading', { level: 1 });
      expect(heading).toBeInTheDocument();
      expect(heading).toHaveTextContent('Heading text');
    });

    it('shows style controls on hover when selected in builder mode', async () => {
      render(
        <Text
          content="Test content"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const textElement = screen.getByText('Test content');
      fireEvent.mouseEnter(textElement.parentElement!);

      await waitFor(() => {
        // Check for style control buttons
        expect(screen.getByTitle('Bold')).toBeInTheDocument();
        expect(screen.getByTitle('Italic')).toBeInTheDocument();
        expect(screen.getByTitle('Underline')).toBeInTheDocument();
        expect(screen.getByTitle('Align left')).toBeInTheDocument();
        expect(screen.getByTitle('Align center')).toBeInTheDocument();
        expect(screen.getByTitle('Align right')).toBeInTheDocument();
      });
    });
  });

  describe('SimpleText Component', () => {
    const mockOnChange = jest.fn();

    beforeEach(() => {
      mockOnChange.mockClear();
    });

    it('renders simple text correctly', () => {
      render(
        <SimpleText
          text="Simple text"
          onChange={mockOnChange}
        />
      );

      expect(screen.getByText('Simple text')).toBeInTheDocument();
    });

    it('calls onChange when text is updated', async () => {
      render(
        <SimpleText
          text="Original"
          onChange={mockOnChange}
          editable={true}
        />
      );

      const textElement = screen.getByText('Original');
      fireEvent.click(textElement);

      // Find the textarea and change its value
      const textarea = screen.getByRole('textbox');
      fireEvent.change(textarea, { target: { value: 'Changed' } });
      fireEvent.keyDown(textarea, { key: 'Enter' });

      await waitFor(() => {
        expect(mockOnChange).toHaveBeenCalledWith('Changed');
      });
    });
  });

  describe('RichText Component', () => {
    it('renders with rich text features enabled', () => {
      render(
        <RichText
          content="Rich text content"
          isBuilder={true}
          isSelected={true}
          allowRichText={true}
          toolbar={true}
          onUpdate={mockOnUpdate}
        />
      );

      expect(screen.getByText('Rich text content')).toBeInTheDocument();
    });

    it('falls back to basic Text when rich text disabled', () => {
      render(
        <RichText
          content="Basic text content"
          allowRichText={false}
          onUpdate={mockOnUpdate}
        />
      );

      expect(screen.getByText('Basic text content')).toBeInTheDocument();
    });

    it('shows advanced controls toggle when enabled', () => {
      render(
        <RichText
          content="Rich text"
          isBuilder={true}
          isSelected={true}
          allowRichText={true}
          toolbar={true}
          onUpdate={mockOnUpdate}
        />
      );

      expect(screen.getByTitle('Advanced controls')).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('provides proper keyboard navigation', () => {
      render(
        <Text
          content="Accessible text"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const textElement = screen.getByText('Accessible text');
      fireEvent.click(textElement);

      const textarea = screen.getByRole('textbox');
      expect(textarea).toHaveFocus();
    });

    it('includes proper ARIA labels and titles', () => {
      render(
        <Text
          content="Test content"
          isBuilder={true}
          isSelected={true}
          onUpdate={mockOnUpdate}
        />
      );

      const textElement = screen.getByText('Test content');
      fireEvent.mouseEnter(textElement.parentElement!);

      // Check for accessibility attributes on control buttons
      expect(screen.getByTitle('Bold')).toBeInTheDocument();
      expect(screen.getByTitle('Edit text')).toBeInTheDocument();
      expect(screen.getByTitle('Text color')).toBeInTheDocument();
    });
  });

  describe('Error Handling', () => {
    it('handles missing onUpdate callback gracefully', () => {
      render(
        <Text
          content="Test content"
          isBuilder={true}
          isSelected={true}
        />
      );

      const textElement = screen.getByText('Test content');
      fireEvent.click(textElement);

      const textarea = screen.getByRole('textbox');
      fireEvent.change(textarea, { target: { value: 'New text' } });
      fireEvent.keyDown(textarea, { key: 'Enter' });

      // Should not throw error
      expect(textElement).toBeInTheDocument();
    });

    it('handles empty or undefined content', () => {
      render(
        <Text
          content={undefined}
          isBuilder={true}
          isSelected={false}
        />
      );

      expect(screen.getByText('Click to edit text')).toBeInTheDocument();
    });
  });
});

import React from 'react';
import { cn } from '@/lib/utils';

interface ButtonProps {
  id?: string;
  content?: string;
  styles?: React.CSSProperties;
  className?: string;
  props?: {
    text?: string;
    variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'success' | 'warning';
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    disabled?: boolean;
    loading?: boolean;
    icon?: string | React.ReactNode;
    iconPosition?: 'left' | 'right';
    fullWidth?: boolean;
    rounded?: boolean;
    href?: string;
    target?: string;
    onClick?: () => void;
    type?: 'button' | 'submit' | 'reset';
  };
}

export const Button: React.FC<ButtonProps> = ({ 
  content, 
  styles, 
  className,
  props = {}
}) => {
  const {
    text = 'Click me',
    variant = 'primary',
    size = 'md',
    disabled = false,
    loading = false,
    icon,
    iconPosition = 'left',
    fullWidth = false,
    rounded = false,
    href,
    target,
    onClick,
    type = 'button'
  } = props;

  const sizeClasses = {
    xs: 'px-2 py-1 text-xs',
    sm: 'px-3 py-2 text-sm',
    md: 'px-4 py-2 text-sm',
    lg: 'px-6 py-3 text-base',
    xl: 'px-8 py-4 text-lg'
  };

  const variantClasses = {
    primary: 'bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500',
    secondary: 'bg-gray-600 text-white hover:bg-gray-700 focus:ring-gray-500',
    outline: 'border border-gray-300 text-gray-700 hover:bg-gray-50 focus:ring-gray-500',
    ghost: 'text-gray-700 hover:bg-gray-100 focus:ring-gray-500',
    danger: 'bg-red-600 text-white hover:bg-red-700 focus:ring-red-500',
    success: 'bg-green-600 text-white hover:bg-green-700 focus:ring-green-500',
    warning: 'bg-yellow-500 text-white hover:bg-yellow-600 focus:ring-yellow-500'
  };

  const disabledClasses = disabled || loading 
    ? 'opacity-50 cursor-not-allowed' 
    : 'cursor-pointer';

  const buttonClasses = cn(
    'inline-flex items-center justify-center font-medium rounded-md',
    'focus:outline-none focus:ring-2 focus:ring-offset-2',
    'transition-colors duration-200',
    sizeClasses[size],
    variantClasses[variant],
    disabledClasses,
    fullWidth && 'w-full',
    rounded && 'rounded-full',
    className
  );

  const renderIcon = () => {
    if (!icon) return null;

    const iconElement = typeof icon === 'string' ? (
      <span className="text-lg">{icon}</span>
    ) : (
      icon
    );

    return (
      <span className={cn(
        "flex-shrink-0",
        iconPosition === 'left' ? "mr-2" : "ml-2"
      )}>
        {iconElement}
      </span>
    );
  };

  const buttonContent = (
    <>
      {loading && (
        <svg 
          className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
          xmlns="http://www.w3.org/2000/svg" 
          fill="none" 
          viewBox="0 0 24 24"
        >
          <circle 
            className="opacity-25" 
            cx="12" 
            cy="12" 
            r="10" 
            stroke="currentColor" 
            strokeWidth="4"
          />
          <path 
            className="opacity-75" 
            fill="currentColor" 
            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
          />
        </svg>
      )}

      {!loading && iconPosition === 'left' && renderIcon()}

      <span>{content || text}</span>

      {!loading && iconPosition === 'right' && renderIcon()}
    </>
  );

  if (href) {
    return (
      <a 
        href={href} 
        target={target}
        className={buttonClasses}
        style={styles}
        onClick={onClick}
        aria-disabled={disabled || loading}
      >
        {buttonContent}
      </a>
    );
  }

  return (
    <button 
      type={type}
      className={buttonClasses}
      style={styles}
      onClick={onClick}
      disabled={disabled || loading}
    >
      {buttonContent}
    </button>
  );
};

// Button Group Component
interface ButtonGroupProps {
  children?: React.ReactNode;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  orientation?: 'horizontal' | 'vertical';
  spacing?: 'tight' | 'normal' | 'loose';
  className?: string;
}

export const ButtonGroup: React.FC<ButtonGroupProps> = ({ 
  children, 
  size = 'md', 
  orientation = 'horizontal', 
  spacing = 'normal',
  className 
}) => {
  const spacingClasses = {
    tight: 'space-x-1',
    normal: 'space-x-2',
    loose: 'space-x-4'
  };

  const orientationClasses = {
    horizontal: 'flex flex-row',
    vertical: 'flex flex-col space-y-2'
  };

  return (
    <div className={cn(
      orientationClasses[orientation],
      orientation === 'horizontal' && spacingClasses[spacing],
      className
    )}>
      {React.Children.map(children, (child) => 
        React.cloneElement(child as React.ReactElement, { size })
      )}
    </div>
  );
};

// Action Buttons Component
interface ActionButtonsProps {
  actions: Array<{
    text: string;
    href?: string;
    onClick?: () => void;
    variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
    icon?: string | React.ReactNode;
  }>;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  orientation?: 'horizontal' | 'vertical';
  className?: string;
}

export const ActionButtons: React.FC<ActionButtonsProps> = ({ 
  actions, 
  size = 'md', 
  orientation = 'horizontal',
  className 
}) => {
  return (
    <ButtonGroup size={size} orientation={orientation} className={className}>
      {actions.map((action, index) => (
        <Button
          key={index}
          props={{
            text: action.text,
            href: action.href,
            onClick: action.onClick,
            variant: action.variant || 'primary',
            icon: action.icon
          }}
        />
      ))}
    </ButtonGroup>
  );
};

import React from 'react';
import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';
import { 
  ArrowRight, 
  Star, 
  CheckCircle, 
  Sparkles, 
  TrendingUp,
  Users,
  Clock,
  Award
} from 'lucide-react';

interface CardProps {
  id?: string;
  content?: string;
  styles?: React.CSSProperties;
  className?: string;
  props?: {
    title?: string;
    subtitle?: string;
    description?: string;
    image?: string;
    imageAlt?: string;
    icon?: string | React.ReactNode;
    variant?: 'default' | 'elevated' | 'outlined' | 'filled' | 'ghost' | 'gradient' | 'glass' | 'feature' | 'testimonial' | 'pricing' | 'stat';
    size?: 'small' | 'medium' | 'large';
    orientation?: 'vertical' | 'horizontal';
    interactive?: boolean;
    link?: string;
    badge?: string;
    animation?: boolean;
    hover?: boolean;
    actions?: Array<{
      text: string;
      href?: string;
      onClick?: () => void;
      variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
      icon?: React.ReactNode;
    }>;
    // Feature card specific
    features?: string[];
    price?: string;
    period?: string;
    popular?: boolean;
    // Testimonial specific
    quote?: string;
    author?: string;
    role?: string;
    avatar?: string;
    rating?: number;
    // Stat specific
    number?: string;
    label?: string;
    trend?: 'up' | 'down' | 'neutral';
    percentage?: string;
  };
}

export const Card: React.FC<CardProps> = ({ 
  content, 
  styles, 
  className,
  props = {}
}) => {
  const {
    title,
    subtitle,
    description,
    image,
    imageAlt,
    icon,
    variant = 'default',
    size = 'medium',
    orientation = 'vertical',
    interactive = false,
    link,
    badge,
    animation = true,
    hover = true,
    actions = [],
    features = [],
    price,
    period,
    popular = false,
    quote,
    author,
    role,
    avatar,
    rating,
    number,
    label,
    trend = 'neutral',
    percentage
  } = props;

  const sizeClasses = {
    small: 'p-4 text-sm',
    medium: 'p-6',
    large: 'p-8 text-lg'
  };

  const getVariantClasses = () => {
    switch (variant) {
      case 'elevated':
        return 'bg-white shadow-lg hover:shadow-xl border border-gray-100';
      case 'outlined':
        return 'border-2 border-gray-300 bg-white hover:border-blue-500';
      case 'filled':
        return 'bg-gray-50 hover:bg-gray-100';
      case 'ghost':
        return 'bg-transparent hover:bg-gray-50';
      case 'gradient':
        return 'bg-gradient-to-br from-blue-500 to-purple-600 text-white shadow-lg';
      case 'glass':
        return 'bg-white bg-opacity-20 backdrop-blur-lg border border-white border-opacity-30 shadow-xl';
      case 'feature':
        return 'bg-white border border-gray-200 shadow-sm hover:shadow-md hover:border-blue-300';
      case 'testimonial':
        return 'bg-white border border-gray-200 shadow-sm relative';
      case 'pricing':
        return popular 
          ? 'bg-white border-2 border-blue-500 shadow-lg relative transform scale-105' 
          : 'bg-white border border-gray-200 shadow-sm';
      case 'stat':
        return 'bg-gradient-to-br from-gray-50 to-white border border-gray-200 shadow-sm';
      default:
        return 'bg-white border border-gray-200 shadow-sm';
    }
  };

  const cardStyles: React.CSSProperties = {
    borderRadius: variant === 'glass' ? '1rem' : '0.75rem',
    overflow: 'hidden',
    transition: 'all 0.3s ease',
    position: 'relative',
    ...styles,
  };

  const cardClasses = cn(
    'card group',
    sizeClasses[size],
    getVariantClasses(),
    interactive && hover && 'hover:scale-102 cursor-pointer transform transition-transform',
    orientation === 'horizontal' && 'md:flex md:items-center',
    className
  );

  const MotionWrapper = animation ? motion.div : 'div';
  const motionProps = animation ? {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    whileHover: hover ? { y: -2 } : {},
    transition: { duration: 0.3 }
  } : {};

  // Render different card types
  const renderCardContent = () => {
    switch (variant) {
      case 'testimonial':
        return renderTestimonialCard();
      case 'pricing':
        return renderPricingCard();
      case 'stat':
        return renderStatCard();
      case 'feature':
        return renderFeatureCard();
      default:
        return renderDefaultCard();
    }
  };

  const renderTestimonialCard = () => (
    <>
      {/* Quote Mark */}
      <div className="absolute top-4 right-4 text-blue-500 opacity-20">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
          <path d="M14.017 21v-7.391c0-5.704 3.731-9.57 8.983-10.609l.995 2.151c-2.432.917-3.995 3.638-3.995 5.849h4v10h-10zm-14.017 0v-7.391c0-5.704 3.748-9.57 9-10.609l.996 2.151c-2.433.917-3.996 3.638-3.996 5.849h4v10h-10z"/>
        </svg>
      </div>

      {/* Rating */}
      {rating && (
        <div className="flex items-center gap-1 mb-4">
          {[...Array(5)].map((_, i) => (
            <Star
              key={i}
              className={`w-4 h-4 ${i < rating ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'}`}
            />
          ))}
        </div>
      )}

      {/* Quote */}
      {quote && (
        <blockquote className="text-gray-700 italic mb-6 text-lg leading-relaxed">
          "{quote}"
        </blockquote>
      )}

      {/* Author */}
      <div className="flex items-center gap-3">
        {avatar && (
          <img
            src={avatar}
            alt={author}
            className="w-12 h-12 rounded-full object-cover"
          />
        )}
        <div>
          <div className="font-semibold text-gray-900">{author}</div>
          <div className="text-sm text-gray-600">{role}</div>
        </div>
      </div>
    </>
  );

  const renderPricingCard = () => (
    <>
      {/* Popular Badge */}
      {popular && (
        <div className="absolute -top-3 left-1/2 transform -translate-x-1/2">
          <div className="bg-blue-500 text-white px-4 py-1 rounded-full text-sm font-semibold flex items-center gap-1">
            <Award className="w-3 h-3" />
            Most Popular
          </div>
        </div>
      )}

      <div className="text-center space-y-6">
        {/* Plan Name */}
        <div>
          <h3 className="text-2xl font-bold text-gray-900">{title}</h3>
          {subtitle && <p className="text-gray-600 mt-1">{subtitle}</p>}
        </div>

        {/* Price */}
        {price && (
          <div className="py-4">
            <span className="text-4xl font-bold text-gray-900">{price}</span>
            {period && <span className="text-gray-600">/{period}</span>}
          </div>
        )}

        {/* Features */}
        {features.length > 0 && (
          <ul className="space-y-3 text-left">
            {features.map((feature, index) => (
              <li key={index} className="flex items-center gap-3">
                <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" />
                <span className="text-gray-700">{feature}</span>
              </li>
            ))}
          </ul>
        )}

        {/* Description */}
        {description && (
          <p className="text-gray-600 text-center">{description}</p>
        )}
      </div>
    </>
  );

  const renderStatCard = () => (
    <div className="text-center space-y-2">
      {/* Number */}
      <div className="flex items-center justify-center gap-2">
        <span className="text-3xl font-bold text-gray-900">{number}</span>
        {percentage && (
          <div className={`flex items-center gap-1 text-sm font-medium ${
            trend === 'up' ? 'text-green-600' : trend === 'down' ? 'text-red-600' : 'text-gray-600'
          }`}>
            <TrendingUp className={`w-4 h-4 ${trend === 'down' ? 'rotate-180' : ''}`} />
            {percentage}
          </div>
        )}
      </div>

      {/* Label */}
      <div className="text-gray-600 font-medium">{label}</div>

      {/* Description */}
      {description && (
        <div className="text-sm text-gray-500">{description}</div>
      )}
    </div>
  );

  const renderFeatureCard = () => (
    <>
      {/* Icon */}
      {icon && (
        <div className="mb-4">
          {typeof icon === 'string' ? (
            <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
              <span className="text-2xl">{icon}</span>
            </div>
          ) : (
            <div className="w-12 h-12 text-blue-500">{icon}</div>
          )}
        </div>
      )}

      {/* Title */}
      {title && (
        <h3 className="text-xl font-semibold mb-3 text-gray-900 group-hover:text-blue-600 transition-colors">
          {title}
        </h3>
      )}

      {/* Description */}
      {description && (
        <p className="text-gray-600 mb-4 leading-relaxed">
          {description}
        </p>
      )}

      {/* Features */}
      {features.length > 0 && (
        <ul className="space-y-2 mb-4">
          {features.map((feature, index) => (
            <li key={index} className="flex items-center gap-2 text-sm">
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>
              <span className="text-gray-700">{feature}</span>
            </li>
          ))}
        </ul>
      )}

      {/* Learn More Link */}
      {link && (
        <div className="flex items-center gap-2 text-blue-600 font-medium group-hover:gap-3 transition-all">
          <span>Learn more</span>
          <ArrowRight className="w-4 h-4" />
        </div>
      )}
    </>
  );

  const renderDefaultCard = () => (
    <>
      {/* Badge */}
      {badge && (
        <div className="absolute top-4 right-4">
          <span className="bg-blue-100 text-blue-800 text-xs font-semibold px-2.5 py-0.5 rounded-full flex items-center gap-1">
            <Sparkles className="w-3 h-3" />
            {badge}
          </span>
        </div>
      )}

      {/* Image */}
      {image && (
        <div className={cn(
          'card-image mb-4',
          orientation === 'horizontal' && 'md:w-1/3 md:pr-6 md:mb-0'
        )}>
          <img 
            src={image} 
            alt={imageAlt || title || 'Card image'}
            className="w-full h-48 object-cover rounded-lg"
          />
        </div>
      )}

      {/* Icon */}
      {icon && !image && (
        <div className="mb-4">
          {typeof icon === 'string' ? (
            <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
              <span className="text-2xl">{icon}</span>
            </div>
          ) : (
            <div className="w-12 h-12">{icon}</div>
          )}
        </div>
      )}

      {/* Content */}
      <div className={cn(
        'card-content flex-1',
        orientation === 'horizontal' && 'md:w-2/3'
      )}>
        {title && (
          <h3 className="text-xl font-semibold mb-2 text-gray-900">
            {title}
          </h3>
        )}

        {subtitle && (
          <p className="text-sm text-gray-600 mb-2">
            {subtitle}
          </p>
        )}

        {description && (
          <p className="text-gray-700 mb-4 leading-relaxed">
            {description}
          </p>
        )}

        {content && !title && !description && (
          <div className="text-gray-700">
            {content}
          </div>
        )}
      </div>
    </>
  );

  const cardContent = (
    <MotionWrapper {...motionProps} className={cardClasses} style={cardStyles}>
      {renderCardContent()}

      {/* Actions */}
      {actions.length > 0 && (
        <div className="mt-6 flex flex-wrap gap-2">
          {actions.map((action, index) => {
            const buttonClasses = cn(
              'px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 flex items-center gap-2',
              {
                'bg-blue-600 text-white hover:bg-blue-700 shadow-md hover:shadow-lg': action.variant === 'primary',
                'bg-gray-200 text-gray-900 hover:bg-gray-300': action.variant === 'secondary',
                'border border-gray-300 text-gray-700 hover:bg-gray-50 hover:border-gray-400': action.variant === 'outline',
                'text-blue-600 hover:text-blue-800 hover:bg-blue-50': action.variant === 'ghost',
              }
            );

            const content = (
              <>
                {action.icon}
                {action.text}
              </>
            );

            return action.href ? (
              <motion.a 
                key={index} 
                href={action.href} 
                className={buttonClasses}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                {content}
              </motion.a>
            ) : (
              <motion.button 
                key={index} 
                onClick={action.onClick} 
                className={buttonClasses}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                {content}
              </motion.button>
            );
          })}
        </div>
      )}
    </MotionWrapper>
  );

  if (link && variant !== 'pricing') {
    return (
      <motion.a 
        href={link} 
        className="block"
        whileHover={{ scale: hover ? 1.02 : 1 }}
        transition={{ duration: 0.2 }}
      >
        {cardContent}
      </motion.a>
    );
  }

  return cardContent;
};

// Convenience exports for specific card types
export const TestimonialCard: React.FC<Omit<CardProps, 'props'> & { 
  quote: string;
  author: string;
  role: string;
  avatar?: string;
  rating?: number;
}> = ({ quote, author, role, avatar, rating, ...props }) => {
  return (
    <Card
      {...props}
      props={{
        variant: 'testimonial',
        quote,
        author,
        role,
        avatar,
        rating,
        ...props.props,
      }}
    />
  );
};

export const PricingCard: React.FC<Omit<CardProps, 'props'> & {
  plan: string;
  price: string;
  period: string;
  features: string[];
  popular?: boolean;
  ctaText?: string;
  ctaAction?: () => void;
}> = ({ plan, price, period, features, popular, ctaText = 'Get Started', ctaAction, ...props }) => {
  return (
