export function TemplateSelector({
  onTemplateSelect,
  preselectedTemplate,
  showIntelligenceScores = false,
  businessContext,
  className,
}: TemplateSelectorProps) {
  const router = useRouter();
  const { loadTemplate } = useBuilderStore();

  const [selectedCategory, setSelectedCategory] = useState('All');
