Textarea.displayName = "Textarea"

export { Textarea }

'use client';

import React, { useState, useCallback, useRef, useMemo } from 'react';
import { ReactFlowProvider, ReactFlow, Background, Controls, MiniMap, Panel, Node, Edge, Connection, NodeChange, EdgeChange, addEdge } from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ScrollArea } from '@/components/ui/scroll-area';
import { 
  Play, 
  Square, 
  GitBranch, 
  Clock, 
  Webhook, 
  Mail, 
  Users, 
  Zap, 
  Settings,
  Save,
  Plus,
  Trash2,
  Copy,
  Search,
  Filter,
  Eye,
  MoreHorizontal,
  ChevronDown,
  Activity,
  AlertTriangle,
  CheckCircle,
  Timer
} from 'lucide-react';
import { WorkflowNode as WorkflowNodeType, WorkflowEdge, WorkflowDefinition, WorkflowNodeType as NodeType, WorkflowCategory, TriggerType } from '@/types/workflow';
import { workflowService } from '@/lib/api/services';

// Custom Node Components
import TriggerNode from './workflow-nodes/TriggerNode';
import ActionNode from './workflow-nodes/ActionNode';
import ConditionNode from './workflow-nodes/ConditionNode';
import DelayNode from './workflow-nodes/DelayNode';
import WebhookNode from './workflow-nodes/WebhookNode';
import EmailNode from './workflow-nodes/EmailNode';
import CRMNode from './workflow-nodes/CRMNode';
import EndNode from './workflow-nodes/EndNode';

// Node type registry
const nodeTypes = {
  trigger: TriggerNode,
  action: ActionNode,
  condition: ConditionNode,
  delay: DelayNode,
  webhook: WebhookNode,
  email: EmailNode,
  crm: CRMNode,
  end: EndNode,
};

// Node configurations for the palette
const NODE_CONFIGS = {
  trigger: {
    color: 'green',
    icon: Play,
    category: 'Triggers',
    description: 'Start workflow when conditions are met',
    label: 'Trigger'
  },
  action: {
    color: 'blue',
    icon: Zap,
    category: 'Actions',
    description: 'Perform automated actions',
    label: 'Action'
  },
  condition: {
    color: 'yellow',
    icon: GitBranch,
    category: 'Logic',
    description: 'Branch workflow based on conditions',
    label: 'Condition'
  },
  delay: {
    color: 'purple',
    icon: Clock,
    category: 'Timing',
    description: 'Wait before continuing workflow',
    label: 'Delay'
  },
  webhook: {
    color: 'indigo',
    icon: Webhook,
    category: 'Integration',
    description: 'Send HTTP requests to external services',
    label: 'Webhook'
  },
  email: {
    color: 'red',
    icon: Mail,
    category: 'Communication',
    description: 'Send automated emails',
    label: 'Email'
  },
  crm: {
    color: 'teal',
    icon: Users,
    category: 'CRM',
    description: 'Manage contacts and leads',
    label: 'CRM'
  },
  end: {
    color: 'gray',
    icon: Square,
    category: 'Control',
    description: 'End workflow execution',
    label: 'End'
  }
} as const;

interface MagicConnectorBuilderProps {
  onWorkflowSave?: (workflow: WorkflowDefinition) => void;
  onWorkflowExecute?: (workflowId: string) => void;
  initialWorkflow?: WorkflowDefinition;
  connectedComponentId?: string;
  isModal?: boolean;
  onClose?: () => void;
}

interface NodePaletteItem {
  type: NodeType;
  config: typeof NODE_CONFIGS[NodeType];
}

export default function MagicConnectorBuilder({
  onWorkflowSave,
  onWorkflowExecute,
  initialWorkflow,
  connectedComponentId,
  isModal = false,
  onClose
}: MagicConnectorBuilderProps) {
  // State management
  const [nodes, setNodes] = useState<Node[]>(initialWorkflow?.nodes || []);
  const [edges, setEdges] = useState<Edge[]>(initialWorkflow?.edges || []);
  const [selectedNode, setSelectedNode] = useState<string | null>(null);
  const [selectedEdge, setSelectedEdge] = useState<string | null>(null);
  const [workflowName, setWorkflowName] = useState(initialWorkflow?.name || 'Untitled Workflow');
  const [workflowDescription, setWorkflowDescription] = useState(initialWorkflow?.description || '');
  const [workflowCategory, setWorkflowCategory] = useState<WorkflowCategory>(WorkflowCategory.AUTOMATION);
  const [isExecuting, setIsExecuting] = useState(false);
  const [executionProgress, setExecutionProgress] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'design' | 'properties' | 'execution'>('design');

  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const reactFlowInstance = useRef<any>(null);

  // Node palette filtered by search and category
  const nodePalette: NodePaletteItem[] = useMemo(() => {
    const items = Object.entries(NODE_CONFIGS).map(([type, config]) => ({
      type: type as NodeType,
      config
    }));

    if (!searchTerm) return items;

    return items.filter(item => 
      item.config.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.config.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.config.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [searchTerm]);

  // React Flow event handlers
  const onNodesChange = useCallback((changes: NodeChange[]) => {
    setNodes((nds) => {
      const updatedNodes = nds.map(node => {
        const change = changes.find(c => c.id === node.id);
        if (change?.type === 'select') {
          setSelectedNode(change.selected ? node.id : null);
        }
        return node;
      });
      return updatedNodes;
    });
  }, []);

  const onEdgesChange = useCallback((changes: EdgeChange[]) => {
    setEdges((eds) => {
      const updatedEdges = eds.map(edge => {
        const change = changes.find(c => c.id === edge.id);
        if (change?.type === 'select') {
          setSelectedEdge(change.selected ? edge.id : null);
        }
        return edge;
      });
      return updatedEdges;
    });
  }, []);

  const onConnect = useCallback((connection: Connection) => {
    setEdges((eds) => addEdge({
      ...connection,
      id: `edge-${Date.now()}`,
      type: 'smoothstep',
      animated: true,
      style: { stroke: '#6366f1', strokeWidth: 2 }
    }, eds));
  }, []);

  // Node operations
  const addNode = useCallback((nodeType: NodeType, position?: { x: number; y: number }) => {
    const newNode: Node = {
      id: `${nodeType}-${Date.now()}`,
      type: nodeType,
      position: position || { x: Math.random() * 300, y: Math.random() * 300 },
      data: {
        label: NODE_CONFIGS[nodeType].label,
        description: NODE_CONFIGS[nodeType].description,
        config: {},
        status: 'idle'
      }
    };

    setNodes((nds) => [...nds, newNode]);
    setSelectedNode(newNode.id);
  }, []);

  const deleteNode = useCallback((nodeId: string) => {
    setNodes((nds) => nds.filter(n => n.id !== nodeId));
    setEdges((eds) => eds.filter(e => e.source !== nodeId && e.target !== nodeId));
    setSelectedNode(null);
  }, []);

  const deleteEdge = useCallback((edgeId: string) => {
    setEdges((eds) => eds.filter(e => e.id !== edgeId));
    setSelectedEdge(null);
  }, []);

  // Workflow operations
  const saveWorkflow = useCallback(async () => {
    const workflowData = {
      name: workflowName,
      description: workflowDescription,
      category: workflowCategory,
      trigger_type: 'manual' as const,
      component_id: connectedComponentId,
      nodes: nodes.map(node => ({
        node_id: node.id,
        name: node.data.label,
        node_type: node.type as any,
        parameters: node.data.config || {},
        position: { x: node.position.x, y: node.position.y },
        inputs: [],
        outputs: []
      })),
      connections: edges.map(edge => ({
        source: edge.source,
        target: edge.target,
        sourceHandle: edge.sourceHandle,
        targetHandle: edge.targetHandle
      })),
      settings: {
        maxExecutionTime: 3600,
        retryAttempts: 3,
        retryDelay: 5,
        enableLogging: true,
        enableAnalytics: true,
        errorHandling: 'stop'
      }
    };

    try {
      let result;
      if (initialWorkflow?.id) {
        // Update existing workflow
        result = await workflowService.updateWorkflow(parseInt(initialWorkflow.id), workflowData);
      } else {
        // Create new workflow
        result = await workflowService.createWorkflow(workflowData);
      }

      // Convert result back to WorkflowDefinition format for callback
      const workflowDefinition: WorkflowDefinition = {
        id: result.id.toString(),
        name: result.name,
        description: result.description || '',
        version: 1,
        nodes: result.nodes || [],
        edges: result.connections || [],
        variables: [],
        settings: result.settings || {
          maxExecutionTime: 3600,
          retryAttempts: 3,
          retryDelay: 5,
          enableLogging: true,
          enableAnalytics: true,
          errorHandling: 'stop'
        },
        metadata: {
          category: result.category,
          tags: [],
          author: 'Current User',
          lastModifiedBy: 'Current User',
          usageCount: result.trigger_count || 0,
          averageExecutionTime: 0,
          successRate: result.success_count && result.trigger_count 
            ? (result.success_count / result.trigger_count) * 100 
            : 100,
          integrations: []
        },
        status: result.status,
        created_at: new Date(result.created_at),
        updated_at: new Date(result.updated_at || result.created_at)
      };

      onWorkflowSave?.(workflowDefinition);
    } catch (error) {
      console.error('Failed to save workflow:', error);
    }
  }, [workflowName, workflowDescription, workflowCategory, nodes, edges, initialWorkflow, connectedComponentId, onWorkflowSave]);

  const executeWorkflow = useCallback(async () => {
    if (!nodes.length) return;

    setIsExecuting(true);
    setExecutionProgress(0);

    try {
      // If we have an existing workflow ID, execute it
      if (initialWorkflow?.id) {
        // Execute the workflow via backend API
        const execution = await workflowService.executeWorkflow(
          parseInt(initialWorkflow.id), 
          { manual_trigger: true }
        );

        // Monitor execution progress
        const progressInterval = setInterval(async () => {
          setExecutionProgress(prev => {
            const newProgress = Math.min(prev + 20, 100);
            if (newProgress >= 100) {
              clearInterval(progressInterval);
              setIsExecuting(false);
              onWorkflowExecute?.(initialWorkflow.id!);
            }
            return newProgress;
          });
        }, 500);
      } else {
        // For unsaved workflows, simulate execution
        for (let i = 0; i <= 100; i += 10) {
          setExecutionProgress(i);
          await new Promise(resolve => setTimeout(resolve, 200));
        }

        setIsExecuting(false);
        onWorkflowExecute?.('new-workflow');
      }
    } catch (error) {
      console.error('Workflow execution failed:', error);
      setIsExecuting(false);
      setExecutionProgress(0);
    }
  }, [nodes, initialWorkflow, onWorkflowExecute]);

  // Drag and drop from palette
  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback((event: React.DragEvent) => {
    event.preventDefault();

    const nodeType = event.dataTransfer.getData('application/reactflow');
    if (!nodeType || !reactFlowInstance.current) return;

    const position = reactFlowInstance.current.screenToFlowPosition({
      x: event.clientX,
      y: event.clientY,
    });

    addNode(nodeType as NodeType, position);
  }, [addNode]);

  const onDragStart = (event: React.DragEvent, nodeType: string) => {
    event.dataTransfer.setData('application/reactflow', nodeType);
    event.dataTransfer.effectAllowed = 'move';
  };

  const selectedNodeData = useMemo(() => {
    return selectedNode ? nodes.find(n => n.id === selectedNode) : null;
  }, [selectedNode, nodes]);

  const selectedEdgeData = useMemo(() => {
    return selectedEdge ? edges.find(e => e.id === selectedEdge) : null;
  }, [selectedEdge, edges]);

  return (
    <div className={`h-full flex flex-col ${isModal ? 'max-h-[90vh]' : 'h-screen'} bg-gray-50`}>
      {/* Header */}
      <div className="bg-white border-b border-gray-200 p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-2">
              <Activity className="h-6 w-6 text-indigo-600" />
              <h1 className="text-xl font-semibold text-gray-900">Magic Connector</h1>
            </div>
            <div className="flex items-center space-x-2">
              <Input
                type="text"
                placeholder="Workflow name"
                value={workflowName}
                onChange={(e) => setWorkflowName(e.target.value)}
                className="w-64"
              />
              <Badge variant={workflowCategory === WorkflowCategory.AUTOMATION ? 'default' : 'secondary'}>
                {workflowCategory}
              </Badge>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            {connectedComponentId && (
              <Badge variant="outline" className="flex items-center space-x-1">
                <Zap className="h-3 w-3" />
                <span>Connected to Component</span>
              </Badge>
            )}

            <Button variant="outline" size="sm" onClick={saveWorkflow}>
              <Save className="h-4 w-4 mr-1" />
              Save
            </Button>

            <Button 
              size="sm" 
              onClick={executeWorkflow}
              disabled={isExecuting || !nodes.length}
            >
              {isExecuting ? (
                <>
                  <Timer className="h-4 w-4 mr-1 animate-spin" />
                  Executing...
                </>
              ) : (
                <>
                  <Play className="h-4 w-4 mr-1" />
                  Execute
                </>
              )}
            </Button>

            {isModal && (
              <Button variant="ghost" size="sm" onClick={onClose}>
                ×
              </Button>
            )}
          </div>
        </div>

        {/* Progress bar when executing */}
        {isExecuting && (
          <div className="mt-3">
            <div className="flex items-center justify-between text-sm text-gray-600 mb-1">
              <span>Executing workflow...</span>
              <span>{executionProgress}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div 
                className="bg-indigo-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${executionProgress}%` }}
              />
            </div>
          </div>
        )}
      </div>

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        {/* Node Palette Sidebar */}
        <div className="w-80 bg-white border-r border-gray-200 flex flex-col">
          <div className="p-4 border-b border-gray-200">
            <div className="flex items-center space-x-2 mb-3">
              <h2 className="text-sm font-medium text-gray-900">Node Library</h2>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                type="text"
                placeholder="Search nodes..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>

          <ScrollArea className="flex-1">
            <div className="p-4 space-y-3">
              {nodePalette.map(({ type, config }) => {
                const IconComponent = config.icon;
                return (
                  <div
                    key={type}
                    draggable
                    onDragStart={(e) => onDragStart(e, type)}
                    className="flex items-center space-x-3 p-3 border border-gray-200 rounded-lg cursor-move hover:border-indigo-300 hover:bg-indigo-50 transition-colors"
                  >
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center bg-${config.color}-100`}>
                      <IconComponent className={`h-5 w-5 text-${config.color}-600`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-sm text-gray-900">{config.label}</div>
                      <div className="text-xs text-gray-500 truncate">{config.description}</div>
                      <Badge variant="secondary" className="text-xs mt-1">
                        {config.category}
                      </Badge>
                    </div>
                  </div>
                );
              })}
            </div>
          </ScrollArea>
        </div>

        {/* Workflow Canvas */}
        <div className="flex-1 flex flex-col">
          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as typeof activeTab)} className="flex-1 flex flex-col">
            <div className="border-b border-gray-200 px-4">
              <TabsList className="h-10">
                <TabsTrigger value="design">Design</TabsTrigger>
                <TabsTrigger value="properties">Properties</TabsTrigger>
                <TabsTrigger value="execution">Execution</TabsTrigger>
              </TabsList>
            </div>

            <TabsContent value="design" className="flex-1 m-0">
              <div ref={reactFlowWrapper} className="h-full">
                <ReactFlowProvider>
                  <ReactFlow
                    ref={reactFlowInstance}
                    nodes={nodes}
                    edges={edges}
                    nodeTypes={nodeTypes}
                    onNodesChange={onNodesChange}
                    onEdgesChange={onEdgesChange}
                    onConnect={onConnect}
                    onDrop={onDrop}
                    onDragOver={onDragOver}
                    className="bg-gray-50"
                    fitView
                  >
                    <Background color="#e5e7eb" gap={20} />
                    <Controls />
                    <MiniMap 
                      style={{
                        backgroundColor: '#f9fafb',
                        border: '1px solid #e5e7eb'
                      }}
                    />

                    {/* Canvas Instructions */}
                    {nodes.length === 0 && (
                      <Panel position="center">
                        <div className="bg-white rounded-lg border border-gray-200 p-6 shadow-lg max-w-md text-center">
                          <Activity className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                          <h3 className="text-lg font-medium text-gray-900 mb-2">
                            Build Your Workflow
                          </h3>
                          <p className="text-gray-600 mb-4">
                            Drag nodes from the sidebar to start building your automation workflow.
                          </p>
                          <Button onClick={() => addNode('trigger')}>
                            <Plus className="h-4 w-4 mr-2" />
                            Add Trigger
                          </Button>
                        </div>
                      </Panel>
                    )}
                  </ReactFlow>
                </ReactFlowProvider>
              </div>
            </TabsContent>

            <TabsContent value="properties" className="flex-1 m-0 p-4 overflow-auto">
              {selectedNodeData ? (
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center justify-between">
                      <span>Node Properties</span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => deleteNode(selectedNodeData.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div>
                      <Label htmlFor="node-label">Label</Label>
                      <Input
                        id="node-label"
                        value={selectedNodeData.data.label}
                        onChange={(e) => {
                          setNodes(nds => nds.map(n => 
                            n.id === selectedNodeData.id 
                              ? { ...n, data: { ...n.data, label: e.target.value } }
                              : n
                          ));
                        }}
                      />
                    </div>
                    <div>
                      <Label htmlFor="node-description">Description</Label>
                      <Input
                        id="node-description"
                        value={selectedNodeData.data.description || ''}
                        onChange={(e) => {
                          setNodes(nds => nds.map(n => 
                            n.id === selectedNodeData.id 
                              ? { ...n, data: { ...n.data, description: e.target.value } }
                              : n
                          ));
                        }}
                      />
                    </div>
                    {/* Additional node-specific configuration would go here */}
                  </CardContent>
                </Card>
              ) : selectedEdgeData ? (
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center justify-between">
                      <span>Connection Properties</span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => deleteEdge(selectedEdgeData.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-gray-600">Configure connection conditions and data flow.</p>
                  </CardContent>
                </Card>
              ) : (
                <div className="text-center py-12 text-gray-500">
                  <Settings className="h-12 w-12 mx-auto mb-4 text-gray-400" />
                  <p>Select a node or connection to view properties</p>
                </div>
              )}
            </TabsContent>

            <TabsContent value="execution" className="flex-1 m-0 p-4 overflow-auto">
              <Card>
                <CardHeader>
                  <CardTitle>Execution History</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-center py-12 text-gray-500">
                    <Eye className="h-12 w-12 mx-auto mb-4 text-gray-400" />
                    <p>No execution history available</p>
                    <p className="text-sm mt-2">Execute your workflow to see results here</p>
                  </div>
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </div>
      </div>
    </div>
  );
}

/**
 * Action Node Component  
 * Performs automated actions within workflows
 */

'use client';

import React from 'react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData, ActionNodeType } from '@/types/workflow';
import { 
  Zap,
  Mail,
  UserPlus,
  Users,
  MessageSquare,
  Database,
  Webhook,
  Tag,
  Calendar,
  Bell,
  Gift,
  BarChart
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface ActionNodeProps {
  data: WorkflowNodeData & {
    actionType: ActionNodeType;
    actionConfig: {
      email?: {
        to: string;
        subject: string;
        template?: string;
        variables?: Record<string, any>;
      };
      contact?: {
        fields: Record<string, any>;
        lists?: string[];
        tags?: string[];
      };
      webhook?: {
        url: string;
        method: string;
        headers?: Record<string, string>;
        body?: any;
      };
      notification?: {
        message: string;
        channels: string[];
        priority: 'low' | 'normal' | 'high';
      };
      task?: {
        title: string;
        assignee?: string;
        dueDate?: Date;
        priority: 'low' | 'normal' | 'high';
      };
    };
  };
  selected?: boolean;
}

export const ActionNode: React.FC<ActionNodeProps> = ({ data, selected }) => {
  const getActionIcon = (actionType: ActionNodeType) => {
    const iconMap = {
      send_email: Mail,
      create_contact: UserPlus,
      update_contact: Users,
      add_to_list: Users,
      remove_from_list: Users,
      send_sms: MessageSquare,
      create_task: Calendar,
      send_notification: Bell,
      update_database: Database,
      call_api: Webhook,
      generate_coupon: Gift,
      schedule_meeting: Calendar,
      track_event: BarChart
    };

    return iconMap[actionType] || Zap;
  };

  const getActionLabel = (actionType: ActionNodeType) => {
    const labelMap = {
      send_email: 'Send Email',
      create_contact: 'Create Contact',
      update_contact: 'Update Contact', 
      add_to_list: 'Add to List',
      remove_from_list: 'Remove from List',
      send_sms: 'Send SMS',
      create_task: 'Create Task',
      send_notification: 'Send Notification',
      update_database: 'Update Database',
      call_api: 'API Call',
      generate_coupon: 'Generate Coupon',
      schedule_meeting: 'Schedule Meeting',
      track_event: 'Track Event'
    };

    return labelMap[actionType] || 'Action';
  };

  const getActionCategory = (actionType: ActionNodeType) => {
    if (['send_email', 'send_sms', 'send_notification'].includes(actionType)) {
      return 'Communication';
    }
    if (['create_contact', 'update_contact', 'add_to_list', 'remove_from_list'].includes(actionType)) {
      return 'CRM';
    }
    if (['update_database', 'call_api'].includes(actionType)) {
      return 'Integration';
    }
    if (['create_task', 'schedule_meeting'].includes(actionType)) {
      return 'Productivity';
    }
    if (['generate_coupon', 'track_event'].includes(actionType)) {
      return 'Marketing';
    }
    return 'Action';
  };

  const ActionIcon = getActionIcon(data.actionType);

  const renderActionDetails = () => {
    const { actionType, actionConfig } = data;

    switch (actionType) {
      case 'send_email':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Email
            </Badge>
            {actionConfig.email?.subject && (
              <div className="text-xs text-gray-600 truncate">
                Subject: {actionConfig.email.subject}
              </div>
            )}
            {actionConfig.email?.template && (
              <div className="text-xs text-gray-500">
                Template: {actionConfig.email.template}
              </div>
            )}
          </div>
        );

      case 'create_contact':
      case 'update_contact':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Contact
            </Badge>
            {actionConfig.contact?.fields && (
              <div className="text-xs text-gray-600">
                {Object.keys(actionConfig.contact.fields).length} field(s)
              </div>
            )}
            {actionConfig.contact?.lists && actionConfig.contact.lists.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {actionConfig.contact.lists.slice(0, 2).map((list, idx) => (
                  <span key={idx} className="text-xs bg-blue-100 text-blue-600 px-1 py-0.5 rounded">
                    {list}
                  </span>
                ))}
                {actionConfig.contact.lists.length > 2 && (
                  <span className="text-xs text-gray-500">
                    +{actionConfig.contact.lists.length - 2} more
                  </span>
                )}
              </div>
            )}
          </div>
        );

      case 'call_api':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {actionConfig.webhook?.method || 'POST'}
            </Badge>
            {actionConfig.webhook?.url && (
              <div className="text-xs text-gray-600 truncate">
                {actionConfig.webhook.url}
              </div>
            )}
          </div>
        );

      case 'send_notification':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {actionConfig.notification?.priority || 'normal'} priority
            </Badge>
            {actionConfig.notification?.message && (
              <div className="text-xs text-gray-600 truncate">
                {actionConfig.notification.message}
              </div>
            )}
            {actionConfig.notification?.channels && (
              <div className="text-xs text-gray-500">
                {actionConfig.notification.channels.join(', ')}
              </div>
            )}
          </div>
        );

      case 'create_task':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Task
            </Badge>
            {actionConfig.task?.title && (
              <div className="text-xs text-gray-600 truncate">
                {actionConfig.task.title}
              </div>
            )}
            {actionConfig.task?.assignee && (
              <div className="text-xs text-gray-500">
                → {actionConfig.task.assignee}
              </div>
            )}
            {actionConfig.task?.dueDate && (
              <div className="text-xs text-gray-500">
                Due: {actionConfig.task.dueDate.toLocaleDateString()}
              </div>
            )}
          </div>
        );

      case 'generate_coupon':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Coupon
            </Badge>
            <div className="text-xs text-gray-600">
              Generate discount code
            </div>
          </div>
        );

      case 'track_event':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Analytics
            </Badge>
            <div className="text-xs text-gray-600">
              Track custom event
            </div>
          </div>
        );

      default:
        return (
          <Badge variant="outline" className="text-xs">
            {getActionCategory(actionType)}
          </Badge>
        );
    }
  };

  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || getActionLabel(data.actionType)
      }}
      type="action"
      selected={selected}
      icon={ActionIcon}
      color="blue"
      hasInput={true}
      hasOutput={true}
    >
      {renderActionDetails()}
    </BaseNode>
  );
};

/**
 * Base Workflow Node Component
 * Reusable foundation for all workflow nodes
 */

'use client';

import React from 'react';
import { Handle, Position } from '@xyflow/react';
import { cn } from '@/lib/utils';
import { WorkflowNodeData, WorkflowNodeType } from '@/types/workflow';
import { 
  CheckCircle2, 
  AlertCircle, 
  Clock, 
  Play,
  Square
} from 'lucide-react';

interface BaseNodeProps {
  data: WorkflowNodeData;
  type: WorkflowNodeType;
  selected?: boolean;
  icon: React.ComponentType<{ className?: string }>;
  color: string;
  children?: React.ReactNode;
  hasInput?: boolean;
  hasOutput?: boolean;
  className?: string;
}

export const BaseNode: React.FC<BaseNodeProps> = ({
  data,
  type,
  selected = false,
  icon: Icon,
  color,
  children,
  hasInput = true,
  hasOutput = true,
  className = ''
}) => {
  const getStatusIcon = () => {
    switch (data.status) {
      case 'success':
        return <CheckCircle2 className="w-3 h-3 text-green-500" />;
      case 'error':
        return <AlertCircle className="w-3 h-3 text-red-500" />;
      case 'running':
        return <Play className="w-3 h-3 text-blue-500 animate-pulse" />;
      default:
        return <Square className="w-3 h-3 text-gray-400" />;
    }
  };

  const getColorClasses = (color: string) => {
    const colorMap = {
      green: {
        bg: 'bg-green-50 border-green-200',
        selectedBg: 'bg-green-100 border-green-400',
        icon: 'bg-green-500 text-white',
        text: 'text-green-700'
      },
      blue: {
        bg: 'bg-blue-50 border-blue-200',
        selectedBg: 'bg-blue-100 border-blue-400',
        icon: 'bg-blue-500 text-white',
        text: 'text-blue-700'
      },
      yellow: {
        bg: 'bg-yellow-50 border-yellow-200',
        selectedBg: 'bg-yellow-100 border-yellow-400',
        icon: 'bg-yellow-500 text-white',
        text: 'text-yellow-700'
      },
      purple: {
        bg: 'bg-purple-50 border-purple-200',
        selectedBg: 'bg-purple-100 border-purple-400',
        icon: 'bg-purple-500 text-white',
        text: 'text-purple-700'
      },
      indigo: {
        bg: 'bg-indigo-50 border-indigo-200',
        selectedBg: 'bg-indigo-100 border-indigo-400',
        icon: 'bg-indigo-500 text-white',
        text: 'text-indigo-700'
      },
      red: {
        bg: 'bg-red-50 border-red-200',
        selectedBg: 'bg-red-100 border-red-400',
        icon: 'bg-red-500 text-white',
        text: 'text-red-700'
      },
      teal: {
        bg: 'bg-teal-50 border-teal-200',
        selectedBg: 'bg-teal-100 border-teal-400',
        icon: 'bg-teal-500 text-white',
        text: 'text-teal-700'
      },
      gray: {
        bg: 'bg-gray-50 border-gray-200',
        selectedBg: 'bg-gray-100 border-gray-400',
        icon: 'bg-gray-500 text-white',
        text: 'text-gray-700'
      }
    };

    return colorMap[color as keyof typeof colorMap] || colorMap.gray;
  };

  const colors = getColorClasses(color);

  return (
    <div className={cn(
      "relative bg-white border-2 rounded-lg shadow-sm transition-all duration-200 min-w-[200px]",
      selected ? colors.selectedBg : colors.bg,
      selected && "ring-2 ring-blue-500 ring-offset-1",
      data.status === 'running' && "animate-pulse",
      className
    )}>
      {/* Input Handle */}
      {hasInput && (
        <Handle
          type="target"
          position={Position.Left}
          className="w-3 h-3 border-2 border-gray-300 bg-white"
        />
      )}

      {/* Node Header */}
      <div className="flex items-center gap-3 p-3 pb-2">
        <div className={cn("p-2 rounded-lg", colors.icon)}>
          <Icon className="w-4 h-4" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between">
            <h3 className={cn("font-medium text-sm truncate", colors.text)}>
              {data.label}
            </h3>
            {getStatusIcon()}
          </div>
          {data.description && (
            <p className="text-xs text-gray-500 truncate mt-1">
              {data.description}
            </p>
          )}
        </div>
      </div>

      {/* Node Content */}
      {children && (
        <div className="px-3 pb-3">
          {children}
        </div>
      )}

      {/* Execution Info */}
      {(data.executionTime || data.lastExecuted) && (
        <div className="px-3 pb-2">
          <div className="flex items-center gap-2 text-xs text-gray-500">
            <Clock className="w-3 h-3" />
            {data.executionTime && (
              <span>{data.executionTime}ms</span>
            )}
            {data.lastExecuted && (
              <span>Last: {data.lastExecuted.toLocaleTimeString()}</span>
            )}
          </div>
        </div>
      )}

      {/* Error Message */}
      {data.status === 'error' && data.errorMessage && (
        <div className="px-3 pb-3">
          <div className="bg-red-50 border border-red-200 rounded-md p-2">
            <p className="text-xs text-red-600">{data.errorMessage}</p>
          </div>
        </div>
      )}

      {/* Output Handle */}
      {hasOutput && (
        <Handle
          type="source"
          position={Position.Right}
          className="w-3 h-3 border-2 border-gray-300 bg-white"
        />
      )}

      {/* Running Indicator */}
      {data.status === 'running' && (
        <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-500 rounded-full animate-ping" />
      )}
    </div>
  );
};

/**
 * Condition Node Component
 * Implements branching logic in workflows
 */

'use client';

import React from 'react';
import { Handle, Position } from '@xyflow/react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData, ConditionNodeType } from '@/types/workflow';
import { 
  GitBranch,
  Filter,
  ToggleLeft,
  Repeat,
  Search,
  Calculator,
  Type,
  Hash,
  Calendar,
  List
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

interface ConditionNodeProps {
  data: WorkflowNodeData & {
    conditionType: ConditionNodeType;
    conditionConfig: {
      rules?: Array<{
        field: string;
        operator: string;
        value: any;
        logicalOperator?: 'AND' | 'OR';
      }>;
      branches?: Array<{
        id: string;
        label: string;
        condition: string;
        isDefault?: boolean;
      }>;
      loopConfig?: {
        type: 'for' | 'while' | 'forEach';
        iterations?: number;
        condition?: string;
        array?: string;
      };
    };
  };
  selected?: boolean;
}

export const ConditionNode: React.FC<ConditionNodeProps> = ({ data, selected }) => {
  const getConditionIcon = (conditionType: ConditionNodeType) => {
    const iconMap = {
      if_then_else: GitBranch,
      filter: Filter,
      switch: ToggleLeft,
      loop: Repeat,
      exists_check: Search,
      comparison: Calculator,
      text_contains: Type,
      number_range: Hash,
      date_range: Calendar,
      list_contains: List
    };

    return iconMap[conditionType] || GitBranch;
  };

  const getConditionLabel = (conditionType: ConditionNodeType) => {
    const labelMap = {
      if_then_else: 'If/Then/Else',
      filter: 'Filter',
      switch: 'Switch',
      loop: 'Loop',
      exists_check: 'Exists Check',
      comparison: 'Comparison',
      text_contains: 'Text Contains',
      number_range: 'Number Range',
      date_range: 'Date Range',
      list_contains: 'List Contains'
    };

    return labelMap[conditionType] || 'Condition';
  };

  const ConditionIcon = getConditionIcon(data.conditionType);

  const renderConditionDetails = () => {
    const { conditionType, conditionConfig } = data;

    switch (conditionType) {
      case 'if_then_else':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              If/Then/Else
            </Badge>
            {conditionConfig.rules && conditionConfig.rules.length > 0 && (
              <div className="space-y-1">
                {conditionConfig.rules.slice(0, 2).map((rule, idx) => (
                  <div key={idx} className="text-xs text-gray-600 truncate">
                    {rule.field} {rule.operator} {String(rule.value)}
                  </div>
                ))}
                {conditionConfig.rules.length > 2 && (
                  <div className="text-xs text-gray-500">
                    +{conditionConfig.rules.length - 2} more condition(s)
                  </div>
                )}
              </div>
            )}
          </div>
        );

      case 'switch':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Switch
            </Badge>
            {conditionConfig.branches && (
              <div className="text-xs text-gray-600">
                {conditionConfig.branches.length} branch(es)
              </div>
            )}
          </div>
        );

      case 'loop':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {conditionConfig.loopConfig?.type || 'Loop'}
            </Badge>
            {conditionConfig.loopConfig?.iterations && (
              <div className="text-xs text-gray-600">
                {conditionConfig.loopConfig.iterations} iteration(s)
              </div>
            )}
            {conditionConfig.loopConfig?.condition && (
              <div className="text-xs text-gray-600 truncate">
                While: {conditionConfig.loopConfig.condition}
              </div>
            )}
          </div>
        );

      case 'filter':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Filter
            </Badge>
            {conditionConfig.rules && (
              <div className="text-xs text-gray-600">
                {conditionConfig.rules.length} filter rule(s)
              </div>
            )}
          </div>
        );

      case 'comparison':
      case 'text_contains':
      case 'number_range':
      case 'date_range':
      case 'list_contains':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {getConditionLabel(conditionType)}
            </Badge>
            {conditionConfig.rules && conditionConfig.rules[0] && (
              <div className="text-xs text-gray-600 truncate">
                {conditionConfig.rules[0].field} {conditionConfig.rules[0].operator} {String(conditionConfig.rules[0].value)}
              </div>
            )}
          </div>
        );

      default:
        return (
          <Badge variant="outline" className="text-xs">
            {getConditionLabel(conditionType)}
          </Badge>
        );
    }
  };

  // Custom node with multiple output handles for branching
  const renderMultiOutputNode = () => {
    const { conditionType, conditionConfig } = data;

    // Determine number of outputs
    let outputs: Array<{ id: string; label: string; position: number }> = [];

    if (conditionType === 'if_then_else') {
      outputs = [
        { id: 'true', label: 'True', position: 0.3 },
        { id: 'false', label: 'False', position: 0.7 }
      ];
    } else if (conditionType === 'switch' && conditionConfig.branches) {
      outputs = conditionConfig.branches.map((branch, idx) => ({
        id: branch.id,
        label: branch.label,
        position: (idx + 1) / (conditionConfig.branches!.length + 1)
      }));
    } else {
      // Default single output
      outputs = [{ id: 'output', label: '', position: 0.5 }];
    }

    return (
      <div className={cn(
        "relative bg-white border-2 rounded-lg shadow-sm transition-all duration-200 min-w-[200px]",
        selected ? "bg-yellow-100 border-yellow-400 ring-2 ring-blue-500 ring-offset-1" : "bg-yellow-50 border-yellow-200",
        data.status === 'running' && "animate-pulse"
      )}>
        {/* Input Handle */}
        <Handle
          type="target"
          position={Position.Left}
          className="w-3 h-3 border-2 border-gray-300 bg-white"
        />

        {/* Node Header */}
        <div className="flex items-center gap-3 p-3">
          <div className="p-2 rounded-lg bg-yellow-500 text-white">
            <ConditionIcon className="w-4 h-4" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-medium text-sm text-yellow-700 truncate">
              {data.label || getConditionLabel(data.conditionType)}
            </h3>
            {data.description && (
              <p className="text-xs text-gray-500 truncate mt-1">
                {data.description}
              </p>
            )}
          </div>
        </div>

        {/* Content */}
        <div className="px-3 pb-3">
          {renderConditionDetails()}
        </div>

        {/* Multiple Output Handles */}
        {outputs.map((output, idx) => (
          <React.Fragment key={output.id}>
            <Handle
              type="source"
              position={Position.Right}
              id={output.id}
              style={{ top: `${output.position * 100}%` }}
              className="w-3 h-3 border-2 border-gray-300 bg-white"
            />
            {output.label && (
              <div 
                className="absolute text-xs font-medium text-gray-600 bg-white px-1 py-0.5 rounded border"
                style={{ 
                  right: '-45px', 
                  top: `${output.position * 100 - 10}%`,
                  transform: 'translateY(-50%)'
                }}
              >
                {output.label}
              </div>
            )}
          </React.Fragment>
        ))}

        {/* Running Indicator */}
        {data.status === 'running' && (
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-500 rounded-full animate-ping" />
        )}
      </div>
    );
  };

  // Use custom multi-output node for branching conditions
  if (data.conditionType === 'if_then_else' || data.conditionType === 'switch') {
    return renderMultiOutputNode();
  }

  // Use base node for simple conditions
  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || getConditionLabel(data.conditionType)
      }}
      type="condition"
      selected={selected}
      icon={ConditionIcon}
      color="yellow"
      hasInput={true}
      hasOutput={true}
    >
      {renderConditionDetails()}
    </BaseNode>
  );
};

/**
 * Delay Node Component
 * Introduces time delays in workflow execution
 */

'use client';

import React from 'react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData } from '@/types/workflow';
import { Clock, Timer, Calendar, Play } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface DelayNodeProps {
  data: WorkflowNodeData & {
    delayConfig: {
      type: 'fixed' | 'dynamic' | 'schedule';
      duration?: number; // minutes
      unit?: 'minutes' | 'hours' | 'days' | 'weeks';
      dynamicField?: string; // field to read delay from
      schedule?: {
        datetime: Date;
        timezone?: string;
      };
      businessHoursOnly?: boolean;
      skipWeekends?: boolean;
    };
  };
  selected?: boolean;
}

export const DelayNode: React.FC<DelayNodeProps> = ({ data, selected }) => {
  const getDelayIcon = () => {
    switch (data.delayConfig.type) {
      case 'schedule':
        return Calendar;
      case 'dynamic':
        return Timer;
      default:
        return Clock;
    }
  };

  const formatDelayDuration = () => {
    const { duration, unit } = data.delayConfig;
    if (!duration || !unit) return 'Custom delay';

    return `${duration} ${duration === 1 ? unit.slice(0, -1) : unit}`;
  };

  const DelayIcon = getDelayIcon();

  const renderDelayDetails = () => {
    const { delayConfig } = data;

    switch (delayConfig.type) {
      case 'fixed':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Fixed Delay
            </Badge>
            <div className="text-xs text-gray-600">
              Wait: {formatDelayDuration()}
            </div>
            {delayConfig.businessHoursOnly && (
              <div className="text-xs text-gray-500">
                Business hours only
              </div>
            )}
            {delayConfig.skipWeekends && (
              <div className="text-xs text-gray-500">
                Skip weekends
              </div>
            )}
          </div>
        );

      case 'dynamic':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Dynamic Delay
            </Badge>
            {delayConfig.dynamicField && (
              <div className="text-xs text-gray-600">
                From: {delayConfig.dynamicField}
              </div>
            )}
          </div>
        );

      case 'schedule':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Scheduled
            </Badge>
            {delayConfig.schedule?.datetime && (
              <div className="text-xs text-gray-600">
                {delayConfig.schedule.datetime.toLocaleString()}
              </div>
            )}
            {delayConfig.schedule?.timezone && (
              <div className="text-xs text-gray-500">
                {delayConfig.schedule.timezone}
              </div>
            )}
          </div>
        );

      default:
        return (
          <Badge variant="outline" className="text-xs">
            Delay
          </Badge>
        );
    }
  };

  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || `Delay (${formatDelayDuration()})`
      }}
      type="delay"
      selected={selected}
      icon={DelayIcon}
      color="purple"
      hasInput={true}
      hasOutput={true}
    >
      {renderDelayDetails()}

      {/* Show countdown if currently delaying */}
      {data.status === 'running' && (
        <div className="mt-2 flex items-center justify-center">
          <div className="flex items-center gap-1 text-xs text-purple-600">
            <Play className="w-3 h-3 animate-pulse" />
            <span>Waiting...</span>
          </div>
        </div>
      )}
    </BaseNode>
  );
};

/**
 * Email Node Component
 * Sends automated emails within workflows
 */

'use client';

import React from 'react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData } from '@/types/workflow';
import { Mail, FileText, Users, Personalizations, Send } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface EmailNodeProps {
  data: WorkflowNodeData & {
    emailConfig: {
      to: string | string[]; // recipient(s)
      cc?: string | string[];
      bcc?: string | string[];
      subject: string;
      body?: string;
      template?: {
        id: string;
        name: string;
        variables?: Record<string, any>;
      };
      attachments?: Array<{
        name: string;
        url: string;
        type?: string;
      }>;
      scheduling?: {
        sendAt?: Date;
        timezone?: string;
        businessHoursOnly?: boolean;
      };
      tracking?: {
        trackOpens: boolean;
        trackClicks: boolean;
        trackUnsubscribes: boolean;
      };
      personalization?: {
        enabled: boolean;
        fields: Record<string, string>; // field mappings
      };
    };
  };
  selected?: boolean;
}

export const EmailNode: React.FC<EmailNodeProps> = ({ data, selected }) => {
  const getRecipientCount = () => {
    const { to } = data.emailConfig;
    if (Array.isArray(to)) {
      return to.length;
    }
    return to.includes(',') ? to.split(',').length : 1;
  };

  const isTemplate = () => {
    return !!data.emailConfig.template;
  };

  const hasPersonalization = () => {
    return data.emailConfig.personalization?.enabled;
  };

  const hasTracking = () => {
    const tracking = data.emailConfig.tracking;
    return tracking && (tracking.trackOpens || tracking.trackClicks || tracking.trackUnsubscribes);
  };

  const renderEmailDetails = () => {
    const { emailConfig } = data;
    const recipientCount = getRecipientCount();

    return (
      <div className="space-y-2">
        {/* Email Type */}
        <div className="flex items-center gap-2">
          <Badge variant="outline" className="text-xs">
            {isTemplate() ? 'Template' : 'Custom'}
          </Badge>
          {hasPersonalization() && (
            <Badge variant="outline" className="text-xs bg-purple-50 text-purple-600">
              Personalized
            </Badge>
          )}
        </div>

        {/* Recipients */}
        <div className="flex items-center gap-1 text-xs text-gray-600">
          <Users className="w-3 h-3" />
          <span>
            {recipientCount === 1 ? '1 recipient' : `${recipientCount} recipients`}
          </span>
        </div>

        {/* Subject */}
        <div className="text-xs text-gray-600 truncate">
          Subject: {emailConfig.subject}
        </div>

        {/* Template Info */}
        {emailConfig.template && (
          <div className="flex items-center gap-1 text-xs text-gray-500">
            <FileText className="w-3 h-3" />
            <span>{emailConfig.template.name}</span>
          </div>
        )}

        {/* Personalization */}
        {hasPersonalization() && emailConfig.personalization && (
          <div className="flex items-center gap-1 text-xs text-purple-600">
            <Personalizations className="w-3 h-3" />
            <span>{Object.keys(emailConfig.personalization.fields).length} field(s)</span>
          </div>
        )}

        {/* Attachments */}
        {emailConfig.attachments && emailConfig.attachments.length > 0 && (
          <div className="text-xs text-gray-500">
            {emailConfig.attachments.length} attachment(s)
          </div>
        )}

        {/* Scheduling */}
        {emailConfig.scheduling?.sendAt && (
          <div className="text-xs text-gray-500">
            Scheduled: {emailConfig.scheduling.sendAt.toLocaleString()}
          </div>
        )}

        {/* Tracking */}
        {hasTracking() && (
          <div className="flex flex-wrap gap-1">
            {emailConfig.tracking?.trackOpens && (
              <span className="text-xs bg-blue-100 text-blue-600 px-1 py-0.5 rounded">
                Track opens
              </span>
            )}
            {emailConfig.tracking?.trackClicks && (
              <span className="text-xs bg-green-100 text-green-600 px-1 py-0.5 rounded">
                Track clicks
              </span>
            )}
          </div>
        )}

        {/* Status Info */}
        {data.status === 'success' && data.lastExecuted && (
          <div className="flex items-center gap-1 text-xs text-green-600">
            <Send className="w-3 h-3" />
            <span>Sent successfully</span>
          </div>
        )}

        {data.status === 'error' && data.errorMessage && (
          <div className="text-xs text-red-600 truncate">
            Error: {data.errorMessage}
          </div>
        )}
      </div>
    );
  };

  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || 'Send Email'
      }}
      type="email"
      selected={selected}
      icon={Mail}
      color="red"
      hasInput={true}
      hasOutput={true}
    >
      {renderEmailDetails()}
    </BaseNode>
  );
};

