/**
 * Trigger Node Component
 * Start point for workflows - defines when workflow should execute
 */

'use client';

import React from 'react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData, TriggerNodeType } from '@/types/workflow';
import { 
  Play,
  MousePointer,
  Clock,
  Webhook,
  Mail,
  ShoppingCart,
  UserPlus,
  Eye
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface TriggerNodeProps {
  data: WorkflowNodeData & {
    triggerType: TriggerNodeType;
    triggerConfig: {
      conditions?: Array<{
        field: string;
        operator: string;
        value: any;
      }>;
      schedule?: {
        type: 'once' | 'recurring';
        datetime?: Date;
        cron?: string;
      };
      webhook?: {
        url: string;
        method: string;
        headers?: Record<string, string>;
      };
    };
  };
  selected?: boolean;
}

export const TriggerNode: React.FC<TriggerNodeProps> = ({ data, selected }) => {
  const getTriggerIcon = (triggerType: TriggerNodeType) => {
    const iconMap = {
      form_submission: MousePointer,
      page_view: Eye,
      button_click: MousePointer,
      time_based: Clock,
      webhook: Webhook,
      api_call: Webhook,
      email_open: Mail,
      email_click: Mail,
      cart_abandonment: ShoppingCart,
      user_signup: UserPlus,
      purchase_complete: ShoppingCart
    };

    return iconMap[triggerType] || Play;
  };

  const getTriggerLabel = (triggerType: TriggerNodeType) => {
    const labelMap = {
      form_submission: 'Form Submission',
      page_view: 'Page View',
      button_click: 'Button Click',
      time_based: 'Schedule',
      webhook: 'Webhook',
      api_call: 'API Call',
      email_open: 'Email Open',
      email_click: 'Email Click',
      cart_abandonment: 'Cart Abandonment',
      user_signup: 'User Signup',
      purchase_complete: 'Purchase Complete'
    };

    return labelMap[triggerType] || 'Trigger';
  };

  const TriggerIcon = getTriggerIcon(data.triggerType);

  const renderTriggerDetails = () => {
    const { triggerType, triggerConfig } = data;

    switch (triggerType) {
      case 'form_submission':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Form Trigger
            </Badge>
            {triggerConfig.conditions && (
              <div className="text-xs text-gray-600">
                {triggerConfig.conditions.length} condition(s)
              </div>
            )}
          </div>
        );

      case 'time_based':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {triggerConfig.schedule?.type === 'recurring' ? 'Recurring' : 'One-time'}
            </Badge>
            {triggerConfig.schedule?.cron && (
              <div className="text-xs text-gray-600 font-mono">
                {triggerConfig.schedule.cron}
              </div>
            )}
            {triggerConfig.schedule?.datetime && (
              <div className="text-xs text-gray-600">
                {triggerConfig.schedule.datetime.toLocaleDateString()}
              </div>
            )}
          </div>
        );

      case 'webhook':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              {triggerConfig.webhook?.method || 'POST'}
            </Badge>
            {triggerConfig.webhook?.url && (
              <div className="text-xs text-gray-600 truncate">
                {triggerConfig.webhook.url}
              </div>
            )}
          </div>
        );

      case 'page_view':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              Page View
            </Badge>
            {triggerConfig.conditions && (
              <div className="text-xs text-gray-600">
                URL: {triggerConfig.conditions.find(c => c.field === 'url')?.value || 'Any page'}
              </div>
            )}
          </div>
        );

      case 'cart_abandonment':
        return (
          <div className="space-y-2">
            <Badge variant="outline" className="text-xs">
              E-commerce
            </Badge>
            <div className="text-xs text-gray-600">
              Trigger after cart inactivity
            </div>
          </div>
        );

      default:
        return (
          <Badge variant="outline" className="text-xs">
            {getTriggerLabel(triggerType)}
          </Badge>
        );
    }
  };

  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || getTriggerLabel(data.triggerType)
      }}
      type="trigger"
      selected={selected}
      icon={TriggerIcon}
      color="green"
      hasInput={false}
      hasOutput={true}
    >
      {renderTriggerDetails()}
    </BaseNode>
  );
};

/**
 * Webhook Node Component
 * Sends HTTP requests to external services
 */

'use client';

import React from 'react';
import { BaseNode } from './BaseNode';
import { WorkflowNodeData } from '@/types/workflow';
import { Webhook, Globe, Lock, Key, Database } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface WebhookNodeProps {
  data: WorkflowNodeData & {
    webhookConfig: {
      url: string;
      method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
      headers?: Record<string, string>;
      body?: any;
      authentication?: {
        type: 'none' | 'basic' | 'bearer' | 'api_key' | 'oauth2';
        credentials?: Record<string, string>;
      };
      timeout?: number; // seconds
      retryPolicy?: {
        enabled: boolean;
        maxRetries: number;
        backoffStrategy: 'linear' | 'exponential';
        initialDelay: number;
      };
      responseHandling?: {
        expectedStatus?: number[];
        parseJson?: boolean;
        extractFields?: Record<string, string>;
      };
    };
  };
  selected?: boolean;
}

export const WebhookNode: React.FC<WebhookNodeProps> = ({ data, selected }) => {
  const getMethodColor = (method: string) => {
    const colors = {
      GET: 'bg-green-100 text-green-600',
      POST: 'bg-blue-100 text-blue-600',
      PUT: 'bg-orange-100 text-orange-600',
      PATCH: 'bg-yellow-100 text-yellow-600',
      DELETE: 'bg-red-100 text-red-600'
    };
    return colors[method as keyof typeof colors] || 'bg-gray-100 text-gray-600';
  };

  const getAuthIcon = (authType?: string) => {
    switch (authType) {
      case 'basic':
      case 'bearer':
        return Lock;
      case 'api_key':
        return Key;
      case 'oauth2':
        return Database;
      default:
        return Globe;
    }
  };

  const AuthIcon = getAuthIcon(data.webhookConfig.authentication?.type);

  const renderWebhookDetails = () => {
    const { webhookConfig } = data;

    return (
      <div className="space-y-2">
        {/* HTTP Method */}
        <Badge className={`text-xs ${getMethodColor(webhookConfig.method)}`}>
          {webhookConfig.method}
        </Badge>

        {/* URL */}
        <div className="text-xs text-gray-600 truncate">
          {webhookConfig.url}
        </div>

        {/* Authentication */}
        {webhookConfig.authentication && webhookConfig.authentication.type !== 'none' && (
          <div className="flex items-center gap-1 text-xs text-gray-500">
            <AuthIcon className="w-3 h-3" />
            <span>{webhookConfig.authentication.type.replace('_', ' ')}</span>
          </div>
        )}

        {/* Headers count */}
        {webhookConfig.headers && Object.keys(webhookConfig.headers).length > 0 && (
          <div className="text-xs text-gray-500">
            {Object.keys(webhookConfig.headers).length} header(s)
          </div>
        )}

        {/* Timeout */}
        {webhookConfig.timeout && (
          <div className="text-xs text-gray-500">
            Timeout: {webhookConfig.timeout}s
          </div>
        )}

        {/* Retry Policy */}
        {webhookConfig.retryPolicy?.enabled && (
          <div className="text-xs text-gray-500">
            Retries: {webhookConfig.retryPolicy.maxRetries}
          </div>
        )}

        {/* Response Status */}
        {data.status === 'success' && data.lastExecuted && (
          <div className="text-xs text-green-600">
            Last response: 200 OK
          </div>
        )}

        {data.status === 'error' && data.errorMessage && (
          <div className="text-xs text-red-600 truncate">
            {data.errorMessage}
          </div>
        )}
      </div>
    );
  };

  return (
    <BaseNode
      data={{
        ...data,
        label: data.label || 'Webhook Request'
      }}
      type="webhook"
      selected={selected}
      icon={Webhook}
      color="indigo"
      hasInput={true}
      hasOutput={true}
    >
      {renderWebhookDetails()}
    </BaseNode>
  );
};

'use client';

import React, { memo } from 'react';
import { Handle, Position, NodeProps } from '@xyflow/react';
import { Zap, Mail, Database, Webhook, MessageSquare, FileText, Users } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface ActionNodeData {
  label: string;
  description?: string;
  actionType?: 'send_email' | 'add_to_crm' | 'webhook_post' | 'slack_notification' | 'update_contact' | 'create_record';
  config: Record<string, any>;
  status?: 'idle' | 'running' | 'success' | 'error';
  executionTime?: number;
}

const actionIcons = {
  send_email: Mail,
  add_to_crm: Users,
  webhook_post: Webhook,
  slack_notification: MessageSquare,
  update_contact: FileText,
  create_record: Database
};

const ActionNode = memo(({ data, selected }: NodeProps<ActionNodeData>) => {
  const { label, actionType = 'send_email', status = 'idle', executionTime } = data;
  const ActionIcon = actionIcons[actionType] || Zap;

  const getStatusColor = () => {
    switch (status) {
      case 'running': return 'border-blue-500 bg-blue-50';
      case 'success': return 'border-green-500 bg-green-50';
      case 'error': return 'border-red-500 bg-red-50';
      default: return 'border-gray-300 bg-white';
    }
  };

  const getStatusDot = () => {
    switch (status) {
      case 'running': return 'bg-blue-500 animate-pulse';
      case 'success': return 'bg-green-500';
      case 'error': return 'bg-red-500';
      default: return 'bg-gray-400';
    }
  };

  return (
    <div className={`px-4 py-3 shadow-lg rounded-lg border-2 min-w-[200px] ${getStatusColor()} ${selected ? 'ring-2 ring-indigo-500' : ''}`}>
      {/* Input handle */}
      <Handle
        type="target"
        position={Position.Left}
        className="w-3 h-3 bg-blue-500 border-2 border-white"
      />

      {/* Status indicator */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center space-x-2">
          <div className={`w-2 h-2 rounded-full ${getStatusDot()}`} />
          <Badge variant="secondary" className="text-xs">
            ACTION
          </Badge>
        </div>
        {executionTime && (
          <div className="text-xs text-gray-500">
            {executionTime}ms
          </div>
        )}
      </div>

      {/* Node content */}
      <div className="flex items-center space-x-3">
        <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
          <ActionIcon className="h-5 w-5 text-blue-600" />
        </div>
        <div className="flex-1">
          <div className="font-medium text-sm text-gray-900">{label}</div>
          <div className="text-xs text-gray-500 capitalize">
            {actionType.replace('_', ' ')}
          </div>
        </div>
      </div>

      {/* Execution info */}
      {status === 'running' && (
        <div className="mt-2 text-xs text-blue-600">
          Executing action...
        </div>
      )}

      {status === 'error' && (
        <div className="mt-2 text-xs text-red-600">
          Action failed
        </div>
      )}

      {/* Output handle */}
      <Handle
        type="source"
        position={Position.Right}
        className="w-3 h-3 bg-blue-500 border-2 border-white"
      />
    </div>
  );
});

ActionNode.displayName = 'ActionNode';

export default ActionNode;

'use client';

import React, { memo } from 'react';
import { Handle, Position, NodeProps } from '@xyflow/react';
import { GitBranch, Check, X } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

interface ConditionNodeData {
  label: string;
  description?: string;
  condition?: string;
  config: Record<string, any>;
  status?: 'idle' | 'running' | 'success' | 'error';
  lastResult?: boolean;
}

const ConditionNode = memo(({ data, selected }: NodeProps<ConditionNodeData>) => {
  const { label, condition, status = 'idle', lastResult } = data;

  const getStatusColor = () => {
    switch (status) {
      case 'running': return 'border-yellow-500 bg-yellow-50';
      case 'success': return 'border-green-500 bg-green-50';
      case 'error': return 'border-red-500 bg-red-50';
      default: return 'border-gray-300 bg-white';
    }
  };

  const getStatusDot = () => {
    switch (status) {
      case 'running': return 'bg-yellow-500 animate-pulse';
      case 'success': return 'bg-green-500';
      case 'error': return 'bg-red-500';
      default: return 'bg-gray-400';
    }
  };

  return (
    <div className={`px-4 py-3 shadow-lg rounded-lg border-2 min-w-[200px] ${getStatusColor()} ${selected ? 'ring-2 ring-indigo-500' : ''}`}>
      {/* Input handle */}
      <Handle
        type="target"
        position={Position.Left}
        className="w-3 h-3 bg-yellow-500 border-2 border-white"
      />

      {/* Status indicator */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center space-x-2">
          <div className={`w-2 h-2 rounded-full ${getStatusDot()}`} />
          <Badge variant="secondary" className="text-xs">
            CONDITION
          </Badge>
        </div>
        {lastResult !== undefined && (
          <div className="flex items-center space-x-1">
            {lastResult ? (
              <Check className="h-4 w-4 text-green-500" />
            ) : (
              <X className="h-4 w-4 text-red-500" />
            )}
          </div>
        )}
      </div>

      {/* Node content */}
      <div className="flex items-center space-x-3">
        <div className="w-10 h-10 bg-yellow-100 rounded-lg flex items-center justify-center">
          <GitBranch className="h-5 w-5 text-yellow-600" />
        </div>
        <div className="flex-1">
          <div className="font-medium text-sm text-gray-900">{label}</div>
          {condition && (
            <div className="text-xs text-gray-500 mt-1 font-mono">
              {condition}
            </div>
          )}
        </div>
      </div>

      {/* Execution info */}
      {status === 'running' && (
        <div className="mt-2 text-xs text-yellow-600">
          Evaluating condition...
        </div>
      )}

      {/* Output handles */}
      <Handle
        type="source"
        position={Position.Right}
        id="true"
        style={{ top: '40%' }}
        className="w-3 h-3 bg-green-500 border-2 border-white"
      />
      <Handle
        type="source"
        position={Position.Right}
        id="false"
        style={{ top: '70%' }}
        className="w-3 h-3 bg-red-500 border-2 border-white"
      />

      {/* Branch labels */}
      <div className="absolute -right-12 top-1/2 transform -translate-y-1/2 space-y-2 text-xs">
        <div className="text-green-600 font-medium">TRUE</div>
        <div className="text-red-600 font-medium">FALSE</div>
      </div>
    </div>
  );
});

ConditionNode.displayName = 'ConditionNode';

export default ConditionNode;

