// Convert legacy Template to EnhancedTemplate compatible format type LegacyEnhancedTemplate = Template & { subcategory?: string; is_premium?: boolean; is_featured?: boolean; usage_count?: number; rating?: number; review_count?: number; tags?: string[]; difficulty?: 'beginner' | 'intermediate' | 'advanced'; features?: string[]; preview_images?: string[]; // Add EnhancedTemplate fields target_industries?: BusinessIndustry[]; target_business_types?: BusinessType[]; design_style?: DesignStyle[]; complexity_level?: 'beginner' | 'intermediate' | 'advanced'; setup_time_minutes?: number; responsive?: boolean; mobile_optimized?: boolean; seo_optimized?: boolean; analytics_ready?: boolean; conversion_optimized?: boolean; a11y_compliant?: boolean; performance_score?: number; last_updated?: string; version?: string; intelligence_score?: TemplateIntelligenceScore; personalization_data?: TemplatePersonalizationData; usage_analytics?: TemplateUsageAnalytics; ai_insights?: TemplateAIInsights; };
// Generate AI Intelligence Score for templates const generateIntelligenceScore = (template: Partial<LegacyEnhancedTemplate>): TemplateIntelligenceScore => { const baseScore = (template.rating || 4.0) / 5.0 * 0.8; const usageScore = Math.min((template.usage_count || 1000) / 20000, 1.0) * 0.2;
return { overall_score: Math.min(baseScore + usageScore, 1.0), category_scores: { industry_alignment: template.target_industries?.length ? 0.9 : 0.7, audience_fit: 0.85, design_quality: (template.rating || 4.0) / 5.0, performance: template.performance_score || 0.8, conversion_potential: template.conversion_optimized ? 0.9 : 0.7, customization_ease: template.difficulty === 'beginner' ? 0.9 : template.difficulty === 'intermediate' ? 0.7 : 0.5 }, confidence_level: 0.85, reasoning: [ `High user satisfaction with ${(template.rating || 4.0).toFixed(1)}/5.0 rating`, `Proven performance with ${template.usage_count || 1000}+ implementations`, `Optimized for ${template.target_industries?.join(', ') || 'multiple industries'}` ], improvement_suggestions: [ 'Add more industry-specific customization options', 'Enhance mobile responsiveness', 'Improve loading performance' ] }; };
