// Helper functions export function getTemplatesByCategory(category: string): LegacyEnhancedTemplate[] { if (category === 'all') { return sampleTemplates; } return sampleTemplates.filter(template => template.category === category); }
export function getTemplateById(id: string): LegacyEnhancedTemplate | undefined { return sampleTemplates.find(template => template.id === id); }
export function getFeaturedTemplates(): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.is_featured); }
export function getPremiumTemplates(): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.is_premium); }
export function getPopularTemplates(): LegacyEnhancedTemplate[] { return sampleTemplates .sort((a, b) => (b.usage_count || 0) - (a.usage_count || 0)) .slice(0, 6); }
export function searchTemplates(query: string): LegacyEnhancedTemplate[] { const lowerQuery = query.toLowerCase(); return sampleTemplates.filter(template => template.name.toLowerCase().includes(lowerQuery) || template.description.toLowerCase().includes(lowerQuery) || template.tags?.some(tag => tag.toLowerCase().includes(lowerQuery)) || template.category.toLowerCase().includes(lowerQuery) || template.subcategory?.toLowerCase().includes(lowerQuery) ); }
// Filter templates by business intelligence scoring export function getTemplatesByIntelligenceScore(minScore: number = 0.8): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.intelligence_score && template.intelligence_score.overall_score >= minScore ); }
// Get templates recommended for specific industries export function getTemplatesForIndustry(industry: BusinessIndustry): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.target_industries?.includes(industry) ); }
// Get templates by business type export function getTemplatesForBusinessType(businessType: BusinessType): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.target_business_types?.includes(businessType) ); }
// Get templates by design style preference export function getTemplatesByDesignStyle(style: DesignStyle): LegacyEnhancedTemplate[] { return sampleTemplates.filter(template => template.design_style?.includes(style) ); }

