describe('useWorkflowStatus Hook', () => {
  let mockWebSocket: MockWebSocket;

  beforeEach(() => {
    jest.clearAllMocks();
    mockUseAuth.mockReturnValue({ token: 'test-token-123' });
  });

  afterEach(() => {
    jest.clearAllTimers();
    jest.useRealTimers();
  });

  // ========================================================================
  // CONNECTION MANAGEMENT TESTS
  // ========================================================================

  describe('Connection Management', () => {
    it('establishes WebSocket connection on mount with autoConnect', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnecting).toBe(true);
      });

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
        expect(result.current.isConnecting).toBe(false);
      });
    });

    it('does not auto-connect when autoConnect is false', () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        autoConnect: false
      }));

      expect(result.current.isConnected).toBe(false);
      expect(result.current.isConnecting).toBe(false);
    });

    it('constructs correct WebSocket URL with token', async () => {
      renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(MockWebSocket).toHaveBeenCalledWith(
          'ws://localhost:8000/api/v1/workflows/123/debug?token=test-token-123'
        );
      });
    });

    it('handles manual connect and disconnect', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        autoConnect: false
      }));

      expect(result.current.isConnected).toBe(false);

      act(() => {
        result.current.connect();
      });

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        result.current.disconnect();
      });

      await waitFor(() => {
        expect(result.current.isConnected).toBe(false);
      });
    });

    it('prevents duplicate connections', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Try to connect again
      act(() => {
        result.current.connect();
      });

      // Should still have only one connection
      expect(MockWebSocket).toHaveBeenCalledTimes(1);
    });

    it('does not connect without workflowId or token', () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        workflowId: null
      }));

      expect(result.current.isConnected).toBe(false);
      expect(MockWebSocket).not.toHaveBeenCalled();
    });
  });

  // ========================================================================
  // MESSAGE HANDLING TESTS
  // ========================================================================

  describe('Message Handling', () => {
    it('handles connected event and triggers callback', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Simulate receiving connected message
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockConnectedEvent)
          }));
        }
      });

      await waitFor(() => {
        expect(result.current.workflowInfo).toEqual({
          workflow_id: 123,
          workflow_name: 'Test Workflow',
          workflow_status: 'active',
          is_active: true
        });
        expect(result.current.recentExecutions).toEqual(mockConnectedEvent.recent_executions);
        expect(mockOptions.onConnected).toHaveBeenCalledWith(mockConnectedEvent);
      });
    });

    it('handles execution started event', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockExecutionStartedEvent)
          }));
        }
      });

      await waitFor(() => {
        expect(result.current.currentExecution).toEqual({
          execution_id: 789,
          status: 'running',
          started_at: '2024-01-15T10:30:00Z'
        });
        expect(mockOptions.onExecutionStarted).toHaveBeenCalledWith(mockExecutionStartedEvent);
      });
    });

    it('handles execution update event with node status', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockExecutionUpdateEvent)
          }));
        }
      });

      await waitFor(() => {
        const nodeStatus = result.current.nodeStatuses['node-1'];
        expect(nodeStatus).toEqual({
          id: 'node-1',
          status: 'running',
          executionTime: 2500,
          lastUpdated: new Date('2024-01-15T10:30:15Z')
        });
        expect(mockOptions.onStatusUpdate).toHaveBeenCalledWith('node-1', nodeStatus);
      });
    });

    it('handles execution completed event', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // First start an execution
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockExecutionStartedEvent)
          }));
        }
      });

      // Then complete it
      act(() => {
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockExecutionCompletedEvent)
          }));
        }
      });

      await waitFor(() => {
        expect(result.current.currentExecution).toEqual({
          execution_id: 789,
          status: 'success',
          started_at: '2024-01-15T10:30:00Z',
          finished_at: '2024-01-15T10:32:00Z',
          total_nodes: 5,
          completed_nodes: 5,
          success_rate: 100
        });
        expect(mockOptions.onExecutionComplete).toHaveBeenCalledWith(mockExecutionCompletedEvent);
      });
    });

    it('handles error events', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockErrorEvent)
          }));
        }
      });

      await waitFor(() => {
        expect(result.current.error).toBe('Connection timeout occurred');
        expect(mockOptions.onError).toHaveBeenCalledWith('Connection timeout occurred');
      });
    });

    it('handles malformed messages gracefully', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));
      const consoleSpy = jest.spyOn(console, 'error').mockImplementation();

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: 'invalid json'
          }));
        }
      });

      expect(consoleSpy).toHaveBeenCalledWith(
        '[useWorkflowStatus] Failed to parse message:',
        expect.any(Error)
      );

      consoleSpy.mockRestore();
    });
  });

  // ========================================================================
  // MESSAGE SENDING TESTS
  // ========================================================================

  describe('Message Sending', () => {
    it('sends messages when connected', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      const testMessage = { type: 'test', data: 'test-data' };

      act(() => {
        result.current.sendMessage(testMessage);
      });

      mockWebSocket = (MockWebSocket as any).mock.instances[0];
      expect(mockWebSocket.send).toHaveBeenCalledWith(JSON.stringify(testMessage));
    });

    it('queues messages when disconnected', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        autoConnect: false
      }));

      const testMessage = { type: 'test', data: 'test-data' };

      act(() => {
        result.current.sendMessage(testMessage);
      });

      expect(result.current.messageQueue).toContain(testMessage);
    });

    it('sends queued messages on connection', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        autoConnect: false
      }));

      const testMessage = { type: 'test', data: 'test-data' };

      // Queue a message while disconnected
      act(() => {
        result.current.sendMessage(testMessage);
      });

      expect(result.current.messageQueue).toContain(testMessage);

      // Connect
      act(() => {
        result.current.connect();
      });

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      mockWebSocket = (MockWebSocket as any).mock.instances[0];

      // Wait for queued messages to be processed
      await waitFor(() => {
        expect(mockWebSocket.send).toHaveBeenCalledWith(JSON.stringify(testMessage));
        expect(result.current.messageQueue).toHaveLength(0);
      });
    });

    it('provides convenience methods for common messages', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      mockWebSocket = (MockWebSocket as any).mock.instances[0];

      act(() => {
        result.current.getExecutionDetails(456);
      });

      expect(mockWebSocket.send).toHaveBeenCalledWith(JSON.stringify({
        type: 'get_execution_details',
        execution_id: 456
      }));

      act(() => {
        result.current.getNodeLogs(456, 'node-1');
      });

      expect(mockWebSocket.send).toHaveBeenCalledWith(JSON.stringify({
        type: 'get_node_logs',
        execution_id: 456,
        node_id: 'node-1'
      }));

      act(() => {
        result.current.subscribeToExecution(456);
      });

      expect(mockWebSocket.send).toHaveBeenCalledWith(JSON.stringify({
        type: 'subscribe_execution',
        execution_id: 456
      }));
    });
  });

  // ========================================================================
  // ERROR HANDLING AND RECONNECTION TESTS
  // ========================================================================

  describe('Error Handling and Reconnection', () => {
    beforeEach(() => {
      jest.useFakeTimers();
    });

    it('attempts reconnection on connection loss', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Simulate connection loss
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onclose) {
          mockWebSocket.onclose(new CloseEvent('close', { code: 1006 }));
        }
      });

      expect(result.current.isConnected).toBe(false);
      expect(result.current.connectionAttempts).toBe(1);

      // Fast-forward timer to trigger reconnection
      act(() => {
        jest.advanceTimersByTime(1000);
      });

      // Should attempt to reconnect
      expect(MockWebSocket).toHaveBeenCalledTimes(2);
    });

    it('uses exponential backoff for reconnection delays', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        reconnectDelay: 1000
      }));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Simulate multiple connection failures
      for (let attempt = 0; attempt < 3; attempt++) {
        act(() => {
          mockWebSocket = (MockWebSocket as any).mock.instances[MockWebSocket.mock.instances.length - 1];
          if (mockWebSocket.onclose) {
            mockWebSocket.onclose(new CloseEvent('close', { code: 1006 }));
          }
        });

        const expectedDelay = 1000 * Math.pow(1.5, attempt);

        act(() => {
          jest.advanceTimersByTime(expectedDelay - 1);
        });

        // Should not reconnect yet
        expect(MockWebSocket).toHaveBeenCalledTimes(attempt + 2);

        act(() => {
          jest.advanceTimersByTime(1);
        });

        // Should reconnect now
        expect(MockWebSocket).toHaveBeenCalledTimes(attempt + 3);
      }
    });

    it('stops reconnecting after max attempts', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        maxReconnectAttempts: 2
      }));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Simulate connection failures beyond max attempts
      for (let attempt = 0; attempt < 3; attempt++) {
        act(() => {
          mockWebSocket = (MockWebSocket as any).mock.instances[MockWebSocket.mock.instances.length - 1];
          if (mockWebSocket.onclose) {
            mockWebSocket.onclose(new CloseEvent('close', { code: 1006 }));
          }
        });

        act(() => {
          jest.advanceTimersByTime(5000);
        });
      }

      await waitFor(() => {
        expect(result.current.error).toBe('Maximum reconnection attempts reached');
        expect(mockOptions.onError).toHaveBeenCalledWith('Maximum reconnection attempts reached');
      });
    });

    it('does not reconnect on manual disconnect', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Manual disconnect
      act(() => {
        result.current.disconnect();
      });

      expect(result.current.isConnected).toBe(false);

      // Fast-forward timers - should not reconnect
      act(() => {
        jest.advanceTimersByTime(10000);
      });

      expect(MockWebSocket).toHaveBeenCalledTimes(1);
    });

    it('handles WebSocket errors', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onerror) {
          mockWebSocket.onerror(new Event('error'));
        }
      });

      await waitFor(() => {
        expect(result.current.error).toBe('WebSocket connection error');
        expect(mockOptions.onError).toHaveBeenCalledWith('WebSocket connection error');
      });
    });

    it('provides retry functionality', async () => {
      const { result } = renderHook(() => useWorkflowStatus({
        ...mockOptions,
        maxReconnectAttempts: 1
      }));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Cause connection failure beyond max attempts
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onclose) {
          mockWebSocket.onclose(new CloseEvent('close', { code: 1006 }));
        }
      });

      act(() => {
        jest.advanceTimersByTime(5000);
      });

      // Should fail after max attempts
      await waitFor(() => {
        expect(result.current.error).toBeTruthy();
      });

      // Retry should reset attempts and reconnect
      act(() => {
        result.current.retry();
      });

      expect(result.current.connectionAttempts).toBe(0);
      expect(MockWebSocket).toHaveBeenCalledTimes(3); // Initial + failed attempt + retry
    });

    it('clears errors when requested', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Cause an error
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onerror) {
          mockWebSocket.onerror(new Event('error'));
        }
      });

      await waitFor(() => {
        expect(result.current.error).toBeTruthy();
      });

      // Clear error
      act(() => {
        result.current.clearError();
      });

      expect(result.current.error).toBeNull();
    });
  });

  // ========================================================================
  // UTILITY METHOD TESTS
  // ========================================================================

  describe('Utility Methods', () => {
    it('provides node status lookup', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Add a node status
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onmessage) {
          mockWebSocket.onmessage(new MessageEvent('message', {
            data: JSON.stringify(mockExecutionUpdateEvent)
          }));
        }
      });

      const nodeStatus = result.current.getNodeStatus('node-1');
      expect(nodeStatus).toBeDefined();
      expect(nodeStatus?.id).toBe('node-1');
      expect(nodeStatus?.status).toBe('running');

      const missingStatus = result.current.getNodeStatus('non-existent');
      expect(missingStatus).toBeNull();
    });

    it('tracks connection latency', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      const latency = result.current.getConnectionLatency();
      expect(latency).toBeGreaterThanOrEqual(0);
    });
  });

  // ========================================================================
  // CLEANUP TESTS
  // ========================================================================

  describe('Cleanup', () => {
    it('cleans up WebSocket connection on unmount', async () => {
      const { result, unmount } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      mockWebSocket = (MockWebSocket as any).mock.instances[0];

      unmount();

      expect(mockWebSocket.close).toHaveBeenCalledWith(1000, 'Manual disconnect');
    });

    it('clears reconnection timers on unmount', async () => {
      jest.useFakeTimers();

      const { result, unmount } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      // Cause disconnection to start reconnection timer
      act(() => {
        mockWebSocket = (MockWebSocket as any).mock.instances[0];
        if (mockWebSocket.onclose) {
          mockWebSocket.onclose(new CloseEvent('close', { code: 1006 }));
        }
      });

      const clearTimeoutSpy = jest.spyOn(global, 'clearTimeout');

      unmount();

      expect(clearTimeoutSpy).toHaveBeenCalled();
      clearTimeoutSpy.mockRestore();
    });
  });

  // ========================================================================
  // PERFORMANCE TESTS
  // ========================================================================

  describe('Performance', () => {
    it('memoizes return value to prevent unnecessary re-renders', () => {
      const { result, rerender } = renderHook(() => useWorkflowStatus(mockOptions));

      const initialReturn = result.current;

      // Re-render with same props
      rerender();

      // The memoized return should be the same reference
      expect(result.current).toBe(initialReturn);
    });

    it('handles high-frequency message updates efficiently', async () => {
      const { result } = renderHook(() => useWorkflowStatus(mockOptions));

      await waitFor(() => {
        expect(result.current.isConnected).toBe(true);
      });

      mockWebSocket = (MockWebSocket as any).mock.instances[0];

      // Send 100 rapid updates
      const startTime = Date.now();

      act(() => {
        for (let i = 0; i < 100; i++) {
          if (mockWebSocket.onmessage) {
            mockWebSocket.onmessage(new MessageEvent('message', {
              data: JSON.stringify({
                ...mockExecutionUpdateEvent,
                node_id: `node-${i}`,
                execution_time_ms: i * 100
              })
            }));
          }
        }
      });

      const endTime = Date.now();
      const duration = endTime - startTime;

      // Should process all updates quickly (less than 100ms for 100 updates)
      expect(duration).toBeLessThan(100);
      expect(Object.keys(result.current.nodeStatuses)).toHaveLength(100);
    });
  });
});

/**
 * Hooks Index
 * Central export point for all custom hooks
 */

export { useAuth } from './useAuth';
export { useTemplates, useTemplate, useFeaturedTemplates } from './useTemplates';
export { useWorkflows, useWorkflow, useWorkflowExecutions } from './useWorkflows';
export { useContacts, useContact, useEmailCampaigns, useCRMAnalytics } from './useCRM';
export { usePublishing } from './usePublishing';

// Re-export types for convenience
export type {
  LoadingState
} from '@/lib/api/types';

import { useState, useCallback, useRef } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData } from '@/types/builder';

export interface AIEdit {
  id: string;
  prompt: string;
  originalCode: string;
  modifiedCode: string;
  timestamp: Date;
  applied: boolean;
  description: string;
  componentId: string;
}

export interface AIEditorState {
  isOpen: boolean;
  currentCode: string;
  originalCode: string;
  aiEdits: AIEdit[];
  currentEditIndex: number;
  isProcessing: boolean;
  aiSuggestions: string[];
}

interface UseAIEditorReturn {
  state: AIEditorState;
  openEditor: (component: ComponentData, initialCode?: string) => void;
  closeEditor: () => void;
  applyAIEdit: (edit: AIEdit) => Promise<void>;
  undoLastEdit: () => void;
  redoLastEdit: () => void;
  resetToOriginal: () => void;
  generateCodeFromComponent: (component: ComponentData) => string;
  processAIPrompt: (prompt: string) => Promise<AIEdit>;
}

export function useAIEditor(): UseAIEditorReturn {
  const [state, setState] = useState<AIEditorState>({
    isOpen: false,
    currentCode: '',
    originalCode: '',
    aiEdits: [],
    currentEditIndex: -1,
    isProcessing: false,
    aiSuggestions: []
  });

  const componentRef = useRef<ComponentData | null>(null);
  const { updateComponent } = useBuilderStore();

  const generateCodeFromComponent = useCallback((component: ComponentData): string => {
    const { type, props, content } = component;

    // Generate React component code based on type
    switch (type) {
      case 'button':
        return `<button
  className="${props.className || ''}"
  style={${JSON.stringify(props.style || {})}}
  ${props.onClick ? 'onClick={handleClick}' : ''}
>
  ${content || props.text || 'Button'}
</button>`;

      case 'text':
        return `<p
  className="${props.className || ''}"
  style={${JSON.stringify(props.style || {})}}
>
  ${content || props.text || 'Text content'}
</p>`;

      case 'container':
        return `<div
  className="${props.className || ''}"
  style={${JSON.stringify(props.style || {})}}
>
  ${content || ''}
</div>`;

      case 'form':
        return `<form
  className="${props.className || ''}"
  style={${JSON.stringify(props.style || {})}}
  onSubmit={handleSubmit}
>
  ${content || ''}
</form>`;

      default:
        return `<div
  className="${props.className || ''}"
  style={${JSON.stringify(props.style || {})}}
>
  ${content || 'Component'}
</div>`;
    }
  }, []);

  const processAIPrompt = useCallback(async (prompt: string): Promise<AIEdit> => {
    if (!componentRef.current) {
      throw new Error('No component selected');
    }

    setState(prev => ({ ...prev, isProcessing: true }));

    try {
      // Simulate AI processing - replace with actual API call
      const modifiedCode = await simulateAIEditing(state.currentCode, prompt);

      const newEdit: AIEdit = {
        id: `ai-${Date.now()}`,
        prompt,
        originalCode: state.currentCode,
        modifiedCode,
        timestamp: new Date(),
        applied: false,
        description: `AI: ${prompt.substring(0, 50)}...`,
        componentId: componentRef.current.id
      };

      setState(prev => ({
        ...prev,
        aiEdits: [...prev.aiEdits, newEdit],
        currentEditIndex: prev.aiEdits.length,
        currentCode: modifiedCode,
        isProcessing: false
      }));

      return newEdit;
    } catch (error) {
      setState(prev => ({ ...prev, isProcessing: false }));
      throw error;
    }
  }, [state.currentCode]);

  const simulateAIEditing = async (code: string, prompt: string): Promise<string> => {
    // Simulate AI response based on prompt and code
    return new Promise((resolve) => {
      setTimeout(() => {
        let modifiedCode = code;
        const promptLower = prompt.toLowerCase();

        // Smart replacements based on prompt keywords
        if (promptLower.includes('button') && promptLower.includes('blue')) {
          modifiedCode = modifiedCode.replace(
            /bg-(red|green|yellow|purple|pink|indigo|gray)-\d+/g,
            'bg-blue-500'
          );
        }

        if (promptLower.includes('larger') || promptLower.includes('bigger')) {
          modifiedCode = modifiedCode.replace(
            /className="([^"]*)px-4 py-2([^"]*)"/g,
            'className="$1px-6 py-3$2"'
          );
        }

        if (promptLower.includes('animation') || promptLower.includes('hover')) {
          modifiedCode = modifiedCode.replace(
            /className="([^"]*)"/g,
            'className="$1 hover:scale-105 transition-transform duration-200"'
          );
        }

        if (promptLower.includes('modern') || promptLower.includes('professional')) {
          modifiedCode = modifiedCode.replace(
            /style={{([^}]*)}}/g,
            'style={{ borderRadius: "8px", boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1)", $1 }}'
          );
        }

        resolve(modifiedCode);
      }, 1000);
    });
  };

  const openEditor = useCallback((component: ComponentData, initialCode?: string) => {
    componentRef.current = component;
    const code = initialCode || generateCodeFromComponent(component);

    setState({
      isOpen: true,
      currentCode: code,
      originalCode: code,
      aiEdits: [],
      currentEditIndex: -1,
      isProcessing: false,
      aiSuggestions: [
        'Make this component more prominent',
        'Add hover animations and transitions',
        'Improve spacing and visual hierarchy',
        'Apply modern design patterns',
        'Optimize for mobile responsiveness'
      ]
    });
  }, [generateCodeFromComponent]);

  const closeEditor = useCallback(() => {
    setState({
      ...state,
      isOpen: false
    });
  }, [state]);

  const applyAIEdit = useCallback(async (edit: AIEdit) => {
    if (!componentRef.current) return;

    // Update the component with the AI-generated changes
    const updatedProps = parseCodeToProps(edit.modifiedCode);

    updateComponent(componentRef.current.id, {
      props: { ...componentRef.current.props, ...updatedProps }
    });

    setState(prev => ({
      ...prev,
      aiEdits: prev.aiEdits.map(e => 
        e.id === edit.id ? { ...e, applied: true } : e
      )
    }));
  }, [updateComponent]);

  const parseCodeToProps = (code: string): any => {
    // Simple parser to extract props from React component code
    // This is a basic implementation - in production, use a proper AST parser
    const props: any = {};

    // Extract className
    const classNameMatch = code.match(/className="([^"]*)"/);
    if (classNameMatch) {
      props.className = classNameMatch[1];
    }

    // Extract style object
    const styleMatch = code.match(/style={({[^}]*})}/);
    if (styleMatch) {
      try {
        props.style = JSON.parse(styleMatch[1].replace(/'/g, '"'));
      } catch (e) {
        props.style = {};
      }
    }

    // Extract content
    const contentMatch = code.match(/>\s*([^<>]*)\s*</);
    if (contentMatch && contentMatch[1].trim()) {
      props.content = contentMatch[1].trim();
    }

    return props;
  };

  const undoLastEdit = useCallback(() => {
    const { currentEditIndex, aiEdits } = state;
    if (currentEditIndex > 0) {
      const previousEdit = aiEdits[currentEditIndex - 1];
      setState(prev => ({
        ...prev,
        currentCode: previousEdit.originalCode,
        currentEditIndex: currentEditIndex - 1
      }));
    } else if (currentEditIndex === 0) {
      setState(prev => ({
        ...prev,
        currentCode: prev.originalCode,
        currentEditIndex: -1
      }));
    }
  }, [state]);

  const redoLastEdit = useCallback(() => {
    const { currentEditIndex, aiEdits } = state;
    if (currentEditIndex < aiEdits.length - 1) {
      const nextEdit = aiEdits[currentEditIndex + 1];
      setState(prev => ({
        ...prev,
        currentCode: nextEdit.modifiedCode,
        currentEditIndex: currentEditIndex + 1
      }));
    }
  }, [state]);

  const resetToOriginal = useCallback(() => {
    setState(prev => ({
      ...prev,
      currentCode: prev.originalCode,
      aiEdits: [],
      currentEditIndex: -1
    }));
  }, []);

  return {
    state,
    openEditor,
    closeEditor,
    applyAIEdit,
    undoLastEdit,
    redoLastEdit,
    resetToOriginal,
    generateCodeFromComponent,
    processAIPrompt
  };
}

/**
 * Authentication Hook
 */

import { useState, useEffect, useCallback } from 'react';
import { authService } from '@/lib/api/services';
import type { 
  User, 
  LoginCredentials, 
  RegisterData, 
  AuthResponse, 
  LoadingState 
} from '@/lib/api/types';

interface UseAuthReturn extends LoadingState {
  user: User | null;
  isAuthenticated: boolean;
  login: (credentials: LoginCredentials) => Promise<AuthResponse>;
  register: (userData: RegisterData) => Promise<AuthResponse>;
  logout: () => Promise<void>;
  updateProfile: (userData: Partial<User>) => Promise<User>;
  refreshToken: () => Promise<AuthResponse>;
  changePassword: (currentPassword: string, newPassword: string) => Promise<{ message: string }>;
}

export function useAuth(): UseAuthReturn {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Check if user is authenticated on mount
  useEffect(() => {
    const initializeAuth = async () => {
      try {
        if (authService.isAuthenticated()) {
          const currentUser = await authService.getCurrentUser();
          setUser(currentUser);
        }
      } catch (err) {
        console.error('Failed to initialize auth:', err);
        // Clear invalid token
        authService.logout();
      } finally {
        setIsLoading(false);
      }
    };

    initializeAuth();
  }, []);

  const login = useCallback(async (credentials: LoginCredentials): Promise<AuthResponse> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await authService.login(credentials);
      setUser(response.user);

      return response;
    } catch (err: any) {
      const errorMessage = err.message || 'Login failed';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const register = useCallback(async (userData: RegisterData): Promise<AuthResponse> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await authService.register(userData);
      setUser(response.user);

      return response;
    } catch (err: any) {
      const errorMessage = err.message || 'Registration failed';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const logout = useCallback(async (): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await authService.logout();
      setUser(null);
    } catch (err: any) {
      const errorMessage = err.message || 'Logout failed';
      setError(errorMessage);
      console.error('Logout error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateProfile = useCallback(async (userData: Partial<User>): Promise<User> => {
    try {
      setIsLoading(true);
      setError(null);

      const updatedUser = await authService.updateProfile(userData);
      setUser(updatedUser);

      return updatedUser;
    } catch (err: any) {
      const errorMessage = err.message || 'Profile update failed';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const refreshToken = useCallback(async (): Promise<AuthResponse> => {
    try {
      setError(null);

      const response = await authService.refreshToken();
      setUser(response.user);

      return response;
    } catch (err: any) {
      const errorMessage = err.message || 'Token refresh failed';
      setError(errorMessage);
      throw err;
    }
  }, []);

  const changePassword = useCallback(async (
    currentPassword: string, 
    newPassword: string
  ): Promise<{ message: string }> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await authService.changePassword(currentPassword, newPassword);
      return response;
    } catch (err: any) {
      const errorMessage = err.message || 'Password change failed';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  return {
    user,
    isAuthenticated: !!user,
    isLoading,
    error,
    login,
    register,
    logout,
    updateProfile,
    refreshToken,
    changePassword
  };
}

/**
 * useCollaboration Hook
 * Manages real-time collaboration state and operations
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { 
  CollaborationState, 
  CollaborationUser, 
  CollaborationEvent,
  UserCursor,
  ComponentLock,
  ChatMessage,
  CollaborationError,
  SyncPreferences
} from '@/types/collaboration';
import { ComponentData } from '@/types/builder';
import { collaborationWS, WebSocketStatus } from '@/lib/collaboration/websocket';

interface UseCollaborationOptions {
  projectId: string;
  userId: string;
  userName: string;
  userEmail: string;
  authToken: string;
  autoConnect?: boolean;
  syncPreferences?: Partial<SyncPreferences>;
}

interface UseCollaborationReturn {
  // Connection state
  isConnected: boolean;
  connectionStatus: WebSocketStatus;
  error: CollaborationError | null;

  // Users and presence
  currentUser: CollaborationUser | null;
  activeUsers: CollaborationUser[];
  userCursors: Map<string, UserCursor>;

  // Component management
  componentLocks: Map<string, ComponentLock>;
  isComponentLocked: (componentId: string) => boolean;
  lockComponent: (componentId: string, lockType: 'editing' | 'moving' | 'resizing') => void;
  unlockComponent: (componentId: string) => void;

  // Real-time operations
  updateCursor: (position: { x: number; y: number }, visible?: boolean) => void;
  selectComponent: (componentId: string | null) => void;

  // Chat functionality
  chatMessages: ChatMessage[];
  sendChatMessage: (message: string, componentId?: string) => void;

  // Connection management
  connect: () => Promise<void>;
  disconnect: () => void;
  reconnect: () => Promise<void>;

  // Sync preferences
  syncPreferences: SyncPreferences;
  updateSyncPreferences: (preferences: Partial<SyncPreferences>) => void;
}

const defaultSyncPreferences: SyncPreferences = {
  enableRealTimeSync: true,
  enableCursorSharing: true,
  enableComponentLocking: true,
  enableChatNotifications: true,
  autoSaveInterval: 5000, // 5 seconds
  conflictResolutionStrategy: 'auto',
};

export function useCollaboration(options: UseCollaborationOptions): UseCollaborationReturn {
  const {
    projectId,
    userId,
    userName,
    userEmail,
    authToken,
    autoConnect = true,
    syncPreferences: initialSyncPreferences = {},
  } = options;

  // Builder store actions
  const {
    addComponent,
    updateComponent,
    removeComponent,
    updateComponentPosition,
    updateComponentSize,
    selectComponent: selectComponentInStore,
  } = useBuilderStore();

  // Local collaboration state
  const [collaborationState, setCollaborationState] = useState<CollaborationState>({
    isConnected: false,
    connectionStatus: 'disconnected',
    currentUser: null,
    activeUsers: [],
    userCursors: new Map(),
    componentLocks: new Map(),
    lastPingTime: null,
    connectionId: null,
  });

  const [error, setError] = useState<CollaborationError | null>(null);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [syncPreferences, setSyncPreferences] = useState<SyncPreferences>({
    ...defaultSyncPreferences,
    ...initialSyncPreferences,
  });

  // Refs for stable callbacks
  const lastCursorUpdate = useRef<Date>(new Date());
  const autoSaveTimer = useRef<NodeJS.Timeout | null>(null);
  const isInitialized = useRef(false);

  // Generate user color for cursor/presence
  const getUserColor = useCallback((userId: string): string => {
    const colors = [
      '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEAA7',
      '#DDA0DD', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E9',
    ];
    const hash = userId.split('').reduce((a, b) => {
      a = ((a << 5) - a) + b.charCodeAt(0);
      return a & a;
    }, 0);
    return colors[Math.abs(hash) % colors.length];
  }, []);

  // Create current user object
  const currentUser: CollaborationUser = {
    id: userId,
    name: userName,
    email: userEmail,
    color: getUserColor(userId),
    status: 'active',
    lastSeen: new Date(),
    permissions: 'editor', // TODO: Get from user context
  };

  // WebSocket event handlers
  const handleConnectionStatusChange = useCallback((status: WebSocketStatus) => {
    setCollaborationState(prev => ({
      ...prev,
      connectionStatus: status,
      isConnected: status === 'connected',
    }));
  }, []);

  const handleCollaborationEvent = useCallback((event: CollaborationEvent) => {
    if (!syncPreferences.enableRealTimeSync) return;

    switch (event.type) {
      case 'user.joined':
        setCollaborationState(prev => ({
          ...prev,
          activeUsers: [...prev.activeUsers.filter(u => u.id !== event.user.id), event.user],
        }));
        break;

      case 'user.left':
        setCollaborationState(prev => ({
          ...prev,
          activeUsers: prev.activeUsers.filter(u => u.id !== event.userId),
          userCursors: new Map([...prev.userCursors].filter(([id]) => id !== event.userId)),
          componentLocks: new Map([...prev.componentLocks].filter(([, lock]) => lock.userId !== event.userId)),
        }));
        break;

      case 'user.cursor_update':
        if (syncPreferences.enableCursorSharing && event.userId !== userId) {
          setCollaborationState(prev => ({
            ...prev,
            userCursors: new Map(prev.userCursors.set(event.userId, event.cursor)),
          }));
        }
        break;

      case 'component.added':
        if (event.userId !== userId) {
          addComponent(event.component);
        }
        break;

      case 'component.updated':
        if (event.userId !== userId) {
          updateComponent(event.componentId, event.changes);
        }
        break;

      case 'component.deleted':
        if (event.userId !== userId) {
          removeComponent(event.componentId);
        }
        break;

      case 'component.moved':
        if (event.userId !== userId) {
          updateComponentPosition(event.componentId, event.position);
        }
        break;

      case 'component.resized':
        if (event.userId !== userId) {
          updateComponentSize(event.componentId, event.size);
        }
        break;

      case 'component.selected':
        if (event.userId !== userId) {
          // Show visual indicator of other user's selection
          // This doesn't change our local selection
        }
        break;

      case 'component.locked':
        if (syncPreferences.enableComponentLocking) {
          setCollaborationState(prev => ({
            ...prev,
            componentLocks: new Map(prev.componentLocks.set(event.lock.componentId, event.lock)),
          }));
        }
        break;

      case 'component.unlocked':
        setCollaborationState(prev => ({
          ...prev,
          componentLocks: new Map([...prev.componentLocks].filter(([id]) => id !== event.componentId)),
        }));
        break;

      case 'chat.message':
        const chatMessage: ChatMessage = {
          id: event.id,
          userId: event.userId,
          user: collaborationState.activeUsers.find(u => u.id === event.userId) || currentUser,
          message: event.message,
          timestamp: event.timestamp,
          type: 'text',
        };
        setChatMessages(prev => [...prev, chatMessage]);
        break;
    }
  }, [
    syncPreferences,
    userId,
    addComponent,
    updateComponent,
    removeComponent,
    updateComponentPosition,
    updateComponentSize,
    collaborationState.activeUsers,
    currentUser,
  ]);

  const handleUserList = useCallback((users: CollaborationUser[]) => {
    setCollaborationState(prev => ({
      ...prev,
      activeUsers: users.filter(u => u.id !== userId),
    }));
  }, [userId]);

  const handleError = useCallback((error: CollaborationError) => {
    console.error('Collaboration error:', error);
    setError(error);

    // Clear error after 5 seconds for recoverable errors
    if (error.recoverable) {
      setTimeout(() => setError(null), 5000);
    }
  }, []);

  // Connection management
  const connect = useCallback(async () => {
    try {
      setError(null);
      await collaborationWS.connect(userId, projectId, authToken);

      setCollaborationState(prev => ({
        ...prev,
        currentUser,
        isConnected: true,
        connectionStatus: 'connected',
      }));

      // Request current user list
      collaborationWS.requestUserList();
    } catch (error) {
      setError({
        type: 'connection',
        message: error instanceof Error ? error.message : 'Connection failed',
        code: 'CONNECTION_FAILED',
        timestamp: new Date(),
        recoverable: true,
      });
    }
  }, [userId, projectId, authToken, currentUser]);

  const disconnect = useCallback(() => {
    collaborationWS.disconnect();
    setCollaborationState(prev => ({
      ...prev,
      isConnected: false,
      connectionStatus: 'disconnected',
      activeUsers: [],
      userCursors: new Map(),
      componentLocks: new Map(),
    }));
  }, []);

  const reconnect = useCallback(async () => {
    disconnect();
    await connect();
  }, [connect, disconnect]);

  // Real-time operations
  const updateCursor = useCallback((position: { x: number; y: number }, visible: boolean = true) => {
    if (!syncPreferences.enableCursorSharing || !collaborationWS.isConnected()) return;

    const now = new Date();
    if (now.getTime() - lastCursorUpdate.current.getTime() > 100) { // Throttle to 10fps
      collaborationWS.updateCursor(position, visible);
      lastCursorUpdate.current = now;
    }
  }, [syncPreferences.enableCursorSharing]);

  const selectComponent = useCallback((componentId: string | null) => {
    selectComponentInStore(componentId);

    if (collaborationWS.isConnected()) {
      collaborationWS.selectComponent(componentId);
    }
  }, [selectComponentInStore]);

  // Component locking
  const isComponentLocked = useCallback((componentId: string): boolean => {
    const lock = collaborationState.componentLocks.get(componentId);
    if (!lock) return false;

    // Check if lock has expired
    if (new Date() > lock.expiresAt) {
      // Remove expired lock
      setCollaborationState(prev => ({
        ...prev,
        componentLocks: new Map([...prev.componentLocks].filter(([id]) => id !== componentId)),
      }));
      return false;
    }

    return lock.userId !== userId;
  }, [collaborationState.componentLocks, userId]);

  const lockComponent = useCallback((componentId: string, lockType: 'editing' | 'moving' | 'resizing') => {
    if (!syncPreferences.enableComponentLocking || !collaborationWS.isConnected()) return;

    if (!isComponentLocked(componentId)) {
      collaborationWS.lockComponent(componentId, lockType);
    }
  }, [syncPreferences.enableComponentLocking, isComponentLocked]);

  const unlockComponent = useCallback((componentId: string) => {
    if (collaborationWS.isConnected()) {
      collaborationWS.unlockComponent(componentId);
    }
  }, []);

  // Chat functionality
  const sendChatMessage = useCallback((message: string, componentId?: string) => {
    if (collaborationWS.isConnected()) {
      collaborationWS.sendChatMessage(message, componentId);
    }
  }, []);

  // Sync preferences
  const updateSyncPreferences = useCallback((preferences: Partial<SyncPreferences>) => {
    setSyncPreferences(prev => ({ ...prev, ...preferences }));
  }, []);

  // Setup WebSocket event listeners
  useEffect(() => {
    if (isInitialized.current) return;
    isInitialized.current = true;

    collaborationWS.on('connected', () => handleConnectionStatusChange('connected'));
    collaborationWS.on('disconnected', () => handleConnectionStatusChange('disconnected'));
    collaborationWS.on('error', handleError);
    collaborationWS.on('event', handleCollaborationEvent);
    collaborationWS.on('user_list', handleUserList);

    return () => {
      collaborationWS.off('connected', handleConnectionStatusChange);
      collaborationWS.off('disconnected', handleConnectionStatusChange);
      collaborationWS.off('error', handleError);
      collaborationWS.off('event', handleCollaborationEvent);
      collaborationWS.off('user_list', handleUserList);
    };
  }, [
    handleConnectionStatusChange,
    handleError,
    handleCollaborationEvent,
    handleUserList,
  ]);

  // Auto-connect on mount
  useEffect(() => {
    if (autoConnect && !collaborationWS.isConnected()) {
      connect();
    }

    return () => {
      if (autoSaveTimer.current) {
        clearTimeout(autoSaveTimer.current);
      }
    };
  }, [autoConnect, connect]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      disconnect();
    };
  }, [disconnect]);

  return {
    // Connection state
    isConnected: collaborationState.isConnected,
    connectionStatus: collaborationState.connectionStatus,
    error,

    // Users and presence
    currentUser: collaborationState.currentUser,
    activeUsers: collaborationState.activeUsers,
    userCursors: collaborationState.userCursors,

    // Component management
    componentLocks: collaborationState.componentLocks,
    isComponentLocked,
    lockComponent,
    unlockComponent,

    // Real-time operations
    updateCursor,
    selectComponent,

    // Chat functionality
    chatMessages,
    sendChatMessage,

    // Connection management
    connect,
    disconnect,
    reconnect,

    // Sync preferences
    syncPreferences,
    updateSyncPreferences,
  };
}

/**
 * CRM Hook
 */

import { useState, useEffect, useCallback } from 'react';
import { crmService } from '@/lib/api/services';
import type { 
  Contact, 
  ContactCreate, 
  ContactUpdate, 
  ContactFilters,
  EmailCampaign,
  EmailCampaignCreate,
  EmailCampaignUpdate,
  PaginatedResponse,
  LoadingState 
} from '@/lib/api/types';

// ============ CONTACTS HOOK ============

interface UseContactsReturn extends LoadingState {
  contacts: Contact[];
  totalContacts: number;
  currentPage: number;
  totalPages: number;
  refreshContacts: () => Promise<void>;
  loadMore: () => Promise<void>;
  createContact: (contactData: ContactCreate) => Promise<Contact>;
  updateContact: (contactId: number, contactData: ContactUpdate) => Promise<Contact>;
  deleteContact: (contactId: number) => Promise<void>;
  bulkDeleteContacts: (contactIds: number[]) => Promise<void>;
  addContactTags: (contactId: number, tags: string[]) => Promise<Contact>;
  removeContactTags: (contactId: number, tags: string[]) => Promise<Contact>;
}

interface UseContactsOptions {
  filters?: ContactFilters;
  autoLoad?: boolean;
  pageSize?: number;
}

export function useContacts(options: UseContactsOptions = {}): UseContactsReturn {
  const {
    filters = {},
    autoLoad = true,
    pageSize = 20
  } = options;

  const [contacts, setContacts] = useState<Contact[]>([]);
  const [totalContacts, setTotalContacts] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadContacts = useCallback(async (
    page: number = 1, 
    append: boolean = false
  ): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await crmService.getContacts({
        ...filters,
        skip: (page - 1) * pageSize,
        limit: pageSize
      });

      if (append) {
        setContacts(prev => [...prev, ...response.items]);
      } else {
        setContacts(response.items);
      }

      setTotalContacts(response.total);
      setCurrentPage(page);
      setTotalPages(response.pages);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load contacts';
      setError(errorMessage);
      console.error('Load contacts error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [filters, pageSize]);

  const refreshContacts = useCallback((): Promise<void> => {
    return loadContacts(1, false);
  }, [loadContacts]);

  const loadMore = useCallback((): Promise<void> => {
    if (currentPage < totalPages) {
      return loadContacts(currentPage + 1, true);
    }
    return Promise.resolve();
  }, [loadContacts, currentPage, totalPages]);

  const createContact = useCallback(async (contactData: ContactCreate): Promise<Contact> => {
    try {
      setIsLoading(true);
      setError(null);

      const newContact = await crmService.createContact(contactData);

      // Add to the beginning of the list
      setContacts(prev => [newContact, ...prev]);
      setTotalContacts(prev => prev + 1);

      return newContact;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to create contact';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateContact = useCallback(async (
    contactId: number, 
    contactData: ContactUpdate
  ): Promise<Contact> => {
    try {
      setIsLoading(true);
      setError(null);

      const updatedContact = await crmService.updateContact(contactId, contactData);

      // Update in the list
      setContacts(prev => prev.map(contact => 
        contact.id === contactId ? updatedContact : contact
      ));

      return updatedContact;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to update contact';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const deleteContact = useCallback(async (contactId: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await crmService.deleteContact(contactId);

      // Remove from the list
      setContacts(prev => prev.filter(contact => contact.id !== contactId));
      setTotalContacts(prev => prev - 1);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to delete contact';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const bulkDeleteContacts = useCallback(async (contactIds: number[]): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await crmService.bulkDeleteContacts(contactIds);

      // Remove from the list
      setContacts(prev => prev.filter(contact => !contactIds.includes(contact.id)));
      setTotalContacts(prev => prev - contactIds.length);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to delete contacts';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const addContactTags = useCallback(async (
    contactId: number, 
    tags: string[]
  ): Promise<Contact> => {
    try {
      setError(null);

      const updatedContact = await crmService.addContactTags(contactId, tags);

      // Update in the list
      setContacts(prev => prev.map(contact => 
        contact.id === contactId ? updatedContact : contact
      ));

      return updatedContact;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to add tags to contact';
      setError(errorMessage);
      throw err;
    }
  }, []);

  const removeContactTags = useCallback(async (
    contactId: number, 
    tags: string[]
  ): Promise<Contact> => {
    try {
      setError(null);

      const updatedContact = await crmService.removeContactTags(contactId, tags);

      // Update in the list
      setContacts(prev => prev.map(contact => 
        contact.id === contactId ? updatedContact : contact
      ));

      return updatedContact;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to remove tags from contact';
      setError(errorMessage);
      throw err;
    }
  }, []);

  // Load contacts on mount if autoLoad is enabled
  useEffect(() => {
    if (autoLoad) {
      loadContacts();
    }
  }, [autoLoad, loadContacts]);

  // Reload when filters change
  useEffect(() => {
    if (autoLoad) {
      loadContacts(1, false);
    }
  }, [filters, autoLoad, loadContacts]);

  return {
    contacts,
    totalContacts,
    currentPage,
    totalPages,
    isLoading,
    error,
    refreshContacts,
    loadMore,
    createContact,
    updateContact,
    deleteContact,
    bulkDeleteContacts,
    addContactTags,
    removeContactTags
  };
}

// ============ SINGLE CONTACT HOOK ============

export function useContact(contactId: number | null) {
  const [contact, setContact] = useState<Contact | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadContact = useCallback(async (id: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const contactData = await crmService.getContact(id);
      setContact(contactData);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load contact';
      setError(errorMessage);
      console.error('Load contact error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (contactId) {
      loadContact(contactId);
    } else {
      setContact(null);
    }
  }, [contactId, loadContact]);

  return {
    contact,
    isLoading,
    error,
    refreshContact: () => contactId ? loadContact(contactId) : Promise.resolve()
  };
}

// ============ EMAIL CAMPAIGNS HOOK ============

interface UseEmailCampaignsReturn extends LoadingState {
