      }

      setTotalCampaigns(response.total);
      setCurrentPage(page);
      setTotalPages(response.pages);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load email campaigns';
      setError(errorMessage);
      console.error('Load campaigns error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [filters, pageSize]);

  const refreshCampaigns = useCallback((): Promise<void> => {
    return loadCampaigns(1, false);
  }, [loadCampaigns]);

  const loadMore = useCallback((): Promise<void> => {
    if (currentPage < totalPages) {
      return loadCampaigns(currentPage + 1, true);
    }
    return Promise.resolve();
  }, [loadCampaigns, currentPage, totalPages]);

  const createCampaign = useCallback(async (campaignData: EmailCampaignCreate): Promise<EmailCampaign> => {
    try {
      setIsLoading(true);
      setError(null);

      const newCampaign = await crmService.createEmailCampaign(campaignData);

      // Add to the beginning of the list
      setCampaigns(prev => [newCampaign, ...prev]);
      setTotalCampaigns(prev => prev + 1);

      return newCampaign;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to create email campaign';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateCampaign = useCallback(async (
    campaignId: number, 
    campaignData: EmailCampaignUpdate
  ): Promise<EmailCampaign> => {
    try {
      setIsLoading(true);
      setError(null);

      const updatedCampaign = await crmService.updateEmailCampaign(campaignId, campaignData);

      // Update in the list
      setCampaigns(prev => prev.map(campaign => 
        campaign.id === campaignId ? updatedCampaign : campaign
      ));

      return updatedCampaign;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to update email campaign';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const deleteCampaign = useCallback(async (campaignId: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await crmService.deleteEmailCampaign(campaignId);

      // Remove from the list
      setCampaigns(prev => prev.filter(campaign => campaign.id !== campaignId));
      setTotalCampaigns(prev => prev - 1);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to delete email campaign';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const sendCampaign = useCallback(async (campaignId: number) => {
    try {
      setError(null);

      const result = await crmService.sendEmailCampaign(campaignId);

      // Update campaign status
      setCampaigns(prev => prev.map(campaign => 
        campaign.id === campaignId 
          ? { ...campaign, status: 'sent' as const, sent_at: new Date().toISOString() }
          : campaign
      ));

      return result;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to send email campaign';
      setError(errorMessage);
      throw err;
    }
  }, []);

  const testCampaign = useCallback(async (campaignId: number, testEmail: string) => {
    try {
      setError(null);

      const result = await crmService.testEmailCampaign(campaignId, testEmail);
      return result;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to test email campaign';
      setError(errorMessage);
      throw err;
    }
  }, []);

  // Load campaigns on mount if autoLoad is enabled
  useEffect(() => {
    if (autoLoad) {
      loadCampaigns();
    }
  }, [autoLoad, loadCampaigns]);

  // Reload when filters change
  useEffect(() => {
    if (autoLoad) {
      loadCampaigns(1, false);
    }
  }, [filters, autoLoad, loadCampaigns]);

  return {
    campaigns,
    totalCampaigns,
    currentPage,
    totalPages,
    isLoading,
    error,
    refreshCampaigns,
    loadMore,
    createCampaign,
    updateCampaign,
    deleteCampaign,
    sendCampaign,
    testCampaign
  };
}

// ============ CRM ANALYTICS HOOK ============

export function useCRMAnalytics() {
  const [overview, setOverview] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadAnalytics = useCallback(async (): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const overviewData = await crmService.getCRMOverview();
      setOverview(overviewData);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load CRM analytics';
      setError(errorMessage);
      console.error('Load CRM analytics error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAnalytics();
  }, [loadAnalytics]);

  return {
    overview,
    isLoading,
    error,
    refresh: loadAnalytics
  };
}

/**
 * Magic Connector Hook
 * 
 * React hook for managing Magic Connector functionality throughout the application
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { ComponentData } from '@/types/builder';
import { 
  magicConnector, 
  MagicConnectorAnalysis, 
  MagicConnectorSuggestion,
  WorkflowConnection,
  MagicConnectorContext 
} from '@/lib/ai/magic-connector';

interface UseMagicConnectorOptions {
  autoAnalyze?: boolean;
  debounceMs?: number;
  cacheResults?: boolean;
  enableRealTimeUpdates?: boolean;
}

interface UseMagicConnectorReturn {
  // Analysis state
  analyses: Map<string, MagicConnectorAnalysis>;
  currentAnalysis: MagicConnectorAnalysis | null;
  isAnalyzing: boolean;
  analysisError: string | null;

  // Workflow connections
  connections: WorkflowConnection[];
  activeConnections: WorkflowConnection[];

  // Canvas-wide insights
  canvasInsights: {
    totalSuggestions: number;
    highPrioritySuggestions: number;
    automationPotential: number;
    estimatedTimesSaved: string;
    estimatedConversionIncrease: string;
  };

  // Actions
  analyzeComponent: (component: ComponentData, context?: MagicConnectorContext) => Promise<MagicConnectorAnalysis>;
  analyzeAllComponents: (context?: MagicConnectorContext) => Promise<void>;
  connectWorkflow: (componentId: string, suggestion: MagicConnectorSuggestion) => Promise<WorkflowConnection>;
  disconnectWorkflow: (connectionId: string) => Promise<void>;
  refreshAnalysis: (componentId?: string) => Promise<void>;
  clearAnalyses: () => void;

  // Real-time monitoring
  startMonitoring: (componentId: string) => void;
  stopMonitoring: (componentId: string) => void;

  // Bulk operations
  connectAllHighPriority: () => Promise<WorkflowConnection[]>;
  generateCanvasReport: () => Promise<{
    summary: string;
    recommendations: string[];
    automationOpportunities: string[];
    performanceMetrics: Record<string, number>;
  }>;
}

export function useMagicConnector(options: UseMagicConnectorOptions = {}): UseMagicConnectorReturn {
  const {
    autoAnalyze = true,
    debounceMs = 500,
    cacheResults = true,
    enableRealTimeUpdates = false
  } = options;

  // State
  const [analyses, setAnalyses] = useState<Map<string, MagicConnectorAnalysis>>(new Map());
  const [connections, setConnections] = useState<WorkflowConnection[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [monitoredComponents, setMonitoredComponents] = useState<Set<string>>(new Set());

  // Builder store
  const { components, selectedComponentId, getSelectedComponent } = useBuilderStore();

  // Current analysis for selected component
  const currentAnalysis = useMemo(() => {
    if (!selectedComponentId) return null;
    return analyses.get(selectedComponentId) || null;
  }, [selectedComponentId, analyses]);

  // Active connections (status = 'active' or 'connected')
  const activeConnections = useMemo(() => {
    return connections.filter(conn => 
      conn.status === 'active' || conn.status === 'connected'
    );
  }, [connections]);

  // Canvas-wide insights
  const canvasInsights = useMemo(() => {
    const allSuggestions = Array.from(analyses.values())
      .flatMap(analysis => analysis.suggestions);

    const highPrioritySuggestions = allSuggestions.filter(s => s.priority === 'high');

    const automationPotential = Array.from(analyses.values())
      .reduce((total, analysis) => total + analysis.performancePredictions.automationPotential, 0) / 
      Math.max(analyses.size, 1);

    // Calculate estimated savings from all suggestions
    const timesSaved = allSuggestions
      .map(s => parseFloat(s.estimatedImpact.timesSaved.replace(/[^\d.]/g, '')))
      .reduce((total, hours) => total + (hours || 0), 0);

    const conversionIncrease = allSuggestions
      .map(s => parseFloat(s.estimatedImpact.conversionIncrease.replace(/[^\d.]/g, '')))
      .reduce((total, increase) => total + (increase || 0), 0) / Math.max(allSuggestions.length, 1);

    return {
      totalSuggestions: allSuggestions.length,
      highPrioritySuggestions: highPrioritySuggestions.length,
      automationPotential: Math.round(automationPotential * 100),
      estimatedTimesSaved: `${Math.round(timesSaved)} hours/week`,
      estimatedConversionIncrease: `+${Math.round(conversionIncrease)}%`
    };
  }, [analyses]);

  // Debounced analysis function
  const analyzeComponent = useCallback(async (
    component: ComponentData, 
    context?: MagicConnectorContext
  ): Promise<MagicConnectorAnalysis> => {
    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
      // Enhanced context with current page state
      const enhancedContext: MagicConnectorContext = {
        pageContent: components.map(c => c.name).join(' '),
        businessType: 'general', // Could be inferred or set by user
        industry: 'technology', // Could be detected from content
        userBehavior: {
          scrollDepth: 75,
          timeOnPage: Date.now(),
          previousActions: ['component_select', 'analysis_request']
        },
        existingWorkflows: activeConnections.map(c => c.workflowId),
        ...context
      };

      const analysis = await magicConnector.analyzeComponent(component, enhancedContext);

      if (cacheResults) {
        setAnalyses(prev => new Map(prev).set(component.id, analysis));
      }

      return analysis;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Analysis failed';
      setAnalysisError(errorMessage);
      console.error('Magic Connector analysis failed:', error);
      throw error;
    } finally {
      setIsAnalyzing(false);
    }
  }, [components, activeConnections, cacheResults]);

  // Analyze all components
  const analyzeAllComponents = useCallback(async (context?: MagicConnectorContext) => {
    if (components.length === 0) return;

    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
      const analysisPromises = components.map(component => 
        analyzeComponent(component, context)
      );

      const results = await Promise.allSettled(analysisPromises);

      // Filter successful results
      const successfulAnalyses = results
        .filter((result): result is PromiseFulfilledResult<MagicConnectorAnalysis> => 
          result.status === 'fulfilled'
        )
        .map(result => result.value);

      // Update analyses map
      setAnalyses(prev => {
        const newMap = new Map(prev);
        successfulAnalyses.forEach(analysis => {
          newMap.set(analysis.componentId, analysis);
        });
        return newMap;
      });

      // Check for failed analyses
      const failures = results.filter(result => result.status === 'rejected');
      if (failures.length > 0) {
        console.warn(`${failures.length} component analyses failed`);
      }

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Batch analysis failed';
      setAnalysisError(errorMessage);
      console.error('Batch analysis failed:', error);
    } finally {
      setIsAnalyzing(false);
    }
  }, [components, analyzeComponent]);

  // Connect workflow
  const connectWorkflow = useCallback(async (
    componentId: string, 
    suggestion: MagicConnectorSuggestion
  ): Promise<WorkflowConnection> => {
    try {
      const connection = await magicConnector.connectWorkflow(
        componentId, 
        suggestion.workflow.workflowId,
        { source: 'magic_connector_hook', suggestion: suggestion.title }
      );

      setConnections(prev => [...prev, connection]);

      // Update component in builder store
      useBuilderStore.getState().connectToWorkflow(componentId, suggestion.workflow.workflowId);

      return connection;
    } catch (error) {
      console.error('Failed to connect workflow:', error);
      throw error;
    }
  }, []);

  // Disconnect workflow
  const disconnectWorkflow = useCallback(async (connectionId: string) => {
    try {
      const connection = connections.find(c => c.id === connectionId);
      if (!connection) {
        throw new Error('Connection not found');
      }

      // Remove from connections
      setConnections(prev => prev.filter(c => c.id !== connectionId));

      // Update component in builder store
      useBuilderStore.getState().disconnectFromWorkflow(connection.componentId);

    } catch (error) {
      console.error('Failed to disconnect workflow:', error);
      throw error;
    }
  }, [connections]);

  // Refresh analysis
  const refreshAnalysis = useCallback(async (componentId?: string) => {
    if (componentId) {
      const component = components.find(c => c.id === componentId);
      if (component) {
        await analyzeComponent(component);
      }
    } else {
      await analyzeAllComponents();
    }
  }, [components, analyzeComponent, analyzeAllComponents]);

  // Clear analyses
  const clearAnalyses = useCallback(() => {
    setAnalyses(new Map());
    setAnalysisError(null);
  }, []);

  // Real-time monitoring
  const startMonitoring = useCallback((componentId: string) => {
    setMonitoredComponents(prev => new Set(prev).add(componentId));
  }, []);

  const stopMonitoring = useCallback((componentId: string) => {
    setMonitoredComponents(prev => {
      const newSet = new Set(prev);
      newSet.delete(componentId);
      return newSet;
    });
  }, []);

  // Bulk operations
  const connectAllHighPriority = useCallback(async (): Promise<WorkflowConnection[]> => {
    const highPrioritySuggestions = Array.from(analyses.values())
      .flatMap(analysis => 
        analysis.suggestions
          .filter(s => s.priority === 'high' && s.oneClickSetup)
          .map(s => ({ componentId: analysis.componentId, suggestion: s }))
      );

    const connectionPromises = highPrioritySuggestions.map(({ componentId, suggestion }) =>
      connectWorkflow(componentId, suggestion)
    );

    try {
      const newConnections = await Promise.all(connectionPromises);
      return newConnections;
    } catch (error) {
      console.error('Failed to connect all high priority workflows:', error);
      throw error;
    }
  }, [analyses, connectWorkflow]);

  // Generate canvas report
  const generateCanvasReport = useCallback(async () => {
    const canvasAnalysis = await magicConnector.analyzeCanvas(components);

    return {
      summary: `Analyzed ${components.length} components with ${canvasInsights.totalSuggestions} workflow suggestions (${canvasInsights.highPrioritySuggestions} high-priority). Estimated automation potential: ${canvasInsights.automationPotential}%`,
      recommendations: canvasAnalysis.funnelOptimizations,
      automationOpportunities: Array.from(analyses.values())
        .flatMap(analysis => analysis.automationOpportunities),
      performanceMetrics: {
        totalComponents: components.length,
        analyzedComponents: analyses.size,
        totalSuggestions: canvasInsights.totalSuggestions,
        highPrioritySuggestions: canvasInsights.highPrioritySuggestions,
        activeConnections: activeConnections.length,
        automationPotential: canvasInsights.automationPotential
      }
    };
  }, [components, canvasInsights, analyses, activeConnections]);

  // Auto-analyze when components change
  useEffect(() => {
    if (!autoAnalyze || components.length === 0) return;

    // Debounce the analysis
    const timeoutId = setTimeout(() => {
      // Only analyze new components that haven't been analyzed yet
      const unanalyzedComponents = components.filter(component => 
        !analyses.has(component.id)
      );

      if (unanalyzedComponents.length > 0) {
        // Analyze new components individually to avoid overwhelming the system
        unanalyzedComponents.slice(0, 3).forEach(component => {
          analyzeComponent(component).catch(error => {
            console.warn(`Failed to auto-analyze component ${component.id}:`, error);
          });
        });
      }
    }, debounceMs);

    return () => clearTimeout(timeoutId);
  }, [components, autoAnalyze, debounceMs, analyses, analyzeComponent]);

  // Real-time monitoring effect
  useEffect(() => {
    if (!enableRealTimeUpdates || monitoredComponents.size === 0) return;

    const intervalId = setInterval(async () => {
      for (const componentId of monitoredComponents) {
        try {
          await refreshAnalysis(componentId);
        } catch (error) {
          console.warn(`Real-time monitoring failed for component ${componentId}:`, error);
        }
      }
    }, 10000); // Monitor every 10 seconds

    return () => clearInterval(intervalId);
  }, [enableRealTimeUpdates, monitoredComponents, refreshAnalysis]);

  return {
    // State
    analyses,
    currentAnalysis,
    isAnalyzing,
    analysisError,
    connections,
    activeConnections,
    canvasInsights,

    // Actions
    analyzeComponent,
    analyzeAllComponents,
    connectWorkflow,
    disconnectWorkflow,
    refreshAnalysis,
    clearAnalyses,

    // Real-time monitoring
    startMonitoring,
    stopMonitoring,

    // Bulk operations
    connectAllHighPriority,
    generateCanvasReport
  };
}

// Convenience hook for a single component
export function useMagicConnectorForComponent(componentId: string | null) {
  const magicConnector = useMagicConnector({ autoAnalyze: false });
  const { components } = useBuilderStore();

  const component = useMemo(() => 
    componentId ? components.find(c => c.id === componentId) : null,
    [componentId, components]
  );

  const analysis = useMemo(() => 
    componentId ? magicConnector.analyses.get(componentId) : null,
    [componentId, magicConnector.analyses]
  );

  const analyze = useCallback(async () => {
    if (component) {
      return await magicConnector.analyzeComponent(component);
    }
    return null;
  }, [component, magicConnector.analyzeComponent]);

  return {
    component,
    analysis,
    analyze,
    isAnalyzing: magicConnector.isAnalyzing,
    error: magicConnector.analysisError,
    connectWorkflow: magicConnector.connectWorkflow,
    refreshAnalysis: () => magicConnector.refreshAnalysis(componentId || undefined)
  };
}

export default useMagicConnector;

import { useState, useCallback } from 'react'
import { apiClient } from '@/lib/api/client'

export interface MigrationRequest {
  url: string
  depth: number
  include_assets: boolean
  optimize_content: boolean
  generate_redirects: boolean
}

export interface MigrationStatus {
  id: string
  status: 'starting' | 'scraping' | 'processing' | 'optimizing' | 'completed' | 'failed' | 'cancelled'
  progress: number
  total_pages: number
  processed_pages: number
  errors: string[]
  warnings: string[]
  estimated_time_remaining: string
}

export interface MigrationResult {
  id: string
  original_url: string
  scraped_data: any
  processed_data: any
  migration_plan: any
  recommendations: string[]
  warnings: string[]
  created_at: string
}

export interface MigrationTemplate {
  name: string
  type: string
  content: string
  structure: any
  components: any[]
  metadata: any
  priority: string
}

export interface MigrationAnalysis {
  analysis: {
    feasible: boolean
    complexity: string
    warnings: string[]
    recommendations: string[]
    estimated_time: string
  }
  report: {
    summary: any
    content_analysis: any
    technical_details: any
    migration_plan: any
  }
  preview: {
    pages_found: number
    assets_found: number
    styles_found: number
    scripts_found: number
  }
}

export function useMigrationService() {
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const startMigration = useCallback(async (
    url: string,
    depth: number = 3,
    includeAssets: boolean = true,
    optimizeContent: boolean = true,
    generateRedirects: boolean = true
  ): Promise<{ id: string }> => {
    try {
      setIsLoading(true)
      setError(null)

      const response = await apiClient.post('/migration/start', {
        url,
        depth,
        include_assets: includeAssets,
        optimize_content: optimizeContent,
        generate_redirects: generateRedirects
      })

      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to start migration')
      throw err
    } finally {
      setIsLoading(false)
    }
  }, [])

  const getMigrationStatus = useCallback(async (migrationId: string): Promise<MigrationStatus> => {
    try {
      setError(null)
      const response = await apiClient.get(`/migration/status/${migrationId}`)
      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to get migration status')
      throw err
    }
  }, [])

  const analyzeWebsite = useCallback(async (
    url: string,
    depth: number = 1
  ): Promise<MigrationAnalysis> => {
    try {
      setIsLoading(true)
      setError(null)

      const response = await apiClient.post('/migration/analyze', {
        url,
        depth,
        include_assets: true,
        optimize_content: true,
        generate_redirects: true
      })

      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to analyze website')
      throw err
    } finally {
      setIsLoading(false)
    }
  }, [])

  const getMigrationResult = useCallback(async (migrationId: string): Promise<MigrationResult> => {
    try {
      setError(null)
      const response = await apiClient.get(`/migration/result/${migrationId}`)
      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to get migration result')
      throw err
    }
  }, [])

  const getMigrationTemplates = useCallback(async (migrationId: string): Promise<{
    templates: MigrationTemplate[]
    theme_data: any
    migration_id: string
  }> => {
    try {
      setError(null)
      const response = await apiClient.get(`/migration/templates/${migrationId}`)
      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to get migration templates')
      throw err
    }
  }, [])

  const getActiveMigrations = useCallback(async (): Promise<MigrationStatus[]> => {
    try {
      setError(null)
      const response = await apiClient.get('/migration/active')
      return response.data
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to get active migrations')
      throw err
    }
  }, [])

  const cancelMigration = useCallback(async (migrationId: string): Promise<void> => {
    try {
      setError(null)
      await apiClient.delete(`/migration/cancel/${migrationId}`)
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to cancel migration')
      throw err
    }
  }, [])

  return {
    startMigration,
    getMigrationStatus,
    analyzeWebsite,
    getMigrationResult,
    getMigrationTemplates,
    getActiveMigrations,
    cancelMigration,
    isLoading,
    error
  }
}

'use client';

import { useState, useCallback } from 'react';
import { useBuilderStore } from '@/store/builderStore';

export interface PublishingOptions {
  customDomain?: string;
  seoSettings?: {
    title?: string;
    description?: string;
    keywords?: string[];
    socialImage?: string;
  };
  performanceOptimization?: boolean;
  analyticsId?: string;
}

export interface PublishingStatus {
  status: 'idle' | 'preparing' | 'building' | 'optimizing' | 'uploading' | 'configuring' | 'success' | 'error';
  progress: number;
  message: string;
  taskId?: string;
  publishedUrl?: string;
  error?: string;
}

export interface PublishingResult {
  success: boolean;
  url?: string;
  error?: string;
  taskId?: string;
}

export const usePublishing = () => {
  const { canvasElements, siteName, siteSettings } = useBuilderStore();
  const [publishingStatus, setPublishingStatus] = useState<PublishingStatus>({
    status: 'idle',
    progress: 0,
    message: ''
  });

  const updateStatus = useCallback((update: Partial<PublishingStatus>) => {
    setPublishingStatus(prev => ({ ...prev, ...update }));
  }, []);

  const publishSite = useCallback(async (options: PublishingOptions = {}): Promise<PublishingResult> => {
    try {
      // Validation
      if (!canvasElements || canvasElements.length === 0) {
        throw new Error('No content to publish. Please add components to your site.');
      }

      if (!siteName) {
        throw new Error('Site name is required for publishing.');
      }

      // Prepare publishing data
      updateStatus({
        status: 'preparing',
        progress: 10,
        message: 'Preparing site for publication...'
      });

      const publishData = {
        site_name: siteName,
        components: canvasElements,
        settings: {
          ...siteSettings,
          ...options.seoSettings
        },
        custom_domain: options.customDomain,
        performance_optimization: options.performanceOptimization ?? true,
        analytics_id: options.analyticsId
      };

      // Start building
      updateStatus({
        status: 'building',
        progress: 25,
        message: 'Converting components to HTML/CSS...'
      });

      // Call backend API
      const response = await fetch('/api/v1/sites/publish', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(publishData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Publishing failed');
      }

      const result = await response.json();

      if (result.task_id) {
        // Poll for status updates
        await pollPublishingStatus(result.task_id);
      }

      return {
        success: true,
        url: result.published_url || publishingStatus.publishedUrl,
        taskId: result.task_id
      };

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';

      updateStatus({
        status: 'error',
        progress: 0,
        message: errorMessage,
        error: errorMessage
      });

      return {
        success: false,
        error: errorMessage
      };
    }
  }, [canvasElements, siteName, siteSettings, publishingStatus.publishedUrl, updateStatus]);

  const pollPublishingStatus = useCallback(async (taskId: string): Promise<void> => {
    const maxAttempts = 60; // 5 minutes max
    let attempts = 0;

    const poll = async (): Promise<void> => {
      try {
        const response = await fetch(`/api/v1/sites/publish/status/${taskId}`);

        if (!response.ok) {
          throw new Error('Failed to get publishing status');
        }

        const status = await response.json();

        // Update progress based on status
        const progressMap: Record<string, { progress: number; message: string; status: PublishingStatus['status'] }> = {
          'PENDING': { progress: 15, message: 'Task queued for processing...', status: 'preparing' },
          'BUILDING': { progress: 35, message: 'Building static site...', status: 'building' },
          'OPTIMIZING': { progress: 55, message: 'Optimizing images and assets...', status: 'optimizing' },
          'UPLOADING': { progress: 75, message: 'Uploading to CDN...', status: 'uploading' },
          'CONFIGURING': { progress: 90, message: 'Configuring domain and SSL...', status: 'configuring' },
          'SUCCESS': { progress: 100, message: 'Site published successfully!', status: 'success' },
          'FAILURE': { progress: 0, message: 'Publishing failed', status: 'error' }
        };

        const statusInfo = progressMap[status.status] || progressMap['PENDING'];

        updateStatus({
          ...statusInfo,
          taskId,
          publishedUrl: status.published_url,
          error: status.error
        });

        if (status.status === 'SUCCESS' || status.status === 'FAILURE') {
          return; // Stop polling
        }

        // Continue polling
        attempts++;
        if (attempts < maxAttempts) {
          setTimeout(poll, 5000); // Poll every 5 seconds
        } else {
          throw new Error('Publishing timeout - please check status manually');
        }

      } catch (error) {
        updateStatus({
          status: 'error',
          progress: 0,
          message: error instanceof Error ? error.message : 'Failed to check publishing status',
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    };

    await poll();
  }, [updateStatus]);

  const checkDomainStatus = useCallback(async (domain: string) => {
    try {
      const response = await fetch(`/api/v1/domains/verify`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ domain }),
      });

      if (!response.ok) {
        throw new Error('Failed to check domain status');
      }

      return await response.json();
    } catch (error) {
      console.error('Domain check failed:', error);
      return { verified: false, error: error instanceof Error ? error.message : 'Unknown error' };
    }
  }, []);

  const getPublishingHistory = useCallback(async () => {
    try {
      const response = await fetch('/api/v1/sites/publish/history');

      if (!response.ok) {
        throw new Error('Failed to get publishing history');
      }

      return await response.json();
    } catch (error) {
      console.error('Failed to get publishing history:', error);
      return { deployments: [] };
    }
  }, []);

  const cancelPublishing = useCallback(async (taskId: string) => {
    try {
      const response = await fetch(`/api/v1/sites/publish/cancel/${taskId}`, {
        method: 'POST',
      });

      if (!response.ok) {
        throw new Error('Failed to cancel publishing');
      }

      updateStatus({
        status: 'idle',
        progress: 0,
        message: 'Publishing cancelled'
      });

      return { success: true };
    } catch (error) {
      console.error('Failed to cancel publishing:', error);
      return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
    }
  }, [updateStatus]);

  const resetPublishing = useCallback(() => {
    setPublishingStatus({
      status: 'idle',
      progress: 0,
      message: ''
    });
  }, []);

  return {
    publishingStatus,
    publishSite,
    checkDomainStatus,
    getPublishingHistory,
    cancelPublishing,
    resetPublishing,
    isPublishing: publishingStatus.status !== 'idle' && publishingStatus.status !== 'success' && publishingStatus.status !== 'error',
    isSuccess: publishingStatus.status === 'success',
    isError: publishingStatus.status === 'error',
  };
};

/**
 * Templates Hook
 */

import { useState, useEffect, useCallback } from 'react';
import { templateService } from '@/lib/api/services';
import type { 
  Template, 
  TemplateCreate, 
  TemplateUpdate, 
  TemplateFilters,
  PaginatedResponse,
  LoadingState 
} from '@/lib/api/types';

interface UseTemplatesReturn extends LoadingState {
  templates: Template[];
  totalTemplates: number;
  currentPage: number;
  totalPages: number;
  refreshTemplates: () => Promise<void>;
  loadMore: () => Promise<void>;
  createTemplate: (templateData: TemplateCreate) => Promise<Template>;
  updateTemplate: (templateId: number, templateData: TemplateUpdate) => Promise<Template>;
  deleteTemplate: (templateId: number) => Promise<void>;
  duplicateTemplate: (templateId: number, name?: string) => Promise<Template>;
}

interface UseTemplatesOptions {
  filters?: TemplateFilters;
  autoLoad?: boolean;
  pageSize?: number;
}

export function useTemplates(options: UseTemplatesOptions = {}): UseTemplatesReturn {
  const {
    filters = {},
    autoLoad = true,
    pageSize = 20
  } = options;

  const [templates, setTemplates] = useState<Template[]>([]);
  const [totalTemplates, setTotalTemplates] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadTemplates = useCallback(async (
    page: number = 1, 
    append: boolean = false
  ): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await templateService.getTemplates({
        ...filters,
        skip: (page - 1) * pageSize,
        limit: pageSize
      });

      if (append) {
        setTemplates(prev => [...prev, ...response.items]);
      } else {
        setTemplates(response.items);
      }

      setTotalTemplates(response.total);
      setCurrentPage(page);
      setTotalPages(response.pages);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load templates';
      setError(errorMessage);
      console.error('Load templates error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [filters, pageSize]);

  const refreshTemplates = useCallback((): Promise<void> => {
    return loadTemplates(1, false);
  }, [loadTemplates]);

  const loadMore = useCallback((): Promise<void> => {
    if (currentPage < totalPages) {
      return loadTemplates(currentPage + 1, true);
    }
    return Promise.resolve();
  }, [loadTemplates, currentPage, totalPages]);

  const createTemplate = useCallback(async (templateData: TemplateCreate): Promise<Template> => {
    try {
      setIsLoading(true);
      setError(null);

      const newTemplate = await templateService.createTemplate(templateData);

      // Add to the beginning of the list
      setTemplates(prev => [newTemplate, ...prev]);
      setTotalTemplates(prev => prev + 1);

      return newTemplate;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to create template';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateTemplate = useCallback(async (
    templateId: number, 
    templateData: TemplateUpdate
  ): Promise<Template> => {
    try {
      setIsLoading(true);
      setError(null);

      const updatedTemplate = await templateService.updateTemplate(templateId, templateData);

      // Update in the list
      setTemplates(prev => prev.map(template => 
        template.id === templateId ? updatedTemplate : template
      ));

      return updatedTemplate;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to update template';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const deleteTemplate = useCallback(async (templateId: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await templateService.deleteTemplate(templateId);

      // Remove from the list
      setTemplates(prev => prev.filter(template => template.id !== templateId));
      setTotalTemplates(prev => prev - 1);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to delete template';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const duplicateTemplate = useCallback(async (
    templateId: number, 
    name?: string
  ): Promise<Template> => {
    try {
      setIsLoading(true);
      setError(null);

      const duplicatedTemplate = await templateService.duplicateTemplate(templateId, name);

      // Add to the beginning of the list
      setTemplates(prev => [duplicatedTemplate, ...prev]);
      setTotalTemplates(prev => prev + 1);

      return duplicatedTemplate;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to duplicate template';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Load templates on mount if autoLoad is enabled
  useEffect(() => {
    if (autoLoad) {
      loadTemplates();
    }
  }, [autoLoad, loadTemplates]);

  // Reload when filters change
  useEffect(() => {
    if (autoLoad) {
      loadTemplates(1, false);
    }
  }, [filters, autoLoad, loadTemplates]);

  return {
    templates,
    totalTemplates,
    currentPage,
    totalPages,
    isLoading,
    error,
    refreshTemplates,
    loadMore,
    createTemplate,
    updateTemplate,
    deleteTemplate,
    duplicateTemplate
  };
}

// Hook for single template
export function useTemplate(templateId: number | null) {
  const [template, setTemplate] = useState<Template | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadTemplate = useCallback(async (id: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const templateData = await templateService.getTemplate(id);
      setTemplate(templateData);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load template';
      setError(errorMessage);
      console.error('Load template error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (templateId) {
      loadTemplate(templateId);
    } else {
      setTemplate(null);
    }
  }, [templateId, loadTemplate]);

  return {
    template,
    isLoading,
    error,
    refreshTemplate: () => templateId ? loadTemplate(templateId) : Promise.resolve()
  };
}

// Hook for featured templates
export function useFeaturedTemplates(limit: number = 10) {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadFeaturedTemplates = useCallback(async (): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const featuredTemplates = await templateService.getFeaturedTemplates(limit);
      setTemplates(featuredTemplates);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load featured templates';
      setError(errorMessage);
      console.error('Load featured templates error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [limit]);

  useEffect(() => {
    loadFeaturedTemplates();
  }, [loadFeaturedTemplates]);

  return {
    templates,
    isLoading,
    error,
    refresh: loadFeaturedTemplates
  };
}

'use client';

import { useState, useCallback, useEffect, useMemo } from 'react';
import { useBuilderStore } from '@/store/builderStore';
import { sampleTemplates, getTemplateById } from '@/data/templates';

interface TemplateSelectionState {
  isLoading: boolean;
  error: string | null;
  selectedTemplateId: string | null;
  recentlyUsed: string[];
  favorites: Set<string>;
  searchTerm: string;
  selectedCategory: string;
  sortBy: 'popular' | 'newest' | 'rating' | 'name';
}

interface UseTemplateSelectionReturn {
  state: TemplateSelectionState;
  actions: {
    // Template operations
    applyTemplate: (templateId: string) => Promise<void>;
    previewTemplate: (templateId: string) => void;
    selectTemplate: (templateId: string) => void;
    clearSelection: () => void;

    // Favorites management
    addToFavorites: (templateId: string) => void;
    removeFromFavorites: (templateId: string) => void;
    toggleFavorite: (templateId: string) => void;

    // Search and filtering
    setSearchTerm: (term: string) => void;
    setCategory: (category: string) => void;
    setSortBy: (sort: 'popular' | 'newest' | 'rating' | 'name') => void;
    clearFilters: () => void;

    // Utility functions
    getFilteredTemplates: () => any[];
    getTemplateById: (templateId: string) => any | null;
    isTemplateFavorited: (templateId: string) => boolean;
    isTemplateRecentlyUsed: (templateId: string) => boolean;
  };
  analytics: {
    totalTemplates: number;
    filteredCount: number;
    favoriteCount: number;
    recentCount: number;
    categoryStats: Record<string, number>;
  };
}

export const useTemplateSelection = (): UseTemplateSelectionReturn => {
  const { loadTemplate, currentTemplate, canvasComponents } = useBuilderStore();

  // Local state management
  const [state, setState] = useState<TemplateSelectionState>({
    isLoading: false,
    error: null,
    selectedTemplateId: null,
    recentlyUsed: [],
    favorites: new Set(),
    searchTerm: '',
    selectedCategory: 'all',
    sortBy: 'popular'
  });

  // Load persisted data from localStorage
  useEffect(() => {
    try {
      const savedFavorites = localStorage.getItem('template-favorites');
      const savedRecentlyUsed = localStorage.getItem('template-recently-used');

      if (savedFavorites) {
        const favorites = JSON.parse(savedFavorites);
        setState(prev => ({ ...prev, favorites: new Set(favorites) }));
      }

      if (savedRecentlyUsed) {
        const recentlyUsed = JSON.parse(savedRecentlyUsed);
        setState(prev => ({ ...prev, recentlyUsed }));
      }
    } catch (error) {
      console.warn('Failed to load template selection data from localStorage:', error);
    }
  }, []);

  // Persist favorites to localStorage
  useEffect(() => {
    try {
      localStorage.setItem('template-favorites', JSON.stringify(Array.from(state.favorites)));
    } catch (error) {
      console.warn('Failed to save favorites to localStorage:', error);
    }
  }, [state.favorites]);

  // Persist recently used to localStorage
  useEffect(() => {
    try {
      localStorage.setItem('template-recently-used', JSON.stringify(state.recentlyUsed));
    } catch (error) {
      console.warn('Failed to save recently used to localStorage:', error);
    }
  }, [state.recentlyUsed]);

  // Template operations
  const applyTemplate = useCallback(async (templateId: string) => {
    const template = getTemplateById(templateId);
    if (!template) {
      setState(prev => ({ ...prev, error: 'Template not found' }));
      return;
    }

    setState(prev => ({ ...prev, isLoading: true, error: null }));

    try {
      // Simulate network delay for better UX
      await new Promise(resolve => setTimeout(resolve, 500));

      // Apply template to builder store
      loadTemplate(template);

      // Add to recently used (limit to 10 items)
      setState(prev => ({
        ...prev,
        recentlyUsed: [
          templateId,
          ...prev.recentlyUsed.filter(id => id !== templateId)
        ].slice(0, 10),
        selectedTemplateId: templateId,
        isLoading: false
      }));

    } catch (error) {
      console.error('Failed to apply template:', error);
      setState(prev => ({ 
        ...prev, 
        error: error instanceof Error ? error.message : 'Failed to apply template',
        isLoading: false 
      }));
    }
  }, [loadTemplate]);

  const previewTemplate = useCallback((templateId: string) => {
    setState(prev => ({ ...prev, selectedTemplateId: templateId }));
  }, []);

  const selectTemplate = useCallback((templateId: string) => {
    setState(prev => ({ ...prev, selectedTemplateId: templateId }));
  }, []);

  const clearSelection = useCallback(() => {
    setState(prev => ({ ...prev, selectedTemplateId: null }));
  }, []);

  // Favorites management
  const addToFavorites = useCallback((templateId: string) => {
    setState(prev => ({
      ...prev,
      favorites: new Set([...prev.favorites, templateId])
    }));
  }, []);

  const removeFromFavorites = useCallback((templateId: string) => {
    setState(prev => {
      const newFavorites = new Set(prev.favorites);
      newFavorites.delete(templateId);
      return { ...prev, favorites: newFavorites };
    });
  }, []);

  const toggleFavorite = useCallback((templateId: string) => {
    setState(prev => {
      const newFavorites = new Set(prev.favorites);
      if (newFavorites.has(templateId)) {
        newFavorites.delete(templateId);
      } else {
        newFavorites.add(templateId);
      }
      return { ...prev, favorites: newFavorites };
    });
  }, []);

  // Search and filtering
  const setSearchTerm = useCallback((term: string) => {
    setState(prev => ({ ...prev, searchTerm: term }));
  }, []);

  const setCategory = useCallback((category: string) => {
    setState(prev => ({ ...prev, selectedCategory: category }));
  }, []);

  const setSortBy = useCallback((sort: 'popular' | 'newest' | 'rating' | 'name') => {
    setState(prev => ({ ...prev, sortBy: sort }));
  }, []);

  const clearFilters = useCallback(() => {
    setState(prev => ({
      ...prev,
      searchTerm: '',
      selectedCategory: 'all',
      sortBy: 'popular'
    }));
  }, []);

  // Utility functions
  const getFilteredTemplates = useCallback(() => {
    let templates = state.selectedCategory === 'all' 
      ? sampleTemplates 
      : sampleTemplates.filter(t => t.category === state.selectedCategory);

    // Apply search filter
    if (state.searchTerm) {
      const searchLower = state.searchTerm.toLowerCase();
      templates = templates.filter(template =>
        template.name.toLowerCase().includes(searchLower) ||
        template.description.toLowerCase().includes(searchLower) ||
        (template as any).tags?.some((tag: string) => 
          tag.toLowerCase().includes(searchLower)
        )
      );
    }

    // Apply sorting
    templates.sort((a, b) => {
      switch (state.sortBy) {
        case 'popular':
          return ((b as any).usage_count || 0) - ((a as any).usage_count || 0);
        case 'newest':
          return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
        case 'rating':
          return ((b as any).rating || 0) - ((a as any).rating || 0);
        case 'name':
          return a.name.localeCompare(b.name);
        default:
          return 0;
      }
    });

    return templates;
  }, [state.searchTerm, state.selectedCategory, state.sortBy]);

  const getTemplateByIdWrapper = useCallback((templateId: string) => {
    return getTemplateById(templateId) || null;
  }, []);

  const isTemplateFavorited = useCallback((templateId: string) => {
    return state.favorites.has(templateId);
  }, [state.favorites]);

  const isTemplateRecentlyUsed = useCallback((templateId: string) => {
    return state.recentlyUsed.includes(templateId);
  }, [state.recentlyUsed]);

  // Analytics
  const analytics = useMemo(() => {
    const filteredTemplates = getFilteredTemplates();

    // Calculate category stats
    const categoryStats: Record<string, number> = {};
    sampleTemplates.forEach(template => {
      categoryStats[template.category] = (categoryStats[template.category] || 0) + 1;
    });

    return {
      totalTemplates: sampleTemplates.length,
      filteredCount: filteredTemplates.length,
      favoriteCount: state.favorites.size,
      recentCount: state.recentlyUsed.length,
      categoryStats
    };
  }, [getFilteredTemplates, state.favorites.size, state.recentlyUsed.length]);

  return {
    state,
    actions: {
      applyTemplate,
      previewTemplate,
      selectTemplate,
      clearSelection,
      addToFavorites,
      removeFromFavorites,
      toggleFavorite,
      setSearchTerm,
      setCategory,
      setSortBy,
      clearFilters,
      getFilteredTemplates,
      getTemplateById: getTemplateByIdWrapper,
      isTemplateFavorited,
      isTemplateRecentlyUsed
    },
    analytics
  };
};

export default useTemplateSelection;

/**
 * Workflows Hook
 */

import { useState, useEffect, useCallback } from 'react';
import { workflowService } from '@/lib/api/services';
import type { 
  Workflow, 
  WorkflowCreate, 
  WorkflowUpdate, 
  WorkflowExecution,
  PaginatedResponse,
  LoadingState 
} from '@/lib/api/types';

interface UseWorkflowsReturn extends LoadingState {
  workflows: Workflow[];
  totalWorkflows: number;
  currentPage: number;
  totalPages: number;
  refreshWorkflows: () => Promise<void>;
  loadMore: () => Promise<void>;
  createWorkflow: (workflowData: WorkflowCreate) => Promise<Workflow>;
  updateWorkflow: (workflowId: number, workflowData: WorkflowUpdate) => Promise<Workflow>;
  deleteWorkflow: (workflowId: number) => Promise<void>;
  duplicateWorkflow: (workflowId: number, name?: string) => Promise<Workflow>;
  executeWorkflow: (workflowId: number, triggerData?: any) => Promise<WorkflowExecution>;
  activateWorkflow: (workflowId: number) => Promise<Workflow>;
  deactivateWorkflow: (workflowId: number) => Promise<Workflow>;
}

interface UseWorkflowsOptions {
  filters?: {
    status?: string;
    search?: string;
  };
  autoLoad?: boolean;
  pageSize?: number;
}

export function useWorkflows(options: UseWorkflowsOptions = {}): UseWorkflowsReturn {
  const {
    filters = {},
    autoLoad = true,
    pageSize = 20
  } = options;

  const [workflows, setWorkflows] = useState<Workflow[]>([]);
  const [totalWorkflows, setTotalWorkflows] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadWorkflows = useCallback(async (
    page: number = 1, 
    append: boolean = false
  ): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await workflowService.getWorkflows({
        ...filters,
        skip: (page - 1) * pageSize,
        limit: pageSize
      });

      if (append) {
        setWorkflows(prev => [...prev, ...response.items]);
      } else {
        setWorkflows(response.items);
      }

      setTotalWorkflows(response.total);
      setCurrentPage(page);
      setTotalPages(response.pages);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load workflows';
      setError(errorMessage);
      console.error('Load workflows error:', err);
    } finally {
      setIsLoading(false);
    }
  }, [filters, pageSize]);

  const refreshWorkflows = useCallback((): Promise<void> => {
    return loadWorkflows(1, false);
  }, [loadWorkflows]);

  const loadMore = useCallback((): Promise<void> => {
    if (currentPage < totalPages) {
      return loadWorkflows(currentPage + 1, true);
    }
    return Promise.resolve();
  }, [loadWorkflows, currentPage, totalPages]);

  const createWorkflow = useCallback(async (workflowData: WorkflowCreate): Promise<Workflow> => {
    try {
      setIsLoading(true);
      setError(null);

      const newWorkflow = await workflowService.createWorkflow(workflowData);

      // Add to the beginning of the list
      setWorkflows(prev => [newWorkflow, ...prev]);
      setTotalWorkflows(prev => prev + 1);

      return newWorkflow;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to create workflow';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const updateWorkflow = useCallback(async (
    workflowId: number, 
    workflowData: WorkflowUpdate
  ): Promise<Workflow> => {
    try {
      setIsLoading(true);
      setError(null);

      const updatedWorkflow = await workflowService.updateWorkflow(workflowId, workflowData);

      // Update in the list
      setWorkflows(prev => prev.map(workflow => 
        workflow.id === workflowId ? updatedWorkflow : workflow
      ));

      return updatedWorkflow;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to update workflow';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const deleteWorkflow = useCallback(async (workflowId: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      await workflowService.deleteWorkflow(workflowId);

      // Remove from the list
      setWorkflows(prev => prev.filter(workflow => workflow.id !== workflowId));
      setTotalWorkflows(prev => prev - 1);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to delete workflow';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const duplicateWorkflow = useCallback(async (
    workflowId: number, 
    name?: string
  ): Promise<Workflow> => {
    try {
      setIsLoading(true);
      setError(null);

      const duplicatedWorkflow = await workflowService.duplicateWorkflow(workflowId, name);

      // Add to the beginning of the list
      setWorkflows(prev => [duplicatedWorkflow, ...prev]);
      setTotalWorkflows(prev => prev + 1);

      return duplicatedWorkflow;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to duplicate workflow';
      setError(errorMessage);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, []);

  const executeWorkflow = useCallback(async (
    workflowId: number, 
    triggerData?: any
  ): Promise<WorkflowExecution> => {
    try {
      setError(null);

      const execution = await workflowService.executeWorkflow(workflowId, triggerData);

      // Update execution count in the workflow
      setWorkflows(prev => prev.map(workflow => 
        workflow.id === workflowId 
          ? { ...workflow, execution_count: workflow.execution_count + 1 }
          : workflow
      ));

      return execution;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to execute workflow';
      setError(errorMessage);
      throw err;
    }
  }, []);

  const activateWorkflow = useCallback(async (workflowId: number): Promise<Workflow> => {
    try {
      setError(null);

      const activatedWorkflow = await workflowService.activateWorkflow(workflowId);

      // Update in the list
      setWorkflows(prev => prev.map(workflow => 
        workflow.id === workflowId ? activatedWorkflow : workflow
      ));

      return activatedWorkflow;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to activate workflow';
      setError(errorMessage);
      throw err;
    }
  }, []);

  const deactivateWorkflow = useCallback(async (workflowId: number): Promise<Workflow> => {
    try {
      setError(null);

      const deactivatedWorkflow = await workflowService.deactivateWorkflow(workflowId);

      // Update in the list
      setWorkflows(prev => prev.map(workflow => 
        workflow.id === workflowId ? deactivatedWorkflow : workflow
      ));

      return deactivatedWorkflow;
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to deactivate workflow';
      setError(errorMessage);
      throw err;
    }
  }, []);

  // Load workflows on mount if autoLoad is enabled
  useEffect(() => {
    if (autoLoad) {
      loadWorkflows();
    }
  }, [autoLoad, loadWorkflows]);

  // Reload when filters change
  useEffect(() => {
    if (autoLoad) {
      loadWorkflows(1, false);
    }
  }, [filters, autoLoad, loadWorkflows]);

  return {
    workflows,
    totalWorkflows,
    currentPage,
    totalPages,
    isLoading,
    error,
    refreshWorkflows,
    loadMore,
    createWorkflow,
    updateWorkflow,
    deleteWorkflow,
    duplicateWorkflow,
    executeWorkflow,
    activateWorkflow,
    deactivateWorkflow
  };
}

// Hook for single workflow
export function useWorkflow(workflowId: number | null) {
  const [workflow, setWorkflow] = useState<Workflow | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadWorkflow = useCallback(async (id: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const workflowData = await workflowService.getWorkflow(id);
      setWorkflow(workflowData);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load workflow';
      setError(errorMessage);
      console.error('Load workflow error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (workflowId) {
      loadWorkflow(workflowId);
    } else {
      setWorkflow(null);
    }
  }, [workflowId, loadWorkflow]);

  return {
    workflow,
    isLoading,
    error,
    refreshWorkflow: () => workflowId ? loadWorkflow(workflowId) : Promise.resolve()
  };
}

// Hook for workflow executions
export function useWorkflowExecutions(workflowId: number | null) {
  const [executions, setExecutions] = useState<WorkflowExecution[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadExecutions = useCallback(async (id: number): Promise<void> => {
    try {
      setIsLoading(true);
      setError(null);

      const response = await workflowService.getWorkflowExecutions(id, { limit: 50 });
      setExecutions(response.items);
    } catch (err: any) {
      const errorMessage = err.message || 'Failed to load workflow executions';
      setError(errorMessage);
      console.error('Load workflow executions error:', err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (workflowId) {
      loadExecutions(workflowId);
    } else {
      setExecutions([]);
    }
  }, [workflowId, loadExecutions]);

  return {
    executions,
    isLoading,
    error,
    refreshExecutions: () => workflowId ? loadExecutions(workflowId) : Promise.resolve()
  };
}

/**
 * useWorkflowStatus Hook
 * 
 * Real-time WebSocket connection for workflow debugging and status updates
 * Part of Story 3.1: Visual Workflow Debugging
 * 
 * Features:
 * - WebSocket connection management with auto-reconnect
 * - Real-time status updates for workflow nodes
 * - Error handling and connection state management
 * - Performance target: <100ms status update latency
 * - Integration callbacks for status updates
 * 
 * @author Frontend Developer - Story 3.1 Implementation
 */

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { useAuth } from './useAuth';

// ============================================================================
// TYPES & INTERFACES (Story 3.1 WebSocket Protocol)
// ============================================================================

export interface WorkflowStatusEvent {
  type: 'connected' | 'execution_update' | 'execution_started' | 'execution_completed' | 'execution_details' | 'node_logs' | 'error' | 'subscribed';
  timestamp: string;
  workflow_id: number;
  execution_id?: number;
  node_id?: string;
  status?: 'pending' | 'running' | 'success' | 'failed' | 'paused';
  execution_time_ms?: number;
  error_details?: string;
  next_nodes?: string[];
  workflow_name?: string;
  workflow_status?: string;
  is_active?: boolean;
  recent_executions?: Array<{
    execution_id: number;
    status: string;
    started_at: string | null;
    finished_at: string | null;
    execution_time: number | null;
  }>;
  final_status?: string;
  duration_ms?: number;
  success_count?: number;
  total_nodes?: number;
  success_rate?: number;
  trigger_data?: Record<string, any>;
  execution_data?: Record<string, any>;
  error_message?: string;
  node_executions?: Array<any>;
  logs?: Array<{
    timestamp: string;
    level: string;
    message: string;
  }>;
  metrics?: {
    execution_time_ms: number;
    memory_usage: string;
    cpu_usage: string;
  };
  message?: string;
}

export interface WorkflowNodeData {
  id: string;
  status: 'pending' | 'running' | 'success' | 'failed' | 'paused';
  executionTime?: number;
  lastUpdated: Date;
  errorMessage?: string;
  metrics?: {
    execution_time_ms: number;
    memory_usage: string;
    cpu_usage: string;
  };
}

export interface WorkflowStatusState {
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;
  nodeStatuses: Record<string, WorkflowNodeData>;
  currentExecution: {
    execution_id?: number;
    status?: string;
    started_at?: string;
    finished_at?: string;
    total_nodes?: number;
    completed_nodes?: number;
    success_rate?: number;
  } | null;
  workflowInfo: {
    workflow_id?: number;
    workflow_name?: string;
    workflow_status?: string;
    is_active?: boolean;
  } | null;
  recentExecutions: Array<{
    execution_id: number;
    status: string;
    started_at: string | null;
    finished_at: string | null;
    execution_time: number | null;
  }>;
  connectionAttempts: number;
  lastMessage?: WorkflowStatusEvent;
  messageQueue: any[];
}

export interface UseWorkflowStatusOptions {
  workflowId: number | null;
  autoConnect?: boolean;
  maxReconnectAttempts?: number;
  reconnectDelay?: number;
  onStatusUpdate?: (nodeId: string, status: WorkflowNodeData) => void;
  onExecutionComplete?: (execution: WorkflowStatusEvent) => void;
  onExecutionStarted?: (execution: WorkflowStatusEvent) => void;
  onError?: (error: string) => void;
  onConnected?: (workflowInfo: WorkflowStatusEvent) => void;
}

export interface UseWorkflowStatusReturn extends WorkflowStatusState {
  connect: () => void;
  disconnect: () => void;
  sendMessage: (message: any) => void;
  getNodeStatus: (nodeId: string) => WorkflowNodeData | null;
  getExecutionDetails: (executionId: number) => void;
  getNodeLogs: (executionId: number, nodeId: string) => void;
  subscribeToExecution: (executionId: number) => void;
  clearError: () => void;
  retry: () => void;
  getConnectionLatency: () => number | null;
}

// ============================================================================
// HOOK IMPLEMENTATION
// ============================================================================

export function useWorkflowStatus(options: UseWorkflowStatusOptions): UseWorkflowStatusReturn {
  const {
    workflowId,
    autoConnect = true,
    maxReconnectAttempts = 5,
    reconnectDelay = 3000,
    onStatusUpdate,
    onExecutionComplete,
    onExecutionStarted,
    onError,
    onConnected
  } = options;

  const { token } = useAuth();

  // WebSocket ref and connection state
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isManualDisconnect = useRef(false);
  const connectionStartTime = useRef<number | null>(null);
  const latency = useRef<number | null>(null);

  const [state, setState] = useState<WorkflowStatusState>({
    isConnected: false,
    isConnecting: false,
    error: null,
    nodeStatuses: {},
    currentExecution: null,
    workflowInfo: null,
    recentExecutions: [],
    connectionAttempts: 0,
    messageQueue: []
  });

  // ============================================================================
  // CONNECTION MANAGEMENT
  // ============================================================================

  const connect = useCallback(() => {
    if (!workflowId || !token || wsRef.current?.readyState === WebSocket.OPEN) {
      return;
    }

    // Story 3.1 WebSocket endpoint: /api/v1/workflows/{workflow_id}/debug
    const wsUrl = `${process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:8000'}/api/v1/workflows/${workflowId}/debug?token=${token}`;

    setState(prev => ({
      ...prev,
      isConnecting: true,
      error: null,
      connectionAttempts: prev.connectionAttempts + 1
    }));

    connectionStartTime.current = Date.now();

    try {
      wsRef.current = new WebSocket(wsUrl);
      isManualDisconnect.current = false;

      wsRef.current.onopen = () => {
        if (connectionStartTime.current) {
          latency.current = Date.now() - connectionStartTime.current;
        }

        console.log(`[useWorkflowStatus] Connected to workflow ${workflowId} debugging (latency: ${latency.current}ms)`);

        setState(prev => ({
          ...prev,
          isConnected: true,
          isConnecting: false,
          connectionAttempts: 0,
          error: null
        }));

        // Process queued messages
        state.messageQueue.forEach(queuedMessage => {
          if (wsRef.current?.readyState === WebSocket.OPEN) {
            wsRef.current.send(JSON.stringify(queuedMessage));
          }
        });
        setState(prev => ({ ...prev, messageQueue: [] }));
      };

      wsRef.current.onmessage = (event) => {
        try {
          const message: WorkflowStatusEvent = JSON.parse(event.data);
          handleMessage(message);
        } catch (err) {
          console.error('[useWorkflowStatus] Failed to parse message:', err);
        }
      };

      wsRef.current.onclose = (event) => {
        console.log(`[useWorkflowStatus] Connection closed:`, event.code, event.reason);

        setState(prev => ({
          ...prev,
          isConnected: false,
          isConnecting: false
        }));

        // Auto-reconnect if not manually disconnected and under attempt limit
        if (!isManualDisconnect.current && state.connectionAttempts < maxReconnectAttempts) {
          const delay = reconnectDelay * Math.pow(1.5, state.connectionAttempts);
          console.log(`[useWorkflowStatus] Reconnecting in ${delay}ms (attempt ${state.connectionAttempts + 1})`);

          reconnectTimeoutRef.current = setTimeout(() => {
            connect();
          }, delay);
        } else if (state.connectionAttempts >= maxReconnectAttempts) {
          const error = 'Maximum reconnection attempts reached';
          setState(prev => ({ ...prev, error }));
          onError?.(error);
        }
      };

      wsRef.current.onerror = (event) => {
        console.error('[useWorkflowStatus] WebSocket error:', event);
        const error = 'WebSocket connection error';
        setState(prev => ({ ...prev, error, isConnecting: false }));
        onError?.(error);
      };

    } catch (err: any) {
      const error = `Connection failed: ${err.message}`;
      setState(prev => ({ ...prev, error, isConnecting: false }));
      onError?.(error);
    }
  }, [workflowId, token, state.connectionAttempts, state.messageQueue, maxReconnectAttempts, reconnectDelay, onError]);

  const disconnect = useCallback(() => {
    isManualDisconnect.current = true;

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }

    if (wsRef.current) {
      wsRef.current.close(1000, 'Manual disconnect');
      wsRef.current = null;
    }

    setState(prev => ({
      ...prev,
      isConnected: false,
      isConnecting: false,
      connectionAttempts: 0
    }));
  }, []);

  // ============================================================================
  // MESSAGE HANDLING (Story 3.1 Protocol)
  // ============================================================================

  const handleMessage = useCallback((message: WorkflowStatusEvent) => {
    setState(prev => ({
      ...prev,
      lastMessage: message
    }));

    switch (message.type) {
      case 'connected':
        console.log(`[useWorkflowStatus] Connected to workflow: ${message.workflow_name}`);

        const workflowInfo = {
          workflow_id: message.workflow_id,
          workflow_name: message.workflow_name,
          workflow_status: message.workflow_status,
          is_active: message.is_active
        };

        setState(prev => ({
          ...prev,
          workflowInfo,
          recentExecutions: message.recent_executions || []
        }));

        onConnected?.(message);
        break;

      case 'execution_started':
        console.log(`[useWorkflowStatus] Execution started: ${message.execution_id}`);

        setState(prev => ({
          ...prev,
          currentExecution: {
            execution_id: message.execution_id,
            status: 'running',
            started_at: message.timestamp
          }
        }));

        onExecutionStarted?.(message);
        break;

      case 'execution_update':
        if (message.node_id && message.status) {
          const nodeStatus: WorkflowNodeData = {
            id: message.node_id,
            status: message.status,
            executionTime: message.execution_time_ms,
            lastUpdated: new Date(message.timestamp),
            errorMessage: message.error_details
          };

          setState(prev => ({
            ...prev,
            nodeStatuses: {
              ...prev.nodeStatuses,
              [message.node_id!]: nodeStatus
            }
          }));

          // Performance target: <100ms status update latency
          onStatusUpdate?.(message.node_id, nodeStatus);
        }
        break;

      case 'execution_completed':
        console.log(`[useWorkflowStatus] Execution completed: ${message.execution_id}`);

        setState(prev => ({
          ...prev,
          currentExecution: prev.currentExecution ? {
            ...prev.currentExecution,
            status: message.final_status,
            finished_at: message.timestamp,
            total_nodes: message.total_nodes,
            completed_nodes: message.success_count,
            success_rate: message.success_rate
          } : null
        }));

        onExecutionComplete?.(message);
        break;

      case 'execution_details':
        console.log(`[useWorkflowStatus] Received execution details for: ${message.execution_id}`);
        // This could be used to update a detailed view
        break;

      case 'node_logs':
        if (message.node_id && message.logs) {
          console.log(`[useWorkflowStatus] Received logs for node: ${message.node_id}`);

          // Update node with metrics if available
          if (message.metrics && message.node_id) {
            setState(prev => ({
              ...prev,
              nodeStatuses: {
                ...prev.nodeStatuses,
                [message.node_id!]: {
                  ...prev.nodeStatuses[message.node_id!],
                  metrics: message.metrics
                }
              }
            }));
          }
        }
        break;

      case 'subscribed':
        console.log(`[useWorkflowStatus] Subscribed to execution: ${message.execution_id}`);
        break;

      case 'error':
        const error = message.error_details || message.message || 'Unknown error occurred';
        setState(prev => ({ ...prev, error }));
        onError?.(error);
        break;

      default:
        console.log(`[useWorkflowStatus] Unhandled message type: ${message.type}`, message);
    }
  }, [onStatusUpdate, onExecutionComplete, onExecutionStarted, onError, onConnected]);

  // ============================================================================
  // MESSAGE SENDING (Story 3.1 Client Commands)
  // ============================================================================

  const sendMessage = useCallback((message: any) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(message));
    } else {
      // Queue message for when connection is available
      setState(prev => ({
        ...prev,
        messageQueue: [...prev.messageQueue, message]
      }));
    }
  }, []);

  const getExecutionDetails = useCallback((executionId: number) => {
    sendMessage({
      type: 'get_execution_details',
      execution_id: executionId
    });
  }, [sendMessage]);

  const getNodeLogs = useCallback((executionId: number, nodeId: string) => {
    sendMessage({
      type: 'get_node_logs',
      execution_id: executionId,
      node_id: nodeId
    });
  }, [sendMessage]);

  const subscribeToExecution = useCallback((executionId: number) => {
    sendMessage({
      type: 'subscribe_execution',
      execution_id: executionId
    });
  }, [sendMessage]);

  // ============================================================================
  // UTILITY METHODS
  // ============================================================================

  const getNodeStatus = useCallback((nodeId: string): WorkflowNodeData | null => {
    return state.nodeStatuses[nodeId] || null;
  }, [state.nodeStatuses]);

  const clearError = useCallback(() => {
    setState(prev => ({ ...prev, error: null }));
  }, []);

  const retry = useCallback(() => {
    setState(prev => ({ ...prev, connectionAttempts: 0 }));
    connect();
  }, [connect]);

  const getConnectionLatency = useCallback((): number | null => {
    return latency.current;
  }, []);

  // ============================================================================
  // EFFECTS
  // ============================================================================

  // Auto-connect when workflowId changes
  useEffect(() => {
    if (autoConnect && workflowId && token) {
      connect();
    }

    return () => {
      disconnect();
    };
  }, [workflowId, token, autoConnect]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      disconnect();
    };
  }, [disconnect]);

  // ============================================================================
  // RETURN VALUE
  // ============================================================================

  return useMemo(() => ({
    ...state,
    connect,
    disconnect,
    sendMessage,
    getNodeStatus,
    getExecutionDetails,
    getNodeLogs,
    subscribeToExecution,
    clearError,
    retry,
    getConnectionLatency
  }), [
    state,
    connect,
    disconnect,
    sendMessage,
    getNodeStatus,
    getExecutionDetails,
    getNodeLogs,
    subscribeToExecution,
    clearError,
    retry,
    getConnectionLatency
  ]);
}

/**
 * Theme Integration Tests
 * 
 * Tests for Story 1.1: Master Theme System Foundation
 * Integration tests for theme system with sample components and real-world usage
 */

import { render } from '@testing-library/react';
import React from 'react';
import {
  masterTheme,
  colors,
  spacing,
  presets,
  createThemeClass,
  themeUtils,
} from '../theme';

// Mock component for testing theme integration
const SampleCard: React.FC<{ variant?: 'landing' | 'canvas' | 'nav' }> = ({ 
  variant = 'landing',
  children = 'Sample Content' 
}) => {
  const getVariantClasses = () => {
    switch (variant) {
      case 'landing':
        return presets.landingPage;
      case 'canvas':
        return presets.builderCanvas;
      case 'nav':
        return presets.navigation;
      default:
        return presets.landingPage;
    }
  };

  return (
    <div 
      className={createThemeClass(getVariantClasses(), spacing.component.padding)}
      data-testid={`sample-card-${variant}`}
    >
      {children}
    </div>
  );
};

// Mock button component using theme utilities
const ThemedButton: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <button 
    className={themeUtils.buttonPrimary}
    data-testid="themed-button"
  >
    {children}
  </button>
);

// Mock input component using theme system
const ThemedInput: React.FC = () => (
  <input 
    className={themeUtils.inputStyle}
    data-testid="themed-input"
    placeholder="Sample input"
  />
);

describe('Theme Integration with React Components', () => {
  test('landing page preset applies correctly', () => {
    const { getByTestId } = render(<SampleCard variant="landing" />);
    const element = getByTestId('sample-card-landing');

    expect(element.className).toContain('bg-gray-900');
    expect(element.className).toContain('text-white');
    expect(element.className).toContain('p-4');
  });

  test('canvas preset applies correctly', () => {
    const { getByTestId } = render(<SampleCard variant="canvas" />);
    const element = getByTestId('sample-card-canvas');

    expect(element.className).toContain('bg-gray-800');
    expect(element.className).toContain('text-white');
  });

  test('navigation preset includes border styling', () => {
    const { getByTestId } = render(<SampleCard variant="nav" />);
    const element = getByTestId('sample-card-nav');

    expect(element.className).toContain('bg-gray-900');
    expect(element.className).toContain('text-white');
    expect(element.className).toContain('border-b');
  });

  test('themed button component works correctly', () => {
    const { getByTestId } = render(<ThemedButton>Click me</ThemedButton>);
    const button = getByTestId('themed-button');

    expect(button.className).toContain('bg-yellow-400');
    expect(button.className).toContain('text-white');
    expect(button.className).toContain('hover:');
  });

  test('themed input component works correctly', () => {
    const { getByTestId } = render(<ThemedInput />);
    const input = getByTestId('themed-input');

    expect(input.className).toContain('bg-gray-800');
    expect(input.className).toContain('text-white');
    expect(input.className).toContain('border');
  });
});

describe('Theme System Performance', () => {
  test('createThemeClass performs efficiently with many classes', () => {
    const start = performance.now();

    for (let i = 0; i < 1000; i++) {
      createThemeClass(
        colors.background.primary,
        colors.text.primary,
        spacing.component.padding,
        'rounded-lg',
        'shadow-lg',
        'hover:scale-105'
      );
    }

    const end = performance.now();
    const duration = end - start;

    // Should complete 1000 operations in less than 100ms
    expect(duration).toBeLessThan(100);
  });

  test('theme validation performs efficiently', () => {
    const start = performance.now();

    for (let i = 0; i < 1000; i++) {
      themeUtils.validate(masterTheme);
    }

    const end = performance.now();
    const duration = end - start;

    // Should complete 1000 validations in less than 50ms
    expect(duration).toBeLessThan(50);
  });
});

describe('CSS Class Generation', () => {
  test('generates valid Tailwind CSS classes', () => {
    const validTailwindPattern = /^[a-z-]+$/;

    // Test background colors
    expect(colors.background.primary.replace('bg-', '')).toMatch(validTailwindPattern);
    expect(colors.background.secondary.replace('bg-', '')).toMatch(validTailwindPattern);
    expect(colors.background.accent.replace('bg-', '')).toMatch(validTailwindPattern);

    // Test text colors
    expect(colors.text.primary.replace('text-', '')).toMatch(validTailwindPattern);
    expect(colors.text.secondary.replace('text-', '')).toMatch(validTailwindPattern);
    expect(colors.text.accent.replace('text-', '')).toMatch(validTailwindPattern);
  });

  test('spacing classes are properly formatted', () => {
    // Check that padding classes include responsive modifiers
    expect(spacing.component.padding).toContain('p-');
    expect(spacing.component.padding).toContain('md:p-');
    expect(spacing.component.padding).toContain('lg:p-');

    // Check that margin classes include responsive modifiers
    expect(spacing.component.margin).toContain('m-');
    expect(spacing.component.margin).toContain('md:m-');
    expect(spacing.component.margin).toContain('lg:m-');
  });

  test('preset combinations create valid class strings', () => {
    Object.values(presets).forEach(preset => {
      expect(typeof preset).toBe('string');
      expect(preset.trim()).toBe(preset); // No leading/trailing whitespace
      expect(preset).not.toContain('  '); // No double spaces
    });
  });
});

describe('Real-world Usage Scenarios', () => {
  test('theme works for complex component structures', () => {
    const ComplexComponent = () => (
      <div className={presets.landingPage}>
        <header className={presets.navigation}>
          <nav className={spacing.component.padding}>
            <button className={themeUtils.buttonPrimary}>
              Primary Action
            </button>
          </nav>
        </header>
        <main className={presets.builderCanvas}>
          <div className={themeUtils.cardStyle}>
            <input className={themeUtils.inputStyle} />
          </div>
        </main>
      </div>
    );

    const { container } = render(<ComplexComponent />);

    // Should render without errors
    expect(container.firstChild).toBeInTheDocument();

    // Check nested theme applications
    const header = container.querySelector('header');
    expect(header?.className).toContain('bg-gray-900');

    const main = container.querySelector('main');
    expect(main?.className).toContain('bg-gray-800');
  });

  test('theme system supports dynamic class generation', () => {
    const DynamicComponent: React.FC<{ isActive: boolean }> = ({ isActive }) => (
      <div 
        className={createThemeClass(
          colors.background.primary,
          colors.text.primary,
          isActive ? colors.background.accent : undefined,
          spacing.component.padding
        )}
        data-testid="dynamic-component"
      />
    );

    const { getByTestId, rerender } = render(<DynamicComponent isActive={false} />);
    const element = getByTestId('dynamic-component');

    expect(element.className).not.toContain('bg-yellow-400');

    rerender(<DynamicComponent isActive={true} />);
    expect(element.className).toContain('bg-yellow-400');
  });

  test('theme system handles edge cases gracefully', () => {
    // Test with empty values
    const emptyClass = createThemeClass('', null, undefined, colors.background.primary);
    expect(emptyClass).toBe('bg-gray-900');

    // Test with mixed valid and invalid values
    const mixedClass = createThemeClass(
      colors.background.primary,
      false as any,
      colors.text.primary,
      0 as any,
      'custom-class'
    );
    expect(mixedClass).toContain('bg-gray-900');
    expect(mixedClass).toContain('text-white');
    expect(mixedClass).toContain('custom-class');
    expect(mixedClass).not.toContain('false');
    expect(mixedClass).not.toContain('0');
  });
});

describe('Accessibility Integration', () => {
  test('theme colors provide sufficient contrast', () => {
    // Test dark background with light text
    const darkWithLight = createThemeClass(
      colors.background.primary,
      colors.text.primary
    );
    expect(darkWithLight).toContain('bg-gray-900');
    expect(darkWithLight).toContain('text-white');

    // Test secondary background with light text
    const secondaryWithLight = createThemeClass(
      colors.background.secondary,
      colors.text.primary
    );
    expect(secondaryWithLight).toContain('bg-gray-800');
    expect(secondaryWithLight).toContain('text-white');
  });

  test('accent colors maintain readability', () => {
    const accentButton = createThemeClass(
      colors.background.accent,
      colors.text.primary
    );

    // Yellow background should work with white text
    expect(accentButton).toContain('bg-yellow-400');
    expect(accentButton).toContain('text-white');
  });

  test('theme utilities include focus states', () => {
    expect(themeUtils.inputStyle).toContain('focus:');
    expect(themeUtils.buttonPrimary).toContain('hover:');
  });
});

describe('TypeScript Integration', () => {
