export const componentSuggestionEngine = new ComponentSuggestionEngine();

import { ComponentData } from '@/types/builder';

interface LayoutPattern {
  id: string;
  name: string;
  description: string;
  structure: LayoutStructure;
  bestFor: string[];
  confidence: number;
  variants: LayoutVariant[];
}

interface LayoutStructure {
  containers: number;
  sections: string[];
  hierarchy: number;
  complexity: 'simple' | 'moderate' | 'complex';
}

interface LayoutVariant {
  id: string;
  name: string;
  components: ComponentTemplate[];
  spacing: SpacingSystem;
  responsive: ResponsiveBreakpoints;
}

interface ComponentTemplate {
  type: string;
  position: { x: number; y: number };
  size: { width: number; height: number };
  props: Record<string, any>;
  relationships: string[];
}

interface SpacingSystem {
  base: number;
  scale: number[];
  margins: Record<string, number>;
  paddings: Record<string, number>;
}

interface ResponsiveBreakpoints {
  mobile: { maxWidth: number; columns: number };
  tablet: { maxWidth: number; columns: number };
  desktop: { maxWidth: number; columns: number };
}

interface LayoutSuggestion {
  pattern: LayoutPattern;
  reasoning: string;
  modifications: string[];
  confidence: number;
  expectedImpact: string;
}

