    if (component.type === 'button') {
      actions.push({
        id: 'ab-test-button',
        label: 'A/B Test Button',
        description: 'Create automated A/B test variations',
        action: async () => {
          await this.createButtonABTest(component.id);
        }
      });
    }

    return actions;
  }

