// Export singleton instance
export const magicConnector = new MagicConnector();

interface PromptAnalysis {
  intent: 'style' | 'content' | 'layout' | 'interaction' | 'complex';
  confidence: number;
  entities: {
    colors: string[];
    dimensions: string[];
    animations: string[];
    properties: string[];
  };
  suggestions: string[];
  expandedPrompt: string;
}

interface PromptTemplate {
  id: string;
  name: string;
  category: string;
  template: string;
  variables: string[];
  examples: string[];
}

export class PromptProcessor {
  private templates: PromptTemplate[] = [];
  private colorKeywords = [
    'blue', 'red', 'green', 'yellow', 'purple', 'orange', 'pink', 'gray', 'black', 'white',
    'primary', 'secondary', 'accent', 'brand', 'theme', 'dark', 'light', 'vibrant', 'muted'
  ];

  private dimensionKeywords = [
    'large', 'small', 'big', 'tiny', 'huge', 'compact', 'wide', 'narrow', 'tall', 'short',
    'responsive', 'mobile', 'desktop', 'tablet', 'full-width', 'centered'
  ];

  private animationKeywords = [
    'animate', 'animation', 'hover', 'transition', 'fade', 'slide', 'bounce', 'scale',
    'rotate', 'smooth', 'effect', 'interactive', 'motion', 'transform'
  ];

  constructor() {
    this.initializeTemplates();
  }

  private initializeTemplates() {
    this.templates = [
      {
        id: 'modern-button',
        name: 'Modern Button',
        category: 'components',
        template: 'Create a modern {style} button with {color} background, {size} size, and {effect} hover effect',
        variables: ['style', 'color', 'size', 'effect'],
        examples: [
          'Create a modern sleek button with blue background, large size, and scale hover effect',
          'Create a modern rounded button with green background, medium size, and glow hover effect'
        ]
      },
      {
        id: 'responsive-card',
        name: 'Responsive Card',
        category: 'layout',
        template: 'Design a responsive card component with {layout} layout, {shadow} shadow, and {spacing} spacing',
        variables: ['layout', 'shadow', 'spacing'],
        examples: [
          'Design a responsive card component with vertical layout, subtle shadow, and comfortable spacing',
          'Design a responsive card component with horizontal layout, deep shadow, and tight spacing'
        ]
      },
      {
        id: 'hero-section',
        name: 'Hero Section',
        category: 'sections',
        template: 'Build a {style} hero section with {background} background, {alignment} text alignment, and {cta} call-to-action',
        variables: ['style', 'background', 'alignment', 'cta'],
        examples: [
          'Build a modern hero section with gradient background, center text alignment, and prominent call-to-action',
          'Build a minimal hero section with image background, left text alignment, and subtle call-to-action'
        ]
      },
      {
        id: 'navigation-menu',
        name: 'Navigation Menu',
        category: 'navigation',
        template: 'Create a {type} navigation menu with {style} styling, {responsive} responsive behavior, and {effect} hover effects',
        variables: ['type', 'style', 'responsive', 'effect'],
        examples: [
          'Create a horizontal navigation menu with modern styling, mobile responsive behavior, and underline hover effects',
          'Create a sidebar navigation menu with minimal styling, tablet responsive behavior, and background hover effects'
        ]
      }
    ];
  }

  analyzePrompt(prompt: string): PromptAnalysis {
    const normalizedPrompt = prompt.toLowerCase().trim();

    // Determine primary intent
    const intent = this.determineIntent(normalizedPrompt);

    // Extract entities
    const entities = this.extractEntities(normalizedPrompt);

    // Calculate confidence based on specificity
    const confidence = this.calculateConfidence(normalizedPrompt, entities);

    // Generate suggestions for improvement
    const suggestions = this.generateSuggestions(normalizedPrompt, entities, intent);

    // Create expanded prompt
    const expandedPrompt = this.expandPrompt(normalizedPrompt, entities, intent);

    return {
      intent,
      confidence,
      entities,
      suggestions,
      expandedPrompt
    };
  }

  private determineIntent(prompt: string): PromptAnalysis['intent'] {
    const styleKeywords = ['color', 'background', 'border', 'shadow', 'gradient', 'theme', 'style'];
    const contentKeywords = ['text', 'content', 'copy', 'heading', 'title', 'description', 'label'];
    const layoutKeywords = ['layout', 'position', 'align', 'spacing', 'margin', 'padding', 'grid', 'flex'];
    const interactionKeywords = ['click', 'hover', 'animation', 'transition', 'interactive', 'effect'];

    const styleScore = this.countKeywords(prompt, styleKeywords);
    const contentScore = this.countKeywords(prompt, contentKeywords);
    const layoutScore = this.countKeywords(prompt, layoutKeywords);
    const interactionScore = this.countKeywords(prompt, interactionKeywords);

    const scores = {
      style: styleScore,
      content: contentScore,
      layout: layoutScore,
      interaction: interactionScore
    };

    const maxScore = Math.max(...Object.values(scores));
    const intents = Object.entries(scores).filter(([, score]) => score === maxScore);

    if (intents.length > 1 || maxScore >= 3) {
      return 'complex';
    }

    return (intents[0]?.[0] as PromptAnalysis['intent']) || 'style';
  }

  private countKeywords(text: string, keywords: string[]): number {
    return keywords.reduce((count, keyword) => {
      return count + (text.includes(keyword) ? 1 : 0);
    }, 0);
  }

  private extractEntities(prompt: string): PromptAnalysis['entities'] {
    return {
      colors: this.extractColors(prompt),
      dimensions: this.extractDimensions(prompt),
      animations: this.extractAnimations(prompt),
      properties: this.extractProperties(prompt)
    };
  }

  private extractColors(prompt: string): string[] {
    const found: string[] = [];

    this.colorKeywords.forEach(color => {
      if (prompt.includes(color)) {
        found.push(color);
      }
    });

    // Extract hex codes
    const hexMatches = prompt.match(/#[0-9a-f]{6}/gi);
    if (hexMatches) {
      found.push(...hexMatches);
    }

    // Extract RGB values
    const rgbMatches = prompt.match(/rgb\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\)/gi);
    if (rgbMatches) {
      found.push(...rgbMatches);
    }

    return [...new Set(found)];
  }

  private extractDimensions(prompt: string): string[] {
    const found: string[] = [];

    this.dimensionKeywords.forEach(dimension => {
      if (prompt.includes(dimension)) {
        found.push(dimension);
      }
    });

    // Extract specific measurements
    const measurementMatches = prompt.match(/\d+(?:px|em|rem|%|vh|vw)/gi);
    if (measurementMatches) {
      found.push(...measurementMatches);
    }

    return [...new Set(found)];
  }

  private extractAnimations(prompt: string): string[] {
    const found: string[] = [];

    this.animationKeywords.forEach(animation => {
      if (prompt.includes(animation)) {
        found.push(animation);
      }
    });

    return [...new Set(found)];
  }

  private extractProperties(prompt: string): string[] {
    const propertyKeywords = [
      'border-radius', 'box-shadow', 'opacity', 'z-index', 'position',
      'display', 'flex-direction', 'justify-content', 'align-items',
      'font-size', 'font-weight', 'line-height', 'letter-spacing'
    ];

    const found: string[] = [];

    propertyKeywords.forEach(property => {
      if (prompt.includes(property) || prompt.includes(property.replace('-', ' '))) {
        found.push(property);
      }
    });

    return [...new Set(found)];
  }

  private calculateConfidence(prompt: string, entities: PromptAnalysis['entities']): number {
    let confidence = 0.5; // Base confidence

    // Increase confidence based on specificity
    const totalEntities = Object.values(entities).flat().length;
    confidence += Math.min(totalEntities * 0.1, 0.3);

    // Increase confidence based on prompt length (more detailed = higher confidence)
    const wordCount = prompt.split(' ').length;
    if (wordCount > 10) confidence += 0.1;
    if (wordCount > 20) confidence += 0.1;

    // Decrease confidence for vague terms
    const vagueTerms = ['nice', 'good', 'better', 'improve', 'fix', 'change'];
    const vagueCount = this.countKeywords(prompt, vagueTerms);
    confidence -= vagueCount * 0.1;

    return Math.max(0.1, Math.min(confidence, 1.0));
  }

  private generateSuggestions(
    prompt: string, 
    entities: PromptAnalysis['entities'], 
    intent: PromptAnalysis['intent']
  ): string[] {
    const suggestions: string[] = [];

    // Suggest being more specific about colors
    if (intent === 'style' && entities.colors.length === 0) {
      suggestions.push('Consider specifying colors (e.g., "blue background" or "#3B82F6")');
    }

    // Suggest including dimensions
    if (entities.dimensions.length === 0) {
      suggestions.push('Add size information (e.g., "large", "medium", or specific pixels)');
    }

    // Suggest animations for interactions
    if (intent === 'interaction' && entities.animations.length === 0) {
      suggestions.push('Specify animation type (e.g., "fade in", "slide up", "scale on hover")');
    }

    // Suggest responsive considerations
    if (!prompt.includes('responsive') && !prompt.includes('mobile')) {
      suggestions.push('Consider mentioning responsive behavior for better mobile experience');
    }

    // Suggest accessibility
    if (!prompt.includes('accessible') && !prompt.includes('aria')) {
      suggestions.push('Consider accessibility requirements (e.g., "accessible", "high contrast")');
    }

    return suggestions;
  }

  private expandPrompt(
    prompt: string, 
    entities: PromptAnalysis['entities'], 
    intent: PromptAnalysis['intent']
  ): string {
    let expanded = prompt;

    // Add context based on intent
    const contextAdditions: Record<PromptAnalysis['intent'], string> = {
      'style': ' with modern design principles and consistent branding',
      'content': ' ensuring clear hierarchy and readability',
      'layout': ' with responsive design and proper spacing',
      'interaction': ' with smooth animations and good user feedback',
      'complex': ' following best practices for UX and accessibility'
    };

    expanded += contextAdditions[intent];

    // Add missing important details
    if (entities.colors.length === 0 && intent === 'style') {
      expanded += ', using appropriate brand colors';
    }

    if (!prompt.includes('responsive')) {
      expanded += ', optimized for all screen sizes';
    }

    if (!prompt.includes('accessible')) {
      expanded += ', with accessibility considerations';
    }

    return expanded;
  }

  validatePrompt(prompt: string): {
    isValid: boolean;
    errors: string[];
    warnings: string[];
  } {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Check minimum length
    if (prompt.trim().length < 5) {
      errors.push('Prompt is too short. Please provide more details.');
    }

    // Check maximum length
    if (prompt.length > 1000) {
      errors.push('Prompt is too long. Please keep it under 1000 characters.');
    }

    // Check for potentially problematic content
    const problematicTerms = ['hack', 'exploit', 'inject', 'bypass'];
    const hasProblematic = problematicTerms.some(term => 
      prompt.toLowerCase().includes(term)
    );

    if (hasProblematic) {
      warnings.push('Prompt contains potentially problematic terms.');
    }

    // Check for very vague prompts
    const vaguePhrases = ['make it better', 'improve this', 'fix it', 'change it'];
    const isVague = vaguePhrases.some(phrase => 
      prompt.toLowerCase().includes(phrase)
    );

    if (isVague) {
      warnings.push('Prompt is quite vague. Consider being more specific about what you want to change.');
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings
    };
  }

  getSuggestedTemplates(prompt: string): PromptTemplate[] {
    const analysis = this.analyzePrompt(prompt);

    return this.templates
      .map(template => {
        let score = 0;

        // Check if prompt mentions template category
        if (prompt.toLowerCase().includes(template.category)) {
          score += 0.5;
        }

        // Check if prompt mentions template variables
        template.variables.forEach(variable => {
          if (prompt.toLowerCase().includes(variable)) {
            score += 0.2;
          }
        });

        // Check intent alignment
        if (template.category === 'components' && analysis.intent === 'style') score += 0.3;
        if (template.category === 'layout' && analysis.intent === 'layout') score += 0.3;
        if (template.category === 'sections' && analysis.intent === 'complex') score += 0.3;

        return { ...template, score };
      })
      .filter(template => template.score > 0.2)
      .sort((a, b) => b.score - a.score)
      .slice(0, 3);
  }

  generatePromptVariations(basePrompt: string): string[] {
    const analysis = this.analyzePrompt(basePrompt);
    const variations: string[] = [];

    // Create more specific variation
    variations.push(`${basePrompt} with attention to detail and modern styling`);

    // Create variations with different focuses
    if (analysis.intent !== 'layout') {
      variations.push(`${basePrompt} ensuring responsive layout and proper spacing`);
    }

    if (analysis.intent !== 'interaction') {
      variations.push(`${basePrompt} with smooth animations and hover effects`);
    }

    if (analysis.entities.colors.length === 0) {
      variations.push(`${basePrompt} using modern color palette and gradients`);
    }

    // Create simplified variation
    variations.push(`Simplify: ${basePrompt}`);

    return variations.slice(0, 4);
  }
}

export type { PromptAnalysis, PromptTemplate };

import { ComponentData } from '@/types/builder';

interface PageContext {
  templateType?: string;
  industry?: string;
  brandColors?: string[];
  existingComponents: ComponentData[];
  pageGoals: string[];
}

interface LayoutPattern {
  id: string;
  name: string;
  description: string;
  components: string[];
  bestFor: string[];
  confidence: number;
}

interface ColorPalette {
  primary: string;
  secondary: string;
  accent: string;
  neutral: string;
  complementary: string[];
}

interface TypographyPairing {
  heading: string;
  body: string;
  accent: string;
  confidence: number;
  reasoning: string;
}

interface AISuggestion {
  id: string;
  type: 'layout' | 'color' | 'typography' | 'content' | 'interaction';
  title: string;
  description: string;
  confidence: number;
  prompt: string;
  expectedOutcome: string;
  category: string;
  priority: 'high' | 'medium' | 'low';
}

export class AIContext {
  private pageContext: PageContext;
  private componentAnalysis: Map<string, any> = new Map();
  private layoutPatterns: LayoutPattern[] = [];

  constructor(pageContext: PageContext) {
    this.pageContext = pageContext;
    this.initializeLayoutPatterns();
  }

  private initializeLayoutPatterns() {
    this.layoutPatterns = [
      {
        id: 'hero-cta-features',
        name: 'Hero-CTA-Features',
        description: 'Classic landing page layout with hero section, call-to-action, and feature showcase',
        components: ['hero', 'button', 'features', 'testimonials'],
        bestFor: ['saas', 'product-launch', 'startup'],
        confidence: 0.92
      },
      {
        id: 'grid-showcase',
        name: 'Grid Showcase',
        description: 'Product or service showcase using card-based grid layout',
        components: ['card', 'grid', 'filter', 'pagination'],
        bestFor: ['portfolio', 'ecommerce', 'gallery'],
        confidence: 0.88
      },
      {
        id: 'story-timeline',
        name: 'Story Timeline',
        description: 'Narrative flow with timeline or step-by-step progression',
        components: ['timeline', 'steps', 'progress', 'narrative'],
        bestFor: ['process', 'journey', 'about'],
        confidence: 0.85
      },
      {
        id: 'dashboard-metrics',
        name: 'Dashboard Metrics',
        description: 'Data-driven layout with metrics, charts, and key indicators',
        components: ['metrics', 'chart', 'widget', 'kpi'],
        bestFor: ['analytics', 'reporting', 'business'],
        confidence: 0.90
      }
    ];
  }

  analyzePageContext(): {
    dominantPatterns: LayoutPattern[];
    missingElements: string[];
    improvementAreas: string[];
  } {
    const existingTypes = this.pageContext.existingComponents.map(c => c.type);
    const dominantPatterns = this.layoutPatterns
      .filter(pattern => {
        const overlap = pattern.components.filter(comp => 
          existingTypes.some(type => type.includes(comp) || comp.includes(type))
        ).length;
        return overlap >= pattern.components.length * 0.5;
      })
      .sort((a, b) => b.confidence - a.confidence);

    const missingElements = this.identifyMissingElements(existingTypes);
    const improvementAreas = this.identifyImprovementAreas();

    return {
      dominantPatterns,
      missingElements,
      improvementAreas
    };
  }

  private identifyMissingElements(existingTypes: string[]): string[] {
    const essential = ['navigation', 'header', 'footer', 'cta'];
    const recommended = ['testimonials', 'features', 'contact'];

    const missing = [];

    essential.forEach(element => {
      if (!existingTypes.some(type => type.includes(element))) {
        missing.push(element);
      }
    });

    recommended.forEach(element => {
      if (!existingTypes.some(type => type.includes(element))) {
        missing.push(element);
      }
    });

    return missing;
  }

  private identifyImprovementAreas(): string[] {
    const areas: string[] = [];
    const components = this.pageContext.existingComponents;

    // Check for responsive design
    const hasResponsiveDesign = components.some(c => 
      c.props.className?.includes('responsive') || 
      c.props.responsive === true
    );
    if (!hasResponsiveDesign) areas.push('responsive-design');

    // Check for accessibility
    const hasAccessibility = components.some(c => 
      c.props['aria-label'] || c.props.alt || c.props.role
    );
    if (!hasAccessibility) areas.push('accessibility');

    // Check for animations
    const hasAnimations = components.some(c => 
      c.props.className?.includes('animate') || 
      c.props.animation !== undefined
    );
    if (!hasAnimations) areas.push('animations');

    // Check for consistent styling
    const colorVariance = this.analyzeColorConsistency(components);
    if (colorVariance > 0.7) areas.push('color-consistency');

    return areas;
  }

  private analyzeColorConsistency(components: ComponentData[]): number {
    const colors = new Set<string>();

    components.forEach(component => {
      if (component.style?.backgroundColor) {
        colors.add(component.style.backgroundColor as string);
      }
      if (component.style?.color) {
        colors.add(component.style.color as string);
      }
    });

    // Return variance score (0 = very consistent, 1 = very inconsistent)
    return Math.min(colors.size / 10, 1);
  }

  generateSmartColorPalette(baseColor?: string): ColorPalette {
    // If no base color provided, analyze existing components
    if (!baseColor && this.pageContext.existingComponents.length > 0) {
      baseColor = this.extractDominantColor();
    }

    baseColor = baseColor || '#3B82F6'; // Default to blue

    return {
      primary: baseColor,
      secondary: this.adjustColor(baseColor, { lightness: 0.1, saturation: -0.1 }),
      accent: this.getComplementaryColor(baseColor),
      neutral: '#6B7280',
      complementary: [
        this.adjustColor(baseColor, { hue: 30 }),
        this.adjustColor(baseColor, { hue: -30 }),
        this.adjustColor(baseColor, { lightness: 0.2 }),
        this.adjustColor(baseColor, { lightness: -0.2 })
      ]
    };
  }

  private extractDominantColor(): string {
    const colorCounts = new Map<string, number>();

    this.pageContext.existingComponents.forEach(component => {
      const bgColor = component.style?.backgroundColor as string;
      const textColor = component.style?.color as string;

      if (bgColor && bgColor !== 'transparent') {
        colorCounts.set(bgColor, (colorCounts.get(bgColor) || 0) + 1);
      }
      if (textColor && textColor !== 'inherit') {
        colorCounts.set(textColor, (colorCounts.get(textColor) || 0) + 1);
      }
    });

    const sortedColors = Array.from(colorCounts.entries())
      .sort(([,a], [,b]) => b - a);

    return sortedColors[0]?.[0] || '#3B82F6';
  }

  private adjustColor(color: string, adjustments: {
    hue?: number;
    saturation?: number;
    lightness?: number;
  }): string {
    // Simplified color adjustment - in production, use a proper color library
    // This is a basic implementation for demonstration
    return color; // Would implement HSL adjustments here
  }

  private getComplementaryColor(color: string): string {
    // Simplified complementary color calculation
    // In production, would use proper color theory
    return color === '#3B82F6' ? '#F59E0B' : '#10B981';
  }

  generateTypographyPairings(): TypographyPairing[] {
    const pairings: TypographyPairing[] = [
      {
        heading: 'Inter',
        body: 'Inter',
        accent: 'Inter',
        confidence: 0.95,
        reasoning: 'Modern, clean, and highly readable across all screen sizes'
      },
      {
        heading: 'Poppins',
        body: 'Open Sans',
        accent: 'Poppins',
        confidence: 0.88,
        reasoning: 'Professional pairing with strong character and readability'
      },
      {
        heading: 'Montserrat',
        body: 'Source Sans Pro',
        accent: 'Montserrat',
        confidence: 0.85,
        reasoning: 'Classic combination with excellent brand presence'
      },
      {
        heading: 'Raleway',
        body: 'Lato',
        accent: 'Raleway',
        confidence: 0.82,
        reasoning: 'Elegant and modern with excellent hierarchy'
      }
    ];

    // Filter based on industry if available
    if (this.pageContext.industry) {
      return this.filterTypographyByIndustry(pairings);
    }

    return pairings;
  }

  private filterTypographyByIndustry(pairings: TypographyPairing[]): TypographyPairing[] {
    const industryPreferences: Record<string, string[]> = {
      'tech': ['Inter', 'Poppins', 'Roboto'],
      'finance': ['Montserrat', 'Source Sans Pro', 'Open Sans'],
      'creative': ['Playfair Display', 'Raleway', 'Merriweather'],
      'healthcare': ['Open Sans', 'Lato', 'Source Sans Pro'],
      'education': ['Open Sans', 'Lato', 'Merriweather']
    };

    const preferences = industryPreferences[this.pageContext.industry!] || [];

    return pairings.map(pairing => ({
      ...pairing,
      confidence: preferences.includes(pairing.heading) 
        ? pairing.confidence * 1.1 
        : pairing.confidence * 0.9
    })).sort((a, b) => b.confidence - a.confidence);
  }
}

export class AISuggestionEngine {
  private aiContext: AIContext;

  constructor(pageContext: PageContext) {
    this.aiContext = new AIContext(pageContext);
  }

  generateContextualSuggestions(selectedComponent: ComponentData): AISuggestion[] {
    const suggestions: AISuggestion[] = [];
    const analysis = this.aiContext.analyzePageContext();

    // Layout suggestions
    suggestions.push(...this.generateLayoutSuggestions(selectedComponent, analysis));

    // Color suggestions
    suggestions.push(...this.generateColorSuggestions(selectedComponent));

    // Typography suggestions
    suggestions.push(...this.generateTypographySuggestions(selectedComponent));

    // Content suggestions
    suggestions.push(...this.generateContentSuggestions(selectedComponent));

    // Interaction suggestions
    suggestions.push(...this.generateInteractionSuggestions(selectedComponent));

    return suggestions
      .sort((a, b) => b.confidence - a.confidence)
      .slice(0, 8); // Return top 8 suggestions
  }

  private generateLayoutSuggestions(
    component: ComponentData, 
    analysis: ReturnType<AIContext['analyzePageContext']>
  ): AISuggestion[] {
    const suggestions: AISuggestion[] = [];

    if (analysis.missingElements.includes('cta') && component.type !== 'button') {
      suggestions.push({
        id: 'add-cta',
        type: 'layout',
        title: 'Add Call-to-Action',
        description: 'Include a prominent CTA to guide user actions',
        confidence: 0.9,
        prompt: 'Add a prominent call-to-action button below this component',
        expectedOutcome: 'Improved conversion rates and user engagement',
        category: 'conversion',
        priority: 'high'
      });
    }

    if (component.type === 'container' && !component.children?.length) {
      suggestions.push({
        id: 'improve-spacing',
        type: 'layout',
        title: 'Optimize Spacing',
        description: 'Improve visual hierarchy with better spacing',
        confidence: 0.85,
        prompt: 'Optimize the spacing and padding of this container for better visual flow',
        expectedOutcome: 'Better visual hierarchy and readability',
        category: 'design',
        priority: 'medium'
      });
    }

    return suggestions;
  }

  private generateColorSuggestions(component: ComponentData): AISuggestion[] {
    const suggestions: AISuggestion[] = [];
    const palette = this.aiContext.generateSmartColorPalette();

    if (!component.style?.backgroundColor || component.style.backgroundColor === 'transparent') {
      suggestions.push({
        id: 'apply-brand-colors',
        type: 'color',
        title: 'Apply Brand Colors',
        description: 'Use consistent brand colors for better recognition',
        confidence: 0.88,
        prompt: `Apply the primary brand color ${palette.primary} as background`,
        expectedOutcome: 'Consistent brand identity and visual appeal',
        category: 'branding',
        priority: 'high'
      });
    }

    if (component.type === 'button') {
      suggestions.push({
        id: 'gradient-button',
        type: 'color',
        title: 'Add Gradient Effect',
        description: 'Make buttons more engaging with gradient backgrounds',
        confidence: 0.82,
        prompt: `Create a gradient from ${palette.primary} to ${palette.accent}`,
        expectedOutcome: 'More engaging and modern button appearance',
        category: 'engagement',
        priority: 'medium'
      });
    }

    return suggestions;
  }

  private generateTypographySuggestions(component: ComponentData): AISuggestion[] {
    const suggestions: AISuggestion[] = [];
    const pairings = this.aiContext.generateTypographyPairings();
    const topPairing = pairings[0];

    if (component.type === 'text' || component.type === 'heading') {
      suggestions.push({
        id: 'optimize-typography',
        type: 'typography',
        title: 'Optimize Typography',
        description: topPairing.reasoning,
        confidence: topPairing.confidence,
        prompt: `Apply ${topPairing.heading} font with improved line spacing and hierarchy`,
        expectedOutcome: 'Better readability and professional appearance',
        category: 'readability',
        priority: 'medium'
      });
    }

    return suggestions;
  }

  private generateContentSuggestions(component: ComponentData): AISuggestion[] {
    const suggestions: AISuggestion[] = [];

    if (component.type === 'text' && (!component.props.content || component.props.content.length < 10)) {
      suggestions.push({
        id: 'enhance-content',
        type: 'content',
        title: 'Enhance Content',
        description: 'Add more descriptive and engaging content',
        confidence: 0.78,
        prompt: 'Expand this text with more engaging and descriptive content',
        expectedOutcome: 'Better user engagement and clarity',
        category: 'content',
        priority: 'medium'
      });
    }

    return suggestions;
  }

  private generateInteractionSuggestions(component: ComponentData): AISuggestion[] {
    const suggestions: AISuggestion[] = [];

    const hasAnimation = component.props.className?.includes('animate') || 
                        component.props.animation !== undefined;

    if (!hasAnimation) {
      suggestions.push({
        id: 'add-animations',
        type: 'interaction',
        title: 'Add Micro-interactions',
        description: 'Enhance user experience with subtle animations',
        confidence: 0.75,
        prompt: 'Add hover effects and subtle animations to make this component more interactive',
        expectedOutcome: 'More engaging user experience',
        category: 'engagement',
        priority: 'low'
      });
    }

    return suggestions;
  }

  analyzeComponentRelationships(components: ComponentData[]): {
    clusters: ComponentData[][];
    suggestions: string[];
  } {
    // Group components by proximity and type
    const clusters = this.clusterComponents(components);
    const suggestions = this.generateRelationshipSuggestions(clusters);

    return { clusters, suggestions };
  }

  private clusterComponents(components: ComponentData[]): ComponentData[][] {
    // Simple clustering based on position proximity
    const clusters: ComponentData[][] = [];
    const visited = new Set<string>();

    components.forEach(component => {
      if (visited.has(component.id)) return;

      const cluster = [component];
      visited.add(component.id);

      // Find nearby components
      components.forEach(other => {
        if (visited.has(other.id)) return;

        const distance = Math.sqrt(
          Math.pow(component.position.x - other.position.x, 2) +
          Math.pow(component.position.y - other.position.y, 2)
        );

        if (distance < 150) { // Within 150px
          cluster.push(other);
          visited.add(other.id);
        }
      });

      clusters.push(cluster);
    });

    return clusters;
  }

  private generateRelationshipSuggestions(clusters: ComponentData[][]): string[] {
    const suggestions: string[] = [];

    clusters.forEach(cluster => {
      if (cluster.length > 3) {
        suggestions.push(`Consider grouping ${cluster.length} nearby components into a container`);
      }

      const types = cluster.map(c => c.type);
      if (types.includes('text') && types.includes('button')) {
        suggestions.push('Text and button components work well together - consider aligning them');
      }
    });

    return suggestions;
  }
}

