/**
 * Enterprise-Grade Password Validation System
 * Comprehensive password security with real-time feedback
 */

export interface PasswordValidationResult {
  isValid: boolean;
  score: number; // 0-100
  feedback: string[];
  warnings: string[];
  suggestions: string[];
}

export interface PasswordPolicy {
  minLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumbers: boolean;
  requireSpecialChars: boolean;
  maxLength?: number;
  disallowCommonPasswords: boolean;
  disallowPersonalInfo: boolean;
  minUniqueChars?: number;
}

// Enterprise-grade password policy
export const DEFAULT_PASSWORD_POLICY: PasswordPolicy = {
  minLength: 8,
  requireUppercase: true,
  requireLowercase: true,
  requireNumbers: true,
  requireSpecialChars: true,
  maxLength: 128,
  disallowCommonPasswords: true,
  disallowPersonalInfo: true,
  minUniqueChars: 4,
};

// Common passwords blacklist (top 100)
const COMMON_PASSWORDS = new Set([
  'password', '123456', '123456789', 'welcome', 'admin', 'password123',
  'letmein', 'monkey', '1234567890', 'qwerty', 'abc123', 'Password',
  '123123', 'welcome123', 'admin123', 'password1', '12345678', 'qwerty123',
  'iloveyou', 'princess', 'hello', 'freedom', 'whatever', 'passw0rd',
  'master', 'dragon', 'trustno1', '654321', 'jordan23', 'harley',
]);

const SPECIAL_CHARS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

export class PasswordValidator {
  private policy: PasswordPolicy;

  constructor(policy: PasswordPolicy = DEFAULT_PASSWORD_POLICY) {
    this.policy = policy;
  }

  /**
   * Validate password against policy with detailed feedback
   */
  validate(password: string, userInfo?: { email?: string; firstName?: string; lastName?: string }): PasswordValidationResult {
    const result: PasswordValidationResult = {
      isValid: false,
      score: 0,
      feedback: [],
      warnings: [],
      suggestions: [],
    };

    // Basic length validation
    if (password.length < this.policy.minLength) {
      result.feedback.push(`Password must be at least ${this.policy.minLength} characters long`);
      return result;
    }

    let score = 0;
    const feedback: string[] = [];
    const warnings: string[] = [];
    const suggestions: string[] = [];

    // Character requirements
    const hasUppercase = /[A-Z]/.test(password);
    const hasLowercase = /[a-z]/.test(password);
    const hasNumbers = /\d/.test(password);
    const hasSpecialChars = new RegExp(`[${this.escapeRegex(SPECIAL_CHARS)}]`).test(password);

    if (this.policy.requireUppercase && !hasUppercase) {
      feedback.push('Password must contain at least one uppercase letter');
    } else if (hasUppercase) {
      score += 15;
    }

    if (this.policy.requireLowercase && !hasLowercase) {
      feedback.push('Password must contain at least one lowercase letter');
    } else if (hasLowercase) {
      score += 15;
    }

    if (this.policy.requireNumbers && !hasNumbers) {
      feedback.push('Password must contain at least one number');
    } else if (hasNumbers) {
      score += 15;
    }

    if (this.policy.requireSpecialChars && !hasSpecialChars) {
      feedback.push('Password must contain at least one special character (!@#$%^&*...)');
    } else if (hasSpecialChars) {
      score += 20;
    }

    if (feedback.length > 0) {
      result.feedback = feedback;
      result.score = Math.max(score - 20, 0);
      return result;
    }

    // Advanced security checks
    score += this.calculateComplexityScore(password);

    // Common passwords check
    if (this.policy.disallowCommonPasswords && COMMON_PASSWORDS.has(password.toLowerCase())) {
      feedback.push('This password is commonly used and easily guessable');
      score = Math.max(score - 30, 0);
    }

    // Personal information check
    if (this.policy.disallowPersonalInfo && userInfo) {
      const personalInfoCheck = this.checkPersonalInfo(password, userInfo);
      if (personalInfoCheck.hasPersonalInfo) {
        warnings.push('Password should not contain personal information');
        score = Math.max(score - 15, 0);
      }
    }

    // Pattern checks
    const patternCheck = this.checkPatterns(password);
    if (patternCheck.hasPatterns) {
      warnings.push(...patternCheck.warnings);
      suggestions.push(...patternCheck.suggestions);
      score = Math.max(score - patternCheck.penalty, 0);
    }

    // Generate improvement suggestions
    if (score < 70) {
      suggestions.push(...this.generateSuggestions(password, score));
    }

    result.score = Math.min(score, 100);
    result.isValid = result.score >= 60 && feedback.length === 0;
    result.feedback = feedback;
    result.warnings = warnings;
    result.suggestions = suggestions;

    return result;
  }

  private calculateComplexityScore(password: string): number {
    let score = 0;

    // Length bonus
    if (password.length >= 12) score += 10;
    if (password.length >= 16) score += 10;

    // Character diversity
    const hasUpper = /[A-Z]/.test(password);
    const hasLower = /[a-z]/.test(password);
    const hasNumbers = /\d/.test(password);
    const hasSpecial = new RegExp(`[${this.escapeRegex(SPECIAL_CHARS)}]`).test(password);

    const diversity = [hasUpper, hasLower, hasNumbers, hasSpecial].filter(Boolean).length;
    score += diversity * 5;

    return Math.min(score, 35);
  }

  private checkPersonalInfo(password: string, userInfo: any): { hasPersonalInfo: boolean } {
    const passwordLower = password.toLowerCase();

    if (userInfo.email) {
      const emailParts = userInfo.email.toLowerCase().split('@')[0];
      if (passwordLower.includes(emailParts) && emailParts.length > 3) {
        return { hasPersonalInfo: true };
      }
    }

    if (userInfo.firstName && passwordLower.includes(userInfo.firstName.toLowerCase())) {
      return { hasPersonalInfo: true };
    }

    if (userInfo.lastName && passwordLower.includes(userInfo.lastName.toLowerCase())) {
      return { hasPersonalInfo: true };
    }

    return { hasPersonalInfo: false };
  }

  private checkPatterns(password: string): { hasPatterns: boolean; warnings: string[]; suggestions: string[]; penalty: number } {
    const warnings: string[] = [];
    const suggestions: string[] = [];
    let penalty = 0;

    // Sequential characters
    if (this.hasSequentialChars(password)) {
      warnings.push('Contains sequential characters');
      suggestions.push('Avoid sequences like "123" or "abc"');
      penalty += 10;
    }

    // Repeated characters
    const repeatedCheck = this.checkRepeatedChars(password);
    if (repeatedCheck.hasRepeated) {
      warnings.push('Too many repeated characters');
      suggestions.push('Use more variety in your characters');
      penalty += repeatedCheck.penalty;
    }

    return {
      hasPatterns: warnings.length > 0,
      warnings,
      suggestions,
      penalty,
    };
  }

  private hasSequentialChars(password: string): boolean {
    const sequences = [
      '0123456789',
      'abcdefghijklmnopqrstuvwxyz',
      'qwertyuiopasdfghjklzxcvbnm',
    ];

    return sequences.some(seq => {
      for (let i = 0; i <= seq.length - 3; i++) {
        const subseq = seq.substring(i, i + 3);
        if (password.toLowerCase().includes(subseq)) {
          return true;
        }
      }
      return false;
    });
  }

  private checkRepeatedChars(password: string): { hasRepeated: boolean; penalty: number } {
    let maxRepeat = 0;
    let currentRepeat = 1;

    for (let i = 1; i < password.length; i++) {
      if (password[i] === password[i - 1]) {
        currentRepeat++;
      } else {
        maxRepeat = Math.max(maxRepeat, currentRepeat);
        currentRepeat = 1;
      }
    }
    maxRepeat = Math.max(maxRepeat, currentRepeat);

    if (maxRepeat >= 3) {
      return { hasRepeated: true, penalty: Math.min(maxRepeat * 3, 15) };
    }

    return { hasRepeated: false, penalty: 0 };
  }

  private generateSuggestions(password: string, currentScore: number): string[] {
    const suggestions: string[] = [];

    if (currentScore < 30) {
      suggestions.push('Use a longer password with mixed characters');
      suggestions.push('Consider using a passphrase with multiple words');
    } else if (currentScore < 50) {
      suggestions.push('Add more character variety');
      suggestions.push('Make your password longer for better security');
    } else {
      suggestions.push('Consider making it a bit longer');
    }

    return suggestions;
  }

  private escapeRegex(string: string): string {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  static getStrengthDescription(score: number): { level: string; color: string; description: string } {
    if (score < 30) {
      return { level: 'Very Weak', color: 'red', description: 'Very easily guessable' };
    } else if (score < 50) {
      return { level: 'Weak', color: 'orange', description: 'Weak and vulnerable' };
    } else if (score < 70) {
      return { level: 'Fair', color: 'yellow', description: 'Basic security' };
    } else if (score < 85) {
      return { level: 'Good', color: 'lightgreen', description: 'Good security' };
    } else {
      return { level: 'Excellent', color: 'green', description: 'Excellent security' };
    }
  }
}

export const passwordValidator = new PasswordValidator();

/**
 * Advanced Rate Limiting System
 * Multi-strategy rate limiting with intelligent blocking
 */

export interface RateLimitResult {
  allowed: boolean;
  remainingAttempts: number;
  resetTime: number;
  totalAttempts: number;
  isBlocked: boolean;
  retryAfter?: number;
}

export interface RateLimitConfig {
  windowMs: number;
  maxAttempts: number;
  blockDuration: number;
  strategy: 'fixed_window' | 'sliding_window';
}

// Rate limit configurations
export const RATE_LIMIT_CONFIGS = {
  LOGIN: {
    windowMs: 15 * 60 * 1000, // 15 minutes
    maxAttempts: 5,
    blockDuration: 30 * 60 * 1000, // 30 minutes
    strategy: 'sliding_window' as const,
  },
  REGISTER: {
    windowMs: 60 * 60 * 1000, // 1 hour
    maxAttempts: 3,
    blockDuration: 2 * 60 * 60 * 1000, // 2 hours
    strategy: 'fixed_window' as const,
  },
  PASSWORD_RESET: {
    windowMs: 60 * 60 * 1000, // 1 hour
    maxAttempts: 3,
    blockDuration: 24 * 60 * 60 * 1000, // 24 hours
    strategy: 'fixed_window' as const,
  },
  API_GENERAL: {
    windowMs: 15 * 60 * 1000, // 15 minutes
    maxAttempts: 100,
    blockDuration: 15 * 60 * 1000, // 15 minutes
    strategy: 'fixed_window' as const,
  },
} as const;

interface AttemptRecord {
  timestamp: number;
  success: boolean;
}

export class RateLimiter {
  private attempts: Map<string, AttemptRecord[]> = new Map();
  private blocks: Map<string, { expiresAt: number }> = new Map();
  private config: RateLimitConfig;

  constructor(config: RateLimitConfig) {
    this.config = config;
    this.startCleanup();
  }

  async checkLimit(identifier: string, options: { success?: boolean } = {}): Promise<RateLimitResult> {
    const now = Date.now();

    // Check if blocked
    const blockInfo = this.blocks.get(identifier);
    if (blockInfo && blockInfo.expiresAt > now) {
      return {
        allowed: false,
        remainingAttempts: 0,
        resetTime: blockInfo.expiresAt,
        totalAttempts: this.getAttemptCount(identifier),
        isBlocked: true,
        retryAfter: Math.ceil((blockInfo.expiresAt - now) / 1000),
      };
    }

    // Remove expired block
    if (blockInfo && blockInfo.expiresAt <= now) {
      this.blocks.delete(identifier);
    }

    const currentAttempts = this.getRelevantAttempts(identifier, now);
    const limitResult = this.calculateLimit(currentAttempts, now);

    // Record attempt if specified
    if (options.success !== undefined) {
      this.recordAttempt(identifier, { timestamp: now, success: options.success });
      limitResult.totalAttempts++;

      // Block if limit exceeded and attempt failed
      if (!limitResult.allowed || (limitResult.remainingAttempts === 0 && !options.success)) {
        this.blockIdentifier(identifier, now);
        limitResult.isBlocked = true;
        limitResult.retryAfter = Math.ceil(this.config.blockDuration / 1000);
      }
    }

    return limitResult;
  }

  private recordAttempt(identifier: string, attempt: AttemptRecord): void {
    if (!this.attempts.has(identifier)) {
      this.attempts.set(identifier, []);
    }

    const attempts = this.attempts.get(identifier)!;
    attempts.push(attempt);
  }

  private getRelevantAttempts(identifier: string, currentTime: number): AttemptRecord[] {
    const attempts = this.attempts.get(identifier) || [];
    const cutoff = currentTime - this.config.windowMs;
    return attempts.filter(attempt => attempt.timestamp >= cutoff);
  }

  private calculateLimit(attempts: AttemptRecord[], currentTime: number): RateLimitResult {
    const totalAttempts = attempts.length;

    if (this.config.strategy === 'fixed_window') {
      return this.fixedWindowStrategy(attempts, currentTime);
    } else {
      return this.slidingWindowStrategy(attempts, currentTime);
    }
  }

  private fixedWindowStrategy(attempts: AttemptRecord[], currentTime: number): RateLimitResult {
    const windowStart = Math.floor(currentTime / this.config.windowMs) * this.config.windowMs;
    const windowAttempts = attempts.filter(a => a.timestamp >= windowStart);

    const allowed = windowAttempts.length < this.config.maxAttempts;
    const remaining = Math.max(0, this.config.maxAttempts - windowAttempts.length);
    const resetTime = windowStart + this.config.windowMs;

    return {
      allowed,
      remainingAttempts: remaining,
      resetTime,
      totalAttempts: attempts.length,
      isBlocked: false,
    };
  }

  private slidingWindowStrategy(attempts: AttemptRecord[], currentTime: number): RateLimitResult {
    const windowStart = currentTime - this.config.windowMs;
    const windowAttempts = attempts.filter(a => a.timestamp >= windowStart);

    const allowed = windowAttempts.length < this.config.maxAttempts;
    const remaining = Math.max(0, this.config.maxAttempts - windowAttempts.length);
    const oldestAttempt = windowAttempts[0];
    const resetTime = oldestAttempt ? oldestAttempt.timestamp + this.config.windowMs : currentTime + this.config.windowMs;

    return {
      allowed,
      remainingAttempts: remaining,
      resetTime,
      totalAttempts: attempts.length,
      isBlocked: false,
    };
  }

  private blockIdentifier(identifier: string, currentTime: number): void {
    this.blocks.set(identifier, {
      expiresAt: currentTime + this.config.blockDuration,
    });
  }

  private getAttemptCount(identifier: string): number {
    return this.attempts.get(identifier)?.length || 0;
  }

  reset(identifier: string): void {
    this.attempts.delete(identifier);
    this.blocks.delete(identifier);
  }

  private startCleanup(): void {
    const cleanupInterval = Math.min(this.config.windowMs, 5 * 60 * 1000);

    setInterval(() => {
      const now = Date.now();
      const cutoff = now - this.config.windowMs - this.config.blockDuration;

      // Clean old attempts
      for (const [identifier, attempts] of this.attempts.entries()) {
        const relevantAttempts = attempts.filter(a => a.timestamp > cutoff);
        if (relevantAttempts.length === 0) {
          this.attempts.delete(identifier);
        } else {
          this.attempts.set(identifier, relevantAttempts);
        }
      }

      // Clean expired blocks
      for (const [identifier, blockInfo] of this.blocks.entries()) {
        if (blockInfo.expiresAt <= now) {
          this.blocks.delete(identifier);
        }
      }
    }, cleanupInterval);
  }
}

export class RateLimiterFactory {
  private static instances: Map<string, RateLimiter> = new Map();

  static getInstance(type: keyof typeof RATE_LIMIT_CONFIGS): RateLimiter {
    if (!this.instances.has(type)) {
      const config = RATE_LIMIT_CONFIGS[type];
      this.instances.set(type, new RateLimiter(config));
    }
    return this.instances.get(type)!;
  }
}

// Export instances
export const loginRateLimiter = RateLimiterFactory.getInstance('LOGIN');
export const registerRateLimiter = RateLimiterFactory.getInstance('REGISTER');
export const passwordResetRateLimiter = RateLimiterFactory.getInstance('PASSWORD_RESET');
export const apiRateLimiter = RateLimiterFactory.getInstance('API_GENERAL');

/**
 * WebSocket Client for Real-time Collaboration
 * Handles connection, event broadcasting, and message routing
 */

import { 
  CollaborationEvent, 
  CollaborationUser, 
  CollaborationError,
  Operation,
  OperationResult
} from '@/types/collaboration';

export type WebSocketStatus = 'connecting' | 'connected' | 'disconnected' | 'error' | 'reconnecting';

export interface WebSocketConfig {
  url: string;
  reconnectAttempts: number;
  reconnectInterval: number;
  heartbeatInterval: number;
  timeout: number;
}

export interface WebSocketMessage {
  type: string;
  payload: any;
  timestamp: Date;
  messageId: string;
}

export class CollaborationWebSocket {
  private ws: WebSocket | null = null;
  private config: WebSocketConfig;
  private status: WebSocketStatus = 'disconnected';
  private reconnectCount = 0;
  private heartbeatTimer: NodeJS.Timeout | null = null;
  private messageQueue: WebSocketMessage[] = [];
  private eventListeners: Map<string, Set<Function>> = new Map();

  // Authentication and room context
  private userId: string | null = null;
  private projectId: string | null = null;
  private authToken: string | null = null;

  constructor(config: Partial<WebSocketConfig> = {}) {
    this.config = {
      url: config.url || this.getWebSocketUrl(),
      reconnectAttempts: config.reconnectAttempts || 5,
      reconnectInterval: config.reconnectInterval || 3000,
      heartbeatInterval: config.heartbeatInterval || 30000,
      timeout: config.timeout || 10000,
    };
  }

  private getWebSocketUrl(): string {
    // Use different URLs based on environment
    if (typeof window !== 'undefined') {
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = process.env.NODE_ENV === 'production' 
        ? window.location.host 
        : 'localhost:8000';
      return `${protocol}//${host}/ws/collaboration`;
    }
    return 'ws://localhost:8000/ws/collaboration';
  }

  /**
   * Connect to the collaboration room
   */
  async connect(userId: string, projectId: string, authToken: string): Promise<void> {
    if (this.status === 'connected' || this.status === 'connecting') {
      return;
    }

    this.userId = userId;
    this.projectId = projectId;
    this.authToken = authToken;
    this.status = 'connecting';

    return new Promise((resolve, reject) => {
      try {
        const wsUrl = `${this.config.url}?userId=${userId}&projectId=${projectId}&token=${authToken}`;
        this.ws = new WebSocket(wsUrl);

        this.ws.onopen = () => {
          this.onConnectionOpen();
          resolve();
        };

        this.ws.onmessage = (event) => {
          this.onMessage(event);
        };

        this.ws.onclose = (event) => {
          this.onConnectionClose(event);
        };

        this.ws.onerror = (error) => {
          this.onConnectionError(error);
          reject(new Error('WebSocket connection failed'));
        };

        // Set connection timeout
        setTimeout(() => {
          if (this.status === 'connecting') {
            this.disconnect();
            reject(new Error('Connection timeout'));
          }
        }, this.config.timeout);

      } catch (error) {
        this.status = 'error';
        reject(error);
      }
    });
  }

  /**
   * Disconnect from the collaboration room
   */
  disconnect(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }

    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }

    this.status = 'disconnected';
    this.reconnectCount = 0;
    this.messageQueue = [];
    this.emit('disconnected');
  }

  /**
   * Send a collaboration event
   */
  sendEvent(event: Omit<CollaborationEvent, 'id' | 'timestamp' | 'userId' | 'projectId'>): void {
    if (!this.userId || !this.projectId) {
      console.error('Cannot send event: user or project not set');
      return;
    }

    const fullEvent: CollaborationEvent = {
      ...event,
      id: this.generateMessageId(),
      timestamp: new Date(),
      userId: this.userId,
      projectId: this.projectId,
    } as CollaborationEvent;

    this.send({
      type: 'collaboration_event',
      payload: fullEvent,
      timestamp: new Date(),
      messageId: this.generateMessageId(),
    });
  }

  /**
   * Send operation for operational transform
   */
  sendOperation(operation: Omit<Operation, 'id' | 'timestamp' | 'userId'>): void {
    if (!this.userId) {
      console.error('Cannot send operation: user not set');
      return;
    }

    const fullOperation: Operation = {
      ...operation,
      id: this.generateMessageId(),
      timestamp: new Date(),
      userId: this.userId,
    };

    this.send({
      type: 'operation',
      payload: fullOperation,
      timestamp: new Date(),
      messageId: this.generateMessageId(),
    });
  }

  /**
   * Request user list for the current room
   */
  requestUserList(): void {
    this.send({
      type: 'get_users',
      payload: {},
      timestamp: new Date(),
      messageId: this.generateMessageId(),
    });
  }

  /**
   * Send cursor position update
   */
  updateCursor(position: { x: number; y: number }, visible: boolean = true): void {
    this.sendEvent({
      type: 'user.cursor_update',
      cursor: {
        userId: this.userId!,
        position,
        visible,
        timestamp: new Date(),
      },
    });
  }

  /**
   * Send component selection event
   */
  selectComponent(componentId: string | null): void {
    this.sendEvent({
      type: 'component.selected',
      componentId,
    });
  }

  /**
   * Lock a component for editing
   */
  lockComponent(componentId: string, lockType: 'editing' | 'moving' | 'resizing'): void {
    this.sendEvent({
      type: 'component.locked',
      lock: {
        componentId,
        userId: this.userId!,
        lockType,
        timestamp: new Date(),
        expiresAt: new Date(Date.now() + 30000), // 30 second lock
      },
    });
  }

  /**
   * Unlock a component
   */
  unlockComponent(componentId: string): void {
    this.sendEvent({
      type: 'component.unlocked',
      componentId,
    });
  }

  /**
   * Send chat message
   */
  sendChatMessage(message: string, componentId?: string): void {
    this.sendEvent({
      type: 'chat.message',
      message,
      timestamp: new Date(),
    });
  }

  /**
   * Add event listener
   */
  on(eventType: string, callback: Function): void {
    if (!this.eventListeners.has(eventType)) {
      this.eventListeners.set(eventType, new Set());
    }
    this.eventListeners.get(eventType)!.add(callback);
  }

  /**
   * Remove event listener
   */
  off(eventType: string, callback: Function): void {
    const listeners = this.eventListeners.get(eventType);
    if (listeners) {
      listeners.delete(callback);
    }
  }

  /**
   * Get current connection status
   */
  getStatus(): WebSocketStatus {
    return this.status;
  }

  /**
   * Check if connected
   */
  isConnected(): boolean {
    return this.status === 'connected' && this.ws?.readyState === WebSocket.OPEN;
  }

  // Private methods

  private send(message: WebSocketMessage): void {
    if (this.isConnected()) {
      this.ws!.send(JSON.stringify(message));
    } else {
      // Queue message for later sending
      this.messageQueue.push(message);

      // Attempt to reconnect if not already doing so
      if (this.status === 'disconnected') {
        this.attemptReconnect();
      }
    }
  }

  private onConnectionOpen(): void {
    console.log('WebSocket connected');
    this.status = 'connected';
    this.reconnectCount = 0;

    // Send queued messages
    while (this.messageQueue.length > 0) {
      const message = this.messageQueue.shift()!;
      this.ws!.send(JSON.stringify(message));
    }

    // Start heartbeat
    this.startHeartbeat();

    this.emit('connected');
  }

  private onMessage(event: MessageEvent): void {
    try {
      const message: WebSocketMessage = JSON.parse(event.data);
      this.handleMessage(message);
    } catch (error) {
      console.error('Failed to parse WebSocket message:', error);
      this.emit('error', {
        type: 'validation',
        message: 'Invalid message format',
        code: 'INVALID_MESSAGE',
        timestamp: new Date(),
        recoverable: true,
      } as CollaborationError);
    }
  }

  private onConnectionClose(event: CloseEvent): void {
    console.log('WebSocket disconnected:', event.code, event.reason);
    this.status = 'disconnected';

    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }

    this.emit('disconnected', { code: event.code, reason: event.reason });

    // Attempt to reconnect if it wasn't a clean close
    if (event.code !== 1000 && this.reconnectCount < this.config.reconnectAttempts) {
      this.attemptReconnect();
    }
  }

  private onConnectionError(error: Event): void {
    console.error('WebSocket error:', error);
    this.status = 'error';

    this.emit('error', {
      type: 'connection',
      message: 'WebSocket connection error',
      code: 'CONNECTION_ERROR',
      timestamp: new Date(),
      recoverable: true,
    } as CollaborationError);
  }

  private handleMessage(message: WebSocketMessage): void {
    switch (message.type) {
      case 'collaboration_event':
        this.emit('event', message.payload as CollaborationEvent);
        break;

      case 'operation_result':
        this.emit('operation_result', message.payload as OperationResult);
        break;

      case 'user_list':
        this.emit('user_list', message.payload as CollaborationUser[]);
        break;

      case 'error':
        this.emit('error', message.payload as CollaborationError);
        break;

      case 'heartbeat':
        this.emit('heartbeat');
        break;

      default:
        console.warn('Unknown message type:', message.type);
    }
  }

  private startHeartbeat(): void {
    this.heartbeatTimer = setInterval(() => {
      if (this.isConnected()) {
        this.send({
          type: 'heartbeat',
          payload: { timestamp: new Date() },
          timestamp: new Date(),
          messageId: this.generateMessageId(),
        });
      }
    }, this.config.heartbeatInterval);
  }

  private attemptReconnect(): void {
    if (this.reconnectCount >= this.config.reconnectAttempts) {
      console.error('Max reconnection attempts reached');
      this.emit('max_reconnect_attempts');
      return;
    }

    this.status = 'reconnecting';
    this.reconnectCount++;

    console.log(`Attempting to reconnect (${this.reconnectCount}/${this.config.reconnectAttempts})`);

    setTimeout(() => {
      if (this.userId && this.projectId && this.authToken) {
        this.connect(this.userId, this.projectId, this.authToken)
          .catch((error) => {
            console.error('Reconnection failed:', error);
            this.attemptReconnect();
          });
      }
    }, this.config.reconnectInterval * this.reconnectCount);
  }

  private emit(eventType: string, data?: any): void {
    const listeners = this.eventListeners.get(eventType);
    if (listeners) {
      listeners.forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error(`Error in event listener for ${eventType}:`, error);
        }
      });
    }
  }

  private generateMessageId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Export singleton instance
export const collaborationWS = new CollaborationWebSocket();

/**
 * Deployment Validator for AI Marketing Web Builder
 * 
 * Validates deployment success rate (target: 95%) and deployment pipeline reliability:
 * - Static site generation validation
 * - Deployment pipeline testing
 * - Error handling and recovery
 * - Success rate monitoring
 */

import { StaticSiteGenerator } from '../generators/StaticSiteGenerator';
import { ComponentData, Template } from '@/types/builder';

export interface DeploymentResult {
  success: boolean;
  deploymentId: string;
  url?: string;
  error?: string;
  duration: number;
  timestamp: string;
  size: number;
  provider: 'vercel' | 'netlify' | 'cloudflare' | 'local';
}

export interface DeploymentValidationResult {
  testId: string;
  timestamp: string;
  totalTests: number;
  successfulDeployments: number;
  failedDeployments: number;
  successRate: number;
  averageDeploymentTime: number;
  results: DeploymentResult[];
  issues: DeploymentIssue[];
  recommendations: string[];
}

export interface DeploymentIssue {
  type: 'network' | 'generation' | 'upload' | 'configuration' | 'timeout';
  description: string;
  frequency: number;
  severity: 'low' | 'medium' | 'high' | 'critical';
  solution?: string;
}

export interface SiteValidationResult {
  isValid: boolean;
  htmlValid: boolean;
  cssValid: boolean;
  jsValid: boolean;
  seoCompliant: boolean;
  responsive: boolean;
  accessibilityScore: number;
  performanceScore: number;
  issues: string[];
}

export class DeploymentValidator {
  private static deploymentHistory: DeploymentResult[] = [];
  private static validationHistory: DeploymentValidationResult[] = [];

  /**
   * Validate a generated site before deployment
   */
  static async validateGeneratedSite(
    components: ComponentData[],
    template: Template | null,
    options: any = {}
  ): Promise<SiteValidationResult> {
    console.log('🔍 Validating generated site before deployment...');

    try {
      // Generate the site
      const generator = new StaticSiteGenerator();
      const result = await generator.generateSite(components, template, {
        siteName: options.siteName || 'Test Site',
        seoSettings: options.seoSettings || {},
        enableOptimization: true,
        enablePWA: true,
        minifyOutput: true,
        enableServiceWorker: true,
        enableCriticalCSS: true,
        responsiveBreakpoints: true,
        performanceOptimization: true,
        generateAssets: true
      });

      const issues: string[] = [];

      // Validate HTML structure
      const htmlValid = this.validateHTML(result.html);
      if (!htmlValid) {
        issues.push('HTML structure validation failed');
      }

      // Validate CSS
      const cssValid = this.validateCSS(result.css);
      if (!cssValid) {
        issues.push('CSS validation failed');
      }

      // Validate JavaScript
      const jsValid = this.validateJavaScript(result.js);
      if (!jsValid) {
        issues.push('JavaScript validation failed');
      }

      // Check SEO compliance
      const seoCompliant = this.validateSEO(result.html, result.meta);
      if (!seoCompliant) {
        issues.push('SEO compliance validation failed');
      }

      // Check responsive design
      const responsive = this.validateResponsive(result.css);
      if (!responsive) {
        issues.push('Responsive design validation failed');
      }

      // Calculate scores
      const accessibilityScore = this.calculateAccessibilityScore(result.html);
      const performanceScore = result.optimization?.seoScore || 0;

      const validationResult: SiteValidationResult = {
        isValid: issues.length === 0,
        htmlValid,
        cssValid,
        jsValid,
        seoCompliant,
        responsive,
        accessibilityScore,
        performanceScore,
        issues
      };

      console.log(`✅ Site validation completed - Valid: ${validationResult.isValid}`);
      console.log(`📊 Accessibility: ${accessibilityScore}/100, Performance: ${performanceScore}/100`);

      if (issues.length > 0) {
        console.warn('⚠️ Validation issues found:', issues);
      }

      return validationResult;

    } catch (error) {
      console.error('❌ Site validation failed:', error);
      return {
        isValid: false,
        htmlValid: false,
        cssValid: false,
        jsValid: false,
        seoCompliant: false,
        responsive: false,
        accessibilityScore: 0,
        performanceScore: 0,
        issues: [`Validation error: ${error}`]
      };
    }
  }

  /**
   * Test deployment pipeline with mock deployments
   */
  static async testDeploymentPipeline(
    testCount: number = 20,
    components: ComponentData[],
    template: Template | null = null
  ): Promise<DeploymentValidationResult> {
    console.log(`🚀 Testing deployment pipeline with ${testCount} test deployments...`);

    const testId = `deployment-test-${Date.now()}`;
    const results: DeploymentResult[] = [];
    const issues: DeploymentIssue[] = [];

    for (let i = 0; i < testCount; i++) {
      console.log(`Testing deployment ${i + 1}/${testCount}...`);

      try {
        const result = await this.mockDeploy(components, template, {
          testMode: true,
          deploymentIndex: i
        });

        results.push(result);
        this.deploymentHistory.push(result);

        // Add artificial delay to simulate real deployment timing
        await new Promise(resolve => setTimeout(resolve, 100));

      } catch (error) {
        const failedResult: DeploymentResult = {
          success: false,
          deploymentId: `test-${testId}-${i}`,
          error: String(error),
          duration: 0,
          timestamp: new Date().toISOString(),
          size: 0,
          provider: 'local'
        };

        results.push(failedResult);
        this.deploymentHistory.push(failedResult);
      }
    }

    // Analyze results
    const successfulDeployments = results.filter(r => r.success).length;
    const failedDeployments = results.filter(r => !r.success).length;
    const successRate = (successfulDeployments / testCount) * 100;
    const averageDeploymentTime = results
      .filter(r => r.success)
      .reduce((sum, r) => sum + r.duration, 0) / successfulDeployments || 0;

    // Identify common issues
    const failureTypes = results
      .filter(r => !r.success)
      .map(r => r.error || 'Unknown error');

    const issueFrequency = failureTypes.reduce((acc, error) => {
      acc[error] = (acc[error] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    Object.entries(issueFrequency).forEach(([error, frequency]) => {
      issues.push({
        type: this.categorizeError(error),
        description: error,
        frequency,
        severity: frequency > testCount * 0.1 ? 'high' : 'medium',
        solution: this.getSolutionForError(error)
      });
    });

    // Generate recommendations
    const recommendations = this.generateRecommendations(successRate, averageDeploymentTime, issues);

    const validationResult: DeploymentValidationResult = {
      testId,
      timestamp: new Date().toISOString(),
      totalTests: testCount,
      successfulDeployments,
      failedDeployments,
      successRate,
      averageDeploymentTime,
      results,
      issues,
      recommendations
    };

    this.validationHistory.push(validationResult);

    console.log(`📊 Deployment Pipeline Test Results:`);
    console.log(`   Success Rate: ${successRate.toFixed(1)}% (Target: 95%)`);
    console.log(`   Average Deployment Time: ${averageDeploymentTime.toFixed(0)}ms`);
    console.log(`   Successful: ${successfulDeployments}, Failed: ${failedDeployments}`);

    if (successRate >= 95) {
      console.log('✅ Deployment success rate target achieved!');
    } else {
      console.log('❌ Deployment success rate below target (95%)');
    }

    return validationResult;
  }

  /**
   * Mock deployment for testing
   */
  private static async mockDeploy(
    components: ComponentData[],
    template: Template | null,
    options: any = {}
  ): Promise<DeploymentResult> {
    const startTime = performance.now();
    const deploymentId = `mock-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    try {
      // Simulate deployment steps with potential failures

      // Step 1: Site Generation (5% failure rate)
      if (Math.random() < 0.05) {
        throw new Error('Site generation failed - component compilation error');
      }

      const generator = new StaticSiteGenerator();
      const site = await generator.generateSite(components, template, {
        siteName: 'Test Deployment',
        seoSettings: {},
        enableOptimization: true,
        minifyOutput: true
      });

      // Step 2: Asset Upload (3% failure rate)
      if (Math.random() < 0.03) {
        throw new Error('Asset upload failed - network timeout');
      }

      // Simulate upload delay
      await new Promise(resolve => setTimeout(resolve, Math.random() * 200 + 50));

      // Step 3: DNS/SSL Configuration (2% failure rate)
      if (Math.random() < 0.02) {
        throw new Error('SSL certificate provisioning failed');
      }

      // Step 4: CDN Distribution (1% failure rate)
      if (Math.random() < 0.01) {
        throw new Error('CDN cache invalidation failed');
      }

      const endTime = performance.now();
      const duration = endTime - startTime;

      // Calculate deployment size
      const totalSize = site.html.length + site.css.length + site.js.length +
        (site.assets?.reduce((sum, asset) => sum + asset.size, 0) || 0);

      return {
        success: true,
        deploymentId,
        url: `https://test-${deploymentId}.vercel.app`,
        duration,
        timestamp: new Date().toISOString(),
        size: totalSize,
        provider: 'vercel'
      };

    } catch (error) {
      const endTime = performance.now();
      const duration = endTime - startTime;

      return {
        success: false,
        deploymentId,
        error: String(error),
        duration,
        timestamp: new Date().toISOString(),
        size: 0,
        provider: 'vercel'
      };
    }
  }

  /**
   * Validate HTML structure
   */
  private static validateHTML(html: string): boolean {
    try {
      // Basic HTML validation checks
      const hasDoctype = html.includes('<!DOCTYPE html>');
      const hasHtmlTag = html.includes('<html') && html.includes('</html>');
      const hasHead = html.includes('<head>') && html.includes('</head>');
      const hasBody = html.includes('<body>') && html.includes('</body>');
      const hasTitle = html.includes('<title>') && html.includes('</title>');
      const hasMetaCharset = html.includes('charset=');
      const hasViewport = html.includes('viewport');

      return hasDoctype && hasHtmlTag && hasHead && hasBody && hasTitle && hasMetaCharset && hasViewport;
    } catch (error) {
      return false;
    }
  }

  /**
   * Validate CSS
   */
  private static validateCSS(css: string): boolean {
    try {
      // Basic CSS validation
      const hasBaseStyles = css.includes('*') || css.includes('body');
      const hasResponsiveQueries = css.includes('@media');
      const noBrokenSelectors = !css.includes(';;') && !css.includes('{}');

      return hasBaseStyles && hasResponsiveQueries && noBrokenSelectors;
    } catch (error) {
      return false;
    }
  }

  /**
   * Validate JavaScript
   */
  private static validateJavaScript(js: string): boolean {
    try {
      // Basic JS validation
      const hasEventListeners = js.includes('addEventListener') || js.includes('DOMContentLoaded');
      const hasNoSyntaxErrors = !js.includes('SyntaxError') && !js.includes('undefined');

      return hasEventListeners && hasNoSyntaxErrors;
    } catch (error) {
      return false;
    }
  }

  /**
   * Validate SEO compliance
   */
  private static validateSEO(html: string, meta: any): boolean {
    try {
      const hasTitle = html.includes('<title>') && !html.includes('<title></title>');
      const hasDescription = html.includes('name="description"');
      const hasKeywords = html.includes('name="keywords"') || meta?.keywords?.length > 0;
      const hasOgTags = html.includes('property="og:');
      const hasStructuredData = html.includes('application/ld+json');

      return hasTitle && hasDescription && (hasKeywords || hasOgTags) && hasStructuredData;
    } catch (error) {
      return false;
    }
  }

  /**
   * Validate responsive design
   */
  private static validateResponsive(css: string): boolean {
    try {
      const hasMediaQueries = css.includes('@media');
      const hasMobileFirst = css.includes('min-width') || css.includes('max-width');
      const hasFlexOrGrid = css.includes('display: flex') || css.includes('display: grid');
      const hasViewportUnits = css.includes('vw') || css.includes('vh') || css.includes('%');

      return hasMediaQueries && hasMobileFirst && (hasFlexOrGrid || hasViewportUnits);
    } catch (error) {
      return false;
    }
  }

  /**
   * Calculate accessibility score
   */
  private static calculateAccessibilityScore(html: string): number {
    let score = 0;

    // Check for accessibility features
    if (html.includes('alt=')) score += 20; // Image alt text
    if (html.includes('aria-')) score += 20; // ARIA attributes
    if (html.includes('role=')) score += 15; // Semantic roles
    if (html.includes('<h1>')) score += 15; // Proper heading structure
    if (html.includes('for=') || html.includes('aria-label')) score += 15; // Form labels
    if (html.includes('tabindex')) score += 10; // Keyboard navigation
    if (html.includes('lang=')) score += 5; // Language declaration

    return Math.min(score, 100);
  }

  /**
   * Categorize deployment errors
   */
  private static categorizeError(error: string): DeploymentIssue['type'] {
    if (error.includes('network') || error.includes('timeout')) return 'network';
    if (error.includes('generation') || error.includes('compilation')) return 'generation';
    if (error.includes('upload') || error.includes('asset')) return 'upload';
    if (error.includes('SSL') || error.includes('DNS') || error.includes('domain')) return 'configuration';
    if (error.includes('timeout')) return 'timeout';
    return 'configuration';
  }

  /**
   * Get solution for common errors
   */
  private static getSolutionForError(error: string): string {
    if (error.includes('network')) return 'Implement retry mechanism with exponential backoff';
    if (error.includes('generation')) return 'Add validation before generation and improve error handling';
    if (error.includes('upload')) return 'Implement chunked uploads and resume functionality';
    if (error.includes('SSL')) return 'Verify SSL certificate configuration and DNS settings';
    if (error.includes('timeout')) return 'Increase timeout limits and optimize deployment pipeline';
    return 'Review deployment logs and implement specific error handling';
  }

  /**
   * Generate recommendations based on test results
   */
  private static generateRecommendations(
    successRate: number,
    averageTime: number,
    issues: DeploymentIssue[]
  ): string[] {
    const recommendations: string[] = [];

    // Success rate recommendations
    if (successRate < 95) {
      recommendations.push(`Improve deployment success rate from ${successRate.toFixed(1)}% to 95%+ target`);
    }

    if (successRate < 90) {
      recommendations.push('Critical: Implement robust error handling and retry mechanisms');
    }

    // Performance recommendations
    if (averageTime > 60000) { // 1 minute
      recommendations.push('Optimize deployment pipeline - average time exceeds 1 minute');
    }

    // Issue-specific recommendations
    const criticalIssues = issues.filter(i => i.severity === 'critical' || i.severity === 'high');
    if (criticalIssues.length > 0) {
      recommendations.push(`Address ${criticalIssues.length} high-priority deployment issues`);
    }

    // Network issues
    const networkIssues = issues.filter(i => i.type === 'network');
    if (networkIssues.length > 0) {
      recommendations.push('Implement network resilience: retries, fallbacks, and timeout handling');
    }

    // Configuration issues
    const configIssues = issues.filter(i => i.type === 'configuration');
    if (configIssues.length > 0) {
      recommendations.push('Review and standardize deployment configuration management');
    }

    if (recommendations.length === 0) {
      recommendations.push('Deployment pipeline meets all targets - maintain current standards');
    }

    return recommendations;
  }

  /**
   * Get deployment success rate over time
   */
  static getSuccessRateHistory(days: number = 7): {
    date: string;
    successRate: number;
    deploymentCount: number;
  }[] {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - days);

    const recentDeployments = this.deploymentHistory.filter(d => 
      new Date(d.timestamp) >= cutoffDate
    );

    // Group by date
    const dailyStats = recentDeployments.reduce((acc, deployment) => {
      const date = deployment.timestamp.split('T')[0];
      if (!acc[date]) {
        acc[date] = { total: 0, successful: 0 };
      }
      acc[date].total++;
      if (deployment.success) {
        acc[date].successful++;
      }
      return acc;
    }, {} as Record<string, { total: number; successful: number }>);

    return Object.entries(dailyStats).map(([date, stats]) => ({
      date,
      successRate: (stats.successful / stats.total) * 100,
      deploymentCount: stats.total
    }));
  }

  /**
   * Clear deployment history
   */
  static clearHistory(): void {
    this.deploymentHistory = [];
    this.validationHistory = [];
  }

  /**
   * Get latest validation result
   */
  static getLatestValidation(): DeploymentValidationResult | null {
    return this.validationHistory.length > 0 ? 
      this.validationHistory[this.validationHistory.length - 1] : null;
  }
}

/**
 * Enhanced Static Site Generator
 * Converts builder components into production-ready static HTML/CSS/JS
 * with advanced asset handling, SEO optimization, and responsive design
 */

import { ComponentData, Template } from '@/types/builder';

interface OptimizedAsset {
  name: string;
  content: string;
  type: string;
  size: number;
  compressed?: boolean;
  hash?: string;
  originalSize?: number;
}

interface SEOMetadata {
  title: string;
  description: string;
  keywords: string[];
  author: string;
  viewport: string;
  themeColor?: string;
  backgroundColor?: string;
  canonical?: string;
  ogTitle?: string;
  ogDescription?: string;
  ogImage?: string;
  ogUrl?: string;
  twitterCard?: string;
  twitterTitle?: string;
  twitterDescription?: string;
  twitterImage?: string;
  structuredData?: object[];
}

interface ResponsiveBreakpoints {
  mobile: number;
  tablet: number;
  desktop: number;
  largeDesktop: number;
}

interface GeneratedSite {
  html: string;
  css: string;
  criticalCSS: string;
  js: string;
  assets: OptimizedAsset[];
  serviceWorker?: string;
  manifest?: string;
  meta: SEOMetadata;
  optimization: {
    totalSize: number;
    compressionRatio: number;
    criticalCSSSize: number;
    assetsOptimized: number;
    seoScore: number;
    responsiveScore: number;
  };
}

interface SiteGenerationOptions {
  siteName: string;
  customDomain?: string;
  seoSettings?: {
    title?: string;
    description?: string;
    keywords?: string[];
    author?: string;
    themeColor?: string;
    backgroundColor?: string;
    focusKeyword?: string;
    industry?: string;
    location?: string;
  };
  performanceOptimization?: boolean;
  includeAnalytics?: boolean;
  minifyOutput?: boolean;
  generatePWA?: boolean;
  enableServiceWorker?: boolean;
  criticalCSS?: boolean;
  imageOptimization?: boolean;
  bundleOptimization?: boolean;
  responsiveOptimization?: boolean;
  advancedSEO?: boolean;
}

interface AssetOptimizationOptions {
  enableCompression: boolean;
  enableImageOptimization: boolean;
  enableFontOptimization: boolean;
  enableCriticalCSS: boolean;
}

export class StaticSiteGenerator {
  private assetCache = new Map<string, OptimizedAsset>();
  private fontCache = new Map<string, string>();

  /**
   * Generate a complete optimized static site from builder components
   */
  public async generateSite(
    components: ComponentData[],
    template: Template | null,
    options: SiteGenerationOptions
  ): Promise<GeneratedSite> {
    const {
      siteName,
      customDomain,
      seoSettings = {},
      performanceOptimization = true,
      minifyOutput = true,
      generatePWA = true,
      enableServiceWorker = true,
      criticalCSS = true,
      imageOptimization = true,
      bundleOptimization = true,
      responsiveOptimization = true,
      advancedSEO = true
    } = options;

    const startTime = performance.now();

    // Generate enhanced SEO metadata
    const seoMetadata = await this.generateAdvancedSEOMetadata(components, seoSettings, siteName, customDomain);

    // Generate responsive CSS with mobile-first approach
    const css = await this.generateResponsiveCSS(components, template, {
      minifyOutput,
      enableOptimization: performanceOptimization,
      responsiveBreakpoints: responsiveOptimization
    });

    // Generate critical CSS for above-the-fold content
    const criticalCSSContent = criticalCSS ? await this.generateCriticalCSS(components) : '';

    // Generate JavaScript with optimizations
    const js = await this.generateJavaScript(components, {
      minifyOutput,
      enableOptimization: bundleOptimization
    });

    // Generate and optimize assets
    const assets = await this.generateOptimizedAssets(components, {
      enableCompression: performanceOptimization,
      enableImageOptimization: imageOptimization,
      enableFontOptimization: performanceOptimization,
      enableCriticalCSS: criticalCSS
    });

    // Generate Progressive Web App files
    let serviceWorker: string | undefined;
    let manifest: string | undefined;

    if (generatePWA) {
      manifest = this.generatePWAManifest(siteName, seoSettings);
      assets.push({
        name: 'manifest.json',
        content: manifest,
        type: 'application/json',
        size: manifest.length,
        hash: this.generateHash(manifest)
      });
    }

    if (enableServiceWorker) {
      serviceWorker = this.generateServiceWorker(assets);
      assets.push({
        name: 'sw.js',
        content: serviceWorker,
        type: 'application/javascript',
        size: serviceWorker.length,
        hash: this.generateHash(serviceWorker)
      });
    }

    // Generate HTML with advanced SEO and responsive optimizations
    const html = this.generateAdvancedHTML(components, template, {
      siteName,
      seoMetadata,
      performanceOptimization,
      criticalCSS: criticalCSSContent,
      enablePWA: generatePWA,
      enableServiceWorker,
      assets,
      responsiveOptimization
    });

    // Calculate optimization metrics
    const totalSize = html.length + css.length + js.length + assets.reduce((sum, asset) => sum + asset.size, 0);
    const optimizedSize = assets.reduce((sum, asset) => sum + (asset.originalSize || asset.size), 0);
    const compressionRatio = optimizedSize > 0 ? (optimizedSize - totalSize) / optimizedSize : 0;

    // Calculate SEO and responsive scores
    const seoScore = advancedSEO ? this.calculateSEOScore(seoMetadata, html, css) : 85;
    const responsiveScore = responsiveOptimization ? this.calculateResponsiveScore(css, html) : 80;

    const generationTime = performance.now() - startTime;
    console.log(`Site generated in ${generationTime.toFixed(2)}ms with ${(compressionRatio * 100).toFixed(1)}% compression`);
    console.log(`SEO Score: ${seoScore}/100, Responsive Score: ${responsiveScore}/100`);

    return {
      html,
      css,
      criticalCSS: criticalCSSContent,
      js,
      assets,
      serviceWorker,
      manifest,
      meta: seoMetadata,
      optimization: {
        totalSize,
        compressionRatio,
        criticalCSSSize: criticalCSSContent.length,
        assetsOptimized: assets.filter(a => a.compressed).length,
        seoScore,
        responsiveScore
      }
    };
  }

  /**
   * Generate optimized HTML structure from components
   */
  private generateHTML(
    components: ComponentData[],
    template: Template | null,
    options: {
      siteName: string;
      seoSettings: any;
      performanceOptimization: boolean;
      criticalCSS: string;
      enablePWA: boolean;
      enableServiceWorker: boolean;
      assets: OptimizedAsset[];
    }
  ): string {
    const {
      siteName,
      seoSettings,
      performanceOptimization,
      criticalCSS,
      enablePWA,
      enableServiceWorker,
      assets
    } = options;

    // Sort components by order for proper rendering
    const sortedComponents = [...components].sort((a, b) => {
      const orderA = a.order || 0;
      const orderB = b.order || 0;
      return orderA - orderB;
    });

    // Generate component HTML
    const componentHTML = sortedComponents.map(component => this.generateComponentHTML(component)).join('\n');

    // Performance optimization meta tags
    const performanceTags = performanceOptimization ? `
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link rel="dns-prefetch" href="//cdnjs.cloudflare.com">
    <link rel="preload" href="./styles.css" as="style">
    <link rel="preload" href="./script.js" as="script">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name="robots" content="index, follow">
    <meta name="googlebot" content="index, follow">
    ` : '';

    // PWA meta tags
    const pwaTags = enablePWA ? `
    <link rel="manifest" href="./manifest.json">
    <meta name="theme-color" content="${seoSettings.themeColor || '#4299e1'}">
    <meta name="background-color" content="${seoSettings.backgroundColor || '#ffffff'}">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="default">
    <meta name="apple-mobile-web-app-title" content="${seoSettings.title || siteName}">
    <link rel="apple-touch-icon" href="./assets/icon-192x192.png">
    ` : '';

    // Critical CSS inline
    const criticalCSSTag = criticalCSS ? `
    <style>
      /* Critical CSS for above-the-fold content */
      ${criticalCSS}
    </style>
    ` : '';

    // Service Worker registration
    const serviceWorkerScript = enableServiceWorker ? `
    <script>
      if ('serviceWorker' in navigator) {
        window.addEventListener('load', function() {
          navigator.serviceWorker.register('./sw.js')
            .then(function(registration) {
              console.log('ServiceWorker registration successful with scope: ', registration.scope);
            })
            .catch(function(err) {
              console.log('ServiceWorker registration failed: ', err);
            });
        });
      }
    </script>
    ` : '';

    // Structured data for SEO
    const structuredData = {
      "@context": "https://schema.org",
      "@type": "WebSite",
      "name": seoSettings.title || siteName,
      "description": seoSettings.description || "",
      "url": typeof window !== 'undefined' ? window.location.origin : '',
      "potentialAction": {
        "@type": "SearchAction",
        "target": {
          "@type": "EntryPoint",
          "urlTemplate": `${typeof window !== 'undefined' ? window.location.origin : ''}?q={search_term_string}`
        },
        "query-input": "required name=search_term_string"
      }
    };

    // Resource hints for better performance
    const resourceHints = `
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link rel="preconnect" href="https://cdn.jsdelivr.net">
    `;

    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${seoSettings.title || siteName}</title>
    <meta name="description" content="${seoSettings.description || ''}">
    <meta name="keywords" content="${(seoSettings.keywords || []).join(', ')}">
    <meta name="author" content="${seoSettings.author || 'AI Marketing Web Builder'}">
    ${performanceTags}
    ${pwaTags}
    ${resourceHints}

    <!-- Open Graph / Facebook -->
    <meta property="og:type" content="website">
    <meta property="og:title" content="${seoSettings.title || siteName}">
    <meta property="og:description" content="${seoSettings.description || ''}">
    <meta property="og:image" content="./assets/og-image.jpg">
    <meta property="og:url" content="${typeof window !== 'undefined' ? window.location.href : ''}">

    <!-- Twitter -->
    <meta property="twitter:card" content="summary_large_image">
    <meta property="twitter:title" content="${seoSettings.title || siteName}">
    <meta property="twitter:description" content="${seoSettings.description || ''}">
    <meta property="twitter:image" content="./assets/og-image.jpg">

    <!-- Structured Data -->
    <script type="application/ld+json">
    ${JSON.stringify(structuredData, null, 2)}
    </script>

    ${criticalCSSTag}

    <!-- Styles (non-critical loaded asynchronously) -->
    <link rel="preload" href="./styles.css" as="style" onload="this.onload=null;this.rel='stylesheet'">
    <noscript><link rel="stylesheet" href="./styles.css"></noscript>

    <!-- Fonts with display optimization -->
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">

    ${serviceWorkerScript}
</head>
<body>
    <div id="site-container">
        ${componentHTML}
    </div>

    <!-- Scripts -->
    <script src="./script.js" defer></script>

    <!-- Analytics placeholder -->
    <script>
      // Google Analytics or other analytics code would go here
      window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments);}
      gtag('js', new Date());
    </script>
</body>
</html>`;
  }

  /**
   * Generate HTML for individual component
   */
  private generateComponentHTML(component: ComponentData): string {
    const { type, props, size, position, style, id } = component;

    // Build inline styles
    const inlineStyles = {
      position: 'absolute',
      left: `${position.x}px`,
      top: `${position.y}px`,
      width: `${size.width}px`,
      height: `${size.height}px`,
      ...style
    };

    const styleString = Object.entries(inlineStyles)
      .map(([key, value]) => `${key.replace(/([A-Z])/g, '-$1').toLowerCase()}: ${value}`)
      .join('; ');

    switch (type) {
      case 'hero':
        return `
        <section id="${id}" class="hero-section" style="${styleString}">
          <div class="hero-content">
            <h1 class="hero-heading">${props.heading || 'Welcome'}</h1>
            <p class="hero-subheading">${props.subheading || 'Discover amazing things'}</p>
            ${props.buttonText ? `<button class="hero-button">${props.buttonText}</button>` : ''}
          </div>
        </section>`;

      case 'features':
        return `
        <section id="${id}" class="features-section" style="${styleString}">
          <div class="features-content">
            <h2 class="features-title">${props.title || 'Features'}</h2>
            <div class="features-grid">
              ${(props.features || []).map((feature: any, index: number) => `
                <div class="feature-item" key="${index}">
                  <h3 class="feature-title">${feature.title}</h3>
                  <p class="feature-description">${feature.description}</p>
                </div>
              `).join('')}
            </div>
          </div>
        </section>`;

      case 'text':
        return `
        <div id="${id}" class="text-component" style="${styleString}">
          ${props.content || props.text || 'Text content'}
        </div>`;

      case 'button':
        return `
        <button id="${id}" class="button-component" style="${styleString}">
          ${props.text || props.content || 'Button'}
        </button>`;

      case 'form':
        return `
        <form id="${id}" class="form-component" style="${styleString}">
          <div class="form-content">
            ${(props.fields || []).map((field: any, index: number) => `
              <div class="form-field" key="${index}">
                <label for="${field.id}" class="form-label">${field.label}</label>
                <input
                  type="${field.type || 'text'}"
                  id="${field.id}"
                  name="${field.id}"
                  placeholder="${field.placeholder || ''}"
                  ${field.required ? 'required' : ''}
                  class="form-input"
                />
              </div>
            `).join('')}
            <button type="submit" class="form-submit">Submit</button>
          </div>
        </form>`;

      default:
        return `
        <div id="${id}" class="component ${type}" style="${styleString}">
          <div class="component-content">
            ${JSON.stringify(props)}
          </div>
        </div>`;
    }
  }

