export const validateBusinessAnalysisRequest = (data: unknown): AnalysisValidation => {
  try {
    BusinessAnalysisRequestSchema.parse(data);
    return {
      isValid: true,
      errors: [],
      confidence_score: 1,
      data_completeness: 1
    };
  } catch (error) {
    if (error instanceof z.ZodError) {
      const validationErrors: ValidationError[] = error.errors.map(err => ({
        field: err.path.join('.'),
        message: err.message,
        code: err.code,
        severity: 'error' as const
      }));

      return {
        isValid: false,
        errors: validationErrors,
        confidence_score: 0,
        data_completeness: 0.5
      };
    }

    return {
      isValid: false,
      errors: [{
        field: 'unknown',
        message: 'Unknown validation error',
        code: 'UNKNOWN_ERROR',
        severity: 'error'
      }],
      confidence_score: 0,
      data_completeness: 0
    };
  }
};

export const validateTemplateRecommendation = (data: unknown): boolean => {
  try {
    TemplateRecommendationSchema.parse(data);
    return true;
  } catch {
    return false;
  }
};

export const validatePersonalizationSettings = (data: unknown): boolean => {
  try {
    PersonalizationSettingsSchema.parse(data);
    return true;
  } catch {
    return false;
  }
};

