import { NextRequest, NextResponse } from 'next/server';

/**
 * Next.js Middleware to handle API errors and prefetch issues
 * This helps prevent "Failed to fetch" errors from breaking navigation
 */
export function middleware(request: NextRequest) {
  // Get the pathname
  const pathname = request.nextUrl.pathname;

  // Handle API routes
  if (pathname.startsWith('/api/')) {
    // Add CORS headers for API routes
    const response = NextResponse.next();

    response.headers.set('Access-Control-Allow-Origin', '*');
    response.headers.set('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    response.headers.set('Access-Control-Allow-Headers', 'Content-Type, Authorization');

    return response;
  }

  // Handle prefetch requests
  if (request.headers.get('purpose') === 'prefetch' || 
      request.headers.get('x-purpose') === 'prefetch') {

    // Add headers to help with prefetch error handling
    const response = NextResponse.next();
    response.headers.set('Cache-Control', 'no-cache, no-store, must-revalidate');
    response.headers.set('X-Prefetch-Safe', 'true');

    return response;
  }

  // Continue with normal request processing
  return NextResponse.next();
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
};

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import { 
  ComponentData, 
  CanvasState, 
  DragItem, 
  DroppableZone, 
  AICustomizationContext,
  Template,
  ComponentElement
} from '@/types/builder';
import { ViewportState, ResponsivePreviewSettings } from '@/types/responsive';

// Export types that other components need
export type { ComponentData, Template };

interface BuilderStore extends CanvasState {
  // Template Management
  currentTemplate: Template | null;
  loadTemplate: (template: Template | string) => void;
  getElementChildren: (elementId: string) => ComponentData[];

  // Actions
  addComponent: (component: ComponentData) => void;
  removeComponent: (componentId: string) => void;
  updateComponent: (componentId: string, updates: Partial<ComponentData>) => void;
  updateComponentProps: (componentId: string, props: ComponentData['props']) => void;
  selectComponent: (componentId: string | null) => void;
  setDraggedComponent: (component: DragItem | null) => void;
  updateComponentPosition: (componentId: string, position: { x: number; y: number }) => void;
  updateComponentSize: (componentId: string, size: { width: number; height: number }) => void;
  setZoom: (zoom: number) => void;
  toggleGrid: () => void;
  toggleSnapToGrid: () => void;
  clearCanvas: () => void;
  duplicateComponent: (componentId: string) => void;
  moveComponent: (componentId: string, direction: 'up' | 'down' | 'left' | 'right') => void;

  // AI Integration
  aiContext: AICustomizationContext | null;
  setAIContext: (context: AICustomizationContext | null) => void;
  requestAICustomization: (componentId: string, prompt: string) => Promise<void>;

  // Workflow Integration
  connectToWorkflow: (componentId: string, workflowId: string) => void;
  disconnectFromWorkflow: (componentId: string) => void;

  // Canvas Management
  setCanvasSize: (size: { width: number; height: number }) => void;
  addDroppableZone: (zone: DroppableZone) => void;
  removeDroppableZone: (zoneId: string) => void;

  // Responsive Design
  viewport: ViewportState;
  responsiveSettings: ResponsivePreviewSettings;
  setViewport: (viewport: Partial<ViewportState>) => void;
  setResponsiveSettings: (settings: Partial<ResponsivePreviewSettings>) => void;
  getResponsiveCanvasSize: () => { width: number; height: number };

  // Utilities
  getComponentById: (componentId: string) => ComponentData | undefined;
  getSelectedComponent: () => ComponentData | undefined;
  canDropComponent: (componentType: string, targetZone?: string) => boolean;
}

export const useBuilderStore = create<BuilderStore>()(
  subscribeWithSelector((set, get) => ({
    // Initial state
    components: [],
    selectedComponentId: null,
    draggedComponent: null,
    droppableZones: [],
    canvasSize: { width: 1200, height: 800 },
    zoom: 1,
    gridEnabled: true,
    snapToGrid: true,
    aiContext: null,
    currentTemplate: null,

    // Responsive Design State
    viewport: {
      currentBreakpoint: 'desktop',
      width: 1024,
      height: 768,
      zoom: 1,
      orientation: 'landscape'
    },
    responsiveSettings: {
      showBreakpointBorders: true,
      showResponsiveGrid: false,
      autoRotate: false,
      simulateTouch: false
    },

    // Component management
    addComponent: (component: ComponentData) => {
      set((state) => ({
        components: [...state.components, component],
        selectedComponentId: component.id,
      }));
    },

    removeComponent: (componentId: string) => {
      set((state) => ({
        components: state.components.filter((c) => c.id !== componentId),
        selectedComponentId: state.selectedComponentId === componentId ? null : state.selectedComponentId,
      }));
    },

    updateComponent: (componentId: string, updates: Partial<ComponentData>) => {
      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId ? { ...c, ...updates } : c
        ),
      }));
    },

    updateComponentProps: (componentId: string, props: ComponentData['props']) => {
      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId ? { ...c, props: { ...c.props, ...props } } : c
        ),
      }));
    },

    selectComponent: (componentId: string | null) => {
      set({ selectedComponentId: componentId });
    },

    setDraggedComponent: (component: DragItem | null) => {
      set({ draggedComponent: component });
    },

    updateComponentPosition: (componentId: string, position: { x: number; y: number }) => {
      const { snapToGrid } = get();
      const snappedPosition = snapToGrid
        ? {
            x: Math.round(position.x / 20) * 20,
            y: Math.round(position.y / 20) * 20,
          }
        : position;

      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId ? { ...c, position: snappedPosition } : c
        ),
      }));
    },

    updateComponentSize: (componentId: string, size: { width: number; height: number }) => {
      const { snapToGrid } = get();
      const snappedSize = snapToGrid
        ? {
            width: Math.max(40, Math.round(size.width / 20) * 20),
            height: Math.max(40, Math.round(size.height / 20) * 20),
          }
        : size;

      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId ? { ...c, size: snappedSize } : c
        ),
      }));
    },

    setZoom: (zoom: number) => {
      set({ zoom: Math.max(0.25, Math.min(3, zoom)) });
    },

    toggleGrid: () => {
      set((state) => ({ gridEnabled: !state.gridEnabled }));
    },

    toggleSnapToGrid: () => {
      set((state) => ({ snapToGrid: !state.snapToGrid }));
    },

    clearCanvas: () => {
      set({
        components: [],
        selectedComponentId: null,
        draggedComponent: null,
      });
    },

    duplicateComponent: (componentId: string) => {
      const component = get().getComponentById(componentId);
      if (component) {
        const newComponent: ComponentData = {
          ...component,
          id: `${component.id}-copy-${Date.now()}`,
          position: {
            x: component.position.x + 20,
            y: component.position.y + 20,
          },
        };
        get().addComponent(newComponent);
      }
    },

    moveComponent: (componentId: string, direction: 'up' | 'down' | 'left' | 'right') => {
      const component = get().getComponentById(componentId);
      if (component) {
        const step = get().snapToGrid ? 20 : 1;
        const newPosition = { ...component.position };

        switch (direction) {
          case 'up':
            newPosition.y = Math.max(0, newPosition.y - step);
            break;
          case 'down':
            newPosition.y += step;
            break;
          case 'left':
            newPosition.x = Math.max(0, newPosition.x - step);
            break;
          case 'right':
            newPosition.x += step;
            break;
        }

        get().updateComponentPosition(componentId, newPosition);
      }
    },

    // AI Integration
    setAIContext: (context: AICustomizationContext | null) => {
      set({ aiContext: context });
    },

    requestAICustomization: async (componentId: string, _prompt: string) => {
      const component = get().getComponentById(componentId);
      if (!component) return;

      // Set loading context
      set({
        aiContext: {
          componentId,
          currentProps: component.props,
          availableActions: ['modify', 'style', 'enhance', 'connect'],
          suggestedModifications: [],
        },
      });

      // Simulate AI processing (replace with actual API call)
      setTimeout(() => {
        set({
          aiContext: {
            componentId,
            currentProps: component.props,
            availableActions: ['modify', 'style', 'enhance', 'connect'],
            suggestedModifications: [
              {
                property: 'style',
                suggestion: 'Add rounded corners and shadow',
                reason: 'Improves visual appeal and modern design',
              },
              {
                property: 'animation',
                suggestion: 'Add hover effect',
                reason: 'Enhances user interaction feedback',
              },
            ],
          },
        });
      }, 1000);
    },

    // Workflow Integration
    connectToWorkflow: (componentId: string, workflowId: string) => {
      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId
            ? { ...c, isConnectedToWorkflow: true, workflowId }
            : c
        ),
      }));
    },

    disconnectFromWorkflow: (componentId: string) => {
      set((state) => ({
        components: state.components.map((c) =>
          c.id === componentId
            ? { ...c, isConnectedToWorkflow: false, workflowId: undefined }
            : c
        ),
      }));
    },

    // Canvas Management
    setCanvasSize: (size: { width: number; height: number }) => {
      set({ canvasSize: size });
    },

    addDroppableZone: (zone: DroppableZone) => {
      set((state) => ({
        droppableZones: [...state.droppableZones, zone],
      }));
    },

    removeDroppableZone: (zoneId: string) => {
      set((state) => ({
        droppableZones: state.droppableZones.filter((z) => z.id !== zoneId),
      }));
    },

    // Utilities
    getComponentById: (componentId: string) => {
      return get().components.find((c) => c.id === componentId);
    },

    getSelectedComponent: () => {
      const { selectedComponentId } = get();
      return selectedComponentId ? get().getComponentById(selectedComponentId) : undefined;
    },

    canDropComponent: (componentType: string, targetZone?: string) => {
      if (!targetZone) return true;

      const zone = get().droppableZones.find((z) => z.id === targetZone);
      return zone ? zone.accepts.includes(componentType) || zone.accepts.includes('*') : true;
    },

    // Template Management
    loadTemplate: (template: Template | string) => {
      let templateToLoad: Template;

      if (typeof template === 'string') {
        // TODO: Fetch template by ID from API or template library
        console.error('Template loading by ID not yet implemented');
        return;
      } else {
        templateToLoad = template;
      }

      // Helper function to calculate layout position based on order
      const calculatePosition = (element: any, index: number): { x: number; y: number } => {
        // If element has explicit position info, use it
        if (element.position) {
          return element.position;
        }

        // Calculate position based on component order and type
        const baseY = index * 120; // Stack components vertically with 120px spacing
        const baseX = 20; // Left margin

        // Adjust positioning based on component type
        switch (element.type) {
          case 'navigation':
            return { x: 0, y: 0 }; // Navigation always at top
          case 'hero':
            return { x: 0, y: element.order === 1 ? 80 : baseY }; // Hero after nav
          case 'container':
            return { x: baseX, y: baseY };
          case 'text':
          case 'button':
            // For nested elements, use relative positioning if parentId exists
            if (element.parentId) {
              return { x: 20, y: 20 }; // Relative to parent
            }
            return { x: baseX, y: baseY };
          default:
            return { x: baseX, y: baseY };
        }
      };

      // Helper function to calculate component size based on type
      const calculateSize = (element: any): { width: number; height: number } => {
        if (element.size) {
          return element.size;
        }

        // Default sizes based on component type
        switch (element.type) {
          case 'navigation':
            return { width: 1200, height: 80 };
          case 'hero':
            return { width: 1200, height: 600 };
          case 'container':
            return { width: 1200, height: 400 };
          case 'card':
            return { width: 350, height: 200 };
          case 'text':
            return { width: 400, height: 60 };
          case 'button':
            return { width: 160, height: 48 };
          case 'form':
            return { width: 400, height: 300 };
          default:
            return { width: 300, height: 100 };
        }
      };

      // Helper function to transform template element to ComponentData
      const transformElement = (element: any, index: number): ComponentData => {
        // Create unique ID for this instance
        const uniqueId = `${element.id}-${Date.now()}-${index}`;

        return {
          id: uniqueId,
          type: element.type,
          name: element.name,
          props: {
            // Merge element props with content and styles
            ...element.props,
            content: element.content,
            styles: element.styles,
          },
          position: calculatePosition(element, index),
          size: calculateSize(element),
          style: element.styles, // Keep original styles for CSS
          children: [], // Initialize as empty, will be populated for nested components
          parentId: element.parentId,
          order: element.order,
        };
      };

      // Transform template elements to ComponentData format
      const transformedComponents: ComponentData[] = [];

      // Get elements array (handle both 'elements' and 'components' properties)
      const templateElements = (templateToLoad as any).elements || templateToLoad.components || [];

      if (templateElements.length === 0) {
        console.warn('Template has no elements to load');
        set({
          currentTemplate: templateToLoad,
          components: [],
          selectedComponentId: null,
        });
        return;
      }

      // First pass: Create all components
      const componentMap = new Map<string, ComponentData>();

      templateElements.forEach((element: any, index: number) => {
        const component = transformElement(element, index);
        componentMap.set(element.id, component); // Map using original ID for relationships
        transformedComponents.push(component);
      });

      // Second pass: Handle parent-child relationships
      templateElements.forEach((element: any) => {
        if (element.children && Array.isArray(element.children)) {
          const parentComponent = componentMap.get(element.id);
          if (parentComponent) {
            // Build children array with proper ComponentData references
            const childComponents: ComponentData[] = [];

            element.children.forEach((childRef: any) => {
              const childId = typeof childRef === 'string' ? childRef : childRef.id;
              const childComponent = componentMap.get(childId);
              if (childComponent) {
                childComponents.push(childComponent);
              }
            });

            // Update parent component with children
            parentComponent.children = childComponents;
          }
        }
      });

      // Sort components by order for proper layering
      transformedComponents.sort((a, b) => {
        const orderA = a.order || 0;
        const orderB = b.order || 0;
        return orderA - orderB;
      });

      console.log(`Loading template: ${templateToLoad.name} with ${transformedComponents.length} components`);

      // Update store state
      set({
        currentTemplate: templateToLoad,
        components: transformedComponents,
        selectedComponentId: null, // Clear selection when loading template
      });
    },

    getElementChildren: (elementId: string) => {
      const element = get().components.find((c) => c.id === elementId);
      if (!element || !element.children) return [];

      // Return direct children array (already ComponentData[])
      return element.children;
    },

    // Responsive Design Actions
    setViewport: (viewport: Partial<ViewportState>) => {
      set((state) => ({
        viewport: { ...state.viewport, ...viewport }
      }));

      // Update canvas zoom when viewport zoom changes
      if (viewport.zoom !== undefined) {
        set({ zoom: viewport.zoom });
      }
    },

    setResponsiveSettings: (settings: Partial<ResponsivePreviewSettings>) => {
      set((state) => ({
        responsiveSettings: { ...state.responsiveSettings, ...settings }
      }));
    },

    getResponsiveCanvasSize: () => {
      const { viewport, canvasSize } = get();

      // Return viewport size when in responsive preview mode
      if (viewport.currentBreakpoint !== 'desktop') {
        return {
          width: viewport.width,
          height: viewport.height
        };
      }

      // Return default canvas size for desktop
      return canvasSize;
    },
  }))
);

/* Clean Container Components Styles */

/* Base container styling */
.container-component {
  @apply relative transition-all duration-200 ease-in-out;
}

/* Selection states */
.container-selected {
  @apply ring-2 ring-blue-500;
}

.container-hover:not(.container-selected) {
  @apply ring-1 ring-blue-300;
}

/* Connected workflow indicator */
.container-connected {
  @apply ring-2 ring-emerald-400 ring-offset-1;
}

/* Resize handles */
.resize-handle {
  @apply absolute w-3 h-3 bg-blue-500 border border-white rounded-full shadow-sm;
  @apply hover:bg-blue-600 hover:scale-110 transition-all duration-150 cursor-pointer;
}

.resize-handle:hover {
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.resize-handle.active {
  @apply bg-blue-600 scale-110;
}

/* Resize handle positions */
.resize-handle-se {
  @apply bottom-0 right-0;
  transform: translate(50%, 50%);
  cursor: nwse-resize;
}

.resize-handle-sw {
  @apply bottom-0 left-0;
  transform: translate(-50%, 50%);
  cursor: nesw-resize;
}

.resize-handle-ne {
  @apply top-0 right-0;
  transform: translate(50%, -50%);
  cursor: nesw-resize;
}

.resize-handle-nw {
  @apply top-0 left-0;
  transform: translate(-50%, -50%);
  cursor: nwse-resize;
}

.resize-handle-e {
  @apply top-1/2 right-0;
  transform: translate(50%, -50%);
  cursor: ew-resize;
}

.resize-handle-s {
  @apply bottom-0 left-1/2;
  transform: translate(-50%, 50%);
  cursor: ns-resize;
}

/* Control buttons */
.control-button {
  @apply absolute rounded-full p-1.5 shadow-sm transition-all duration-200;
  @apply text-white hover:scale-105;
}

.control-button-move {
  @apply -top-3 -left-3 bg-blue-500 hover:bg-blue-600;
}

.control-button-settings {
  @apply -top-3 -right-3 bg-gray-600 hover:bg-gray-700;
  @apply opacity-0 group-hover:opacity-100;
}

.control-button-workflow {
  @apply -bottom-2 -right-2 bg-emerald-500 hover:bg-emerald-600;
}

/* Container variants */
.container-empty {
  @apply border-2 border-dashed border-gray-300 bg-gray-50/50;
  @apply hover:border-blue-300 hover:bg-blue-50/30;
  @apply flex items-center justify-center min-h-[120px];
}

.container-section {
  @apply bg-white border border-gray-200 rounded-lg p-6;
}

.container-hero {
  @apply bg-gradient-to-br from-blue-50 to-indigo-100;
  @apply border border-blue-200 rounded-lg p-8;
}

.container-feature {
  @apply bg-gray-50 border border-gray-200 rounded-lg p-6;
}

.container-cta {
  @apply bg-gradient-to-r from-blue-500 to-purple-600;
  @apply text-white rounded-lg p-8;
}

.container-testimonial {
  @apply bg-white border-2 border-gray-100 rounded-xl p-6 shadow-sm;
}

.container-footer {
  @apply bg-gray-900 text-white rounded-lg p-8;
}

/* Empty state content */
.container-empty-content {
  @apply text-center p-8;
}

.container-empty-title {
  @apply text-gray-400 text-sm font-medium mb-2;
}

.container-empty-description {
  @apply text-gray-500 text-xs;
}

/* Component label */
.component-label {
  @apply absolute -top-6 left-0 bg-blue-500 text-white text-xs px-2 py-1 rounded shadow-sm;
}

/* Size indicator during resize */
.size-indicator {
  @apply absolute -top-8 left-1/2 -translate-x-1/2;
  @apply bg-gray-800 text-white text-xs px-2 py-1 rounded shadow-sm;
}

/* Workflow connector button */
.workflow-connector {
  @apply absolute -bottom-7 left-1/2 transform -translate-x-1/2;
  @apply px-2 py-1 rounded text-xs font-medium transition-all duration-200;
  @apply flex items-center space-x-1 shadow-sm border;
}

.workflow-connector-disconnected {
  @apply bg-white text-gray-600 border-gray-200;
  @apply hover:bg-gray-50 hover:border-blue-300;
}

.workflow-connector-connected {
  @apply bg-emerald-50 text-emerald-700 border-emerald-200;
  @apply hover:bg-emerald-100;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .resize-handle {
    @apply w-4 h-4; /* Slightly larger on mobile for better touch targets */
  }

  .control-button {
    @apply p-2; /* Larger touch targets */
  }

  .container-section,
  .container-hero,
  .container-feature,
  .container-cta,
  .container-testimonial,
  .container-footer {
    @apply p-4; /* Reduced padding on mobile */
  }
}

/* Animation keyframes */
@keyframes pulse-ring {
  0% {
    transform: scale(0.8);
    opacity: 1;
  }
  100% {
    transform: scale(2.4);
    opacity: 0;
  }
}

.workflow-pulse::before {
  content: '';
  @apply absolute inset-0 rounded-full bg-emerald-400 opacity-20;
  animation: pulse-ring 2s cubic-bezier(0.455, 0.03, 0.515, 0.955) infinite;
}

import { CSSProperties } from 'react';

// Unified ComponentData interface - THE SINGLE SOURCE OF TRUTH
export interface ComponentData {
  id: string;
  type: string;
  name: string;
  props: Record<string, any>;
  children?: ComponentData[];
  position: {
    x: number;
    y: number;
  };
  size: {
    width: number;
    height: number;
  };
  style?: CSSProperties;
  isConnectedToWorkflow?: boolean;
  workflowId?: string | undefined; // Explicitly allow undefined
  // Added for compatibility with existing code
  content?: string;
  parentId?: string | null;
  order?: number;
}

// React DnD Types - Properly typed for v16
export interface DragItem {
  type: string;
  id: string;
  componentType: string;
  name: string;
  defaultProps: Record<string, any>;
  category: ComponentCategory;
  preview: {
    thumbnail: string;
    description: string;
  };
}

export interface DragCollectedProps {
  isDragging: boolean;
  opacity?: number;
}

export interface DropCollectedProps {
  isOver: boolean;
  canDrop: boolean;
}

export interface DropResult {
  dropEffect: string;
  position: {
    x: number;
    y: number;
  };
  targetZone?: string;
}

export interface DroppableZone {
  id: string;
  accepts: string[];
  position: {
    x: number;
    y: number;
  };
  size: {
    width: number;
    height: number;
  };
}

export type ComponentCategory = 
  | 'layout'
  | 'content'
  | 'forms'
  | 'navigation'
  | 'media'
  | 'interactive'
  | 'ai-powered';

// Canvas State - Unified interface
export interface CanvasState {
  components: ComponentData[];
  selectedComponentId: string | null;
  draggedComponent: DragItem | null;
  droppableZones: DroppableZone[];
  canvasSize: {
    width: number;
    height: number;
  };
  zoom: number;
  gridEnabled: boolean;
  snapToGrid: boolean;
}

// Builder Configuration
export interface BuilderConfig {
  maxComponents: number;
  allowNestedComponents: boolean;
  enableAIAssistance: boolean;
  autoSave: boolean;
  autoSaveInterval: number;
}

// AI Context
export interface AICustomizationContext {
  componentId: string;
  currentProps: Record<string, any>;
  availableActions: string[];
  suggestedModifications: Array<{
    property: string;
    suggestion: string;
    reason: string;
  }>;
}

// Template Interface - Compatible with existing template system
export interface Template {
  id: string;
  name: string;
  category: 'landing' | 'ecommerce' | 'blog' | 'portfolio' | 'corporate' | 'startup';
  description: string;
  thumbnail: string;
  components: ComponentData[]; // Use ComponentData instead of elements
  createdAt: Date;
  updatedAt: Date;
}

// Legacy compatibility - Map ComponentElement to ComponentData
export interface ComponentElement extends Omit<ComponentData, 'children'> {
  // These are mapped from ComponentData for backward compatibility
  styles: CSSProperties;
  children?: ComponentData[]; // Use ComponentData[] to match parent interface
}

// Workflow Types
export interface WorkflowConnection {
  id: string;
  componentId: string;
  trigger: TriggerType;
  actions: WorkflowAction[];
  aiSuggested: boolean;
  active: boolean;
}

export type TriggerType = 
  | 'form-submit'
  | 'button-click'
  | 'page-view'
  | 'scroll-position'
  | 'time-delay'
  | 'exit-intent';

export interface WorkflowAction {
  id: string;
  type: 'email' | 'crm' | 'webhook' | 'notification' | 'redirect';
  config: Record<string, unknown>;
}

// Analytics
export interface ComponentAnalytics {
  views: number;
  interactions: number;
  conversions: number;
  lastUpdated: Date;
}

// AI Customization
export interface AICustomization {
  id: string;
  prompt: string;
  changes: Partial<ComponentData>;
  timestamp: Date;
  applied: boolean;
}

// Responsive Configuration
export interface ResponsiveConfig {
  mobile: Partial<CSSProperties>;
  tablet: Partial<CSSProperties>;
  desktop: Partial<CSSProperties>;
}

// Form Fields
export interface FormField {
  id: string;
  type: 'text' | 'email' | 'tel' | 'textarea' | 'select' | 'checkbox';
  label: string;
  placeholder?: string;
  required?: boolean;
  options?: string[];
}

// Component Content Structure
export interface ComponentContent {
  text?: string;
  heading?: string;
  subheading?: string;
  buttonText?: string;
  imageUrl?: string;
  imageAlt?: string;
  formFields?: FormField[];
}

// Utility type for drag source specification
export interface DragSourceSpec {
  type: string;
  item: DragItem;
  collect: (monitor: any) => DragCollectedProps;
  begin?: () => void;
  end?: () => void;
}

// Utility type for drop target specification
export interface DropTargetSpec {
  accept: string | string[];
  drop?: (item: DragItem, monitor: any) => DropResult | undefined;
  hover?: (item: DragItem, monitor: any) => void;
  collect: (monitor: any) => DropCollectedProps;
}

/**
 * Real-time Collaboration Types
 * Defines the structure for multi-user collaborative editing
 */

import { ComponentData } from './builder';

// User presence and session management
export interface CollaborationUser {
  id: string;
  name: string;
  email: string;
  color: string;
  avatar?: string;
  status: 'active' | 'idle' | 'away';
  lastSeen: Date;
  permissions: UserPermission;
}

export type UserPermission = 'owner' | 'editor' | 'viewer';

// Real-time cursor and selection tracking
export interface UserCursor {
  userId: string;
  position: {
    x: number;
    y: number;
  };
  visible: boolean;
  timestamp: Date;
}

export interface UserSelection {
  userId: string;
  componentId: string | null;
  timestamp: Date;
}

// Component locking for conflict prevention
export interface ComponentLock {
  componentId: string;
  userId: string;
  lockType: 'editing' | 'moving' | 'resizing';
  timestamp: Date;
  expiresAt: Date;
}

// Real-time events for synchronization
export type CollaborationEvent = 
  | UserJoinedEvent
  | UserLeftEvent
  | UserCursorUpdateEvent
  | ComponentAddedEvent
  | ComponentUpdatedEvent
  | ComponentDeletedEvent
  | ComponentMovedEvent
  | ComponentResizedEvent
  | ComponentSelectedEvent
  | ComponentLockedEvent
  | ComponentUnlockedEvent
  | ChatMessageEvent;

export interface BaseCollaborationEvent {
  id: string;
  type: string;
  userId: string;
  timestamp: Date;
  projectId: string;
}

export interface UserJoinedEvent extends BaseCollaborationEvent {
  type: 'user.joined';
  user: CollaborationUser;
}

export interface UserLeftEvent extends BaseCollaborationEvent {
  type: 'user.left';
  userId: string;
}

export interface UserCursorUpdateEvent extends BaseCollaborationEvent {
  type: 'user.cursor_update';
  cursor: UserCursor;
}

export interface ComponentAddedEvent extends BaseCollaborationEvent {
  type: 'component.added';
  component: ComponentData;
  position: { x: number; y: number };
}

export interface ComponentUpdatedEvent extends BaseCollaborationEvent {
  type: 'component.updated';
  componentId: string;
  changes: Partial<ComponentData>;
  version: number;
}

export interface ComponentDeletedEvent extends BaseCollaborationEvent {
  type: 'component.deleted';
  componentId: string;
}

export interface ComponentMovedEvent extends BaseCollaborationEvent {
  type: 'component.moved';
  componentId: string;
  position: { x: number; y: number };
}

export interface ComponentResizedEvent extends BaseCollaborationEvent {
  type: 'component.resized';
  componentId: string;
  size: { width: number; height: number };
}

export interface ComponentSelectedEvent extends BaseCollaborationEvent {
  type: 'component.selected';
  componentId: string | null;
}

export interface ComponentLockedEvent extends BaseCollaborationEvent {
  type: 'component.locked';
  lock: ComponentLock;
}

export interface ComponentUnlockedEvent extends BaseCollaborationEvent {
  type: 'component.unlocked';
  componentId: string;
}

export interface ChatMessageEvent extends BaseCollaborationEvent {
  type: 'chat.message';
  message: string;
  timestamp: Date;
}

// Operational Transform for conflict resolution
export interface Operation {
  id: string;
  type: 'insert' | 'delete' | 'retain' | 'modify';
  position?: number;
  length?: number;
  data?: any;
  componentId?: string;
  property?: string;
  timestamp: Date;
  userId: string;
}

export interface OperationResult {
  applied: boolean;
  transformedOps: Operation[];
  conflicts: ConflictResolution[];
}

export interface ConflictResolution {
  type: 'auto_resolved' | 'manual_required' | 'user_choice_needed';
  description: string;
  operations: Operation[];
  suggestedResolution?: 'accept_local' | 'accept_remote' | 'merge';
}

// WebSocket connection state
export interface CollaborationState {
  isConnected: boolean;
  connectionStatus: 'connecting' | 'connected' | 'disconnected' | 'error' | 'reconnecting';
  currentUser: CollaborationUser | null;
  activeUsers: CollaborationUser[];
  userCursors: Map<string, UserCursor>;
  componentLocks: Map<string, ComponentLock>;
  lastPingTime: Date | null;
  connectionId: string | null;
}

// Room and project context
export interface CollaborationRoom {
  id: string;
  projectId: string;
  name: string;
  activeUsers: string[];
  maxUsers: number;
  createdAt: Date;
  updatedAt: Date;
}

// Chat and communication
export interface ChatMessage {
  id: string;
  userId: string;
  user: CollaborationUser;
  message: string;
  timestamp: Date;
  type: 'text' | 'system' | 'component_mention';
  componentId?: string;
}

// Real-time synchronization preferences
export interface SyncPreferences {
  enableRealTimeSync: boolean;
  enableCursorSharing: boolean;
  enableComponentLocking: boolean;
  enableChatNotifications: boolean;
  autoSaveInterval: number; // milliseconds
  conflictResolutionStrategy: 'auto' | 'manual' | 'ask_user';
}

// Error handling for collaboration
export interface CollaborationError {
  type: 'connection' | 'permission' | 'conflict' | 'validation' | 'timeout';
  message: string;
  code: string;
  timestamp: Date;
  userId?: string;
  componentId?: string;
  recoverable: boolean;
}

// Analytics and monitoring
export interface CollaborationMetrics {
  activeUsers: number;
  totalOperations: number;
  conflictsResolved: number;
  averageLatency: number;
  connectionUptime: number;
  lastSyncTime: Date;
}

