/**
 * Workflow Automation Engine Types
 * Comprehensive type definitions for visual workflow building and execution
 */

// Core Workflow Types
export interface WorkflowNode {
  id: string;
  type: WorkflowNodeType;
  position: { x: number; y: number };
  data: WorkflowNodeData;
  selected?: boolean;
  dragging?: boolean;
}

export interface WorkflowEdge {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
  type?: string;
  data?: {
    condition?: string;
    label?: string;
  };
  animated?: boolean;
  style?: React.CSSProperties;
}

export interface WorkflowNodeData {
  label: string;
  description?: string;
  config: Record<string, any>;
  inputs?: WorkflowInput[];
  outputs?: WorkflowOutput[];
  status?: 'idle' | 'running' | 'success' | 'error';
  executionTime?: number;
  lastExecuted?: Date;
  errorMessage?: string;
}

export interface WorkflowInput {
  id: string;
  name: string;
  type: InputType;
  required?: boolean;
  defaultValue?: any;
  validation?: ValidationRule[];
}

export interface WorkflowOutput {
  id: string;
  name: string;
  type: OutputType;
  description?: string;
}

export type WorkflowNodeType = 
  | 'trigger'
  | 'action'
  | 'condition' 
  | 'delay'
  | 'webhook'
  | 'email'
  | 'sms'
  | 'crm'
  | 'database'
  | 'api'
  | 'transform'
  | 'split'
  | 'merge'
  | 'end';

export type TriggerNodeType = 
  | 'form_submission'
  | 'page_view'
  | 'button_click'
  | 'time_based'
  | 'webhook'
  | 'api_call'
  | 'email_open'
  | 'email_click'
  | 'cart_abandonment'
  | 'user_signup'
  | 'purchase_complete';

export type ActionNodeType =
  | 'send_email'
  | 'create_contact'
  | 'update_contact'
  | 'add_to_list'
  | 'remove_from_list'
  | 'send_sms'
  | 'create_task'
  | 'send_notification'
  | 'update_database'
  | 'call_api'
  | 'generate_coupon'
  | 'schedule_meeting'
  | 'track_event';

export type ConditionNodeType =
  | 'if_then_else'
  | 'filter'
  | 'switch'
  | 'loop'
  | 'exists_check'
  | 'comparison'
  | 'text_contains'
  | 'number_range'
  | 'date_range'
  | 'list_contains';

export type InputType = 
  | 'text' 
  | 'email' 
  | 'number' 
  | 'boolean' 
  | 'date' 
  | 'select' 
  | 'multiselect'
  | 'json'
  | 'file'
  | 'url';

export type OutputType = 
  | 'text' 
  | 'email' 
  | 'number' 
  | 'boolean' 
  | 'date' 
  | 'object'
  | 'array'
  | 'file'
  | 'url';

export interface ValidationRule {
  type: 'required' | 'email' | 'url' | 'min' | 'max' | 'pattern' | 'custom';
  value?: any;
  message: string;
}

// Visual Workflow Builder Types
export interface WorkflowDefinition {
  id: string;
  name: string;
  description?: string;
  version: number;
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  variables: WorkflowVariable[];
  settings: WorkflowSettings;
  metadata: WorkflowMetadata;
  status: 'draft' | 'active' | 'paused' | 'error';
  created_at: Date;
  updated_at: Date;
}

export interface WorkflowVariable {
  id: string;
  name: string;
  type: InputType;
  value?: any;
  scope: 'global' | 'local';
  description?: string;
}

export interface WorkflowSettings {
  maxExecutionTime: number; // seconds
  retryAttempts: number;
  retryDelay: number; // seconds
  enableLogging: boolean;
  enableAnalytics: boolean;
  errorHandling: 'stop' | 'continue' | 'retry';
  rateLimiting?: {
    maxExecutionsPerHour: number;
    maxExecutionsPerDay: number;
  };
}

export interface WorkflowMetadata {
  category: string;
  tags: string[];
  author: string;
  lastModifiedBy: string;
  usageCount: number;
  averageExecutionTime: number;
  successRate: number;
  integrations: string[];
}

// Execution Engine Types
export interface WorkflowExecution {
  id: string;
  workflowId: string;
  status: ExecutionStatus;
  triggerData: any;
  executionContext: ExecutionContext;
  startTime: Date;
  endTime?: Date;
  duration?: number;
  steps: ExecutionStep[];
  error?: ExecutionError;
  result?: any;
}

export type ExecutionStatus = 
  | 'pending'
  | 'running' 
  | 'completed'
  | 'failed'
  | 'cancelled'
  | 'timeout';

export interface ExecutionContext {
  variables: Record<string, any>;
  environment: 'development' | 'staging' | 'production';
  userId?: string;
  sessionId?: string;
  requestId?: string;
}

export interface ExecutionStep {
  nodeId: string;
  nodeType: WorkflowNodeType;
  status: ExecutionStatus;
  startTime: Date;
  endTime?: Date;
  duration?: number;
  input?: any;
  output?: any;
  error?: ExecutionError;
  retryAttempt?: number;
}

export interface ExecutionError {
  code: string;
  message: string;
  details?: any;
  stack?: string;
  nodeId?: string;
  recoverable: boolean;
}

