import { test, expect } from '@playwright/test';

/**
 * AI Component Customization Tests
 * Tests v0-style AI editing and component modification
 */
test.describe('AI Component Customization', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/builder');
    await page.click('[data-testid=component-library]');
    await page.dragAndDrop('[data-testid=hero-section-component]', '[data-testid=canvas]');
    await page.click('[data-testid=hero-section]');
  });

  test('natural language component modification', async ({ page }) => {
    const testPrompts = [
      'Make this more modern and blue',
      'Add a gradient background',
      'Make the text larger and bold',
      'Center align everything',
      'Add more padding around the content',
      'Make this look more professional',
      'Change the button to green',
      'Add a subtle shadow effect'
    ];

    for (const prompt of testPrompts) {
      // Enter AI prompt
      await page.fill('[data-testid=ai-prompt]', prompt);
      await page.click('[data-testid=generate-variations]');

      // Wait for AI to generate variations
      await expect(page.locator('[data-testid=ai-variations]')).toBeVisible({ timeout: 10000 });

      // Verify 3 variations are generated
      await expect(page.locator('[data-testid=variation-1]')).toBeVisible();
      await expect(page.locator('[data-testid=variation-2]')).toBeVisible();
      await expect(page.locator('[data-testid=variation-3]')).toBeVisible();

      // Test variation preview
      await page.hover('[data-testid=variation-1]');
      await expect(page.locator('[data-testid=preview-overlay]')).toBeVisible();

      // Apply variation
      await page.click('[data-testid=variation-1]');
      await expect(page.locator('[data-testid=component-modified]')).toBeVisible();

      // Verify undo functionality
      await page.click('[data-testid=undo-button]');

      // Clear prompt for next iteration
      await page.fill('[data-testid=ai-prompt]', '');
    }
  });

  test('AI customization performance benchmarks', async ({ page }) => {
    const performanceTests = [
      { prompt: 'Make this blue', expectedMaxTime: 3000 },
      { prompt: 'Add a gradient background from blue to purple', expectedMaxTime: 4000 },
      { prompt: 'Make this component look more modern with shadows and rounded corners', expectedMaxTime: 5000 },
      { prompt: 'Transform this into a dark theme with neon accents and futuristic styling', expectedMaxTime: 6000 }
    ];

    for (const test of performanceTests) {
      const startTime = Date.now();

      await page.fill('[data-testid=ai-prompt]', test.prompt);
      await page.click('[data-testid=generate-variations]');
      await page.waitForSelector('[data-testid=ai-variations]');

      const endTime = Date.now();
      const responseTime = endTime - startTime;

      expect(responseTime).toBeLessThan(test.expectedMaxTime);

      // Clear for next test
      await page.fill('[data-testid=ai-prompt]', '');
      await page.click('[data-testid=clear-variations]');
    }
  });

  test('brand consistency enforcement', async ({ page }) => {
    // Set brand guidelines
    await page.click('[data-testid=brand-settings]');
    await page.fill('[data-testid=primary-color]', '#FF6B6B');
    await page.fill('[data-testid=secondary-color]', '#4ECDC4');
    await page.fill('[data-testid=brand-font]', 'Inter');
    await page.click('[data-testid=save-brand]');

    // Test AI respects brand guidelines
    await page.fill('[data-testid=ai-prompt]', 'Make this more colorful');
    await page.click('[data-testid=generate-variations]');

    await page.waitForSelector('[data-testid=ai-variations]');

    // Check that variations use brand colors
    const variation1 = page.locator('[data-testid=variation-1]');
    await expect(variation1).toBeVisible();

    // Apply variation and verify brand consistency
    await page.click('[data-testid=variation-1]');

    const heroSection = page.locator('[data-testid=hero-section]');
    const computedStyle = await heroSection.evaluate((el) => {
      return window.getComputedStyle(el);
    });

    // Should use brand colors or complementary colors
    expect(computedStyle.color || computedStyle.backgroundColor).toMatch(/(255, 107, 107)|(78, 205, 196)/);
  });

  test('multi-component batch editing', async ({ page }) => {
    // Add multiple components
    await page.click('[data-testid=component-library]');
    await page.dragAndDrop('[data-testid=feature-grid-component]', '[data-testid=canvas]');
    await page.dragAndDrop('[data-testid=call-to-action-component]', '[data-testid=canvas]');

    // Select multiple components
    await page.keyboard.down('Shift');
    await page.click('[data-testid=hero-section]');
    await page.click('[data-testid=feature-grid]');
    await page.click('[data-testid=call-to-action]');
    await page.keyboard.up('Shift');

    // Apply AI modification to all selected
    await page.fill('[data-testid=ai-prompt]', 'Make all of these use a consistent blue theme');
    await page.click('[data-testid=generate-variations]');

    await page.waitForSelector('[data-testid=ai-variations]');
    await page.click('[data-testid=variation-1]');

    // Verify all components were modified consistently
    await expect(page.locator('[data-testid=hero-section][data-modified="true"]')).toBeVisible();
    await expect(page.locator('[data-testid=feature-grid][data-modified="true"]')).toBeVisible();
    await expect(page.locator('[data-testid=call-to-action][data-modified="true"]')).toBeVisible();
  });

  test('AI accessibility compliance', async ({ page }) => {
    // Test AI maintains accessibility standards
    await page.fill('[data-testid=ai-prompt]', 'Make this text very light gray on white background');
    await page.click('[data-testid=generate-variations]');

    await page.waitForSelector('[data-testid=ai-variations]');

    // Check for accessibility warnings
    await expect(page.locator('[data-testid=accessibility-warning]')).toBeVisible();
    await expect(page.locator('[data-testid=contrast-ratio-warning]')).toContainText('contrast ratio');

    // Test AI provides accessible alternative
    await page.click('[data-testid=suggest-accessible-alternative]');
    await expect(page.locator('[data-testid=accessible-variation]')).toBeVisible();

    // Apply accessible version
    await page.click('[data-testid=accessible-variation]');

    // Verify accessibility compliance
    const textElement = page.locator('[data-testid=hero-title]');
    const styles = await textElement.evaluate((el) => {
      const computed = window.getComputedStyle(el);
      return {
        color: computed.color,
        backgroundColor: computed.backgroundColor
      };
    });

    // Should have sufficient contrast ratio (simplified check)
    expect(styles.color).not.toBe('rgb(211, 211, 211)'); // Very light gray
  });

  test('AI learning and improvement', async ({ page }) => {
    // Test user feedback improves AI suggestions
    await page.fill('[data-testid=ai-prompt]', 'Make this more professional');
    await page.click('[data-testid=generate-variations]');

    await page.waitForSelector('[data-testid=ai-variations]');

    // Rate variations
    await page.click('[data-testid=variation-1]');
    await page.click('[data-testid=thumbs-up]'); // Positive feedback

    await page.fill('[data-testid=ai-prompt]', 'Make this more professional');
    await page.click('[data-testid=generate-variations]');

    await page.waitForSelector('[data-testid=ai-variations]');

    // Second generation should be influenced by feedback
    // This would need actual AI integration to test properly
    await expect(page.locator('[data-testid=ai-variations]')).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

/**
 * Component Library and Drag-Drop Tests
 * Tests the 50+ smart components and drag-drop functionality
 */
test.describe('Component Library', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/builder');
    await expect(page.locator('[data-testid=canvas]')).toBeVisible();
  });

  test('drag and drop all component types', async ({ page }) => {
    const components = [
      'hero-section',
      'contact-form',
      'newsletter-signup',
      'pricing-table',
      'testimonials',
      'feature-grid',
      'call-to-action',
      'image-gallery',
      'video-embed',
      'social-proof',
      'faq-section',
      'team-showcase',
      'stats-counter',
      'progress-bars',
      'timeline',
      'blog-preview',
      'product-showcase',
      'booking-form',
      'search-bar',
      'navigation-menu'
    ];

    await page.click('[data-testid=component-library]');

    for (const component of components) {
      // Drag component to canvas
      await page.dragAndDrop(
        `[data-testid=${component}-component]`,
        '[data-testid=canvas]'
      );

      // Verify component was added
      await expect(page.locator(`[data-testid=${component}]`)).toBeVisible();

      // Test component selection
      await page.click(`[data-testid=${component}]`);
      await expect(page.locator('[data-testid=property-editor]')).toBeVisible();

      // Verify component has workflow connect button (for form components)
      if (['contact-form', 'newsletter-signup', 'booking-form', 'search-bar'].includes(component)) {
        await expect(page.locator('[data-testid=connect-workflow-button]')).toBeVisible();
      }
    }
  });

  test('component positioning and layout', async ({ page }) => {
    await page.click('[data-testid=component-library]');

    // Add multiple components
    await page.dragAndDrop('[data-testid=hero-section-component]', '[data-testid=canvas]');
    await page.dragAndDrop('[data-testid=feature-grid-component]', '[data-testid=canvas]');
    await page.dragAndDrop('[data-testid=contact-form-component]', '[data-testid=canvas]');

    // Test component reordering
    await page.dragAndDrop('[data-testid=contact-form]', '[data-testid=hero-section]');

    // Verify new order
    const components = await page.locator('[data-testid^=component-]:visible').all();
    expect(components.length).toBe(3);

    // Test responsive behavior
    await page.setViewportSize({ width: 768, height: 1024 }); // Tablet
    await expect(page.locator('[data-testid=canvas]')).toBeVisible();

    await page.setViewportSize({ width: 375, height: 667 }); // Mobile
    await expect(page.locator('[data-testid=canvas]')).toBeVisible();

    // Return to desktop
    await page.setViewportSize({ width: 1280, height: 720 });
  });

  test('component styling and customization', async ({ page }) => {
    await page.click('[data-testid=component-library]');
    await page.dragAndDrop('[data-testid=hero-section-component]', '[data-testid=canvas]');

    // Select component for editing
    await page.click('[data-testid=hero-section]');
    await expect(page.locator('[data-testid=property-editor]')).toBeVisible();

    // Test color customization
    await page.click('[data-testid=background-color]');
    await page.fill('[data-testid=color-input]', '#3B82F6');
    await expect(page.locator('[data-testid=hero-section]')).toHaveCSS('background-color', 'rgb(59, 130, 246)');

    // Test text editing
    await page.dblclick('[data-testid=hero-title]');
    await page.fill('[data-testid=text-editor]', 'Custom Hero Title');
    await page.press('[data-testid=text-editor]', 'Enter');
    await expect(page.locator('[data-testid=hero-title]')).toContainText('Custom Hero Title');

    // Test spacing adjustments
    await page.click('[data-testid=spacing-controls]');
    await page.fill('[data-testid=padding-top]', '64');
    await expect(page.locator('[data-testid=hero-section]')).toHaveCSS('padding-top', '64px');
  });

  test('component performance with 100+ components', async ({ page }) => {
    await page.click('[data-testid=component-library]');

    const startTime = Date.now();

    // Add 100 text components to test performance
    for (let i = 0; i < 100; i++) {
      await page.dragAndDrop('[data-testid=text-component]', '[data-testid=canvas]');
    }

    const endTime = Date.now();
    const totalTime = endTime - startTime;

    // Should handle 100 components within reasonable time
    expect(totalTime).toBeLessThan(30000); // 30 seconds max

    // Test interaction responsiveness with many components
    const interactionStart = Date.now();
    await page.click('[data-testid=text-component]:first-child');
    await page.waitForSelector('[data-testid=property-editor]');
    const interactionEnd = Date.now();

    // Component selection should remain fast
    expect(interactionEnd - interactionStart).toBeLessThan(500); // 500ms max
  });
});

import { test, expect, type Page } from '@playwright/test';
import { DeploymentValidator } from '../../src/lib/deployment/validator';
import { PerformanceMonitor } from '../../src/lib/performance/monitor';

/**
 * Deployment Validation Tests for MVP
 * 
 * Validates deployment success rate target: 95%
 * Tests:
 * - Static site generation reliability
 * - Deployment pipeline robustness
 * - Error handling and recovery
 * - Success rate monitoring
 */

test.describe('MVP Deployment Validation', () => {

  test.beforeEach(async ({ page }) => {
    // Clear deployment history for clean testing
    DeploymentValidator.clearHistory();
  });

  test('Static Site Generation Reliability - Target: 100% success', async ({ page }) => {
    console.log('🏗️ Testing static site generation reliability...');

    await page.goto('/builder', { waitUntil: 'networkidle' });
    await page.waitForSelector('.builder-canvas', { timeout: 15000 });

    let successfulGenerations = 0;
    const totalTests = 10;

    for (let i = 0; i < totalTests; i++) {
      console.log(`Generation test ${i + 1}/${totalTests}...`);

      try {
        // Add a component
        const heroComponent = page.locator('.hero-component, [data-component="hero"]').first();
        if (await heroComponent.isVisible()) {
          await heroComponent.click();
        }

        // Trigger site generation
        await page.click('[data-testid="publish-btn"], .publish-btn');
        await page.waitForSelector('.publish-modal, .deploy-section', { timeout: 10000 });

        // Start generation
        await page.click('.generate-site, .build-site, [data-testid="generate-site"]');

        // Wait for completion
        await page.waitForSelector('.generation-complete, .site-ready', { timeout: 60000 });

        // Verify success
        const successMessage = page.locator('.success-message, .generation-complete');
        if (await successMessage.isVisible()) {
          successfulGenerations++;
          console.log(`✅ Generation ${i + 1} successful`);
        } else {
          console.log(`❌ Generation ${i + 1} failed`);
        }

        // Reset for next test
        await page.click('.close-modal, [data-testid="close"]');
        await page.waitForTimeout(1000);

      } catch (error) {
        console.log(`❌ Generation ${i + 1} failed with error:`, error);
      }
    }

    const successRate = (successfulGenerations / totalTests) * 100;
    console.log(`📊 Site Generation Success Rate: ${successRate}%`);

    // Should have 100% success rate for static generation
    expect(successRate).toBeGreaterThanOrEqual(90);
    expect(successfulGenerations).toBeGreaterThan(0);

    if (successRate >= 95) {
      console.log('✅ Site generation reliability target achieved!');
    }
  });

  test('Deployment Pipeline Robustness - Target: 95% success', async ({ page }) => {
    console.log('🚀 Testing deployment pipeline robustness...');

    // Mock components for testing
    const mockComponents = [
      {
        id: 'hero-1',
        type: 'hero',
        props: { heading: 'Test Website', subheading: 'Built for testing' },
        position: { x: 0, y: 0 },
        size: { width: 1200, height: 600 }
      },
      {
        id: 'text-1',
        type: 'text',
        props: { content: 'This is a test website for deployment validation.' },
        position: { x: 0, y: 600 },
        size: { width: 1200, height: 200 }
      }
    ];

    // Test deployment pipeline with multiple iterations
    const validationResult = await DeploymentValidator.testDeploymentPipeline(
      20, // Test with 20 deployments
      mockComponents,
      null
    );

    console.log(`📊 Deployment Pipeline Test Results:`);
    console.log(`   Success Rate: ${validationResult.successRate.toFixed(1)}%`);
    console.log(`   Successful: ${validationResult.successfulDeployments}`);
    console.log(`   Failed: ${validationResult.failedDeployments}`);
    console.log(`   Average Time: ${validationResult.averageDeploymentTime.toFixed(0)}ms`);

    // Validate against target
    expect(validationResult.successRate).toBeGreaterThanOrEqual(95);
    expect(validationResult.successfulDeployments).toBeGreaterThan(0);
    expect(validationResult.averageDeploymentTime).toBeLessThan(30000); // Under 30 seconds

    // Check for critical issues
    const criticalIssues = validationResult.issues.filter(i => 
      i.severity === 'critical' || i.severity === 'high'
    );
    expect(criticalIssues.length).toBeLessThan(3);

    if (validationResult.successRate >= 95) {
      console.log('✅ Deployment pipeline meets 95% success rate target!');
    } else {
      console.log('❌ Deployment pipeline below 95% success rate target');
      console.log('⚠️ Issues found:', validationResult.issues.map(i => i.description));
    }
  });

  test('Site Validation Before Deployment', async ({ page }) => {
    console.log('🔍 Testing site validation before deployment...');

    const mockComponents = [
      {
        id: 'hero-test',
        type: 'hero',
        props: { 
          heading: 'Validation Test Site',
          subheading: 'Testing comprehensive site validation',
          buttonText: 'Get Started'
        },
        position: { x: 0, y: 0 },
        size: { width: 1200, height: 600 }
      },
      {
        id: 'features-test',
        type: 'features',
        props: {
          title: 'Our Features',
