import { test, expect } from '@playwright/test';

/**
 * Magic Moment End-to-End Test
 * Tests the core user journey: Template → AI Customization → Workflow Connection → Live Site
 */
test.describe('Magic Moment User Journey', () => {
  test('complete template to live site with workflow automation', async ({ page }) => {
    // Step 1: Navigate to template selection
    await page.goto('/templates');
    await expect(page.locator('[data-testid=template-grid]')).toBeVisible();

    // Step 2: Select a SaaS template
    await page.click('[data-testid=saas-template-1]');
    await expect(page.locator('[data-testid=canvas]')).toBeVisible();
    await expect(page.locator('[data-testid=hero-component]')).toBeVisible();

    // Step 3: AI Component Customization
    await page.click('[data-testid=hero-component]');
    await expect(page.locator('[data-testid=property-editor]')).toBeVisible();

    // Test AI customization
    await page.fill('[data-testid=ai-prompt]', 'Make this more modern and blue');
    await page.click('[data-testid=generate-variations]');

    // Wait for AI to generate variations
    await expect(page.locator('[data-testid=ai-variations]')).toBeVisible({ timeout: 10000 });
    await expect(page.locator('[data-testid=variation-1]')).toBeVisible();
    await expect(page.locator('[data-testid=variation-2]')).toBeVisible();
    await expect(page.locator('[data-testid=variation-3]')).toBeVisible();

    // Select a variation
    await page.click('[data-testid=variation-2]');
    await expect(page.locator('[data-testid=hero-component]')).toHaveAttribute('data-variation', '2');

    // Step 4: Add Contact Form Component
    await page.click('[data-testid=component-library]');
    await page.dragAndDrop('[data-testid=contact-form-component]', '[data-testid=canvas]');

    // Verify form component was added
    await expect(page.locator('[data-testid=contact-form]')).toBeVisible();

    // Step 5: Magic Connector - Connect to Workflow
    await page.click('[data-testid=contact-form]');
    await expect(page.locator('[data-testid=connect-workflow-button]')).toBeVisible();
    await page.click('[data-testid=connect-workflow-button]');

    // Step 6: AI Workflow Suggestions
    await expect(page.locator('[data-testid=workflow-suggestions]')).toBeVisible({ timeout: 8000 });
    await expect(page.locator('[data-testid=suggestion-1]')).toContainText('Email follow-up');
    await expect(page.locator('[data-testid=suggestion-2]')).toContainText('CRM tracking');
    await expect(page.locator('[data-testid=suggestion-3]')).toContainText('Slack notification');

    // Select first workflow suggestion
    await page.click('[data-testid=suggestion-1]');
    await page.click('[data-testid=activate-workflow]');

    // Verify workflow was connected
    await expect(page.locator('[data-testid=workflow-connected]')).toBeVisible();
    await expect(page.locator('[data-testid=contact-form]')).toHaveAttribute('data-workflow', 'connected');

    // Step 7: Site Publishing
    await page.click('[data-testid=publish-button]');
    await expect(page.locator('[data-testid=publishing-modal]')).toBeVisible();

    await page.fill('[data-testid=site-name]', 'test-magic-moment-site');
    await page.click('[data-testid=publish-confirm]');

    // Wait for publishing to complete
    await expect(page.locator('[data-testid=published-url]')).toBeVisible({ timeout: 30000 });
    const publishedUrl = await page.locator('[data-testid=published-url]').textContent();

    // Step 8: Test Live Site and Workflow
    await page.goto(publishedUrl!);

    // Verify site loads correctly
    await expect(page.locator('main')).toBeVisible();
    await expect(page.locator('form')).toBeVisible();

    // Test form submission triggers workflow
    await page.fill('[name=name]', 'Test User');
    await page.fill('[name=email]', 'test@example.com');
    await page.fill('[name=message]', 'Testing the Magic Moment workflow');
    await page.click('[type=submit]');

    // Verify form submission success
    await expect(page.locator('[data-testid=form-success]')).toBeVisible();

    // Step 9: Verify Workflow Execution
    await page.goto('/dashboard/workflows');

    // Check that workflow was executed
    await expect(page.locator('[data-testid=workflow-execution]')).toBeVisible();
    await expect(page.locator('[data-testid=execution-status]')).toContainText('completed');

    // Verify CRM contact was created
    await page.goto('/dashboard/crm/contacts');
    await expect(page.locator('[data-email="test@example.com"]')).toBeVisible();
  });

  test('AI customization performance benchmark', async ({ page }) => {
    await page.goto('/templates');
    await page.click('[data-testid=saas-template-1]');

    // Measure AI customization response time
    const startTime = Date.now();

    await page.click('[data-testid=hero-component]');
    await page.fill('[data-testid=ai-prompt]', 'Make this look premium and professional');
    await page.click('[data-testid=generate-variations]');
    await page.waitForSelector('[data-testid=ai-variations]');

    const endTime = Date.now();
    const responseTime = endTime - startTime;

    // AI should respond within 5 seconds
    expect(responseTime).toBeLessThan(5000);

    // Verify quality of variations
    const variations = await page.locator('[data-testid^=variation-]').count();
    expect(variations).toBe(3);
  });

  test('workflow connection success rate', async ({ page }) => {
    await page.goto('/templates');
    await page.click('[data-testid=business-template-1]');

    // Test multiple component types for workflow connectivity
    const components = ['contact-form', 'newsletter-signup', 'booking-form'];

    for (const component of components) {
      await page.dragAndDrop(`[data-testid=${component}-component]`, '[data-testid=canvas]');
      await page.click(`[data-testid=${component}]`);

      // Verify connect to workflow button appears
      await expect(page.locator('[data-testid=connect-workflow-button]')).toBeVisible();

      await page.click('[data-testid=connect-workflow-button]');

      // Verify AI suggests relevant workflows
      await expect(page.locator('[data-testid=workflow-suggestions]')).toBeVisible();
      const suggestions = await page.locator('[data-testid^=suggestion-]').count();
      expect(suggestions).toBeGreaterThan(0);

      // Connect first suggestion
      await page.click('[data-testid=suggestion-1]');
      await page.click('[data-testid=activate-workflow]');

      // Verify successful connection
      await expect(page.locator('[data-testid=workflow-connected]')).toBeVisible();
    }
  });
});

import { test, expect, type Page } from '@playwright/test';

/**
 * MCP Authentication End-to-End Tests
 * 
 * Tests the complete user authentication flow:
 * 1. User Registration
 * 2. User Login
 * 3. Token Validation
 * 4. Protected Route Access
 */

test.describe('MCP Authentication Flow', () => {
  let page: Page;
  const testUser = {
    email: `mcp.test.${Date.now()}@example.com`,
    password: 'McpTestPassword123!',
    name: 'MCP Test User'
  };

  test.beforeEach(async ({ page: testPage }) => {
    page = testPage;
    await page.goto('/');
  });

  test('User Registration and Login Flow', async () => {
    // ===== STEP 1: User Registration =====
    await test.step('User Registration', async () => {
      // Navigate to registration page
      await page.click('[data-testid="get-started-btn"], .get-started, a[href*="register"]');
      await page.waitForURL(/\/(register|signup|auth)/);

      // Fill registration form
      await page.fill('input[name="email"], input[type="email"]', testUser.email);
      await page.fill('input[name="password"], input[type="password"]', testUser.password);
      await page.fill('input[name="name"], input[name="firstName"]', testUser.name);

      // Submit registration
      await page.click('button[type="submit"], .register-btn, .signup-btn');

      // Verify successful registration
      await page.waitForURL(/\/(dashboard|login|builder)/, { timeout: 15000 });

      // Check for success message
      await expect(page.locator('text="Welcome", text="Account created", .success-message')).toBeVisible({ timeout: 10000 });

      console.log('✅ User registration successful');
    });

    // ===== STEP 2: User Login =====
    await test.step('User Login', async () => {
      // If not already on login page, navigate to it
      if (!page.url().includes('login')) {
        await page.click('a[href*="login"], .login-link');
        await page.waitForURL(/\/login/);
      }

      // Fill login form
      await page.fill('input[name="email"], input[type="email"]', testUser.email);
      await page.fill('input[name="password"], input[type="password"]', testUser.password);

      // Submit login
      await page.click('button[type="submit"], .login-btn');

      // Verify successful login
      await page.waitForURL(/\/(dashboard|builder|home)/, { timeout: 15000 });
      await expect(page.locator('text="Welcome", .user-menu, .dashboard')).toBeVisible({ timeout: 10000 });

      console.log('✅ User login successful');
    });

    // ===== STEP 3: Token Validation =====
    await test.step('Authentication Token Validation', async () => {
      // Check if auth token is stored (in localStorage or cookies)
      const localStorageItems = await page.evaluate(() => Object.keys(localStorage));
      const hasAuthToken = localStorageItems.some(key => key.includes('token') || key.includes('auth'));

      // Alternative: check for auth-related cookies
      const cookies = await page.context().cookies();
      const hasAuthCookies = cookies.some(cookie => 
        cookie.name.includes('token') || 
        cookie.name.includes('auth') || 
        cookie.name.includes('session')
      );

      // Expect either auth token in localStorage or auth cookies
      expect(hasAuthToken || hasAuthCookies).toBeTruthy();

      console.log('✅ Authentication token validation successful');
    });

    // ===== STEP 4: Protected Route Access =====
    await test.step('Protected Route Access', async () => {
      // Try to access a protected route (profile/dashboard)
      await page.goto('/dashboard');

      // Should stay on dashboard (not redirected to login)
      await expect(page).toHaveURL(/\/dashboard/);

      // Check for user-specific content
      await expect(page.locator(`text="${testUser.name}", .user-profile, .account-info`)).toBeVisible({ timeout: 10000 });

      console.log('✅ Protected route access successful');
    });

    console.log('✅ Complete MCP Authentication Flow Test Passed');
  });

  test('Login with Invalid Credentials', async () => {
    // ===== STEP 1: Attempt Login with Invalid Credentials =====
    await test.step('Invalid Login Attempt', async () => {
      // Navigate to login page
      await page.goto('/login');

      // Fill login form with invalid credentials
      await page.fill('input[name="email"], input[type="email"]', 'invalid@example.com');
      await page.fill('input[name="password"], input[type="password"]', 'wrongpassword');

      // Submit login
      await page.click('button[type="submit"], .login-btn');

      // Verify error message is displayed
      await expect(page.locator('text="Invalid credentials", text="Incorrect email or password", .error-message')).toBeVisible({ timeout: 10000 });

      // Should remain on login page
      await expect(page).toHaveURL(/\/login/);

      console.log('✅ Invalid login attempt handled correctly');
    });

    console.log('✅ Invalid Credentials Test Passed');
  });

  test('Registration with Existing Email', async () => {
    // ===== STEP 1: Attempt Registration with Existing Email =====
    await test.step('Duplicate Registration Attempt', async () => {
      // Navigate to registration page
      await page.goto('/register');

      // Fill registration form with existing email
      await page.fill('input[name="email"], input[type="email"]', testUser.email);
      await page.fill('input[name="password"], input[type="password"]', 'anotherpassword123');
      await page.fill('input[name="name"], input[name="firstName"]', 'Another User');

      // Submit registration
      await page.click('button[type="submit"], .register-btn, .signup-btn');

      // Verify error message is displayed
      await expect(page.locator('text="Email already registered", text="already exists", .error-message')).toBeVisible({ timeout: 10000 });

      console.log('✅ Duplicate registration attempt handled correctly');
    });

    console.log('✅ Duplicate Registration Test Passed');
  });
});

import { test, expect, type Page } from '@playwright/test';

/**
 * MVP User Journey E2E Tests
 * 
 * Tests the complete user flow from registration to deployed website:
 * 1. User Registration & Authentication
 * 2. Template Selection & Customization 
 * 3. Content Creation & Magic Connector
 * 4. Site Generation & Publishing
 * 5. Performance & SEO Validation
 */

test.describe('MVP Complete User Journey', () => {
  let page: Page;
  const testUser = {
    email: `test.user.${Date.now()}@example.com`,
    password: 'TestPassword123!',
    name: 'Test User'
  };

  test.beforeEach(async ({ page: testPage }) => {
    page = testPage;
    await page.goto('/');
  });

  test('Complete MVP User Journey: Registration → Template → Customization → Publishing', async () => {
    // ===== STEP 1: User Registration & Authentication =====
    await test.step('User Registration and Login', async () => {
      // Navigate to registration
      await page.click('[data-testid="get-started-btn"], .get-started, a[href*="register"]');
      await page.waitForURL(/\/(register|signup|auth)/);

      // Fill registration form
      await page.fill('input[name="email"], input[type="email"]', testUser.email);
      await page.fill('input[name="password"], input[type="password"]', testUser.password);
      await page.fill('input[name="name"], input[name="firstName"]', testUser.name);

      // Submit registration
      await page.click('button[type="submit"], .register-btn, .signup-btn');

      // Verify successful registration (either redirect to dashboard or login)
      await page.waitForURL(/\/(dashboard|login|builder)/);

      // If redirected to login, sign in
      if (page.url().includes('login')) {
        await page.fill('input[name="email"], input[type="email"]', testUser.email);
        await page.fill('input[name="password"], input[type="password"]', testUser.password);
        await page.click('button[type="submit"], .login-btn');
        await page.waitForURL(/\/dashboard/);
      }

      // Verify user is authenticated
      await expect(page.locator('text="Welcome"')).toBeVisible({ timeout: 10000 });
      console.log('✅ User registration and authentication successful');
    });

    // ===== STEP 2: Template Selection =====
    await test.step('Template Selection', async () => {
      // Navigate to template gallery
      await page.click('[data-testid="create-website-btn"], .create-site, a[href*="templates"]');
      await page.waitForURL(/\/(templates|gallery|builder)/);

      // Wait for templates to load
      await page.waitForSelector('.template-card, .template-item', { timeout: 15000 });

      // Select a template (business or marketing template)
      const templates = page.locator('.template-card, .template-item');
      await expect(templates.first()).toBeVisible();

      // Click "Use Template" button
      await page.click('.template-card:first-child .use-template, .template-item:first-child button');

      // Verify navigation to builder
      await page.waitForURL(/\/builder/, { timeout: 15000 });
      await page.waitForSelector('.visual-builder, .builder-canvas', { timeout: 15000 });

      console.log('✅ Template selection successful');
    });

    // ===== STEP 3: Visual Builder Customization =====
    await test.step('Visual Builder Customization', async () => {
      // Wait for builder to load
      await page.waitForSelector('.builder-canvas', { timeout: 15000 });

      // Test component library access
      await expect(page.locator('.component-library, .components-panel')).toBeVisible();

      // Test drag and drop functionality (if available)
      const heroComponent = page.locator('.hero-component, [data-component="hero"]').first();
      if (await heroComponent.isVisible()) {
        await heroComponent.click();
        console.log('✅ Hero component interaction successful');
      }

      // Test text editing
      const editableText = page.locator('text="Welcome", .hero-heading, .editable-text').first();
      if (await editableText.isVisible()) {
        await editableText.click();
        await page.keyboard.selectAll();
        await page.keyboard.type('My Amazing Business Website');
        console.log('✅ Text editing successful');
      }

      // Test Magic Connector (if available)
      const magicConnectorBtn = page.locator('[data-testid="magic-connector"], .magic-connector-btn');
      if (await magicConnectorBtn.isVisible()) {
        await magicConnectorBtn.click();
        await page.waitForSelector('.workflow-builder, .magic-connector-modal', { timeout: 5000 });

        // Test workflow creation
        const workflowNode = page.locator('.workflow-node, .node').first();
        if (await workflowNode.isVisible()) {
          await workflowNode.click();
          console.log('✅ Magic Connector workflow interaction successful');
        }

        // Close modal
        await page.click('.close-modal, [data-testid="close-modal"]');
      }

      console.log('✅ Visual builder customization completed');
    });

    // ===== STEP 4: Site Generation & Publishing =====
    await test.step('Site Generation and Publishing', async () => {
      // Navigate to publish section
      await page.click('[data-testid="publish-btn"], .publish-btn, .deploy-btn');

      // Wait for publish interface
      await page.waitForSelector('.publish-modal, .deploy-section', { timeout: 10000 });

      // Configure site settings
      const siteNameInput = page.locator('input[name="siteName"], input[placeholder*="site name"]');
      if (await siteNameInput.isVisible()) {
        await siteNameInput.fill('My Test Website');
      }

      // Test SEO settings
      const seoSection = page.locator('.seo-settings, [data-section="seo"]');
      if (await seoSection.isVisible()) {
        await seoSection.click();

        const descriptionField = page.locator('textarea[name="description"], .seo-description');
        if (await descriptionField.isVisible()) {
          await descriptionField.fill('A professional business website created with AI Marketing Web Builder');
        }
        console.log('✅ SEO settings configured');
      }

      // Generate static site
      await page.click('.generate-site, .build-site, [data-testid="generate-site"]');

      // Wait for generation to complete (up to 30 seconds)
      await page.waitForSelector('.generation-complete, .site-ready', { timeout: 30000 });

      // Verify generation success
      await expect(page.locator('text="Site generated successfully", .success-message')).toBeVisible();
      console.log('✅ Static site generation successful');
    });

    // ===== STEP 5: Performance & SEO Validation =====
    await test.step('Performance and SEO Validation', async () => {
      // Check SEO score
      const seoScore = page.locator('.seo-score, [data-metric="seo"]');
      if (await seoScore.isVisible()) {
        const scoreText = await seoScore.textContent();
        const score = parseInt(scoreText?.match(/\d+/)?.[0] || '0');
        expect(score).toBeGreaterThan(80); // Expect SEO score > 80
        console.log(`✅ SEO Score: ${score}/100`);
      }

      // Check responsive score
      const responsiveScore = page.locator('.responsive-score, [data-metric="responsive"]');
      if (await responsiveScore.isVisible()) {
        const scoreText = await responsiveScore.textContent();
        const score = parseInt(scoreText?.match(/\d+/)?.[0] || '0');
        expect(score).toBeGreaterThan(75); // Expect responsive score > 75
        console.log(`✅ Responsive Score: ${score}/100`);
      }

      // Check generation time
      const generationTime = page.locator('.generation-time, [data-metric="time"]');
      if (await generationTime.isVisible()) {
        const timeText = await generationTime.textContent();
        const timeMs = parseFloat(timeText?.match(/[\d.]+/)?.[0] || '0');
        expect(timeMs).toBeLessThan(30000); // Should generate in under 30 seconds
        console.log(`✅ Generation Time: ${timeMs}ms`);
      }

      console.log('✅ Performance and SEO validation completed');
    });

    // ===== STEP 6: Final Site Preview =====
    await test.step('Site Preview and Validation', async () => {
      // Open site preview
      const previewBtn = page.locator('.preview-site, .view-site, [data-testid="preview"]');
      if (await previewBtn.isVisible()) {
        await previewBtn.click();

        // Switch to preview tab/window
        const pages = await page.context().pages();
        const previewPage = pages[pages.length - 1];
        await previewPage.waitForLoadState('networkidle');

        // Validate generated site structure
        await expect(previewPage.locator('html')).toBeVisible();
        await expect(previewPage.locator('head title')).toBeVisible();
        await expect(previewPage.locator('meta[name="description"]')).toBeVisible();

        // Test responsive design
        await previewPage.setViewportSize({ width: 375, height: 667 }); // Mobile
        await previewPage.waitForTimeout(1000);
        await expect(previewPage.locator('body')).toBeVisible();

        await previewPage.setViewportSize({ width: 1024, height: 768 }); // Desktop
        await previewPage.waitForTimeout(1000);

        console.log('✅ Site preview validation successful');
        await previewPage.close();
      }
    });

    console.log('🎉 Complete MVP User Journey Test Passed!');
  });

  test('Mobile User Journey', async () => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });

    await test.step('Mobile Template Selection', async () => {
      // Test mobile navigation
      await page.click('[data-testid="mobile-menu"], .hamburger-menu');
      await page.click('[data-testid="templates-link"], a[href*="templates"]');

      // Verify mobile template gallery
      await page.waitForSelector('.template-card', { timeout: 10000 });
      await expect(page.locator('.template-card').first()).toBeVisible();

      console.log('✅ Mobile template selection working');
    });

    await test.step('Mobile Builder Experience', async () => {
      // Select template on mobile
      await page.click('.template-card:first-child .use-template');
      await page.waitForURL(/\/builder/);

      // Test mobile builder interface
      await page.waitForSelector('.builder-canvas', { timeout: 15000 });

      // Test touch interactions
      const heroElement = page.locator('.hero-component').first();
      if (await heroElement.isVisible()) {
        await heroElement.tap();
        console.log('✅ Mobile touch interaction successful');
      }

      console.log('✅ Mobile builder experience validated');
    });
  });

  test('Error Handling and Edge Cases', async () => {
    await test.step('Test Error Recovery', async () => {
      // Test network interruption simulation
      await page.route('**/api/**', route => {
        if (Math.random() < 0.1) { // 10% chance of failure
          route.abort();
        } else {
          route.continue();
        }
      });

      // Attempt normal flow and verify error handling
      await page.goto('/templates');
      await page.waitForTimeout(2000);

      // Check for error messages or retry mechanisms
      const errorMsg = page.locator('.error-message, .retry-btn');
      if (await errorMsg.isVisible()) {
        console.log('✅ Error handling mechanisms present');
      }
    });

    await test.step('Test Invalid Input Handling', async () => {
      await page.goto('/builder');

      // Test with invalid/empty inputs
      const textInput = page.locator('input[type="text"]').first();
      if (await textInput.isVisible()) {
        await textInput.fill(''); // Empty input
        await page.keyboard.press('Enter');

        // Verify validation messages
        const validation = page.locator('.error, .validation-message');
        if (await validation.isVisible()) {
          console.log('✅ Input validation working');
        }
      }
    });
  });
});

