      (global as any).WebSocket = jest.fn(() => ({
        ...mockWebSocket,
        readyState: WebSocket.CLOSED,
        addEventListener: jest.fn((event, callback) => {
          if (event === 'error') {
            setTimeout(() => callback(new Error('Connection failed')), 100);
          }
        })
      }));

      render(
        <WorkflowDebuggingPanel 
          workflow={mockWorkflow}
          isDebugging={true}
        />
      );

      await waitFor(() => {
        expect(screen.getByText('Real-time connection failed')).toBeInTheDocument();
        expect(screen.getByText('Retry Connection')).toBeInTheDocument();
      });
    });

    it('handles incomplete template data', async () => {
      const incompleteTemplate = {
        template_id: 'incomplete',
        name: 'Incomplete Template',
        relevanceScore: 75
        // Missing other required fields
      };

      mockApiClient.get.mockResolvedValueOnce({ data: [incompleteTemplate] });

      render(<SmartTemplateSelector />);

      await waitFor(() => {
        expect(screen.getByText('Incomplete Template')).toBeInTheDocument();
        expect(screen.getByText('75%')).toBeInTheDocument();
        expect(screen.getByText('Data incomplete')).toBeInTheDocument();
      });
    });

    it('provides fallback when AI services are unavailable', async () => {
      mockApiClient.post.mockRejectedValueOnce({ 
        response: { status: 503, data: { error: 'AI service unavailable' } }
      });

      render(<SmartTemplateRecommendations />);

      fireEvent.click(screen.getByText('Analyze My Business'));

      await waitFor(() => {
        expect(screen.getByText('AI analysis unavailable')).toBeInTheDocument();
        expect(screen.getByText('Browse all templates')).toBeInTheDocument();
      });

      // Should fallback to manual template browsing
      fireEvent.click(screen.getByText('Browse all templates'));

      expect(screen.getByText('Template Categories')).toBeInTheDocument();
    });
  });

  // ========================================================================
  // PERFORMANCE TESTS
  // ========================================================================

  describe('Performance Tests', () => {

    it('handles large workflow executions efficiently', async () => {
      const largeExecution = {
        ...mockExecutionData,
        total_steps: 50,
        steps: Array.from({ length: 50 }, (_, i) => ({
          id: `step-${i}`,
          node_id: `node-${i}`,
          status: i < 30 ? 'success' : i < 45 ? 'running' : 'pending',
          execution_time_ms: Math.random() * 5000
        }))
      };

      mockApiClient.get.mockResolvedValueOnce({ data: largeExecution });

      const startTime = performance.now();

      render(
        <WorkflowDebuggingPanel 
          workflow={mockWorkflow}
          isDebugging={true}
        />
      );

      await waitFor(() => {
        expect(screen.getByText('50 steps')).toBeInTheDocument();
      });

      const renderTime = performance.now() - startTime;

      // Should render within reasonable time (less than 1 second)
      expect(renderTime).toBeLessThan(1000);
    });

    it('optimizes template list rendering with virtual scrolling', async () => {
      const manyTemplates = Array.from({ length: 100 }, (_, i) => ({
        ...mockTemplateRecommendation,
        template_id: `template-${i}`,
        name: `Template ${i}`,
        relevanceScore: 100 - i
      }));

      mockApiClient.get.mockResolvedValueOnce({ data: manyTemplates });

      render(<SmartTemplateSelector />);

      await waitFor(() => {
        // Should use virtual scrolling for performance
        expect(screen.getByTestId('virtual-scroll-container')).toBeInTheDocument();

        // Should only render visible items
        const renderedCards = screen.getAllByTestId(/template-card-/);
        expect(renderedCards.length).toBeLessThanOrEqual(20); // Only visible items
      });
    });
  });
});

/**
 * Integration Test: Template Loading and Component Placement Workflow
 * Tests the complete user journey from template selection to component manipulation
 */

import { describe, test, expect, beforeEach } from '@jest/globals';
import { renderHook, act } from '@testing-library/react';
import { useBuilderStore } from '@/store/builderStore';
import { sampleTemplates, getTemplateById } from '@/data/templates';
import { ComponentData } from '@/types/builder';

describe('Template Loading and Component Placement Integration', () => {
  beforeEach(() => {
    // Reset store state before each test
    const { clearCanvas } = useBuilderStore.getState();
    clearCanvas();
  });

  describe('Template Loading Workflow', () => {
    test('should load premium SaaS template with all components', () => {
      const { result } = renderHook(() => useBuilderStore());
      const template = getTemplateById('premium-saas-landing-1');

      expect(template).toBeDefined();
      expect(template?.components).toHaveLength(33); // Premium template has 33 components
      expect(template?.name).toBe('Premium SaaS Landing Page');
    });

    test('should maintain component hierarchy when loading template', () => {
      const template = getTemplateById('premium-saas-landing-1');
      if (!template) throw new Error('Template not found');

      // Test parent-child relationships
      const navElement = template.components.find(el => el.id === 'saas-nav');
      const heroElement = template.components.find(el => el.id === 'saas-hero');
      const heroContent = template.components.find(el => el.id === 'hero-content');

      expect(navElement?.parentId).toBeNull(); // Root element
      expect(heroElement?.parentId).toBeNull(); // Root element  
      expect(heroContent?.parentId).toBe('saas-hero'); // Child of hero
    });

    test('should convert template components to ComponentData format', () => {
      const { result } = renderHook(() => useBuilderStore());
      const template = getTemplateById('premium-saas-landing-1');

      if (!template) throw new Error('Template not found');

      // Mock converting template component to ComponentData
      const templateComponent = template.components[0];
      const componentData: ComponentData = {
        id: templateComponent.id,
        type: templateComponent.type,
        name: templateComponent.name,
        props: {
          ...templateComponent.props,
          content: templateComponent.content,
          styles: templateComponent.styles
        },
        position: { x: 0, y: 0 }, // Default position
        size: { width: 100, height: 100 }, // Default size
        children: []
      };

      expect(componentData.id).toBe(templateComponent.id);
      expect(componentData.type).toBe(templateComponent.type);
      expect(componentData.name).toBe(templateComponent.name);
    });

    test('should actually load template into store', () => {
      const { result } = renderHook(() => useBuilderStore());
      const template = getTemplateById('premium-saas-landing-1');

      if (!template) throw new Error('Template not found');

      act(() => {
        result.current.loadTemplate(template);
      });

      // Check that template was loaded
      expect(result.current.currentTemplate).toBe(template);
      expect(result.current.components.length).toBeGreaterThan(0);

      // Check that components have proper structure
      const firstComponent = result.current.components[0];
      expect(firstComponent.id).toBeDefined();
      expect(firstComponent.type).toBeDefined();
      expect(firstComponent.position).toBeDefined();
      expect(firstComponent.size).toBeDefined();
    });
  });

  describe('Component Placement Integration', () => {
    test('should add component to canvas with correct position', () => {
      const { result } = renderHook(() => useBuilderStore());

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'button',
        name: 'Test Button',
        props: { content: 'Click me' },
        position: { x: 100, y: 200 },
        size: { width: 120, height: 40 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      const addedComponent = result.current.getComponentById('test-component-1');
      expect(addedComponent).toBeDefined();
      expect(addedComponent?.position).toEqual({ x: 100, y: 200 });
      expect(addedComponent?.size).toEqual({ width: 120, height: 40 });
    });

    test('should maintain component selection state', () => {
      const { result } = renderHook(() => useBuilderStore());

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'text',
        name: 'Test Text',
        props: {},
        position: { x: 0, y: 0 },
        size: { width: 100, height: 50 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      // Component should be auto-selected when added
      expect(result.current.selectedComponentId).toBe('test-component-1');

      act(() => {
        result.current.selectComponent(null);
      });

      expect(result.current.selectedComponentId).toBeNull();
    });

    test('should update component properties correctly', () => {
      const { result } = renderHook(() => useBuilderStore());

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'button',
        name: 'Test Button',
        props: { content: 'Original Text' },
        position: { x: 0, y: 0 },
        size: { width: 100, height: 40 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      act(() => {
        result.current.updateComponent('test-component-1', {
          props: { content: 'Updated Text', color: 'blue' }
        });
      });

      const updatedComponent = result.current.getComponentById('test-component-1');
      expect(updatedComponent?.props.content).toBe('Updated Text');
      expect(updatedComponent?.props.color).toBe('blue');
    });
  });

  describe('Drag and Drop Integration', () => {
    test('should handle component position updates with grid snapping', () => {
      const { result } = renderHook(() => useBuilderStore());

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'card',
        name: 'Test Card',
        props: {},
        position: { x: 0, y: 0 },
        size: { width: 200, height: 150 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      // Test position update with grid snapping enabled (default)
      act(() => {
        result.current.updateComponentPosition('test-component-1', { x: 33, y: 47 });
      });

      const component = result.current.getComponentById('test-component-1');
      // Should snap to 20px grid
      expect(component?.position).toEqual({ x: 40, y: 40 });
    });

    test('should handle component resizing with constraints', () => {
      const { result } = renderHook(() => useBuilderStore());

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'container',
        name: 'Test Container',
        props: {},
        position: { x: 0, y: 0 },
        size: { width: 200, height: 150 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      act(() => {
        result.current.updateComponentSize('test-component-1', { width: 33, height: 27 });
      });

      const component = result.current.getComponentById('test-component-1');
      // Should enforce minimum size and snap to grid
      expect(component?.size.width).toBeGreaterThanOrEqual(40);
      expect(component?.size.height).toBeGreaterThanOrEqual(40);
    });
  });

  describe('Canvas State Management', () => {
    test('should manage canvas zoom and grid settings', () => {
      const { result } = renderHook(() => useBuilderStore());

      // Test zoom functionality
      act(() => {
        result.current.setZoom(150);
      });
      expect(result.current.zoom).toBe(150);

      // Test zoom limits
      act(() => {
        result.current.setZoom(500); // Above max
      });
      expect(result.current.zoom).toBe(300); // Clamped to max

      act(() => {
        result.current.setZoom(10); // Below min
      });
      expect(result.current.zoom).toBe(25); // Clamped to min

      // Test grid toggle
      const initialGridState = result.current.gridEnabled;
      act(() => {
        result.current.toggleGrid();
      });
      expect(result.current.gridEnabled).toBe(!initialGridState);
    });

    test('should handle canvas size changes', () => {
      const { result } = renderHook(() => useBuilderStore());

      act(() => {
        result.current.setCanvasSize({ width: 1920, height: 1080 });
      });

      expect(result.current.canvasSize).toEqual({ width: 1920, height: 1080 });
    });
  });

  describe('Auto-save Integration', () => {
    test('should trigger auto-save when components change', () => {
      const { result } = renderHook(() => useBuilderStore());

      // Mock localStorage
      const mockSetItem = jest.spyOn(Storage.prototype, 'setItem');

      const testComponent: ComponentData = {
        id: 'test-component-1',
        type: 'text',
        name: 'Test Text',
        props: {},
        position: { x: 0, y: 0 },
        size: { width: 100, height: 50 }
      };

      act(() => {
        result.current.addComponent(testComponent);
      });

      // Auto-save should be triggered
      expect(mockSetItem).toHaveBeenCalledWith(
        'builder-auto-save',
        expect.stringContaining('test-component-1')
      );

      mockSetItem.mockRestore();
    });
  });

  describe('Component Hierarchy Management', () => {
    test('should handle nested component relationships', () => {
      const { result } = renderHook(() => useBuilderStore());

      const parentComponent: ComponentData = {
        id: 'parent-container',
        type: 'container',
        name: 'Parent Container',
        props: {},
        position: { x: 0, y: 0 },
        size: { width: 400, height: 300 }
      };

      const childComponent: ComponentData = {
        id: 'child-text',
        type: 'text',
        name: 'Child Text',
        props: {},
        position: { x: 20, y: 20 },
        size: { width: 200, height: 50 },
        children: []
      };

      act(() => {
        result.current.addComponent(parentComponent);
        result.current.addComponent(childComponent);
      });

      // Verify both components exist
      expect(result.current.components).toHaveLength(2);
      expect(result.current.getComponentById('parent-container')).toBeDefined();
      expect(result.current.getComponentById('child-text')).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    test('should handle invalid component operations gracefully', () => {
      const { result } = renderHook(() => useBuilderStore());

      // Test operations on non-existent component
      expect(() => {
        act(() => {
          result.current.updateComponent('non-existent-id', { name: 'Updated' });
        });
      }).not.toThrow();

      expect(() => {
        act(() => {
          result.current.removeComponent('non-existent-id');
        });
      }).not.toThrow();

      // Component count should remain 0
      expect(result.current.components).toHaveLength(0);
    });
  });
});

describe('Template Categories and Filtering', () => {
  test('should filter templates by category correctly', () => {
    const landingTemplates = sampleTemplates.filter(t => t.category === 'landing');
    const blogTemplates = sampleTemplates.filter(t => t.category === 'blog');

    expect(landingTemplates.length).toBeGreaterThan(0);
    expect(blogTemplates.length).toBeGreaterThan(0);

    landingTemplates.forEach(template => {
      expect(template.category).toBe('landing');
    });
  });

  test('should provide template metadata correctly', () => {
    sampleTemplates.forEach(template => {
      expect(template.id).toBeDefined();
      expect(template.name).toBeDefined();
      expect(template.category).toBeDefined();
      expect(template.description).toBeDefined();
      expect(template.components).toBeDefined();
      expect(Array.isArray(template.components)).toBe(true);
    });
  });
});

import { test, expect, Page } from '@playwright/test';

/**
 * Theme Styling Validation Test Suite
 * 
 * Comprehensive testing to verify theme implementation and styling functionality
 * Tests based on the design document requirements and current theme system
 */

test.describe('Theme Styling Validation', () => {

  test.beforeEach(async ({ page }) => {
    // Navigate to the main page
    await page.goto('/');
    // Wait for page to fully load
    await page.waitForLoadState('networkidle');
  });

  test('should load page with proper theme backgrounds', async ({ page }) => {
    // Test 1: Check if the main page loads with correct gradient background
    const body = page.locator('body');

    // Check if the page loaded successfully
    await expect(page).toHaveTitle(/AI Marketing Web Builder|Home/);

    // Take a screenshot for visual verification
    await page.screenshot({ 
      path: 'test-results/theme-background-check.png',
      fullPage: true 
    });

    console.log('✓ Page loaded successfully with theme');
  });

  test('should validate landing page gradient backgrounds', async ({ page }) => {
    // Test 2: Check specific gradient background implementation
    const mainContainer = page.locator('main, [class*="gradient"], [class*="bg-gradient"]').first();

    // Check if gradient classes are applied
    const hasGradientBg = await page.evaluate(() => {
      const elements = document.querySelectorAll('[class*="bg-gradient"]');
      return elements.length > 0;
    });

    console.log(`Gradient background elements found: ${hasGradientBg}`);

    // Check for specific theme classes
    const themeElements = await page.evaluate(() => {
      const bgGradient = document.querySelectorAll('[class*="from-black"]');
      const textWhite = document.querySelectorAll('[class*="text-white"]');
      const yellowAccent = document.querySelectorAll('[class*="text-yellow-400"]');

      return {
        gradientElements: bgGradient.length,
        whiteTextElements: textWhite.length,
        yellowAccentElements: yellowAccent.length
      };
    });

    console.log('Theme elements found:', themeElements);

    // Take screenshot of the landing section
    await page.screenshot({ 
      path: 'test-results/landing-gradient-validation.png',
      fullPage: true 
    });
  });

  test('should validate button styling and variants', async ({ page }) => {
    // Test 3: Check button implementations and styling
    const buttons = page.locator('button, [role="button"], a[class*="bg-gradient"]');
    const buttonCount = await buttons.count();

    console.log(`Found ${buttonCount} interactive elements`);

    if (buttonCount > 0) {
      // Check first button styling
      const firstButton = buttons.first();
      await firstButton.scrollIntoViewIfNeeded();

      // Check for luxury button classes
      const buttonClasses = await firstButton.getAttribute('class');
      console.log('First button classes:', buttonClasses);

      // Test button hover state if possible
      await firstButton.hover();
      await page.waitForTimeout(500);

      // Take screenshot of button states
      await page.screenshot({ 
        path: 'test-results/button-styling-validation.png',
        clip: { x: 0, y: 0, width: 1200, height: 800 }
      });
    }
  });

  test('should validate text hierarchy and typography', async ({ page }) => {
    // Test 4: Check text styling and hierarchy
    const textElements = await page.evaluate(() => {
      const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
      const paragraphs = document.querySelectorAll('p');
      const textWhite = document.querySelectorAll('[class*="text-white"]');
      const textGray = document.querySelectorAll('[class*="text-gray"]');
      const textYellow = document.querySelectorAll('[class*="text-yellow"]');

      return {
        headings: headings.length,
        paragraphs: paragraphs.length,
        whiteText: textWhite.length,
        grayText: textGray.length,
        yellowText: textYellow.length,
        headingClasses: Array.from(headings).map(h => h.className).slice(0, 3),
        paragraphClasses: Array.from(paragraphs).map(p => p.className).slice(0, 3)
      };
    });

    console.log('Typography elements:', textElements);

    // Validate we have proper text styling
    expect(textElements.whiteText + textElements.grayText + textElements.yellowText).toBeGreaterThan(0);
  });

  test('should validate component styling consistency', async ({ page }) => {
    // Test 5: Check for consistent component styling
    const componentAnalysis = await page.evaluate(() => {
      // Check for theme utility usage
      const bgGray900 = document.querySelectorAll('[class*="bg-gray-900"]');
      const bgGray800 = document.querySelectorAll('[class*="bg-gray-800"]');
      const backdropBlur = document.querySelectorAll('[class*="backdrop-blur"]');
      const borderGray = document.querySelectorAll('[class*="border-gray"]');

      // Check for consistent spacing
      const padding = document.querySelectorAll('[class*="p-"], [class*="px-"], [class*="py-"]');
      const margin = document.querySelectorAll('[class*="m-"], [class*="mx-"], [class*="my-"]');

      return {
        backgroundElements: {
          gray900: bgGray900.length,
          gray800: bgGray800.length,
          backdropBlur: backdropBlur.length
        },
        spacingElements: {
          padding: padding.length,
          margin: margin.length
        },
        borderElements: borderGray.length
      };
    });

    console.log('Component styling analysis:', componentAnalysis);

    // Take full page screenshot for visual analysis
    await page.screenshot({ 
      path: 'test-results/component-styling-analysis.png',
      fullPage: true 
    });
  });

  test('should validate responsive design and mobile compatibility', async ({ page }) => {
    // Test 6: Check responsive behavior
    const viewports = [
      { width: 375, height: 667, name: 'mobile' },
      { width: 768, height: 1024, name: 'tablet' },
      { width: 1440, height: 900, name: 'desktop' }
    ];

    for (const viewport of viewports) {
      await page.setViewportSize({ width: viewport.width, height: viewport.height });
      await page.waitForTimeout(500);

      // Check if content is properly displayed
      const isContentVisible = await page.evaluate(() => {
        const main = document.querySelector('main');
        return main && window.getComputedStyle(main).display !== 'none';
      });

      console.log(`${viewport.name} viewport (${viewport.width}x${viewport.height}): Content visible = ${isContentVisible}`);

      // Take screenshot for each viewport
      await page.screenshot({ 
        path: `test-results/responsive-${viewport.name}-${viewport.width}x${viewport.height}.png`,
        fullPage: true 
      });
    }
  });

  test('should check for CSS compilation and loading', async ({ page }) => {
    // Test 7: Verify CSS is properly loaded and compiled
    const cssAnalysis = await page.evaluate(() => {
      // Check if Tailwind CSS is working by looking for compiled styles
      const testElement = document.createElement('div');
      testElement.className = 'bg-gray-900 text-white p-4';
      document.body.appendChild(testElement);

      const styles = window.getComputedStyle(testElement);
      const bgColor = styles.backgroundColor;
      const textColor = styles.color;
      const padding = styles.padding;

      document.body.removeChild(testElement);

      return {
        backgroundColor: bgColor,
        textColor: textColor,
        padding: padding,
        tailwindWorking: bgColor !== 'rgba(0, 0, 0, 0)' && bgColor !== 'transparent'
      };
    });

    console.log('CSS compilation analysis:', cssAnalysis);

    // Verify Tailwind CSS is working
    expect(cssAnalysis.tailwindWorking).toBeTruthy();
  });

  test('should analyze theme file accessibility and performance', async ({ page }) => {
    // Test 8: Performance and accessibility analysis

    // Check for accessibility attributes
    const a11yElements = await page.evaluate(() => {
      const focusableElements = document.querySelectorAll('[tabindex], button, a, input, select, textarea');
      const ariaLabels = document.querySelectorAll('[aria-label], [aria-labelledby]');
      const altTexts = document.querySelectorAll('img[alt]');

      return {
        focusableElements: focusableElements.length,
        ariaLabels: ariaLabels.length,
        altTexts: altTexts.length
      };
    });

    console.log('Accessibility elements:', a11yElements);

    // Performance check - measure page load time
    const navigationStart = await page.evaluate(() => performance.timing.navigationStart);
    const loadComplete = await page.evaluate(() => performance.timing.loadEventEnd);
    const loadTime = loadComplete - navigationStart;

    console.log(`Page load time: ${loadTime}ms`);

    // Take final comprehensive screenshot
    await page.screenshot({ 
      path: 'test-results/final-theme-validation.png',
      fullPage: true 
    });
  });

});

test.describe('Theme Error Detection', () => {

  test('should detect common theme issues', async ({ page }) => {
    await page.goto('/');
    await page.waitForLoadState('networkidle');

    // Check for common styling issues
    const issues = await page.evaluate(() => {
      const problems = [];

      // Check for missing background colors
      const elementsWithoutBg = document.querySelectorAll('div:not([class*="bg-"])');
      if (elementsWithoutBg.length > 10) {
        problems.push(`Many elements (${elementsWithoutBg.length}) without background classes`);
      }

      // Check for hardcoded colors
      const elementsWithStyle = document.querySelectorAll('[style*="color"], [style*="background"]');
      if (elementsWithStyle.length > 0) {
        problems.push(`Found ${elementsWithStyle.length} elements with hardcoded styles`);
      }

      // Check for missing text colors
      const textElements = document.querySelectorAll('p, span, div');
      const elementsWithoutTextColor = Array.from(textElements).filter(el => {
        const classes = el.className;
        return !classes.includes('text-') && el.innerText.trim().length > 0;
      });

      if (elementsWithoutTextColor.length > 5) {
        problems.push(`Many text elements (${elementsWithoutTextColor.length}) without text color classes`);
      }

      return problems;
    });

    console.log('Theme issues detected:', issues);

    if (issues.length > 0) {
      console.warn('⚠️ Theme styling issues found:');
      issues.forEach(issue => console.warn(`  - ${issue}`));
    } else {
      console.log('✓ No major theme issues detected');
    }
  });

});

@echo off
REM PNPM Migration Validation Script
REM Validates that the migration to pnpm was successful

echo ==============================================
echo   PNPM Migration Validation
echo ==============================================
echo.

set "errors=0"

echo [1/7] Checking pnpm installation...
pnpm --version >nul 2>&1
if %errorlevel% neq 0 (
    echo ✗ PNPM is not installed or not accessible
    set /a errors+=1
) else (
    for /f %%i in ('pnpm --version') do echo ✓ PNPM %%i is installed
)

echo.
echo [2/7] Checking project configuration...
if exist .pnpmrc (
    echo ✓ .pnpmrc configuration file exists
) else (
    echo ✗ .pnpmrc configuration file missing
    set /a errors+=1
)

if exist pnpm-lock.yaml (
    echo ✓ pnpm-lock.yaml lockfile exists
) else (
    echo ✗ pnpm-lock.yaml lockfile missing
    set /a errors+=1
)

if exist package-lock.json (
    echo ⚠ package-lock.json still exists (should be removed)
    set /a errors+=1
) else (
    echo ✓ npm lockfile properly removed
)

echo.
echo [3/7] Checking node_modules structure...
if exist node_modules\.pnpm (
    echo ✓ PNPM node_modules structure detected
) else (
    echo ✗ PNPM node_modules structure not found
    set /a errors+=1
)

echo.
echo [4/7] Verifying core binaries...
pnpm exec next --version >nul 2>&1
if %errorlevel% neq 0 (
    echo ✗ Next.js binary not accessible via pnpm
    set /a errors+=1
) else (
    for /f %%i in ('pnpm exec next --version') do echo ✓ Next.js %%i accessible
)

pnpm exec tsc --version >nul 2>&1
if %errorlevel% neq 0 (
    echo ✗ TypeScript binary not accessible via pnpm
    set /a errors+=1
) else (
    for /f %%i in ('pnpm exec tsc --version') do echo ✓ TypeScript %%i accessible
)

echo.
echo [5/7] Checking package.json pnpm configuration...
findstr /c:"packageManager.*pnpm" package.json >nul 2>&1
if %errorlevel% neq 0 (
    echo ⚠ package.json missing packageManager field
) else (
    echo ✓ package.json configured for pnpm
)

echo.
echo [6/7] Testing pnpm scripts...
echo Testing: pnpm run type-check...
pnpm run type-check >nul 2>&1
if %errorlevel% neq 0 (
    echo ⚠ TypeScript check has errors (expected due to existing type issues)
) else (
    echo ✓ TypeScript check passed
)

echo.
echo [7/7] Testing development server start...
echo Starting dev server for 5 seconds...
timeout /t 1 /nobreak >nul
start /b pnpm run dev >dev-test.log 2>&1
timeout /t 5 /nobreak >nul
taskkill /f /im node.exe >nul 2>&1

findstr /c:"Ready in" dev-test.log >nul 2>&1
if %errorlevel% neq 0 (
    echo ✗ Development server failed to start
    set /a errors+=1
) else (
    echo ✓ Development server started successfully
)

if exist dev-test.log del dev-test.log

echo.
echo ==============================================
if %errors% equ 0 (
    echo ✓ PNPM MIGRATION SUCCESSFUL!
    echo All checks passed. You can now use:
    echo   pnpm run dev    ^(start development^)
    echo   pnpm run build  ^(production build^)
    echo   pnpm install    ^(add dependencies^)
    echo   pnpm store prune ^(clean store^)
) else (
    echo ✗ PNPM MIGRATION ISSUES DETECTED
    echo Found %errors% issues. Please run emergency-pnpm-recovery.bat
)
echo ==============================================

pause
